    skills_extra_roots: std.ArrayList([]const u8) = .empty,
    skills_list_cache: std.ArrayList(SkillsListCacheEntry) = .empty,
    subscribed_thread_ids: std.ArrayList([]const u8) = .empty,
    opt_out_notification_methods: std.ArrayList([]const u8) = .empty,
    pre_response_notifications: std.ArrayList([]const u8) = .empty,
    pending_notifications: std.ArrayList([]const u8) = .empty,
    pending_server_requests: std.ArrayList(PendingServerRequest) = .empty,
    session_command_approvals: std.ArrayList(SessionCommandApproval) = .empty,
    session_file_approvals: std.ArrayList(SessionFileApproval) = .empty,
    server_request_transport: ?ServerRequestTransport = null,
    connection_output: ?*AppServerConnectionOutputState = null,
    active_command_execs: std.ArrayList(*ActiveCommandExecSession) = .empty,
    active_account_login: ?*ActiveAccountLoginRegistry = null,

    fn deinit(self: *AppServerState, allocator: std.mem.Allocator) void {
        clearAppServerConnectionState(allocator, self);
        self.cli_feature_overrides.deinit(allocator);
        self.runtime_feature_enablement.deinit(allocator);
        for (self.loaded_threads.items) |*thread| thread.deinit(allocator);
        self.loaded_threads.deinit(allocator);
        for (self.environments.items) |*environment| environment.deinit(allocator);
        self.environments.deinit(allocator);
        for (self.pending_thread_unloads.items) |*unload| unload.deinit(allocator);
        self.pending_thread_unloads.deinit(allocator);
        self.fs_watches.deinit(allocator);
        self.fuzzy_search_sessions.deinit(allocator);
        self.skill_watch_roots.deinit(allocator);
        self.skills_extra_roots.deinit(allocator);
        self.skills_list_cache.deinit(allocator);
        self.subscribed_thread_ids.deinit(allocator);
        self.opt_out_notification_methods.deinit(allocator);
        self.pre_response_notifications.deinit(allocator);
        self.pending_notifications.deinit(allocator);
        for (self.pending_server_requests.items) |*request| request.deinit(allocator);
        self.pending_server_requests.deinit(allocator);
        for (self.session_command_approvals.items) |*approval| approval.deinit(allocator);
        self.session_command_approvals.deinit(allocator);
        for (self.session_file_approvals.items) |*approval| approval.deinit(allocator);
        self.session_file_approvals.deinit(allocator);
        self.active_command_execs.deinit(allocator);
        releaseActiveAccountLoginRegistry(allocator, self, true);
    }
};

fn initAppServerState(
    allocator: std.mem.Allocator,
    invocation_options: InvocationOptions,
    deferred_command_exec_stdio: bool,
) !AppServerState {
    var state = AppServerState{
        .deferred_command_exec_stdio = deferred_command_exec_stdio,
        .bypass_hook_trust = invocation_options.bypass_hook_trust,
        .remote_control_enabled = invocation_options.remote_control_enabled,
        .session_source = invocation_options.session_source,
        .active_profile = invocation_options.profile,
        .runtime_overrides = invocation_options.runtime_overrides,
        .thread_unloading_delay_ms = appServerThreadUnloadingDelayMs(allocator),
        .cli_feature_overrides = try invocation_options.feature_overrides.clone(allocator),
    };
    errdefer state.deinit(allocator);
    return state;
}

fn loadAppServerConfig(allocator: std.mem.Allocator, state: *const AppServerState) !config.Config {
    return loadAppServerConfigWithOptions(allocator, state, .{});
}

fn loadAppServerConfigWithOptions(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    options: config.LoadOptions,
) !config.Config {
    var effective_options = options;
    if (effective_options.profile == null) effective_options.profile = state.active_profile;
    var cfg = try config.loadWithOptions(allocator, effective_options);
    errdefer cfg.deinit(allocator);
    try config.applyRuntimeOverrides(&cfg, allocator, state.runtime_overrides);
    return cfg;
}

fn appServerThreadUnloadingDelayMs(allocator: std.mem.Allocator) i64 {
    const override = env.getOwned(allocator, TEST_THREAD_UNLOAD_DELAY_ENV_VAR) catch return THREAD_UNLOADING_DELAY_MS;
    const value = override orelse return THREAD_UNLOADING_DELAY_MS;
    defer allocator.free(value);
    const trimmed = std.mem.trim(u8, value, " \t\r\n");
    const parsed = std.fmt.parseInt(i64, trimmed, 10) catch return THREAD_UNLOADING_DELAY_MS;
    return if (parsed >= 0) parsed else THREAD_UNLOADING_DELAY_MS;
}

fn clearAppServerConnectionState(allocator: std.mem.Allocator, state: *AppServerState) void {
    terminateActiveCommandExecSessions(state);
    cleanupFinishedCommandExecSessions(allocator, state, true);

    for (state.fs_watches.items) |*watch| watch.deinit(allocator);
    state.fs_watches.clearRetainingCapacity();
    for (state.fuzzy_search_sessions.items) |*session| session.deinit(allocator);
    state.fuzzy_search_sessions.clearRetainingCapacity();
    for (state.skill_watch_roots.items) |root| allocator.free(root);
    state.skill_watch_roots.clearRetainingCapacity();
    clearSkillsExtraRoots(allocator, state);
    clearSkillsListCache(allocator, state);
    for (state.subscribed_thread_ids.items) |thread_id| allocator.free(thread_id);
    state.subscribed_thread_ids.clearRetainingCapacity();
    clearOptOutNotificationMethods(allocator, state);
    for (state.pre_response_notifications.items) |payload| allocator.free(payload);
    state.pre_response_notifications.clearRetainingCapacity();
    for (state.pending_notifications.items) |payload| allocator.free(payload);
    state.pending_notifications.clearRetainingCapacity();
    for (state.pending_server_requests.items) |*request| request.deinit(allocator);
    state.pending_server_requests.clearRetainingCapacity();
}

fn clearAppServerConnectionStateAfterDisconnect(allocator: std.mem.Allocator, state: *AppServerState) void {
    scheduleThreadUnloadsForConnectionClose(allocator, state) catch {};
    clearAppServerConnectionState(allocator, state);
}

const ActiveAccountLogin = struct {
    login_id: []const u8,
    kind: union(enum) {
        browser: u16,
        device_code: *AccountLoginCancelToken,
    },

    fn deinit(self: *ActiveAccountLogin, allocator: std.mem.Allocator) void {
        switch (self.kind) {
            .browser => {},
            .device_code => |token| token.release(allocator),
        }
        allocator.free(self.login_id);
    }
};

const ActiveAccountLoginRegistry = struct {
    mutex: std.Io.Mutex = .init,
    active: ?ActiveAccountLogin = null,
    ref_count: std.atomic.Value(usize) = .init(1),

    fn create(allocator: std.mem.Allocator) !*ActiveAccountLoginRegistry {
        const registry = try allocator.create(ActiveAccountLoginRegistry);
        registry.* = .{};
        return registry;
    }

    fn retain(self: *ActiveAccountLoginRegistry) void {
        _ = self.ref_count.fetchAdd(1, .acq_rel);
    }

    fn release(self: *ActiveAccountLoginRegistry, allocator: std.mem.Allocator, cancel: bool) void {
        if (self.ref_count.fetchSub(1, .acq_rel) == 1) {
            clearActiveAccountLoginRegistry(allocator, self, cancel);
            allocator.destroy(self);
        }
    }
};

const AccountLoginCancelToken = struct {
    canceled: std.atomic.Value(bool) = .init(false),
    ref_count: std.atomic.Value(usize) = .init(1),

    fn retain(self: *AccountLoginCancelToken) void {
        _ = self.ref_count.fetchAdd(1, .acq_rel);
    }

    fn release(self: *AccountLoginCancelToken, allocator: std.mem.Allocator) void {
        if (self.ref_count.fetchSub(1, .acq_rel) == 1) allocator.destroy(self);
    }
};

