pub fn run(allocator: std.mem.Allocator, args: *std.process.Args.Iterator) !void {
    try runWithOptions(allocator, args, .{});
}

pub fn runWithOptions(
    allocator: std.mem.Allocator,
    args: *std.process.Args.Iterator,
    invocation_options: InvocationOptions,
) !void {
    var raw_args = std.ArrayList([]const u8).empty;
    defer raw_args.deinit(allocator);
    while (args.next()) |arg| try raw_args.append(allocator, arg);
    try runWithOptionsArgs(allocator, raw_args.items, invocation_options);
}

fn runWithOptionsArgs(
    allocator: std.mem.Allocator,
    raw_args: []const []const u8,
    invocation_options: InvocationOptions,
) !void {
    var options = AppServerOptions{};
    defer options.deinit(allocator);
    var local_profile_override = invocation_options.profile;
    var local_runtime_overrides = invocation_options.runtime_overrides;
    var local_feature_overrides = try invocation_options.feature_overrides.clone(allocator);
    defer local_feature_overrides.deinit(allocator);
    var local_unknown_config_override: ?[]const u8 = null;
    defer if (local_unknown_config_override) |field| allocator.free(field);
    var local_child_global_args = std.ArrayList([]const u8).empty;
    defer local_child_global_args.deinit(allocator);
    var owned_child_global_args = std.ArrayList([]const u8).empty;
    defer {
        for (owned_child_global_args.items) |arg| allocator.free(arg);
        owned_child_global_args.deinit(allocator);
    }
    try local_child_global_args.appendSlice(allocator, invocation_options.child_global_args);
    try appendDaemonProfileArgs(allocator, &local_child_global_args, &owned_child_global_args, invocation_options.profile);
    var subcommand: ?[]const u8 = null;
    var subcommand_args = std.ArrayList([]const u8).empty;
    defer subcommand_args.deinit(allocator);
    const help_like = tailHasHelp(raw_args);

    var index: usize = 0;
    while (index < raw_args.len) : (index += 1) {
        const arg = raw_args[index];
        if (subcommand != null) {
            try subcommand_args.append(allocator, arg);
            continue;
        }
        if (isHelpFlag(arg)) {
            printHelp();
            return;
        }
        if (std.mem.eql(u8, arg, "--listen")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerListenValue;
            options.listen_url = raw_args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--listen=")) {
            options.listen_url = arg["--listen=".len..];
            continue;
        }
        if (std.mem.eql(u8, arg, "--session-source")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerSessionSource;
            try setAppServerSessionSource(allocator, &options, raw_args[index]);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--session-source=")) {
            try setAppServerSessionSource(allocator, &options, arg["--session-source=".len..]);
            continue;
        }
        if (std.mem.eql(u8, arg, "--analytics-default-enabled")) {
            continue;
        }
        if (std.mem.eql(u8, arg, "--remote-control")) {
            options.remote_control_enabled = true;
            continue;
        }
        if (std.mem.eql(u8, arg, "--strict-config")) {
            options.strict_config = true;
            continue;
        }
        if (try parseAppServerLocalConfigFeatureArg(
            allocator,
            raw_args,
            &index,
            &local_profile_override,
            &local_runtime_overrides,
            &local_feature_overrides,
            &local_unknown_config_override,
            &local_child_global_args,
            !help_like,
        )) continue;
        if (std.mem.eql(u8, arg, "--ws-auth")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerWebsocketAuthMode;
            options.websocket_auth.ws_auth = try parseWebsocketAuthMode(raw_args[index]);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-auth=")) {
            options.websocket_auth.ws_auth = try parseWebsocketAuthMode(arg["--ws-auth=".len..]);
            continue;
        }
        if (std.mem.eql(u8, arg, "--ws-token-file")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerWebsocketTokenFile;
            options.websocket_auth.ws_token_file = raw_args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-token-file=")) {
            options.websocket_auth.ws_token_file = arg["--ws-token-file=".len..];
            continue;
        }
        if (std.mem.eql(u8, arg, "--ws-token-sha256")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerWebsocketTokenSha256;
            options.websocket_auth.ws_token_sha256 = raw_args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-token-sha256=")) {
            options.websocket_auth.ws_token_sha256 = arg["--ws-token-sha256=".len..];
            continue;
        }
        if (std.mem.eql(u8, arg, "--ws-shared-secret-file")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerWebsocketSharedSecretFile;
            options.websocket_auth.ws_shared_secret_file = raw_args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-shared-secret-file=")) {
            options.websocket_auth.ws_shared_secret_file = arg["--ws-shared-secret-file=".len..];
            continue;
        }
        if (std.mem.eql(u8, arg, "--ws-issuer")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerWebsocketIssuer;
            options.websocket_auth.ws_issuer = raw_args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-issuer=")) {
            options.websocket_auth.ws_issuer = arg["--ws-issuer=".len..];
            continue;
        }
        if (std.mem.eql(u8, arg, "--ws-audience")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerWebsocketAudience;
            options.websocket_auth.ws_audience = raw_args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-audience=")) {
            options.websocket_auth.ws_audience = arg["--ws-audience=".len..];
            continue;
        }
        if (std.mem.eql(u8, arg, "--ws-max-clock-skew-seconds")) {
            index += 1;
            if (index >= raw_args.len) return error.MissingAppServerWebsocketClockSkew;
            options.websocket_auth.ws_max_clock_skew_seconds = try parseWebsocketClockSkew(raw_args[index]);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-max-clock-skew-seconds=")) {
            options.websocket_auth.ws_max_clock_skew_seconds = try parseWebsocketClockSkew(arg["--ws-max-clock-skew-seconds=".len..]);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "-")) {
            return error.UnknownAppServerOption;
        }
        if (subcommand != null) return error.UnexpectedAppServerArgument;
        subcommand = arg;
    }

    const strict_config = invocation_options.strict_config or options.strict_config;

    if (subcommand) |name| {
        const subcommand_help = appServerSubcommandTailHasHelp(name, subcommand_args.items);
        const subcommand_help_like = subcommand_help or
            std.mem.eql(u8, name, "help") or
            (std.mem.eql(u8, name, "daemon") and daemonTailMentionsHelp(subcommand_args.items));
        if (strict_config and !subcommand_help_like) return failStrictConfigUnsupportedForSubcommandWithTail(name, subcommand_args.items);
        if (!subcommand_help_like) try features_cmd.validateRawConfigOverrides(local_feature_overrides);
        if (std.mem.eql(u8, name, "help")) {
            try printAppServerHelpForArgs(subcommand_args.items);
            return;
        }
        if (std.mem.eql(u8, name, "proxy")) {
            try runProxy(allocator, subcommand_args.items, local_feature_overrides);
            return;
        }
        if (std.mem.eql(u8, name, "daemon")) {
            try runDaemon(allocator, subcommand_args.items, local_feature_overrides, local_child_global_args.items);
            return;
        }
        if (std.mem.eql(u8, name, "generate-ts")) {
            if (subcommand_help) {
                printGenerateTsHelp();
                return;
            }
            try runGenerateTs(allocator, subcommand_args.items, local_feature_overrides);
            return;
        }
        if (std.mem.eql(u8, name, "generate-json-schema")) {
            if (subcommand_help) {
                printGenerateJsonSchemaHelp();
                return;
            }
            try runGenerateJsonSchema(allocator, subcommand_args.items, local_feature_overrides);
            return;
        }
        if (std.mem.eql(u8, name, "generate-internal-json-schema")) {
            if (subcommand_help) {
                printGenerateInternalJsonSchemaHelp();
                return;
            }
            try runGenerateInternalJsonSchema(allocator, subcommand_args.items, local_feature_overrides);
            return;
        }
        return error.UnknownAppServerSubcommand;
    }

    if (strict_config) {
        if (local_unknown_config_override) |field| return config.failStrictConfigUnknownCliOverride(field);
        var cfg = try config.loadWithOptions(allocator, .{
            .profile = local_profile_override,
            .strict_config = true,
        });
        defer cfg.deinit(allocator);
    }

    try validateWebsocketAuthArgs(options.websocket_auth);

    const transport = parseTransport(options.listen_url) catch |err| {
        const message = try std.fmt.allocPrint(
            allocator,
            "unsupported --listen URL '{s}', expected `stdio://`, `unix://`, `unix://PATH`, `ws://IP:PORT`, or `off`\n",
            .{options.listen_url},
        );
        defer allocator.free(message);
        try cli_utils.writeStderr(message);
        return err;
    };

    var server_feature_overrides = try local_feature_overrides.clone(allocator);
    defer server_feature_overrides.deinit(allocator);
    if (options.remote_control_enabled) {
        try server_feature_overrides.put(allocator, "remote_control", true);
    }
    try features_cmd.validateRawConfigOverrides(server_feature_overrides);
    var server_invocation_options = invocation_options;
    server_invocation_options.profile = local_profile_override;
    server_invocation_options.runtime_overrides = local_runtime_overrides;
    server_invocation_options.feature_overrides = server_feature_overrides;
    server_invocation_options.remote_control_enabled = options.remote_control_enabled;
    server_invocation_options.session_source = options.session_source;

    switch (transport) {
        .stdio => {
            var server = StdioServer{ .allocator = allocator, .invocation_options = server_invocation_options };
            try server.run();
        },
        .off => try cli_utils.writeStdout("app-server transport: off\n"),
        .unix_default => {
            const socket_path = try defaultUnixSocketPath(allocator);
            defer allocator.free(socket_path);
            var server = UnixServer{ .allocator = allocator, .socket_path = socket_path, .invocation_options = server_invocation_options };
            try server.run();
        },
        .unix_path => |path| {
            var server = UnixServer{ .allocator = allocator, .socket_path = path, .invocation_options = server_invocation_options };
            try server.run();
        },
        .websocket => |address| {
            var auth_policy = try websocketAuthPolicyFromArgs(allocator, options.websocket_auth);
            defer auth_policy.deinit(allocator);
            var server = WebSocketServer{ .allocator = allocator, .address = address, .auth_policy = auth_policy, .invocation_options = server_invocation_options };
            try server.run();
        },
    }
}

const DaemonCommand = enum {
    bootstrap,
    start,
    restart,
    enable_remote_control,
    disable_remote_control,
    stop,
    version,
    pid_update_loop,
};

const DaemonRemoteControlSettings = struct {
    remoteControlEnabled: bool,
};

const DaemonRunOptions = struct {
    child_global_args: std.ArrayList([]const u8) = .empty,
    bootstrap_remote_control: bool = false,

    fn deinit(self: *DaemonRunOptions, allocator: std.mem.Allocator) void {
        self.child_global_args.deinit(allocator);
    }
};

const DaemonSocketProbe = union(enum) {
    unavailable: []const u8,
    running: []const u8,

    fn deinit(self: DaemonSocketProbe, allocator: std.mem.Allocator) void {
        switch (self) {
            .unavailable => |cause| allocator.free(cause),
            .running => |version| allocator.free(version),
        }
    }
};

const DaemonLifecycleOutputOptions = struct {
    backend: ?[]const u8 = null,
    pid: ?i64 = null,
    app_server_version: ?[]const u8 = null,
};

const DaemonRemoteControlOutputOptions = struct {
    backend: ?[]const u8 = null,
    app_server_version: ?[]const u8 = null,
};

const DaemonStartOutput = struct {
    pid: i64,
    app_server_version: []const u8,
    started: bool,
};

const DaemonUpdaterStartOutput = struct {
    pid: i64,
    started: bool,
};

const ManagedProcessKind = enum {
    app_server,
    updater,
};

const RemoteControlReadyStatus = struct {
    status: []const u8,
    server_name: []const u8,
    environment_id: ?[]const u8,
    timed_out: bool = false,

    fn deinit(self: *RemoteControlReadyStatus, allocator: std.mem.Allocator) void {
        allocator.free(self.status);
        allocator.free(self.server_name);
        if (self.environment_id) |value| allocator.free(value);
    }
};

const RemoteControlIdentity = struct {
    server_name: []const u8,
    installation_id: []const u8,

    fn deinit(self: *RemoteControlIdentity, allocator: std.mem.Allocator) void {
        allocator.free(self.server_name);
        allocator.free(self.installation_id);
    }
};

const REMOTE_CONTROL_READY_TIMEOUT_MS = 10 * std.time.ms_per_s;

const ManagedPidRecord = struct {
    pid: i64,
    process_start_time: []const u8,
    child_global_args: [][]const u8,

    fn deinit(self: *ManagedPidRecord, allocator: std.mem.Allocator) void {
        allocator.free(self.process_start_time);
        freeStringSlice(allocator, self.child_global_args);
    }
};

const DaemonFileLock = struct {
    file: std.Io.File,

    fn release(self: *DaemonFileLock) void {
        self.file.close(std.Io.Threaded.global_single_threaded.io());
    }
};

const DaemonUnixConnect = union(enum) {
    unavailable: []const u8,
    stream: net.Stream,
};

const DaemonUnixSockaddr = extern union {
    any: std.posix.sockaddr,
    un: std.posix.sockaddr.un,
};

pub fn runRemoteControlDaemonStart(
    allocator: std.mem.Allocator,
    json: bool,
    child_global_args: []const []const u8,
    root_feature_overrides: features_cmd.FeatureOverrides,
) !void {
    const codex_home = try resolveDaemonCodexHome(allocator);
    defer allocator.free(codex_home);

    var daemon_child_args = std.ArrayList([]const u8).empty;
    defer daemon_child_args.deinit(allocator);
    try daemon_child_args.appendSlice(allocator, child_global_args);
    try appendDaemonFeatureOverrideArgsExcluding(allocator, &daemon_child_args, root_feature_overrides, "remote_control");

    try ensureDaemonScaffolding(allocator, codex_home, true);
    try ensureDaemonUpdaterPidLock(allocator, codex_home);
    var operation_lock = try acquireDaemonOperationLock(allocator, codex_home);
    defer operation_lock.release();

    const daemon_output = try ensureRemoteControlDaemonStartedLocked(allocator, codex_home, daemon_child_args.items);
    defer allocator.free(daemon_output);
    var ready = try enableDaemonRemoteControl(allocator, codex_home);
    defer ready.deinit(allocator);

    try writeRemoteControlStartOutput(allocator, ready, daemon_output, json);
}

pub fn runRemoteControlDaemonStop(allocator: std.mem.Allocator, json: bool) !void {
    const codex_home = try resolveDaemonCodexHome(allocator);
    defer allocator.free(codex_home);
    try ensureDaemonScaffolding(allocator, codex_home, true);
    var operation_lock = try acquireDaemonOperationLock(allocator, codex_home);
    defer operation_lock.release();

    const stopped = try stopDaemonLifecycleLocked(allocator, codex_home);
    if (json) {
        try writeDaemonLifecycleOutput(allocator, codex_home, if (stopped) "stopped" else "notRunning", .{
            .backend = if (stopped) "pid" else null,
        });
    } else {
        try cli_utils.writeStdout(if (stopped) "Remote control stopped.\n" else "Remote control is not running.\n");
    }
}

fn runDaemon(
    allocator: std.mem.Allocator,
    raw_args: []const []const u8,
    root_feature_overrides: features_cmd.FeatureOverrides,
    root_child_global_args: []const []const u8,
) !void {
    try validateDaemonLocalFeatureOverrides(allocator, raw_args, root_feature_overrides);

    var command: ?DaemonCommand = null;
    var options = DaemonRunOptions{};
    defer options.deinit(allocator);
    try options.child_global_args.appendSlice(allocator, root_child_global_args);
    try appendDaemonFeatureOverrideArgs(allocator, &options.child_global_args, root_feature_overrides);

    var index: usize = 0;
    while (index < raw_args.len) : (index += 1) {
        const arg = raw_args[index];
        if (isHelpFlag(arg)) {
            if (command) |cmd| {
                printDaemonCommandHelp(cmd);
            } else {
                printDaemonHelp();
            }
            return;
        }
        if (std.mem.eql(u8, arg, "help")) {
            if (command) |cmd| return failUnexpectedDaemonArgument(cmd, arg);
            if (index + 1 < raw_args.len) {
                if (index + 2 < raw_args.len) {
                    if (daemonCommandFromName(raw_args[index + 1])) |cmd| {
                        return failUnknownDaemonSubcommandForCommand(cmd, raw_args[index + 2]);
                    }
                    if (std.mem.eql(u8, raw_args[index + 1], "help")) {
                        return failUnknownDaemonSubcommandForHelp(raw_args[index + 2]);
                    }
                    return failUnknownDaemonSubcommand(raw_args[index + 1]);
                }
                if (std.mem.eql(u8, raw_args[index + 1], "help")) {
                    printDaemonHelpCommandHelp();
                    return;
                }
                if (daemonCommandFromName(raw_args[index + 1])) |cmd| {
                    printDaemonCommandHelp(cmd);
                    return;
                }
                return failUnknownDaemonSubcommand(raw_args[index + 1]);
            }
            printDaemonHelp();
            return;
        }
        if (std.mem.eql(u8, arg, "-c") or std.mem.eql(u8, arg, "--config")) {
            if (index + 1 >= raw_args.len) return failMissingDaemonOptionValue(arg);
            try options.child_global_args.append(allocator, arg);
            index += 1;
            try options.child_global_args.append(allocator, raw_args[index]);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--config=")) {
            try options.child_global_args.append(allocator, arg);
            continue;
        }
        if (std.mem.eql(u8, arg, "--enable") or std.mem.eql(u8, arg, "--disable")) {
            if (index + 1 >= raw_args.len) return failMissingDaemonOptionValue(arg);
            try options.child_global_args.append(allocator, arg);
            index += 1;
            try options.child_global_args.append(allocator, raw_args[index]);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--enable=") or std.mem.startsWith(u8, arg, "--disable=")) {
            try options.child_global_args.append(allocator, arg);
            continue;
        }
        if (std.mem.eql(u8, arg, "--remote-control")) {
            if (command) |cmd| {
                if (cmd != .bootstrap) return failUnknownDaemonOptionForCommand(cmd, arg);
            } else {
                return failUnknownDaemonOption(arg);
            }
            options.bootstrap_remote_control = true;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "-")) {
            if (command) |cmd| return failUnknownDaemonOptionForCommand(cmd, arg);
            return failUnknownDaemonOption(arg);
        }
        if (command) |cmd| return failUnexpectedDaemonArgument(cmd, arg);
        command = daemonCommandFromName(arg) orelse return failUnknownDaemonSubcommand(arg);
    }

    const cmd = command orelse {
        printDaemonHelp();
        return error.AppServerDaemonCommandFailed;
    };

    const codex_home = try resolveDaemonCodexHome(allocator);
    defer allocator.free(codex_home);

    switch (cmd) {
        .stop => try runDaemonStop(allocator, codex_home),
        .enable_remote_control => try runDaemonSetRemoteControl(allocator, codex_home, true, options.child_global_args.items),
        .disable_remote_control => try runDaemonSetRemoteControl(allocator, codex_home, false, options.child_global_args.items),
        .version => try runDaemonVersion(allocator, codex_home),
        .bootstrap => try runDaemonBootstrap(allocator, codex_home, options.bootstrap_remote_control, options.child_global_args.items),
        .start => try runDaemonStart(allocator, codex_home, options.child_global_args.items),
        .restart => try runDaemonRestart(allocator, codex_home, options.child_global_args.items),
        .pid_update_loop => try runDaemonPidUpdateLoop(),
    }
}

fn validateDaemonLocalFeatureOverrides(
    allocator: std.mem.Allocator,
    raw_args: []const []const u8,
    root_feature_overrides: features_cmd.FeatureOverrides,
) !void {
    if (daemonTailMentionsHelp(raw_args)) return;

    var feature_overrides = try root_feature_overrides.clone(allocator);
    defer feature_overrides.deinit(allocator);

    var index: usize = 0;
    while (index < raw_args.len) : (index += 1) {
        const arg = raw_args[index];
        if (std.mem.eql(u8, arg, "-c") or std.mem.eql(u8, arg, "--config")) {
            if (index + 1 >= raw_args.len) return failMissingDaemonOptionValue(arg);
            index += 1;
            try features_cmd.applyRawConfigOverride(allocator, &feature_overrides, raw_args[index]);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--config=")) {
            try features_cmd.applyRawConfigOverride(allocator, &feature_overrides, arg["--config=".len..]);
            continue;
        }
        if (std.mem.eql(u8, arg, "--enable")) {
            if (index + 1 >= raw_args.len) return failMissingDaemonOptionValue(arg);
            index += 1;
            try features_cmd.putRuntimeToggle(allocator, &feature_overrides, raw_args[index], true);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--enable=")) {
            try features_cmd.putRuntimeToggle(allocator, &feature_overrides, arg["--enable=".len..], true);
            continue;
        }
        if (std.mem.eql(u8, arg, "--disable")) {
            if (index + 1 >= raw_args.len) return failMissingDaemonOptionValue(arg);
            index += 1;
            try features_cmd.putRuntimeToggle(allocator, &feature_overrides, raw_args[index], false);
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--disable=")) {
            try features_cmd.putRuntimeToggle(allocator, &feature_overrides, arg["--disable=".len..], false);
            continue;
        }
    }

    try features_cmd.validateRawConfigOverrides(feature_overrides);
}

fn parseAppServerLocalConfigFeatureArg(
    allocator: std.mem.Allocator,
    args: []const []const u8,
    index: *usize,
    profile_override: ?*?[]const u8,
    runtime_overrides: ?*config.RuntimeOverrides,
    feature_overrides: *features_cmd.FeatureOverrides,
    unknown_config_override: ?*?[]const u8,
    child_global_args: ?*std.ArrayList([]const u8),
    validate: bool,
) !bool {
    const arg = args[index.*];
    if (std.mem.eql(u8, arg, "-c") or std.mem.eql(u8, arg, "--config")) {
        if (index.* + 1 >= args.len or optionValueLooksMissing(args[index.* + 1])) return error.MissingConfigOptionValue;
        index.* += 1;
        const raw = args[index.*];
        if (raw.len != 0 and validate) {
            if (unknown_config_override) |unknown| {
                try config.rememberStrictConfigUnknownOverride(allocator, unknown, raw);
            }
            if (runtime_overrides) |runtime| {
                var ignored_profile_override: ?[]const u8 = null;
                const profile_target = profile_override orelse &ignored_profile_override;
                try config.applyRawConfigOverride(runtime, profile_target, raw);
            }
            try features_cmd.applyRawConfigOverride(allocator, feature_overrides, raw);
        }
        if (raw.len != 0) {
            if (child_global_args) |child_args| {
                try child_args.append(allocator, arg);
                try child_args.append(allocator, raw);
            }
        }
        return true;
    }
    if (std.mem.startsWith(u8, arg, "--config=")) {
        const raw = arg["--config=".len..];
        if (raw.len != 0 and validate) {
            if (unknown_config_override) |unknown| {
                try config.rememberStrictConfigUnknownOverride(allocator, unknown, raw);
            }
            if (runtime_overrides) |runtime| {
                var ignored_profile_override: ?[]const u8 = null;
                const profile_target = profile_override orelse &ignored_profile_override;
                try config.applyRawConfigOverride(runtime, profile_target, raw);
            }
            try features_cmd.applyRawConfigOverride(allocator, feature_overrides, raw);
        }
        if (raw.len != 0) {
            if (child_global_args) |child_args| try child_args.append(allocator, arg);
        }
        return true;
    }
    if (std.mem.eql(u8, arg, "--enable")) {
        if (index.* + 1 >= args.len or optionValueLooksMissing(args[index.* + 1])) return error.MissingFeatureName;
        index.* += 1;
        if (validate) try features_cmd.putRuntimeToggle(allocator, feature_overrides, args[index.*], true);
        return true;
    }
    if (std.mem.startsWith(u8, arg, "--enable=")) {
        if (validate) try features_cmd.putRuntimeToggle(allocator, feature_overrides, arg["--enable=".len..], true);
        return true;
    }
    if (std.mem.eql(u8, arg, "--disable")) {
        if (index.* + 1 >= args.len or optionValueLooksMissing(args[index.* + 1])) return error.MissingFeatureName;
        index.* += 1;
        if (validate) try features_cmd.putRuntimeToggle(allocator, feature_overrides, args[index.*], false);
        return true;
    }
    if (std.mem.startsWith(u8, arg, "--disable=")) {
        if (validate) try features_cmd.putRuntimeToggle(allocator, feature_overrides, arg["--disable=".len..], false);
        return true;
    }
    return false;
}

fn validateAppServerLocalConfigFeatureOverrides(
    allocator: std.mem.Allocator,
    args: []const []const u8,
    root_feature_overrides: features_cmd.FeatureOverrides,
) !void {
    var runtime_overrides = config.RuntimeOverrides{};
    var feature_overrides = try root_feature_overrides.clone(allocator);
    defer feature_overrides.deinit(allocator);

    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        _ = try parseAppServerLocalConfigFeatureArg(
            allocator,
            args,
            &index,
            null,
            &runtime_overrides,
            &feature_overrides,
            null,
            null,
            true,
        );
    }

    try features_cmd.validateRawConfigOverrides(feature_overrides);
}

pub fn tailHasHelp(args: []const []const u8) bool {
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (std.mem.eql(u8, arg, "--")) return false;
        if (isHelpFlag(arg)) return true;
        if (std.mem.eql(u8, arg, "--ws-auth")) {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            _ = parseWebsocketAuthMode(args[index]) catch return false;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-auth=")) {
            _ = parseWebsocketAuthMode(arg["--ws-auth=".len..]) catch return false;
            continue;
        }
        if (std.mem.eql(u8, arg, "--ws-max-clock-skew-seconds")) {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            _ = parseWebsocketClockSkew(args[index]) catch return false;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--ws-max-clock-skew-seconds=")) {
            _ = parseWebsocketClockSkew(arg["--ws-max-clock-skew-seconds=".len..]) catch return false;
            continue;
        }
        if (appServerRootOptionConsumesSingleValue(arg)) {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            continue;
        }
        if (appServerRootOptionHasInlineValue(arg) or appServerRootOptionIsBoolean(arg)) {
            continue;
        }
        if (std.mem.startsWith(u8, arg, "-")) return false;
        return appServerSubcommandTailHasHelp(arg, args[index + 1 ..]);
    }
    return false;
}

fn appServerRootOptionConsumesSingleValue(arg: []const u8) bool {
    return std.mem.eql(u8, arg, "--listen") or
        std.mem.eql(u8, arg, "--session-source") or
        std.mem.eql(u8, arg, "-c") or
        std.mem.eql(u8, arg, "--config") or
        std.mem.eql(u8, arg, "--enable") or
        std.mem.eql(u8, arg, "--disable") or
        std.mem.eql(u8, arg, "--ws-auth") or
        std.mem.eql(u8, arg, "--ws-token-file") or
        std.mem.eql(u8, arg, "--ws-token-sha256") or
        std.mem.eql(u8, arg, "--ws-shared-secret-file") or
        std.mem.eql(u8, arg, "--ws-issuer") or
        std.mem.eql(u8, arg, "--ws-audience") or
        std.mem.eql(u8, arg, "--ws-max-clock-skew-seconds");
}

fn appServerRootOptionHasInlineValue(arg: []const u8) bool {
    return std.mem.startsWith(u8, arg, "--listen=") or
        std.mem.startsWith(u8, arg, "--session-source=") or
        std.mem.startsWith(u8, arg, "--config=") or
        std.mem.startsWith(u8, arg, "--enable=") or
        std.mem.startsWith(u8, arg, "--disable=") or
        std.mem.startsWith(u8, arg, "--ws-auth=") or
        std.mem.startsWith(u8, arg, "--ws-token-file=") or
        std.mem.startsWith(u8, arg, "--ws-token-sha256=") or
        std.mem.startsWith(u8, arg, "--ws-shared-secret-file=") or
        std.mem.startsWith(u8, arg, "--ws-issuer=") or
        std.mem.startsWith(u8, arg, "--ws-audience=") or
        std.mem.startsWith(u8, arg, "--ws-max-clock-skew-seconds=");
}

fn appServerRootOptionIsBoolean(arg: []const u8) bool {
    return std.mem.eql(u8, arg, "--analytics-default-enabled") or
        std.mem.eql(u8, arg, "--remote-control") or
        std.mem.eql(u8, arg, "--strict-config");
}

fn appServerSubcommandTailHasHelp(name: []const u8, args: []const []const u8) bool {
    if (std.mem.eql(u8, name, "help")) return true;
    if (std.mem.eql(u8, name, "proxy")) return proxyTailHasHelp(args);
    if (std.mem.eql(u8, name, "daemon")) return daemonTailHasHelp(args);
    if (std.mem.eql(u8, name, "generate-ts")) return generatorTailHasHelp(args, true);
    if (std.mem.eql(u8, name, "generate-json-schema")) return generatorTailHasHelp(args, false);
    if (std.mem.eql(u8, name, "generate-internal-json-schema")) return generatorTailHasHelp(args, false);
    return false;
}

fn proxyTailHasHelp(args: []const []const u8) bool {
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (std.mem.eql(u8, arg, "--")) return false;
        if (isHelpFlag(arg)) return true;
        if (appServerLocalConfigFeatureOptionConsumesValue(arg)) {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            continue;
        }
        if (appServerLocalConfigFeatureOptionHasInlineValue(arg)) continue;
        if (std.mem.eql(u8, arg, "--sock")) {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--sock=")) continue;
        return false;
    }
    return false;
}

fn generatorTailHasHelp(args: []const []const u8, allow_prettier: bool) bool {
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (std.mem.eql(u8, arg, "--")) return false;
        if (isHelpFlag(arg)) return true;
        if (appServerLocalConfigFeatureOptionConsumesValue(arg)) {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            continue;
        }
        if (appServerLocalConfigFeatureOptionHasInlineValue(arg)) continue;
        if (std.mem.eql(u8, arg, "-o") or std.mem.eql(u8, arg, "--out")) {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--out=")) continue;
        if (allow_prettier and (std.mem.eql(u8, arg, "-p") or std.mem.eql(u8, arg, "--prettier"))) {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            continue;
        }
        if (allow_prettier and std.mem.startsWith(u8, arg, "--prettier=")) continue;
        if (std.mem.eql(u8, arg, "--experimental")) continue;
        return false;
    }
    return false;
}

fn daemonTailHasHelp(args: []const []const u8) bool {
    var command_seen: ?[]const u8 = null;
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (std.mem.eql(u8, arg, "--")) return false;
        if (isHelpFlag(arg)) return true;
        if (std.mem.eql(u8, arg, "help")) {
            if (command_seen != null) return false;
            if (index + 1 >= args.len) return true;
            if (index + 2 < args.len) return false;
            return daemonCommandNameIsValid(args[index + 1]) or std.mem.eql(u8, args[index + 1], "help");
        }
        if (std.mem.eql(u8, arg, "-c") or
            std.mem.eql(u8, arg, "--config") or
            std.mem.eql(u8, arg, "--enable") or
            std.mem.eql(u8, arg, "--disable"))
        {
            index += 1;
            if (index >= args.len or optionValueLooksMissing(args[index])) return false;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--config=") or
            std.mem.startsWith(u8, arg, "--enable=") or
            std.mem.startsWith(u8, arg, "--disable="))
        {
            continue;
        }
        if (std.mem.eql(u8, arg, "--remote-control")) {
            if (command_seen) |cmd| {
                if (std.mem.eql(u8, cmd, "bootstrap")) continue;
            }
            return false;
        }
        if (std.mem.startsWith(u8, arg, "-")) return false;
        if (!daemonCommandNameIsValid(arg) or command_seen != null) return false;
        command_seen = arg;
    }
    return false;
}

fn daemonTailMentionsHelp(args: []const []const u8) bool {
    for (args) |arg| {
        if (isHelpFlag(arg) or std.mem.eql(u8, arg, "help")) return true;
    }
    return false;
}

fn daemonCommandNameIsValid(arg: []const u8) bool {
    return daemonCommandFromName(arg) != null;
}

fn optionValueLooksMissing(arg: []const u8) bool {
    return std.mem.eql(u8, arg, "--") or std.mem.startsWith(u8, arg, "-");
}

fn appServerLocalConfigFeatureOptionConsumesValue(arg: []const u8) bool {
    return std.mem.eql(u8, arg, "-c") or
        std.mem.eql(u8, arg, "--config") or
        std.mem.eql(u8, arg, "--enable") or
        std.mem.eql(u8, arg, "--disable");
}

fn appServerLocalConfigFeatureOptionHasInlineValue(arg: []const u8) bool {
    return std.mem.startsWith(u8, arg, "--config=") or
        std.mem.startsWith(u8, arg, "--enable=") or
        std.mem.startsWith(u8, arg, "--disable=");
}

fn appendDaemonFeatureOverrideArgs(
    allocator: std.mem.Allocator,
    child_global_args: *std.ArrayList([]const u8),
    overrides: features_cmd.FeatureOverrides,
) !void {
    try appendDaemonFeatureOverrideArgsExcluding(allocator, child_global_args, overrides, null);
}

fn appendDaemonProfileArgs(
    allocator: std.mem.Allocator,
    child_global_args: *std.ArrayList([]const u8),
    owned_child_global_args: *std.ArrayList([]const u8),
    profile: ?[]const u8,
) !void {
    if (profile) |value| {
        if (daemonChildArgsContainProfileOverride(child_global_args.items)) return;
        const raw = try std.fmt.allocPrint(allocator, "profile={s}", .{value});
        errdefer allocator.free(raw);
        try owned_child_global_args.append(allocator, raw);
        try child_global_args.append(allocator, "-c");
        try child_global_args.append(allocator, raw);
    }
}

fn daemonChildArgsContainProfileOverride(args: []const []const u8) bool {
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (std.mem.eql(u8, arg, "-c") or std.mem.eql(u8, arg, "--config")) {
            if (index + 1 < args.len and daemonConfigOverrideIsProfile(args[index + 1])) return true;
            index += 1;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--config=") and daemonConfigOverrideIsProfile(arg["--config=".len..])) return true;
    }
    return false;
}

fn daemonConfigOverrideIsProfile(raw: []const u8) bool {
    const trimmed = std.mem.trim(u8, raw, " \t\r\n");
    if (!std.mem.startsWith(u8, trimmed, "profile")) return false;
    const rest = std.mem.trim(u8, trimmed["profile".len..], " \t\r\n");
    return rest.len > 0 and rest[0] == '=';
}

fn appendDaemonFeatureOverrideArgsExcluding(
    allocator: std.mem.Allocator,
    child_global_args: *std.ArrayList([]const u8),
    overrides: features_cmd.FeatureOverrides,
    excluded_key: ?[]const u8,
) !void {
    for (overrides.items.items) |item| {
        if (excluded_key) |key| {
            if (std.mem.eql(u8, item.key, key)) continue;
        }
        try child_global_args.append(allocator, if (item.enabled) "--enable" else "--disable");
        try child_global_args.append(allocator, item.key);
    }
}

test "daemon profile and feature args are appended after forwarded root config args" {
    const allocator = std.testing.allocator;
    var args = std.ArrayList([]const u8).empty;
    defer args.deinit(allocator);
    var owned_args = std.ArrayList([]const u8).empty;
    defer {
        for (owned_args.items) |arg| allocator.free(arg);
        owned_args.deinit(allocator);
    }
    try args.appendSlice(allocator, &.{ "-c", "features.artifact=false" });
    try appendDaemonProfileArgs(allocator, &args, &owned_args, "work");
    var overrides = features_cmd.FeatureOverrides{};
    defer overrides.deinit(allocator);
    try overrides.put(allocator, "artifact", true);

    try appendDaemonFeatureOverrideArgs(allocator, &args, overrides);

    try std.testing.expectEqual(@as(usize, 6), args.items.len);
    try std.testing.expectEqualStrings("-c", args.items[0]);
    try std.testing.expectEqualStrings("features.artifact=false", args.items[1]);
    try std.testing.expectEqualStrings("-c", args.items[2]);
    try std.testing.expectEqualStrings("profile=work", args.items[3]);
    try std.testing.expectEqualStrings("--enable", args.items[4]);
    try std.testing.expectEqualStrings("artifact", args.items[5]);
}

test "daemon profile arg is not duplicated when forwarded config already selects one" {
    const allocator = std.testing.allocator;
    var split_args = std.ArrayList([]const u8).empty;
    defer split_args.deinit(allocator);
    var split_owned = std.ArrayList([]const u8).empty;
    defer {
        for (split_owned.items) |arg| allocator.free(arg);
        split_owned.deinit(allocator);
    }
    try split_args.appendSlice(allocator, &.{ "-c", "profile = \"work\"" });
    try appendDaemonProfileArgs(allocator, &split_args, &split_owned, "other");
    try std.testing.expectEqual(@as(usize, 2), split_args.items.len);

    var inline_args = std.ArrayList([]const u8).empty;
    defer inline_args.deinit(allocator);
    var inline_owned = std.ArrayList([]const u8).empty;
    defer {
        for (inline_owned.items) |arg| allocator.free(arg);
        inline_owned.deinit(allocator);
    }
    try inline_args.append(allocator, "--config=profile=work");
    try appendDaemonProfileArgs(allocator, &inline_args, &inline_owned, "other");
    try std.testing.expectEqual(@as(usize, 1), inline_args.items.len);
}

test "daemon local feature overrides validate before non-launch actions" {
    const allocator = std.testing.allocator;
    var root = features_cmd.FeatureOverrides{};
    defer root.deinit(allocator);
    try root.put(allocator, "artifact", true);

    try validateDaemonLocalFeatureOverrides(allocator, &.{ "-c", "features.artifact=false", "version" }, root);
    try validateDaemonLocalFeatureOverrides(allocator, &.{ "stop", "--disable=shell_tool" }, root);
    try std.testing.expectError(error.InvalidConfigOverride, validateDaemonLocalFeatureOverrides(allocator, &.{ "-c", "features.artifact=maybe", "stop" }, root));
    try std.testing.expectError(error.UnknownFeature, validateDaemonLocalFeatureOverrides(allocator, &.{ "version", "--enable", "definitely-not-a-feature" }, root));
    try std.testing.expectError(error.InvalidConfigOverride, validateDaemonLocalFeatureOverrides(allocator, &.{ "version", "-c", "features.network_proxy.mode=limited" }, root));
    try validateDaemonLocalFeatureOverrides(allocator, &.{ "-c", "features.artifact=maybe", "--help" }, root);
}

test "app-server local feature flags participate in help preflight" {
    try std.testing.expect(tailHasHelp(&.{ "--enable", "definitely-not-a-feature", "--help" }));
    try std.testing.expect(tailHasHelp(&.{ "-c", "features.artifact=maybe", "proxy", "--help" }));
    try std.testing.expect(tailHasHelp(&.{ "proxy", "--enable", "definitely-not-a-feature", "--help" }));
    try std.testing.expect(tailHasHelp(&.{ "generate-ts", "--out", "src", "--disable", "definitely-not-a-feature", "--help" }));

    try std.testing.expect(!tailHasHelp(&.{ "--enable", "--help" }));
    try std.testing.expect(!tailHasHelp(&.{ "-c", "--help" }));
    try std.testing.expect(!tailHasHelp(&.{ "proxy", "--disable", "--help" }));
    try std.testing.expect(!tailHasHelp(&.{ "generate-json-schema", "--enable", "--help" }));
}

test "app-server local feature overrides validate for execution" {
    const allocator = std.testing.allocator;
    var root = features_cmd.FeatureOverrides{};
    defer root.deinit(allocator);
    try root.put(allocator, "artifact", true);

    try validateAppServerLocalConfigFeatureOverrides(allocator, &.{ "--disable", "artifact" }, root);
    try validateAppServerLocalConfigFeatureOverrides(allocator, &.{ "-c", "features.artifact=false" }, root);
    try validateAppServerLocalConfigFeatureOverrides(allocator, &.{"--config="}, root);
    try validateAppServerLocalConfigFeatureOverrides(allocator, &.{ "-c", "" }, root);
    try std.testing.expectError(error.UnknownFeature, validateAppServerLocalConfigFeatureOverrides(allocator, &.{ "--enable", "definitely-not-a-feature" }, root));
    try std.testing.expectError(error.InvalidConfigOverride, validateAppServerLocalConfigFeatureOverrides(allocator, &.{ "-c", "features.network_proxy.mode=limited" }, root));

    var runtime = config.RuntimeOverrides{};
    var feature_overrides = features_cmd.FeatureOverrides{};
    defer feature_overrides.deinit(allocator);
    var unknown: ?[]const u8 = null;
    defer if (unknown) |field| allocator.free(field);
    var index: usize = 0;
    try std.testing.expect(try parseAppServerLocalConfigFeatureArg(
        allocator,
        &.{ "-c", "typo.field=1" },
        &index,
        null,
        &runtime,
        &feature_overrides,
        &unknown,
        null,
        true,
    ));
    try std.testing.expectEqualStrings("typo.field", unknown.?);

    var profile: ?[]const u8 = "base";
    index = 0;
    try std.testing.expect(try parseAppServerLocalConfigFeatureArg(
        allocator,
        &.{ "-c", "profile=work" },
        &index,
        &profile,
        &runtime,
        &feature_overrides,
        null,
        null,
        true,
    ));
    try std.testing.expectEqualStrings("work", profile.?);
}

test "app-server generator tails defer semantic checks for help" {
    try std.testing.expect(appServerSubcommandTailHasHelp("generate-ts", &.{"--help"}));
    try std.testing.expect(appServerSubcommandTailHasHelp("generate-ts", &.{ "--out", "src", "--help" }));
    try std.testing.expect(appServerSubcommandTailHasHelp("generate-ts", &.{ "--out=src", "--prettier", "prettier", "--help" }));
    try std.testing.expect(appServerSubcommandTailHasHelp("generate-json-schema", &.{ "--out", "src", "--help" }));
    try std.testing.expect(appServerSubcommandTailHasHelp("generate-internal-json-schema", &.{ "--out", "src", "--help" }));

    try std.testing.expect(!appServerSubcommandTailHasHelp("generate-ts", &.{ "--out", "--help" }));
    try std.testing.expect(!appServerSubcommandTailHasHelp("generate-ts", &.{ "--prettier", "--help" }));
    try std.testing.expect(!appServerSubcommandTailHasHelp("generate-json-schema", &.{ "--prettier", "prettier", "--help" }));
    try std.testing.expect(!appServerSubcommandTailHasHelp("generate-json-schema", &.{ "--out", "--help" }));
}

