fn daemonCommandFromName(name: []const u8) ?DaemonCommand {
    if (std.mem.eql(u8, name, "bootstrap")) return .bootstrap;
    if (std.mem.eql(u8, name, "start")) return .start;
    if (std.mem.eql(u8, name, "restart")) return .restart;
    if (std.mem.eql(u8, name, "enable-remote-control")) return .enable_remote_control;
    if (std.mem.eql(u8, name, "disable-remote-control")) return .disable_remote_control;
    if (std.mem.eql(u8, name, "stop")) return .stop;
    if (std.mem.eql(u8, name, "version")) return .version;
    if (std.mem.eql(u8, name, "pid-update-loop")) return .pid_update_loop;
    return null;
}

fn runDaemonBootstrap(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    remote_control_enabled: bool,
    child_global_args: []const []const u8,
) !void {
    try ensureDaemonScaffolding(allocator, codex_home, true);
    try ensureDaemonUpdaterPidLock(allocator, codex_home);
    var operation_lock = try acquireDaemonOperationLock(allocator, codex_home);
    defer operation_lock.release();

    const app_server_version = try bootstrapManagedDaemonLocked(allocator, codex_home, remote_control_enabled, child_global_args);
    defer allocator.free(app_server_version);
    try writeDaemonBootstrapOutput(allocator, codex_home, remote_control_enabled, app_server_version);
}

fn bootstrapManagedDaemonLocked(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    remote_control_enabled: bool,
    child_global_args: []const []const u8,
) ![]const u8 {
    const managed_path = try ensureManagedCodexPath(allocator, codex_home);
    defer allocator.free(managed_path);

    const settings_path = try daemonSettingsPath(allocator, codex_home);
    defer allocator.free(settings_path);
    const probe = try probeDaemonSocket(allocator, codex_home);
    defer probe.deinit(allocator);
    switch (probe) {
        .running => {
            if (try managedDaemonBackend(allocator, codex_home) == null) return failDaemonUnmanagedRunning();
        },
        .unavailable => {},
    }

    try writeDaemonRemoteControlSettings(settings_path, remote_control_enabled);
    _ = try stopManagedDaemonIfRunning(allocator, codex_home);
    _ = try stopManagedUpdaterIfRunning(allocator, codex_home);

    const started = try startManagedDaemon(allocator, codex_home, child_global_args);
    errdefer allocator.free(started.app_server_version);
    _ = try startManagedUpdater(allocator, codex_home);
    return started.app_server_version;
}

fn writeDaemonBootstrapOutput(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    remote_control_enabled: bool,
    app_server_version: []const u8,
) !void {
    const output = try renderDaemonBootstrapOutput(allocator, codex_home, remote_control_enabled, app_server_version);
    defer allocator.free(output);
    try writeStdoutLine(output);
}

fn renderDaemonBootstrapOutput(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    remote_control_enabled: bool,
    app_server_version: []const u8,
) ![]const u8 {
    const managed_path = try managedCodexPath(allocator, codex_home);
    defer allocator.free(managed_path);
    const managed_version = try managedCodexVersionBestEffort(allocator, managed_path);
    defer if (managed_version) |version| allocator.free(version);
    const socket_path = try daemonSocketPath(allocator, codex_home);
    defer allocator.free(socket_path);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"status\":\"bootstrapped\",\"backend\":\"pid\",\"autoUpdateEnabled\":true,\"remoteControlEnabled\":");
    try out.appendSlice(allocator, if (remote_control_enabled) "true" else "false");
    try out.appendSlice(allocator, ",\"managedCodexPath\":");
    try appendJsonString(allocator, &out, managed_path);
    try out.appendSlice(allocator, ",\"managedCodexVersion\":");
    if (managed_version) |version| {
        try appendJsonString(allocator, &out, version);
    } else {
        try out.appendSlice(allocator, "null");
    }
    try out.appendSlice(allocator, ",\"socketPath\":");
    try appendJsonString(allocator, &out, socket_path);
    try out.appendSlice(allocator, ",\"cliVersion\":");
    try appendJsonString(allocator, &out, CLI_VERSION);
    try out.appendSlice(allocator, ",\"appServerVersion\":");
    try appendJsonString(allocator, &out, app_server_version);
    try out.appendSlice(allocator, "}");
    return try out.toOwnedSlice(allocator);
}

fn runDaemonPidUpdateLoop() !void {
    while (true) {
        std.Io.sleep(
            std.Io.Threaded.global_single_threaded.io(),
            .{ .nanoseconds = 60 * std.time.ns_per_s },
            .awake,
        ) catch {};
    }
}

fn runDaemonStop(allocator: std.mem.Allocator, codex_home: []const u8) !void {
    try ensureDaemonScaffolding(allocator, codex_home, true);
    var operation_lock = try acquireDaemonOperationLock(allocator, codex_home);
    defer operation_lock.release();

    const stopped = try stopDaemonLifecycleLocked(allocator, codex_home);
    try writeDaemonLifecycleOutput(allocator, codex_home, if (stopped) "stopped" else "notRunning", .{
        .backend = if (stopped) "pid" else null,
    });
}

fn stopDaemonLifecycleLocked(allocator: std.mem.Allocator, codex_home: []const u8) !bool {
    const stopped = try stopManagedDaemonIfRunning(allocator, codex_home);
    if (!stopped) {
        try ensureDaemonNoManagedServerRunning(allocator, codex_home);
    }
    return stopped;
}

fn ensureDaemonNoManagedServerRunning(allocator: std.mem.Allocator, codex_home: []const u8) !void {
    try ensureDaemonScaffolding(allocator, codex_home, true);
    try validateDaemonSettings(allocator, codex_home);
    const probe = try probeDaemonSocket(allocator, codex_home);
    defer probe.deinit(allocator);
    switch (probe) {
        .running => return failDaemonUnmanagedRunning(),
        .unavailable => {},
    }
}

fn runDaemonVersion(allocator: std.mem.Allocator, codex_home: []const u8) !void {
    try validateDaemonSettings(allocator, codex_home);
    const probe = try probeDaemonSocket(allocator, codex_home);
    defer probe.deinit(allocator);
    switch (probe) {
        .running => |app_server_version| {
            const backend = try managedDaemonBackend(allocator, codex_home);
            try writeDaemonLifecycleOutput(allocator, codex_home, "running", .{
                .backend = backend,
                .app_server_version = app_server_version,
            });
            return;
        },
        .unavailable => |cause| try failDaemonSocketUnavailable(allocator, codex_home, cause),
    }
}

fn runDaemonStart(allocator: std.mem.Allocator, codex_home: []const u8, child_global_args: []const []const u8) !void {
    try ensureDaemonScaffolding(allocator, codex_home, true);
    var operation_lock = try acquireDaemonOperationLock(allocator, codex_home);
    defer operation_lock.release();

    try validateDaemonSettings(allocator, codex_home);
    const probe = try probeDaemonSocket(allocator, codex_home);
    defer probe.deinit(allocator);
    switch (probe) {
        .running => |app_server_version| {
            const backend = try managedDaemonBackend(allocator, codex_home);
            try writeDaemonLifecycleOutput(allocator, codex_home, "alreadyRunning", .{
                .backend = backend,
                .app_server_version = app_server_version,
            });
            return;
        },
        .unavailable => {},
    }
    const started = try startManagedDaemon(allocator, codex_home, child_global_args);
    defer allocator.free(started.app_server_version);
    try writeDaemonLifecycleOutput(allocator, codex_home, if (started.started) "started" else "alreadyRunning", .{
        .backend = "pid",
        .pid = if (started.started) started.pid else null,
        .app_server_version = started.app_server_version,
    });
}

fn runDaemonRestart(allocator: std.mem.Allocator, codex_home: []const u8, child_global_args: []const []const u8) !void {
    try ensureDaemonScaffolding(allocator, codex_home, true);
    var operation_lock = try acquireDaemonOperationLock(allocator, codex_home);
    defer operation_lock.release();

    try validateDaemonSettings(allocator, codex_home);
    const managed_running = try managedDaemonBackend(allocator, codex_home) != null;
    if (managed_running) {
        const managed_path = try ensureManagedCodexPath(allocator, codex_home);
        defer allocator.free(managed_path);
    }
    const stopped = try stopManagedDaemonIfRunning(allocator, codex_home);
    if (!stopped) {
        const probe = try probeDaemonSocket(allocator, codex_home);
        defer probe.deinit(allocator);
        switch (probe) {
            .running => return failDaemonUnmanagedRunning(),
            .unavailable => {},
        }
    }
    const started = try startManagedDaemon(allocator, codex_home, child_global_args);
    defer allocator.free(started.app_server_version);
    try writeDaemonLifecycleOutput(allocator, codex_home, "restarted", .{
        .backend = "pid",
        .pid = started.pid,
        .app_server_version = started.app_server_version,
    });
}

fn writeDaemonLifecycleOutput(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    status: []const u8,
    options: DaemonLifecycleOutputOptions,
) !void {
    const output = try renderDaemonLifecycleOutput(allocator, codex_home, status, options);
    defer allocator.free(output);
    try writeStdoutLine(output);
}

fn renderDaemonLifecycleOutput(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    status: []const u8,
    options: DaemonLifecycleOutputOptions,
) ![]const u8 {
    const managed_path = try managedCodexPath(allocator, codex_home);
    defer allocator.free(managed_path);
    const managed_version = try managedCodexVersionBestEffort(allocator, managed_path);
    defer if (managed_version) |version| allocator.free(version);
    const socket_path = try daemonSocketPath(allocator, codex_home);
    defer allocator.free(socket_path);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"status\":");
    try appendJsonString(allocator, &out, status);
    if (options.backend) |backend| {
        try out.appendSlice(allocator, ",\"backend\":");
        try appendJsonString(allocator, &out, backend);
    }
    if (options.pid) |pid| {
        const pid_text = try std.fmt.allocPrint(allocator, "{d}", .{pid});
        defer allocator.free(pid_text);
        try out.appendSlice(allocator, ",\"pid\":");
        try out.appendSlice(allocator, pid_text);
    }
    try out.appendSlice(allocator, ",\"managedCodexPath\":");
    try appendJsonString(allocator, &out, managed_path);
    try out.appendSlice(allocator, ",\"managedCodexVersion\":");
    if (managed_version) |version| {
        try appendJsonString(allocator, &out, version);
    } else {
        try out.appendSlice(allocator, "null");
    }
    try out.appendSlice(allocator, ",\"socketPath\":");
    try appendJsonString(allocator, &out, socket_path);
    try out.appendSlice(allocator, ",\"cliVersion\":");
    try appendJsonString(allocator, &out, CLI_VERSION);
    if (options.app_server_version) |version| {
        try out.appendSlice(allocator, ",\"appServerVersion\":");
        try appendJsonString(allocator, &out, version);
    }
    try out.appendSlice(allocator, "}");
    return try out.toOwnedSlice(allocator);
}

fn runDaemonSetRemoteControl(allocator: std.mem.Allocator, codex_home: []const u8, enabled: bool, child_global_args: []const []const u8) !void {
    try ensureDaemonScaffolding(allocator, codex_home, true);
    var operation_lock = try acquireDaemonOperationLock(allocator, codex_home);
    defer operation_lock.release();

    const settings_path = try daemonSettingsPath(allocator, codex_home);
    defer allocator.free(settings_path);
    const previous = try readDaemonRemoteControlEnabled(allocator, settings_path);
    const managed_running = try managedDaemonBackend(allocator, codex_home) != null;
    const probe = try probeDaemonSocket(allocator, codex_home);
    defer probe.deinit(allocator);
    switch (probe) {
        .running => {
            if (!managed_running) {
                return failDaemonUnmanagedRunning();
            }
        },
        .unavailable => {},
    }

    const status = if (enabled)
        if (previous) "alreadyEnabled" else "enabled"
    else if (previous) "disabled" else "alreadyDisabled";

    if (previous == enabled) {
        const app_server_version = if (managed_running)
            try waitForDaemonReady(allocator, codex_home)
        else
            null;
        defer if (app_server_version) |version| allocator.free(version);
        try writeDaemonRemoteControlOutput(allocator, codex_home, status, enabled, .{
            .backend = if (managed_running) "pid" else null,
            .app_server_version = app_server_version,
        });
        return;
    }

    if (managed_running) {
        const managed_path = try ensureManagedCodexPath(allocator, codex_home);
        defer allocator.free(managed_path);
    }
    var preserved_child_global_args: ?[][]const u8 = null;
    defer if (preserved_child_global_args) |args| freeStringSlice(allocator, args);
    const restart_child_global_args = if (managed_running and child_global_args.len == 0) args: {
        preserved_child_global_args = try activeManagedDaemonChildGlobalArgs(allocator, codex_home);
        break :args preserved_child_global_args orelse child_global_args;
    } else child_global_args;
    try writeDaemonRemoteControlSettings(settings_path, enabled);

    if (managed_running) {
        _ = try stopManagedDaemonIfRunning(allocator, codex_home);
        const started = try startManagedDaemon(allocator, codex_home, restart_child_global_args);
        defer allocator.free(started.app_server_version);
        try writeDaemonRemoteControlOutput(allocator, codex_home, status, enabled, .{
            .backend = "pid",
            .app_server_version = started.app_server_version,
        });
        return;
    }

    try writeDaemonRemoteControlOutput(allocator, codex_home, status, enabled, .{});
}

fn writeDaemonRemoteControlOutput(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    status: []const u8,
    enabled: bool,
    options: DaemonRemoteControlOutputOptions,
) !void {
    const socket_path = try daemonSocketPath(allocator, codex_home);
    defer allocator.free(socket_path);

    var out = std.ArrayList(u8).empty;
    defer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"status\":");
    try appendJsonString(allocator, &out, status);
    if (options.backend) |backend| {
        try out.appendSlice(allocator, ",\"backend\":");
        try appendJsonString(allocator, &out, backend);
    }
    try out.appendSlice(allocator, ",\"remoteControlEnabled\":");
    try out.appendSlice(allocator, if (enabled) "true" else "false");
    try out.appendSlice(allocator, ",\"socketPath\":");
    try appendJsonString(allocator, &out, socket_path);
    try out.appendSlice(allocator, ",\"cliVersion\":");
    try appendJsonString(allocator, &out, CLI_VERSION);
    if (options.app_server_version) |version| {
        try out.appendSlice(allocator, ",\"appServerVersion\":");
        try appendJsonString(allocator, &out, version);
    }
    try out.appendSlice(allocator, "}");
    try writeStdoutLine(out.items);
}

fn ensureRemoteControlDaemonStartedLocked(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    child_global_args: []const []const u8,
) ![]const u8 {
    try validateDaemonSettings(allocator, codex_home);
    const managed_path = try ensureManagedCodexPath(allocator, codex_home);
    defer allocator.free(managed_path);

    const settings_path = try daemonSettingsPath(allocator, codex_home);
    defer allocator.free(settings_path);
    const previous_remote_control_enabled = try readDaemonRemoteControlEnabled(allocator, settings_path);
    const managed_running = try managedDaemonBackend(allocator, codex_home) != null;
    var preserved_child_global_args: ?[][]const u8 = null;
    defer if (preserved_child_global_args) |args| freeStringSlice(allocator, args);
    const restart_child_global_args = if (managed_running and child_global_args.len == 0) args: {
        preserved_child_global_args = try activeManagedDaemonChildGlobalArgs(allocator, codex_home);
        break :args preserved_child_global_args orelse child_global_args;
    } else child_global_args;

    if (!try managedUpdaterRunning(allocator, codex_home)) {
        const app_server_version = try bootstrapManagedDaemonLocked(allocator, codex_home, true, restart_child_global_args);
        defer allocator.free(app_server_version);
        return try renderDaemonBootstrapOutput(allocator, codex_home, true, app_server_version);
    }

    const probe = try probeDaemonSocket(allocator, codex_home);
    defer probe.deinit(allocator);
    switch (probe) {
        .running => {
            if (!managed_running) return failDaemonUnmanagedRunning();
        },
        .unavailable => {},
    }

    if (!previous_remote_control_enabled) {
        try writeDaemonRemoteControlSettings(settings_path, true);
        if (managed_running) {
            _ = try stopManagedDaemonIfRunning(allocator, codex_home);
            const started = try startManagedDaemon(allocator, codex_home, restart_child_global_args);
            defer allocator.free(started.app_server_version);
            return try renderDaemonLifecycleOutput(allocator, codex_home, "alreadyRunning", .{
                .backend = "pid",
                .app_server_version = started.app_server_version,
            });
        }
    }

    const started = try startManagedDaemon(allocator, codex_home, restart_child_global_args);
    defer allocator.free(started.app_server_version);
    return try renderDaemonLifecycleOutput(allocator, codex_home, if (started.started) "started" else "alreadyRunning", .{
        .backend = "pid",
        .pid = if (started.started) started.pid else null,
        .app_server_version = started.app_server_version,
    });
}

fn enableDaemonRemoteControl(allocator: std.mem.Allocator, codex_home: []const u8) !RemoteControlReadyStatus {
    const socket_path = try daemonSocketPath(allocator, codex_home);
    defer allocator.free(socket_path);

    const io = std.Io.Threaded.global_single_threaded.io();
    const connected = try connectDaemonUnixStream(allocator, socket_path);
    var stream = switch (connected) {
        .unavailable => |cause| {
            defer allocator.free(cause);
            try failDaemonSocketUnavailable(allocator, codex_home, cause);
            unreachable;
        },
        .stream => |value| value,
    };
    defer stream.close(io);

    var input_buffer: [16 * 1024]u8 = undefined;
    var output_buffer: [4096]u8 = undefined;
    var reader = stream.reader(io, &input_buffer);
    var writer = stream.writer(io, &output_buffer);
    try writer.interface.writeAll(
        "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{\"clientInfo\":{\"name\":\"codex_remote_control_daemon\",\"title\":\"Codex Remote Control Daemon\",\"version\":\"0.0.1\"},\"capabilities\":{\"experimentalApi\":true}}}\n",
    );
    try writer.interface.flush();

    var deadline_ms = appServerAwakeDeadlineMs(2 * std.time.ms_per_s);
    while (true) {
        const line = try readDaemonProbeLine(allocator, &reader.interface, stream.socket.handle, deadline_ms) orelse return error.AppServerDaemonCommandFailed;
        defer allocator.free(line);
        if (try jsonRpcResponseMatchesId(allocator, line, 1)) break;
    }

    try writer.interface.writeAll("{\"jsonrpc\":\"2.0\",\"method\":\"initialized\"}\n");
    try writer.interface.writeAll("{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"remoteControl/enable\",\"params\":null}\n");
    try writer.interface.flush();

    deadline_ms = appServerAwakeDeadlineMs(2 * std.time.ms_per_s);
    while (true) {
        const line = try readDaemonProbeLine(allocator, &reader.interface, stream.socket.handle, deadline_ms) orelse return error.AppServerDaemonCommandFailed;
        defer allocator.free(line);
        if (try remoteControlReadyStatusFromResponse(allocator, line, 2)) |ready| {
            return try waitForRemoteControlReadyStatus(allocator, &reader.interface, stream.socket.handle, ready);
        }
    }
}

fn jsonRpcResponseMatchesId(allocator: std.mem.Allocator, line: []const u8, id: i64) !bool {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, line, .{}) catch return false;
    defer parsed.deinit();
    if (parsed.value != .object) return false;
    const object = parsed.value.object;
    const id_value = object.get("id") orelse return false;
    if (!jsonIdMatchesInteger(id_value, id)) return false;
    return object.get("result") != null or object.get("error") != null;
}

fn remoteControlReadyStatusFromResponse(allocator: std.mem.Allocator, line: []const u8, id: i64) !?RemoteControlReadyStatus {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, line, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    const id_value = object.get("id") orelse return null;
    if (!jsonIdMatchesInteger(id_value, id)) return null;
    if (object.get("error")) |error_value| {
        const message = if (error_value == .object)
            requiredJsonStringField(error_value.object, "message") orelse "remoteControl/enable failed"
        else
            "remoteControl/enable failed";
        const rendered = try std.fmt.allocPrint(allocator, "Error: remoteControl/enable failed: {s}\n", .{message});
        defer allocator.free(rendered);
        try cli_utils.writeStderr(rendered);
        return error.AppServerDaemonCommandFailed;
    }
    const result = object.get("result") orelse return null;
    if (result != .object) return error.InvalidRemoteControlStatus;
    return try parseRemoteControlReadyStatus(allocator, result.object, false);
}

fn waitForRemoteControlReadyStatus(
    allocator: std.mem.Allocator,
    reader: *std.Io.Reader,
    fd: std.posix.fd_t,
    initial: RemoteControlReadyStatus,
) !RemoteControlReadyStatus {
    var latest = initial;
    errdefer latest.deinit(allocator);
    if (!std.mem.eql(u8, latest.status, "connecting")) return latest;

    const deadline_ms = appServerAwakeDeadlineMs(REMOTE_CONTROL_READY_TIMEOUT_MS);
    while (true) {
        const line = readDaemonProbeLine(allocator, reader, fd, deadline_ms) catch |err| switch (err) {
            error.AppServerDaemonProbeTimedOut => {
                latest.timed_out = true;
                return latest;
            },
            else => return err,
        } orelse return error.AppServerDaemonCommandFailed;
        defer allocator.free(line);
        if (try remoteControlReadyStatusFromNotification(allocator, line)) |ready| {
            latest.deinit(allocator);
            latest = ready;
            if (!std.mem.eql(u8, latest.status, "connecting")) return latest;
        }
    }
}

fn remoteControlReadyStatusFromNotification(allocator: std.mem.Allocator, line: []const u8) !?RemoteControlReadyStatus {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, line, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    const method = requiredJsonStringField(object, "method") orelse return null;
    if (!std.mem.eql(u8, method, "remoteControl/status/changed")) return null;
    const params = object.get("params") orelse return null;
    if (params != .object) return null;
    return parseRemoteControlReadyStatus(allocator, params.object, false) catch null;
}

fn parseRemoteControlReadyStatus(
    allocator: std.mem.Allocator,
    object: std.json.ObjectMap,
    timed_out: bool,
) !RemoteControlReadyStatus {
    const status = requiredJsonStringField(object, "status") orelse return error.InvalidRemoteControlStatus;
    const server_name = requiredJsonStringField(object, "serverName") orelse return error.InvalidRemoteControlStatus;
    const environment_id_value = object.get("environmentId");
    const environment_id = if (environment_id_value) |value| switch (value) {
        .null => null,
        .string => |string| try allocator.dupe(u8, string),
        else => return error.InvalidRemoteControlStatus,
    } else null;
    errdefer if (environment_id) |value| allocator.free(value);
    const owned_status = try allocator.dupe(u8, status);
    errdefer allocator.free(owned_status);
    const owned_server_name = try allocator.dupe(u8, server_name);
    errdefer allocator.free(owned_server_name);

    return .{
        .status = owned_status,
        .server_name = owned_server_name,
        .environment_id = environment_id,
        .timed_out = timed_out,
    };
}

fn jsonIdMatchesInteger(value: std.json.Value, id: i64) bool {
    return switch (value) {
        .integer => |integer| integer == id,
        .number_string => |number| (std.fmt.parseInt(i64, number, 10) catch return false) == id,
        .string => |string| (std.fmt.parseInt(i64, string, 10) catch return false) == id,
        else => false,
    };
}

fn writeRemoteControlStartOutput(
    allocator: std.mem.Allocator,
    ready: RemoteControlReadyStatus,
    daemon_output_json: []const u8,
    json: bool,
) !void {
    try ensureRemoteControlStartable(allocator, ready);
    if (json) {
        const payload = try renderRemoteControlStartJson(allocator, ready, daemon_output_json);
        defer allocator.free(payload);
        try writeStdoutLine(payload);
        return;
    }

    const message = try remoteControlStartHumanMessage(allocator, ready);
    defer allocator.free(message);
    try cli_utils.writeStdout(message);
    try cli_utils.writeStdout("\n");
    try writeDaemonAppServerHumanLines(allocator, daemon_output_json);
}

fn ensureRemoteControlStartable(allocator: std.mem.Allocator, ready: RemoteControlReadyStatus) !void {
    if (std.mem.eql(u8, ready.status, "connected") or std.mem.eql(u8, ready.status, "connecting")) return;
    const message = if (std.mem.eql(u8, ready.status, "errored"))
        try std.fmt.allocPrint(allocator, "Error: Remote control is enabled on {s} but the connection is errored.\n", .{ready.server_name})
    else if (std.mem.eql(u8, ready.status, "disabled"))
        try std.fmt.allocPrint(allocator, "Error: Remote control is disabled on {s}.\n", .{ready.server_name})
    else
        try std.fmt.allocPrint(allocator, "Error: Remote control reported unsupported status {s} on {s}.\n", .{ ready.status, ready.server_name });
    defer allocator.free(message);
    try cli_utils.writeStderr(message);
    return error.AppServerDaemonCommandFailed;
}

fn remoteControlStartHumanMessage(allocator: std.mem.Allocator, ready: RemoteControlReadyStatus) ![]const u8 {
    if (std.mem.eql(u8, ready.status, "connected")) {
        return std.fmt.allocPrint(allocator, "This machine is available for remote control as {s}.", .{ready.server_name});
    }
    return std.fmt.allocPrint(allocator, "Remote control is enabled on {s} and still connecting.", .{ready.server_name});
}

fn renderRemoteControlStartJson(
    allocator: std.mem.Allocator,
    ready: RemoteControlReadyStatus,
    daemon_output_json: []const u8,
) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"mode\":\"daemon\",\"status\":");
    try appendJsonString(allocator, &out, ready.status);
    try out.appendSlice(allocator, ",\"serverName\":");
    try appendJsonString(allocator, &out, ready.server_name);
    try out.appendSlice(allocator, ",\"environmentId\":");
    try appendOptionalJsonString(allocator, &out, ready.environment_id);
    try out.appendSlice(allocator, ",\"timedOut\":");
    try out.appendSlice(allocator, if (ready.timed_out) "true" else "false");
    try out.appendSlice(allocator, ",\"daemon\":");
    try out.appendSlice(allocator, daemon_output_json);
    try out.appendSlice(allocator, "}");
    return try out.toOwnedSlice(allocator);
}

fn writeDaemonAppServerHumanLines(allocator: std.mem.Allocator, daemon_output_json: []const u8) !void {
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, daemon_output_json, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRemoteControlStatus;
    const object = parsed.value.object;
    const path = requiredJsonStringField(object, "managedCodexPath") orelse return error.InvalidRemoteControlStatus;
    const version_value = object.get("managedCodexVersion");
    const version = if (version_value) |value| switch (value) {
        .string => |string| string,
        .null => "unknown",
        else => return error.InvalidRemoteControlStatus,
    } else "unknown";

    const message = try std.fmt.allocPrint(
        allocator,
        "Daemon used app-server:\n  path: {s}\n  version: {s}\n",
        .{ path, version },
    );
    defer allocator.free(message);
    try cli_utils.writeStdout(message);
}

fn ensureManagedCodexPath(allocator: std.mem.Allocator, codex_home: []const u8) ![]const u8 {
    const managed_path = try managedCodexPath(allocator, codex_home);
    errdefer allocator.free(managed_path);
    if (try managedCodexPathIsFile(allocator, managed_path)) return managed_path;

    const message = try std.fmt.allocPrint(
        allocator,
        \\Error: managed standalone Codex install not found at {s}
        \\
        \\This command requires the standalone install managed by the Codex installer, because the daemon starts and updates app-server from that fixed path.
        \\
        \\Install it with:
        \\  curl -fsSL https://chatgpt.com/codex/install.sh | sh
        \\
        \\Then rerun the command you just tried.
        \\
    ,
        .{managed_path},
    );
    defer allocator.free(message);
    try cli_utils.writeStderr(message);
    return error.AppServerDaemonCommandFailed;
}

fn startManagedDaemon(allocator: std.mem.Allocator, codex_home: []const u8, child_global_args: []const []const u8) !DaemonStartOutput {
    try ensureDaemonScaffolding(allocator, codex_home, true);

    var pid_lock = try acquireDaemonPidLock(allocator, codex_home);
    defer pid_lock.release();

    const managed_path = try ensureManagedCodexPath(allocator, codex_home);
    defer allocator.free(managed_path);

    const pid_path = try daemonPidPath(allocator, codex_home);
    defer allocator.free(pid_path);
    if (try activeManagedPid(allocator, codex_home, pid_path, .app_server)) |pid| {
        const version = try waitForDaemonReady(allocator, codex_home);
        return .{ .pid = pid, .app_server_version = version, .started = false };
    }
    try removeFileIfExists(pid_path);

    const settings_path = try daemonSettingsPath(allocator, codex_home);
    defer allocator.free(settings_path);
    const remote_control_enabled = try readDaemonRemoteControlEnabled(allocator, settings_path);

    const stderr_path = try daemonStderrLogPath(allocator, codex_home);
    defer allocator.free(stderr_path);
    var io_instance: std.Io.Threaded = .init(allocator, .{});
    defer io_instance.deinit();
    const io = io_instance.io();
    var stderr_file = try std.Io.Dir.cwd().createFile(io, stderr_path, .{});
    defer stderr_file.close(io);
    var child_env = try daemonChildEnvironment(allocator, codex_home);
    defer child_env.deinit();

    var argv = std.ArrayList([]const u8).empty;
    defer argv.deinit(allocator);
    try argv.append(allocator, managed_path);
    try argv.appendSlice(allocator, child_global_args);
    try argv.append(allocator, "app-server");
    if (remote_control_enabled) try argv.append(allocator, "--remote-control");
    try argv.append(allocator, "--listen");
    try argv.append(allocator, "unix://");

    var child = std.process.spawn(io, .{
        .argv = argv.items,
        .stdin = .ignore,
        .stdout = .ignore,
        .stderr = .{ .file = stderr_file },
        .environ_map = &child_env,
        .pgid = 0,
    }) catch |err| {
        try failManagedDaemonSpawn(allocator, managed_path, err);
        unreachable;
    };
    const pid = child.id orelse return error.AppServerDaemonCommandFailed;
    child.id = null;
    var keep_child = false;
    errdefer if (!keep_child) {
        terminatePid(pid);
        removeFileIfExists(pid_path) catch {};
    };

    const process_start_time = try processStartTime(allocator, pid) orelse {
        try cli_utils.writeStderr("Error: failed to record managed app-server process identity\n");
        return error.AppServerDaemonCommandFailed;
    };
    defer allocator.free(process_start_time);
    try writeDaemonPidRecord(allocator, pid_path, pid, process_start_time, child_global_args);

    const version = try waitForDaemonReady(allocator, codex_home);
    keep_child = true;
    return .{ .pid = pid, .app_server_version = version, .started = true };
}

fn stopManagedDaemonIfRunning(allocator: std.mem.Allocator, codex_home: []const u8) !bool {
    const pid_path = try daemonPidPath(allocator, codex_home);
    defer allocator.free(pid_path);
    var record = (try activeManagedPidRecord(allocator, codex_home, pid_path, .app_server)) orelse {
        try removeFileIfExists(pid_path);
        return false;
    };
    defer record.deinit(allocator);
    const pid = record.pid;

    terminatePid(pid);
    const deadline_ms = appServerAwakeDeadlineMs(10 * std.time.ms_per_s);
    while (try processMatchesManagedProcess(allocator, codex_home, record, .app_server)) {
        if (remainingAppServerAwakeMillis(deadline_ms) == null) {
            forceTerminatePid(pid);
            break;
        }
        std.Io.sleep(
            std.Io.Threaded.global_single_threaded.io(),
            .{ .nanoseconds = 50 * std.time.ns_per_ms },
            .awake,
        ) catch {};
    }
    try removeFileIfExists(pid_path);
    return true;
}

fn startManagedUpdater(allocator: std.mem.Allocator, codex_home: []const u8) !DaemonUpdaterStartOutput {
    try ensureDaemonScaffolding(allocator, codex_home, true);
    try ensureDaemonUpdaterPidLock(allocator, codex_home);

    var pid_lock = try acquireDaemonUpdaterPidLock(allocator, codex_home);
    defer pid_lock.release();

    const managed_path = try ensureManagedCodexPath(allocator, codex_home);
    defer allocator.free(managed_path);

    const pid_path = try daemonUpdaterPidPath(allocator, codex_home);
    defer allocator.free(pid_path);
    if (try activeManagedPid(allocator, codex_home, pid_path, .updater)) |pid| {
        return .{ .pid = pid, .started = false };
    }
    try removeFileIfExists(pid_path);

    const stderr_path = try daemonUpdaterStderrLogPath(allocator, codex_home);
    defer allocator.free(stderr_path);
    var io_instance: std.Io.Threaded = .init(allocator, .{});
    defer io_instance.deinit();
    const io = io_instance.io();
    var stderr_file = try std.Io.Dir.cwd().createFile(io, stderr_path, .{});
    defer stderr_file.close(io);
    var child_env = try daemonChildEnvironment(allocator, codex_home);
    defer child_env.deinit();

    var child = std.process.spawn(io, .{
        .argv = &.{ managed_path, "app-server", "daemon", "pid-update-loop" },
        .stdin = .ignore,
        .stdout = .ignore,
        .stderr = .{ .file = stderr_file },
        .environ_map = &child_env,
        .pgid = 0,
    }) catch |err| {
        try failManagedDaemonSpawn(allocator, managed_path, err);
        unreachable;
    };
    const pid = child.id orelse return error.AppServerDaemonCommandFailed;
    child.id = null;
    var keep_child = false;
    errdefer if (!keep_child) {
        terminatePid(pid);
        removeFileIfExists(pid_path) catch {};
    };

    const process_start_time = try processStartTime(allocator, pid) orelse {
        try cli_utils.writeStderr("Error: failed to record managed app-server updater process identity\n");
        return error.AppServerDaemonCommandFailed;
    };
    defer allocator.free(process_start_time);
    try writeDaemonPidRecord(allocator, pid_path, pid, process_start_time, &.{});

    keep_child = true;
    return .{ .pid = pid, .started = true };
}

fn stopManagedUpdaterIfRunning(allocator: std.mem.Allocator, codex_home: []const u8) !bool {
    try ensureDaemonUpdaterPidLock(allocator, codex_home);
    var pid_lock = try acquireDaemonUpdaterPidLock(allocator, codex_home);
    defer pid_lock.release();

    const pid_path = try daemonUpdaterPidPath(allocator, codex_home);
    defer allocator.free(pid_path);
    var record = (try activeManagedPidRecord(allocator, codex_home, pid_path, .updater)) orelse {
        try removeFileIfExists(pid_path);
        return false;
    };
    defer record.deinit(allocator);
    const pid = record.pid;

    terminatePid(pid);
    const deadline_ms = appServerAwakeDeadlineMs(10 * std.time.ms_per_s);
    while (try processMatchesManagedProcess(allocator, codex_home, record, .updater)) {
        if (remainingAppServerAwakeMillis(deadline_ms) == null) {
            forceTerminatePid(pid);
            break;
        }
        std.Io.sleep(
            std.Io.Threaded.global_single_threaded.io(),
