fn acquireDaemonFileLock(path: []const u8) !DaemonFileLock {
    const io = std.Io.Threaded.global_single_threaded.io();
    const file = try std.Io.Dir.cwd().openFile(io, path, .{
        .mode = .write_only,
        .lock = .exclusive,
        .lock_nonblocking = false,
    });
    return .{ .file = file };
}

fn daemonChildEnvironment(allocator: std.mem.Allocator, codex_home: []const u8) !std.process.Environ.Map {
    var result = std.process.Environ.Map.init(allocator);
    errdefer result.deinit();

    var index: usize = 0;
    while (std.c.environ[index]) |entry_ptr| : (index += 1) {
        const entry = std.mem.span(entry_ptr);
        const eq = std.mem.indexOfScalar(u8, entry, '=') orelse continue;
        const key = entry[0..eq];
        if (!std.process.Environ.Map.validateKeyForPut(key)) continue;
        try result.put(key, entry[eq + 1 ..]);
    }
    try result.put("CODEX_HOME", codex_home);
    return result;
}

fn waitForDaemonReady(allocator: std.mem.Allocator, codex_home: []const u8) ![]const u8 {
    const deadline_ms = appServerAwakeDeadlineMs(10 * std.time.ms_per_s);
    while (true) {
        const probe = try probeDaemonSocket(allocator, codex_home);
        switch (probe) {
            .running => |version| return version,
            .unavailable => |cause| allocator.free(cause),
        }
        if (remainingAppServerAwakeMillis(deadline_ms) == null) {
            try failDaemonNotReady(allocator, codex_home);
        }
        std.Io.sleep(
            std.Io.Threaded.global_single_threaded.io(),
            .{ .nanoseconds = 50 * std.time.ns_per_ms },
            .awake,
        ) catch {};
    }
}

fn failManagedDaemonSpawn(allocator: std.mem.Allocator, managed_path: []const u8, err: anyerror) !void {
    const message = std.fmt.allocPrint(
        allocator,
        "Error: failed to spawn detached app-server process using {s}\n\nCaused by:\n    {s}\n",
        .{ managed_path, @errorName(err) },
    ) catch {
        try cli_utils.writeStderr("Error: failed to spawn detached app-server process\n");
        return error.AppServerDaemonCommandFailed;
    };
    defer allocator.free(message);
    try cli_utils.writeStderr(message);
    return error.AppServerDaemonCommandFailed;
}

fn failDaemonNotReady(allocator: std.mem.Allocator, codex_home: []const u8) !void {
    const socket_path = daemonSocketPath(allocator, codex_home) catch {
        try cli_utils.writeStderr("Error: app server did not become ready\n");
        return error.AppServerDaemonCommandFailed;
    };
    defer allocator.free(socket_path);
    const message = std.fmt.allocPrint(
        allocator,
        "Error: app server did not become ready on {s}\n",
        .{socket_path},
    ) catch {
        try cli_utils.writeStderr("Error: app server did not become ready\n");
        return error.AppServerDaemonCommandFailed;
    };
    defer allocator.free(message);
    try cli_utils.writeStderr(message);
    return error.AppServerDaemonCommandFailed;
}

fn failDaemonUnmanagedRunning() error{AppServerDaemonCommandFailed} {
    std.debug.print(
        \\Error: app server is running but is not managed by codex app-server daemon
        \\
    , .{});
    return error.AppServerDaemonCommandFailed;
}

fn failDaemonSocketUnavailable(allocator: std.mem.Allocator, codex_home: []const u8, cause: []const u8) !void {
    const socket_path = try daemonSocketPath(allocator, codex_home);
    defer allocator.free(socket_path);
    const message = try std.fmt.allocPrint(
        allocator,
        \\Error: failed to connect to {s}
        \\
        \\Caused by:
        \\    {s}
        \\
    ,
        .{ socket_path, cause },
    );
    defer allocator.free(message);
    try cli_utils.writeStderr(message);
    return error.AppServerDaemonCommandFailed;
}

fn resolveDaemonCodexHome(allocator: std.mem.Allocator) ![]const u8 {
    if (try env.getOwned(allocator, "CODEX_HOME")) |raw| {
        defer allocator.free(raw);
        if (raw.len == 0) return defaultDaemonCodexHome(allocator);

        const stat = statPathFollow(allocator, raw) catch |err| switch (err) {
            error.NotDir => return failDaemonCodexHomeResolve(
                allocator,
                "failed to read CODEX_HOME \"{s}\": Not a directory",
                .{raw},
            ),
            else => return err,
        };
        const resolved_stat = stat orelse return failDaemonCodexHomeResolve(
            allocator,
            "CODEX_HOME points to \"{s}\", but that path does not exist",
            .{raw},
        );
        if (!std.c.S.ISDIR(@intCast(resolved_stat.mode))) {
            return failDaemonCodexHomeResolve(
                allocator,
                "CODEX_HOME points to \"{s}\", but that path is not a directory",
                .{raw},
            );
        }

        return realPathFileAllocPlain(allocator, raw) catch |err| switch (err) {
            else => return err,
        };
    }

    return defaultDaemonCodexHome(allocator);
}

fn defaultDaemonCodexHome(allocator: std.mem.Allocator) ![]const u8 {
    const home = (try env.getOwned(allocator, "HOME")) orelse return error.MissingHome;
    defer allocator.free(home);
    return std.fs.path.join(allocator, &.{ home, ".codex" });
}

fn failDaemonCodexHomeResolve(
    allocator: std.mem.Allocator,
    comptime reason_fmt: []const u8,
    args: anytype,
) ![]const u8 {
    const reason = try std.fmt.allocPrint(allocator, reason_fmt, args);
    defer allocator.free(reason);

    const message = try std.fmt.allocPrint(
        allocator,
        \\Error: failed to resolve CODEX_HOME
        \\
        \\Caused by:
        \\    {s}
        \\
    ,
        .{reason},
    );
    defer allocator.free(message);
    try cli_utils.writeStderr(message);
    return error.AppServerDaemonCommandFailed;
}

