fn validateDaemonSettings(allocator: std.mem.Allocator, codex_home: []const u8) !void {
    const settings_path = try daemonSettingsPath(allocator, codex_home);
    defer allocator.free(settings_path);
    _ = try readDaemonRemoteControlEnabled(allocator, settings_path);
}

fn daemonSettingsParseCause(allocator: std.mem.Allocator, err: anyerror, diagnostics: std.json.Diagnostics) ![]const u8 {
    return switch (err) {
        error.MissingField => std.fmt.allocPrint(
            allocator,
            "missing field `remoteControlEnabled` at line {d} column {d}",
            .{ diagnostics.getLine(), diagnostics.getColumn() },
        ),
        error.SyntaxError => std.fmt.allocPrint(
            allocator,
            "syntax error at line {d} column {d}",
            .{ diagnostics.getLine(), diagnostics.getColumn() },
        ),
        error.UnexpectedEndOfInput => std.fmt.allocPrint(
            allocator,
            "unexpected end of input at line {d} column {d}",
            .{ diagnostics.getLine(), diagnostics.getColumn() },
        ),
        else => std.fmt.allocPrint(
            allocator,
            "{s} at line {d} column {d}",
            .{ @errorName(err), diagnostics.getLine(), diagnostics.getColumn() },
        ),
    };
}

fn readDaemonRemoteControlEnabled(allocator: std.mem.Allocator, settings_path: []const u8) !bool {
    const bytes = std.Io.Dir.cwd().readFileAlloc(
        std.Io.Threaded.global_single_threaded.io(),
        settings_path,
        allocator,
        .limited(4096),
    ) catch |err| switch (err) {
        error.FileNotFound => {
            return false;
        },
        else => return err,
    };
    defer allocator.free(bytes);

    var scanner = std.json.Scanner.initCompleteInput(allocator, bytes);
    defer scanner.deinit();
    var diagnostics = std.json.Diagnostics{};
    scanner.enableDiagnostics(&diagnostics);

    var parsed = std.json.parseFromTokenSource(
        DaemonRemoteControlSettings,
        allocator,
        &scanner,
        .{ .ignore_unknown_fields = true },
    ) catch |err| {
        const cause = try daemonSettingsParseCause(allocator, err, diagnostics);
        defer allocator.free(cause);
        return failDaemonSettingsParse(allocator, settings_path, cause);
    };
    defer parsed.deinit();
    return parsed.value.remoteControlEnabled;
}

fn probeDaemonSocket(allocator: std.mem.Allocator, codex_home: []const u8) !DaemonSocketProbe {
    const socket_path = try daemonSocketPath(allocator, codex_home);
    defer allocator.free(socket_path);

    const io = std.Io.Threaded.global_single_threaded.io();
    const connected = try connectDaemonUnixStream(allocator, socket_path);
    var stream = switch (connected) {
        .unavailable => |cause| return .{ .unavailable = cause },
        .stream => |value| value,
    };
    defer stream.close(io);

    var input_buffer: [16 * 1024]u8 = undefined;
    var output_buffer: [4096]u8 = undefined;
    var reader = stream.reader(io, &input_buffer);
    var writer = stream.writer(io, &output_buffer);
    writer.interface.writeAll(
        "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{\"clientInfo\":{\"name\":\"codex_app_server_daemon\",\"title\":\"Codex App Server Daemon\",\"version\":\"0.0.1\"}}}\n",
    ) catch |err| return .{ .unavailable = try daemonProbeErrorCause(allocator, "failed to send initialize request", err) };
    writer.interface.flush() catch |err| return .{ .unavailable = try daemonProbeErrorCause(allocator, "failed to send initialize request", err) };

    const deadline_ms = appServerAwakeDeadlineMs(2 * std.time.ms_per_s);
    while (true) {
        const line = readDaemonProbeLine(allocator, &reader.interface, stream.socket.handle, deadline_ms) catch |err| switch (err) {
            error.AppServerDaemonProbeTimedOut => return .{ .unavailable = try std.fmt.allocPrint(allocator, "timed out probing app-server control socket {s}", .{socket_path}) },
            error.StreamTooLong => return .{ .unavailable = try allocator.dupe(u8, "app-server probe response exceeded 65536 bytes") },
            else => return err,
        } orelse return .{ .unavailable = try allocator.dupe(u8, "app-server closed the control socket") };
        defer allocator.free(line);
        if (try daemonProbeVersionFromLine(allocator, line)) |version| {
            writer.interface.writeAll("{\"jsonrpc\":\"2.0\",\"method\":\"initialized\"}\n") catch {};
            writer.interface.flush() catch {};
            return .{ .running = version };
        }
    }
}

fn connectDaemonUnixStream(allocator: std.mem.Allocator, socket_path: []const u8) !DaemonUnixConnect {
    const fd = try createDaemonUnixSocketFd();
    var keep_fd = false;
    defer if (!keep_fd) closeFd(fd);

    var storage = std.mem.zeroes(DaemonUnixSockaddr);
    if (socket_path.len >= storage.un.path.len) {
        return .{ .unavailable = try std.fmt.allocPrint(allocator, "socket path is too long: {s}", .{socket_path}) };
    }
    storage.un.family = std.posix.AF.UNIX;
    @memcpy(storage.un.path[0..socket_path.len], socket_path);
    storage.un.path[socket_path.len] = 0;
    const address_len: std.posix.socklen_t = @intCast(@offsetOf(std.posix.sockaddr.un, "path") + socket_path.len + 1);

    while (true) {
        switch (std.posix.errno(std.posix.system.connect(fd, &storage.any, address_len))) {
            .SUCCESS => {
                keep_fd = true;
                return .{ .stream = .{ .socket = .{ .handle = fd, .address = .{ .ip4 = .loopback(0) } } } };
            },
            .INTR => continue,
            .NOENT => return .{ .unavailable = try allocator.dupe(u8, "No such file or directory (os error 2)") },
            .NOTDIR => return .{ .unavailable = try allocator.dupe(u8, "Not a directory (os error 20)") },
            .CONNREFUSED => return .{ .unavailable = try allocator.dupe(u8, "Connection refused (os error 61)") },
            .ACCES => return error.AccessDenied,
            .PERM => return error.PermissionDenied,
            .LOOP => return error.SymLinkLoop,
            else => |err| return .{ .unavailable = try std.fmt.allocPrint(allocator, "unexpected socket error: {s}", .{@tagName(err)}) },
        }
    }
}

fn createDaemonUnixSocketFd() !std.posix.fd_t {
    while (true) {
        const rc = std.posix.system.socket(std.posix.AF.UNIX, std.posix.SOCK.STREAM, 0);
        switch (std.posix.errno(rc)) {
            .SUCCESS => return @intCast(rc),
            .INTR => continue,
            .AFNOSUPPORT => return error.AddressFamilyUnsupported,
            .INVAL => return error.ProtocolUnsupportedBySystem,
            .MFILE => return error.ProcessFdQuotaExceeded,
            .NFILE => return error.SystemFdQuotaExceeded,
            .NOBUFS, .NOMEM => return error.SystemResources,
            .PROTONOSUPPORT => return error.ProtocolUnsupportedBySystem,
            else => return error.Unexpected,
        }
    }
}

fn daemonProbeErrorCause(allocator: std.mem.Allocator, context: []const u8, err: anyerror) ![]const u8 {
    return std.fmt.allocPrint(allocator, "{s}: {s}", .{ context, @errorName(err) });
}

fn readDaemonProbeLine(
    allocator: std.mem.Allocator,
    reader: *std.Io.Reader,
    fd: std.posix.fd_t,
    deadline_ms: i64,
) !?[]const u8 {
    var line = std.ArrayList(u8).empty;
    errdefer line.deinit(allocator);

    while (true) {
        if (!readerHasBufferedTransportBytes(reader)) {
            const remaining_ms = remainingAppServerAwakeMillis(deadline_ms) orelse return error.AppServerDaemonProbeTimedOut;
            const max_poll_timeout_ms: u64 = @intCast(std.math.maxInt(i32));
            const poll_timeout: i32 = if (remaining_ms > max_poll_timeout_ms) std.math.maxInt(i32) else @intCast(remaining_ms);
            if (!try appServerConnectionReadable(fd, poll_timeout)) return error.AppServerDaemonProbeTimedOut;
        }
        const byte = reader.takeByte() catch |err| switch (err) {
            error.EndOfStream => {
                if (line.items.len == 0) return null;
                return try trimOwnedTransportPayload(allocator, try line.toOwnedSlice(allocator));
            },
            else => return err,
        };
        if (byte == '\n') return try trimOwnedTransportPayload(allocator, try line.toOwnedSlice(allocator));
        if (line.items.len >= 64 * 1024) return error.StreamTooLong;
        try line.append(allocator, byte);
    }
}

fn daemonProbeVersionFromLine(allocator: std.mem.Allocator, line: []const u8) !?[]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, line, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    const id = object.get("id") orelse return null;
    if (!jsonIdIsOne(id)) return null;
    const result = object.get("result") orelse return null;
    if (result != .object) return null;
    if (result.object.get("serverInfo")) |server_info| {
        if (server_info == .object) {
            if (server_info.object.get("version")) |version| {
                if (version == .string and version.string.len > 0) return try allocator.dupe(u8, version.string);
            }
        }
    }
    if (result.object.get("userAgent")) |user_agent| {
        if (user_agent == .string) return try daemonVersionFromUserAgent(allocator, user_agent.string);
    }
    return try allocator.dupe(u8, "unknown");
}

fn jsonIdIsOne(value: std.json.Value) bool {
    return switch (value) {
        .integer => |integer| integer == 1,
        .number_string => |number| std.mem.eql(u8, number, "1"),
        .string => |string| std.mem.eql(u8, string, "1"),
        else => false,
    };
}

fn daemonVersionFromUserAgent(allocator: std.mem.Allocator, user_agent: []const u8) ![]const u8 {
    const slash = std.mem.indexOfScalar(u8, user_agent, '/') orelse return allocator.dupe(u8, "unknown");
    const rest = user_agent[slash + 1 ..];
    const end = std.mem.indexOfAny(u8, rest, " \t\r\n") orelse rest.len;
    if (end == 0) return allocator.dupe(u8, "unknown");
    return allocator.dupe(u8, rest[0..end]);
}

fn writeDaemonRemoteControlSettings(settings_path: []const u8, enabled: bool) !void {
    const io = std.Io.Threaded.global_single_threaded.io();
    try std.Io.Dir.cwd().writeFile(io, .{
        .sub_path = settings_path,
        .data = if (enabled)
            "{\n  \"remoteControlEnabled\": true\n}"
        else
            "{\n  \"remoteControlEnabled\": false\n}",
    });
}

fn activeManagedPid(allocator: std.mem.Allocator, codex_home: []const u8, pid_path: []const u8, kind: ManagedProcessKind) !?i64 {
    var record = try activeManagedPidRecord(allocator, codex_home, pid_path, kind) orelse return null;
    defer record.deinit(allocator);
    return record.pid;
}

fn activeManagedDaemonChildGlobalArgs(allocator: std.mem.Allocator, codex_home: []const u8) !?[][]const u8 {
    const pid_path = try daemonPidPath(allocator, codex_home);
    defer allocator.free(pid_path);
    var record = try activeManagedPidRecord(allocator, codex_home, pid_path, .app_server) orelse return null;
    defer record.deinit(allocator);
    return try duplicateStringSlice(allocator, record.child_global_args);
}

fn activeManagedPidRecord(allocator: std.mem.Allocator, codex_home: []const u8, pid_path: []const u8, kind: ManagedProcessKind) !?ManagedPidRecord {
    var record = try readManagedPid(allocator, pid_path) orelse return null;
    if (!processExists(record.pid)) {
        record.deinit(allocator);
        try removeFileIfExists(pid_path);
        return null;
    }
    if (!try processMatchesManagedProcess(allocator, codex_home, record, kind)) {
        record.deinit(allocator);
        try removeFileIfExists(pid_path);
        return null;
    }
    return record;
}

fn readManagedPid(allocator: std.mem.Allocator, pid_path: []const u8) !?ManagedPidRecord {
    const io = std.Io.Threaded.global_single_threaded.io();
    const bytes = std.Io.Dir.cwd().readFileAlloc(io, pid_path, allocator, .limited(4096)) catch |err| switch (err) {
        error.FileNotFound => return null,
        error.StreamTooLong => return null,
        else => return err,
    };
    defer allocator.free(bytes);

    const trimmed = std.mem.trim(u8, bytes, " \t\r\n");
    if (trimmed.len == 0) return null;
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, trimmed, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const pid_value = parsed.value.object.get("pid") orelse return null;
    const pid = switch (pid_value) {
        .integer => |value| value,
        .number_string => |value| std.fmt.parseInt(i64, value, 10) catch return null,
        else => return null,
    };
    if (pid <= 0) return null;
    const start_value = parsed.value.object.get("processStartTime") orelse return null;
    if (start_value != .string or start_value.string.len == 0) return null;
    const process_start_time = try allocator.dupe(u8, start_value.string);
    errdefer allocator.free(process_start_time);
    const child_global_args = parseManagedPidChildGlobalArgs(allocator, parsed.value.object) catch |err| switch (err) {
        error.InvalidManagedPidRecord => {
            allocator.free(process_start_time);
            return null;
        },
        else => return err,
    };
    return .{ .pid = pid, .process_start_time = process_start_time, .child_global_args = child_global_args };
}

fn parseManagedPidChildGlobalArgs(allocator: std.mem.Allocator, object: std.json.ObjectMap) ![][]const u8 {
    const args_value = object.get("childGlobalArgs") orelse return try allocator.alloc([]const u8, 0);
    if (args_value != .array) return error.InvalidManagedPidRecord;
    var args = try allocator.alloc([]const u8, args_value.array.items.len);
    var copied: usize = 0;
    errdefer {
        for (args[0..copied]) |arg| allocator.free(arg);
        allocator.free(args);
    }
    for (args_value.array.items, 0..) |value, index| {
        if (value != .string) return error.InvalidManagedPidRecord;
        args[index] = try allocator.dupe(u8, value.string);
        copied += 1;
    }
    return args;
}

fn duplicateStringSlice(allocator: std.mem.Allocator, items: []const []const u8) ![][]const u8 {
    var duplicated = try allocator.alloc([]const u8, items.len);
    var copied: usize = 0;
    errdefer {
        for (duplicated[0..copied]) |item| allocator.free(item);
        allocator.free(duplicated);
    }
    for (items, 0..) |item, index| {
        duplicated[index] = try allocator.dupe(u8, item);
        copied += 1;
    }
    return duplicated;
}

fn freeStringSlice(allocator: std.mem.Allocator, items: []const []const u8) void {
    for (items) |item| allocator.free(item);
    allocator.free(items);
}

fn writeDaemonPidRecord(allocator: std.mem.Allocator, pid_path: []const u8, pid: i64, process_start_time: []const u8, child_global_args: []const []const u8) !void {
    var record = std.ArrayList(u8).empty;
    defer record.deinit(allocator);
    try record.appendSlice(allocator, "{\"pid\":");
    const pid_text = try std.fmt.allocPrint(allocator, "{d}", .{pid});
    defer allocator.free(pid_text);
    try record.appendSlice(allocator, pid_text);
    try record.appendSlice(allocator, ",\"processStartTime\":");
    try appendJsonString(allocator, &record, process_start_time);
    try record.appendSlice(allocator, ",\"childGlobalArgs\":[");
    for (child_global_args, 0..) |arg, index| {
        if (index > 0) try record.append(allocator, ',');
        try appendJsonString(allocator, &record, arg);
    }
    try record.append(allocator, ']');
    try record.appendSlice(allocator, "}");
    try std.Io.Dir.cwd().writeFile(std.Io.Threaded.global_single_threaded.io(), .{
        .sub_path = pid_path,
        .data = record.items,
    });
}

fn removeFileIfExists(path: []const u8) !void {
    std.Io.Dir.cwd().deleteFile(std.Io.Threaded.global_single_threaded.io(), path) catch |err| switch (err) {
        error.FileNotFound => return,
        else => return err,
    };
}

fn processExists(pid: i64) bool {
    if (pid <= 0 or pid > std.math.maxInt(std.posix.pid_t)) return false;
    const raw_pid: std.c.pid_t = @intCast(pid);
    const result = std.c.kill(raw_pid, @enumFromInt(0));
    if (result == 0) return true;
    return std.c.errno(result) == .PERM;
}

fn processMatchesManagedProcess(allocator: std.mem.Allocator, codex_home: []const u8, record: ManagedPidRecord, kind: ManagedProcessKind) !bool {
    const managed_path = try managedCodexPath(allocator, codex_home);
    defer allocator.free(managed_path);
    const current_start_time = try processStartTime(allocator, record.pid) orelse return false;
    defer allocator.free(current_start_time);
    if (!std.mem.eql(u8, current_start_time, record.process_start_time)) return false;

    const command = try processCommand(allocator, record.pid) orelse return false;
    defer allocator.free(command);
    return switch (kind) {
        .app_server => processCommandMatchesManagedDaemon(command, managed_path),
        .updater => try processCommandMatchesManagedUpdater(allocator, command, managed_path),
    };
}

fn processCommandMatchesManagedDaemon(command: []const u8, managed_path: []const u8) bool {
    if (!std.mem.startsWith(u8, command, managed_path)) return false;
    const rest = command[managed_path.len..];
    return std.mem.endsWith(u8, rest, " app-server --listen unix://") or
        std.mem.endsWith(u8, rest, " app-server --remote-control --listen unix://");
}

fn processCommandMatchesManagedUpdater(allocator: std.mem.Allocator, command: []const u8, managed_path: []const u8) !bool {
    const suffix = " app-server daemon pid-update-loop";
    if (!std.mem.endsWith(u8, command, suffix)) return false;
    const executable = command[0 .. command.len - suffix.len];
    if (std.mem.eql(u8, executable, managed_path)) return true;

    const resolved_managed_path = std.Io.Dir.cwd().realPathFileAlloc(
        std.Io.Threaded.global_single_threaded.io(),
        managed_path,
        allocator,
    ) catch return false;
    defer allocator.free(resolved_managed_path);
    return std.mem.eql(u8, executable, resolved_managed_path);
}

test "managed updater pid matcher accepts resolved standalone path" {
    if (builtin.os.tag == .windows) return error.SkipZigTest;

    const allocator = std.testing.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();

    try dir.dir.createDirPath(io, "releases/0.0.1");
    try dir.dir.createDirPath(io, "current");
    try dir.dir.writeFile(io, .{
        .sub_path = "releases/0.0.1/codex",
        .data = "",
    });
    try dir.dir.symLink(io, "../releases/0.0.1/codex", "current/codex", .{});

    const root = try dir.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(root);
    const managed_path = try std.fs.path.join(allocator, &.{ root, "current", "codex" });
    defer allocator.free(managed_path);
    const release_path = try std.fs.path.join(allocator, &.{ root, "releases", "0.0.1", "codex" });
    defer allocator.free(release_path);

    const symlink_command = try std.fmt.allocPrint(allocator, "{s} app-server daemon pid-update-loop", .{managed_path});
    defer allocator.free(symlink_command);
    try std.testing.expect(try processCommandMatchesManagedUpdater(allocator, symlink_command, managed_path));

    const resolved_command = try std.fmt.allocPrint(allocator, "{s} app-server daemon pid-update-loop", .{release_path});
    defer allocator.free(resolved_command);
    try std.testing.expect(try processCommandMatchesManagedUpdater(allocator, resolved_command, managed_path));
}

fn processStartTime(allocator: std.mem.Allocator, pid: i64) !?[]const u8 {
    return processPsField(allocator, pid, "lstart=");
}

fn processCommand(allocator: std.mem.Allocator, pid: i64) !?[]const u8 {
    return processPsField(allocator, pid, "command=");
}

fn processPsField(allocator: std.mem.Allocator, pid: i64, field: []const u8) !?[]const u8 {
    const pid_text = try std.fmt.allocPrint(allocator, "{d}", .{pid});
    defer allocator.free(pid_text);

    var io_instance: std.Io.Threaded = .init(allocator, .{});
    defer io_instance.deinit();
    const result = std.process.run(allocator, io_instance.io(), .{
        .argv = &.{ "/bin/ps", "-p", pid_text, "-o", field },
        .stdout_limit = .limited(4096),
        .stderr_limit = .limited(4096),
    }) catch return null;
    defer allocator.free(result.stdout);
    defer allocator.free(result.stderr);
    if (!daemonChildTermSuccess(result.term)) return null;
    const trimmed = std.mem.trim(u8, result.stdout, " \t\r\n");
    if (trimmed.len == 0) return null;
    return try allocator.dupe(u8, trimmed);
}

fn daemonChildTermSuccess(term: std.process.Child.Term) bool {
    return switch (term) {
        .exited => |code| code == 0,
        else => false,
    };
}

fn managedCodexVersionBestEffort(allocator: std.mem.Allocator, managed_path: []const u8) !?[]const u8 {
    const is_file = managedCodexPathIsFile(allocator, managed_path) catch |err| switch (err) {
        error.AccessDenied, error.PermissionDenied, error.SymLinkLoop => return null,
        else => return err,
    };
    if (!is_file) return null;
    var io_instance: std.Io.Threaded = .init(allocator, .{});
    defer io_instance.deinit();
    const result = std.process.run(allocator, io_instance.io(), .{
        .argv = &.{ managed_path, "--version" },
        .stdout_limit = .limited(4096),
        .stderr_limit = .limited(4096),
    }) catch return null;
    defer allocator.free(result.stdout);
    defer allocator.free(result.stderr);
    if (!daemonChildTermSuccess(result.term)) return null;
    return parseManagedCodexVersion(allocator, if (result.stdout.len > 0) result.stdout else result.stderr) catch null;
}

fn managedCodexPathIsFile(allocator: std.mem.Allocator, managed_path: []const u8) !bool {
    const stat = statPathFollow(allocator, managed_path) catch |err| switch (err) {
        error.NotDir, error.NameTooLong => return false,
        else => return err,
    } orelse return false;
    return std.c.S.ISREG(@intCast(stat.mode));
}

fn parseManagedCodexVersion(allocator: std.mem.Allocator, output: []const u8) ![]const u8 {
    var parts = std.mem.tokenizeAny(u8, output, " \t\r\n");
    _ = parts.next() orelse return error.InvalidManagedCodexVersion;
    const version = parts.next() orelse return error.InvalidManagedCodexVersion;
    if (version.len == 0) return error.InvalidManagedCodexVersion;
    return allocator.dupe(u8, version);
}

fn terminatePid(pid: i64) void {
    if (pid <= 0 or pid > std.math.maxInt(std.posix.pid_t)) return;
    std.posix.kill(@intCast(pid), .TERM) catch {};
}

fn forceTerminatePid(pid: i64) void {
    if (pid <= 0 or pid > std.math.maxInt(std.posix.pid_t)) return;
    std.posix.kill(@intCast(pid), .KILL) catch {};
}

