    std.debug.print(
        \\error: unrecognized subcommand '{s}'
        \\
        \\Usage: codex-zig app-server daemon help [COMMAND]...
        \\
        \\For more information, try '--help'.
        \\
    , .{arg});
    return error.AppServerDaemonCommandFailed;
}

fn failUnexpectedDaemonArgument(command: DaemonCommand, arg: []const u8) error{AppServerDaemonCommandFailed} {
    std.debug.print(
        \\error: unexpected argument '{s}' found
        \\
        \\Usage: {s}
        \\
        \\For more information, try '--help'.
        \\
    , .{ arg, daemonCommandUsage(command) });
    return error.AppServerDaemonCommandFailed;
}

fn failMissingDaemonOptionValue(arg: []const u8) error{AppServerDaemonCommandFailed} {
    const value_name = if (std.mem.eql(u8, arg, "--enable") or std.mem.eql(u8, arg, "--disable")) "FEATURE" else "key=value";
    std.debug.print(
        \\error: a value is required for '{s} <{s}>' but none was supplied
        \\
        \\For more information, try '--help'.
        \\
    , .{ arg, value_name });
    return error.AppServerDaemonCommandFailed;
}

fn daemonCommandUsage(command: DaemonCommand) []const u8 {
    return switch (command) {
        .bootstrap => "codex-zig app-server daemon bootstrap [OPTIONS]",
        .start => "codex-zig app-server daemon start [OPTIONS]",
        .restart => "codex-zig app-server daemon restart [OPTIONS]",
        .enable_remote_control => "codex-zig app-server daemon enable-remote-control [OPTIONS]",
        .disable_remote_control => "codex-zig app-server daemon disable-remote-control [OPTIONS]",
        .stop => "codex-zig app-server daemon stop [OPTIONS]",
        .version => "codex-zig app-server daemon version [OPTIONS]",
        .pid_update_loop => "codex-zig app-server daemon pid-update-loop",
    };
}

fn parseWebsocketAuthMode(value: []const u8) !WebsocketAuthMode {
    if (std.mem.eql(u8, value, "capability-token")) return .capability_token;
    if (std.mem.eql(u8, value, "signed-bearer-token")) return .signed_bearer_token;
    return error.UnsupportedAppServerWebsocketAuthMode;
}

fn failStrictConfigUnsupportedForSubcommand(subcommand: []const u8) error{StrictConfigUnsupportedForSubcommand} {
    std.debug.print("`--strict-config` is not supported for `codex-zig app-server {s}`\n", .{subcommand});
    return error.StrictConfigUnsupportedForSubcommand;
}

fn failStrictConfigUnsupportedForSubcommandWithTail(subcommand: []const u8, args: []const []const u8) error{StrictConfigUnsupportedForSubcommand} {
    if (std.mem.eql(u8, subcommand, "daemon") and args.len > 0 and daemonCommandFromName(args[0]) != null) {
        std.debug.print("`--strict-config` is not supported for `codex-zig app-server daemon {s}`\n", .{args[0]});
        return error.StrictConfigUnsupportedForSubcommand;
    }
    return failStrictConfigUnsupportedForSubcommand(subcommand);
}

fn parseWebsocketClockSkew(value: []const u8) !u64 {
    return std.fmt.parseUnsigned(u64, value, 10) catch error.InvalidAppServerWebsocketClockSkew;
}

fn validateWebsocketAuthArgs(auth: WebsocketAuthArgs) !void {
    switch (auth.ws_auth orelse {
        if (hasAnyWebsocketAuthModeSpecificFlag(auth)) return error.AppServerWebsocketAuthModeRequired;
        return;
    }) {
        .capability_token => {
            if (auth.ws_shared_secret_file != null or auth.ws_issuer != null or auth.ws_audience != null or auth.ws_max_clock_skew_seconds != null) {
                return error.AppServerWebsocketCapabilityTokenRejectedSignedBearerFlag;
            }
            if (auth.ws_token_file != null and auth.ws_token_sha256 != null) return error.AppServerWebsocketTokenSourcesMutuallyExclusive;
            if (auth.ws_token_file == null and auth.ws_token_sha256 == null) return error.AppServerWebsocketTokenSourceRequired;
            if (auth.ws_token_file) |path| try validateAbsolutePathArg(path);
            if (auth.ws_token_sha256) |digest| try validateSha256DigestArg(digest);
        },
        .signed_bearer_token => {
            if (auth.ws_token_file != null or auth.ws_token_sha256 != null) return error.AppServerWebsocketSignedBearerRejectedCapabilityTokenFlag;
            const shared_secret_file = auth.ws_shared_secret_file orelse return error.AppServerWebsocketSharedSecretFileRequired;
            try validateAbsolutePathArg(shared_secret_file);
        },
    }
}

fn hasAnyWebsocketAuthModeSpecificFlag(auth: WebsocketAuthArgs) bool {
    return auth.ws_token_file != null or
        auth.ws_token_sha256 != null or
        auth.ws_shared_secret_file != null or
        auth.ws_issuer != null or
        auth.ws_audience != null or
        auth.ws_max_clock_skew_seconds != null;
}

fn validateAbsolutePathArg(path: []const u8) !void {
    if (!std.fs.path.isAbsolute(path)) return error.AppServerWebsocketAuthPathMustBeAbsolute;
}

fn validateSha256DigestArg(value: []const u8) !void {
    _ = try parseSha256DigestArg(value);
}

const WebsocketAuthPolicy = union(enum) {
    none,
    capability_token: [std.crypto.hash.sha2.Sha256.digest_length]u8,

    signed_bearer_token: SignedWebsocketBearerPolicy,

    fn deinit(self: *WebsocketAuthPolicy, allocator: std.mem.Allocator) void {
        switch (self.*) {
            .signed_bearer_token => |*policy| policy.deinit(allocator),
            else => {},
        }
    }
};

const SignedWebsocketBearerPolicy = struct {
    shared_secret: []const u8,
    issuer: ?[]const u8 = null,
    audience: ?[]const u8 = null,
    max_clock_skew_seconds: i64 = 30,

    fn deinit(self: *SignedWebsocketBearerPolicy, allocator: std.mem.Allocator) void {
        allocator.free(self.shared_secret);
        if (self.issuer) |issuer| allocator.free(issuer);
        if (self.audience) |audience| allocator.free(audience);
    }
};

fn websocketAuthPolicyFromArgs(allocator: std.mem.Allocator, auth: WebsocketAuthArgs) !WebsocketAuthPolicy {
    switch (auth.ws_auth orelse return .none) {
        .capability_token => {
            if (auth.ws_token_sha256) |digest| {
                return .{ .capability_token = try parseSha256DigestArg(digest) };
            }
            const token_file = auth.ws_token_file orelse return error.AppServerWebsocketTokenSourceRequired;
            const token = try readWebsocketAuthSecret(allocator, token_file);
            defer allocator.free(token);
            var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(token, &digest, .{});
            return .{ .capability_token = digest };
        },
        .signed_bearer_token => {
            const shared_secret_file = auth.ws_shared_secret_file orelse return error.AppServerWebsocketSharedSecretFileRequired;
            const shared_secret = try readWebsocketAuthSecret(allocator, shared_secret_file);
            errdefer allocator.free(shared_secret);
            if (shared_secret.len < WEBSOCKET_MIN_SIGNED_BEARER_SECRET_BYTES) return error.AppServerWebsocketSignedBearerSecretTooShort;
            const issuer = try dupeTrimmedOptionalWebsocketAuthString(allocator, auth.ws_issuer);
            errdefer if (issuer) |value| allocator.free(value);
            const audience = try dupeTrimmedOptionalWebsocketAuthString(allocator, auth.ws_audience);
            errdefer if (audience) |value| allocator.free(value);
            return .{ .signed_bearer_token = .{
                .shared_secret = shared_secret,
                .issuer = issuer,
                .audience = audience,
                .max_clock_skew_seconds = try websocketClockSkewI64(auth.ws_max_clock_skew_seconds orelse WEBSOCKET_DEFAULT_MAX_CLOCK_SKEW_SECONDS),
            } };
        },
    }
}

fn dupeTrimmedOptionalWebsocketAuthString(allocator: std.mem.Allocator, value: ?[]const u8) !?[]const u8 {
    const raw = value orelse return null;
    const trimmed = std.mem.trim(u8, raw, " \t\r\n");
    if (trimmed.len == 0) return null;
    const owned = try allocator.dupe(u8, trimmed);
    return owned;
}

fn websocketClockSkewI64(value: u64) !i64 {
    if (value > std.math.maxInt(i64)) return error.AppServerWebsocketClockSkewOutOfRange;
    return @intCast(value);
}

fn parseSha256DigestArg(value: []const u8) ![std.crypto.hash.sha2.Sha256.digest_length]u8 {
    const trimmed = std.mem.trim(u8, value, " \t\r\n");
    if (trimmed.len != 64) return error.AppServerWebsocketAuthSha256DigestInvalid;
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    for (&digest, 0..) |*byte, index| {
        const pair = trimmed[index * 2 .. index * 2 + 2];
        byte.* = (try websocketHexNibble(pair[0])) << 4 | try websocketHexNibble(pair[1]);
    }
    return digest;
}

fn websocketHexNibble(byte: u8) !u8 {
    return switch (byte) {
        '0'...'9' => byte - '0',
        'a'...'f' => byte - 'a' + 10,
        'A'...'F' => byte - 'A' + 10,
        else => error.AppServerWebsocketAuthSha256DigestInvalid,
    };
}

fn readWebsocketAuthSecret(allocator: std.mem.Allocator, path: []const u8) ![]const u8 {
    const raw = try std.Io.Dir.cwd().readFileAlloc(std.Io.Threaded.global_single_threaded.io(), path, allocator, .limited(1024 * 1024));
    defer allocator.free(raw);
    const trimmed = std.mem.trim(u8, raw, " \t\r\n");
    if (trimmed.len == 0) return error.AppServerWebsocketAuthSecretEmpty;
    return allocator.dupe(u8, trimmed);
}

fn runGenerateTs(allocator: std.mem.Allocator, args: []const []const u8, root_feature_overrides: features_cmd.FeatureOverrides) !void {
    var out_dir: ?[]const u8 = null;
    var prettier: ?[]const u8 = null;
    var experimental = false;
    var ignored_runtime_overrides = config.RuntimeOverrides{};
    var ignored_feature_overrides = features_cmd.FeatureOverrides{};
    defer ignored_feature_overrides.deinit(allocator);
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (try parseAppServerLocalConfigFeatureArg(allocator, args, &index, null, &ignored_runtime_overrides, &ignored_feature_overrides, null, null, false)) continue;
        if (std.mem.eql(u8, arg, "-o") or std.mem.eql(u8, arg, "--out")) {
            if (index + 1 >= args.len or optionValueLooksMissing(args[index + 1])) return error.MissingAppServerGenerateTsOutDir;
            index += 1;
            out_dir = args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--out=")) {
            out_dir = arg["--out=".len..];
            continue;
        }
        if (std.mem.eql(u8, arg, "-p") or std.mem.eql(u8, arg, "--prettier")) {
            if (index + 1 >= args.len or optionValueLooksMissing(args[index + 1])) return error.MissingAppServerGenerateTsPrettierPath;
            index += 1;
            prettier = args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--prettier=")) {
            prettier = arg["--prettier=".len..];
            continue;
        }
        if (std.mem.eql(u8, arg, "--experimental")) {
            experimental = true;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "-")) return error.UnknownAppServerGenerateTsOption;
        return error.UnexpectedAppServerGenerateTsArgument;
    }

    const target_dir = out_dir orelse return error.MissingAppServerGenerateTsOutDir;
    if (target_dir.len == 0) return error.MissingAppServerGenerateTsOutDir;
    try validateAppServerLocalConfigFeatureOverrides(allocator, args, root_feature_overrides);
    try writeAppServerTs(allocator, target_dir, prettier, experimental);
}

