fn writeAppServerTs(allocator: std.mem.Allocator, out_dir: []const u8, prettier: ?[]const u8, experimental: bool) !void {
    _ = prettier;
    const io = std.Io.Threaded.global_single_threaded.io();
    const v2_out_dir = try std.fs.path.join(allocator, &.{ out_dir, "v2" });
    defer allocator.free(v2_out_dir);
    try std.Io.Dir.cwd().createDirPath(io, v2_out_dir);
    const serde_json_out_dir = try std.fs.path.join(allocator, &.{ out_dir, "serde_json" });
    defer allocator.free(serde_json_out_dir);
    try std.Io.Dir.cwd().createDirPath(io, serde_json_out_dir);
    try writeSchemaFilesForMode(allocator, out_dir, &APP_SERVER_TS_FILES, experimental);
}

fn writeAppServerJsonSchemas(allocator: std.mem.Allocator, out_dir: []const u8, experimental: bool) !void {
    try writeSchemaFilesForMode(allocator, out_dir, &APP_SERVER_JSON_SCHEMA_FILES, experimental);
    try writeVersionedJsonSchemaAliases(allocator, out_dir);
}

fn writeRolloutLineJsonSchema(allocator: std.mem.Allocator, out_dir: []const u8) !void {
    const files = [_]SchemaFile{.{ .name = "RolloutLine.json", .contents = ROLLOUT_LINE_JSON_SCHEMA }};
    try writeSchemaFiles(allocator, out_dir, &files);
}

fn writeSchemaFiles(allocator: std.mem.Allocator, out_dir: []const u8, files: []const SchemaFile) !void {
    try writeSchemaFilesForMode(allocator, out_dir, files, false);
}

fn writeSchemaFilesForMode(allocator: std.mem.Allocator, out_dir: []const u8, files: []const SchemaFile, experimental: bool) !void {
    const io = std.Io.Threaded.global_single_threaded.io();
    try std.Io.Dir.cwd().createDirPath(io, out_dir);
    for (files) |file| {
        const schema_path = try std.fs.path.join(allocator, &.{ out_dir, file.name });
        defer allocator.free(schema_path);
        if (std.fs.path.dirname(schema_path)) |parent_dir| {
            try std.Io.Dir.cwd().createDirPath(io, parent_dir);
        }
        try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = schema_path, .data = schemaFileContentsForMode(file, experimental) });
    }
}

fn schemaFileContentsForMode(file: SchemaFile, experimental: bool) []const u8 {
    if (experimental and std.mem.eql(u8, file.name, "v2/ConfigRequirements.ts")) return CONFIG_REQUIREMENTS_EXPERIMENTAL_TS;
    if (experimental and std.mem.eql(u8, file.name, "v2/ConfigRequirementsReadResponse.json")) return CONFIG_REQUIREMENTS_READ_RESPONSE_EXPERIMENTAL_JSON_SCHEMA;
    return file.contents;
}

fn writeVersionedJsonSchemaAliases(allocator: std.mem.Allocator, out_dir: []const u8) !void {
    for (APP_SERVER_JSON_SCHEMA_VERSIONED_ALIASES) |versioned_name| {
        const basename = std.fs.path.basename(versioned_name);
        const source = findSchemaFile(&APP_SERVER_JSON_SCHEMA_FILES, basename) orelse return error.MissingAppServerJsonSchemaAliasSource;
        const rewritten = try rewriteVersionedJsonSchemaRefs(allocator, source.contents);
        defer allocator.free(rewritten);
        const files = [_]SchemaFile{.{ .name = versioned_name, .contents = rewritten }};
        try writeSchemaFiles(allocator, out_dir, &files);
    }
}

fn findSchemaFile(files: []const SchemaFile, name: []const u8) ?SchemaFile {
    for (files) |file| {
        if (std.mem.eql(u8, file.name, name)) return file;
    }
    return null;
}

fn rewriteVersionedJsonSchemaRefs(allocator: std.mem.Allocator, contents: []const u8) ![]const u8 {
    const ref_prefix = "\"$ref\": \"";
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);

    var index: usize = 0;
    while (std.mem.indexOfPos(u8, contents, index, ref_prefix)) |pos| {
        const value_start = pos + ref_prefix.len;
        const value_end = std.mem.indexOfScalarPos(u8, contents, value_start, '"') orelse return error.InvalidJsonSchemaRef;
        const value = contents[value_start..value_end];
        try out.appendSlice(allocator, contents[index..value_start]);
        if (shouldPrefixVersionedJsonSchemaRef(value)) {
            try out.appendSlice(allocator, "../");
        }
        try out.appendSlice(allocator, value);
        index = value_end;
    }

    try out.appendSlice(allocator, contents[index..]);
    return out.toOwnedSlice(allocator);
}

fn shouldPrefixVersionedJsonSchemaRef(value: []const u8) bool {
    if (value.len == 0) return false;
    if (value[0] == '#') return false;
    if (std.mem.startsWith(u8, value, "../")) return false;
    if (std.mem.startsWith(u8, value, "http://")) return false;
    if (std.mem.startsWith(u8, value, "https://")) return false;
    return true;
}

fn runProxy(allocator: std.mem.Allocator, args: []const []const u8, root_feature_overrides: features_cmd.FeatureOverrides) !void {
    var socket_path_arg: ?[]const u8 = null;
    const help_like = proxyTailHasHelp(args);
    var runtime_overrides = config.RuntimeOverrides{};
    var feature_overrides = try root_feature_overrides.clone(allocator);
    defer feature_overrides.deinit(allocator);
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (isHelpFlag(arg)) {
            printProxyHelp();
            return;
        }
        if (try parseAppServerLocalConfigFeatureArg(allocator, args, &index, null, &runtime_overrides, &feature_overrides, null, null, !help_like)) continue;
        if (std.mem.eql(u8, arg, "--sock")) {
            if (index + 1 >= args.len) return error.MissingAppServerProxySocketPath;
            index += 1;
            socket_path_arg = args[index];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--sock=")) {
            socket_path_arg = arg["--sock=".len..];
            continue;
        }
        if (std.mem.startsWith(u8, arg, "-")) return error.UnknownAppServerProxyOption;
        return error.UnexpectedAppServerProxyArgument;
    }
    try features_cmd.validateRawConfigOverrides(feature_overrides);

    const owned_default_path = if (socket_path_arg == null) try defaultUnixSocketPath(allocator) else null;
    defer if (owned_default_path) |path| allocator.free(path);
    const socket_path = socket_path_arg orelse owned_default_path.?;
    try runStdioToUnixSocket(allocator, socket_path);
}

pub fn runStdioToUnixSocket(allocator: std.mem.Allocator, socket_path: []const u8) !void {
    _ = allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var address = try net.UnixAddress.init(socket_path);
    var stream = try address.connect(io);
    defer stream.close(io);

    var socket_out_buffer: [64 * 1024]u8 = undefined;
    var socket_writer = stream.writer(io, &socket_out_buffer);

    var stdin_open = true;
    var buffer: [64 * 1024]u8 = undefined;
    var fds = [_]std.posix.pollfd{
        .{ .fd = std.posix.STDIN_FILENO, .events = @intCast(std.posix.POLL.IN), .revents = 0 },
        .{ .fd = stream.socket.handle, .events = @intCast(std.posix.POLL.IN), .revents = 0 },
    };

    while (true) {
        fds[0].fd = if (stdin_open) std.posix.STDIN_FILENO else -1;
        fds[0].events = if (stdin_open) @intCast(std.posix.POLL.IN) else 0;
        fds[0].revents = 0;
        fds[1].events = @intCast(std.posix.POLL.IN);
        fds[1].revents = 0;

        _ = try std.posix.poll(&fds, -1);

        if (stdin_open and pollReventsInclude(fds[0].revents, relay_poll_read_events)) {
            const read_len = try std.posix.read(std.posix.STDIN_FILENO, &buffer);
            if (read_len == 0) {
                stdin_open = false;
                stream.shutdown(io, .send) catch {};
            } else {
                try socket_writer.interface.writeAll(buffer[0..read_len]);
                try socket_writer.interface.flush();
            }
        }

        if (pollReventsInclude(fds[1].revents, relay_poll_read_events)) {
            const read_len = try std.posix.read(stream.socket.handle, &buffer);
            if (read_len == 0) break;
            try cli_utils.writeStdout(buffer[0..read_len]);
        }
    }
}

const relay_poll_read_events = std.posix.POLL.IN | std.posix.POLL.HUP | std.posix.POLL.ERR | std.posix.POLL.NVAL;

fn pollReventsInclude(revents: i16, mask: comptime_int) bool {
    return (@as(u16, @bitCast(revents)) & @as(u16, @intCast(mask))) != 0;
}

fn parseTransport(value: []const u8) !Transport {
    if (std.mem.eql(u8, value, "stdio://")) return .stdio;
    if (std.mem.eql(u8, value, "off")) return .off;
    if (std.mem.eql(u8, value, "unix://")) return .unix_default;
    if (std.mem.startsWith(u8, value, "unix://")) {
        const path = value["unix://".len..];
        if (path.len == 0) return error.UnsupportedAppServerListenUrl;
        return .{ .unix_path = path };
    }
    if (std.mem.startsWith(u8, value, "ws://")) {
        const address = value["ws://".len..];
        const colon = std.mem.lastIndexOfScalar(u8, address, ':') orelse return error.UnsupportedAppServerListenUrl;
        const host = address[0..colon];
        const port_text = address[colon + 1 ..];
        if (host.len == 0 or port_text.len == 0) return error.UnsupportedAppServerListenUrl;
        const port = std.fmt.parseUnsigned(u16, port_text, 10) catch return error.UnsupportedAppServerListenUrl;
        return .{ .websocket = .{ .host = host, .port = port } };
    }
    return error.UnsupportedAppServerListenUrl;
}

fn formatTransportLabel(allocator: std.mem.Allocator, transport: Transport) ![]const u8 {
    return switch (transport) {
        .stdio => allocator.dupe(u8, "stdio://"),
        .off => allocator.dupe(u8, "off"),
        .unix_default => allocator.dupe(u8, "unix://"),
        .unix_path => |path| std.fmt.allocPrint(allocator, "unix://{s}", .{path}),
        .websocket => |address| std.fmt.allocPrint(allocator, "ws://{s}:{d}", .{ address.host, address.port }),
    };
}

const StdioServer = struct {
    allocator: std.mem.Allocator,
    invocation_options: InvocationOptions = .{},

    fn run(self: *StdioServer) !void {
        var state = try initAppServerState(self.allocator, self.invocation_options, true);
        defer state.deinit(self.allocator);

        var input_buffer: [64 * 1024]u8 = undefined;
        var stdin_reader = std.Io.File.stdin().reader(std.Io.Threaded.global_single_threaded.io(), &input_buffer);
        var transport_context = JsonRpcTransportContext{
            .kind = .stdout_line,
            .reader = &stdin_reader.interface,
            .read_fd = std.Io.File.stdin().handle,
        };
        state.server_request_transport = .{
            .ctx = &transport_context,
            .send_payload = sendJsonRpcTransportPayload,
            .read_payload = readJsonRpcTransportPayload,
            .read_payload_with_timeout = readJsonRpcTransportPayloadWithTimeout,
        };

        var line_buffer = std.ArrayList(u8).empty;
        defer line_buffer.deinit(self.allocator);
        while (true) {
            if (!readerHasBufferedTransportBytes(&stdin_reader.interface) and
                !try appServerConnectionReadable(std.Io.File.stdin().handle, appServerConnectionPollTimeoutMs(&state)))
            {
                try flushAppServerIdleWorkStdout(self.allocator, &state);
                continue;
            }
            const byte_or_null: ?u8 = stdin_reader.interface.takeByte() catch |err| switch (err) {
                error.EndOfStream => null,
                else => return err,
            };
            if (byte_or_null) |byte| {
                if (byte != '\n') {
                    if (line_buffer.items.len >= max_app_server_json_rpc_line_bytes) return error.StreamTooLong;
                    try line_buffer.append(self.allocator, byte);
                    continue;
                }
            } else if (line_buffer.items.len == 0) {
                break;
            }
            const trimmed = std.mem.trim(u8, line_buffer.items, " \t\r\n");
            defer line_buffer.clearRetainingCapacity();
            if (trimmed.len == 0) continue;
            const response = handleJsonRpcLine(self.allocator, &state, trimmed) catch |err| {
                const message = try std.fmt.allocPrint(self.allocator, "[app-server] failed to handle message: {s}\n", .{@errorName(err)});
                defer self.allocator.free(message);
                try cli_utils.writeStderr(message);
                continue;
            };
            try writePreResponseNotificationsStdout(self.allocator, &state);
            if (response) |payload| {
                defer self.allocator.free(payload);
                try writeStdoutLine(payload);
            }
            try flushAppServerIdleWorkStdout(self.allocator, &state);
        }
    }
};

const UnixServer = struct {
    allocator: std.mem.Allocator,
    socket_path: []const u8,
    invocation_options: InvocationOptions = .{},

    fn run(self: *UnixServer) !void {
        const shutdown_handlers = try AppServerShutdownSignalHandlers.install();
        defer shutdown_handlers.deinit();

        const io = std.Io.Threaded.global_single_threaded.io();
        try ensureParentDir(io, self.socket_path);
        try deleteSocketFileIfSocket(self.allocator, io, self.socket_path);

        var address = try net.UnixAddress.init(self.socket_path);
        var server = address.listen(io, .{}) catch |err| switch (err) {
            error.AddressInUse, error.NotDir => return error.AppServerUnixSocketPathExists,
            else => return err,
        };
        defer server.deinit(io);
        defer deleteSocketFileIfSocket(self.allocator, io, self.socket_path) catch {};
        try setFdNonblocking(server.socket.handle, true);

        var state = try initAppServerState(self.allocator, self.invocation_options, false);
        defer state.deinit(self.allocator);

        while (!appServerShutdownRequested()) {
            const stream_or_null = try acceptAppServerStream(&server, &shutdown_handlers, appServerDaemonAcceptPollTimeoutMs(&state));
            if (stream_or_null == null) {
                if (appServerShutdownRequested()) break;
                try reapExpiredThreadUnloads(self.allocator, &state, false);
                continue;
            }
            var stream = stream_or_null.?;
            self.handleConnection(&state, io, &stream) catch |err| {
                if (!appServerShutdownRequested()) {
                    const message = std.fmt.allocPrint(
                        self.allocator,
                        "[app-server] unix connection error: {s}\n",
                        .{@errorName(err)},
                    ) catch null;
                    if (message) |stderr_message| {
                        defer self.allocator.free(stderr_message);
                        cli_utils.writeStderr(stderr_message) catch {};
                    }
                }
                stream.close(io);
                continue;
            };
            stream.close(io);
        }
    }

    fn handleConnection(
        self: *UnixServer,
        state: *AppServerState,
        io: std.Io,
        stream: *net.Stream,
    ) !void {
        app_server_shutdown_active_connection_fd.store(stream.socket.handle, .release);
        defer app_server_shutdown_active_connection_fd.store(-1, .release);
        if (appServerShutdownRequested()) return;
        defer clearAppServerConnectionStateAfterDisconnect(self.allocator, state);

        var input_buffer: [64 * 1024]u8 = undefined;
        var output_buffer: [64 * 1024]u8 = undefined;
        var reader = stream.reader(io, &input_buffer);
        var writer = stream.writer(io, &output_buffer);
        const output_state = try createAppServerConnectionOutput(self.allocator, .stream_line, stream.socket.handle);
        defer closeAppServerConnectionOutput(self.allocator, output_state);
        var transport_context = JsonRpcTransportContext{
            .kind = .stream_line,
            .reader = &reader.interface,
            .read_fd = stream.socket.handle,
            .writer = &writer.interface,
            .output = output_state,
        };
        state.server_request_transport = .{
            .ctx = &transport_context,
            .send_payload = sendJsonRpcTransportPayload,
            .read_payload = readJsonRpcTransportPayload,
            .read_payload_with_timeout = readJsonRpcTransportPayloadWithTimeout,
        };
        defer state.server_request_transport = null;
        state.connection_output = output_state;
        defer state.connection_output = null;
        try reapExpiredThreadUnloads(self.allocator, state, false);

        var line_buffer = std.ArrayList(u8).empty;
        defer line_buffer.deinit(self.allocator);
        while (!appServerShutdownRequested()) {
            if (!readerHasBufferedTransportBytes(&reader.interface) and
                !try appServerConnectionReadable(stream.socket.handle, appServerConnectionPollTimeoutMs(state)))
            {
                try flushAppServerIdleWorkStream(self.allocator, state, &writer.interface);
                continue;
            }
            const byte_or_null: ?u8 = reader.interface.takeByte() catch |err| switch (err) {
                error.EndOfStream => null,
                else => return err,
            };
            if (byte_or_null) |byte| {
                if (byte != '\n') {
                    if (line_buffer.items.len >= max_app_server_json_rpc_line_bytes) return error.StreamTooLong;
                    try line_buffer.append(self.allocator, byte);
                    continue;
                }
            } else {
                if (line_buffer.items.len == 0 or appServerShutdownRequested()) break;
            }
            if (appServerShutdownRequested()) break;
            const trimmed = std.mem.trim(u8, line_buffer.items, " \t\r\n");
            defer line_buffer.clearRetainingCapacity();
            if (trimmed.len == 0) continue;
            const response = handleJsonRpcLine(self.allocator, state, trimmed) catch |err| {
                const message = try std.fmt.allocPrint(self.allocator, "[app-server] failed to handle message: {s}\n", .{@errorName(err)});
                defer self.allocator.free(message);
                try cli_utils.writeStderr(message);
                continue;
            };
            try writePreResponseNotificationsStream(self.allocator, state, &writer.interface);
            if (response) |payload| {
                defer self.allocator.free(payload);
                try writeStreamLineWithConnection(state.connection_output, &writer.interface, payload);
            }
            try flushAppServerIdleWorkStream(self.allocator, state, &writer.interface);
        }
    }
};

const WebSocketServer = struct {
    allocator: std.mem.Allocator,
    address: WebSocketListen,
    auth_policy: WebsocketAuthPolicy = .none,
    invocation_options: InvocationOptions = .{},

    fn run(self: *WebSocketServer) !void {
        const shutdown_handlers = try AppServerShutdownSignalHandlers.install();
        defer shutdown_handlers.deinit();

        const io = std.Io.Threaded.global_single_threaded.io();
        var address = net.IpAddress.parse(self.address.host, self.address.port) catch return error.UnsupportedAppServerListenUrl;
        var server = try address.listen(io, .{ .reuse_address = true });
        defer server.deinit(io);
        try setFdNonblocking(server.socket.handle, true);

        const actual_port = server.socket.address.getPort();
        const bind_message = try std.fmt.allocPrint(self.allocator, "app-server websocket listening on ws://{s}:{d}\n", .{ self.address.host, actual_port });
        defer self.allocator.free(bind_message);
        try cli_utils.writeStderr(bind_message);

        var state = try initAppServerState(self.allocator, self.invocation_options, false);
        defer state.deinit(self.allocator);

        while (!appServerShutdownRequested()) {
            const stream_or_null = try acceptAppServerStream(&server, &shutdown_handlers, appServerDaemonAcceptPollTimeoutMs(&state));
            if (stream_or_null == null) {
                if (appServerShutdownRequested()) break;
                try reapExpiredThreadUnloads(self.allocator, &state, false);
                continue;
            }
            var stream = stream_or_null.?;
            self.handleConnection(&state, io, &stream) catch |err| {
                if (!appServerShutdownRequested()) {
                    const message = std.fmt.allocPrint(
                        self.allocator,
                        "[app-server] websocket connection error: {s}\n",
                        .{@errorName(err)},
                    ) catch null;
                    if (message) |stderr_message| {
                        defer self.allocator.free(stderr_message);
                        cli_utils.writeStderr(stderr_message) catch {};
                    }
                }
                stream.close(io);
                continue;
            };
            stream.close(io);
        }
    }

    fn handleConnection(
        self: *WebSocketServer,
        state: *AppServerState,
        io: std.Io,
        stream: *net.Stream,
    ) !void {
        app_server_shutdown_active_connection_fd.store(stream.socket.handle, .release);
        defer app_server_shutdown_active_connection_fd.store(-1, .release);
        if (appServerShutdownRequested()) return;
        defer clearAppServerConnectionStateAfterDisconnect(self.allocator, state);

        var input_buffer: [64 * 1024]u8 = undefined;
        var output_buffer: [64 * 1024]u8 = undefined;
        var reader = stream.reader(io, &input_buffer);
        var writer = stream.writer(io, &output_buffer);
        var http_server: std.http.Server = .init(&reader.interface, &writer.interface);
        var request = http_server.receiveHead() catch |err| switch (err) {
            error.HttpConnectionClosing => return,
            else => return err,
        };

        if (websocketHeaderValue(&request, "origin") != null) {
            try request.respond("Forbidden\n", .{ .status = .forbidden });
            return;
        }

        if (std.mem.eql(u8, request.head.target, "/readyz") or std.mem.eql(u8, request.head.target, "/healthz")) {
            try request.respond("OK\n", .{
                .status = .ok,
                .extra_headers = &.{
                    .{ .name = "Content-Type", .value = "text/plain; charset=utf-8" },
                    .{ .name = "Connection", .value = "close" },
                },
            });
            return;
        }

        if (request.head.method != .GET) {
            try request.respond("Not Found\n", .{ .status = .not_found });
            return;
        }

        const websocket_key = websocketHeaderValue(&request, "sec-websocket-key") orelse {
            try request.respond("Bad Request\n", .{ .status = .bad_request });
            return;
        };
        if (!websocketHeaderEquals(&request, "upgrade", "websocket") or
            !websocketConnectionIncludesUpgrade(&request) or
            !websocketHeaderEquals(&request, "sec-websocket-version", "13"))
        {
            try request.respond("Bad Request\n", .{ .status = .bad_request });
            return;
        }
        if (!websocketAuthorizeUpgrade(self.allocator, &request, self.auth_policy)) {
            try request.respond("Unauthorized\n", .{ .status = .unauthorized });
            return;
        }
        const accept = try websocketAcceptValue(self.allocator, websocket_key);
        defer self.allocator.free(accept);

        try writer.interface.print(
            "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {s}\r\n\r\n",
            .{accept},
        );
        try writer.interface.flush();

        const output_state = try createAppServerConnectionOutput(self.allocator, .websocket, stream.socket.handle);
        defer closeAppServerConnectionOutput(self.allocator, output_state);
        var transport_context = JsonRpcTransportContext{
            .kind = .websocket,
            .reader = &reader.interface,
            .read_fd = stream.socket.handle,
            .writer = &writer.interface,
            .output = output_state,
        };
        state.server_request_transport = .{
            .ctx = &transport_context,
            .send_payload = sendJsonRpcTransportPayload,
            .read_payload = readJsonRpcTransportPayload,
            .read_payload_with_timeout = readJsonRpcTransportPayloadWithTimeout,
        };
        defer state.server_request_transport = null;
        state.connection_output = output_state;
        defer state.connection_output = null;
        try reapExpiredThreadUnloads(self.allocator, state, false);

        while (!appServerShutdownRequested()) {
            if (!readerHasBufferedTransportBytes(&reader.interface) and
                !try appServerConnectionReadable(stream.socket.handle, appServerConnectionPollTimeoutMs(state)))
            {
                try flushAppServerIdleWorkWebSocket(self.allocator, state, &writer.interface);
                continue;
            }
            switch (try readWebSocketFrame(self.allocator, &reader.interface, &writer.interface, state.connection_output)) {
                .text => |payload| {
                    defer self.allocator.free(payload);
                    const trimmed = std.mem.trim(u8, payload, " \t\r\n");
                    if (trimmed.len == 0) continue;

                    const response = handleJsonRpcLine(self.allocator, state, trimmed) catch |err| {
                        const message = try std.fmt.allocPrint(self.allocator, "[app-server] failed to handle websocket message: {s}\n", .{@errorName(err)});
                        defer self.allocator.free(message);
                        try cli_utils.writeStderr(message);
                        continue;
                    };
                    try writePreResponseNotificationsWebSocket(self.allocator, state, &writer.interface);
                    if (response) |payload_response| {
                        defer self.allocator.free(payload_response);
                        try writeWebSocketTextFrameWithConnection(state.connection_output, &writer.interface, payload_response);
                    }
                    try flushAppServerIdleWorkWebSocket(self.allocator, state, &writer.interface);
                },
                .closed => return,
                .control => {
                    try flushAppServerIdleWorkWebSocket(self.allocator, state, &writer.interface);
                    continue;
                },
            }
        }
    }
};

fn websocketHeaderValue(request: *const std.http.Server.Request, name: []const u8) ?[]const u8 {
    var iter = request.iterateHeaders();
    while (iter.next()) |header| {
        if (std.ascii.eqlIgnoreCase(header.name, name)) return std.mem.trim(u8, header.value, " \t\r\n");
    }
    return null;
}

fn websocketHeaderEquals(request: *const std.http.Server.Request, name: []const u8, expected: []const u8) bool {
    const value = websocketHeaderValue(request, name) orelse return false;
    return std.ascii.eqlIgnoreCase(value, expected);
}

fn websocketConnectionIncludesUpgrade(request: *const std.http.Server.Request) bool {
    const value = websocketHeaderValue(request, "connection") orelse return false;
    var parts = std.mem.splitScalar(u8, value, ',');
    while (parts.next()) |part| {
        const token = std.mem.trim(u8, part, " \t\r\n");
        if (std.ascii.eqlIgnoreCase(token, "upgrade")) return true;
    }
    return false;
}

fn websocketAuthorizeUpgrade(allocator: std.mem.Allocator, request: *const std.http.Server.Request, policy: WebsocketAuthPolicy) bool {
    switch (policy) {
        .none => return true,
        .capability_token => |expected_digest| {
            const token = websocketBearerToken(request) orelse return false;
            var actual_digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(token, &actual_digest, .{});
            return websocketConstantTimeEqual(&expected_digest, &actual_digest);
        },
        .signed_bearer_token => |signed_policy| {
            const token = websocketBearerToken(request) orelse return false;
            return websocketVerifySignedBearerToken(allocator, token, signed_policy) catch false;
        },
    }
}

fn websocketBearerToken(request: *const std.http.Server.Request) ?[]const u8 {
    const value = websocketHeaderValue(request, "authorization") orelse return null;
    const separator = std.mem.indexOfScalar(u8, value, ' ') orelse return null;
    const scheme = value[0..separator];
    if (!std.ascii.eqlIgnoreCase(scheme, "Bearer")) return null;
    const token = std.mem.trim(u8, value[separator + 1 ..], " \t\r\n");
    if (token.len == 0) return null;
    return token;
}

fn websocketConstantTimeEqual(a: *const [std.crypto.hash.sha2.Sha256.digest_length]u8, b: *const [std.crypto.hash.sha2.Sha256.digest_length]u8) bool {
    return websocketConstantTimeEqualBytes(a[0..], b[0..]);
}

fn websocketConstantTimeEqualBytes(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    var difference: u8 = 0;
    for (a, b) |left, right| {
        difference |= left ^ right;
    }
    return difference == 0;
}

fn websocketVerifySignedBearerToken(allocator: std.mem.Allocator, token: []const u8, policy: SignedWebsocketBearerPolicy) !bool {
    const first_dot = std.mem.indexOfScalar(u8, token, '.') orelse return false;
    const second_dot_offset = std.mem.indexOfScalar(u8, token[first_dot + 1 ..], '.') orelse return false;
    const second_dot = first_dot + 1 + second_dot_offset;
    if (std.mem.indexOfScalar(u8, token[second_dot + 1 ..], '.') != null) return false;

    const header_segment = token[0..first_dot];
    const payload_segment = token[first_dot + 1 .. second_dot];
    const signature_segment = token[second_dot + 1 ..];
    if (!try websocketJwtHeaderIsHs256(allocator, header_segment)) return false;
    if (!try websocketJwtSignatureMatches(allocator, token[0..second_dot], signature_segment, policy.shared_secret)) return false;
    return try websocketJwtClaimsAreValid(allocator, payload_segment, policy);
}

fn websocketJwtHeaderIsHs256(allocator: std.mem.Allocator, segment: []const u8) !bool {
    const decoded = websocketBase64UrlDecodeAlloc(allocator, segment) catch return false;
    defer allocator.free(decoded);
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, decoded, .{}) catch return false;
    defer parsed.deinit();
    if (parsed.value != .object) return false;
    const alg = websocketJsonStringField(parsed.value.object, "alg") orelse return false;
    return std.mem.eql(u8, alg, "HS256");
}

fn websocketJwtSignatureMatches(allocator: std.mem.Allocator, signing_input: []const u8, signature_segment: []const u8, shared_secret: []const u8) !bool {
    const signature = websocketBase64UrlDecodeAlloc(allocator, signature_segment) catch return false;
    defer allocator.free(signature);
    const HmacSha256 = std.crypto.auth.hmac.sha2.HmacSha256;
    if (signature.len != HmacSha256.mac_length) return false;
    var expected: [HmacSha256.mac_length]u8 = undefined;
    HmacSha256.create(expected[0..], signing_input, shared_secret);
    return websocketConstantTimeEqualBytes(expected[0..], signature);
}

fn websocketJwtClaimsAreValid(allocator: std.mem.Allocator, segment: []const u8, policy: SignedWebsocketBearerPolicy) !bool {
    const decoded = websocketBase64UrlDecodeAlloc(allocator, segment) catch return false;
    defer allocator.free(decoded);
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, decoded, .{}) catch return false;
    defer parsed.deinit();
    if (parsed.value != .object) return false;
    const object = parsed.value.object;

    const exp = websocketJsonI64Field(object, "exp") orelse return false;
    const now = websocketCurrentEpochSeconds();
    if (now > websocketSaturatingAddNonNegative(exp, policy.max_clock_skew_seconds)) return false;
    if (websocketJsonI64Field(object, "nbf")) |nbf| {
        if (now < websocketSaturatingSubNonNegative(nbf, policy.max_clock_skew_seconds)) return false;
    }
    if (policy.issuer) |expected_issuer| {
        const issuer = websocketJsonStringField(object, "iss") orelse return false;
        if (!std.mem.eql(u8, issuer, expected_issuer)) return false;
    }
    if (policy.audience) |expected_audience| {
        const audience = object.get("aud") orelse return false;
        if (!websocketJwtAudienceMatches(audience, expected_audience)) return false;
    }
    return true;
}

fn websocketBase64UrlDecodeAlloc(allocator: std.mem.Allocator, segment: []const u8) ![]u8 {
    const decoded_len = try std.base64.url_safe_no_pad.Decoder.calcSizeForSlice(segment);
    const decoded = try allocator.alloc(u8, decoded_len);
    errdefer allocator.free(decoded);
    try std.base64.url_safe_no_pad.Decoder.decode(decoded, segment);
    return decoded;
}

fn websocketJsonStringField(object: std.json.ObjectMap, key: []const u8) ?[]const u8 {
    const value = object.get(key) orelse return null;
    if (value != .string) return null;
    return value.string;
}

fn websocketJsonI64Field(object: std.json.ObjectMap, key: []const u8) ?i64 {
    const value = object.get(key) orelse return null;
    if (value != .integer) return null;
    return value.integer;
}

fn websocketJwtAudienceMatches(value: std.json.Value, expected: []const u8) bool {
    switch (value) {
        .string => |actual| return std.mem.eql(u8, actual, expected),
        .array => |array| {
            for (array.items) |item| {
                if (item == .string and std.mem.eql(u8, item.string, expected)) return true;
            }
            return false;
        },
        else => return false,
    }
}

fn websocketCurrentEpochSeconds() i64 {
    const now = std.Io.Timestamp.now(std.Io.Threaded.global_single_threaded.io(), .real);
    const seconds = now.toSeconds();
    if (seconds > std.math.maxInt(i64)) return std.math.maxInt(i64);
    return @intCast(seconds);
}

fn websocketSaturatingAddNonNegative(value: i64, delta: i64) i64 {
    if (delta <= 0) return value;
    if (value > std.math.maxInt(i64) - delta) return std.math.maxInt(i64);
    return value + delta;
}

fn websocketSaturatingSubNonNegative(value: i64, delta: i64) i64 {
    if (delta <= 0) return value;
    if (value < std.math.minInt(i64) + delta) return std.math.minInt(i64);
    return value - delta;
}

fn websocketAcceptValue(allocator: std.mem.Allocator, key: []const u8) ![]const u8 {
    const magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
    const combined = try std.fmt.allocPrint(allocator, "{s}{s}", .{ key, magic });
    defer allocator.free(combined);
    var digest: [std.crypto.hash.Sha1.digest_length]u8 = undefined;
    std.crypto.hash.Sha1.hash(combined, &digest, .{});
    const encoded_len = std.base64.standard.Encoder.calcSize(digest.len);
    const encoded = try allocator.alloc(u8, encoded_len);
    _ = std.base64.standard.Encoder.encode(encoded, &digest);
    return encoded;
}

const WebSocketReadResult = union(enum) {
    text: []const u8,
    closed,
    control,
};

fn readWebSocketFrame(
    allocator: std.mem.Allocator,
    reader: *std.Io.Reader,
    writer: *std.Io.Writer,
    output: ?*AppServerConnectionOutputState,
) !WebSocketReadResult {
    const first = reader.takeByte() catch |err| switch (err) {
        error.EndOfStream => return .closed,
        else => return err,
    };
    const second = try reader.takeByte();
    const fin = (first & 0x80) != 0;
    const opcode = first & 0x0f;
    const masked = (second & 0x80) != 0;
    var payload_len: u64 = second & 0x7f;
    if (payload_len == 126) {
        payload_len = try reader.takeInt(u16, .big);
    } else if (payload_len == 127) {
        payload_len = try reader.takeInt(u64, .big);
    }
    if (!fin) return error.UnsupportedWebSocketFragment;
    if (!masked) return error.UnmaskedWebSocketClientFrame;
    if (payload_len > 16 * 1024 * 1024) return error.WebSocketFrameTooLarge;

    const mask = try reader.takeArray(4);
    const payload = try allocator.alloc(u8, @intCast(payload_len));
    errdefer allocator.free(payload);
    try reader.readSliceAll(payload);
    for (payload, 0..) |*byte, index| {
        byte.* ^= mask[index % 4];
    }

    switch (opcode) {
        0x1 => return .{ .text = payload },
        0x8 => {
            try writeWebSocketFrameWithConnection(output, writer, 0x8, payload);
            allocator.free(payload);
            return .closed;
        },
        0x9 => {
            try writeWebSocketFrameWithConnection(output, writer, 0xA, payload);
            allocator.free(payload);
            return .control;
        },
        0xA => {
            allocator.free(payload);
            return .control;
        },
        else => return error.UnsupportedWebSocketOpcode,
    }
}

fn readWebSocketTextFrame(
    allocator: std.mem.Allocator,
    reader: *std.Io.Reader,
    writer: *std.Io.Writer,
    output: ?*AppServerConnectionOutputState,
) !?[]const u8 {
    while (true) {
        switch (try readWebSocketFrame(allocator, reader, writer, output)) {
            .text => |payload| return payload,
            .closed => return null,
            .control => continue,
        }
    }
}

fn writeWebSocketTextFrame(writer: *std.Io.Writer, payload: []const u8) !void {
    try writeWebSocketFrame(writer, 0x1, payload);
}

fn writeWebSocketFrame(writer: *std.Io.Writer, opcode: u8, payload: []const u8) !void {
    try writer.writeByte(0x80 | (opcode & 0x0f));
    if (payload.len <= 125) {
        try writer.writeByte(@intCast(payload.len));
    } else if (payload.len <= std.math.maxInt(u16)) {
        try writer.writeByte(126);
        try writer.writeInt(u16, @intCast(payload.len), .big);
    } else {
        try writer.writeByte(127);
        try writer.writeInt(u64, @intCast(payload.len), .big);
    }
    try writer.writeAll(payload);
    try writer.flush();
}

fn sendJsonRpcTransportPayload(ctx: *anyopaque, payload: []const u8) !void {
    const context: *JsonRpcTransportContext = @ptrCast(@alignCast(ctx));
    switch (context.kind) {
        .stdout_line => try writeStdoutLine(payload),
        .stream_line => try writeStreamLineWithConnection(context.output, context.writer orelse return error.AppServerTransportMissingWriter, payload),
        .websocket => try writeWebSocketTextFrameWithConnection(context.output, context.writer orelse return error.AppServerTransportMissingWriter, payload),
    }
}

fn readJsonRpcTransportPayload(ctx: *anyopaque, allocator: std.mem.Allocator) !?[]const u8 {
    const context: *JsonRpcTransportContext = @ptrCast(@alignCast(ctx));
    switch (context.kind) {
        .stdout_line, .stream_line => {
            const line = try context.reader.takeDelimiter('\n') orelse return null;
            const trimmed = std.mem.trim(u8, line, " \t\r\n");
            return try allocator.dupe(u8, trimmed);
        },
        .websocket => {
            const writer = context.writer orelse return error.AppServerTransportMissingWriter;
            const payload = try readWebSocketTextFrame(allocator, context.reader, writer, context.output) orelse return null;
            errdefer allocator.free(payload);
            const trimmed = std.mem.trim(u8, payload, " \t\r\n");
            if (trimmed.len == payload.len) return payload;
            const owned = try allocator.dupe(u8, trimmed);
            allocator.free(payload);
            return owned;
        },
    }
}

fn readJsonRpcTransportPayloadWithTimeout(ctx: *anyopaque, allocator: std.mem.Allocator, timeout_ms: u64) !TimedTransportPayload {
    const context: *JsonRpcTransportContext = @ptrCast(@alignCast(ctx));
    const deadline_ms = appServerAwakeDeadlineMs(timeout_ms);
    return switch (context.kind) {
        .stdout_line, .stream_line => readJsonRpcLineTransportPayloadWithDeadline(context, allocator, deadline_ms),
        .websocket => readJsonRpcWebSocketTransportPayloadWithDeadline(context, allocator, deadline_ms),
    };
}

fn readJsonRpcLineTransportPayloadWithDeadline(
    context: *JsonRpcTransportContext,
    allocator: std.mem.Allocator,
    deadline_ms: i64,
) !TimedTransportPayload {
    var line = std.ArrayList(u8).empty;
    errdefer line.deinit(allocator);

    while (true) {
        switch (try takeReaderByteWithDeadline(context, deadline_ms)) {
            .byte => |byte| {
                if (byte == '\n') {
                    const trimmed = std.mem.trim(u8, line.items, " \t\r\n");
                    const payload = try allocator.dupe(u8, trimmed);
                    line.deinit(allocator);
                    return .{ .payload = payload };
                }
                if (line.items.len >= max_app_server_json_rpc_line_bytes) return error.StreamTooLong;
                try line.append(allocator, byte);
            },
            .closed => {
                if (line.items.len == 0) {
                    line.deinit(allocator);
                    return .closed;
                }
                const trimmed = std.mem.trim(u8, line.items, " \t\r\n");
                const payload = try allocator.dupe(u8, trimmed);
                line.deinit(allocator);
                return .{ .payload = payload };
            },
            .timed_out => {
                line.deinit(allocator);
                return .timed_out;
            },
        }
    }
}

fn readJsonRpcWebSocketTransportPayloadWithDeadline(
    context: *JsonRpcTransportContext,
    allocator: std.mem.Allocator,
    deadline_ms: i64,
) !TimedTransportPayload {
    while (true) {
        const first = switch (try takeReaderByteWithDeadline(context, deadline_ms)) {
            .byte => |byte| byte,
            .closed => return .closed,
            .timed_out => return .timed_out,
        };
        const second = switch (try takeReaderByteWithDeadline(context, deadline_ms)) {
            .byte => |byte| byte,
            .closed => return .closed,
            .timed_out => return .timed_out,
        };
        const fin = (first & 0x80) != 0;
        const opcode = first & 0x0f;
        const masked = (second & 0x80) != 0;
        var payload_len: u64 = second & 0x7f;
        if (payload_len == 126) {
            var len_bytes: [2]u8 = undefined;
            switch (try readReaderBytesWithDeadline(context, deadline_ms, &len_bytes)) {
                .ok => {},
                .closed => return .closed,
                .timed_out => return .timed_out,
            }
            payload_len = std.mem.readInt(u16, &len_bytes, .big);
        } else if (payload_len == 127) {
            var len_bytes: [8]u8 = undefined;
            switch (try readReaderBytesWithDeadline(context, deadline_ms, &len_bytes)) {
                .ok => {},
                .closed => return .closed,
                .timed_out => return .timed_out,
            }
            payload_len = std.mem.readInt(u64, &len_bytes, .big);
        }
        if (!fin) return error.UnsupportedWebSocketFragment;
        if (!masked) return error.UnmaskedWebSocketClientFrame;
        if (payload_len > 16 * 1024 * 1024) return error.WebSocketFrameTooLarge;

        var mask: [4]u8 = undefined;
        switch (try readReaderBytesWithDeadline(context, deadline_ms, &mask)) {
            .ok => {},
            .closed => return .closed,
            .timed_out => return .timed_out,
        }

        const payload = try allocator.alloc(u8, @intCast(payload_len));
        errdefer allocator.free(payload);
        for (payload, 0..) |*byte, index| {
            byte.* = switch (try takeReaderByteWithDeadline(context, deadline_ms)) {
                .byte => |value| value ^ mask[index % 4],
                .closed => {
                    allocator.free(payload);
                    return .closed;
                },
                .timed_out => {
                    allocator.free(payload);
                    return .timed_out;
                },
            };
        }

        const writer = context.writer orelse return error.AppServerTransportMissingWriter;
        switch (opcode) {
            0x1 => return .{ .payload = try trimOwnedTransportPayload(allocator, payload) },
            0x8 => {
                try writeWebSocketFrameWithConnection(context.output, writer, 0x8, payload);
                allocator.free(payload);
                return .closed;
            },
            0x9 => {
                try writeWebSocketFrameWithConnection(context.output, writer, 0xA, payload);
                allocator.free(payload);
                continue;
            },
            0xA => {
                allocator.free(payload);
                continue;
            },
            else => {
                return error.UnsupportedWebSocketOpcode;
            },
        }
    }
}

const TimedTransportReadStatus = enum {
    ok,
    closed,
    timed_out,
};

fn readReaderBytesWithDeadline(context: *JsonRpcTransportContext, deadline_ms: i64, dest: []u8) !TimedTransportReadStatus {
    for (dest) |*byte| {
        byte.* = switch (try takeReaderByteWithDeadline(context, deadline_ms)) {
            .byte => |value| value,
            .closed => return .closed,
            .timed_out => return .timed_out,
        };
    }
    return .ok;
}

const TimedTransportByte = union(enum) {
    byte: u8,
    closed,
    timed_out,
};

fn takeReaderByteWithDeadline(context: *JsonRpcTransportContext, deadline_ms: i64) !TimedTransportByte {
    if (!readerHasBufferedTransportBytes(context.reader)) {
        if (!try jsonRpcTransportPayloadReady(context, deadline_ms)) return .timed_out;
    }
    const byte = context.reader.takeByte() catch |err| switch (err) {
        error.EndOfStream => return .closed,
        else => return err,
    };
    return .{ .byte = byte };
}

fn jsonRpcTransportPayloadReady(context: *const JsonRpcTransportContext, deadline_ms: i64) !bool {
    if (readerHasBufferedTransportBytes(context.reader)) return true;
    const remaining_ms = remainingAppServerAwakeMillis(deadline_ms) orelse return false;

    var fds = [_]std.posix.pollfd{
        .{ .fd = context.read_fd, .events = @intCast(std.posix.POLL.IN), .revents = 0 },
    };
    const max_poll_timeout_ms: u64 = @intCast(std.math.maxInt(i32));
    const poll_timeout: i32 = if (remaining_ms > max_poll_timeout_ms) std.math.maxInt(i32) else @intCast(remaining_ms);
    const ready = try std.posix.poll(&fds, poll_timeout);
    if (ready == 0) return false;
    return pollReventsInclude(fds[0].revents, std.posix.POLL.IN | std.posix.POLL.HUP | std.posix.POLL.ERR | std.posix.POLL.NVAL);
}

fn trimOwnedTransportPayload(allocator: std.mem.Allocator, payload: []u8) ![]const u8 {
    const trimmed = std.mem.trim(u8, payload, " \t\r\n");
    if (trimmed.len == payload.len) return payload;
    const owned = try allocator.dupe(u8, trimmed);
    allocator.free(payload);
    return owned;
}

fn readerHasBufferedTransportBytes(reader: *const std.Io.Reader) bool {
    return reader.seek < reader.end;
}

fn appServerAwakeDeadlineMs(timeout_ms: u64) i64 {
    const now = currentAppServerAwakeMillis();
    const delta = std.math.cast(i64, timeout_ms) orelse std.math.maxInt(i64);
    if (delta > std.math.maxInt(i64) - now) return std.math.maxInt(i64);
    return now + delta;
}

fn remainingAppServerAwakeMillis(deadline_ms: i64) ?u64 {
    const now = currentAppServerAwakeMillis();
    if (now >= deadline_ms) return null;
    return @intCast(deadline_ms - now);
}

fn currentAppServerAwakeMillis() i64 {
    const now_ns = std.Io.Timestamp.now(std.Io.Threaded.global_single_threaded.io(), .awake).nanoseconds;
    return @intCast(@divTrunc(now_ns, std.time.ns_per_ms));
}

fn handleJsonRpcLine(allocator: std.mem.Allocator, state: *AppServerState, line: []const u8) !?[]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, line, .{}) catch {
        return try renderJsonRpcError(allocator, null, -32700, "Parse error");
    };
    defer parsed.deinit();

    if (parsed.value != .object) {
        return try renderJsonRpcError(allocator, null, -32600, "Invalid Request");
    }

    const object = parsed.value.object;
    const id_value = object.get("id");
    const method_value = object.get("method") orelse {
        if (isJsonRpcResponseEnvelope(object)) {
            try handleJsonRpcResponseEnvelope(allocator, state, object);
            return null;
        }
        return try renderJsonRpcError(allocator, id_value, -32600, "Invalid Request");
    };
    if (method_value != .string) {
        return try renderJsonRpcError(allocator, id_value, -32600, "Invalid Request");
    }
    if (id_value == null) return null;

    const method = method_value.string;
    if (std.mem.eql(u8, method, "initialize")) {
        try updateInitializeCapabilities(allocator, state, object.get("params"));
        try queueInitializeConfigWarningNotifications(allocator, state);
        try queueInitialRemoteControlStatusNotification(allocator, state);
        const result = try renderInitializeResult(allocator);
        defer allocator.free(result);
        return try renderJsonRpcResult(allocator, id_value.?, result);
    }
    if (isEnvironmentMethod(method)) {
        if (try validateEnvironmentRequestParams(allocator, method, object.get("params"))) |message| {
            defer allocator.free(message);
            return try renderJsonRpcError(allocator, id_value, -32600, message);
        }
    }
    if (experimentalReasonForRequestMethod(method)) |reason| {
        if (!state.experimental_api_enabled) {
            return try renderExperimentalApiRequiredError(allocator, id_value, reason);
        }
    }
    if (experimentalReasonForRequestFields(method, object.get("params"))) |reason| {
        if (!state.experimental_api_enabled) {
            return try renderExperimentalApiRequiredError(allocator, id_value, reason);
        }
    }
    if (isRemoteControlMethod(method)) {
        return try handleRemoteControlMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isEnvironmentMethod(method)) {
        return try handleEnvironmentMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (std.mem.eql(u8, method, "memory/reset")) {
        return try handleMemoryReset(allocator, state, id_value.?);
    }
    if (std.mem.eql(u8, method, "getConversationSummary")) {
        return try handleGetConversationSummary(allocator, state, id_value.?, object.get("params"));
    }
    if (std.mem.eql(u8, method, "gitDiffToRemote")) {
        return try handleGitDiffToRemote(allocator, id_value.?, object.get("params"));
    }
    if (std.mem.eql(u8, method, "fuzzyFileSearch")) {
        return try handleFuzzyFileSearch(allocator, id_value.?, object.get("params"));
    }
    if (std.mem.eql(u8, method, "app/list")) {
        return try handleAppsList(allocator, state, id_value.?, object.get("params"));
    }
    if (std.mem.eql(u8, method, "app/read")) {
        return try handleAppsRead(allocator, id_value.?, object.get("params"));
    }
    if (std.mem.eql(u8, method, "app/installed")) {
        return try handleAppsInstalled(allocator, state, id_value.?, object.get("params"));
    }
    if (isReviewMethod(method)) {
        return try handleReviewMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isTurnMethod(method)) {
        return try handleTurnMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isThreadMethod(method)) {
        return try handleThreadMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isFuzzyFileSearchSessionMethod(method)) {
        return try handleFuzzyFileSearchSessionMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isMarketplaceMethod(method)) {
        return try handleMarketplaceMethod(allocator, id_value.?, method, object.get("params"));
    }
    if (isPluginMethod(method)) {
        return try handlePluginMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (std.mem.eql(u8, method, "hooks/list")) {
        return try handleHooksList(allocator, id_value.?, object.get("params"));
    }
    if (std.mem.eql(u8, method, "skills/list")) {
        return try handleSkillsList(allocator, state, id_value.?, object.get("params"));
    }
    if (std.mem.eql(u8, method, "skills/extraRoots/set")) {
        return try handleSkillsExtraRootsSet(allocator, state, id_value.?, object.get("params"));
    }
    if (std.mem.eql(u8, method, "skills/config/write")) {
        return try handleSkillsConfigWrite(allocator, state, id_value.?, object.get("params"));
    }
    if (isFsMethod(method)) {
        return try handleFsMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isCommandExecMethod(method)) {
        return try handleCommandExecMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isFeedbackMethod(method)) {
        return try handleFeedbackMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isConfigMethod(method)) {
        return try handleConfigMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isAccountMethod(method)) {
        return try handleAccountMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isModelMethod(method)) {
        return try handleModelMethod(allocator, id_value.?, method, object.get("params"));
    }
    if (isCollaborationModeMethod(method)) {
        return try handleCollaborationModeMethod(allocator, id_value.?, method, object.get("params"));
    }
    if (isPermissionProfileMethod(method)) {
        return try handlePermissionProfileMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isExperimentalFeatureMethod(method)) {
        return try handleExperimentalFeatureMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isMcpServerMethod(method)) {
        return try handleMcpServerMethod(allocator, state, id_value.?, method, object.get("params"));
    }
    if (isWindowsSandboxMethod(method)) {
        return try handleWindowsSandboxMethod(allocator, state, id_value.?, method, object.get("params"));
    }

    const message = try std.fmt.allocPrint(allocator, "unsupported app-server method: {s}", .{method});
    defer allocator.free(message);
    return try renderJsonRpcError(allocator, id_value, -32601, message);
}

fn isJsonRpcResponseEnvelope(object: std.json.ObjectMap) bool {
    const id_value = object.get("id") orelse return false;
    if (!isJsonRpcRequestIdValue(id_value)) return false;
    const has_result = object.get("result") != null;
    const error_value = object.get("error");
    if (has_result) return error_value == null;
    const error_object = error_value orelse return false;
    return isJsonRpcErrorValue(error_object);
}

fn isJsonRpcRequestIdValue(value: std.json.Value) bool {
    return switch (value) {
        .string, .integer => true,
        else => false,
    };
}

fn isJsonRpcErrorValue(value: std.json.Value) bool {
    if (value != .object) return false;
    const object = value.object;
    const code_value = object.get("code") orelse return false;
    if (code_value != .integer) return false;
    const message_value = object.get("message") orelse return false;
    return message_value == .string;
}

fn handleJsonRpcResponseEnvelope(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    object: std.json.ObjectMap,
) !void {
    const id_value = object.get("id") orelse return;
    const request_id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    defer allocator.free(request_id_json);

    var pending = takePendingServerRequest(state, request_id_json) orelse return;
    defer pending.deinit(allocator);

    const notification = try renderServerRequestResolvedNotification(allocator, pending.thread_id, pending.request_id_json);
    try queuePendingServerNotification(allocator, state, "serverRequest/resolved", notification);
}

fn trackPendingServerRequest(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    request_json: []const u8,
) !void {
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, request_json, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidServerRequest;
    const object = parsed.value.object;
    const id_value = object.get("id") orelse return error.InvalidServerRequest;
    if (!isJsonRpcRequestIdValue(id_value)) return error.InvalidServerRequest;
    const params_value = object.get("params") orelse return error.InvalidServerRequest;
    if (params_value != .object) return error.InvalidServerRequest;
    const thread_id_value = params_value.object.get("threadId") orelse return error.InvalidServerRequest;
    if (thread_id_value != .string or thread_id_value.string.len == 0) return error.InvalidServerRequest;

    const request_id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    errdefer allocator.free(request_id_json);
    const thread_id = try allocator.dupe(u8, thread_id_value.string);
    errdefer allocator.free(thread_id);

    if (takePendingServerRequest(state, request_id_json)) |existing_request| {
        var existing = existing_request;
        existing.deinit(allocator);
    }

    try state.pending_server_requests.append(allocator, .{
        .request_id_json = request_id_json,
        .thread_id = thread_id,
    });
}

fn trackPendingServerRequestWithThreadId(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    request_json: []const u8,
    thread_id_value: []const u8,
) !void {
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, request_json, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidServerRequest;
    const object = parsed.value.object;
    const id_value = object.get("id") orelse return error.InvalidServerRequest;
    if (!isJsonRpcRequestIdValue(id_value)) return error.InvalidServerRequest;
    if (thread_id_value.len == 0) return error.InvalidServerRequest;

    const request_id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    errdefer allocator.free(request_id_json);
    const thread_id = try allocator.dupe(u8, thread_id_value);
    errdefer allocator.free(thread_id);

    if (takePendingServerRequest(state, request_id_json)) |existing_request| {
        var existing = existing_request;
        existing.deinit(allocator);
    }

    try state.pending_server_requests.append(allocator, .{
        .request_id_json = request_id_json,
        .thread_id = thread_id,
    });
}

fn takePendingServerRequest(state: *AppServerState, request_id_json: []const u8) ?PendingServerRequest {
    for (state.pending_server_requests.items, 0..) |request, index| {
        if (std.mem.eql(u8, request.request_id_json, request_id_json)) {
            return state.pending_server_requests.orderedRemove(index);
        }
    }
    return null;
}

fn renderServerRequestResolvedNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    request_id_json: []const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"serverRequest/resolved\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"requestId\":");
    try notification.appendSlice(allocator, request_id_json);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

