        thread_id,
        null,
    )).?;
    defer allocator.free(response);

    try std.testing.expect(std.mem.indexOf(u8, response, "cannot process request while approval is pending") != null);
}

fn handleAppServerGoalTool(ctx: *anyopaque, call: api.FunctionCall) !tool_runner.ToolResult {
    const context: *AppServerGoalToolContext = @ptrCast(@alignCast(ctx));
    if (context.thread.ephemeral) {
        const message = try std.fmt.allocPrint(context.allocator, "ephemeral thread does not support goals: {s}", .{context.thread.id});
        defer context.allocator.free(message);
        return goalToolResult(context.allocator, call.call_id, "goal rejected", message);
    }

    if (std.mem.eql(u8, call.name, "get_goal")) {
        if (try refreshLoadedThreadGoalAccountingAndPersistAt(context.allocator, context.thread, currentUnixSeconds())) {
            _ = try saveLoadedThreadGoalToStateDb(context.allocator, context.sqlite_home, context.thread, false);
        }
        const output = try renderGoalToolResponse(context.allocator, context.thread, .omit);
        defer context.allocator.free(output);
        return goalToolResult(context.allocator, call.call_id, "goal read", output);
    }

    var parsed = std.json.parseFromSlice(std.json.Value, context.allocator, call.arguments, .{}) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return goalToolResult(context.allocator, call.call_id, "goal invalid", "goal tool arguments must be an object"),
    };
    defer parsed.deinit();
    if (parsed.value != .object) {
        return goalToolResult(context.allocator, call.call_id, "goal invalid", "goal tool arguments must be an object");
    }
    const object = parsed.value.object;

    if (std.mem.eql(u8, call.name, "create_goal")) {
        if (context.thread.goal != null) {
            return goalToolResult(context.allocator, call.call_id, "goal rejected", "cannot create a new goal because this thread already has a goal; use update_goal only when the existing goal is complete");
        }
        if (validateCreateGoalToolParams(object)) |message| {
            return goalToolResult(context.allocator, call.call_id, "goal invalid", message);
        }
        const replaced_goal = try setLoadedThreadGoal(context.allocator, context.thread, object);
        _ = try saveLoadedThreadGoalToStateDb(context.allocator, context.sqlite_home, context.thread, replaced_goal);
        try queueThreadGoalUpdatedTurnNotification(context);
        const output = try renderGoalToolResponse(context.allocator, context.thread, .omit);
        defer context.allocator.free(output);
        return goalToolResult(context.allocator, call.call_id, "goal created", output);
    }

    if (std.mem.eql(u8, call.name, "update_goal")) {
        if (validateUpdateGoalToolParams(object)) |message| {
            return goalToolResult(context.allocator, call.call_id, "goal invalid", message);
        }
        const replaced_goal = setLoadedThreadGoal(context.allocator, context.thread, object) catch |err| switch (err) {
            error.MissingThreadGoal => return goalToolResult(context.allocator, call.call_id, "goal rejected", "cannot update goal because this thread has no goal"),
            else => return err,
        };
        _ = try saveLoadedThreadGoalToStateDb(context.allocator, context.sqlite_home, context.thread, replaced_goal);
        try queueThreadGoalUpdatedTurnNotification(context);
        const output = try renderGoalToolResponse(context.allocator, context.thread, .include);
        defer context.allocator.free(output);
        return goalToolResult(context.allocator, call.call_id, "goal updated", output);
    }

    return goalToolResult(context.allocator, call.call_id, "unsupported goal tool", "unsupported goal tool");
}

fn goalToolResult(
    allocator: std.mem.Allocator,
    call_id: []const u8,
    summary: []const u8,
    output: []const u8,
) !tool_runner.ToolResult {
    return .{
        .call_id = try allocator.dupe(u8, call_id),
        .summary = try allocator.dupe(u8, summary),
        .output = try allocator.dupe(u8, output),
    };
}

fn validateCreateGoalToolParams(object: std.json.ObjectMap) ?[]const u8 {
    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        if (std.mem.eql(u8, entry.key_ptr.*, "objective")) continue;
        if (std.mem.eql(u8, entry.key_ptr.*, "token_budget")) continue;
        return "create_goal only accepts objective and token_budget";
    }

    const objective = object.get("objective") orelse return "goal objective is required";
    if (objective != .string) return "goal objective must be a string";
    const trimmed = std.mem.trim(u8, objective.string, " \t\r\n");
    if (trimmed.len == 0) return "goal objective must not be empty";
    const char_count = std.unicode.utf8CountCodepoints(trimmed) catch 4001;
    if (char_count > 4000) return "goal objective must be at most 4000 characters";
    return validateGoalToolBudget(object);
}

fn validateUpdateGoalToolParams(object: std.json.ObjectMap) ?[]const u8 {
    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        if (std.mem.eql(u8, entry.key_ptr.*, "status")) continue;
        return "update_goal only accepts status";
    }
    const status = object.get("status") orelse return "goal status is required";
    if (status != .string or !(std.mem.eql(u8, status.string, "complete") or std.mem.eql(u8, status.string, "blocked"))) {
        return "update_goal can only mark the existing goal complete or blocked; pause, resume, and budget-limited status changes are controlled by the user or system";
    }
    return null;
}

fn validateGoalToolBudget(object: std.json.ObjectMap) ?[]const u8 {
    const budget = object.get("token_budget") orelse return null;
    if (budget != .integer) return "goal token_budget must be a positive integer";
    if (budget.integer <= 0) return "goal budgets must be positive when provided";
    return null;
}

fn queueThreadGoalUpdatedTurnNotification(context: *AppServerGoalToolContext) !void {
    if (serverNotificationShouldBeDropped(context.state, "thread/goal/updated")) return;
    const notification = try renderThreadGoalUpdatedNotification(context.allocator, context.thread, context.turn_id);
    errdefer context.allocator.free(notification);
    try context.notifications.append(context.allocator, notification);
}

fn handleAppServerRequestPermissions(ctx: *anyopaque, request: session_mod.RequestPermissionsRequest) !session_mod.RequestPermissionsResult {
    const context: *AppServerRequestPermissionsContext = @ptrCast(@alignCast(ctx));
    try sendRequestPermissionsTurnStartResponse(context);

    const request_id = try std.fmt.allocPrint(context.allocator, "permissions-{s}", .{request.call_id});
    defer context.allocator.free(request_id);
    const request_id_json = try std.json.Stringify.valueAlloc(context.allocator, request_id, .{});
    defer context.allocator.free(request_id_json);

    const request_json = try renderPermissionsRequestApprovalRequest(
        context.allocator,
        request_id,
        context.thread.id,
        context.turn_id,
        request,
    );
    defer context.allocator.free(request_json);

    try trackPendingServerRequest(context.allocator, context.state, request_json);
    const active_wait_thread = try beginLoadedThreadActiveWait(context.allocator, context.state, context.transport, context.thread, .permission);
    defer if (active_wait_thread) |thread| decrementLoadedThreadActiveWait(thread, .permission);
    var pending_tracked = true;
    defer if (pending_tracked) {
        if (takePendingServerRequest(context.state, request_id_json)) |pending_request| {
            var pending = pending_request;
            pending.deinit(context.allocator);
        }
    };

    const visible_request = try renderServerRequestForConnection(context.allocator, context.state.experimental_api_enabled, request_json);
    defer context.allocator.free(visible_request);
    try context.transport.send_payload(context.transport.ctx, visible_request);

    while (true) {
        const payload = try context.transport.read_payload(context.transport.ctx, context.allocator) orelse return error.AppServerRequestPermissionsClientClosed;
        defer context.allocator.free(payload);
        if (payload.len == 0) continue;

        if (try requestPermissionsResultFromResponsePayload(context.allocator, payload, request_id_json, context.thread.cwd)) |parsed_result| {
            var result = parsed_result;
            errdefer result.deinit(context.allocator);
            try applySessionScopedRequestPermissions(context.allocator, context.thread, result);
            try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
            pending_tracked = false;
            return result;
        }

        if (try renderPendingApprovalInterruptResponse(context.allocator, payload, context.thread.id, context.turn_id)) |interrupt_response| {
            defer context.allocator.free(interrupt_response.payload);
            try context.transport.send_payload(context.transport.ctx, interrupt_response.payload);
            if (interrupt_response.cancel_approval) {
                try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
                pending_tracked = false;
                return emptyRequestPermissionsResult(context.allocator, "request_permissions was cancelled before receiving a response");
            }
            continue;
        }

        if (try renderPendingTurnSteerResponse(context.allocator, payload, context.state, context.thread, context.turn_id, context.pending_steers)) |response_payload| {
            defer context.allocator.free(response_payload);
            try context.transport.send_payload(context.transport.ctx, response_payload);
            continue;
        }

        if (try renderPendingApprovalJsonRpcResponse(context.allocator, payload, context.thread.id, context.turn_id)) |response_payload| {
            defer context.allocator.free(response_payload);
            try context.transport.send_payload(context.transport.ctx, response_payload);
        }
    }
}

fn sendRequestPermissionsTurnStartResponse(context: *AppServerRequestPermissionsContext) !void {
    if (context.turn_start_response_sent.*) return;
    try context.transport.send_payload(context.transport.ctx, context.turn_start_response_payload);
    context.turn_start_response_sent.* = true;
}

fn renderPermissionsRequestApprovalRequest(
    allocator: std.mem.Allocator,
    request_id: []const u8,
    thread_id: []const u8,
    turn_id: []const u8,
    request: session_mod.RequestPermissionsRequest,
) ![]const u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, request.arguments_json, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRequestPermissions;
    const permissions = parsed.value.object.get("permissions") orelse return error.InvalidRequestPermissions;
    if (permissions != .object) return error.InvalidRequestPermissions;
    const permissions_json = try renderRequestPermissionProfileJson(allocator, permissions, request.cwd);
    defer allocator.free(permissions_json);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"id\":");
    try appendJsonString(allocator, &out, request_id);
    try out.appendSlice(allocator, ",\"method\":\"item/permissions/requestApproval\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &out, thread_id);
    try out.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &out, turn_id);
    try out.appendSlice(allocator, ",\"itemId\":");
    try appendJsonString(allocator, &out, request.call_id);
    try out.appendSlice(allocator, ",\"cwd\":");
    try appendJsonString(allocator, &out, request.cwd);
    try out.appendSlice(allocator, ",\"reason\":");
    try appendOptionalJsonString(allocator, &out, request.reason);
    try out.appendSlice(allocator, ",\"permissions\":");
    try out.appendSlice(allocator, permissions_json);
    try out.appendSlice(allocator, "}}");
    return out.toOwnedSlice(allocator);
}

fn renderRequestPermissionProfileJson(
    allocator: std.mem.Allocator,
    permissions: std.json.Value,
    cwd: []const u8,
) ![]const u8 {
    if (permissions != .object) return error.InvalidRequestPermissions;
    const network_value = permissions.object.get("network");
    const file_system_value = permissions.object.get("fileSystem") orelse permissions.object.get("file_system");
    const network_json = try renderRequestPermissionNetworkJson(allocator, network_value);
    defer allocator.free(network_json);
    const file_system_json = try renderRequestPermissionFileSystemJson(allocator, file_system_value, cwd);
    defer allocator.free(file_system_json);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"network\":");
    try out.appendSlice(allocator, network_json);
    try out.appendSlice(allocator, ",\"fileSystem\":");
    try out.appendSlice(allocator, file_system_json);
    try out.appendSlice(allocator, "}");
    return out.toOwnedSlice(allocator);
}

fn renderRequestPermissionNetworkJson(
    allocator: std.mem.Allocator,
    network_value: ?std.json.Value,
) ![]const u8 {
    const network = network_value orelse return allocator.dupe(u8, "null");
    if (network == .null) return allocator.dupe(u8, "null");
    if (network != .object) return error.InvalidRequestPermissions;
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"enabled\":");
    if (network.object.get("enabled")) |enabled| {
        if (enabled == .bool) {
            try out.appendSlice(allocator, if (enabled.bool) "true" else "false");
        } else if (enabled == .null) {
            try out.appendSlice(allocator, "null");
        } else {
            return error.InvalidRequestPermissions;
        }
    } else {
        try out.appendSlice(allocator, "null");
    }
    try out.appendSlice(allocator, "}");
    return out.toOwnedSlice(allocator);
}

fn renderRequestPermissionFileSystemJson(
    allocator: std.mem.Allocator,
    file_system_value: ?std.json.Value,
    cwd: []const u8,
) ![]const u8 {
    const file_system = file_system_value orelse return allocator.dupe(u8, "null");
    if (file_system == .null) return allocator.dupe(u8, "null");
    if (file_system != .object) return error.InvalidRequestPermissions;

    var read_roots = std.ArrayList([]const u8).empty;
    defer deinitStringArrayList(allocator, &read_roots);
    var write_roots = std.ArrayList([]const u8).empty;
    defer deinitStringArrayList(allocator, &write_roots);
    try appendResolvedPermissionPaths(allocator, &read_roots, file_system.object.get("read"), cwd);
    try appendResolvedPermissionPaths(allocator, &write_roots, file_system.object.get("write"), cwd);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"read\":");
    try appendNullableJsonStringArray(allocator, &out, read_roots.items);
    try out.appendSlice(allocator, ",\"write\":");
    try appendNullableJsonStringArray(allocator, &out, write_roots.items);
    if (file_system.object.get("globScanMaxDepth")) |depth| {
        if (depth != .integer or depth.integer <= 0) return error.InvalidRequestPermissions;
        try out.appendSlice(allocator, ",\"globScanMaxDepth\":");
        const depth_json = try std.json.Stringify.valueAlloc(allocator, depth, .{});
        defer allocator.free(depth_json);
        try out.appendSlice(allocator, depth_json);
    }
    if (read_roots.items.len > 0 or write_roots.items.len > 0) {
        try out.appendSlice(allocator, ",\"entries\":[");
        var first = true;
        try appendPermissionPathEntries(allocator, &out, &first, read_roots.items, "read");
        try appendPermissionPathEntries(allocator, &out, &first, write_roots.items, "write");
        try out.appendSlice(allocator, "]");
    }
    try out.appendSlice(allocator, "}");
    return out.toOwnedSlice(allocator);
}

fn appendResolvedPermissionPaths(
    allocator: std.mem.Allocator,
    paths: *std.ArrayList([]const u8),
    value: ?std.json.Value,
    cwd: []const u8,
) !void {
    const array_value = value orelse return;
    if (array_value == .null) return;
    if (array_value != .array) return error.InvalidRequestPermissions;
    for (array_value.array.items) |item| {
        if (item != .string) return error.InvalidRequestPermissions;
        const resolved = if (std.fs.path.isAbsolute(item.string))
            try std.fs.path.resolve(allocator, &.{item.string})
        else
            try std.fs.path.resolve(allocator, &.{ cwd, item.string });
        errdefer allocator.free(resolved);
        if (stringSliceContains(paths.items, resolved)) {
            allocator.free(resolved);
            continue;
        }
        try paths.append(allocator, resolved);
    }
}

fn appendNullableJsonStringArray(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    values: []const []const u8,
) !void {
    if (values.len == 0) {
        try out.appendSlice(allocator, "null");
        return;
    }
    try appendJsonStringArray(allocator, out, values);
}

fn appendPermissionPathEntries(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    first: *bool,
    paths: []const []const u8,
    access: []const u8,
) !void {
    for (paths) |path| {
        if (!first.*) try out.appendSlice(allocator, ",");
        first.* = false;
        try out.appendSlice(allocator, "{\"path\":{\"type\":\"path\",\"path\":");
        try appendJsonString(allocator, out, path);
        try out.appendSlice(allocator, "},\"access\":");
        try appendJsonString(allocator, out, access);
        try out.appendSlice(allocator, "}");
    }
}

fn requestPermissionsResultFromResponsePayload(
    allocator: std.mem.Allocator,
    payload: []const u8,
    request_id_json: []const u8,
    cwd: []const u8,
) !?session_mod.RequestPermissionsResult {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, payload, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    if (!isJsonRpcResponseEnvelope(object)) return null;
    const id_value = object.get("id") orelse return null;
    const id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    defer allocator.free(id_json);
    if (!std.mem.eql(u8, id_json, request_id_json)) return null;
    if (object.get("error") != null) {
        return try emptyRequestPermissionsResult(allocator, "request_permissions client rejected request");
    }
    const result = object.get("result") orelse return try emptyRequestPermissionsResult(allocator, "request_permissions client returned no permissions");
    if (result != .object) return try emptyRequestPermissionsResult(allocator, "request_permissions client returned invalid permissions");

    const output_json = try std.json.Stringify.valueAlloc(allocator, result, .{});
    errdefer allocator.free(output_json);
    const scope = requestPermissionGrantScopeFromValue(result.object.get("scope"));
    var writable_roots = std.ArrayList([]const u8).empty;
    errdefer deinitStringArrayList(allocator, &writable_roots);
    var network_enabled: ?bool = null;
    if (result.object.get("permissions")) |permissions| {
        if (permissions == .object) {
            if (permissions.object.get("fileSystem") orelse permissions.object.get("file_system")) |file_system| {
                try appendGrantedWritableRoots(allocator, &writable_roots, file_system, cwd);
            }
            if (permissions.object.get("network")) |network| {
                network_enabled = grantedNetworkEnabled(network);
            }
        }
    }
    return .{
        .output_json = output_json,
        .scope = scope,
        .writable_roots = try writable_roots.toOwnedSlice(allocator),
        .network_enabled = network_enabled,
    };
}

fn emptyRequestPermissionsResult(allocator: std.mem.Allocator, output: []const u8) !session_mod.RequestPermissionsResult {
    return .{
        .output_json = try allocator.dupe(u8, output),
        .scope = .turn,
        .writable_roots = try allocator.alloc([]const u8, 0),
        .network_enabled = null,
    };
}

fn handleAppServerRequestUserInput(ctx: *anyopaque, request: session_mod.RequestUserInputRequest) !session_mod.RequestUserInputResult {
    const context: *AppServerRequestUserInputContext = @ptrCast(@alignCast(ctx));
    try sendRequestUserInputTurnStartResponse(context);

    const request_id = try std.fmt.allocPrint(context.allocator, "user-input-{s}", .{request.call_id});
    defer context.allocator.free(request_id);
    const request_id_json = try std.json.Stringify.valueAlloc(context.allocator, request_id, .{});
    defer context.allocator.free(request_id_json);

    const request_json = try renderToolRequestUserInputRequest(
        context.allocator,
        request_id,
        context.thread_id,
        context.turn_id,
        request,
    );
    defer context.allocator.free(request_json);

    try trackPendingServerRequest(context.allocator, context.state, request_json);
    const active_wait_thread = try beginLoadedThreadActiveWait(context.allocator, context.state, context.transport, context.thread, .user_input);
    defer if (active_wait_thread) |thread| decrementLoadedThreadActiveWait(thread, .user_input);
    var pending_tracked = true;
    defer if (pending_tracked) {
        if (takePendingServerRequest(context.state, request_id_json)) |pending_request| {
            var pending = pending_request;
            pending.deinit(context.allocator);
        }
    };

    const visible_request = try renderServerRequestForConnection(context.allocator, context.state.experimental_api_enabled, request_json);
    defer context.allocator.free(visible_request);
    try context.transport.send_payload(context.transport.ctx, visible_request);

    while (true) {
        const payload = try context.transport.read_payload(context.transport.ctx, context.allocator) orelse return error.AppServerRequestUserInputClientClosed;
        defer context.allocator.free(payload);
        if (payload.len == 0) continue;

        if (try requestUserInputResultFromResponsePayload(context.allocator, payload, request_id_json)) |parsed_result| {
            try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
            pending_tracked = false;
            return parsed_result;
        }

        if (try renderPendingApprovalInterruptResponse(context.allocator, payload, context.thread_id, context.turn_id)) |interrupt_response| {
            defer context.allocator.free(interrupt_response.payload);
            try context.transport.send_payload(context.transport.ctx, interrupt_response.payload);
            if (interrupt_response.cancel_approval) {
                try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
                pending_tracked = false;
                return emptyRequestUserInputResult(context.allocator, "request_user_input was cancelled before receiving a response");
            }
            continue;
        }

        if (try renderPendingTurnSteerResponse(context.allocator, payload, context.state, context.thread, context.turn_id, context.pending_steers)) |response_payload| {
            defer context.allocator.free(response_payload);
            try context.transport.send_payload(context.transport.ctx, response_payload);
            continue;
        }

        if (try renderPendingApprovalJsonRpcResponse(context.allocator, payload, context.thread_id, context.turn_id)) |response_payload| {
            defer context.allocator.free(response_payload);
            try context.transport.send_payload(context.transport.ctx, response_payload);
        }
    }
}

fn sendRequestUserInputTurnStartResponse(context: *AppServerRequestUserInputContext) !void {
    if (context.turn_start_response_sent.*) return;
    try context.transport.send_payload(context.transport.ctx, context.turn_start_response_payload);
    context.turn_start_response_sent.* = true;
}

fn renderToolRequestUserInputRequest(
    allocator: std.mem.Allocator,
    request_id: []const u8,
    thread_id: []const u8,
    turn_id: []const u8,
    request: session_mod.RequestUserInputRequest,
) ![]const u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, request.arguments_json, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRequestUserInput;
    const questions = parsed.value.object.get("questions") orelse return error.InvalidRequestUserInput;
    const questions_json = try renderRequestUserInputQuestionsJson(allocator, questions);
    defer allocator.free(questions_json);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"id\":");
    try appendJsonString(allocator, &out, request_id);
    try out.appendSlice(allocator, ",\"method\":\"item/tool/requestUserInput\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &out, thread_id);
    try out.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &out, turn_id);
    try out.appendSlice(allocator, ",\"itemId\":");
    try appendJsonString(allocator, &out, request.call_id);
    try out.appendSlice(allocator, ",\"questions\":");
    try out.appendSlice(allocator, questions_json);
    try out.appendSlice(allocator, "}}");
    return out.toOwnedSlice(allocator);
}

fn renderRequestUserInputQuestionsJson(
    allocator: std.mem.Allocator,
    questions: std.json.Value,
) ![]const u8 {
    if (questions != .array) return error.InvalidRequestUserInput;
    if (questions.array.items.len == 0) return error.InvalidRequestUserInput;

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "[");
    for (questions.array.items, 0..) |question, index| {
        if (question != .object) return error.InvalidRequestUserInput;
        if (index > 0) try out.appendSlice(allocator, ",");
        try out.appendSlice(allocator, "{\"id\":");
        try appendJsonString(allocator, &out, requiredJsonStringField(question.object, "id") orelse return error.InvalidRequestUserInput);
        try out.appendSlice(allocator, ",\"header\":");
        try appendJsonString(allocator, &out, requiredJsonStringField(question.object, "header") orelse return error.InvalidRequestUserInput);
        try out.appendSlice(allocator, ",\"question\":");
        try appendJsonString(allocator, &out, requiredJsonStringField(question.object, "question") orelse return error.InvalidRequestUserInput);
        try out.appendSlice(allocator, ",\"isOther\":true,\"isSecret\":false,\"options\":");
        try renderRequestUserInputOptionsJson(allocator, &out, question.object.get("options") orelse return error.InvalidRequestUserInput);
        try out.appendSlice(allocator, "}");
    }
    try out.appendSlice(allocator, "]");
    return out.toOwnedSlice(allocator);
}

fn renderRequestUserInputOptionsJson(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    options: std.json.Value,
) !void {
    if (options != .array) return error.InvalidRequestUserInput;
    if (options.array.items.len == 0) return error.InvalidRequestUserInput;
    try out.appendSlice(allocator, "[");
    for (options.array.items, 0..) |option, index| {
        if (option != .object) return error.InvalidRequestUserInput;
        if (index > 0) try out.appendSlice(allocator, ",");
        try out.appendSlice(allocator, "{\"label\":");
        try appendJsonString(allocator, out, requiredJsonStringField(option.object, "label") orelse return error.InvalidRequestUserInput);
        try out.appendSlice(allocator, ",\"description\":");
        try appendJsonString(allocator, out, requiredJsonStringField(option.object, "description") orelse return error.InvalidRequestUserInput);
        try out.appendSlice(allocator, "}");
    }
    try out.appendSlice(allocator, "]");
}

fn requiredJsonStringField(object: std.json.ObjectMap, name: []const u8) ?[]const u8 {
    const value = object.get(name) orelse return null;
    if (value != .string) return null;
    return value.string;
}

fn requestUserInputResultFromResponsePayload(
    allocator: std.mem.Allocator,
    payload: []const u8,
    request_id_json: []const u8,
) !?session_mod.RequestUserInputResult {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, payload, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    if (!isJsonRpcResponseEnvelope(object)) return null;
    const id_value = object.get("id") orelse return null;
    const id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    defer allocator.free(id_json);
    if (!std.mem.eql(u8, id_json, request_id_json)) return null;
    if (object.get("error") != null) return try emptyRequestUserInputAnswersResult(allocator);
    const result = object.get("result") orelse return try emptyRequestUserInputAnswersResult(allocator);
    if (!requestUserInputResponseIsValid(result)) return try emptyRequestUserInputAnswersResult(allocator);
    return .{ .output_json = try std.json.Stringify.valueAlloc(allocator, result, .{}) };
}

fn requestUserInputResponseIsValid(value: std.json.Value) bool {
    if (value != .object) return false;
    const answers = value.object.get("answers") orelse return false;
    if (answers != .object) return false;
    var iterator = answers.object.iterator();
    while (iterator.next()) |entry| {
        const answer = entry.value_ptr.*;
        if (answer != .object) return false;
        const choices = answer.object.get("answers") orelse return false;
        if (choices != .array) return false;
        for (choices.array.items) |choice| {
            if (choice != .string) return false;
        }
    }
    return true;
}

fn emptyRequestUserInputAnswersResult(allocator: std.mem.Allocator) !session_mod.RequestUserInputResult {
    return .{ .output_json = try allocator.dupe(u8, "{\"answers\":{}}") };
}

fn emptyRequestUserInputResult(allocator: std.mem.Allocator, output: []const u8) !session_mod.RequestUserInputResult {
    return .{ .output_json = try allocator.dupe(u8, output) };
}

const ExternalAuthRefreshPayload = struct {
    access_token: []const u8,
    account_id: []const u8,
    plan_type: ?[]const u8 = null,

    fn deinit(self: ExternalAuthRefreshPayload, allocator: std.mem.Allocator) void {
        allocator.free(self.access_token);
        allocator.free(self.account_id);
        if (self.plan_type) |value| allocator.free(value);
    }
};

fn handleAppServerExternalAuthRefresh(
    ctx: *anyopaque,
    allocator: std.mem.Allocator,
    previous_account_id: ?[]const u8,
) !auth_mod.Credentials {
    _ = allocator;
    const context: *AppServerExternalAuthRefreshContext = @ptrCast(@alignCast(ctx));
    try sendExternalAuthRefreshTurnStartResponse(context);

    const request_id = try std.fmt.allocPrint(context.allocator, "auth-refresh-{s}", .{context.turn_id});
    defer context.allocator.free(request_id);
    const request_id_json = try std.json.Stringify.valueAlloc(context.allocator, request_id, .{});
    defer context.allocator.free(request_id_json);

    const request_json = try renderChatGptAuthTokensRefreshRequest(context.allocator, request_id, previous_account_id);
    defer context.allocator.free(request_json);

    try trackPendingServerRequestWithThreadId(context.allocator, context.state, request_json, context.thread_id);
    var pending_tracked = true;
    defer if (pending_tracked) {
        if (takePendingServerRequest(context.state, request_id_json)) |pending_request| {
            var pending = pending_request;
            pending.deinit(context.allocator);
        }
    };

    const visible_request = try renderServerRequestForConnection(context.allocator, context.state.experimental_api_enabled, request_json);
    defer context.allocator.free(visible_request);
    try context.transport.send_payload(context.transport.ctx, visible_request);

    const refresh_deadline_ms = appServerAwakeDeadlineMs(EXTERNAL_AUTH_REFRESH_TIMEOUT_MS);
    while (true) {
        const read_timeout_ms = remainingAppServerAwakeMillis(refresh_deadline_ms) orelse {
            try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
            pending_tracked = false;
            return error.AppServerExternalAuthRefreshTimedOut;
        };
        const payload = switch (try context.transport.read_payload_with_timeout(context.transport.ctx, context.allocator, read_timeout_ms)) {
            .payload => |payload| payload,
            .closed => return error.AppServerExternalAuthRefreshClientClosed,
            .timed_out => {
                try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
                pending_tracked = false;
                return error.AppServerExternalAuthRefreshTimedOut;
            },
        };
        defer context.allocator.free(payload);
        if (payload.len == 0) continue;

        if (try externalAuthRefreshResponseMatchesRequest(context.allocator, payload, request_id_json)) {
            try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
            pending_tracked = false;
            const refresh_payload = (try externalAuthRefreshPayloadFromResponse(context.allocator, payload, request_id_json)) orelse return error.InvalidExternalAuthRefreshResponse;
            defer refresh_payload.deinit(context.allocator);
            if (context.forced_chatgpt_workspace_id) |expected_workspace| {
                if (!std.mem.eql(u8, refresh_payload.account_id, expected_workspace)) return error.WorkspaceRestriction;
            }
            try auth_mod.saveChatGptAuthTokensJsonWithMode(context.allocator, context.codex_home, .ephemeral, refresh_payload.access_token, refresh_payload.account_id, refresh_payload.plan_type);
            var credentials = (try auth_mod.loadActiveStoredWithMode(context.allocator, context.codex_home, context.auth_store_mode)) orelse return error.NoUsableAuth;
            errdefer credentials.deinit(context.allocator);
            const refreshed_credentials = credentials;
            credentials = undefined;
            return refreshed_credentials;
        }

        if (try renderPendingApprovalInterruptResponse(context.allocator, payload, context.thread_id, context.turn_id)) |interrupt_response| {
            defer context.allocator.free(interrupt_response.payload);
            try context.transport.send_payload(context.transport.ctx, interrupt_response.payload);
            if (interrupt_response.cancel_approval) {
                try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
                pending_tracked = false;
                return error.AppServerApprovalCanceled;
            }
            continue;
        }

        if (try renderPendingApprovalJsonRpcResponse(context.allocator, payload, context.thread_id, context.turn_id)) |response_payload| {
            defer context.allocator.free(response_payload);
            try context.transport.send_payload(context.transport.ctx, response_payload);
        }
    }
}

fn sendExternalAuthRefreshTurnStartResponse(context: *AppServerExternalAuthRefreshContext) !void {
    if (context.turn_start_response_sent.*) return;
    try context.transport.send_payload(context.transport.ctx, context.turn_start_response_payload);
    context.turn_start_response_sent.* = true;
}

fn renderChatGptAuthTokensRefreshRequest(
    allocator: std.mem.Allocator,
    request_id: []const u8,
    previous_account_id: ?[]const u8,
) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"id\":");
    try appendJsonString(allocator, &out, request_id);
    try out.appendSlice(allocator, ",\"method\":\"account/chatgptAuthTokens/refresh\",\"params\":{\"reason\":\"unauthorized\",\"previousAccountId\":");
    try appendOptionalJsonString(allocator, &out, previous_account_id);
    try out.appendSlice(allocator, "}}");
    return out.toOwnedSlice(allocator);
}

fn externalAuthRefreshPayloadFromResponse(
    allocator: std.mem.Allocator,
    payload: []const u8,
    request_id_json: []const u8,
) !?ExternalAuthRefreshPayload {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, payload, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    if (!isJsonRpcResponseEnvelope(object)) return null;
    const id_value = object.get("id") orelse return null;
    const id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    defer allocator.free(id_json);
    if (!std.mem.eql(u8, id_json, request_id_json)) return null;
    if (object.get("error") != null) return error.AppServerExternalAuthRefreshRejected;
    const result = object.get("result") orelse return error.InvalidExternalAuthRefreshResponse;
    if (result != .object) return error.InvalidExternalAuthRefreshResponse;
    const access_token = requiredJsonStringField(result.object, "accessToken") orelse return error.InvalidExternalAuthRefreshResponse;
    const account_id = requiredJsonStringField(result.object, "chatgptAccountId") orelse return error.InvalidExternalAuthRefreshResponse;
    if (access_token.len == 0 or account_id.len == 0) return error.InvalidExternalAuthRefreshResponse;
    const plan_type = if (result.object.get("chatgptPlanType")) |value| blk: {
        if (value == .null) break :blk null;
        if (value != .string) return error.InvalidExternalAuthRefreshResponse;
        break :blk value.string;
    } else null;

    const access_token_owned = try allocator.dupe(u8, access_token);
    errdefer allocator.free(access_token_owned);
    const account_id_owned = try allocator.dupe(u8, account_id);
    errdefer allocator.free(account_id_owned);
    const plan_type_owned = if (plan_type) |value| try allocator.dupe(u8, value) else null;
    errdefer if (plan_type_owned) |value| allocator.free(value);

    return .{
        .access_token = access_token_owned,
        .account_id = account_id_owned,
        .plan_type = plan_type_owned,
    };
}

fn externalAuthRefreshResponseMatchesRequest(
    allocator: std.mem.Allocator,
    payload: []const u8,
    request_id_json: []const u8,
) !bool {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, payload, .{}) catch return false;
    defer parsed.deinit();
    if (parsed.value != .object) return false;
    const object = parsed.value.object;
    if (!isJsonRpcResponseEnvelope(object)) return false;
    const id_value = object.get("id") orelse return false;
    const id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    defer allocator.free(id_json);
    return std.mem.eql(u8, id_json, request_id_json);
}

fn handleAppServerMcpElicitation(ctx: *anyopaque, request: mcp_runtime.ElicitationRequest) !mcp_runtime.ElicitationResponse {
    const context: *AppServerMcpElicitationContext = @ptrCast(@alignCast(ctx));
    if (context.auto_decline) return emptyMcpElicitationResult(context.allocator, "decline");
    try sendMcpElicitationTurnStartResponse(context);

    const request_id = try mcpElicitationAppServerRequestId(context.allocator, request.server_name, request.request_id_json);
    defer context.allocator.free(request_id);
    const request_id_json = try std.json.Stringify.valueAlloc(context.allocator, request_id, .{});
    defer context.allocator.free(request_id_json);

    const request_json = try renderMcpServerElicitationRequest(
        context.allocator,
        request_id,
        context.thread_id,
        context.turn_id,
        request,
    );
    defer context.allocator.free(request_json);

    try trackPendingServerRequest(context.allocator, context.state, request_json);
    const active_wait_thread = try beginLoadedThreadActiveWait(context.allocator, context.state, context.transport, context.thread, .permission);
    defer if (active_wait_thread) |thread| decrementLoadedThreadActiveWait(thread, .permission);
    var pending_tracked = true;
    defer if (pending_tracked) {
        if (takePendingServerRequest(context.state, request_id_json)) |pending_request| {
            var pending = pending_request;
            pending.deinit(context.allocator);
        }
    };

    const visible_request = try renderServerRequestForConnection(context.allocator, context.state.experimental_api_enabled, request_json);
    defer context.allocator.free(visible_request);
    try context.transport.send_payload(context.transport.ctx, visible_request);

    while (true) {
        const payload = try context.transport.read_payload(context.transport.ctx, context.allocator) orelse return error.AppServerMcpElicitationClientClosed;
        defer context.allocator.free(payload);
        if (payload.len == 0) continue;

        if (try mcpElicitationResultFromResponsePayload(context.allocator, payload, request_id_json)) |result| {
            try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
            pending_tracked = false;
            return result;
        }

        if (context.turn_id) |turn_id| {
            if (try renderPendingApprovalInterruptResponse(context.allocator, payload, context.thread_id, turn_id)) |interrupt_response| {
                defer context.allocator.free(interrupt_response.payload);
                try context.transport.send_payload(context.transport.ctx, interrupt_response.payload);
                if (interrupt_response.cancel_approval) {
                    try sendServerRequestResolvedForRequest(context.allocator, context.state, context.transport, request_id_json);
                    pending_tracked = false;
                    return emptyMcpElicitationResult(context.allocator, "cancel");
                }
                continue;
            }
        }

        if (try renderPendingApprovalJsonRpcResponse(context.allocator, payload, context.thread_id, context.turn_id)) |response_payload| {
            defer context.allocator.free(response_payload);
            try context.transport.send_payload(context.transport.ctx, response_payload);
        }
    }
}

fn sendMcpElicitationTurnStartResponse(context: *AppServerMcpElicitationContext) !void {
    const sent = context.turn_start_response_sent orelse return;
    if (sent.*) return;
    const payload = context.turn_start_response_payload orelse return;
    try context.transport.send_payload(context.transport.ctx, payload);
    sent.* = true;
}

fn mcpElicitationAppServerRequestId(
    allocator: std.mem.Allocator,
    server_name: []const u8,
    mcp_request_id_json: []const u8,
) ![]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, mcp_request_id_json, .{}) catch {
        return std.fmt.allocPrint(allocator, "mcp-elicitation-{s}-{s}", .{ server_name, mcp_request_id_json });
    };
    defer parsed.deinit();
    const label = if (parsed.value == .string) parsed.value.string else mcp_request_id_json;
    return std.fmt.allocPrint(allocator, "mcp-elicitation-{s}-{s}", .{ server_name, label });
}

fn renderMcpServerElicitationRequest(
    allocator: std.mem.Allocator,
    request_id: []const u8,
    thread_id: []const u8,
    turn_id: ?[]const u8,
    request: mcp_runtime.ElicitationRequest,
) ![]const u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, request.params_json, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidMcpElicitationRequest;
    const object = parsed.value.object;
    const message = requiredJsonStringField(object, "message") orelse return error.InvalidMcpElicitationRequest;

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"id\":");
    try appendJsonString(allocator, &out, request_id);
    try out.appendSlice(allocator, ",\"method\":\"mcpServer/elicitation/request\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &out, thread_id);
    try out.appendSlice(allocator, ",\"turnId\":");
    try appendOptionalJsonString(allocator, &out, turn_id);
    try out.appendSlice(allocator, ",\"serverName\":");
    try appendJsonString(allocator, &out, request.server_name);

    if (object.get("url")) |url_value| {
        if (url_value != .string) return error.InvalidMcpElicitationRequest;
        const elicitation_id = requiredJsonStringField(object, "elicitationId") orelse return error.InvalidMcpElicitationRequest;
        try out.appendSlice(allocator, ",\"mode\":\"url\",\"_meta\":");
        try appendMcpElicitationMeta(allocator, &out, object);
        try out.appendSlice(allocator, ",\"message\":");
        try appendJsonString(allocator, &out, message);
        try out.appendSlice(allocator, ",\"url\":");
        try appendJsonString(allocator, &out, url_value.string);
        try out.appendSlice(allocator, ",\"elicitationId\":");
        try appendJsonString(allocator, &out, elicitation_id);
        try out.appendSlice(allocator, "}}");
        return out.toOwnedSlice(allocator);
    }

    const requested_schema = object.get("requestedSchema") orelse object.get("requested_schema") orelse return error.InvalidMcpElicitationRequest;
    const requested_schema_json = try std.json.Stringify.valueAlloc(allocator, requested_schema, .{});
    defer allocator.free(requested_schema_json);
    try out.appendSlice(allocator, ",\"mode\":\"form\",\"_meta\":");
    try appendMcpElicitationMeta(allocator, &out, object);
    try out.appendSlice(allocator, ",\"message\":");
    try appendJsonString(allocator, &out, message);
    try out.appendSlice(allocator, ",\"requestedSchema\":");
    try out.appendSlice(allocator, requested_schema_json);
    try out.appendSlice(allocator, "}}");
    return out.toOwnedSlice(allocator);
}

fn appendMcpElicitationMeta(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    object: std.json.ObjectMap,
) !void {
    const meta = object.get("_meta") orelse object.get("meta") orelse {
        try out.appendSlice(allocator, "null");
        return;
    };
    const meta_json = try std.json.Stringify.valueAlloc(allocator, meta, .{});
    defer allocator.free(meta_json);
    try out.appendSlice(allocator, meta_json);
}

fn mcpElicitationResultFromResponsePayload(
    allocator: std.mem.Allocator,
    payload: []const u8,
    request_id_json: []const u8,
) !?mcp_runtime.ElicitationResponse {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, payload, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    if (!isJsonRpcResponseEnvelope(object)) return null;
    const id_value = object.get("id") orelse return null;
    const id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    defer allocator.free(id_json);
    if (!std.mem.eql(u8, id_json, request_id_json)) return null;

    if (object.get("error") != null) return try emptyMcpElicitationResult(allocator, "decline");
    const result = object.get("result") orelse return try emptyMcpElicitationResult(allocator, "decline");
    return .{ .result_json = try renderMcpElicitationResultJson(allocator, result) };
}

fn renderMcpElicitationResultJson(allocator: std.mem.Allocator, result: std.json.Value) ![]const u8 {
    if (result != .object) return try allocator.dupe(u8, "{\"action\":\"decline\"}");
    const action_value = result.object.get("action") orelse return try allocator.dupe(u8, "{\"action\":\"decline\"}");
    if (action_value != .string or !mcpElicitationActionIsValid(action_value.string)) {
        return try allocator.dupe(u8, "{\"action\":\"decline\"}");
    }

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"action\":");
    try appendJsonString(allocator, &out, action_value.string);
    if (result.object.get("content")) |content| {
        const content_json = try std.json.Stringify.valueAlloc(allocator, content, .{});
        defer allocator.free(content_json);
        try out.appendSlice(allocator, ",\"content\":");
        try out.appendSlice(allocator, content_json);
    }
    if (result.object.get("_meta") orelse result.object.get("meta")) |meta| {
        const meta_json = try std.json.Stringify.valueAlloc(allocator, meta, .{});
        defer allocator.free(meta_json);
        try out.appendSlice(allocator, ",\"_meta\":");
        try out.appendSlice(allocator, meta_json);
    }
    try out.appendSlice(allocator, "}");
    return out.toOwnedSlice(allocator);
}

fn emptyMcpElicitationResult(allocator: std.mem.Allocator, action: []const u8) !mcp_runtime.ElicitationResponse {
    const action_json = try std.json.Stringify.valueAlloc(allocator, action, .{});
    defer allocator.free(action_json);
    const result_json = try std.fmt.allocPrint(allocator, "{{\"action\":{s}}}", .{action_json});
    return .{ .result_json = result_json };
}

fn mcpElicitationActionIsValid(action: []const u8) bool {
    return std.mem.eql(u8, action, "accept") or
        std.mem.eql(u8, action, "decline") or
        std.mem.eql(u8, action, "cancel");
}

fn requestPermissionGrantScopeFromValue(value: ?std.json.Value) session_mod.PermissionGrantScope {
    const scope = value orelse return .turn;
    if (scope == .string and std.mem.eql(u8, scope.string, "session")) return .session;
    return .turn;
}

fn appendGrantedWritableRoots(
    allocator: std.mem.Allocator,
    roots: *std.ArrayList([]const u8),
    file_system: std.json.Value,
    cwd: []const u8,
) !void {
    if (file_system != .object) return;
    try appendResolvedPermissionPaths(allocator, roots, file_system.object.get("write"), cwd);
    if (file_system.object.get("entries")) |entries| {
        if (entries != .array) return;
        for (entries.array.items) |entry| {
            if (entry != .object) continue;
            const access = entry.object.get("access") orelse continue;
            if (access != .string or !std.mem.eql(u8, access.string, "write")) continue;
            const path_value = entry.object.get("path") orelse continue;
            if (try permissionEntryPathString(path_value)) |path| {
                const resolved = if (std.fs.path.isAbsolute(path))
                    try std.fs.path.resolve(allocator, &.{path})
                else
                    try std.fs.path.resolve(allocator, &.{ cwd, path });
                errdefer allocator.free(resolved);
                if (stringSliceContains(roots.items, resolved)) {
                    allocator.free(resolved);
                    continue;
                }
                try roots.append(allocator, resolved);
            }
        }
    }
}

fn permissionEntryPathString(value: std.json.Value) !?[]const u8 {
    if (value != .object) return null;
    const type_value = value.object.get("type") orelse return null;
    if (type_value != .string or !std.mem.eql(u8, type_value.string, "path")) return null;
    const path = value.object.get("path") orelse return null;
    if (path != .string) return null;
    return path.string;
}

fn grantedNetworkEnabled(value: std.json.Value) ?bool {
    if (value != .object) return null;
    const enabled = value.object.get("enabled") orelse return null;
    if (enabled != .bool) return null;
    return enabled.bool;
}

fn applySessionScopedRequestPermissions(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    result: session_mod.RequestPermissionsResult,
) !void {
    if (result.scope != .session) return;
    for (result.writable_roots) |root| {
        try appendLoadedThreadWritableRoot(allocator, thread, root);
    }
    if (result.network_enabled) |enabled| {
        if (enabled) thread.sandbox_network_enabled = true;
    }
}

fn appendLoadedThreadWritableRoot(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    root: []const u8,
) !void {
    if (stringSliceContains(thread.sandbox_writable_roots.items, root)) return;
    const old_items = thread.sandbox_writable_roots.items;
    const new_items = try allocator.alloc([]const u8, old_items.len + 1);
    errdefer allocator.free(new_items);
    @memcpy(new_items[0..old_items.len], old_items);
    new_items[old_items.len] = try allocator.dupe(u8, root);
    allocator.free(old_items);
    thread.sandbox_writable_roots.items = new_items;
}

fn deinitStringArrayList(allocator: std.mem.Allocator, list: *std.ArrayList([]const u8)) void {
    for (list.items) |item| allocator.free(item);
    list.deinit(allocator);
}

fn stringSliceContains(values: []const []const u8, needle: []const u8) bool {
    for (values) |value| {
        if (std.mem.eql(u8, value, needle)) return true;
    }
    return false;
}

fn handleMemoryReset(allocator: std.mem.Allocator, state: *const AppServerState, id_value: std.json.Value) ![]const u8 {
    const paths = resolveMemoryResetRuntimePaths(allocator, state) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "failed to resolve runtime paths", err);
    };
    defer paths.deinit(allocator);

    const state_path = memory_reset.resolveStateDbPathForSqliteHome(allocator, paths.sqlite_home) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "failed to resolve state db path", err);
    };
    defer allocator.free(state_path);

    const state_exists = memory_reset.stateDbExists(allocator, state_path) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "failed to inspect state db", err);
    };
    if (state_exists) {
        memory_reset.clearMemoryStateDb(allocator, state_path) catch |err| {
            return try renderJsonRpcErrorForFailure(allocator, id_value, "failed to clear memory state db", err);
        };
    }

    memory_reset.clearMemoryRootsContents(allocator, paths.codex_home) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "failed to clear memory directories", err);
    };
    return try renderJsonRpcResult(allocator, id_value, "{}");
}

fn resolveMemoryResetRuntimePaths(allocator: std.mem.Allocator, state: *const AppServerState) !MemoryResetRuntimePaths {
    const codex_home = try config.resolveCodexHome(allocator);
    errdefer allocator.free(codex_home);

    const sqlite_home = if (state.runtime_overrides.sqlite_home) |raw|
        try config.resolveRuntimeOverridePath(allocator, raw)
    else
        try config.resolveRuntimeSqliteHome(allocator, codex_home);
    errdefer allocator.free(sqlite_home);

    return .{
        .codex_home = codex_home,
        .sqlite_home = sqlite_home,
    };
}

fn handleAppsList(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = switch (optionalAppsListParams(params_value)) {
        .object => |object| object,
        .empty => null,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };

    var scoped_thread: ?*const LoadedThread = null;
    if (params) |object| {
        if (object.get("threadId")) |value| {
            if (value != .null) {
                if (value != .string or value.string.len == 0) return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string or null");
                scoped_thread = findLoadedThread(state, value.string) orelse return renderThreadNotFound(allocator, id_value, value.string);
            }
        }
    }

    if (!(try appServerFeatureEnabled(allocator, state, "apps"))) {
        return renderJsonRpcResult(allocator, id_value, "{\"data\":[],\"nextCursor\":null}");
    }

    var cursor: ?[]const u8 = null;
    var limit: ?usize = null;
    var force_refetch = false;
    if (params) |object| {
        if (object.get("cursor")) |value| {
            if (value != .null) {
                if (value != .string) return renderJsonRpcError(allocator, id_value, -32602, "cursor must be a string or null");
                cursor = value.string;
            }
        }
        if (object.get("limit")) |value| {
            limit = switch (value) {
                .null => null,
                .integer => |integer| blk: {
                    if (integer < 0) return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null");
                    break :blk @intCast(integer);
                },
                .number_string => |number| std.fmt.parseUnsigned(usize, number, 10) catch {
                    return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null");
                },
                else => return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null"),
            };
        }
        if (object.get("forceRefetch")) |value| {
            force_refetch = value == .bool and value.bool;
        }
    }

    const start = if (cursor) |value|
        std.fmt.parseUnsigned(usize, value, 10) catch {
            const message = try std.fmt.allocPrint(allocator, "invalid cursor: {s}", .{value});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
    else
        0;

    var cfg = loadAppServerConfig(allocator, state) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "app/list failed", err);
    };
    defer cfg.deinit(allocator);
    const codex_home = cfg.codex_home;

    const config_path = config.configTomlPath(allocator, codex_home) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "app/list failed", err);
    };
    defer allocator.free(config_path);
    const config_bytes = config.readConfigTomlFile(allocator, config_path) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "app/list failed", err);
    };
    defer if (config_bytes) |bytes| allocator.free(bytes);

    var requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "app/list failed", err);
    };
    defer requirements.deinit(allocator);

    var scoped_cwds_storage: [1][]const u8 = undefined;
    var scoped_cwds: []const []const u8 = &.{};
    if (scoped_thread) |thread| {
        scoped_cwds_storage[0] = thread.cwd;
        scoped_cwds = scoped_cwds_storage[0..];
    }

    var remote_directory_pages = std.ArrayList([]const u8).empty;
    defer {
        for (remote_directory_pages.items) |page| allocator.free(page);
        remote_directory_pages.deinit(allocator);
    }
    try fetchRemoteAppDirectoryPagesIfAvailable(allocator, &remote_directory_pages, force_refetch);

    const accessible_catalog: ?mcp_runtime.Catalog = loadCodexAppsAccessibleCatalog(allocator, &cfg, force_refetch) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "app/list failed", err);
    };
    defer if (accessible_catalog) |catalog| catalog.deinit(allocator);
    const accessible_tools: []const mcp_runtime.ToolSpec = if (accessible_catalog) |catalog| catalog.tools else &.{};

    var total: usize = 0;
    const result = plugin_list.renderAppsListResponseWithRemoteDirectoryPagesAndAccessibleTools(
        allocator,
        codex_home,
        config_bytes orelse "",
        requirements.app_requirements,
        scoped_cwds,
        remote_directory_pages.items,
        accessible_tools,
        start,
        limit,
        &total,
    ) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "app/list failed", err);
    };
    const result_json = result orelse {
        const message = try std.fmt.allocPrint(allocator, "cursor {d} exceeds total apps {d}", .{ start, total });
        defer allocator.free(message);
        return renderJsonRpcError(allocator, id_value, -32600, message);
    };
    defer allocator.free(result_json);

    return renderJsonRpcResult(allocator, id_value, result_json);
}

fn handleAppsRead(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: missing field `params`");
    if (params == .null) return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: missing field `params`");
    if (params != .object) {
        if (params == .array) {
            const message = try std.fmt.allocPrint(allocator, "Invalid request: invalid length {d}, expected struct AppsReadParams with 2 elements", .{params.array.items.len});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
        return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: expected struct AppsReadParams");
    }

    const object = params.object;
    const app_ids_value = object.get("appIds") orelse return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: missing field `appIds`");
    if (app_ids_value != .array) {
        if (app_ids_value == .string) {
            const message = try std.fmt.allocPrint(allocator, "Invalid request: invalid type: string \"{s}\", expected a sequence", .{app_ids_value.string});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
        return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: expected a sequence");
    }
    if (app_ids_value.array.items.len > 100) {
        return renderJsonRpcError(allocator, id_value, -32602, "app/read accepts at most 100 appIds");
    }
    if (object.get("includeTools")) |value| {
        if (value != .bool) {
            if (value == .string) {
                const message = try std.fmt.allocPrint(allocator, "Invalid request: invalid type: string \"{s}\", expected a boolean", .{value.string});
                defer allocator.free(message);
                return renderJsonRpcError(allocator, id_value, -32600, message);
            }
            return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: expected a boolean");
        }
    }

    var missing_app_ids = std.ArrayList([]const u8).empty;
    defer missing_app_ids.deinit(allocator);
    for (app_ids_value.array.items) |item| {
        if (item != .string) {
            if (item == .integer) {
                const message = try std.fmt.allocPrint(allocator, "Invalid request: invalid type: integer `{d}`, expected a string", .{item.integer});
                defer allocator.free(message);
                return renderJsonRpcError(allocator, id_value, -32600, message);
            }
            return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: expected a string");
        }
        if (!stringSliceContains(missing_app_ids.items, item.string)) {
            try missing_app_ids.append(allocator, item.string);
        }
    }

    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"apps\":[],\"missingAppIds\":");
    try appendJsonStringArray(allocator, &result, missing_app_ids.items);
    try result.appendSlice(allocator, "}");
    return renderJsonRpcResult(allocator, id_value, result.items);
}

fn handleAppsInstalled(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: missing field `params`");
    if (params == .null) return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: missing field `params`");
    if (params != .object) {
        if (params == .array) {
            const message = try std.fmt.allocPrint(allocator, "Invalid request: invalid length {d}, expected struct AppsInstalledParams with 2 elements", .{params.array.items.len});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
        return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: expected struct AppsInstalledParams");
    }

    const object = params.object;
    if (object.get("threadId")) |value| {
        if (value != .null) {
            if (value != .string) {
                if (value == .integer) {
                    const message = try std.fmt.allocPrint(allocator, "Invalid request: invalid type: integer `{d}`, expected a string", .{value.integer});
                    defer allocator.free(message);
                    return renderJsonRpcError(allocator, id_value, -32600, message);
                }
                return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: expected a string");
            }
            if (!isUuidString(value.string)) {
                return renderInvalidThreadId(allocator, id_value, value.string);
            }
            _ = findLoadedThread(state, value.string) orelse return renderThreadNotFound(allocator, id_value, value.string);
        }
    }
    if (object.get("forceRefresh")) |value| {
        if (value != .bool) {
            if (value == .string) {
                const message = try std.fmt.allocPrint(allocator, "Invalid request: invalid type: string \"{s}\", expected a boolean", .{value.string});
                defer allocator.free(message);
                return renderJsonRpcError(allocator, id_value, -32600, message);
            }
            return renderJsonRpcError(allocator, id_value, -32600, "Invalid request: expected a boolean");
        }
    }

    return renderJsonRpcResult(allocator, id_value, "{\"apps\":[]}");
}

fn queueAppListUpdatedNotificationAfterEnablement(allocator: std.mem.Allocator, state: *AppServerState) !void {
    if (serverNotificationShouldBeDropped(state, "app/list/updated")) return;
    if (!(try appServerFeatureEnabled(allocator, state, "apps"))) return;

    const notification = try renderAppListUpdatedNotification(allocator, state);
    try queuePendingServerNotification(allocator, state, "app/list/updated", notification);
}

fn renderAppListUpdatedNotification(allocator: std.mem.Allocator, state: *const AppServerState) ![]const u8 {
    const data_json = try renderCurrentAppListDataJson(allocator, state);
    defer allocator.free(data_json);

    return std.fmt.allocPrint(
        allocator,
        "{{\"jsonrpc\":\"2.0\",\"method\":\"app/list/updated\",\"params\":{{\"data\":{s}}}}}",
        .{data_json},
    );
}

fn renderCurrentAppListDataJson(allocator: std.mem.Allocator, state: *const AppServerState) ![]const u8 {
    var cfg = try loadAppServerConfig(allocator, state);
    defer cfg.deinit(allocator);
    const codex_home = cfg.codex_home;

    const config_path = try config.configTomlPath(allocator, codex_home);
    defer allocator.free(config_path);
    const config_bytes = try config.readConfigTomlFile(allocator, config_path);
    defer if (config_bytes) |bytes| allocator.free(bytes);

    var total: usize = 0;
    var requirements = try loadConfigRequirementsReadRequirements(allocator);
    defer requirements.deinit(allocator);

    var remote_directory_pages = std.ArrayList([]const u8).empty;
    defer {
        for (remote_directory_pages.items) |page| allocator.free(page);
        remote_directory_pages.deinit(allocator);
    }
    try fetchRemoteAppDirectoryPagesIfAvailable(allocator, &remote_directory_pages, false);

    const accessible_catalog: ?mcp_runtime.Catalog = try loadCodexAppsAccessibleCatalog(allocator, &cfg, false);
    defer if (accessible_catalog) |catalog| catalog.deinit(allocator);
    const accessible_tools: []const mcp_runtime.ToolSpec = if (accessible_catalog) |catalog| catalog.tools else &.{};

    const response = (try plugin_list.renderAppsListResponseWithRemoteDirectoryPagesAndAccessibleTools(
        allocator,
        codex_home,
        config_bytes orelse "",
        requirements.app_requirements,
        &.{},
        remote_directory_pages.items,
        accessible_tools,
        0,
        null,
        &total,
    )) orelse return error.InvalidAppListRefreshCursor;
    defer allocator.free(response);

    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, response, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidAppListRefreshResponse;
    const data = parsed.value.object.get("data") orelse return error.InvalidAppListRefreshResponse;
    if (data != .array) return error.InvalidAppListRefreshResponse;
    return std.json.Stringify.valueAlloc(allocator, data, .{});
}

fn loadCodexAppsAccessibleCatalog(allocator: std.mem.Allocator, cfg: *const config.Config, force_refetch: bool) !?mcp_runtime.Catalog {
    const cache_key = try codexAppsAccessibleToolsCacheKey(allocator, cfg);
    defer if (cache_key) |key| allocator.free(key);

    if (!force_refetch) {
        if (cache_key) |key| {
            if (try loadCachedCodexAppsAccessibleCatalog(allocator, key)) |cached| return cached;
        }
    }

    const catalog = mcp_runtime.loadHostOwnedCodexAppsCatalogForConfig(allocator, cfg.codex_home, cfg) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return null,
    };
    errdefer catalog.deinit(allocator);
    if (cache_key) |key| {
        try replaceCodexAppsAccessibleToolsCache(allocator, key, catalog.tools);
    }
    return catalog;
}

fn codexAppsAccessibleToolsCacheKey(allocator: std.mem.Allocator, cfg: *const config.Config) !?[]const u8 {
    var credentials = auth_mod.loadCliAuthNoRefreshForConfig(allocator, cfg) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return null,
    };
    defer credentials.deinit(allocator);

    if (!appDirectoryCredentialsUseCodexBackend(credentials)) return null;

    var key = std.ArrayList(u8).empty;
    errdefer key.deinit(allocator);
    try appendAppDirectoryCacheKeyPart(allocator, &key, "codex_home", cfg.codex_home);
    try appendAppDirectoryCacheKeyPart(allocator, &key, "chatgpt_base_url", cfg.chatgpt_base_url);
    try appendAppDirectoryCacheKeyPart(allocator, &key, "apps_mcp_path_override", cfg.apps_mcp_path_override orelse "");
    try appendAppDirectoryCacheKeyPart(allocator, &key, "auth_mode", authMethodLabel(credentials.mode) orelse "local_oss");
    try appendAppDirectoryCacheKeyPart(allocator, &key, "account_id", credentials.account_id orelse "");
    try appendAppDirectoryCacheKeyPart(allocator, &key, "chatgpt_user_id", credentials.chatgpt_user_id orelse "");
    try appendAppDirectoryCacheKeyPart(allocator, &key, "fedramp", if (credentials.fedramp) "true" else "false");
    try appendCodexConnectorsTokenCacheKeyPart(allocator, &key);
    const owned: []const u8 = try key.toOwnedSlice(allocator);
    return owned;
}

fn appendCodexConnectorsTokenCacheKeyPart(allocator: std.mem.Allocator, key: *std.ArrayList(u8)) !void {
    const value = try env.getOwned(allocator, CODEX_CONNECTORS_TOKEN_ENV_VAR) orelse {
        try appendAppDirectoryCacheKeyPart(allocator, key, "codex_connectors_token", "absent");
        return;
    };
    defer allocator.free(value);

    const trimmed = std.mem.trim(u8, value, " \t\r\n");
    if (trimmed.len == 0) {
        try appendAppDirectoryCacheKeyPart(allocator, key, "codex_connectors_token", "blank");
        return;
    }

    const fingerprint = std.hash.Wyhash.hash(0, trimmed);
    const fingerprint_text = try std.fmt.allocPrint(allocator, "{x}", .{fingerprint});
    defer allocator.free(fingerprint_text);
    try appendAppDirectoryCacheKeyPart(allocator, key, "codex_connectors_token", fingerprint_text);
}

fn loadCachedCodexAppsAccessibleCatalog(
    allocator: std.mem.Allocator,
    cache_key: []const u8,
) !?mcp_runtime.Catalog {
    const io = std.Io.Threaded.global_single_threaded.io();
    app_accessible_tools_cache_mutex.lockUncancelable(io);
    defer app_accessible_tools_cache_mutex.unlock(io);
    const cache = if (app_accessible_tools_cache) |*cache| cache else return null;
    if (currentUnixMilliseconds() >= cache.expires_at_ms) return null;
    if (!std.mem.eql(u8, cache.key, cache_key)) return null;
    return .{ .tools = try cloneMcpToolSpecs(allocator, cache.tools) };
}

fn replaceCodexAppsAccessibleToolsCache(
    allocator: std.mem.Allocator,
    cache_key: []const u8,
    tools: []const mcp_runtime.ToolSpec,
) !void {
    const owned_key = try allocator.dupe(u8, cache_key);
    errdefer allocator.free(owned_key);
    const owned_tools = try cloneMcpToolSpecs(allocator, tools);
    errdefer {
        for (owned_tools) |tool| tool.deinit(allocator);
        allocator.free(owned_tools);
    }

    var next_cache = AppAccessibleToolsCache{
        .key = owned_key,
        .expires_at_ms = currentUnixMilliseconds() + APP_LIST_DIRECTORY_CACHE_TTL_MS,
        .tools = owned_tools,
    };
    var keep_next_cache = false;
    defer if (!keep_next_cache) next_cache.deinit(allocator);

    const io = std.Io.Threaded.global_single_threaded.io();
    app_accessible_tools_cache_mutex.lockUncancelable(io);
    defer app_accessible_tools_cache_mutex.unlock(io);
    if (app_accessible_tools_cache) |*cache| cache.deinit(allocator);
    app_accessible_tools_cache = next_cache;
    keep_next_cache = true;
}

fn cloneMcpToolSpecs(allocator: std.mem.Allocator, tools: []const mcp_runtime.ToolSpec) ![]mcp_runtime.ToolSpec {
    const cloned = try allocator.alloc(mcp_runtime.ToolSpec, tools.len);
    var initialized: usize = 0;
    errdefer {
        for (cloned[0..initialized]) |tool| tool.deinit(allocator);
        allocator.free(cloned);
    }

    for (tools) |tool| {
        cloned[initialized] = try cloneMcpToolSpec(allocator, tool);
        initialized += 1;
    }
    return cloned;
}

fn cloneMcpToolSpec(allocator: std.mem.Allocator, tool: mcp_runtime.ToolSpec) !mcp_runtime.ToolSpec {
    const server_name = try allocator.dupe(u8, tool.server_name);
    errdefer allocator.free(server_name);
    const raw_tool_name = try allocator.dupe(u8, tool.raw_tool_name);
    errdefer allocator.free(raw_tool_name);
    const callable_name = try allocator.dupe(u8, tool.callable_name);
    errdefer allocator.free(callable_name);
    const description = try allocator.dupe(u8, tool.description);
    errdefer allocator.free(description);
    const input_schema_json = try allocator.dupe(u8, tool.input_schema_json);
    errdefer allocator.free(input_schema_json);

    var connector_id: ?[]const u8 = null;
    errdefer if (connector_id) |owned| allocator.free(owned);
    var connector_name: ?[]const u8 = null;
    errdefer if (connector_name) |owned| allocator.free(owned);
    var namespace_description: ?[]const u8 = null;
    errdefer if (namespace_description) |owned| allocator.free(owned);

    if (tool.connector_id) |value| connector_id = try allocator.dupe(u8, value);
    if (tool.connector_name) |value| connector_name = try allocator.dupe(u8, value);
    if (tool.namespace_description) |value| namespace_description = try allocator.dupe(u8, value);

    return .{
        .server_name = server_name,
        .raw_tool_name = raw_tool_name,
        .callable_name = callable_name,
        .description = description,
        .input_schema_json = input_schema_json,
        .connector_id = connector_id,
        .connector_name = connector_name,
        .namespace_description = namespace_description,
    };
}

fn fetchRemoteAppDirectoryPagesIfAvailable(allocator: std.mem.Allocator, pages: *std.ArrayList([]const u8), force_refetch: bool) !void {
    var cfg = config.load(allocator) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return,
    };
    defer cfg.deinit(allocator);

    var credentials = auth_mod.loadCliAuthNoRefreshForConfig(allocator, &cfg) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return,
    };
    defer credentials.deinit(allocator);

    if (!appDirectoryCredentialsUseCodexBackend(credentials)) return;
    const cache_key = try appDirectoryCacheKey(allocator, cfg.chatgpt_base_url, credentials);
    defer allocator.free(cache_key);

    if (!force_refetch and try appendCachedRemoteAppDirectoryPages(allocator, pages, cache_key)) return;

    const initial_len = pages.items.len;
    fetchRemoteAppDirectoryPages(allocator, cfg.chatgpt_base_url, credentials, pages) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return,
    };
    try replaceRemoteAppDirectoryCache(allocator, cache_key, pages.items[initial_len..]);
}

fn appDirectoryCredentialsUseCodexBackend(credentials: auth_mod.Credentials) bool {
    return switch (credentials.mode) {
        .chatgpt, .chatgpt_auth_tokens, .agent_identity => true,
        .api_key, .local_oss, .provider_no_auth => false,
    };
}

fn appDirectoryCacheKey(allocator: std.mem.Allocator, base_url: []const u8, credentials: auth_mod.Credentials) ![]const u8 {
    var key = std.ArrayList(u8).empty;
    errdefer key.deinit(allocator);
    try appendAppDirectoryCacheKeyPart(allocator, &key, "chatgpt_base_url", base_url);
    try appendAppDirectoryCacheKeyPart(allocator, &key, "auth_mode", authMethodLabel(credentials.mode) orelse "local_oss");
    try appendAppDirectoryCacheKeyPart(allocator, &key, "account_id", credentials.account_id orelse "");
    try appendAppDirectoryCacheKeyPart(allocator, &key, "chatgpt_user_id", credentials.chatgpt_user_id orelse "");
    try appendAppDirectoryCacheKeyPart(allocator, &key, "fedramp", if (credentials.fedramp) "true" else "false");
    return key.toOwnedSlice(allocator);
}

fn appendAppDirectoryCacheKeyPart(
    allocator: std.mem.Allocator,
    key: *std.ArrayList(u8),
    name: []const u8,
    value: []const u8,
) !void {
    const len_text = try std.fmt.allocPrint(allocator, "{d}", .{value.len});
    defer allocator.free(len_text);
    try key.appendSlice(allocator, name);
    try key.append(allocator, ':');
    try key.appendSlice(allocator, len_text);
    try key.append(allocator, ':');
    try key.appendSlice(allocator, value);
    try key.append(allocator, '\n');
}

fn appendCachedRemoteAppDirectoryPages(
    allocator: std.mem.Allocator,
    pages: *std.ArrayList([]const u8),
    cache_key: []const u8,
) !bool {
    const io = std.Io.Threaded.global_single_threaded.io();
    app_directory_cache_mutex.lockUncancelable(io);
    defer app_directory_cache_mutex.unlock(io);
    const cache = if (app_directory_cache) |*cache| cache else return false;
    if (currentUnixMilliseconds() >= cache.expires_at_ms) return false;
    if (!std.mem.eql(u8, cache.key, cache_key)) return false;
    try appendOwnedRemoteAppDirectoryPages(allocator, pages, cache.pages.items);
    return true;
}

fn replaceRemoteAppDirectoryCache(allocator: std.mem.Allocator, cache_key: []const u8, pages: []const []const u8) !void {
    var next_cache = AppDirectoryCache{
        .key = try allocator.dupe(u8, cache_key),
        .expires_at_ms = currentUnixMilliseconds() + APP_LIST_DIRECTORY_CACHE_TTL_MS,
        .pages = .empty,
    };
    var keep_next_cache = false;
    defer if (!keep_next_cache) next_cache.deinit(allocator);
    try appendOwnedRemoteAppDirectoryPages(allocator, &next_cache.pages, pages);

    const io = std.Io.Threaded.global_single_threaded.io();
    app_directory_cache_mutex.lockUncancelable(io);
    defer app_directory_cache_mutex.unlock(io);
    if (app_directory_cache) |*cache| cache.deinit(allocator);
    app_directory_cache = next_cache;
    keep_next_cache = true;
}

fn appendOwnedRemoteAppDirectoryPages(
    allocator: std.mem.Allocator,
    target: *std.ArrayList([]const u8),
    source: []const []const u8,
) !void {
    const initial_len = target.items.len;
    errdefer {
        for (target.items[initial_len..]) |page| allocator.free(page);
        target.shrinkRetainingCapacity(initial_len);
    }
    for (source) |page| {
        const owned = try allocator.dupe(u8, page);
        errdefer allocator.free(owned);
        try target.append(allocator, owned);
    }
}

fn fetchRemoteAppDirectoryPages(
    allocator: std.mem.Allocator,
    base_url: []const u8,
    credentials: auth_mod.Credentials,
    pages: *std.ArrayList([]const u8),
) !void {
    const initial_len = pages.items.len;
    errdefer {
        for (pages.items[initial_len..]) |page| allocator.free(page);
        pages.shrinkRetainingCapacity(initial_len);
    }

    var next_token: ?[]const u8 = null;
    defer if (next_token) |value| allocator.free(value);

    var page_count: usize = 0;
    while (page_count < APP_LIST_DIRECTORY_MAX_PAGES) : (page_count += 1) {
        const url = try remoteAppDirectoryListUrl(allocator, base_url, next_token);
        defer allocator.free(url);

        const body = try remote_plugin.fetchJsonBytes(allocator, url, credentials);
        errdefer allocator.free(body);
        const following_token = try remoteAppDirectoryNextToken(allocator, body);
        errdefer if (following_token) |value| allocator.free(value);

        try pages.append(allocator, body);
        if (next_token) |value| allocator.free(value);
        next_token = following_token;
        if (next_token == null) break;
    }
}

fn remoteAppDirectoryListUrl(allocator: std.mem.Allocator, base_url: []const u8, page_token: ?[]const u8) ![]const u8 {
    const trimmed = std.mem.trimEnd(u8, base_url, "/");
    if (trimmed.len == 0) return error.InvalidRemoteAppDirectoryBaseUrl;

    var url = std.ArrayList(u8).empty;
    errdefer url.deinit(allocator);
    try url.appendSlice(allocator, trimmed);
    try url.appendSlice(allocator, "/connectors/directory/list?");
    if (page_token) |token| {
        try url.appendSlice(allocator, "token=");
        try appendQueryComponent(allocator, &url, token);
        try url.append(allocator, '&');
    }
    try url.appendSlice(allocator, "external_logos=true");
    return url.toOwnedSlice(allocator);
}

fn remoteAppDirectoryNextToken(allocator: std.mem.Allocator, body: []const u8) !?[]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, body, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const token = remoteAppDirectoryStringField(parsed.value.object, "nextToken") orelse remoteAppDirectoryStringField(parsed.value.object, "next_token") orelse return null;
    const trimmed = std.mem.trim(u8, token, " \t\r\n");
    if (trimmed.len == 0) return null;
    const owned: []const u8 = try allocator.dupe(u8, trimmed);
    return owned;
}

fn remoteAppDirectoryStringField(object: std.json.ObjectMap, field: []const u8) ?[]const u8 {
    const value = object.get(field) orelse return null;
    if (value != .string) return null;
    return value.string;
}

fn appendQueryComponent(allocator: std.mem.Allocator, out: *std.ArrayList(u8), value: []const u8) !void {
    const hex = "0123456789ABCDEF";
    for (value) |byte| {
        if (std.ascii.isAlphanumeric(byte) or byte == '-' or byte == '.' or byte == '_' or byte == '~') {
            try out.append(allocator, byte);
        } else {
            try out.append(allocator, '%');
            try out.append(allocator, hex[byte >> 4]);
            try out.append(allocator, hex[byte & 0x0f]);
        }
    }
}

fn handleGetConversationSummary(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "getConversationSummary params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "getConversationSummary params must be an object");

    if (params.object.get("rolloutPath")) |rollout_path_value| {
        if (rollout_path_value != .string or rollout_path_value.string.len == 0) {
            return renderJsonRpcError(allocator, id_value, -32602, "rolloutPath must be a string");
        }

        var cfg = loadAppServerConfig(allocator, state) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "getConversationSummary failed to load config", err);
        };
        defer cfg.deinit(allocator);

        const path_raw = if (std.fs.path.isAbsolute(rollout_path_value.string))
            try allocator.dupe(u8, rollout_path_value.string)
        else
            try std.fs.path.join(allocator, &.{ cfg.codex_home, rollout_path_value.string });
        defer allocator.free(path_raw);

        return renderConversationSummaryResponseFromPath(allocator, id_value, cfg, path_raw, null, "rollout path", rollout_path_value.string);
    }

    if (params.object.get("conversationId")) |conversation_id_value| {
        if (conversation_id_value != .string or conversation_id_value.string.len == 0) {
            return renderJsonRpcError(allocator, id_value, -32602, "conversationId must be a string");
        }
        const conversation_id = conversation_id_value.string;
        if (findLoadedThread(state, conversation_id)) |thread| {
            var state_metadata: ?thread_state.ThreadMetadata = null;
            if (loadAppServerConfig(allocator, state)) |loaded_cfg| {
                var loaded_cfg_mut = loaded_cfg;
                defer loaded_cfg_mut.deinit(allocator);
                state_metadata = thread_state.findThreadMetadataByThreadId(allocator, configSqliteHome(loaded_cfg_mut), conversation_id) catch null;
            } else |_| {}
            defer if (state_metadata) |*metadata| metadata.deinit(allocator);

            const metadata = if (state_metadata) |*value| value else null;
            const result = try renderConversationSummaryResponseFromLoadedThread(allocator, thread, metadata);
            defer allocator.free(result);
            return renderJsonRpcResult(allocator, id_value, result);
        }

        var cfg = loadAppServerConfig(allocator, state) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "getConversationSummary failed to load config", err);
        };
        defer cfg.deinit(allocator);

        var state_metadata = thread_state.findThreadMetadataByThreadId(allocator, configSqliteHome(cfg), conversation_id) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "getConversationSummary failed to load state metadata", err);
        };
        defer if (state_metadata) |*metadata| metadata.deinit(allocator);

        const state_path = thread_state.findRolloutPathByThreadId(allocator, cfg.codex_home, configSqliteHome(cfg), conversation_id) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "getConversationSummary failed to resolve state thread path", err);
        };
        defer if (state_path) |path| allocator.free(path);

        const path_raw = if (state_path) |path|
            path
        else
            session_store.resolveResumePath(allocator, cfg.codex_home, conversation_id) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "getConversationSummary failed to resolve thread path", err);
            };
        defer if (state_path == null) allocator.free(path_raw);

        const metadata = if (state_metadata) |*value| value else null;
        return renderConversationSummaryResponseFromPath(allocator, id_value, cfg, path_raw, metadata, "thread id", conversation_id);
    }

    return renderJsonRpcError(allocator, id_value, -32602, "getConversationSummary params must include conversationId or rolloutPath");
}

fn renderConversationSummaryResponseFromPath(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    cfg: config.Config,
    path_raw: []const u8,
    metadata: ?*const thread_state.ThreadMetadata,
    target_kind: []const u8,
    target_value: []const u8,
) ![]const u8 {
    var transcript = session_store.loadTranscript(allocator, path_raw) catch |err| switch (err) {
        error.FileNotFound => {
            const message = try std.fmt.allocPrint(allocator, "no rollout found for {s} {s}", .{ target_kind, target_value });
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        },
        else => return renderJsonRpcErrorForFailure(allocator, id_value, "getConversationSummary failed to load transcript", err),
    };
    defer transcript.deinit(allocator);

    const real_path = std.Io.Dir.cwd().realPathFileAlloc(std.Io.Threaded.global_single_threaded.io(), path_raw, allocator) catch |err| switch (err) {
        error.FileNotFound => {
            const message = try std.fmt.allocPrint(allocator, "no rollout found for {s} {s}", .{ target_kind, target_value });
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        },
        else => return err,
    };
    defer allocator.free(real_path);

    const configured_model_provider = try config.loadModelProviderId(allocator, cfg.active_profile);
    defer if (configured_model_provider) |value| allocator.free(value);
    const fallback_model_provider = configured_model_provider orelse "openai";

    const result = try renderConversationSummaryResponseFromTranscript(allocator, real_path, &transcript, fallback_model_provider, metadata);
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn handleGitDiffToRemote(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "gitDiffToRemote params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "gitDiffToRemote params must be an object");

    const cwd_value = params.object.get("cwd") orelse return renderJsonRpcError(allocator, id_value, -32602, "cwd must be a string");
    if (cwd_value != .string or cwd_value.string.len == 0) {
        return renderJsonRpcError(allocator, id_value, -32602, "cwd must be a string");
    }

    var diff = git_remote_diff.compute(allocator, cwd_value.string) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => {
            const message = try std.fmt.allocPrint(allocator, "failed to compute git diff to remote for cwd: {s}", .{cwd_value.string});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32602, message);
        },
    };
    defer diff.deinit(allocator);

    const sha_json = try std.json.Stringify.valueAlloc(allocator, diff.sha, .{});
    defer allocator.free(sha_json);
    const diff_json = try std.json.Stringify.valueAlloc(allocator, diff.diff, .{});
    defer allocator.free(diff_json);
    const result = try std.fmt.allocPrint(allocator, "{{\"sha\":{s},\"diff\":{s}}}", .{ sha_json, diff_json });
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn handleFuzzyFileSearch(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "fuzzyFileSearch params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "fuzzyFileSearch params must be an object");

    const query_value = params.object.get("query") orelse return renderJsonRpcError(allocator, id_value, -32602, "query must be a string");
    if (query_value != .string) return renderJsonRpcError(allocator, id_value, -32602, "query must be a string");

    const roots = parseFuzzyFileSearchRoots(allocator, params.object.get("roots")) catch |err| switch (err) {
        error.InvalidFuzzyFileSearchRoots => return renderJsonRpcError(allocator, id_value, -32602, "roots must be an array of strings"),
        else => return err,
    };
    defer allocator.free(roots);

    if (params.object.get("cancellationToken")) |value| {
        if (value != .null and value != .string) {
            return renderJsonRpcError(allocator, id_value, -32602, "cancellationToken must be a string or null");
        }
    }

    var results = try fuzzy_file_search.search(allocator, query_value.string, roots);
    defer results.deinit(allocator);

    const result = try renderFuzzyFileSearchResult(allocator, results);
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn parseFuzzyFileSearchRoots(allocator: std.mem.Allocator, roots_value: ?std.json.Value) ![]const []const u8 {
    const value = roots_value orelse return error.InvalidFuzzyFileSearchRoots;
    if (value != .array) return error.InvalidFuzzyFileSearchRoots;
    const roots = try allocator.alloc([]const u8, value.array.items.len);
    errdefer allocator.free(roots);
    for (value.array.items, 0..) |item, index| {
        if (item != .string) return error.InvalidFuzzyFileSearchRoots;
        roots[index] = item.string;
    }
    return roots;
}

fn renderFuzzyFileSearchResult(allocator: std.mem.Allocator, results: fuzzy_file_search.Results) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);

    try out.appendSlice(allocator, "{\"files\":[");
    for (results.files, 0..) |file, index| {
        if (index > 0) try out.appendSlice(allocator, ",");
        try appendFuzzyFileSearchMatch(allocator, &out, file);
    }
    try out.appendSlice(allocator, "]}");
    return out.toOwnedSlice(allocator);
}

