const max_app_server_json_rpc_line_bytes = 16 * 1024 * 1024;
const max_user_input_text_chars: usize = 1 << 20;

const TurnStartInput = struct {
    prompt: []const u8,
    user_content_json: []const u8,
    image_urls: []const []const u8,
    local_image_paths: []const []const u8,
    skills: []const TurnNamedPathInput,
    mentions: []const TurnNamedPathInput,
    text_char_count: usize,

    fn deinit(self: *TurnStartInput, allocator: std.mem.Allocator) void {
        allocator.free(self.prompt);
        allocator.free(self.user_content_json);
        for (self.image_urls) |image_url| allocator.free(image_url);
        allocator.free(self.image_urls);
        for (self.local_image_paths) |path| allocator.free(path);
        allocator.free(self.local_image_paths);
        for (self.skills) |item| item.deinit(allocator);
        allocator.free(self.skills);
        for (self.mentions) |item| item.deinit(allocator);
        allocator.free(self.mentions);
    }
};

const TurnNamedPathInput = input_context.NamedPathInput;

const TurnLocalImages = struct {
    data_urls: []const []const u8 = &.{},
    missing_placeholders: []const []const u8 = &.{},

    fn deinit(self: *TurnLocalImages, allocator: std.mem.Allocator) void {
        for (self.data_urls) |data_url| allocator.free(data_url);
        if (self.data_urls.len > 0) allocator.free(self.data_urls);
        for (self.missing_placeholders) |placeholder| allocator.free(placeholder);
        if (self.missing_placeholders.len > 0) allocator.free(self.missing_placeholders);
    }
};

fn isReviewMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "review/start");
}

fn handleReviewMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) !?[]const u8 {
    if (std.mem.eql(u8, method, "review/start")) {
        return try handleReviewStart(allocator, state, id_value, params_value);
    }
    return try renderParsedButNotImplemented(allocator, id_value, method);
}

const ReviewStartTarget = union(enum) {
    uncommitted_changes,
    base_branch: []const u8,
    commit: Commit,
    custom: []const u8,

    const Commit = struct {
        sha: []const u8,
        title: ?[]const u8,
    };

    fn deinit(self: ReviewStartTarget, allocator: std.mem.Allocator) void {
        switch (self) {
            .uncommitted_changes => {},
            .base_branch => |branch| allocator.free(branch),
            .commit => |commit| {
                allocator.free(commit.sha);
                if (commit.title) |title| allocator.free(title);
            },
            .custom => |instructions| allocator.free(instructions),
        }
    }
};

const ReviewStartDelivery = enum {
    inline_delivery,
    detached,
};

fn validateReviewStartParamsObject(object: std.json.ObjectMap) !void {
    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        if (std.mem.eql(u8, entry.key_ptr.*, "threadId")) continue;
        if (std.mem.eql(u8, entry.key_ptr.*, "target")) continue;
        if (std.mem.eql(u8, entry.key_ptr.*, "delivery")) continue;
        return error.UnknownReviewStartParam;
    }
}

fn handleReviewStart(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) !?[]const u8 {
    const params = params_value orelse return try renderJsonRpcError(allocator, id_value, -32602, "review/start params must be an object");
    if (params != .object) return try renderJsonRpcError(allocator, id_value, -32602, "review/start params must be an object");
    const object = params.object;
    validateReviewStartParamsObject(object) catch |err| switch (err) {
        error.UnknownReviewStartParam => return try renderJsonRpcError(allocator, id_value, -32602, "review/start params only support threadId, target, and delivery"),
    };

    const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
        error.MissingThreadId => return try renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
    };
    if (!isUuidString(thread_id)) {
        return try renderInvalidThreadId(allocator, id_value, thread_id);
    }
    const thread_index = findLoadedThreadIndex(state, thread_id) orelse {
        return try renderThreadNotFound(allocator, id_value, thread_id);
    };

    var target = parseReviewStartTarget(allocator, object) catch |err| switch (err) {
        error.InvalidReviewTarget => return try renderJsonRpcError(allocator, id_value, -32602, "target must be a supported review target object"),
        error.EmptyReviewBranch => return try renderJsonRpcError(allocator, id_value, -32600, "branch must not be empty"),
        error.EmptyReviewSha => return try renderJsonRpcError(allocator, id_value, -32600, "sha must not be empty"),
        error.EmptyReviewInstructions => return try renderJsonRpcError(allocator, id_value, -32600, "instructions must not be empty"),
        else => return err,
    };
    defer target.deinit(allocator);

    const delivery = parseReviewStartDelivery(object) catch |err| switch (err) {
        error.InvalidReviewDelivery => return try renderJsonRpcError(allocator, id_value, -32602, "delivery must be inline, detached, or null"),
    };

    const parent_thread = &state.loaded_threads.items[thread_index];
    var cfg = loadConfigForLoadedThread(allocator, state, parent_thread) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "review/start failed to load config", err);
    };
    defer cfg.deinit(allocator);

    applyProjectLayersToConfigForCwd(allocator, &cfg, parent_thread.cwd) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "review/start failed to load project config", err);
    };

    applyLoadedThreadRuntimeToConfig(allocator, &cfg, parent_thread) catch |err| switch (err) {
        error.InvalidLoadedThreadRuntime => return try renderJsonRpcError(allocator, id_value, -32602, "invalid loaded review context"),
        else => return err,
    };
    try applyReviewStartConstraints(allocator, &cfg);
    try applyReviewModelForTurn(allocator, &cfg);

    var credentials = loadCredentialsForLoadedThread(allocator, &cfg, parent_thread) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "review/start failed to load auth", err);
    };
    defer credentials.deinit(allocator);

    const display_text = try buildReviewStartDisplayText(allocator, target);
    defer allocator.free(display_text);
    const prompt = try buildReviewStartPrompt(allocator, parent_thread.cwd, target);
    defer allocator.free(prompt);

    var review_thread_index = thread_index;
    if (delivery == .detached) {
        var detached_thread = createLoadedThreadForDetachedReview(allocator, cfg, parent_thread, state.session_source) catch |err| {
            return try renderJsonRpcErrorForFailure(allocator, id_value, "review/start failed to create detached review thread", err);
        };
        var detached_thread_moved = false;
        errdefer if (!detached_thread_moved) detached_thread.deinit(allocator);

        const thread_started_notification = try renderThreadStartedNotification(allocator, &detached_thread);
        var thread_started_notification_moved = false;
        errdefer if (!thread_started_notification_moved) allocator.free(thread_started_notification);

        const subscription_added = try ensureThreadSubscribed(allocator, state, detached_thread.id);
        var subscription_committed = false;
        errdefer {
            if (subscription_added and !subscription_committed) _ = removeThreadSubscription(allocator, state, detached_thread.id);
        }

        try state.loaded_threads.append(allocator, detached_thread);
        detached_thread_moved = true;
        subscription_committed = true;
        review_thread_index = state.loaded_threads.items.len - 1;
        try queueThreadStartedNotification(allocator, state, thread_started_notification);
        thread_started_notification_moved = true;
    }

    const thread = &state.loaded_threads.items[review_thread_index];

    const turn_id = try allocateNextTurnIdForThread(allocator, thread);
    defer allocator.free(turn_id);
    const review_next_turn_index = thread.next_turn_index;
    const started_at_ms = currentUnixMilliseconds();
    const started_at = @divTrunc(started_at_ms, std.time.ms_per_s);

    const response = try renderReviewStartResponse(allocator, turn_id, display_text, thread.id);
    defer allocator.free(response);
    const response_payload = try renderJsonRpcResult(allocator, id_value, response);
    var response_payload_moved = false;
    defer if (!response_payload_moved) allocator.free(response_payload);
    var turn_start_response_sent = false;
    const started_notification = try renderTurnNotification(allocator, "turn/started", thread.id, turn_id, "inProgress", started_at, null);
    var started_notification_moved = false;
    defer if (!started_notification_moved) allocator.free(started_notification);
    var turn_update_notifications = std.ArrayList([]const u8).empty;
    defer {
        for (turn_update_notifications.items) |notification| allocator.free(notification);
        turn_update_notifications.deinit(allocator);
    }

    var plan_update_context = PlanUpdateNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "turn/plan/updated"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var proposed_plan_context = ProposedPlanNotificationContext{
        .allocator = allocator,
        .started_enabled = !notificationMethodOptedOut(state, "item/started"),
        .delta_enabled = !notificationMethodOptedOut(state, "item/plan/delta"),
        .completed_enabled = !notificationMethodOptedOut(state, "item/completed"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var diff_update_context = DiffUpdateNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "turn/diff/updated"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .cwd = thread.cwd,
        .notifications = &turn_update_notifications,
    };
    var command_execution_output_context = CommandExecutionOutputNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "item/commandExecution/outputDelta"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var terminal_interaction_context = TerminalInteractionNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "item/commandExecution/terminalInteraction"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var file_change_patch_update_context = FileChangePatchUpdateNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "item/fileChange/patchUpdated"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var raw_response_item_context = RawResponseItemNotificationContext{
        .allocator = allocator,
        .raw_enabled = !notificationMethodOptedOut(state, "rawResponseItem/completed"),
        .item_started_enabled = !notificationMethodOptedOut(state, "item/started"),
        .item_completed_enabled = !notificationMethodOptedOut(state, "item/completed"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var reasoning_event_context = ReasoningEventNotificationContext{
        .allocator = allocator,
        .summary_text_delta_enabled = !notificationMethodOptedOut(state, "item/reasoning/summaryTextDelta"),
        .summary_part_added_enabled = !notificationMethodOptedOut(state, "item/reasoning/summaryPartAdded"),
        .text_delta_enabled = !notificationMethodOptedOut(state, "item/reasoning/textDelta"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var model_notification_context = ModelNotificationContext{
        .allocator = allocator,
        .cfg = &cfg,
        .credentials = &credentials,
        .rerouted_enabled = !notificationMethodOptedOut(state, "model/rerouted"),
        .verification_enabled = !notificationMethodOptedOut(state, "model/verification"),
        .requested_model = cfg.model,
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var mcp_startup_status_context = McpStartupStatusNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "mcpServer/startupStatus/updated"),
        .notifications = &turn_update_notifications,
    };
    var mcp_tool_call_progress_context = McpToolCallProgressNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "item/mcpToolCall/progress"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };

    const review_progress_sent = try maybeSendReviewStartProgress(
        allocator,
        state,
        thread,
        turn_id,
        response_payload,
        &turn_start_response_sent,
        started_notification,
        &started_notification_moved,
        display_text,
        started_at_ms,
    );

    const run_review_hooks = delivery == .inline_delivery;
    var hook_setup = prepareReviewStartHooks(allocator, state, thread, &cfg, turn_id, prompt, review_progress_sent, run_review_hooks) catch |err| {
        if (review_progress_sent) {
            const error_message = try std.fmt.allocPrint(allocator, "review/start failed to prepare review: {s}", .{@errorName(err)});
            defer allocator.free(error_message);
            try completeFailedReviewStartAfterProgress(allocator, state, thread, turn_id, display_text, error_message, started_at, review_next_turn_index);
            return null;
        }
        return try renderJsonRpcErrorForFailure(allocator, id_value, "review/start failed to prepare review", err);
    };
    defer hook_setup.deinit(allocator);
    const session_start_hooks = &hook_setup.session_start_hooks;
    const user_prompt_hooks = &hook_setup.user_prompt_hooks;

    var approval_context: AppServerApprovalContext = undefined;
    const approval_callback: ?tool_runner.ApprovalCallback = if (state.server_request_transport) |transport| blk: {
        approval_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread = thread,
            .thread_id = thread.id,
            .turn_id = turn_id,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &approval_context,
            .on_approval_requested = handleAppServerApprovalRequest,
        };
    } else null;

    var request_permissions_context: AppServerRequestPermissionsContext = undefined;
    const request_permissions_callback: ?session_mod.RequestPermissionsCallback = if (state.server_request_transport) |transport| blk: {
        request_permissions_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread = thread,
            .turn_id = turn_id,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &request_permissions_context,
            .on_request_permissions_requested = handleAppServerRequestPermissions,
        };
    } else null;

    var request_user_input_context: AppServerRequestUserInputContext = undefined;
    const request_user_input_callback: ?session_mod.RequestUserInputCallback = if (state.server_request_transport) |transport| blk: {
        request_user_input_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread_id = thread.id,
            .turn_id = turn_id,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &request_user_input_context,
            .on_request_user_input_requested = handleAppServerRequestUserInput,
        };
    } else null;

    var goal_tool_context = AppServerGoalToolContext{
        .allocator = allocator,
        .state = state,
        .sqlite_home = configSqliteHome(cfg),
        .thread = thread,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    const goal_tool_callback = session_mod.GoalToolCallback{
        .ctx = &goal_tool_context,
        .on_goal_tool_requested = handleAppServerGoalTool,
    };

    var external_auth_refresh_context: AppServerExternalAuthRefreshContext = undefined;
    const external_auth_refresh_callback: ?api.ExternalAuthRefreshCallback = if (state.server_request_transport) |transport| blk: {
        external_auth_refresh_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .codex_home = cfg.codex_home,
            .auth_store_mode = cfg.cli_auth_credentials_store_mode,
            .forced_chatgpt_workspace_id = cfg.forced_chatgpt_workspace_id,
            .thread_id = thread.id,
            .turn_id = turn_id,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &external_auth_refresh_context,
            .on_refresh = handleAppServerExternalAuthRefresh,
        };
    } else null;

    var mcp_elicitation_context: AppServerMcpElicitationContext = undefined;
    const mcp_elicitation_callback: ?mcp_runtime.ElicitationCallback = if (state.server_request_transport) |transport| blk: {
        mcp_elicitation_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread = thread,
            .thread_id = thread.id,
            .turn_id = turn_id,
            .auto_decline = cfg.approval_policy == .never,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &mcp_elicitation_context,
            .on_elicitation_requested = handleAppServerMcpElicitation,
        };
    } else null;

    var turn_feature_overrides = try effectiveAppServerTurnFeatureOverrides(allocator, state, thread);
    defer turn_feature_overrides.deinit(allocator);
    try applyReviewStartFeatureOverrides(allocator, &turn_feature_overrides);

    var review_transcript = session_mod.Transcript{};
    defer review_transcript.deinit(allocator);
    for (session_start_hooks.contexts.items) |context| {
        try review_transcript.appendDeveloperMessage(allocator, context);
    }

    if (session_start_hooks.should_stop or user_prompt_hooks.should_stop) {
        const completed_at_ms = currentUnixMilliseconds();
        const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
        const completed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "completed", started_at, completed_at);
        var completed_notification_moved = false;
        errdefer if (!completed_notification_moved) allocator.free(completed_notification);

        try refreshLoadedThreadAfterUnpersistedTurn(allocator, thread, display_text, review_next_turn_index);
        if (thread.path) |path| {
            try session_store.saveTranscript(allocator, path, &thread.transcript);
        }

        if (!review_progress_sent) {
            thread.status = .active;
            try queueThreadStatusChangedNotification(allocator, state, thread.id, .active);
            try queueTurnNotification(allocator, state, "turn/started", started_notification);
            started_notification_moved = true;
            try movePendingHookRuntimeNotifications(allocator, state, &session_start_hooks.notifications);
            try movePendingHookRuntimeNotifications(allocator, state, &user_prompt_hooks.notifications);
            try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "enteredReviewMode", display_text, "startedAtMs", started_at_ms);
            try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "enteredReviewMode", display_text, "completedAtMs", completed_at_ms);
        }
        try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "startedAtMs", completed_at_ms);
        try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "completedAtMs", completed_at_ms);
        try queueTurnNotification(allocator, state, "turn/completed", completed_notification);
        completed_notification_moved = true;
        thread.status = .idle;
        try queueThreadStatusChangedNotification(allocator, state, thread.id, .idle);

        if (turn_start_response_sent) return null;
        response_payload_moved = true;
        return response_payload;
    }

    var output_schema = try review_output_mod.parseOutputSchema(allocator);
    defer output_schema.deinit();
    const answer = session_mod.runTurnWithOptions(allocator, cfg, &credentials, &review_transcript, prompt, .{
        .prompt_for_approval = false,
        .approval_callback = approval_callback,
        .request_permissions_callback = request_permissions_callback,
        .request_user_input_callback = request_user_input_callback,
        .goal_tool_callback = goal_tool_callback,
        .mcp_elicitation_callback = mcp_elicitation_callback,
        .external_auth_refresh_callback = external_auth_refresh_callback,
        .additional_writable_roots = &.{},
        .read_denied_roots = thread.sandbox_read_denied_roots.items,
        .read_denied_globs = thread.sandbox_read_denied_globs.items,
        .include_cwd_write_root = false,
        .network_enabled = false,
        .developer_messages_after_user = user_prompt_hooks.contexts.items,
        .plan_update_callback = .{
            .ctx = &plan_update_context,
            .on_plan_updated = handleSessionPlanUpdated,
        },
        .proposed_plan_callback = .{
            .ctx = &proposed_plan_context,
            .on_proposed_plan = handleSessionProposedPlan,
        },
        .diff_update_callback = .{
            .ctx = &diff_update_context,
            .on_diff_updated = handleSessionDiffUpdated,
        },
        .command_execution_output_callback = .{
            .ctx = &command_execution_output_context,
            .on_command_execution_output = handleSessionCommandExecutionOutput,
        },
        .terminal_interaction_callback = .{
            .ctx = &terminal_interaction_context,
            .on_terminal_interaction = handleSessionTerminalInteraction,
        },
        .file_change_patch_update_callback = .{
            .ctx = &file_change_patch_update_context,
            .on_file_change_patch_updated = handleSessionFileChangePatchUpdated,
        },
        .raw_response_item_callback = .{
            .ctx = &raw_response_item_context,
            .on_raw_response_item = handleSessionRawResponseItem,
        },
        .reasoning_event_callback = .{
            .ctx = &reasoning_event_context,
            .on_reasoning_event = handleSessionReasoningEvent,
        },
        .server_model_callback = .{
            .ctx = &model_notification_context,
            .on_server_model = handleSessionServerModel,
        },
        .models_etag_callback = .{
            .ctx = &model_notification_context,
            .on_models_etag = handleSessionModelsEtag,
        },
        .model_verification_callback = .{
            .ctx = &model_notification_context,
            .on_model_verifications = handleSessionModelVerifications,
        },
        .mcp_tool_call_progress_callback = .{
            .ctx = &mcp_tool_call_progress_context,
            .on_mcp_tool_call_progress = handleSessionMcpToolCallProgress,
        },
        .mcp_startup_status_callback = .{
            .ctx = &mcp_startup_status_context,
            .on_startup_status = handleSessionMcpStartupStatus,
        },
        .output_schema = output_schema.value,
        .feature_overrides = turn_feature_overrides,
        .workdir = thread.cwd,
        .background_terminal_owner = thread.id,
        .subagent_runtime = &thread.subagents,
    }) catch |err| {
        if (err == error.AppServerApprovalCanceled) {
            const completed_at_ms = currentUnixMilliseconds();
            const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
            const completed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "interrupted", started_at, completed_at);
            var completed_notification_moved = false;
            errdefer if (!completed_notification_moved) allocator.free(completed_notification);

            try refreshLoadedThreadAfterUnpersistedTurn(allocator, thread, display_text, review_next_turn_index);
            if (thread.path) |path| {
                try session_store.saveTranscript(allocator, path, &thread.transcript);
            }

            if (!review_progress_sent) {
                thread.status = .active;
                try queueThreadStatusChangedNotification(allocator, state, thread.id, .active);
                try queueTurnNotification(allocator, state, "turn/started", started_notification);
                started_notification_moved = true;
                try movePendingHookRuntimeNotifications(allocator, state, &session_start_hooks.notifications);
                try movePendingHookRuntimeNotifications(allocator, state, &user_prompt_hooks.notifications);
                try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "enteredReviewMode", display_text, "startedAtMs", started_at_ms);
                try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "enteredReviewMode", display_text, "completedAtMs", completed_at_ms);
            }
            try movePendingTurnUpdateNotifications(allocator, state, &turn_update_notifications);
            try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "startedAtMs", completed_at_ms);
            try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "completedAtMs", completed_at_ms);
            try queueTurnNotification(allocator, state, "turn/completed", completed_notification);
            completed_notification_moved = true;
            thread.status = .idle;
            try queueThreadStatusChangedNotification(allocator, state, thread.id, .idle);

            if (turn_start_response_sent) return null;
            response_payload_moved = true;
            return response_payload;
        }

        const error_message = try std.fmt.allocPrint(allocator, "review/start failed to run review: {s}", .{@errorName(err)});
        defer allocator.free(error_message);
        const should_emit_started = turn_start_response_sent or
            session_start_hooks.notifications.items.len > 0 or
            user_prompt_hooks.notifications.items.len > 0;
        if (should_emit_started and !review_progress_sent) {
            const completed_at_ms = currentUnixMilliseconds();
            const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
            const failed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "failed", started_at, completed_at);
            var failed_notification_moved = false;
            errdefer if (!failed_notification_moved) allocator.free(failed_notification);
            thread.status = .active;
            try queueThreadStatusChangedNotification(allocator, state, thread.id, .active);
            try queueTurnNotification(allocator, state, "turn/started", started_notification);
            started_notification_moved = true;
            try movePendingHookRuntimeNotifications(allocator, state, &session_start_hooks.notifications);
            try movePendingHookRuntimeNotifications(allocator, state, &user_prompt_hooks.notifications);
            try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "enteredReviewMode", display_text, "startedAtMs", started_at_ms);
            try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "enteredReviewMode", display_text, "completedAtMs", completed_at_ms);
            try movePendingTurnUpdateNotifications(allocator, state, &turn_update_notifications);
            try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "startedAtMs", completed_at_ms);
            try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "completedAtMs", completed_at_ms);
            try queueTurnNotification(allocator, state, "turn/completed", failed_notification);
            failed_notification_moved = true;
        } else if (review_progress_sent) {
            const completed_at_ms = currentUnixMilliseconds();
            const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
            const failed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "failed", started_at, completed_at);
            var failed_notification_moved = false;
            errdefer if (!failed_notification_moved) allocator.free(failed_notification);
            try movePendingTurnUpdateNotifications(allocator, state, &turn_update_notifications);
            try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "startedAtMs", completed_at_ms);
            try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "completedAtMs", completed_at_ms);
            try queueTurnNotification(allocator, state, "turn/completed", failed_notification);
            failed_notification_moved = true;
        }
        thread.status = .system_error;
        try refreshLoadedThreadAfterUnpersistedTurn(allocator, thread, display_text, review_next_turn_index);
        if (thread.path) |path| {
            try session_store.saveTranscript(allocator, path, &thread.transcript);
        }
        try queueErrorNotification(allocator, state, thread.id, turn_id, error_message, false);
        try queueThreadStatusChangedNotification(allocator, state, thread.id, .system_error);
        if (turn_start_response_sent) return null;
        return try renderJsonRpcError(allocator, id_value, -32603, error_message);
    };
    defer allocator.free(answer);

    const completed_at_ms = currentUnixMilliseconds();
    const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
    const completed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "completed", started_at, completed_at);
    var completed_notification_moved = false;
    errdefer if (!completed_notification_moved) allocator.free(completed_notification);

    const review_output = try renderReviewStartOutputText(allocator, answer);
    defer allocator.free(review_output);
    const review_context = try renderReviewStartRolloutUserMessage(allocator, review_output);
    defer allocator.free(review_context);
    try thread.transcript.appendUserMessage(allocator, review_context);
    try thread.transcript.appendAssistantMessage(allocator, review_output);
    const assistant_item_index = thread.transcript.history.items.len - 1;

    try refreshLoadedThreadAfterReviewTurn(allocator, thread, display_text, review_next_turn_index);
    if (thread.path) |path| {
        try session_store.saveTranscript(allocator, path, &thread.transcript);
    }

    if (!review_progress_sent) {
        try queueTurnStartOpeningNotifications(
            allocator,
            state,
            thread,
            started_notification,
            &started_notification_moved,
            &session_start_hooks.notifications,
            &user_prompt_hooks.notifications,
        );
        try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "enteredReviewMode", display_text, "startedAtMs", started_at_ms);
        try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "enteredReviewMode", display_text, "completedAtMs", completed_at_ms);
    }
    try movePendingTurnUpdateNotifications(allocator, state, &turn_update_notifications);
    try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "exitedReviewMode", review_output, "startedAtMs", completed_at_ms);
    try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "exitedReviewMode", review_output, "completedAtMs", completed_at_ms);
    if (review_output.len > 0) {
        try queueAgentMessageItemNotification(allocator, state, "item/started", thread.id, turn_id, assistant_item_index, review_output, "startedAtMs", completed_at_ms);
        try queueAgentMessageItemNotification(allocator, state, "item/completed", thread.id, turn_id, assistant_item_index, review_output, "completedAtMs", completed_at_ms);
    }
    try queueTurnNotification(allocator, state, "turn/completed", completed_notification);
    completed_notification_moved = true;
    thread.status = .idle;
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .idle);

    if (turn_start_response_sent) return null;
    response_payload_moved = true;
    return response_payload;
}

fn parseReviewStartDelivery(params: std.json.ObjectMap) !ReviewStartDelivery {
    const delivery_value = params.get("delivery") orelse return .inline_delivery;
    if (delivery_value == .null) return .inline_delivery;
    if (delivery_value != .string) return error.InvalidReviewDelivery;
    if (std.mem.eql(u8, delivery_value.string, "inline")) return .inline_delivery;
    if (std.mem.eql(u8, delivery_value.string, "detached")) return .detached;
    return error.InvalidReviewDelivery;
}

fn parseReviewStartTarget(allocator: std.mem.Allocator, params: std.json.ObjectMap) !ReviewStartTarget {
    const target_value = params.get("target") orelse return error.InvalidReviewTarget;
    if (target_value != .object) return error.InvalidReviewTarget;
    const target = target_value.object;
    const target_type_value = target.get("type") orelse return error.InvalidReviewTarget;
    if (target_type_value != .string) return error.InvalidReviewTarget;
    const target_type = target_type_value.string;
    if (std.mem.eql(u8, target_type, "uncommittedChanges")) {
        if (!reviewTargetObjectHasOnlyKeys(target, &.{"type"})) return error.InvalidReviewTarget;
        return .uncommitted_changes;
    }
    if (std.mem.eql(u8, target_type, "baseBranch")) {
        if (!reviewTargetObjectHasOnlyKeys(target, &.{ "type", "branch" })) return error.InvalidReviewTarget;
        const branch_value = target.get("branch") orelse return error.InvalidReviewTarget;
        if (branch_value != .string) return error.InvalidReviewTarget;
        const branch = std.mem.trim(u8, branch_value.string, " \t\r\n");
        if (branch.len == 0) return error.EmptyReviewBranch;
        return .{ .base_branch = try allocator.dupe(u8, branch) };
    }
    if (std.mem.eql(u8, target_type, "commit")) {
        if (!reviewTargetObjectHasOnlyKeys(target, &.{ "type", "sha", "title" })) return error.InvalidReviewTarget;
        const sha_value = target.get("sha") orelse return error.InvalidReviewTarget;
        if (sha_value != .string) return error.InvalidReviewTarget;
        const sha = std.mem.trim(u8, sha_value.string, " \t\r\n");
        if (sha.len == 0) return error.EmptyReviewSha;
        const sha_copy = try allocator.dupe(u8, sha);
        errdefer allocator.free(sha_copy);
        var title_copy: ?[]const u8 = null;
        errdefer if (title_copy) |title| allocator.free(title);
        if (target.get("title")) |title_value| {
            if (title_value != .null) {
                if (title_value != .string) return error.InvalidReviewTarget;
                const title = std.mem.trim(u8, title_value.string, " \t\r\n");
                if (title.len > 0) {
                    title_copy = try allocator.dupe(u8, title);
                }
            }
        }
        return .{ .commit = .{ .sha = sha_copy, .title = title_copy } };
    }
    if (std.mem.eql(u8, target_type, "custom")) {
        if (!reviewTargetObjectHasOnlyKeys(target, &.{ "type", "instructions" })) return error.InvalidReviewTarget;
        const instructions_value = target.get("instructions") orelse return error.InvalidReviewTarget;
        if (instructions_value != .string) return error.InvalidReviewTarget;
        const instructions = std.mem.trim(u8, instructions_value.string, " \t\r\n");
        if (instructions.len == 0) return error.EmptyReviewInstructions;
        return .{ .custom = try allocator.dupe(u8, instructions) };
    }
    return error.InvalidReviewTarget;
}

fn reviewTargetObjectHasOnlyKeys(target: std.json.ObjectMap, allowed_keys: []const []const u8) bool {
    var iterator = target.iterator();
    while (iterator.next()) |entry| {
        var allowed = false;
        for (allowed_keys) |allowed_key| {
            if (std.mem.eql(u8, entry.key_ptr.*, allowed_key)) {
                allowed = true;
                break;
            }
        }
        if (!allowed) return false;
    }
    return true;
}

fn applyReviewModelForTurn(allocator: std.mem.Allocator, cfg: *config.Config) !void {
    const review_model = cfg.review_model orelse return;
    try replaceOwnedString(allocator, &cfg.model, review_model);
}

fn buildReviewStartDisplayText(allocator: std.mem.Allocator, target: ReviewStartTarget) ![]const u8 {
    switch (target) {
        .uncommitted_changes => return allocator.dupe(u8, "current changes"),
        .base_branch => |branch| return std.fmt.allocPrint(allocator, "changes against '{s}'", .{branch}),
        .commit => |commit| {
            const short_len = @min(commit.sha.len, 7);
            const short_sha = commit.sha[0..short_len];
            if (commit.title) |title| {
                return std.fmt.allocPrint(allocator, "commit {s}: {s}", .{ short_sha, title });
            }
            return std.fmt.allocPrint(allocator, "commit {s}", .{short_sha});
        },
        .custom => |instructions| return allocator.dupe(u8, instructions),
    }
}

fn buildReviewStartPrompt(allocator: std.mem.Allocator, cwd: []const u8, target: ReviewStartTarget) ![]const u8 {
    switch (target) {
        .uncommitted_changes => return allocator.dupe(u8, "Review the current code changes (staged, unstaged, and untracked files) and provide prioritized findings."),
        .base_branch => |branch| {
            const merge_base = git_diff.mergeBaseWithHead(allocator, cwd, branch) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => null,
            };
            defer if (merge_base) |base| allocator.free(base);
            if (merge_base) |base| {
                return std.fmt.allocPrint(allocator, "Review the code changes against the base branch '{s}'. The merge base commit for this comparison is {s}. Run `git diff {s}` to inspect the changes relative to {s}. Provide prioritized, actionable findings.", .{ branch, base, base, branch });
            }
            return std.fmt.allocPrint(allocator, "Review the code changes against the base branch '{s}'. The merge base could not be precomputed, so inspect it with read-only git commands: run `git rev-parse --abbrev-ref --symbolic-full-name {s}@{{upstream}}`; if that succeeds, run `git merge-base HEAD <upstream-ref>`, otherwise run `git merge-base HEAD {s}`; then run `git diff <merge-base-sha>` to see what changes we would merge into {s}. Provide prioritized, actionable findings.", .{ branch, branch, branch, branch });
        },
        .commit => |commit| {
            if (commit.title) |title| {
                return std.fmt.allocPrint(allocator, "Review the code changes introduced by commit {s} (\"{s}\"). Provide prioritized, actionable findings.", .{ commit.sha, title });
            }
            return std.fmt.allocPrint(allocator, "Review the code changes introduced by commit {s}. Provide prioritized, actionable findings.", .{commit.sha});
        },
        .custom => |instructions| return allocator.dupe(u8, instructions),
    }
}

fn renderReviewStartOutputText(allocator: std.mem.Allocator, text: []const u8) ![]const u8 {
    return review_output_mod.renderText(allocator, text);
}

test "review output JSON fallback releases partial render buffer" {
    const malformed =
        \\{"overall_explanation":"Looks partial","findings":[{"title":"Missing body"}]}
    ;

    const rendered = try renderReviewStartOutputText(std.testing.allocator, malformed);
    defer std.testing.allocator.free(rendered);

    try std.testing.expectEqualStrings(malformed, rendered);
}

test "base branch review prompt falls back when merge base cannot be precomputed" {
    const prompt = try buildReviewStartPrompt(std.testing.allocator, "/definitely-not-a-codex-zig-port-repo", .{ .base_branch = "main" });
    defer std.testing.allocator.free(prompt);

    try std.testing.expect(std.mem.indexOf(u8, prompt, "The merge base could not be precomputed") != null);
    try std.testing.expect(std.mem.indexOf(u8, prompt, "git merge-base HEAD main") != null);
}

test "review target parser rejects extra target fields" {
    var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator,
        \\{"target":{"type":"baseBranch","branch":"main","sha":"abc123"}}
    , .{});
    defer parsed.deinit();

    try std.testing.expectError(error.InvalidReviewTarget, parseReviewStartTarget(std.testing.allocator, parsed.value.object));
}

fn renderReviewStartRolloutUserMessage(allocator: std.mem.Allocator, review_output: []const u8) ![]const u8 {
    return std.fmt.allocPrint(allocator,
        \\<user_action>
        \\  <context>User initiated a review task. Here's the full review output from reviewer model. User may select one or more comments to resolve.</context>
        \\  <action>review</action>
        \\  <results>
        \\  {s}
        \\  </results>
        \\  </user_action>
        \\
    , .{review_output});
}

fn renderReviewStartResponse(
    allocator: std.mem.Allocator,
    turn_id: []const u8,
    display_text: []const u8,
    review_thread_id: []const u8,
) ![]const u8 {
    var response = std.ArrayList(u8).empty;
    errdefer response.deinit(allocator);
    try response.appendSlice(allocator, "{\"turn\":");
    try appendReviewStartTurnJson(allocator, &response, turn_id, display_text);
    try response.appendSlice(allocator, ",\"reviewThreadId\":");
    try appendJsonString(allocator, &response, review_thread_id);
    try response.append(allocator, '}');
    return response.toOwnedSlice(allocator);
}

fn appendReviewStartTurnJson(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    turn_id: []const u8,
    display_text: []const u8,
) !void {
    try out.appendSlice(allocator, "{\"id\":");
    try appendJsonString(allocator, out, turn_id);
    try out.appendSlice(allocator, ",\"items\":[{\"type\":\"userMessage\",\"id\":");
    try appendJsonString(allocator, out, turn_id);
    try out.appendSlice(allocator, ",\"content\":[{\"type\":\"text\",\"text\":");
    try appendJsonString(allocator, out, display_text);
    try out.appendSlice(allocator, ",\"text_elements\":[]}]}],\"itemsView\":\"notLoaded\",\"status\":\"inProgress\",\"error\":null,\"startedAt\":null,\"completedAt\":null,\"durationMs\":null}");
}

fn maybeSendReviewStartProgress(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread: *LoadedThread,
    turn_id: []const u8,
    response_payload: []const u8,
    turn_start_response_sent: *bool,
    started_notification: []const u8,
    started_notification_moved: *bool,
    display_text: []const u8,
    started_at_ms: i64,
) !bool {
    const transport = state.server_request_transport orelse return false;
    if (!turn_start_response_sent.*) {
        try transport.send_payload(transport.ctx, response_payload);
        turn_start_response_sent.* = true;
    }

    thread.status = .active;
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .active);
    try queueTurnNotification(allocator, state, "turn/started", started_notification);
    started_notification_moved.* = true;
    try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "enteredReviewMode", display_text, "startedAtMs", started_at_ms);
    try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "enteredReviewMode", display_text, "completedAtMs", currentUnixMilliseconds());
    try flushPendingNotificationsToTransport(allocator, state, transport);
    return true;
}

fn queueTurnStartOpeningNotifications(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread: *LoadedThread,
    started_notification: []const u8,
    started_notification_moved: *bool,
    session_start_notifications: *std.ArrayList(HookRuntimeNotification),
    user_prompt_notifications: *std.ArrayList(HookRuntimeNotification),
) !void {
    thread.status = .active;
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .active);
    try queueTurnNotification(allocator, state, "turn/started", started_notification);
    started_notification_moved.* = true;
    try movePendingHookRuntimeNotifications(allocator, state, session_start_notifications);
    try movePendingHookRuntimeNotifications(allocator, state, user_prompt_notifications);
}

fn queueTurnUserMessageItemIfPresent(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread: *LoadedThread,
    turn_id: []const u8,
    user_item_index: usize,
    user_content_json: []const u8,
    started_at_ms: i64,
    completed_at_ms: i64,
) !void {
    if (user_item_index >= thread.transcript.history.items.len) return;
    const user_item = thread.transcript.history.items[user_item_index];
    if (user_item.kind != .message or !isHistoryRole(user_item, "user")) return;
    try queueUserMessageItemNotification(allocator, state, "item/started", thread.id, turn_id, user_item_index, user_content_json, "startedAtMs", started_at_ms);
    try queueUserMessageItemNotification(allocator, state, "item/completed", thread.id, turn_id, user_item_index, user_content_json, "completedAtMs", completed_at_ms);
}

fn maybeSendTurnStartProgress(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread: *LoadedThread,
    response_payload: []const u8,
    turn_start_response_sent: *bool,
    started_notification: []const u8,
    started_notification_moved: *bool,
    session_start_notifications: *std.ArrayList(HookRuntimeNotification),
    user_prompt_notifications: *std.ArrayList(HookRuntimeNotification),
) !bool {
    const transport = state.server_request_transport orelse return false;
    if (!turn_start_response_sent.*) {
        try transport.send_payload(transport.ctx, response_payload);
        turn_start_response_sent.* = true;
    }

    try queueTurnStartOpeningNotifications(
        allocator,
        state,
        thread,
        started_notification,
        started_notification_moved,
        session_start_notifications,
        user_prompt_notifications,
    );
    try flushPendingNotificationsToTransport(allocator, state, transport);
    return true;
}

const ReviewStartHookSetup = struct {
    session_start_hooks: HookRuntimeResult = .{},
    user_prompt_hooks: HookRuntimeResult = .{},

    fn deinit(self: *ReviewStartHookSetup, allocator: std.mem.Allocator) void {
        self.session_start_hooks.deinit(allocator);
        self.user_prompt_hooks.deinit(allocator);
    }
};

fn prepareReviewStartHooks(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread: *LoadedThread,
    cfg: *const config.Config,
    turn_id: []const u8,
    prompt: []const u8,
    review_progress_sent: bool,
    run_hooks: bool,
) !ReviewStartHookSetup {
    var setup = ReviewStartHookSetup{};
    errdefer setup.deinit(allocator);

    if (!run_hooks) return setup;

    try materializeHookTranscriptForThread(allocator, thread);
    if (thread.pending_session_start_source) |source| {
        thread.pending_session_start_source = null;
        defer allocator.free(source);
        setup.session_start_hooks = try runSessionStartHooks(
            allocator,
            cfg.codex_home,
            thread.id,
            turn_id,
            thread.path,
            thread.cwd,
            cfg.model,
            hookPermissionMode(cfg.approval_policy),
            source,
            state.bypass_hook_trust,
        );
    }
    if (setup.session_start_hooks.contexts.items.len > 0) {
        try persistHookContextsForNextTurn(allocator, thread, setup.session_start_hooks.contexts.items);
    }

    if (!setup.session_start_hooks.should_stop) {
        setup.user_prompt_hooks = try runUserPromptSubmitHooks(
            allocator,
            cfg.codex_home,
            thread.id,
            turn_id,
            thread.path,
            thread.cwd,
            cfg.model,
            hookPermissionMode(cfg.approval_policy),
            prompt,
            state.bypass_hook_trust,
        );
    }
    if (review_progress_sent) {
        try movePendingHookRuntimeNotifications(allocator, state, &setup.session_start_hooks.notifications);
        try movePendingHookRuntimeNotifications(allocator, state, &setup.user_prompt_hooks.notifications);
        try flushPendingNotificationsToActiveTransport(allocator, state);
    }

    return setup;
}

fn completeFailedReviewStartAfterProgress(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread: *LoadedThread,
    turn_id: []const u8,
    display_text: []const u8,
    error_message: []const u8,
    started_at: i64,
    minimum_next_turn_index: usize,
) !void {
    const completed_at_ms = currentUnixMilliseconds();
    const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
    const failed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "failed", started_at, completed_at);
    var failed_notification_moved = false;
    errdefer if (!failed_notification_moved) allocator.free(failed_notification);

    try queueReviewModeItemNotification(allocator, state, "item/started", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "startedAtMs", completed_at_ms);
    try queueReviewModeItemNotification(allocator, state, "item/completed", thread.id, turn_id, "exitedReviewMode", "Reviewer failed to output a response.", "completedAtMs", completed_at_ms);
    try queueTurnNotification(allocator, state, "turn/completed", failed_notification);
    failed_notification_moved = true;
    thread.status = .system_error;
    try queueErrorNotification(allocator, state, thread.id, turn_id, error_message, false);
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .system_error);

    refreshLoadedThreadAfterUnpersistedTurn(allocator, thread, display_text, minimum_next_turn_index) catch {};
    if (thread.path) |path| {
        session_store.saveTranscript(allocator, path, &thread.transcript) catch {};
    }
}

fn flushPendingNotificationsToActiveTransport(allocator: std.mem.Allocator, state: *AppServerState) !void {
    const transport = state.server_request_transport orelse return;
    try flushPendingNotificationsToTransport(allocator, state, transport);
}

fn flushPendingNotificationsToTransport(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    transport: ServerRequestTransport,
) !void {
    var notifications = state.pending_notifications;
    state.pending_notifications = .empty;
    defer freePendingNotifications(allocator, &notifications);
    for (notifications.items) |payload| {
        try transport.send_payload(transport.ctx, payload);
    }
}

fn isTurnMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "turn/start") or
        std.mem.eql(u8, method, "turn/steer") or
        std.mem.eql(u8, method, "turn/interrupt");
}

fn handleTurnMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) !?[]const u8 {
    if (std.mem.eql(u8, method, "turn/start")) {
        return try handleTurnStart(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "turn/steer")) {
        return try handleTurnSteer(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "turn/interrupt")) {
        return try handleTurnInterrupt(allocator, state, id_value, params_value);
    }
    return try renderParsedButNotImplemented(allocator, id_value, method);
}

fn handleTurnStart(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) !?[]const u8 {
    const params = params_value orelse return try renderJsonRpcError(allocator, id_value, -32602, "turn/start params must be an object");
    if (params != .object) return try renderJsonRpcError(allocator, id_value, -32602, "turn/start params must be an object");
    const object = params.object;

    const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
        error.MissingThreadId => return try renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
    };
    if (!isUuidString(thread_id)) {
        return try renderInvalidThreadId(allocator, id_value, thread_id);
    }
    const thread_index = findLoadedThreadIndex(state, thread_id) orelse {
        return try renderThreadNotFound(allocator, id_value, thread_id);
    };

    var input = parseTurnStartInput(allocator, object) catch |err| switch (err) {
        error.InvalidTurnInput => return try renderJsonRpcError(allocator, id_value, -32602, "input must be an array of supported user input items"),
        error.EmptyTurnInput => return try renderJsonRpcError(allocator, id_value, -32600, "input must include text or image"),
        error.UnsupportedTurnInput => return try renderJsonRpcError(allocator, id_value, -32600, "only text, image, localImage, skill, and mention turn/start input is implemented"),
        else => return err,
    };
    defer input.deinit(allocator);
    if (input.text_char_count > max_user_input_text_chars) {
        return try renderTurnInputTooLargeError(allocator, id_value, input.text_char_count);
    }

    const thread = &state.loaded_threads.items[thread_index];
    var cfg = loadConfigForLoadedThread(allocator, state, thread) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "turn/start failed to load config", err);
    };
    defer cfg.deinit(allocator);

    const project_cwd = turnContextProjectConfigCwd(allocator, thread, object) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "turn/start failed to resolve cwd", err);
    };
    defer allocator.free(project_cwd);

    applyProjectLayersToConfigForCwd(allocator, &cfg, project_cwd) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "turn/start failed to load project config", err);
    };

    var runtime_requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "turn/start failed to load config requirements", err);
    };
    defer runtime_requirements.deinit(allocator);
    validateTurnScalarRequirementOverrides(allocator, cfg.codex_home, project_cwd, object, runtime_requirements) catch |err| switch (err) {
        error.InvalidTurnContextOverride => return try renderJsonRpcError(allocator, id_value, -32602, "invalid turn context override"),
        else => return try renderRuntimeRequirementOverrideError(allocator, id_value, err),
    };

    applyTurnStartRuntimeConfigOverrides(allocator, &cfg, thread, object) catch |err| switch (err) {
        error.InvalidTurnContextOverride => return try renderJsonRpcError(allocator, id_value, -32602, "invalid turn context override"),
        else => return err,
    };
    applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, runtime_requirements) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "turn/start failed to apply config requirements", err);
    };

    var credentials = loadCredentialsForLoadedThread(allocator, &cfg, thread) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "turn/start failed to load auth", err);
    };
    defer credentials.deinit(allocator);

    applyTurnStartRuntimeOverrides(allocator, &cfg, thread, object, true) catch |err| switch (err) {
        error.InvalidTurnContextOverride => return try renderJsonRpcError(allocator, id_value, -32602, "invalid turn context override"),
        else => return err,
    };
    applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(allocator, thread, runtime_requirements) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "turn/start failed to apply runtime requirements", err);
    };
    applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, runtime_requirements) catch |err| {
        return try renderJsonRpcErrorForFailure(allocator, id_value, "turn/start failed to apply config requirements", err);
    };

    const turn_id = try allocateNextTurnIdForThread(allocator, thread);
    defer allocator.free(turn_id);

    var local_images = try loadTurnLocalImages(allocator, thread.cwd, input.local_image_paths);
    defer local_images.deinit(allocator);
    const request_input_images = try combineTurnInputImages(allocator, input.image_urls, local_images.data_urls);
    defer if (request_input_images.len > 0) allocator.free(request_input_images);
    var skill_injections = try loadTurnSkillInjections(allocator, state, thread.cwd, input.skills);
    defer skill_injections.deinit(allocator);
    var mention_markers = try renderTurnMentionMarkers(allocator, input.mentions);
    defer mention_markers.deinit(allocator);
    const prompt_for_turn = try turnPromptWithContextBlocks(allocator, input.prompt, local_images.missing_placeholders, skill_injections.blocks, mention_markers.markers);
    defer allocator.free(prompt_for_turn);
    const started_at_ms = currentUnixMilliseconds();
    const started_at = @divTrunc(started_at_ms, std.time.ms_per_s);
    try materializeHookTranscriptForThread(allocator, thread);

    var session_start_hooks = HookRuntimeResult{};
    defer session_start_hooks.deinit(allocator);
    if (thread.pending_session_start_source) |source| {
        thread.pending_session_start_source = null;
        defer allocator.free(source);
        session_start_hooks = try runSessionStartHooks(
            allocator,
            cfg.codex_home,
            thread.id,
            turn_id,
            thread.path,
            thread.cwd,
            cfg.model,
            hookPermissionMode(cfg.approval_policy),
            source,
            state.bypass_hook_trust,
        );
    }
    if (session_start_hooks.contexts.items.len > 0) {
        try persistHookContextsForNextTurn(allocator, thread, session_start_hooks.contexts.items);
    }

    var user_prompt_hooks = HookRuntimeResult{};
    defer user_prompt_hooks.deinit(allocator);
    if (!session_start_hooks.should_stop) {
        user_prompt_hooks = try runUserPromptSubmitHooks(
            allocator,
            cfg.codex_home,
            thread.id,
            turn_id,
            thread.path,
            thread.cwd,
            cfg.model,
            hookPermissionMode(cfg.approval_policy),
            input.prompt,
            state.bypass_hook_trust,
        );
    }

    const response = try renderTurnStartResponse(allocator, turn_id);
    defer allocator.free(response);
    const response_payload = try renderJsonRpcResult(allocator, id_value, response);
    var response_payload_moved = false;
    defer if (!response_payload_moved) allocator.free(response_payload);
    var turn_start_response_sent = false;
    const user_item_index = thread.transcript.history.items.len;
    const started_notification = try renderTurnNotification(allocator, "turn/started", thread.id, turn_id, "inProgress", started_at, null);
    var started_notification_moved = false;
    errdefer if (!started_notification_moved) allocator.free(started_notification);
    var turn_update_notifications = std.ArrayList([]const u8).empty;
    defer {
        for (turn_update_notifications.items) |notification| allocator.free(notification);
        turn_update_notifications.deinit(allocator);
    }
    var plan_update_context = PlanUpdateNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "turn/plan/updated"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var proposed_plan_context = ProposedPlanNotificationContext{
        .allocator = allocator,
        .started_enabled = !notificationMethodOptedOut(state, "item/started"),
        .delta_enabled = !notificationMethodOptedOut(state, "item/plan/delta"),
        .completed_enabled = !notificationMethodOptedOut(state, "item/completed"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var diff_update_context = DiffUpdateNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "turn/diff/updated"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .cwd = thread.cwd,
        .notifications = &turn_update_notifications,
    };
    var command_execution_output_context = CommandExecutionOutputNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "item/commandExecution/outputDelta"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var terminal_interaction_context = TerminalInteractionNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "item/commandExecution/terminalInteraction"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var file_change_patch_update_context = FileChangePatchUpdateNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "item/fileChange/patchUpdated"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var raw_response_item_context = RawResponseItemNotificationContext{
        .allocator = allocator,
        .raw_enabled = !notificationMethodOptedOut(state, "rawResponseItem/completed"),
        .item_started_enabled = !notificationMethodOptedOut(state, "item/started"),
        .item_completed_enabled = !notificationMethodOptedOut(state, "item/completed"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var reasoning_event_context = ReasoningEventNotificationContext{
        .allocator = allocator,
        .summary_text_delta_enabled = !notificationMethodOptedOut(state, "item/reasoning/summaryTextDelta"),
        .summary_part_added_enabled = !notificationMethodOptedOut(state, "item/reasoning/summaryPartAdded"),
        .text_delta_enabled = !notificationMethodOptedOut(state, "item/reasoning/textDelta"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var model_notification_context = ModelNotificationContext{
        .allocator = allocator,
        .cfg = &cfg,
        .credentials = &credentials,
        .rerouted_enabled = !notificationMethodOptedOut(state, "model/rerouted"),
        .verification_enabled = !notificationMethodOptedOut(state, "model/verification"),
        .requested_model = cfg.model,
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    var mcp_startup_status_context = McpStartupStatusNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "mcpServer/startupStatus/updated"),
        .notifications = &turn_update_notifications,
    };
    var mcp_tool_call_progress_context = McpToolCallProgressNotificationContext{
        .allocator = allocator,
        .enabled = !notificationMethodOptedOut(state, "item/mcpToolCall/progress"),
        .thread_id = thread.id,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };

    if (session_start_hooks.should_stop or user_prompt_hooks.should_stop) {
        const completed_at_ms = currentUnixMilliseconds();
        const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
        const completed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "completed", started_at, completed_at);
        var completed_notification_moved = false;
        errdefer if (!completed_notification_moved) allocator.free(completed_notification);

        try persistHookContextsForNextTurn(allocator, thread, user_prompt_hooks.contexts.items);
        if (thread.path) |path| {
            try session_store.saveTranscript(allocator, path, &thread.transcript);
        }

        try queueTurnStartOpeningNotifications(
            allocator,
            state,
            thread,
            started_notification,
            &started_notification_moved,
            &session_start_hooks.notifications,
            &user_prompt_hooks.notifications,
        );
        try queueTurnNotification(allocator, state, "turn/completed", completed_notification);
        completed_notification_moved = true;
        thread.status = .idle;
        try queueThreadStatusChangedNotification(allocator, state, thread.id, .idle);

        if (turn_start_response_sent) return null;
        response_payload_moved = true;
        return response_payload;
    }

    var pending_steers = AppServerPendingTurnInputQueue{};
    defer pending_steers.deinit(allocator);
    const pending_input_callback = session_mod.PendingInputCallback{
        .ctx = &pending_steers,
        .on_drain_pending_input = drainAppServerPendingTurnInput,
    };

    var approval_context: AppServerApprovalContext = undefined;
    const approval_callback: ?tool_runner.ApprovalCallback = if (state.server_request_transport) |transport| blk: {
        approval_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread = thread,
            .thread_id = thread.id,
            .turn_id = turn_id,
            .pending_steers = &pending_steers,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &approval_context,
            .on_approval_requested = handleAppServerApprovalRequest,
        };
    } else null;

    var request_permissions_context: AppServerRequestPermissionsContext = undefined;
    const request_permissions_callback: ?session_mod.RequestPermissionsCallback = if (state.server_request_transport) |transport| blk: {
        request_permissions_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread = thread,
            .turn_id = turn_id,
            .pending_steers = &pending_steers,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &request_permissions_context,
            .on_request_permissions_requested = handleAppServerRequestPermissions,
        };
    } else null;

    var request_user_input_context: AppServerRequestUserInputContext = undefined;
    const request_user_input_callback: ?session_mod.RequestUserInputCallback = if (state.server_request_transport) |transport| blk: {
        request_user_input_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread = thread,
            .thread_id = thread.id,
            .turn_id = turn_id,
            .pending_steers = &pending_steers,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &request_user_input_context,
            .on_request_user_input_requested = handleAppServerRequestUserInput,
        };
    } else null;

    var goal_tool_context = AppServerGoalToolContext{
        .allocator = allocator,
        .state = state,
        .sqlite_home = configSqliteHome(cfg),
        .thread = thread,
        .turn_id = turn_id,
        .notifications = &turn_update_notifications,
    };
    const goal_tool_callback = session_mod.GoalToolCallback{
        .ctx = &goal_tool_context,
        .on_goal_tool_requested = handleAppServerGoalTool,
    };

    var external_auth_refresh_context: AppServerExternalAuthRefreshContext = undefined;
    const external_auth_refresh_callback: ?api.ExternalAuthRefreshCallback = if (state.server_request_transport) |transport| blk: {
        external_auth_refresh_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .codex_home = cfg.codex_home,
            .auth_store_mode = cfg.cli_auth_credentials_store_mode,
            .forced_chatgpt_workspace_id = cfg.forced_chatgpt_workspace_id,
            .thread_id = thread.id,
            .turn_id = turn_id,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &external_auth_refresh_context,
            .on_refresh = handleAppServerExternalAuthRefresh,
        };
    } else null;

    var mcp_elicitation_context: AppServerMcpElicitationContext = undefined;
    const mcp_elicitation_callback: ?mcp_runtime.ElicitationCallback = if (state.server_request_transport) |transport| blk: {
        mcp_elicitation_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread = thread,
            .thread_id = thread.id,
            .turn_id = turn_id,
            .auto_decline = cfg.approval_policy == .never,
            .turn_start_response_payload = response_payload,
            .turn_start_response_sent = &turn_start_response_sent,
        };
        break :blk .{
            .ctx = &mcp_elicitation_context,
            .on_elicitation_requested = handleAppServerMcpElicitation,
        };
    } else null;

    var turn_feature_overrides = try effectiveAppServerTurnFeatureOverrides(allocator, state, thread);
    defer turn_feature_overrides.deinit(allocator);

    var effective_writable_roots = try loadedThreadEffectiveWritableRoots(allocator, thread);
    defer effective_writable_roots.deinit(allocator);

    const turn_progress_sent = try maybeSendTurnStartProgress(
        allocator,
        state,
        thread,
        response_payload,
        &turn_start_response_sent,
        started_notification,
        &started_notification_moved,
        &session_start_hooks.notifications,
        &user_prompt_hooks.notifications,
    );

    const answer = session_mod.runTurnWithOptions(allocator, cfg, &credentials, &thread.transcript, prompt_for_turn, .{
        .prompt_for_approval = approval_callback != null,
        .approval_callback = approval_callback,
        .request_permissions_callback = request_permissions_callback,
        .request_user_input_callback = request_user_input_callback,
        .pending_input_callback = pending_input_callback,
        .goal_tool_callback = goal_tool_callback,
        .mcp_elicitation_callback = mcp_elicitation_callback,
        .external_auth_refresh_callback = external_auth_refresh_callback,
        .additional_writable_roots = effective_writable_roots.items,
        .read_denied_roots = thread.sandbox_read_denied_roots.items,
        .read_denied_globs = thread.sandbox_read_denied_globs.items,
        .include_cwd_write_root = thread.sandbox_include_cwd_write_root,
        .network_enabled = thread.sandbox_network_enabled,
        .output_schema = optionalJsonParam(object, "outputSchema"),
        .input_images = request_input_images,
        .developer_messages_after_user = user_prompt_hooks.contexts.items,
        .plan_mode = std.mem.eql(u8, thread.collaboration_mode, "plan"),
        .plan_update_callback = .{
            .ctx = &plan_update_context,
            .on_plan_updated = handleSessionPlanUpdated,
        },
        .proposed_plan_callback = .{
            .ctx = &proposed_plan_context,
            .on_proposed_plan = handleSessionProposedPlan,
        },
        .diff_update_callback = .{
            .ctx = &diff_update_context,
            .on_diff_updated = handleSessionDiffUpdated,
        },
        .command_execution_output_callback = .{
            .ctx = &command_execution_output_context,
            .on_command_execution_output = handleSessionCommandExecutionOutput,
        },
        .terminal_interaction_callback = .{
            .ctx = &terminal_interaction_context,
            .on_terminal_interaction = handleSessionTerminalInteraction,
        },
        .file_change_patch_update_callback = .{
            .ctx = &file_change_patch_update_context,
            .on_file_change_patch_updated = handleSessionFileChangePatchUpdated,
        },
        .raw_response_item_callback = .{
            .ctx = &raw_response_item_context,
            .on_raw_response_item = handleSessionRawResponseItem,
        },
        .reasoning_event_callback = .{
            .ctx = &reasoning_event_context,
            .on_reasoning_event = handleSessionReasoningEvent,
        },
        .server_model_callback = .{
            .ctx = &model_notification_context,
            .on_server_model = handleSessionServerModel,
        },
        .models_etag_callback = .{
            .ctx = &model_notification_context,
            .on_models_etag = handleSessionModelsEtag,
        },
        .model_verification_callback = .{
            .ctx = &model_notification_context,
            .on_model_verifications = handleSessionModelVerifications,
        },
        .mcp_tool_call_progress_callback = .{
            .ctx = &mcp_tool_call_progress_context,
            .on_mcp_tool_call_progress = handleSessionMcpToolCallProgress,
        },
        .mcp_startup_status_callback = .{
            .ctx = &mcp_startup_status_context,
            .on_startup_status = handleSessionMcpStartupStatus,
        },
        .feature_overrides = turn_feature_overrides,
        .workdir = thread.cwd,
        .background_terminal_owner = thread.id,
        .subagent_runtime = &thread.subagents,
        .input_mentions = input.mentions,
    }) catch |err| {
        if (err == error.AppServerApprovalCanceled) {
            const completed_at_ms = currentUnixMilliseconds();
            const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
            const completed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "interrupted", started_at, completed_at);
            var completed_notification_moved = false;
            errdefer if (!completed_notification_moved) allocator.free(completed_notification);

            const goal_accounting_changed = try refreshLoadedThreadAfterTurnAndAccountGoal(allocator, configSqliteHome(cfg), thread, prompt_for_turn, completed_at);
            if (thread.path) |path| {
                try session_store.saveTranscript(allocator, path, &thread.transcript);
            }

            if (!turn_progress_sent) {
                try queueTurnStartOpeningNotifications(
                    allocator,
                    state,
                    thread,
                    started_notification,
                    &started_notification_moved,
                    &session_start_hooks.notifications,
                    &user_prompt_hooks.notifications,
                );
            }
            try queueTurnUserMessageItemIfPresent(allocator, state, thread, turn_id, user_item_index, input.user_content_json, started_at_ms, completed_at_ms);
            try movePendingTurnUpdateNotifications(allocator, state, &turn_update_notifications);
            if (goal_accounting_changed) try queueThreadGoalUpdatedNotificationForTurn(allocator, state, thread, turn_id);
            try queueThreadTokenUsageNotificationForTurn(allocator, state, thread, turn_id);
            try queueTurnNotification(allocator, state, "turn/completed", completed_notification);
            completed_notification_moved = true;
            thread.status = .idle;
            try queueThreadStatusChangedNotification(allocator, state, thread.id, .idle);

            if (turn_start_response_sent) return null;
            response_payload_moved = true;
            return response_payload;
        }

        const error_message = try std.fmt.allocPrint(allocator, "turn/start failed to run turn: {s}", .{@errorName(err)});
        defer allocator.free(error_message);
        const should_emit_started = turn_progress_sent or
            turn_start_response_sent or
            session_start_hooks.notifications.items.len > 0 or
            user_prompt_hooks.notifications.items.len > 0;
        if (should_emit_started) {
            if (!turn_progress_sent) {
                try queueTurnStartOpeningNotifications(
                    allocator,
                    state,
                    thread,
                    started_notification,
                    &started_notification_moved,
                    &session_start_hooks.notifications,
                    &user_prompt_hooks.notifications,
                );
            }
            try queueTurnUserMessageItemIfPresent(allocator, state, thread, turn_id, user_item_index, input.user_content_json, started_at_ms, currentUnixMilliseconds());
            try movePendingTurnUpdateNotifications(allocator, state, &turn_update_notifications);
        }
        thread.status = .system_error;
        const failed_at = currentUnixSeconds();
        const goal_accounting_changed = try refreshLoadedThreadAfterTurnAndAccountGoal(allocator, configSqliteHome(cfg), thread, prompt_for_turn, failed_at);
        if (thread.path) |path| {
            try session_store.saveTranscript(allocator, path, &thread.transcript);
        }
        if (should_emit_started) {
            if (goal_accounting_changed) try queueThreadGoalUpdatedNotificationForTurn(allocator, state, thread, turn_id);
            try queueThreadTokenUsageNotificationForTurn(allocator, state, thread, turn_id);
        }
        try queueErrorNotification(allocator, state, thread.id, turn_id, error_message, false);
        if (turn_start_response_sent) {
            const completed_at_ms = currentUnixMilliseconds();
            const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
            const failed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "failed", started_at, completed_at);
            var failed_notification_moved = false;
            errdefer if (!failed_notification_moved) allocator.free(failed_notification);
            try queueTurnNotification(allocator, state, "turn/completed", failed_notification);
            failed_notification_moved = true;
        }
        try queueThreadStatusChangedNotification(allocator, state, thread.id, .system_error);
        if (turn_start_response_sent) return null;
        return try renderJsonRpcError(allocator, id_value, -32603, error_message);
    };
    defer allocator.free(answer);

    const completed_at_ms = currentUnixMilliseconds();
    const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
    const completed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "completed", started_at, completed_at);
    var completed_notification_moved = false;
    errdefer if (!completed_notification_moved) allocator.free(completed_notification);

    const goal_accounting_changed = try refreshLoadedThreadAfterTurnAndAccountGoal(allocator, configSqliteHome(cfg), thread, prompt_for_turn, completed_at);
    if (thread.path) |path| {
        try session_store.saveTranscript(allocator, path, &thread.transcript);
    }

    if (!turn_progress_sent) {
        try queueTurnStartOpeningNotifications(
            allocator,
            state,
            thread,
            started_notification,
            &started_notification_moved,
            &session_start_hooks.notifications,
            &user_prompt_hooks.notifications,
        );
    }
    try queueTurnUserMessageItemIfPresent(allocator, state, thread, turn_id, user_item_index, input.user_content_json, started_at_ms, currentUnixMilliseconds());
    try movePendingTurnUpdateNotifications(allocator, state, &turn_update_notifications);
    if (goal_accounting_changed) try queueThreadGoalUpdatedNotificationForTurn(allocator, state, thread, turn_id);
    try queueThreadTokenUsageNotificationForTurn(allocator, state, thread, turn_id);
    if (latestAssistantMessageIndex(&thread.transcript, user_item_index)) |assistant_item_index| {
        if (answer.len > 0) {
            try queueAgentMessageItemNotification(allocator, state, "item/started", thread.id, turn_id, assistant_item_index, answer, "startedAtMs", started_at_ms);
            try queueAgentMessageDeltaNotification(allocator, state, thread.id, turn_id, assistant_item_index, answer);
            try queueAgentMessageItemNotification(allocator, state, "item/completed", thread.id, turn_id, assistant_item_index, answer, "completedAtMs", completed_at_ms);
        }
    }
    try queueTurnNotification(allocator, state, "turn/completed", completed_notification);
    completed_notification_moved = true;
    thread.status = .idle;
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .idle);

    if (turn_start_response_sent) return null;
    response_payload_moved = true;
    return response_payload;
}

fn handleTurnSteer(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "turn/steer params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "turn/steer params must be an object");
    const object = params.object;

    const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
        error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
    };
    const expected_turn_id_value = object.get("expectedTurnId") orelse return renderJsonRpcError(allocator, id_value, -32602, "expectedTurnId must be a string");
    if (expected_turn_id_value != .string) return renderJsonRpcError(allocator, id_value, -32602, "expectedTurnId must be a string");
    if (expected_turn_id_value.string.len == 0) return renderJsonRpcError(allocator, id_value, -32600, "expectedTurnId must not be empty");
    if (!isUuidString(thread_id)) {
        return renderInvalidThreadId(allocator, id_value, thread_id);
    }
    if (findLoadedThreadIndex(state, thread_id) == null) {
        return renderThreadNotFound(allocator, id_value, thread_id);
    }

    var input = parseTurnStartInput(allocator, object) catch |err| switch (err) {
        error.InvalidTurnInput => return renderJsonRpcError(allocator, id_value, -32602, "input must be an array of supported user input items"),
        error.EmptyTurnInput => return renderJsonRpcError(allocator, id_value, -32600, "input must not be empty"),
        error.UnsupportedTurnInput => return renderJsonRpcError(allocator, id_value, -32600, "only text, image, localImage, skill, and mention turn/steer input is implemented"),
        else => return err,
    };
    defer input.deinit(allocator);
    if (input.text_char_count > max_user_input_text_chars) {
        return renderTurnInputTooLargeError(allocator, id_value, input.text_char_count);
    }

    return renderJsonRpcError(allocator, id_value, -32600, "no active turn to steer");
}

fn handleTurnInterrupt(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "turn/interrupt params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "turn/interrupt params must be an object");
    const object = params.object;

    const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
        error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
    };
    const turn_id_value = object.get("turnId") orelse return renderJsonRpcError(allocator, id_value, -32602, "turnId must be a string");
    if (turn_id_value != .string) return renderJsonRpcError(allocator, id_value, -32602, "turnId must be a string");
    if (!isUuidString(thread_id)) {
        return renderInvalidThreadId(allocator, id_value, thread_id);
    }
    if (findLoadedThreadIndex(state, thread_id) == null) {
        return renderThreadNotFound(allocator, id_value, thread_id);
    }

    if (turn_id_value.string.len == 0) {
        return renderJsonRpcResult(allocator, id_value, "{}");
    }
    return renderJsonRpcError(allocator, id_value, -32600, "no active turn to interrupt");
}

fn parseTurnStartInput(allocator: std.mem.Allocator, params: std.json.ObjectMap) !TurnStartInput {
    const input = params.get("input") orelse return error.InvalidTurnInput;
    if (input != .array) return error.InvalidTurnInput;

    var prompt = std.ArrayList(u8).empty;
    errdefer prompt.deinit(allocator);
    var user_content = std.ArrayList(u8).empty;
    errdefer user_content.deinit(allocator);
    try user_content.append(allocator, '[');
    var image_urls = std.ArrayList([]const u8).empty;
    var image_urls_moved = false;
    errdefer if (!image_urls_moved) {
        for (image_urls.items) |image_url| allocator.free(image_url);
        image_urls.deinit(allocator);
    };
    var local_image_paths = std.ArrayList([]const u8).empty;
    var local_image_paths_moved = false;
    errdefer if (!local_image_paths_moved) {
        for (local_image_paths.items) |path| allocator.free(path);
        local_image_paths.deinit(allocator);
    };
    var skills = std.ArrayList(TurnNamedPathInput).empty;
    var skills_moved = false;
    errdefer if (!skills_moved) {
        for (skills.items) |item| item.deinit(allocator);
        skills.deinit(allocator);
    };
    var mentions = std.ArrayList(TurnNamedPathInput).empty;
    var mentions_moved = false;
    errdefer if (!mentions_moved) {
        for (mentions.items) |item| item.deinit(allocator);
        mentions.deinit(allocator);
    };
    var input_items: usize = 0;
    var text_items: usize = 0;
    var text_char_count: usize = 0;
    for (input.array.items) |item| {
        if (item != .object) return error.InvalidTurnInput;
        const item_type = item.object.get("type") orelse return error.InvalidTurnInput;
        if (item_type != .string) return error.InvalidTurnInput;
        if (std.mem.eql(u8, item_type.string, "text")) {
            const text = item.object.get("text") orelse return error.InvalidTurnInput;
            if (text != .string) return error.InvalidTurnInput;
            text_char_count += std.unicode.utf8CountCodepoints(text.string) catch text.string.len;
            if (text_items > 0) try prompt.append(allocator, '\n');
            try prompt.appendSlice(allocator, text.string);
            if (input_items > 0) try user_content.append(allocator, ',');
            try appendTurnStartTextInputJson(allocator, &user_content, item.object, text.string);
            text_items += 1;
            input_items += 1;
        } else if (std.mem.eql(u8, item_type.string, "image")) {
            const url = item.object.get("url") orelse return error.InvalidTurnInput;
            if (url != .string) return error.InvalidTurnInput;
            const image_url = try allocator.dupe(u8, url.string);
            image_urls.append(allocator, image_url) catch |err| {
                allocator.free(image_url);
                return err;
            };
            if (input_items > 0) try user_content.append(allocator, ',');
            try appendTurnStartImageInputJson(allocator, &user_content, url.string);
            input_items += 1;
        } else if (std.mem.eql(u8, item_type.string, "localImage")) {
            const path = item.object.get("path") orelse return error.InvalidTurnInput;
            if (path != .string) return error.InvalidTurnInput;
            const local_image_path = try allocator.dupe(u8, path.string);
            local_image_paths.append(allocator, local_image_path) catch |err| {
                allocator.free(local_image_path);
                return err;
            };
            if (input_items > 0) try user_content.append(allocator, ',');
            try appendTurnStartLocalImageInputJson(allocator, &user_content, path.string);
            input_items += 1;
        } else if (std.mem.eql(u8, item_type.string, "skill")) {
            const name = item.object.get("name") orelse return error.InvalidTurnInput;
            const path = item.object.get("path") orelse return error.InvalidTurnInput;
            if (name != .string or path != .string) return error.InvalidTurnInput;
            const skill = try TurnNamedPathInput.init(allocator, name.string, path.string);
            skills.append(allocator, skill) catch |err| {
                skill.deinit(allocator);
                return err;
            };
            if (input_items > 0) try user_content.append(allocator, ',');
            try appendTurnStartNamedPathInputJson(allocator, &user_content, "skill", name.string, path.string);
            input_items += 1;
        } else if (std.mem.eql(u8, item_type.string, "mention")) {
            const name = item.object.get("name") orelse return error.InvalidTurnInput;
            const path = item.object.get("path") orelse return error.InvalidTurnInput;
            if (name != .string or path != .string) return error.InvalidTurnInput;
            const mention = try TurnNamedPathInput.init(allocator, name.string, path.string);
            mentions.append(allocator, mention) catch |err| {
                mention.deinit(allocator);
                return err;
            };
            if (input_items > 0) try user_content.append(allocator, ',');
            try appendTurnStartNamedPathInputJson(allocator, &user_content, "mention", name.string, path.string);
            input_items += 1;
        } else {
            return error.UnsupportedTurnInput;
        }
    }
    if (input_items == 0) return error.EmptyTurnInput;
    try user_content.append(allocator, ']');
    const prompt_owned = try prompt.toOwnedSlice(allocator);
    errdefer allocator.free(prompt_owned);
    const user_content_owned = try user_content.toOwnedSlice(allocator);
    errdefer allocator.free(user_content_owned);
    const image_urls_owned = try image_urls.toOwnedSlice(allocator);
    image_urls_moved = true;
    errdefer {
        for (image_urls_owned) |image_url| allocator.free(image_url);
        allocator.free(image_urls_owned);
    }
    const local_image_paths_owned = try local_image_paths.toOwnedSlice(allocator);
    local_image_paths_moved = true;
    errdefer {
        for (local_image_paths_owned) |path| allocator.free(path);
        allocator.free(local_image_paths_owned);
    }
    const skills_owned = try skills.toOwnedSlice(allocator);
    skills_moved = true;
    errdefer {
        for (skills_owned) |item| item.deinit(allocator);
        allocator.free(skills_owned);
    }
    const mentions_owned = try mentions.toOwnedSlice(allocator);
    mentions_moved = true;
    errdefer {
        for (mentions_owned) |item| item.deinit(allocator);
        allocator.free(mentions_owned);
    }
    return .{
        .prompt = prompt_owned,
        .user_content_json = user_content_owned,
        .image_urls = image_urls_owned,
        .local_image_paths = local_image_paths_owned,
        .skills = skills_owned,
        .mentions = mentions_owned,
        .text_char_count = text_char_count,
    };
}

fn renderTurnInputTooLargeError(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    actual_chars: usize,
) ![]const u8 {
    const message = try std.fmt.allocPrint(
        allocator,
        "Input exceeds the maximum length of {d} characters.",
        .{max_user_input_text_chars},
    );
    defer allocator.free(message);
    const data = try std.fmt.allocPrint(
        allocator,
        "{{\"input_error_code\":\"input_too_large\",\"max_chars\":{d},\"actual_chars\":{d}}}",
        .{ max_user_input_text_chars, actual_chars },
    );
    defer allocator.free(data);
    return renderJsonRpcErrorWithData(allocator, id_value, -32602, message, data);
}

fn appendTurnStartTextInputJson(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    item: std.json.ObjectMap,
    text: []const u8,
) !void {
    try out.appendSlice(allocator, "{\"type\":\"text\",\"text\":");
    try appendJsonString(allocator, out, text);
    try out.appendSlice(allocator, ",\"text_elements\":");
    if (item.get("text_elements")) |text_elements| {
        if (text_elements != .array) return error.InvalidTurnInput;
        const text_elements_json = try std.json.Stringify.valueAlloc(allocator, text_elements, .{});
        defer allocator.free(text_elements_json);
        try out.appendSlice(allocator, text_elements_json);
    } else {
        try out.appendSlice(allocator, "[]");
    }
    try out.append(allocator, '}');
}

fn appendTurnStartImageInputJson(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    url: []const u8,
) !void {
    try out.appendSlice(allocator, "{\"type\":\"image\",\"url\":");
    try appendJsonString(allocator, out, url);
    try out.append(allocator, '}');
}

fn appendTurnStartLocalImageInputJson(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    path: []const u8,
) !void {
    try out.appendSlice(allocator, "{\"type\":\"localImage\",\"path\":");
    try appendJsonString(allocator, out, path);
    try out.append(allocator, '}');
}

fn appendTurnStartNamedPathInputJson(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    item_type: []const u8,
    name: []const u8,
    path: []const u8,
) !void {
    try out.appendSlice(allocator, "{\"type\":");
    try appendJsonString(allocator, out, item_type);
    try out.appendSlice(allocator, ",\"name\":");
    try appendJsonString(allocator, out, name);
    try out.appendSlice(allocator, ",\"path\":");
    try appendJsonString(allocator, out, path);
    try out.append(allocator, '}');
}

fn combineTurnInputImages(
    allocator: std.mem.Allocator,
    image_urls: []const []const u8,
    local_image_urls: []const []const u8,
) ![]const []const u8 {
    const total_len = image_urls.len + local_image_urls.len;
    if (total_len == 0) return &.{};

    const combined = try allocator.alloc([]const u8, total_len);
    for (image_urls, 0..) |image_url, index| combined[index] = image_url;
    for (local_image_urls, 0..) |image_url, index| combined[image_urls.len + index] = image_url;
    return combined;
}

fn loadTurnLocalImages(allocator: std.mem.Allocator, base_cwd: ?[]const u8, paths: []const []const u8) !TurnLocalImages {
    if (paths.len == 0) return .{};

    var data_urls = std.ArrayList([]const u8).empty;
    var data_urls_moved = false;
    errdefer if (!data_urls_moved) {
        for (data_urls.items) |data_url| allocator.free(data_url);
        data_urls.deinit(allocator);
    };

    var missing_placeholders = std.ArrayList([]const u8).empty;
    var missing_placeholders_moved = false;
    errdefer if (!missing_placeholders_moved) {
        for (missing_placeholders.items) |placeholder| allocator.free(placeholder);
        missing_placeholders.deinit(allocator);
    };

    for (paths) |path| {
        const data_url = image_inputs.loadOneFromBase(allocator, base_cwd, path) catch |err| {
            const placeholder = try image_inputs.renderLoadErrorPlaceholder(allocator, path, err);
            missing_placeholders.append(allocator, placeholder) catch |append_err| {
                allocator.free(placeholder);
                return append_err;
            };
            continue;
        };
        data_urls.append(allocator, data_url) catch |err| {
            allocator.free(data_url);
            return err;
        };
    }

    const data_urls_owned = try data_urls.toOwnedSlice(allocator);
    data_urls_moved = true;
    errdefer {
        for (data_urls_owned) |data_url| allocator.free(data_url);
        if (data_urls_owned.len > 0) allocator.free(data_urls_owned);
    }
    const missing_placeholders_owned = try missing_placeholders.toOwnedSlice(allocator);
    missing_placeholders_moved = true;
    return .{
        .data_urls = data_urls_owned,
        .missing_placeholders = missing_placeholders_owned,
    };
}

const TurnSkillInjections = struct {
    blocks: []const []const u8 = &.{},

    fn deinit(self: *TurnSkillInjections, allocator: std.mem.Allocator) void {
        for (self.blocks) |block| allocator.free(block);
        if (self.blocks.len > 0) allocator.free(self.blocks);
    }
};

const TurnMentionMarkers = struct {
    markers: []const []const u8 = &.{},

    fn deinit(self: *TurnMentionMarkers, allocator: std.mem.Allocator) void {
        for (self.markers) |marker| allocator.free(marker);
        if (self.markers.len > 0) allocator.free(self.markers);
    }
};

fn loadTurnSkillInjections(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    base_cwd: ?[]const u8,
    skills: []const TurnNamedPathInput,
) !TurnSkillInjections {
    if (skills.len == 0) return .{};

    var blocks = std.ArrayList([]const u8).empty;
    var blocks_moved = false;
    errdefer if (!blocks_moved) {
        for (blocks.items) |block| allocator.free(block);
        blocks.deinit(allocator);
    };

    const registered_paths = cachedSkillPathsForCwd(state, base_cwd);
    for (skills) |skill| {
        const block = try input_context.loadRegisteredSkillBlockFromBaseWithOptions(allocator, base_cwd, skill.name, skill.path, .{
            .registered_paths = registered_paths,
        });
        blocks.append(allocator, block) catch |err| {
            allocator.free(block);
            return err;
        };
    }

    const blocks_owned = try blocks.toOwnedSlice(allocator);
    blocks_moved = true;
    return .{ .blocks = blocks_owned };
}

fn renderTurnMentionMarkers(allocator: std.mem.Allocator, mentions: []const TurnNamedPathInput) !TurnMentionMarkers {
    if (mentions.len == 0) return .{};

    var markers = std.ArrayList([]const u8).empty;
    var markers_moved = false;
    errdefer if (!markers_moved) {
        for (markers.items) |marker| allocator.free(marker);
        markers.deinit(allocator);
    };

    for (mentions) |mention| {
        const marker = try input_context.renderNamedPathPreview(allocator, "mention", mention.name, mention.path);
        markers.append(allocator, marker) catch |err| {
            allocator.free(marker);
            return err;
        };
    }

    const markers_owned = try markers.toOwnedSlice(allocator);
    markers_moved = true;
    return .{ .markers = markers_owned };
}

fn cachedSkillPathsForCwd(state: *const AppServerState, base_cwd: ?[]const u8) []const []const u8 {
    const cwd = base_cwd orelse return &.{};
    const cached = findSkillsListCacheEntry(state, cwd) orelse return &.{};
    return cached.skill_paths;
}

test "skills list cache preserves enabled paths for turn skill injection" {
    const allocator = std.testing.allocator;
    var state = AppServerState{};
    defer state.deinit(allocator);

    const cwd = "/tmp/codex-zig-extra-root";
    const extra_path = "/tmp/codex-zig-extra-root/shared/demo/SKILL.md";
    const disabled_path = "/tmp/codex-zig-extra-root/shared/disabled/SKILL.md";
    var skills = [_]skills_list.Skill{
        .{
            .name = "demo",
            .description = "",
            .short_description = null,
            .interface = null,
            .dependencies = null,
            .path = extra_path,
            .scope = "user",
            .enabled = true,
        },
        .{
            .name = "disabled",
            .description = "",
            .short_description = null,
            .interface = null,
            .dependencies = null,
            .path = disabled_path,
            .scope = "user",
            .enabled = false,
        },
    };
    var errors = [_]skills_list.SkillError{};
    var entries = [_]skills_list.Entry{.{
        .cwd = cwd,
        .skills = &skills,
        .errors = &errors,
    }};
    const result = skills_list.Result{ .entries = &entries };

    try updateSkillsListCache(allocator, &state, result);

    const paths = cachedSkillPathsForCwd(&state, cwd);
    try std.testing.expectEqual(@as(usize, 1), paths.len);
    try std.testing.expectEqualStrings(extra_path, paths[0]);
}

fn turnPromptWithContextBlocks(
    allocator: std.mem.Allocator,
    prompt: []const u8,
    placeholders: []const []const u8,
    skill_blocks: []const []const u8,
    mention_markers: []const []const u8,
) ![]const u8 {
    if (placeholders.len == 0 and skill_blocks.len == 0 and mention_markers.len == 0) return allocator.dupe(u8, prompt);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    if (prompt.len > 0) try out.appendSlice(allocator, prompt);
    for (placeholders) |placeholder| {
        if (out.items.len > 0) try out.append(allocator, '\n');
        try out.appendSlice(allocator, placeholder);
    }
    for (skill_blocks) |skill_block| {
        if (out.items.len > 0) try out.append(allocator, '\n');
        try out.appendSlice(allocator, skill_block);
    }
    for (mention_markers) |mention_marker| {
        if (out.items.len > 0) try out.append(allocator, '\n');
        try out.appendSlice(allocator, mention_marker);
    }
    return out.toOwnedSlice(allocator);
}

fn materializeHookTranscriptForThread(allocator: std.mem.Allocator, thread: *const LoadedThread) !void {
    if (thread.path) |path| try session_store.saveTranscript(allocator, path, &thread.transcript);
}

fn createLoadedThreadForDetachedReview(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    source: *const LoadedThread,
    session_source: []const u8,
) !LoadedThread {
    var empty_params = try std.json.ObjectMap.init(allocator, &.{}, &.{});
    defer empty_params.deinit(allocator);

    var thread = try createLoadedThreadFromForkParamsWithSource(allocator, cfg, empty_params, source, session_source);
    errdefer thread.deinit(allocator);
    try replaceOwnedString(allocator, &thread.model, cfg.model);
    thread.runtime_overrides.model = true;
    try replaceOptionalOwnedString(allocator, &thread.pending_session_start_source, "resume");
    try thread.transcript.setModelProvider(allocator, thread.model_provider);
    return thread;
}

fn persistHookContextsForNextTurn(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    contexts: []const []const u8,
) !void {
    if (contexts.len == 0) return;
    for (contexts) |context| {
        try thread.transcript.appendDeveloperMessage(allocator, context);
    }

    const turns_json = try renderTranscriptTurnsJson(allocator, &thread.transcript, true);
    errdefer allocator.free(turns_json);
    allocator.free(thread.turns_json);
    thread.turns_json = turns_json;
    syncLoadedThreadNextTurnIndex(thread);
    thread.updated_at = currentUnixSeconds();
}

fn hookPermissionMode(approval_policy: config.ApprovalPolicy) []const u8 {
    return switch (approval_policy) {
        .never => "bypassPermissions",
        .untrusted, .on_failure, .on_request => "default",
    };
}

const HookRuntimeNotification = struct {
    method: []const u8,
    payload: []const u8,

    fn deinit(self: HookRuntimeNotification, allocator: std.mem.Allocator) void {
        allocator.free(self.payload);
    }
};

const HookRuntimeResult = struct {
    notifications: std.ArrayList(HookRuntimeNotification) = .empty,
    contexts: std.ArrayList([]const u8) = .empty,
    should_stop: bool = false,

    fn deinit(self: *HookRuntimeResult, allocator: std.mem.Allocator) void {
        for (self.notifications.items) |notification| notification.deinit(allocator);
        self.notifications.deinit(allocator);
        for (self.contexts.items) |context| allocator.free(context);
        self.contexts.deinit(allocator);
        self.* = .{};
    }
};

const HookOutputEntry = struct {
    kind: []const u8,
    text: []const u8,

    fn deinit(self: HookOutputEntry, allocator: std.mem.Allocator) void {
        allocator.free(self.text);
    }
};

const HookCommandRun = struct {
    hook: hooks_list.Hook,
    hook_run_id: []const u8,
    started_at_ms: i64,
    started_at: i64,
    worker: HookCommandWorker,
    thread: ?std.Thread = null,

    fn deinit(self: *HookCommandRun, allocator: std.mem.Allocator) void {
        allocator.free(self.hook_run_id);
        if (self.worker.result) |*result| result.deinit(std.heap.page_allocator);
    }
};

const HookCommandWorker = struct {
    codex_home: []const u8,
    hook: hooks_list.Hook,
    cwd: []const u8,
    input_json: []const u8,
    result: ?CommandExecRunResult = null,
    error_name: ?[]const u8 = null,
    completed_at_ms: ?i64 = null,
};

fn runSessionStartHooks(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    thread_id: []const u8,
    turn_id: []const u8,
    transcript_path: ?[]const u8,
    cwd: []const u8,
    model: []const u8,
    permission_mode: []const u8,
    source: []const u8,
    bypass_hook_trust: bool,
) !HookRuntimeResult {
    var runtime = HookRuntimeResult{};
    errdefer runtime.deinit(allocator);

    var listed = try hooks_list.list(allocator, codex_home, &.{cwd});
    defer listed.deinit(allocator);
    if (listed.entries.len == 0) return runtime;

    const input_json = try renderSessionStartHookInput(allocator, thread_id, transcript_path, cwd, model, permission_mode, source);
    defer allocator.free(input_json);

    var runs = std.ArrayList(HookCommandRun).empty;
    defer deinitHookCommandRuns(allocator, &runs);
    defer joinPendingHookCommandRuns(&runs);

    for (listed.entries[0].hooks) |hook| {
        if (hook.event_name != .session_start or !hook.shouldRunWithBypass(bypass_hook_trust) or !(try hookMatcherMatchesInput(allocator, hook.matcher, source))) continue;
        const hook_run_id = try renderHookRunId(allocator, hook);
        var hook_run_id_moved = false;
        errdefer if (!hook_run_id_moved) allocator.free(hook_run_id);

        const started_at_ms = currentUnixMilliseconds();
        const started_at = @divTrunc(started_at_ms, std.time.ms_per_s);
        const started = try renderHookNotification(allocator, "hook/started", thread_id, turn_id, hook, hook_run_id, "running", started_at, null, null, &.{});
        errdefer allocator.free(started);
        try runtime.notifications.append(allocator, .{ .method = "hook/started", .payload = started });

        try runs.append(allocator, .{
            .hook = hook,
            .hook_run_id = hook_run_id,
            .started_at_ms = started_at_ms,
            .started_at = started_at,
            .worker = .{
                .codex_home = codex_home,
                .hook = hook,
                .cwd = cwd,
                .input_json = input_json,
            },
        });
        hook_run_id_moved = true;
    }

    for (runs.items) |*hook_run| {
        hook_run.thread = try std.Thread.spawn(.{}, runHookCommandWorker, .{&hook_run.worker});
    }

    joinPendingHookCommandRuns(&runs);

    for (runs.items) |*hook_run| {
        var entries = std.ArrayList(HookOutputEntry).empty;
        defer deinitHookOutputEntries(allocator, &entries);

        const status = if (hook_run.worker.error_name) |error_name| blk: {
            const message = try std.fmt.allocPrint(allocator, "hook failed to run: {s}", .{error_name});
            defer allocator.free(message);
            try appendHookOutputEntry(allocator, &entries, "error", message);
            break :blk "failed";
        } else blk: {
            const result = hook_run.worker.result orelse return error.HookCommandMissingResult;
            break :blk try collectSessionStartHookEntries(allocator, &result, &entries, &runtime.contexts);
        };

        if (std.mem.eql(u8, status, "stopped")) runtime.should_stop = true;
        const completed_at_ms = hook_run.worker.completed_at_ms orelse currentUnixMilliseconds();
        const completed = try renderHookNotification(
            allocator,
            "hook/completed",
            thread_id,
            turn_id,
            hook_run.hook,
            hook_run.hook_run_id,
            status,
            hook_run.started_at,
            @divTrunc(completed_at_ms, std.time.ms_per_s),
            @max(completed_at_ms - hook_run.started_at_ms, 0),
            entries.items,
        );
        errdefer allocator.free(completed);
        try runtime.notifications.append(allocator, .{ .method = "hook/completed", .payload = completed });
    }

    return runtime;
}

fn runUserPromptSubmitHooks(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    thread_id: []const u8,
    turn_id: []const u8,
    transcript_path: ?[]const u8,
    cwd: []const u8,
    model: []const u8,
    permission_mode: []const u8,
    prompt: []const u8,
    bypass_hook_trust: bool,
) !HookRuntimeResult {
    var runtime = HookRuntimeResult{};
    errdefer runtime.deinit(allocator);

    var listed = try hooks_list.list(allocator, codex_home, &.{cwd});
    defer listed.deinit(allocator);
    if (listed.entries.len == 0) return runtime;

    const input_json = try renderUserPromptSubmitHookInput(allocator, thread_id, turn_id, transcript_path, cwd, model, permission_mode, prompt);
    defer allocator.free(input_json);

    var runs = std.ArrayList(HookCommandRun).empty;
    defer deinitHookCommandRuns(allocator, &runs);
    defer joinPendingHookCommandRuns(&runs);

    for (listed.entries[0].hooks) |hook| {
        if (hook.event_name != .user_prompt_submit or !hook.shouldRunWithBypass(bypass_hook_trust)) continue;
        const hook_run_id = try renderHookRunId(allocator, hook);
        var hook_run_id_moved = false;
        errdefer if (!hook_run_id_moved) allocator.free(hook_run_id);

        const started_at_ms = currentUnixMilliseconds();
        const started_at = @divTrunc(started_at_ms, std.time.ms_per_s);
        const started = try renderHookNotification(allocator, "hook/started", thread_id, turn_id, hook, hook_run_id, "running", started_at, null, null, &.{});
        errdefer allocator.free(started);
        try runtime.notifications.append(allocator, .{ .method = "hook/started", .payload = started });

        try runs.append(allocator, .{
            .hook = hook,
            .hook_run_id = hook_run_id,
            .started_at_ms = started_at_ms,
            .started_at = started_at,
            .worker = .{
                .codex_home = codex_home,
                .hook = hook,
                .cwd = cwd,
                .input_json = input_json,
            },
        });
        hook_run_id_moved = true;
    }

    for (runs.items) |*hook_run| {
        hook_run.thread = try std.Thread.spawn(.{}, runHookCommandWorker, .{&hook_run.worker});
    }

    joinPendingHookCommandRuns(&runs);

    for (runs.items) |*hook_run| {
        var entries = std.ArrayList(HookOutputEntry).empty;
        defer deinitHookOutputEntries(allocator, &entries);

        const status = if (hook_run.worker.error_name) |error_name| blk: {
            const message = try std.fmt.allocPrint(allocator, "hook failed to run: {s}", .{error_name});
            defer allocator.free(message);
            try appendHookOutputEntry(allocator, &entries, "error", message);
            break :blk "failed";
        } else blk: {
            const result = hook_run.worker.result orelse return error.HookCommandMissingResult;
            break :blk try collectUserPromptSubmitHookEntries(allocator, &result, &entries, &runtime.contexts);
        };

        if (std.mem.eql(u8, status, "blocked") or std.mem.eql(u8, status, "stopped")) runtime.should_stop = true;
        const completed_at_ms = hook_run.worker.completed_at_ms orelse currentUnixMilliseconds();
        const completed = try renderHookNotification(
            allocator,
            "hook/completed",
            thread_id,
            turn_id,
            hook_run.hook,
            hook_run.hook_run_id,
            status,
            hook_run.started_at,
            @divTrunc(completed_at_ms, std.time.ms_per_s),
            @max(completed_at_ms - hook_run.started_at_ms, 0),
            entries.items,
        );
        errdefer allocator.free(completed);
        try runtime.notifications.append(allocator, .{ .method = "hook/completed", .payload = completed });
    }

    return runtime;
}

fn deinitHookCommandRuns(allocator: std.mem.Allocator, runs: *std.ArrayList(HookCommandRun)) void {
    for (runs.items) |*hook_run| hook_run.deinit(allocator);
    runs.deinit(allocator);
}

fn joinPendingHookCommandRuns(runs: *std.ArrayList(HookCommandRun)) void {
    for (runs.items) |*hook_run| {
        if (hook_run.thread) |thread| {
            thread.join();
            hook_run.thread = null;
        }
    }
}

fn runHookCommandWorker(worker: *HookCommandWorker) void {
    worker.result = runTrustedHookCommand(
        std.heap.page_allocator,
        worker.codex_home,
        worker.hook,
        worker.cwd,
        worker.input_json,
    ) catch |err| {
        worker.completed_at_ms = currentUnixMilliseconds();
        worker.error_name = @errorName(err);
        return;
    };
    worker.completed_at_ms = currentUnixMilliseconds();
}

fn runTrustedHookCommand(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    hook: hooks_list.Hook,
    cwd: []const u8,
    input_json: []const u8,
) !CommandExecRunResult {
    var io_instance: std.Io.Threaded = .init(allocator, .{});
    defer io_instance.deinit();
    const shell = currentHookShell();
    const command = try hookCommand(allocator, codex_home, hook);
    defer allocator.free(command);
    const argv = [_][]const u8{ shell, "-lc", command };
    const timeout_sec = @min(hook.timeout_sec, @as(u64, @intCast(std.math.maxInt(i64) / 1000)));
    const timeout_ms: i64 = @intCast(timeout_sec * 1000);
    var child_env = try hookEnvironment(allocator, codex_home, hook);
    defer if (child_env) |*hook_env| hook_env.deinit();
    const env_map = if (child_env) |*hook_env| hook_env else null;
    return runCommandExecProcess(
        allocator,
        &io_instance,
        &argv,
        .{ .path = cwd },
        env_map,
        input_json,
        timeout_ms,
        COMMAND_EXEC_DEFAULT_OUTPUT_BYTES_CAP,
    );
}

fn hookCommand(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    hook: hooks_list.Hook,
) ![]const u8 {
    var command = try allocator.dupe(u8, hook.command);
    errdefer allocator.free(command);
    if (hook.source != .plugin) return command;

    const plugin_id = hook.plugin_id orelse return command;
    const plugin_root = (try plugin_config.localPluginRoot(allocator, codex_home, plugin_id)) orelse return command;
    defer allocator.free(plugin_root);
    const plugin_data_root = (try plugin_config.localPluginDataRoot(allocator, codex_home, plugin_id)) orelse return command;
    defer allocator.free(plugin_data_root);

    try replaceHookCommandPlaceholder(allocator, &command, "${PLUGIN_ROOT}", plugin_root);
    try replaceHookCommandPlaceholder(allocator, &command, "${CLAUDE_PLUGIN_ROOT}", plugin_root);
    try replaceHookCommandPlaceholder(allocator, &command, "${PLUGIN_DATA}", plugin_data_root);
    try replaceHookCommandPlaceholder(allocator, &command, "${CLAUDE_PLUGIN_DATA}", plugin_data_root);
    return command;
}

fn replaceHookCommandPlaceholder(
    allocator: std.mem.Allocator,
    command: *[]u8,
    placeholder: []const u8,
    replacement: []const u8,
) !void {
    if (std.mem.indexOf(u8, command.*, placeholder) == null) return;

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    var start: usize = 0;
    while (std.mem.indexOfPos(u8, command.*, start, placeholder)) |index| {
        try out.appendSlice(allocator, command.*[start..index]);
        try out.appendSlice(allocator, replacement);
        start = index + placeholder.len;
    }
    try out.appendSlice(allocator, command.*[start..]);

    const next = try out.toOwnedSlice(allocator);
    allocator.free(command.*);
    command.* = next;
}

fn hookEnvironment(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    hook: hooks_list.Hook,
) !?std.process.Environ.Map {
    if (hook.source != .plugin) return null;
    const plugin_id = hook.plugin_id orelse return null;
    const plugin_root = (try plugin_config.localPluginRoot(allocator, codex_home, plugin_id)) orelse return null;
    defer allocator.free(plugin_root);
    const plugin_data_root = (try plugin_config.localPluginDataRoot(allocator, codex_home, plugin_id)) orelse return null;
    defer allocator.free(plugin_data_root);

    var hook_env = try commandExecCurrentEnvironment(allocator);
    errdefer hook_env.deinit();
    try hook_env.put("PLUGIN_ROOT", plugin_root);
    try hook_env.put("CLAUDE_PLUGIN_ROOT", plugin_root);
    try hook_env.put("PLUGIN_DATA", plugin_data_root);
    try hook_env.put("CLAUDE_PLUGIN_DATA", plugin_data_root);
    return hook_env;
}

fn renderUserPromptSubmitHookInput(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    turn_id: []const u8,
    transcript_path: ?[]const u8,
    cwd: []const u8,
    model: []const u8,
    permission_mode: []const u8,
    prompt: []const u8,
) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"session_id\":");
    try appendJsonString(allocator, &out, thread_id);
    try out.appendSlice(allocator, ",\"turn_id\":");
    try appendJsonString(allocator, &out, turn_id);
    try out.appendSlice(allocator, ",\"transcript_path\":");
    try appendOptionalJsonString(allocator, &out, transcript_path);
    try out.appendSlice(allocator, ",\"cwd\":");
    try appendJsonString(allocator, &out, cwd);
    try out.appendSlice(allocator, ",\"hook_event_name\":\"UserPromptSubmit\",\"model\":");
    try appendJsonString(allocator, &out, model);
    try out.appendSlice(allocator, ",\"permission_mode\":");
    try appendJsonString(allocator, &out, permission_mode);
    try out.appendSlice(allocator, ",\"prompt\":");
    try appendJsonString(allocator, &out, prompt);
    try out.append(allocator, '}');
    return out.toOwnedSlice(allocator);
}

fn renderSessionStartHookInput(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    transcript_path: ?[]const u8,
    cwd: []const u8,
    model: []const u8,
    permission_mode: []const u8,
    source: []const u8,
) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"session_id\":");
    try appendJsonString(allocator, &out, thread_id);
    try out.appendSlice(allocator, ",\"transcript_path\":");
    try appendOptionalJsonString(allocator, &out, transcript_path);
    try out.appendSlice(allocator, ",\"cwd\":");
    try appendJsonString(allocator, &out, cwd);
    try out.appendSlice(allocator, ",\"hook_event_name\":\"SessionStart\",\"model\":");
    try appendJsonString(allocator, &out, model);
    try out.appendSlice(allocator, ",\"permission_mode\":");
    try appendJsonString(allocator, &out, permission_mode);
    try out.appendSlice(allocator, ",\"source\":");
    try appendJsonString(allocator, &out, source);
    try out.append(allocator, '}');
    return out.toOwnedSlice(allocator);
}

fn hookMatcherMatchesInput(allocator: std.mem.Allocator, matcher: ?[]const u8, input: []const u8) !bool {
    const value = matcher orelse return true;
    if (value.len == 0 or std.mem.eql(u8, value, "*")) return true;
    if (!hookMatcherIsExact(value)) return hookRegexMatcherMatchesInput(allocator, value, input);

    var parts = std.mem.splitScalar(u8, value, '|');
    while (parts.next()) |part| {
        if (std.mem.eql(u8, part, input)) return true;
    }
    return false;
}

fn hookMatcherIsExact(matcher: []const u8) bool {
    for (matcher) |ch| {
        if ((ch >= 'a' and ch <= 'z') or
            (ch >= 'A' and ch <= 'Z') or
            (ch >= '0' and ch <= '9') or
            ch == '_' or
            ch == '|')
        {
            continue;
        }
        return false;
    }
    return true;
}

fn hookRegexMatcherMatchesInput(allocator: std.mem.Allocator, matcher: []const u8, input: []const u8) !bool {
    const translated = try translateRustRegexForPosix(allocator, matcher);
    defer translated.deinit(allocator);
    return hookPosixRegexMatcherMatchesInput(allocator, translated.pattern, input, translated.flags);
}

const TranslatedHookRegex = struct {
    pattern: []const u8,
    flags: c_int,

    fn deinit(self: TranslatedHookRegex, allocator: std.mem.Allocator) void {
        allocator.free(self.pattern);
    }
};

fn translateRustRegexForPosix(allocator: std.mem.Allocator, matcher: []const u8) !TranslatedHookRegex {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    var flags: c_int = regex_c.REG_EXTENDED;
    var index: usize = 0;
    while (index < matcher.len) {
        if (try appendTranslatedRustRegexGroup(allocator, &out, matcher, &index, &flags)) {
            continue;
        }

        const ch = matcher[index];
        if (ch == '\\' and index + 1 < matcher.len) {
            const next = matcher[index + 1];
            switch (next) {
                'd' => {
                    try out.appendSlice(allocator, "[[:digit:]]");
                    index += 2;
                    continue;
                },
                'D' => {
                    try out.appendSlice(allocator, "[^[:digit:]]");
                    index += 2;
                    continue;
                },
                's' => {
                    try out.appendSlice(allocator, "[[:space:]]");
                    index += 2;
                    continue;
                },
                'S' => {
                    try out.appendSlice(allocator, "[^[:space:]]");
                    index += 2;
                    continue;
                },
                'w' => {
                    try out.appendSlice(allocator, "[[:alnum:]_]");
                    index += 2;
                    continue;
                },
                'W' => {
                    try out.appendSlice(allocator, "[^[:alnum:]_]");
                    index += 2;
                    continue;
                },
                else => {},
            }
            try out.append(allocator, ch);
            try out.append(allocator, next);
            index += 2;
            continue;
        }

        if ((ch == '*' or ch == '+' or ch == '?') and index + 1 < matcher.len and matcher[index + 1] == '?') {
            try out.append(allocator, ch);
            index += 2;
            continue;
        }

        try out.append(allocator, ch);
        index += 1;
    }
    return .{ .pattern = try out.toOwnedSlice(allocator), .flags = flags };
}

fn appendTranslatedRustRegexGroup(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    matcher: []const u8,
    index: *usize,
    flags: *c_int,
) !bool {
    if (index.* + 2 >= matcher.len) return false;
    if (matcher[index.*] != '(' or matcher[index.* + 1] != '?') return false;

    const kind = matcher[index.* + 2];
    if (kind == ':') {
        try out.append(allocator, '(');
        index.* += 3;
        return true;
    }
    if (kind == '<') {
        if (std.mem.indexOfScalarPos(u8, matcher, index.* + 3, '>')) |end| {
            try out.append(allocator, '(');
            index.* = end + 1;
            return true;
        }
        return false;
    }
    if (kind == 'P' and index.* + 3 < matcher.len and matcher[index.* + 3] == '<') {
        if (std.mem.indexOfScalarPos(u8, matcher, index.* + 4, '>')) |end| {
            try out.append(allocator, '(');
            index.* = end + 1;
            return true;
        }
        return false;
    }

    var cursor = index.* + 2;
    var saw_flag = false;
    var negating = false;
    while (cursor < matcher.len) : (cursor += 1) {
        switch (matcher[cursor]) {
            'i' => {
                saw_flag = true;
                if (!negating) flags.* |= regex_c.REG_ICASE;
            },
            'm', 's', 'U', 'x' => saw_flag = true,
            '-' => {
                saw_flag = true;
                negating = true;
            },
            ':' => {
                if (!saw_flag) return false;
                try out.append(allocator, '(');
                index.* = cursor + 1;
                return true;
            },
            ')' => {
                if (!saw_flag) return false;
                index.* = cursor + 1;
                return true;
            },
            else => return false,
        }
    }
    return false;
}

fn hookPosixRegexMatcherMatchesInput(allocator: std.mem.Allocator, matcher: []const u8, input: []const u8, flags: c_int) !bool {
    const matcher_z = try allocator.dupeZ(u8, matcher);
    defer allocator.free(matcher_z);
    const input_z = try allocator.dupeZ(u8, input);
    defer allocator.free(input_z);

    var regex: regex_c.regex_t = undefined;
    if (regex_c.regcomp(&regex, matcher_z.ptr, flags) != 0) return false;
    defer regex_c.regfree(&regex);
    return regex_c.regexec(&regex, input_z.ptr, 0, null, 0) == 0;
}

test "app-server hook matcher supports exact alternatives and regexes" {
    const allocator = std.testing.allocator;
    try std.testing.expect(try hookMatcherMatchesInput(allocator, null, "startup"));
    try std.testing.expect(try hookMatcherMatchesInput(allocator, "", "startup"));
    try std.testing.expect(try hookMatcherMatchesInput(allocator, "*", "clear"));
    try std.testing.expect(try hookMatcherMatchesInput(allocator, "startup|resume", "resume"));
    try std.testing.expect(!try hookMatcherMatchesInput(allocator, "startup|resume", "clear"));
    try std.testing.expect(try hookMatcherMatchesInput(allocator, "^start.*$", "startup"));
    try std.testing.expect(!try hookMatcherMatchesInput(allocator, "^start.*$", "resume"));
    try std.testing.expect(try hookMatcherMatchesInput(allocator, "(?i)^(?:STARTUP|RESUME)$", "startup"));
    try std.testing.expect(try hookMatcherMatchesInput(allocator, "^(?:startup|resume)$", "resume"));
    try std.testing.expect(try hookMatcherMatchesInput(allocator, "^sta\\w+?$", "startup"));
    try std.testing.expect(!try hookMatcherMatchesInput(allocator, "[", "startup"));
}

fn renderHookRunId(
    allocator: std.mem.Allocator,
    hook: hooks_list.Hook,
) ![]const u8 {
    return std.fmt.allocPrint(allocator, "{s}:{d}:{s}", .{ hook.event_name.runIdLabel(), hook.display_order, hook.source_path });
}

fn collectSessionStartHookEntries(
    allocator: std.mem.Allocator,
    result: *const CommandExecRunResult,
    entries: *std.ArrayList(HookOutputEntry),
    contexts: *std.ArrayList([]const u8),
) ![]const u8 {
    if (result.exit_code == 0) {
        const trimmed_stdout = std.mem.trim(u8, result.stdout, " \t\r\n");
        if (trimmed_stdout.len == 0) return "completed";
        if (try collectJsonSessionStartHookOutput(allocator, trimmed_stdout, entries, contexts)) |status| return status;
        if (looksLikeJson(trimmed_stdout)) {
            try appendHookOutputEntry(allocator, entries, "error", "hook returned invalid session start JSON output");
            return "failed";
        }
        try appendHookContextEntry(allocator, entries, contexts, trimmed_stdout);
        return "completed";
    }
    const message = try std.fmt.allocPrint(allocator, "hook exited with code {d}", .{result.exit_code});
    defer allocator.free(message);
    try appendHookOutputEntry(allocator, entries, "error", message);
    return "failed";
}

fn collectJsonSessionStartHookOutput(
    allocator: std.mem.Allocator,
    stdout: []const u8,
    entries: *std.ArrayList(HookOutputEntry),
    contexts: *std.ArrayList([]const u8),
) !?[]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, stdout, .{}) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return null,
    };
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    if (!isValidSessionStartOutputObject(object)) return try appendInvalidSessionStartJsonOutput(allocator, entries);

    if (optionalHookStringField(object, "systemMessage")) |message| {
        try appendHookOutputEntry(allocator, entries, "warning", message);
    }

    if (object.get("hookSpecificOutput")) |specific| {
        if (specific == .null) {
            // Explicit null matches the Rust optional hookSpecificOutput field.
        } else if (specific == .object) {
            const event_name = optionalHookStringField(specific.object, "hookEventName") orelse return try appendInvalidSessionStartJsonOutput(allocator, entries);
            if (!std.mem.eql(u8, event_name, "SessionStart")) return try appendInvalidSessionStartJsonOutput(allocator, entries);
            if (optionalHookStringField(specific.object, "additionalContext")) |context| {
                try appendHookContextEntry(allocator, entries, contexts, context);
            }
        } else {
            return try appendInvalidSessionStartJsonOutput(allocator, entries);
        }
    }

    if (optionalBoolField(object, "continue")) |continue_processing| {
        if (!continue_processing) {
            if (optionalHookStringField(object, "stopReason")) |reason| {
                try appendHookOutputEntry(allocator, entries, "stop", reason);
            }
            return "stopped";
        }
    }

    return "completed";
}

fn appendInvalidSessionStartJsonOutput(
    allocator: std.mem.Allocator,
    entries: *std.ArrayList(HookOutputEntry),
) ![]const u8 {
    try appendHookOutputEntry(allocator, entries, "error", "hook returned invalid session start JSON output");
    return "failed";
}

fn isValidSessionStartOutputObject(object: std.json.ObjectMap) bool {
    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        const key = entry.key_ptr.*;
        const value = entry.value_ptr.*;
        if (std.mem.eql(u8, key, "continue") or std.mem.eql(u8, key, "suppressOutput")) {
            if (value != .bool) return false;
        } else if (std.mem.eql(u8, key, "systemMessage") or std.mem.eql(u8, key, "stopReason")) {
            if (!isNullOrString(value)) return false;
        } else if (std.mem.eql(u8, key, "hookSpecificOutput")) {
            if (!isValidSessionStartHookSpecificOutput(value)) return false;
        } else {
            return false;
        }
    }
    return true;
}

fn isValidSessionStartHookSpecificOutput(value: std.json.Value) bool {
    if (value == .null) return true;
    if (value != .object) return false;
    const object = value.object;
    const event_name = object.get("hookEventName") orelse return false;
    if (event_name != .string or !std.mem.eql(u8, event_name.string, "SessionStart")) return false;

    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        const key = entry.key_ptr.*;
        const field_value = entry.value_ptr.*;
        if (std.mem.eql(u8, key, "hookEventName")) {
            if (field_value != .string or !std.mem.eql(u8, field_value.string, "SessionStart")) return false;
        } else if (std.mem.eql(u8, key, "additionalContext")) {
            if (!isNullOrString(field_value)) return false;
        } else {
            return false;
        }
    }
    return true;
}

fn collectUserPromptSubmitHookEntries(
    allocator: std.mem.Allocator,
    result: *const CommandExecRunResult,
    entries: *std.ArrayList(HookOutputEntry),
    contexts: *std.ArrayList([]const u8),
) ![]const u8 {
    if (result.exit_code == 0) {
        const trimmed_stdout = std.mem.trim(u8, result.stdout, " \t\r\n");
        if (trimmed_stdout.len == 0) return "completed";
        if (try collectJsonUserPromptSubmitHookOutput(allocator, trimmed_stdout, entries, contexts)) |status| return status;
        if (looksLikeJson(trimmed_stdout)) {
            try appendHookOutputEntry(allocator, entries, "error", "hook returned invalid user prompt submit JSON output");
            return "failed";
        }
        try appendHookContextEntry(allocator, entries, contexts, trimmed_stdout);
        return "completed";
    }
    if (result.exit_code == 2) {
        const reason = std.mem.trim(u8, result.stderr, " \t\r\n");
        if (reason.len > 0) {
            try appendHookOutputEntry(allocator, entries, "feedback", reason);
            return "blocked";
        }
        try appendHookOutputEntry(allocator, entries, "error", "UserPromptSubmit hook exited with code 2 but did not write a blocking reason to stderr");
        return "failed";
    }
    const message = try std.fmt.allocPrint(allocator, "hook exited with code {d}", .{result.exit_code});
    defer allocator.free(message);
    try appendHookOutputEntry(allocator, entries, "error", message);
    return "failed";
}

fn collectJsonUserPromptSubmitHookOutput(
    allocator: std.mem.Allocator,
    stdout: []const u8,
    entries: *std.ArrayList(HookOutputEntry),
    contexts: *std.ArrayList([]const u8),
) !?[]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, stdout, .{}) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return null,
    };
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const object = parsed.value.object;
    if (!isValidUserPromptSubmitOutputObject(object)) return try appendInvalidUserPromptSubmitJsonOutput(allocator, entries);

    var additional_context: ?[]const u8 = null;
    if (object.get("hookSpecificOutput")) |specific| {
        if (specific == .null) {
            // Explicit null matches the Rust optional hookSpecificOutput field.
        } else if (specific == .object) {
            const event_name = optionalHookStringField(specific.object, "hookEventName") orelse return try appendInvalidUserPromptSubmitJsonOutput(allocator, entries);
            if (!isHookEventWireName(event_name)) return try appendInvalidUserPromptSubmitJsonOutput(allocator, entries);
            additional_context = optionalHookStringField(specific.object, "additionalContext");
        } else {
            return try appendInvalidUserPromptSubmitJsonOutput(allocator, entries);
        }
    }

    var should_block = false;
    var invalid_block_reason = false;
    var block_reason: ?[]const u8 = null;
    if (object.get("decision")) |decision_value| {
        if (decision_value == .null) {
            // Explicit null matches the Rust optional decision field.
        } else if (decision_value == .string and std.mem.eql(u8, decision_value.string, "block")) {
            should_block = true;
            block_reason = optionalHookStringField(object, "reason");
            invalid_block_reason = block_reason == null or std.mem.trim(u8, block_reason.?, " \t\r\n").len == 0;
        } else {
            return try appendInvalidUserPromptSubmitJsonOutput(allocator, entries);
        }
    }

    if (optionalHookStringField(object, "systemMessage")) |message| {
        try appendHookOutputEntry(allocator, entries, "warning", message);
    }

    if (!invalid_block_reason) {
        if (additional_context) |context| {
            try appendHookContextEntry(allocator, entries, contexts, context);
        }
    }

    if (optionalBoolField(object, "continue")) |continue_processing| {
        if (!continue_processing) {
            if (optionalHookStringField(object, "stopReason")) |reason| {
                if (std.mem.trim(u8, reason, " \t\r\n").len > 0) {
                    try appendHookOutputEntry(allocator, entries, "stop", reason);
                }
            }
            return "stopped";
        }
    }
    if (invalid_block_reason) {
        try appendHookOutputEntry(allocator, entries, "error", "UserPromptSubmit hook returned decision:block without a non-empty reason");
        return "failed";
    }
    if (should_block) {
        try appendHookOutputEntry(allocator, entries, "feedback", block_reason.?);
        return "blocked";
    }
    return "completed";
}

fn appendInvalidUserPromptSubmitJsonOutput(
    allocator: std.mem.Allocator,
    entries: *std.ArrayList(HookOutputEntry),
) ![]const u8 {
    try appendHookOutputEntry(allocator, entries, "error", "hook returned invalid user prompt submit JSON output");
    return "failed";
}

fn optionalHookStringField(object: std.json.ObjectMap, field: []const u8) ?[]const u8 {
    const value = object.get(field) orelse return null;
    if (value != .string) return null;
    return value.string;
}

fn isValidUserPromptSubmitOutputObject(object: std.json.ObjectMap) bool {
    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        const key = entry.key_ptr.*;
        const value = entry.value_ptr.*;
        if (std.mem.eql(u8, key, "continue") or std.mem.eql(u8, key, "suppressOutput")) {
            if (value != .bool) return false;
        } else if (std.mem.eql(u8, key, "systemMessage") or std.mem.eql(u8, key, "stopReason") or std.mem.eql(u8, key, "reason")) {
            if (!isNullOrString(value)) return false;
        } else if (std.mem.eql(u8, key, "decision")) {
            if (value == .null) {
                continue;
            }
            if (value != .string or !std.mem.eql(u8, value.string, "block")) return false;
        } else if (std.mem.eql(u8, key, "hookSpecificOutput")) {
            if (!isValidUserPromptSubmitHookSpecificOutput(value)) return false;
        } else {
            return false;
        }
    }
    return true;
}

fn isValidUserPromptSubmitHookSpecificOutput(value: std.json.Value) bool {
    if (value == .null) return true;
    if (value != .object) return false;
    const object = value.object;
    const event_name = object.get("hookEventName") orelse return false;
    if (event_name != .string or !isHookEventWireName(event_name.string)) return false;

    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        const key = entry.key_ptr.*;
        const field_value = entry.value_ptr.*;
        if (std.mem.eql(u8, key, "hookEventName")) {
            if (field_value != .string or !isHookEventWireName(field_value.string)) return false;
        } else if (std.mem.eql(u8, key, "additionalContext")) {
            if (!isNullOrString(field_value)) return false;
        } else {
            return false;
        }
    }
    return true;
}

fn isNullOrString(value: std.json.Value) bool {
    return value == .null or value == .string;
}

fn isHookEventWireName(value: []const u8) bool {
    inline for (&.{
        "PreToolUse",
        "PermissionRequest",
        "PostToolUse",
        "PreCompact",
        "PostCompact",
        "SessionStart",
        "UserPromptSubmit",
        "Stop",
    }) |name| {
        if (std.mem.eql(u8, value, name)) return true;
    }
    return false;
}

fn appendHookContextEntry(
    allocator: std.mem.Allocator,
    entries: *std.ArrayList(HookOutputEntry),
    contexts: *std.ArrayList([]const u8),
    context: []const u8,
) !void {
    try appendHookOutputEntry(allocator, entries, "context", context);
    const owned_context = try allocator.dupe(u8, context);
    errdefer allocator.free(owned_context);
    try contexts.append(allocator, owned_context);
}

fn appendHookOutputEntry(
    allocator: std.mem.Allocator,
    entries: *std.ArrayList(HookOutputEntry),
    kind: []const u8,
    text: []const u8,
) !void {
    const owned_text = try allocator.dupe(u8, text);
    errdefer allocator.free(owned_text);
    try entries.append(allocator, .{ .kind = kind, .text = owned_text });
}

fn deinitHookOutputEntries(allocator: std.mem.Allocator, entries: *std.ArrayList(HookOutputEntry)) void {
    for (entries.items) |entry| entry.deinit(allocator);
    entries.deinit(allocator);
}

fn looksLikeJson(value: []const u8) bool {
    return value.len > 0 and (value[0] == '{' or value[0] == '[');
}

fn optionalBoolField(object: std.json.ObjectMap, name: []const u8) ?bool {
    const value = object.get(name) orelse return null;
    if (value != .bool) return null;
    return value.bool;
}

fn renderHookNotification(
    allocator: std.mem.Allocator,
    method: []const u8,
    thread_id: []const u8,
    turn_id: []const u8,
    hook: hooks_list.Hook,
    hook_run_id: []const u8,
    status: []const u8,
    started_at: i64,
    completed_at: ?i64,
    duration_ms: ?i64,
    entries: []const HookOutputEntry,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":");
    try appendJsonString(allocator, &notification, method);
    try notification.appendSlice(allocator, ",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &notification, turn_id);
    try notification.appendSlice(allocator, ",\"run\":{");
    try notification.appendSlice(allocator, "\"id\":");
    try appendJsonString(allocator, &notification, hook_run_id);
    try notification.appendSlice(allocator, ",\"eventName\":");
    try appendJsonString(allocator, &notification, hook.event_name.jsonLabel());
    try notification.appendSlice(allocator, ",\"handlerType\":\"command\",\"executionMode\":\"sync\",\"scope\":");
    try appendJsonString(allocator, &notification, hookScopeLabel(hook.event_name));
    try notification.appendSlice(allocator, ",\"sourcePath\":");
    try appendJsonString(allocator, &notification, hook.source_path);
    try notification.appendSlice(allocator, ",\"source\":");
    try appendJsonString(allocator, &notification, hook.source.label());
    try notification.appendSlice(allocator, ",\"displayOrder\":");
    try appendInt(allocator, &notification, hook.display_order);
    try notification.appendSlice(allocator, ",\"status\":");
    try appendJsonString(allocator, &notification, status);
    try notification.appendSlice(allocator, ",\"statusMessage\":");
    try appendOptionalJsonString(allocator, &notification, hook.status_message);
    try notification.appendSlice(allocator, ",\"startedAt\":");
    try appendInt(allocator, &notification, started_at);
    try notification.appendSlice(allocator, ",\"completedAt\":");
    try appendOptionalInt(allocator, &notification, completed_at);
    try notification.appendSlice(allocator, ",\"durationMs\":");
    try appendOptionalInt(allocator, &notification, duration_ms);
    try notification.appendSlice(allocator, ",\"entries\":[");
    for (entries, 0..) |entry, index| {
        if (index > 0) try notification.append(allocator, ',');
        try notification.appendSlice(allocator, "{\"kind\":");
        try appendJsonString(allocator, &notification, entry.kind);
        try notification.appendSlice(allocator, ",\"text\":");
        try appendJsonString(allocator, &notification, entry.text);
        try notification.append(allocator, '}');
    }
    try notification.appendSlice(allocator, "]}}}");
    return notification.toOwnedSlice(allocator);
}

fn hookScopeLabel(event_name: hooks_list.HookEvent) []const u8 {
    return switch (event_name) {
        .session_start => "thread",
        else => "turn",
    };
}

fn allocateNextTurnIdForThread(allocator: std.mem.Allocator, thread: *LoadedThread) ![]const u8 {
    syncLoadedThreadNextTurnIndex(thread);
    if (thread.reserved_next_turn_index) |reserved_next_turn_index| {
        if (thread.next_turn_index < reserved_next_turn_index) {
            thread.next_turn_index = reserved_next_turn_index;
        }
        thread.reserved_next_turn_index = null;
    }
    const index = thread.next_turn_index;
    const turn_id = try std.fmt.allocPrint(allocator, "turn-{d}", .{index});
    thread.next_turn_index = index + 1;
    return turn_id;
}

fn syncLoadedThreadNextTurnIndex(thread: *LoadedThread) void {
    thread.next_turn_index = turnCountForTranscript(&thread.transcript);
}

fn turnCountForTranscript(transcript: *const session_mod.Transcript) usize {
    var count: usize = 0;
    for (transcript.history.items) |item| {
        if (historyItemVisibleInTurns(item)) count += 1;
    }
    return count;
}

const defaultCollaborationDeveloperInstructions =
    "Work in default coding mode. Implement requested changes directly, keep edits focused, and verify the result before reporting completion.";
const planCollaborationDeveloperInstructions =
    "Work in plan mode. Clarify the approach before editing, present a concrete plan, and wrap plan responses in <proposed_plan>...</proposed_plan>.";

const TurnStartCollaborationMode = struct {
    mode: []const u8,
    model: []const u8,
    reasoning_effort: ?config.ReasoningEffort,
    developer_instructions: []const u8,
};

fn parseTurnStartCollaborationMode(params: std.json.ObjectMap) !?TurnStartCollaborationMode {
    const value = params.get("collaborationMode") orelse return null;
    if (value == .null) return null;
    if (value != .object) return error.InvalidTurnContextOverride;

    const mode_value = value.object.get("mode") orelse return error.InvalidTurnContextOverride;
    if (mode_value != .string) return error.InvalidTurnContextOverride;
    const mode = normalizeTurnStartCollaborationMode(mode_value.string) orelse return error.InvalidTurnContextOverride;

    const settings_value = value.object.get("settings") orelse return error.InvalidTurnContextOverride;
    if (settings_value != .object) return error.InvalidTurnContextOverride;
    const settings = settings_value.object;

    const model_value = settings.get("model") orelse return error.InvalidTurnContextOverride;
    if (model_value != .string or model_value.string.len == 0) return error.InvalidTurnContextOverride;

    const reasoning_effort = parseTurnStartCollaborationReasoningEffort(settings.get("reasoning_effort")) catch return error.InvalidTurnContextOverride;
    const developer_instructions = parseTurnStartCollaborationDeveloperInstructions(settings.get("developer_instructions"), mode) catch return error.InvalidTurnContextOverride;

    return .{
        .mode = mode,
        .model = model_value.string,
        .reasoning_effort = reasoning_effort,
        .developer_instructions = developer_instructions,
    };
}

fn normalizeTurnStartCollaborationMode(value: []const u8) ?[]const u8 {
    if (std.mem.eql(u8, value, "plan")) return "plan";
    if (std.mem.eql(u8, value, "default")) return "default";
    if (std.mem.eql(u8, value, "code")) return "default";
    if (std.mem.eql(u8, value, "pair_programming")) return "default";
    if (std.mem.eql(u8, value, "execute")) return "default";
    if (std.mem.eql(u8, value, "custom")) return "default";
    return null;
}

fn parseTurnStartCollaborationReasoningEffort(value: ?std.json.Value) !?config.ReasoningEffort {
    const raw = value orelse return null;
    if (raw == .null) return null;
    if (raw != .string) return error.InvalidTurnContextOverride;
    return config.ReasoningEffort.parse(raw.string) catch error.InvalidTurnContextOverride;
}

fn parseTurnStartCollaborationDeveloperInstructions(value: ?std.json.Value, mode: []const u8) ![]const u8 {
    const raw = value orelse return builtInTurnStartCollaborationInstructions(mode);
    if (raw == .null) return builtInTurnStartCollaborationInstructions(mode);
    if (raw != .string) return error.InvalidTurnContextOverride;
    return raw.string;
}

fn builtInTurnStartCollaborationInstructions(mode: []const u8) []const u8 {
    if (std.mem.eql(u8, mode, "plan")) return planCollaborationDeveloperInstructions;
    return defaultCollaborationDeveloperInstructions;
}

test "turn-start parses external sandbox policy" {
    const allocator = std.testing.allocator;
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, "{\"type\":\"externalSandbox\",\"networkAccess\":\"enabled\"}", .{});
    defer parsed.deinit();

    var policy = try parseTurnStartSandboxPolicy(allocator, parsed.value);
    defer policy.deinit(allocator);
