fn applyLoadedThreadRuntimeToConfig(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    thread: *const LoadedThread,
) !void {
    try replaceOwnedString(allocator, &cfg.model, thread.model);
    cfg.model_context_window = thread.model_context_window;
    cfg.model_auto_compact_token_limit = thread.model_auto_compact_token_limit;
    if (thread.model_verbosity) |value| {
        cfg.model_verbosity = config.Verbosity.parse(value) catch return error.InvalidLoadedThreadRuntime;
    } else {
        cfg.model_verbosity = null;
    }
    try config.applyRuntimeOverrides(cfg, allocator, .{ .model_provider_id = thread.model_provider });
    try applyLoadedThreadBaseUrlsToConfig(allocator, cfg, thread);
    cfg.web_search_mode = thread.web_search_mode;
    cfg.approval_policy = config.ApprovalPolicy.parse(thread.approval_policy) catch return error.InvalidLoadedThreadRuntime;
    cfg.sandbox_mode = config.SandboxMode.parse(thread.sandbox_mode) catch return error.InvalidLoadedThreadRuntime;
    if (cfg.service_tier) |existing| allocator.free(existing);
    cfg.service_tier = null;
    cfg.service_tier = if (thread.service_tier) |value| try allocator.dupe(u8, value) else null;
    if (thread.reasoning_effort) |value| {
        cfg.model_reasoning_effort = config.ReasoningEffort.parse(value) catch return error.InvalidLoadedThreadRuntime;
    } else {
        cfg.model_reasoning_effort = null;
    }
    if (thread.reasoning_summary) |value| {
        cfg.model_reasoning_summary = config.ReasoningSummary.parse(value) catch return error.InvalidLoadedThreadRuntime;
    } else {
        cfg.model_reasoning_summary = null;
    }
    if (thread.personality) |value| {
        cfg.personality = config.Personality.parse(value) catch return error.InvalidLoadedThreadRuntime;
    } else {
        cfg.personality = null;
    }
    if (thread.collaboration_developer_instructions) |value| {
        try replaceConfigOptionalString(allocator, &cfg.developer_instructions, value);
    }
    try applyLoadedThreadOssModeToConfig(allocator, cfg, thread);
}

fn applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    requirements: ConfigRequirementsReadRequirements,
) !void {
    const approval_policy = try configReadRequirementApprovalPolicy(
        config.ApprovalPolicy.parse(thread.approval_policy) catch return error.InvalidLoadedThreadRuntime,
        requirements,
    );
    if (!std.mem.eql(u8, thread.approval_policy, approval_policy.label())) {
        try replaceOwnedString(allocator, &thread.approval_policy, approval_policy.label());
    }

    const approvals_reviewer = try configReadRequirementApprovalsReviewer(
        config.ApprovalsReviewer.parse(thread.approvals_reviewer) catch return error.InvalidLoadedThreadRuntime,
        requirements,
    );
    if (!std.mem.eql(u8, thread.approvals_reviewer, approvals_reviewer.label())) {
        try replaceOwnedString(allocator, &thread.approvals_reviewer, approvals_reviewer.label());
    }

    const sandbox_mode = try configReadRequirementSandboxMode(
        config.SandboxMode.parse(thread.sandbox_mode) catch return error.InvalidLoadedThreadRuntime,
        requirements,
    );
    if (!std.mem.eql(u8, thread.sandbox_mode, sandbox_mode.label())) {
        const sandbox_runtime_override = thread.runtime_overrides.sandbox_mode;
        try resetLoadedThreadSandboxProfile(
            allocator,
            thread,
            sandbox_mode,
            defaultNetworkEnabledForSandboxMode(sandbox_mode),
            false,
        );
        thread.runtime_overrides.sandbox_mode = sandbox_runtime_override;
    }

    thread.web_search_mode = try configReadRequirementWebSearchMode(thread.web_search_mode, requirements);
}

fn applyReviewStartConstraints(allocator: std.mem.Allocator, cfg: *config.Config) !void {
    cfg.web_search_mode = .disabled;
    cfg.approval_policy = .never;
    cfg.sandbox_mode = .read_only;
    try replaceConfigOptionalString(allocator, &cfg.base_instructions, review_prompt.text);
    clearOptionalOwnedString(allocator, &cfg.developer_instructions);
}

fn applyReviewStartFeatureOverrides(
    allocator: std.mem.Allocator,
    overrides: *features_cmd.FeatureOverrides,
) !void {
    try overrides.put(allocator, "multi_agent", false);
    try overrides.put(allocator, "multi_agent_v2", false);
    try overrides.put(allocator, "mcp_tools", false);
    try overrides.put(allocator, "mcp_resource_tools", false);
    try overrides.put(allocator, "write_stdin_tool", false);
    try overrides.put(allocator, "request_permissions_tool", false);
    try overrides.put(allocator, "request_user_input_tool", false);
    try overrides.put(allocator, "default_mode_request_user_input", false);
    try overrides.put(allocator, "goal_tools", false);
}

fn validateTurnScalarRequirementOverrides(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    cwd: []const u8,
    params: std.json.ObjectMap,
    requirements: ConfigRequirementsReadRequirements,
) !void {
    if (optionalStringParam(params, "approvalPolicy")) |approval_policy| {
        try validateRuntimeApprovalPolicyAllowed(
            config.ApprovalPolicy.parse(approval_policy) catch return error.InvalidTurnContextOverride,
            requirements,
        );
    }
    if (try optionalApprovalsReviewerParam(params, "approvalsReviewer")) |approvals_reviewer| {
        try validateRuntimeApprovalsReviewerAllowed(
            config.ApprovalsReviewer.parse(approvals_reviewer) catch return error.InvalidTurnContextOverride,
            requirements,
        );
    }

    const permissions_value = params.get("permissions");
    const has_permissions = permissions_value != null and permissions_value.? != .null;
    if (has_permissions) {
        if (params.get("sandboxPolicy")) |sandbox_policy| {
            if (sandbox_policy != .null) return error.InvalidTurnContextOverride;
        }
        if (params.get("sandbox")) |sandbox| {
            if (sandbox != .null) return error.InvalidTurnContextOverride;
        }
        var profile = parseTurnStartPermissionSelection(allocator, codex_home, cwd, permissions_value.?) catch return error.InvalidTurnContextOverride;
        defer profile.deinit(allocator);
        try validateRuntimeSandboxModeAllowed(profile.mode, requirements);
    } else if (params.get("sandboxPolicy")) |sandbox_policy| {
        if (sandbox_policy != .null and params.get("sandbox") != null and params.get("sandbox").? != .null) {
            return error.InvalidTurnContextOverride;
        }
        if (sandbox_policy != .null) {
            var sandbox_selection = parseTurnStartSandboxPolicy(allocator, sandbox_policy) catch return error.InvalidTurnContextOverride;
            defer sandbox_selection.deinit(allocator);
            try validateRuntimeSandboxModeAllowed(sandbox_selection.mode, requirements);
        } else if (optionalStringParam(params, "sandbox")) |sandbox| {
            try validateRuntimeSandboxModeAllowed(
                config.SandboxMode.parse(sandbox) catch return error.InvalidTurnContextOverride,
                requirements,
            );
        }
    } else if (optionalStringParam(params, "sandbox")) |sandbox| {
        try validateRuntimeSandboxModeAllowed(
            config.SandboxMode.parse(sandbox) catch return error.InvalidTurnContextOverride,
            requirements,
        );
    }
}

fn applyTurnStartRuntimeConfigOverrides(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    thread: *const LoadedThread,
    params: std.json.ObjectMap,
) !void {
    const collaboration_mode = try parseTurnStartCollaborationMode(params);

    const effective_model = if (collaboration_mode) |collaboration|
        collaboration.model
    else
        optionalStringParam(params, "model") orelse thread.model;
    try replaceOwnedString(allocator, &cfg.model, effective_model);

    cfg.model_context_window = thread.model_context_window;
    cfg.model_auto_compact_token_limit = thread.model_auto_compact_token_limit;
    if (thread.model_verbosity) |value| {
        cfg.model_verbosity = config.Verbosity.parse(value) catch return error.InvalidTurnContextOverride;
    } else {
        cfg.model_verbosity = null;
    }
    cfg.web_search_mode = thread.web_search_mode;

    const approval_policy_label = optionalStringParam(params, "approvalPolicy") orelse thread.approval_policy;
    cfg.approval_policy = config.ApprovalPolicy.parse(approval_policy_label) catch return error.InvalidTurnContextOverride;

    const requested_reviewer = optionalApprovalsReviewerParam(params, "approvalsReviewer") catch return error.InvalidTurnContextOverride;
    cfg.approvals_reviewer = config.ApprovalsReviewer.parse(requested_reviewer orelse thread.approvals_reviewer) catch return error.InvalidTurnContextOverride;

    const permissions_value = params.get("permissions");
    const has_permissions = permissions_value != null and permissions_value.? != .null;
    if (has_permissions) {
        if (params.get("sandboxPolicy")) |sandbox_policy| {
            if (sandbox_policy != .null) return error.InvalidTurnContextOverride;
        }
        if (params.get("sandbox")) |sandbox| {
            if (sandbox != .null) return error.InvalidTurnContextOverride;
        }
        const permission_profile_cwd = try turnContextProjectConfigCwd(allocator, thread, params);
        defer allocator.free(permission_profile_cwd);
        var profile = parseTurnStartPermissionSelection(allocator, cfg.codex_home, permission_profile_cwd, permissions_value.?) catch return error.InvalidTurnContextOverride;
        defer profile.deinit(allocator);
        cfg.sandbox_mode = profile.mode;
    } else if (params.get("sandboxPolicy")) |sandbox_policy| {
        if (sandbox_policy != .null and params.get("sandbox") != null and params.get("sandbox").? != .null) return error.InvalidTurnContextOverride;
        if (sandbox_policy != .null) {
            var sandbox_selection = parseTurnStartSandboxPolicy(allocator, sandbox_policy) catch return error.InvalidTurnContextOverride;
            defer sandbox_selection.deinit(allocator);
            cfg.sandbox_mode = sandbox_selection.mode;
        } else {
            const sandbox_label = optionalStringParam(params, "sandbox") orelse thread.sandbox_mode;
            cfg.sandbox_mode = config.SandboxMode.parse(sandbox_label) catch return error.InvalidTurnContextOverride;
        }
    } else {
        const sandbox_label = optionalStringParam(params, "sandbox") orelse thread.sandbox_mode;
        cfg.sandbox_mode = config.SandboxMode.parse(sandbox_label) catch return error.InvalidTurnContextOverride;
    }

    const requested_model_provider = optionalStringParam(params, "modelProvider");
    try config.applyRuntimeOverrides(cfg, allocator, .{
        .model_provider_id = requested_model_provider orelse thread.model_provider,
    });
    if (requested_model_provider == null) {
        try applyLoadedThreadBaseUrlsToConfig(allocator, cfg, thread);
    }

    if (params.get("serviceTier")) |service_tier_value| {
        if (service_tier_value != .null and service_tier_value != .string) return error.InvalidTurnContextOverride;
        clearOptionalOwnedString(allocator, &cfg.service_tier);
        cfg.service_tier = if (service_tier_value == .string)
            try allocator.dupe(u8, service_tier_value.string)
        else
            null;
    } else {
        clearOptionalOwnedString(allocator, &cfg.service_tier);
        cfg.service_tier = if (thread.service_tier) |value| try allocator.dupe(u8, value) else null;
    }

    const requested_effort = if (collaboration_mode) |collaboration|
        collaboration.reasoning_effort
    else
        optionalReasoningEffortParam(params, "effort") catch return error.InvalidTurnContextOverride;
    if (requested_effort) |effort| {
        cfg.model_reasoning_effort = effort;
    } else if (collaboration_mode != null) {
        cfg.model_reasoning_effort = null;
    } else if (thread.reasoning_effort) |value| {
        cfg.model_reasoning_effort = config.ReasoningEffort.parse(value) catch return error.InvalidTurnContextOverride;
    } else {
        cfg.model_reasoning_effort = null;
    }

    const requested_summary = optionalReasoningSummaryParam(params, "summary") catch return error.InvalidTurnContextOverride;
    if (requested_summary) |summary| {
        cfg.model_reasoning_summary = summary;
    } else if (thread.reasoning_summary) |value| {
        cfg.model_reasoning_summary = config.ReasoningSummary.parse(value) catch return error.InvalidTurnContextOverride;
    } else {
        cfg.model_reasoning_summary = null;
    }

    const requested_personality = optionalPersonalityParam(params, "personality") catch return error.InvalidTurnContextOverride;
    if (requested_personality) |personality| {
        cfg.personality = personality;
    } else if (thread.personality) |value| {
        cfg.personality = config.Personality.parse(value) catch return error.InvalidTurnContextOverride;
    } else {
        cfg.personality = null;
    }

    if (collaboration_mode) |collaboration| {
        try replaceConfigOptionalString(allocator, &cfg.developer_instructions, collaboration.developer_instructions);
    } else if (thread.collaboration_developer_instructions) |value| {
        try replaceConfigOptionalString(allocator, &cfg.developer_instructions, value);
    }
    try applyLoadedThreadOssModeToConfig(allocator, cfg, thread);
}

fn applyTurnStartRuntimeOverrides(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    thread: *LoadedThread,
    params: std.json.ObjectMap,
    provider_config_prepared: bool,
) !void {
    const collaboration_mode = try parseTurnStartCollaborationMode(params);

    const effective_model = if (collaboration_mode) |collaboration|
        collaboration.model
    else
        optionalStringParam(params, "model") orelse thread.model;
    try replaceOwnedString(allocator, &cfg.model, effective_model);
    if (collaboration_mode) |collaboration| {
        try replaceOwnedString(allocator, &thread.model, collaboration.model);
        try replaceOwnedString(allocator, &thread.collaboration_mode, collaboration.mode);
        try replaceOptionalOwnedString(allocator, &thread.collaboration_developer_instructions, collaboration.developer_instructions);
        thread.runtime_overrides.model = true;
        thread.runtime_overrides.collaboration_mode = true;
    } else if (optionalStringParam(params, "model")) |model| {
        try replaceOwnedString(allocator, &thread.model, model);
        thread.runtime_overrides.model = true;
    }

    cfg.model_context_window = thread.model_context_window;
    cfg.model_auto_compact_token_limit = thread.model_auto_compact_token_limit;
    if (thread.model_verbosity) |value| {
        cfg.model_verbosity = config.Verbosity.parse(value) catch return error.InvalidTurnContextOverride;
    } else {
        cfg.model_verbosity = null;
    }
    cfg.web_search_mode = thread.web_search_mode;

    if (optionalStringParam(params, "cwd")) |cwd_raw| {
        const cwd = try std.Io.Dir.cwd().realPathFileAlloc(std.Io.Threaded.global_single_threaded.io(), cwd_raw, allocator);
        defer allocator.free(cwd);
        try replaceOwnedString(allocator, &thread.cwd, cwd);
        try thread.transcript.setCwd(allocator, cwd);
    }

    const approval_policy_label = optionalStringParam(params, "approvalPolicy") orelse thread.approval_policy;
    cfg.approval_policy = config.ApprovalPolicy.parse(approval_policy_label) catch return error.InvalidTurnContextOverride;
    if (optionalStringParam(params, "approvalPolicy")) |approval_policy| {
        try replaceOwnedString(allocator, &thread.approval_policy, approval_policy);
        thread.runtime_overrides.approval_policy = true;
    }

    const requested_reviewer = optionalApprovalsReviewerParam(params, "approvalsReviewer") catch return error.InvalidTurnContextOverride;
    if (requested_reviewer) |approvals_reviewer| {
        try replaceOwnedString(allocator, &thread.approvals_reviewer, approvals_reviewer);
        thread.runtime_overrides.approvals_reviewer = true;
    }

    const permissions_value = params.get("permissions");
    const has_permissions = permissions_value != null and permissions_value.? != .null;
    if (has_permissions) {
        if (params.get("sandboxPolicy")) |sandbox_policy| {
            if (sandbox_policy != .null) return error.InvalidTurnContextOverride;
        }
        if (params.get("sandbox")) |sandbox| {
            if (sandbox != .null) return error.InvalidTurnContextOverride;
        }
        var profile = parseTurnStartPermissionSelection(allocator, cfg.codex_home, thread.cwd, permissions_value.?) catch return error.InvalidTurnContextOverride;
        defer profile.deinit(allocator);
        try applySandboxPermissionProfileToLoadedThread(allocator, cfg, thread, &profile);
    } else if (params.get("sandboxPolicy")) |sandbox_policy| {
        if (sandbox_policy != .null and params.get("sandbox") != null and params.get("sandbox").? != .null) return error.InvalidTurnContextOverride;
        if (sandbox_policy != .null) {
            var sandbox_selection = parseTurnStartSandboxPolicy(allocator, sandbox_policy) catch return error.InvalidTurnContextOverride;
            defer sandbox_selection.deinit(allocator);
            cfg.sandbox_mode = sandbox_selection.mode;
            var writable_roots = sandbox_selection.takeWritableRoots();
            var writable_roots_moved = false;
            errdefer if (!writable_roots_moved) writable_roots.deinit(allocator);
            var read_denied_roots = try emptyStringList(allocator);
            var read_denied_roots_moved = false;
            errdefer if (!read_denied_roots_moved) read_denied_roots.deinit(allocator);
            var read_denied_globs = try emptyStringList(allocator);
            var read_denied_globs_moved = false;
            errdefer if (!read_denied_globs_moved) read_denied_globs.deinit(allocator);
            try replaceLoadedThreadSandboxProfile(
                allocator,
                thread,
                sandbox_selection.mode,
                writable_roots,
                read_denied_roots,
                read_denied_globs,
                true,
                sandbox_selection.network_enabled,
                sandbox_selection.exclude_tmpdir_env_var,
                sandbox_selection.exclude_slash_tmp,
                sandbox_selection.external,
            );
            writable_roots_moved = true;
            read_denied_roots_moved = true;
            read_denied_globs_moved = true;
        } else {
            const sandbox_label = optionalStringParam(params, "sandbox") orelse thread.sandbox_mode;
            cfg.sandbox_mode = config.SandboxMode.parse(sandbox_label) catch return error.InvalidTurnContextOverride;
            if (optionalStringParam(params, "sandbox")) |sandbox| {
                const requested_sandbox_mode = config.SandboxMode.parse(sandbox) catch return error.InvalidTurnContextOverride;
                try resetLoadedThreadSandboxProfile(
                    allocator,
                    thread,
                    requested_sandbox_mode,
                    defaultNetworkEnabledForSandboxMode(requested_sandbox_mode),
                    false,
                );
            }
        }
    } else {
        const sandbox_label = optionalStringParam(params, "sandbox") orelse thread.sandbox_mode;
        cfg.sandbox_mode = config.SandboxMode.parse(sandbox_label) catch return error.InvalidTurnContextOverride;
        if (optionalStringParam(params, "sandbox")) |sandbox| {
            const requested_sandbox_mode = config.SandboxMode.parse(sandbox) catch return error.InvalidTurnContextOverride;
            try resetLoadedThreadSandboxProfile(
                allocator,
                thread,
                requested_sandbox_mode,
                defaultNetworkEnabledForSandboxMode(requested_sandbox_mode),
                false,
            );
        }
    }

    const requested_model_provider = optionalStringParam(params, "modelProvider");
    if (requested_model_provider) |model_provider| {
        try replaceOwnedString(allocator, &thread.model_provider, model_provider);
        try thread.transcript.setModelProvider(allocator, model_provider);
        clearLoadedThreadBaseUrls(allocator, thread);
        thread.runtime_overrides.model_provider = true;
    }
    if (!provider_config_prepared) {
        try config.applyRuntimeOverrides(cfg, allocator, .{ .model_provider_id = thread.model_provider });
    }
    try applyLoadedThreadBaseUrlsToConfig(allocator, cfg, thread);

    if (params.get("serviceTier")) |service_tier_value| {
        if (service_tier_value != .null and service_tier_value != .string) return error.InvalidTurnContextOverride;
        if (thread.service_tier) |existing| allocator.free(existing);
        thread.service_tier = if (service_tier_value == .string)
            try allocator.dupe(u8, service_tier_value.string)
        else
            null;
        if (cfg.service_tier) |existing| allocator.free(existing);
        cfg.service_tier = if (thread.service_tier) |value| try allocator.dupe(u8, value) else null;
        thread.runtime_overrides.service_tier = true;
    } else {
        if (cfg.service_tier) |existing| allocator.free(existing);
        cfg.service_tier = if (thread.service_tier) |value| try allocator.dupe(u8, value) else null;
    }

    const requested_effort = if (collaboration_mode) |collaboration|
        collaboration.reasoning_effort
    else
        optionalReasoningEffortParam(params, "effort") catch return error.InvalidTurnContextOverride;
    if (collaboration_mode != null) {
        if (requested_effort) |effort| {
            cfg.model_reasoning_effort = effort;
            try replaceOptionalOwnedString(allocator, &thread.reasoning_effort, effort.label());
        } else {
            cfg.model_reasoning_effort = null;
            clearOptionalOwnedString(allocator, &thread.reasoning_effort);
        }
        thread.runtime_overrides.reasoning_effort = true;
    } else if (requested_effort) |effort| {
        cfg.model_reasoning_effort = effort;
        try replaceOptionalOwnedString(allocator, &thread.reasoning_effort, effort.label());
        thread.runtime_overrides.reasoning_effort = true;
    } else if (thread.reasoning_effort) |value| {
        cfg.model_reasoning_effort = config.ReasoningEffort.parse(value) catch return error.InvalidTurnContextOverride;
    } else {
        cfg.model_reasoning_effort = null;
    }

    const requested_summary = optionalReasoningSummaryParam(params, "summary") catch return error.InvalidTurnContextOverride;
    if (requested_summary) |summary| {
        cfg.model_reasoning_summary = summary;
        try replaceOptionalOwnedString(allocator, &thread.reasoning_summary, summary.label());
        thread.runtime_overrides.reasoning_summary = true;
    } else if (thread.reasoning_summary) |value| {
        cfg.model_reasoning_summary = config.ReasoningSummary.parse(value) catch return error.InvalidTurnContextOverride;
    } else {
        cfg.model_reasoning_summary = null;
    }

    const requested_personality = optionalPersonalityParam(params, "personality") catch return error.InvalidTurnContextOverride;
    if (requested_personality) |personality| {
        cfg.personality = personality;
        try replaceOptionalOwnedString(allocator, &thread.personality, personality.label());
        thread.runtime_overrides.personality = true;
    } else if (thread.personality) |value| {
        cfg.personality = config.Personality.parse(value) catch return error.InvalidTurnContextOverride;
    } else {
        cfg.personality = null;
    }

    if (thread.collaboration_developer_instructions) |value| {
        if (cfg.developer_instructions) |existing| allocator.free(existing);
        cfg.developer_instructions = try allocator.dupe(u8, value);
    }
    try applyLoadedThreadOssModeToConfig(allocator, cfg, thread);
}

fn handleThreadSettingsUpdate(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
        error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, "thread/settings/update"),
    };
    const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
        error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
    };
    if (!isUuidString(thread_id)) {
        return renderInvalidThreadId(allocator, id_value, thread_id);
    }
    if (validateThreadSettingsUpdateParams(object)) |message| {
        return renderJsonRpcError(allocator, id_value, -32602, message);
    }
    const thread_index = findLoadedThreadIndex(state, thread_id) orelse {
        return renderThreadNotFound(allocator, id_value, thread_id);
    };
    const thread = &state.loaded_threads.items[thread_index];

    var cfg = loadConfigForLoadedThread(allocator, state, thread) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/settings/update failed to load config", err);
    };
    defer cfg.deinit(allocator);

    const project_cwd = turnContextProjectConfigCwd(allocator, thread, object) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/settings/update failed to resolve cwd", err);
    };
    defer allocator.free(project_cwd);

    applyProjectLayersToConfigForCwd(allocator, &cfg, project_cwd) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/settings/update failed to load project config", err);
    };

    var runtime_requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/settings/update failed to load config requirements", err);
    };
    defer runtime_requirements.deinit(allocator);

    validateTurnScalarRequirementOverrides(allocator, cfg.codex_home, project_cwd, object, runtime_requirements) catch |err| switch (err) {
        error.InvalidTurnContextOverride => return renderJsonRpcError(allocator, id_value, -32602, "invalid thread settings override"),
        else => return renderRuntimeRequirementOverrideError(allocator, id_value, err),
    };

    applyTurnStartRuntimeConfigOverrides(allocator, &cfg, thread, object) catch |err| switch (err) {
        error.InvalidTurnContextOverride => return renderJsonRpcError(allocator, id_value, -32602, "invalid thread settings override"),
        else => return err,
    };
    applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/settings/update failed to apply config requirements", err);
    };

    applyTurnStartRuntimeOverrides(allocator, &cfg, thread, object, true) catch |err| switch (err) {
        error.InvalidTurnContextOverride => return renderJsonRpcError(allocator, id_value, -32602, "invalid thread settings override"),
        else => return err,
    };
    applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(allocator, thread, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/settings/update failed to apply runtime requirements", err);
    };

    const notification = try renderThreadSettingsUpdatedNotification(allocator, thread);
    try queuePendingServerNotification(allocator, state, "thread/settings/updated", notification);
    return renderJsonRpcResult(allocator, id_value, "{}");
}

fn validateThreadSettingsUpdateParams(object: std.json.ObjectMap) ?[]const u8 {
    inline for (&.{
        "model",
        "modelProvider",
        "serviceTier",
        "cwd",
        "approvalPolicy",
        "sandbox",
    }) |field| {
        if (!threadSettingsOptionalStringFieldIsValid(object, field)) return "thread settings string overrides must be strings or null";
    }
    if (!threadSettingsOptionalFieldIsStringObjectOrNull(object, "permissions")) return "permissions must be a string, profile object, or null";
    if (object.get("sandboxPolicy")) |sandbox_policy| {
        if (sandbox_policy != .null and sandbox_policy != .object) return "sandboxPolicy must be an object or null";
    }
    const has_permissions = object.get("permissions") != null and object.get("permissions").? != .null;
    const has_sandbox_policy = object.get("sandboxPolicy") != null and object.get("sandboxPolicy").? != .null;
    if (has_permissions and has_sandbox_policy) return "`permissions` cannot be combined with `sandboxPolicy`";
    return null;
}

fn threadSettingsOptionalStringFieldIsValid(object: std.json.ObjectMap, name: []const u8) bool {
    const value = object.get(name) orelse return true;
    return value == .null or value == .string;
}

fn threadSettingsOptionalFieldIsStringObjectOrNull(object: std.json.ObjectMap, name: []const u8) bool {
    const value = object.get(name) orelse return true;
    return value == .null or value == .string or value == .object;
}

fn applySandboxPermissionProfileToLoadedThread(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    thread: *LoadedThread,
    profile: *const config.SandboxPermissionProfile,
) !void {
    cfg.sandbox_mode = profile.mode;
    var roots = try loadedThreadRootsFromProfile(allocator, thread.cwd, profile.additional_writable_roots.items);
    var roots_moved = false;
    errdefer if (!roots_moved) roots.deinit(allocator);
    var read_denied_roots = try loadedThreadRootsFromProfile(allocator, thread.cwd, profile.read_denied_roots.items);
    var read_denied_roots_moved = false;
    errdefer if (!read_denied_roots_moved) read_denied_roots.deinit(allocator);
    var read_denied_globs = try loadedThreadGlobsFromProfile(allocator, thread.cwd, profile.read_denied_globs.items);
    var read_denied_globs_moved = false;
    errdefer if (!read_denied_globs_moved) read_denied_globs.deinit(allocator);
    try replaceLoadedThreadSandboxProfile(
        allocator,
        thread,
        profile.mode,
        roots,
        read_denied_roots,
        read_denied_globs,
        profile.include_cwd_write_root,
        profile.network_enabled,
        profile.exclude_tmpdir_env_var,
        profile.exclude_slash_tmp,
        false,
    );
    roots_moved = true;
    read_denied_roots_moved = true;
    read_denied_globs_moved = true;
}

fn turnContextProjectConfigCwd(
    allocator: std.mem.Allocator,
    thread: *const LoadedThread,
    params: std.json.ObjectMap,
) ![]const u8 {
    if (optionalStringParam(params, "cwd")) |cwd_raw| {
        return realPathFileAllocPlain(allocator, cwd_raw);
    }
    return allocator.dupe(u8, thread.cwd);
}

const TurnStartSandboxPolicy = struct {
    mode: config.SandboxMode,
    network_enabled: bool,
    exclude_tmpdir_env_var: bool = false,
    exclude_slash_tmp: bool = false,
    external: bool = false,
    writable_roots: config.StringList,
    roots_moved: bool = false,

    fn deinit(self: *TurnStartSandboxPolicy, allocator: std.mem.Allocator) void {
        if (!self.roots_moved) self.writable_roots.deinit(allocator);
    }

    fn takeWritableRoots(self: *TurnStartSandboxPolicy) config.StringList {
        self.roots_moved = true;
        return self.writable_roots;
    }
};

fn parseTurnStartSandboxPolicy(allocator: std.mem.Allocator, value: std.json.Value) !TurnStartSandboxPolicy {
    if (value != .object) return error.InvalidTurnContextOverride;
    const type_value = value.object.get("type") orelse return error.InvalidTurnContextOverride;
    if (type_value != .string) return error.InvalidTurnContextOverride;
    if (std.mem.eql(u8, type_value.string, "dangerFullAccess")) return .{
        .mode = .danger_full_access,
        .network_enabled = true,
        .writable_roots = try emptyStringList(allocator),
    };
    if (std.mem.eql(u8, type_value.string, "readOnly")) {
        try expectTurnStartSandboxPolicyNetworkDisabled(value.object);
        return .{
            .mode = .read_only,
            .network_enabled = false,
            .writable_roots = try emptyStringList(allocator),
        };
    }
    if (std.mem.eql(u8, type_value.string, "externalSandbox")) {
        return .{
            .mode = .danger_full_access,
            .network_enabled = parseCommandExecExternalSandboxPolicyNetworkAccess(value.object) catch return error.InvalidTurnContextOverride,
            .external = true,
            .writable_roots = try emptyStringList(allocator),
        };
    }
    if (std.mem.eql(u8, type_value.string, "workspaceWrite")) {
        try expectTurnStartSandboxPolicyNetworkDisabled(value.object);
        return .{
            .mode = .workspace_write,
            .network_enabled = false,
            .exclude_tmpdir_env_var = parseCommandExecSandboxPolicyBool(
                value.object,
                "excludeTmpdirEnvVar",
                error.InvalidTurnContextOverride,
            ) catch return error.InvalidTurnContextOverride,
            .exclude_slash_tmp = parseCommandExecSandboxPolicyBool(
                value.object,
                "excludeSlashTmp",
                error.InvalidTurnContextOverride,
            ) catch return error.InvalidTurnContextOverride,
            .writable_roots = try parseTurnStartSandboxPolicyWritableRoots(allocator, value.object),
        };
    }
    return error.InvalidTurnContextOverride;
}

fn parseTurnStartSandboxPolicyWritableRoots(allocator: std.mem.Allocator, object: std.json.ObjectMap) !config.StringList {
    const roots = parseCommandExecWritableRoots(allocator, object) catch return error.InvalidTurnContextOverride;
    defer allocator.free(roots);
    return (config.StringList{ .items = roots }).clone(allocator);
}

fn parseTurnStartPermissionSelection(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    cwd: []const u8,
    value: std.json.Value,
) !config.SandboxPermissionProfile {
    var modifications_value: ?std.json.Value = null;
    const profile_id = switch (value) {
        .string => |id| id,
        .object => |object| blk: {
            const type_value = object.get("type") orelse return error.InvalidTurnContextOverride;
            if (type_value != .string or !std.mem.eql(u8, type_value.string, "profile")) return error.InvalidTurnContextOverride;
            const id_value = object.get("id") orelse return error.InvalidTurnContextOverride;
            if (id_value != .string) return error.InvalidTurnContextOverride;
            modifications_value = object.get("modifications");
            break :blk id_value.string;
        },
        else => return error.InvalidTurnContextOverride,
    };
    if (profile_id.len == 0) return error.InvalidTurnContextOverride;

    var profile = loadSandboxPermissionProfileFromAppServerConfigStack(allocator, codex_home, cwd, profile_id, .{
        .allow_read_denied_globs = true,
    }) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return error.InvalidTurnContextOverride,
    };
    errdefer profile.deinit(allocator);

    try applyTurnStartPermissionModifications(allocator, &profile, modifications_value);
    return profile;
}

fn applyTurnStartPermissionModifications(
    allocator: std.mem.Allocator,
    profile: *config.SandboxPermissionProfile,
    modifications_value: ?std.json.Value,
) !void {
    const value = modifications_value orelse return;
    if (value == .null) return;
    if (value != .array) return error.InvalidTurnContextOverride;
    if (value.array.items.len == 0) return;

    var roots = std.ArrayList([]const u8).empty;
    var roots_moved = false;
    errdefer if (!roots_moved) {
        for (roots.items) |root| allocator.free(root);
        roots.deinit(allocator);
    };

    for (profile.additional_writable_roots.items) |root| {
        const copy = try allocator.dupe(u8, root);
        roots.append(allocator, copy) catch |err| {
            allocator.free(copy);
            return err;
        };
    }

    var added_root = false;
    for (value.array.items) |modification| {
        if (modification != .object) return error.InvalidTurnContextOverride;
        const type_value = modification.object.get("type") orelse return error.InvalidTurnContextOverride;
        if (type_value != .string or !std.mem.eql(u8, type_value.string, "additionalWritableRoot")) {
            return error.InvalidTurnContextOverride;
        }
        const path_value = modification.object.get("path") orelse return error.InvalidTurnContextOverride;
        if (path_value != .string or path_value.string.len == 0 or !std.fs.path.isAbsolute(path_value.string)) {
            return error.InvalidTurnContextOverride;
        }
        const path = try allocator.dupe(u8, path_value.string);
        roots.append(allocator, path) catch |err| {
            allocator.free(path);
            return err;
        };
        added_root = true;
    }

    if (!added_root) return;
    const owned_roots = try roots.toOwnedSlice(allocator);
    roots_moved = true;
    profile.additional_writable_roots.deinit(allocator);
    profile.additional_writable_roots = .{ .items = owned_roots };
    if (profile.mode == .read_only) {
        profile.mode = .workspace_write;
        profile.include_cwd_write_root = false;
    }
}

fn loadedThreadRootsFromProfile(
    allocator: std.mem.Allocator,
    cwd: []const u8,
    roots: []const []const u8,
) !config.StringList {
    var resolved = std.ArrayList([]const u8).empty;
    var moved = false;
    errdefer if (!moved) {
        for (resolved.items) |root| allocator.free(root);
        resolved.deinit(allocator);
    };

    for (roots) |root| {
        const owned = if (std.fs.path.isAbsolute(root))
            try std.fs.path.resolve(allocator, &.{root})
        else
            try std.fs.path.resolve(allocator, &.{ cwd, root });
        resolved.append(allocator, owned) catch |err| {
            allocator.free(owned);
            return err;
        };
    }

    const items = try resolved.toOwnedSlice(allocator);
    moved = true;
    return .{ .items = items };
}

fn loadedThreadGlobsFromProfile(
    allocator: std.mem.Allocator,
    cwd: []const u8,
    patterns: []const []const u8,
) !config.StringList {
    var resolved = std.ArrayList([]const u8).empty;
    var moved = false;
    errdefer if (!moved) {
        for (resolved.items) |pattern| allocator.free(pattern);
        resolved.deinit(allocator);
    };

    for (patterns) |pattern| {
        const owned = if (std.fs.path.isAbsolute(pattern))
            try allocator.dupe(u8, pattern)
        else
            try std.fs.path.resolve(allocator, &.{ cwd, pattern });
        resolved.append(allocator, owned) catch |err| {
            allocator.free(owned);
            return err;
        };
    }

    const items = try resolved.toOwnedSlice(allocator);
    moved = true;
    return .{ .items = items };
}

fn expectTurnStartSandboxPolicyNetworkDisabled(object: std.json.ObjectMap) !void {
    const value = object.get("networkAccess") orelse return;
    if (value == .null) return;
    if (value != .bool or value.bool) return error.InvalidTurnContextOverride;
}

fn emptyStringList(allocator: std.mem.Allocator) !config.StringList {
    return .{ .items = try allocator.alloc([]const u8, 0) };
}

fn defaultNetworkEnabledForSandboxMode(mode: config.SandboxMode) bool {
    return mode == .danger_full_access;
}

fn defaultNetworkEnabledForSandboxModeLabel(mode: []const u8) bool {
    return std.mem.eql(u8, mode, "danger-full-access");
}

fn resetLoadedThreadSandboxProfile(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    mode: config.SandboxMode,
    network_enabled: bool,
    external: bool,
) !void {
    var roots = try emptyStringList(allocator);
    errdefer roots.deinit(allocator);
    var read_denied_roots = try emptyStringList(allocator);
    errdefer read_denied_roots.deinit(allocator);
    var read_denied_globs = try emptyStringList(allocator);
    errdefer read_denied_globs.deinit(allocator);
    try replaceLoadedThreadSandboxProfile(
        allocator,
        thread,
        mode,
        roots,
        read_denied_roots,
        read_denied_globs,
        true,
        network_enabled,
        false,
        false,
        external,
    );
}

fn replaceLoadedThreadSandboxProfile(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    mode: config.SandboxMode,
    roots: config.StringList,
    read_denied_roots: config.StringList,
    read_denied_globs: config.StringList,
    include_cwd_write_root: bool,
    network_enabled: bool,
    exclude_tmpdir_env_var: bool,
    exclude_slash_tmp: bool,
    external: bool,
) !void {
    try replaceOwnedString(allocator, &thread.sandbox_mode, mode.label());
    thread.sandbox_writable_roots.deinit(allocator);
    thread.sandbox_writable_roots = roots;
    thread.sandbox_read_denied_roots.deinit(allocator);
    thread.sandbox_read_denied_roots = read_denied_roots;
    thread.sandbox_read_denied_globs.deinit(allocator);
    thread.sandbox_read_denied_globs = read_denied_globs;
    thread.sandbox_include_cwd_write_root = include_cwd_write_root;
    thread.sandbox_network_enabled = network_enabled;
    thread.sandbox_exclude_tmpdir_env_var = exclude_tmpdir_env_var;
    thread.sandbox_exclude_slash_tmp = exclude_slash_tmp;
    thread.sandbox_external = external;
    thread.runtime_overrides.sandbox_mode = true;
}

const LoadedThreadEffectiveWritableRoots = struct {
    items: []const []const u8,
    owned: bool = false,

    fn deinit(self: *LoadedThreadEffectiveWritableRoots, allocator: std.mem.Allocator) void {
        if (self.owned) allocator.free(self.items);
    }
};

fn loadedThreadEffectiveWritableRoots(
    allocator: std.mem.Allocator,
    thread: *const LoadedThread,
) !LoadedThreadEffectiveWritableRoots {
    if (!std.mem.eql(u8, thread.sandbox_mode, "workspace-write")) {
        return .{ .items = &.{} };
    }

    return .{
        .items = try buildCommandExecWorkspaceWriteRoots(
            allocator,
            thread.sandbox_writable_roots.items,
            if (thread.sandbox_exclude_tmpdir_env_var) null else commandExecCurrentAbsoluteEnv("TMPDIR"),
            if (thread.sandbox_exclude_slash_tmp) null else "/tmp",
        ),
        .owned = true,
    };
}

fn refreshLoadedThreadAfterTurn(allocator: std.mem.Allocator, thread: *LoadedThread, prompt: []const u8) !void {
    if (thread.preview.len == 0) try replaceOwnedString(allocator, &thread.preview, prompt);
    const turns_json = try renderTranscriptTurnsJson(allocator, &thread.transcript, true);
    errdefer allocator.free(turns_json);
    allocator.free(thread.turns_json);
    thread.turns_json = turns_json;
    try syncLoadedThreadTokenUsage(allocator, thread);
    syncLoadedThreadNextTurnIndex(thread);
    thread.updated_at = currentUnixSeconds();
}

fn refreshLoadedThreadAfterTurnAndAccountGoal(
    allocator: std.mem.Allocator,
    sqlite_home: []const u8,
    thread: *LoadedThread,
    prompt: []const u8,
    accounting_at: i64,
) !bool {
    try refreshLoadedThreadAfterTurn(allocator, thread, prompt);
    const goal_accounting_changed = refreshLoadedThreadGoalAccountingAt(thread, accounting_at);
    if (goal_accounting_changed) {
        try syncLoadedThreadGoalToTranscript(allocator, thread);
        _ = try saveLoadedThreadGoalToStateDb(allocator, sqlite_home, thread, false);
    }
    return goal_accounting_changed;
}

fn refreshLoadedThreadAfterReviewTurn(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    prompt: []const u8,
    minimum_next_turn_index: usize,
) !void {
    try refreshLoadedThreadAfterTurn(allocator, thread, prompt);
    thread.next_turn_index = preserveReviewNextTurnIndex(thread.next_turn_index, minimum_next_turn_index);
}

fn preserveReviewNextTurnIndex(next_turn_index: usize, minimum_next_turn_index: usize) usize {
    return if (next_turn_index < minimum_next_turn_index) minimum_next_turn_index else next_turn_index;
}

test "review turn refresh preserves allocated high-water mark" {
    try std.testing.expectEqual(@as(usize, 3), preserveReviewNextTurnIndex(1, 3));
    try std.testing.expectEqual(@as(usize, 4), preserveReviewNextTurnIndex(4, 3));
}

fn refreshLoadedThreadAfterUnpersistedTurn(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    prompt: []const u8,
    minimum_next_turn_index: usize,
) !void {
    try refreshLoadedThreadAfterTurn(allocator, thread, prompt);
    if (thread.next_turn_index < minimum_next_turn_index) {
        thread.next_turn_index = minimum_next_turn_index;
    }
    if (thread.reserved_next_turn_index) |reserved_next_turn_index| {
        if (reserved_next_turn_index < minimum_next_turn_index) {
            thread.reserved_next_turn_index = minimum_next_turn_index;
        }
    } else {
        thread.reserved_next_turn_index = minimum_next_turn_index;
    }
}

fn rollbackLoadedThread(allocator: std.mem.Allocator, thread: *LoadedThread, num_turns: u32) !bool {
    if (thread.status == .active) return error.RollbackWhileTurnActive;
    const path = thread.path orelse return error.RollbackRequiresPersistedHistory;
    var goal_cleared = false;
    if (rollbackCutIndex(&thread.transcript, num_turns)) |cut_index| {
        goal_cleared = thread.goal != null or thread.transcript.goal != null;
        trimTranscriptHistoryFrom(allocator, &thread.transcript, cut_index);
        thread.transcript.token_usage = null;
        thread.transcript.token_usage_turn_index = null;
        clearLoadedThreadGoalForRollback(allocator, thread);
    }
    try refreshLoadedThreadAfterRollback(allocator, thread);
    // The appended rollback event is the durable clear. Replay trims history and clears saved goal/token metadata.
    try session_store.appendThreadRollback(allocator, path, num_turns);
    return goal_cleared;
}

fn clearLoadedThreadGoalForRollback(allocator: std.mem.Allocator, thread: *LoadedThread) void {
    if (thread.goal) |*goal| goal.deinit(allocator);
    thread.goal = null;
    thread.transcript.clearGoal(allocator);
}

fn rollbackCutIndex(transcript: *const session_mod.Transcript, num_turns: u32) ?usize {
    var earliest_user_index: ?usize = null;
    var remaining = num_turns;
    var index = transcript.history.items.len;
    while (index > 0) {
        index -= 1;
        const item = transcript.history.items[index];
        if (item.kind == .message and isHistoryRole(item, "user")) {
            earliest_user_index = index;
            if (remaining == 1) return index;
            remaining -= 1;
        }
    }
    return earliest_user_index;
}

test "thread rollback rejects active loaded threads before history checks" {
    const allocator = std.testing.allocator;
    var cfg = try testAppServerConfig(allocator, "gpt-active-rollback");
    defer cfg.deinit(allocator);

    var params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"ephemeral\":true}", .{});
    defer params.deinit();

    var thread = try createLoadedThreadFromStartParams(allocator, cfg, params.value.object);
    defer thread.deinit(allocator);
    thread.status = .active;

    try std.testing.expectError(error.RollbackWhileTurnActive, rollbackLoadedThread(allocator, &thread, 1));
}

fn trimTranscriptHistoryFrom(allocator: std.mem.Allocator, transcript: *session_mod.Transcript, cut_index: usize) void {
    for (transcript.history.items[cut_index..]) |item| item.deinit(allocator);
    transcript.history.shrinkRetainingCapacity(cut_index);
}

fn refreshLoadedThreadAfterRollback(allocator: std.mem.Allocator, thread: *LoadedThread) !void {
    const preview = try resumePreview(allocator, &thread.transcript);
    defer allocator.free(preview);
    try replaceOwnedString(allocator, &thread.preview, preview);

    const turns_json = try renderTranscriptTurnsJson(allocator, &thread.transcript, true);
    errdefer allocator.free(turns_json);
    allocator.free(thread.turns_json);
    thread.turns_json = turns_json;

    try syncLoadedThreadTokenUsage(allocator, thread);
    syncLoadedThreadNextTurnIndex(thread);
    thread.updated_at = currentUnixSeconds();
}

fn syncLoadedThreadTokenUsage(allocator: std.mem.Allocator, thread: *LoadedThread) !void {
    thread.token_usage = thread.transcript.token_usage;
    if (thread.token_usage_turn_id) |turn_id| allocator.free(turn_id);
    thread.token_usage_turn_id = null;
    thread.token_usage_turn_id = try transcriptTokenUsageTurnId(allocator, &thread.transcript);
}

fn setLoadedThreadName(allocator: std.mem.Allocator, thread: *LoadedThread, name: []const u8) !void {
    const owned_name = try allocator.dupe(u8, name);
    var owned_name_moved = false;
    errdefer if (!owned_name_moved) allocator.free(owned_name);

    try thread.transcript.setTitle(allocator, name);
    if (thread.name) |existing| allocator.free(existing);
    thread.name = owned_name;
    owned_name_moved = true;
    thread.updated_at = currentUnixSeconds();
    if (thread.path) |path| try session_store.saveTranscript(allocator, path, &thread.transcript);
}

fn setLoadedThreadMemoryMode(allocator: std.mem.Allocator, thread: *LoadedThread, mode: []const u8) !void {
    try thread.transcript.setMemoryMode(allocator, mode);
    thread.updated_at = currentUnixSeconds();
    if (thread.path) |path| try session_store.saveTranscript(allocator, path, &thread.transcript);
}

fn setLoadedThreadPath(allocator: std.mem.Allocator, thread: *LoadedThread, path: []const u8) !void {
    const owned_path = try allocator.dupe(u8, path);
    errdefer allocator.free(owned_path);
    if (thread.path) |existing| allocator.free(existing);
    thread.path = owned_path;
    thread.updated_at = currentUnixSeconds();
}

fn setLoadedThreadGoal(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    object: std.json.ObjectMap,
) !bool {
    const now = currentUnixSeconds();
    const objective = loadedThreadGoalObjective(object);
    const status = loadedThreadGoalStatus(object);
    const token_budget = loadedThreadGoalTokenBudget(object);

    if (objective) |value| {
        if (thread.goal != null) _ = refreshLoadedThreadGoalAccountingAt(thread, now);
        if (thread.goal) |*existing| {
            if (std.mem.eql(u8, existing.objective, value) and !std.mem.eql(u8, existing.status, "complete")) {
                const requested_status = status orelse "active";
                const next_status = loadedThreadGoalUpdatedStatus(existing.status, requested_status, existing.tokens_used, if (token_budget.present) token_budget.value else existing.token_budget);
                const was_active = std.mem.eql(u8, existing.status, "active");
                if (!std.mem.eql(u8, existing.status, next_status)) {
                    const status_copy = try allocator.dupe(u8, next_status);
                    allocator.free(existing.status);
                    existing.status = status_copy;
                    if (!was_active and std.mem.eql(u8, existing.status, "active")) {
                        resetLoadedThreadGoalAccountingBaselines(existing, thread, now);
                    }
                }
                if (token_budget.present) existing.token_budget = token_budget.value;
                existing.updated_at = now;
                thread.updated_at = now;
                try persistLoadedThreadGoal(allocator, thread);
                return false;
            }
            existing.deinit(allocator);
            thread.goal = null;
        }

        const objective_copy = try allocator.dupe(u8, value);
        var objective_copy_moved = false;
        errdefer if (!objective_copy_moved) allocator.free(objective_copy);
        const status_copy = try allocator.dupe(u8, loadedThreadGoalStatusAfterBudgetLimit(status orelse "active", 0, if (token_budget.present) token_budget.value else null));
        var status_copy_moved = false;
        errdefer if (!status_copy_moved) allocator.free(status_copy);

        thread.goal = .{
            .objective = objective_copy,
            .status = status_copy,
            .token_budget = if (token_budget.present) token_budget.value else null,
            .tokens_used = 0,
            .time_used_seconds = 0,
            .created_at = now,
            .updated_at = now,
            .token_usage_start_total = loadedThreadGoalUsageTokens(thread),
            .time_usage_start_seconds = 0,
            .time_usage_start_at = now,
        };
        objective_copy_moved = true;
        status_copy_moved = true;
        thread.updated_at = now;
        try persistLoadedThreadGoal(allocator, thread);
        return true;
    }

    _ = refreshLoadedThreadGoalAccountingAt(thread, now);
    const existing = if (thread.goal) |*goal| goal else return error.MissingThreadGoal;
    if (status != null or token_budget.present) {
        const was_active = std.mem.eql(u8, existing.status, "active");
        const next_status = loadedThreadGoalUpdatedStatus(existing.status, status, existing.tokens_used, if (token_budget.present) token_budget.value else existing.token_budget);
        if (!std.mem.eql(u8, existing.status, next_status)) {
            const status_copy = try allocator.dupe(u8, next_status);
            allocator.free(existing.status);
            existing.status = status_copy;
            if (!was_active and std.mem.eql(u8, existing.status, "active")) {
                resetLoadedThreadGoalAccountingBaselines(existing, thread, now);
            }
        }
    }
    if (token_budget.present) existing.token_budget = token_budget.value;
    existing.updated_at = now;
    thread.updated_at = now;
    try persistLoadedThreadGoal(allocator, thread);
    return false;
}

fn loadedThreadGoalObjective(object: std.json.ObjectMap) ?[]const u8 {
    const value = object.get("objective") orelse return null;
    if (value == .null) return null;
    return std.mem.trim(u8, value.string, " \t\r\n");
}

fn loadedThreadGoalStatus(object: std.json.ObjectMap) ?[]const u8 {
    const value = object.get("status") orelse return null;
    if (value == .null) return null;
    return value.string;
}

const LoadedThreadGoalTokenBudget = struct {
    present: bool,
    value: ?i64,
};

fn loadedThreadGoalTokenBudget(object: std.json.ObjectMap) LoadedThreadGoalTokenBudget {
    const value = object.get("tokenBudget") orelse object.get("token_budget") orelse return .{ .present = false, .value = null };
    if (value == .null) return .{ .present = true, .value = null };
    return .{ .present = true, .value = value.integer };
}

fn loadedThreadGoalStatusAfterBudgetLimit(status: []const u8, tokens_used: i64, token_budget: ?i64) []const u8 {
    if (std.mem.eql(u8, status, "active")) {
        if (token_budget) |budget| {
            if (tokens_used >= budget) return "budgetLimited";
        }
    }
    return status;
}

fn loadedThreadGoalUpdatedStatus(existing_status: []const u8, status: ?[]const u8, tokens_used: i64, token_budget: ?i64) []const u8 {
    if (status) |requested_status| {
        if (std.mem.eql(u8, existing_status, "budgetLimited") and budgetLimitedPreservesStatus(requested_status)) {
            return "budgetLimited";
        }
        return loadedThreadGoalStatusAfterBudgetLimit(requested_status, tokens_used, token_budget);
    }
    return loadedThreadGoalStatusAfterBudgetLimit(existing_status, tokens_used, token_budget);
}

fn budgetLimitedPreservesStatus(requested_status: []const u8) bool {
    return std.mem.eql(u8, requested_status, "paused") or std.mem.eql(u8, requested_status, "blocked");
}

fn clearLoadedThreadGoal(allocator: std.mem.Allocator, thread: *LoadedThread) !bool {
    const had_goal = thread.goal != null or thread.transcript.goal != null;
    if (!had_goal) return false;
    if (thread.goal) |*goal| {
        goal.deinit(allocator);
    }
    thread.goal = null;
    thread.transcript.clearGoal(allocator);
    thread.updated_at = currentUnixSeconds();
    if (thread.path) |path| try session_store.saveTranscript(allocator, path, &thread.transcript);
    return true;
}

fn refreshLoadedThreadGoalAccountingAt(thread: *LoadedThread, now: i64) bool {
    const goal = if (thread.goal) |*payload| payload else return false;
    if (accountLoadedThreadGoalAt(goal, loadedThreadGoalUsageTokens(thread), now)) {
        thread.updated_at = now;
        return true;
    }
    return false;
}

fn refreshLoadedThreadGoalAccountingAndPersistAt(allocator: std.mem.Allocator, thread: *LoadedThread, now: i64) !bool {
    if (!refreshLoadedThreadGoalAccountingAt(thread, now)) return false;
    try persistLoadedThreadGoal(allocator, thread);
    return true;
}

fn accountLoadedThreadGoalAt(goal: *LoadedThreadGoal, current_total_tokens: i64, now: i64) bool {
    if (!std.mem.eql(u8, goal.status, "active")) return false;
    var changed = false;
    const token_delta = current_total_tokens - goal.token_usage_start_total;
    const tokens_used = if (token_delta > 0) token_delta else 0;
    if (goal.tokens_used != tokens_used) {
        goal.tokens_used = tokens_used;
        changed = true;
    }
    const active_seconds = if (now > goal.time_usage_start_at) now - goal.time_usage_start_at else 0;
    const time_used_seconds = goal.time_usage_start_seconds + active_seconds;
    if (goal.time_used_seconds != time_used_seconds) {
        goal.time_used_seconds = time_used_seconds;
        changed = true;
    }
    if (changed) goal.updated_at = now;
    return changed;
}

fn resetLoadedThreadGoalAccountingBaselines(goal: *LoadedThreadGoal, thread: *const LoadedThread, now: i64) void {
    resetLoadedThreadGoalAccountingBaselinesAt(goal, loadedThreadGoalUsageTokens(thread), now);
}

fn resetLoadedThreadGoalAccountingBaselinesAt(goal: *LoadedThreadGoal, current_goal_usage_tokens: i64, now: i64) void {
    goal.token_usage_start_total = current_goal_usage_tokens - goal.tokens_used;
    goal.time_usage_start_seconds = goal.time_used_seconds;
    goal.time_usage_start_at = now;
}

fn loadedThreadGoalUsageTokens(thread: *const LoadedThread) i64 {
    if (thread.transcript.token_usage) |usage_info| return goalUsageTokensFromUsage(usage_info.total);
    if (thread.token_usage) |usage_info| return goalUsageTokensFromUsage(usage_info.total);
    return 0;
}

fn goalUsageTokensFromUsage(usage: session_mod.TokenUsage) i64 {
    const cached_input = if (usage.cached_input_tokens > 0) usage.cached_input_tokens else 0;
    const non_cached_input = if (usage.input_tokens > cached_input) usage.input_tokens - cached_input else 0;
    const output = if (usage.output_tokens > 0) usage.output_tokens else 0;
    return non_cached_input + output;
}

fn loadedThreadGoalStartTotalForSavedUsage(current_total_tokens: i64, tokens_used: i64) i64 {
    const normalized_tokens_used = if (tokens_used > 0) tokens_used else 0;
    return current_total_tokens - normalized_tokens_used;
}

fn persistLoadedThreadGoal(allocator: std.mem.Allocator, thread: *LoadedThread) !void {
    try syncLoadedThreadGoalToTranscript(allocator, thread);
    if (thread.path) |path| try session_store.saveTranscript(allocator, path, &thread.transcript);
}

fn syncLoadedThreadGoalToTranscript(allocator: std.mem.Allocator, thread: *LoadedThread) !void {
    const goal = thread.goal orelse {
        thread.transcript.clearGoal(allocator);
        return;
    };
    try thread.transcript.setGoal(allocator, .{
        .objective = goal.objective,
        .status = goal.status,
        .token_budget = goal.token_budget,
        .tokens_used = goal.tokens_used,
        .time_used_seconds = goal.time_used_seconds,
        .created_at = goal.created_at,
        .updated_at = goal.updated_at,
    });
}

fn saveLoadedThreadGoalToStateDb(allocator: std.mem.Allocator, sqlite_home: []const u8, thread: *const LoadedThread, replace_goal_id: bool) !bool {
    const goal = thread.goal orelse return false;
    return thread_state.saveThreadGoalSnapshot(allocator, sqlite_home, thread.id, .{
        .objective = goal.objective,
        .status = goal.status,
        .token_budget = goal.token_budget,
        .tokens_used = goal.tokens_used,
        .time_used_seconds = goal.time_used_seconds,
        .created_at = goal.created_at,
        .updated_at = goal.updated_at,
    }, replace_goal_id);
}

fn loadedThreadGoalFromSessionGoal(allocator: std.mem.Allocator, maybe_goal: ?session_mod.ThreadGoal) !?LoadedThreadGoal {
    const goal = maybe_goal orelse return null;
    const objective = try allocator.dupe(u8, goal.objective);
    errdefer allocator.free(objective);
    const status = try allocator.dupe(u8, goal.status);
    errdefer allocator.free(status);
    const now = currentUnixSeconds();
    return LoadedThreadGoal{
        .objective = objective,
        .status = status,
        .token_budget = goal.token_budget,
        .tokens_used = goal.tokens_used,
        .time_used_seconds = goal.time_used_seconds,
        .created_at = goal.created_at,
        .updated_at = goal.updated_at,
        .token_usage_start_total = 0,
        .time_usage_start_seconds = goal.time_used_seconds,
        .time_usage_start_at = loadedThreadGoalTimeUsageStartAtForSavedGoal(goal.status, goal.updated_at, now),
    };
}

fn loadedThreadGoalFromStateGoal(allocator: std.mem.Allocator, goal: thread_state.ThreadGoal) !LoadedThreadGoal {
    const objective = try allocator.dupe(u8, goal.objective);
    errdefer allocator.free(objective);
    const status = try allocator.dupe(u8, goal.status);
    errdefer allocator.free(status);
    const now = currentUnixSeconds();
    return .{
        .objective = objective,
        .status = status,
        .token_budget = goal.token_budget,
        .tokens_used = goal.tokens_used,
        .time_used_seconds = goal.time_used_seconds,
        .created_at = goal.created_at,
        .updated_at = goal.updated_at,
        .token_usage_start_total = 0,
        .time_usage_start_seconds = goal.time_used_seconds,
        .time_usage_start_at = now,
    };
}

fn applyStateThreadGoal(allocator: std.mem.Allocator, sqlite_home: []const u8, thread: *LoadedThread) !void {
    const state_goal = (try thread_state.findThreadGoalByThreadId(allocator, sqlite_home, thread.id)) orelse return;
    defer state_goal.deinit(allocator);

    var loaded_goal = try loadedThreadGoalFromStateGoal(allocator, state_goal);
    errdefer loaded_goal.deinit(allocator);
    const goal_usage_tokens = loadedThreadGoalUsageTokens(thread);
    loaded_goal.token_usage_start_total = loadedThreadGoalStartTotalForSavedUsage(goal_usage_tokens, loaded_goal.tokens_used);

    if (thread.goal) |*existing| existing.deinit(allocator);
    thread.goal = loaded_goal;
    try syncLoadedThreadGoalToTranscript(allocator, thread);
}

fn loadedThreadGoalTimeUsageStartAtForSavedGoal(status: []const u8, updated_at: i64, now: i64) i64 {
    return if (std.mem.eql(u8, status, "active")) updated_at else now;
}

fn updateLoadedThreadGitInfo(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    git_info: std.json.ObjectMap,
) !void {
    try patchLoadedThreadGitInfoField(allocator, git_info, "sha", &thread.git_sha);
    try patchLoadedThreadGitInfoField(allocator, git_info, "branch", &thread.git_branch);
    try patchLoadedThreadGitInfoField(allocator, git_info, "originUrl", &thread.git_origin_url);
    try syncLoadedThreadGitInfoToTranscript(allocator, thread);
    thread.updated_at = currentUnixSeconds();
    if (thread.path) |path| try session_store.saveTranscript(allocator, path, &thread.transcript);
}

fn syncLoadedThreadGitInfoToTranscript(allocator: std.mem.Allocator, thread: *LoadedThread) !void {
    if (thread.git_sha) |value|
        try thread.transcript.setGitSha(allocator, value)
    else
        thread.transcript.clearGitSha(allocator);
    if (thread.git_branch) |value|
        try thread.transcript.setGitBranch(allocator, value)
    else
        thread.transcript.clearGitBranch(allocator);
    if (thread.git_origin_url) |value|
        try thread.transcript.setGitOriginUrl(allocator, value)
    else
        thread.transcript.clearGitOriginUrl(allocator);
}

fn patchLoadedThreadGitInfoField(
    allocator: std.mem.Allocator,
    git_info: std.json.ObjectMap,
    field_name: []const u8,
    slot: *?[]const u8,
) !void {
    const value = git_info.get(field_name) orelse return;
    if (value == .null) {
        clearOptionalOwnedString(allocator, slot);
        return;
    }
    if (value != .string) return error.InvalidThreadMetadataGitInfo;
    const normalized = std.mem.trim(u8, value.string, " \t\r\n");
    if (normalized.len == 0) return error.InvalidThreadMetadataGitInfo;
    try replaceOptionalOwnedString(allocator, slot, normalized);
}

fn replaceOptionalOwnedString(
    allocator: std.mem.Allocator,
    slot: *?[]const u8,
    value: []const u8,
) !void {
    const owned = try allocator.dupe(u8, value);
    clearOptionalOwnedString(allocator, slot);
    slot.* = owned;
}

fn clearOptionalOwnedString(allocator: std.mem.Allocator, slot: *?[]const u8) void {
    if (slot.*) |existing| allocator.free(existing);
    slot.* = null;
}

fn appendInjectedResponseItem(
    allocator: std.mem.Allocator,
    transcript: *session_mod.Transcript,
    item: std.json.Value,
) !void {
    const before_len = transcript.history.items.len;
    try session_mod.appendResponseHistoryItem(allocator, transcript, item);
    if (transcript.history.items.len == before_len and !isSkippableInjectedResponseItem(item)) return error.UnsupportedInjectedItem;
}

fn isSkippableInjectedResponseItem(item: std.json.Value) bool {
    if (item != .object) return false;
    const object = item.object;
    const type_value = object.get("type") orelse return false;
    if (type_value != .string) return false;
    const is_tool_search = std.mem.eql(u8, type_value.string, "tool_search_call") or
        std.mem.eql(u8, type_value.string, "tool_search_output");
    if (!is_tool_search) return false;
    const execution = object.get("execution") orelse return false;
    if (execution != .string or !std.mem.eql(u8, execution.string, "server")) return false;
    const call_id = object.get("call_id") orelse object.get("callId") orelse return false;
    return call_id == .null;
}

fn parseInjectedResponseItems(
    allocator: std.mem.Allocator,
    items: []const std.json.Value,
) !session_mod.Transcript {
    var transcript = session_mod.Transcript{};
    errdefer transcript.deinit(allocator);
    for (items) |item| try appendInjectedResponseItem(allocator, &transcript, item);
    return transcript;
}

fn injectLoadedThreadItems(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    items: []const std.json.Value,
) !void {
    if (items.len == 0) return;

    var injected = try parseInjectedResponseItems(allocator, items);
    defer injected.deinit(allocator);
    for (injected.history.items) |item| try thread.transcript.appendHistoryItem(allocator, item);

    const turns_json = try renderTranscriptTurnsJson(allocator, &thread.transcript, true);
    errdefer allocator.free(turns_json);
    allocator.free(thread.turns_json);
    thread.turns_json = turns_json;
    syncLoadedThreadNextTurnIndex(thread);
    thread.updated_at = currentUnixSeconds();
    if (thread.path) |path| try session_store.saveTranscript(allocator, path, &thread.transcript);
}

fn handleLoadedThreadCompactStart(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    thread_index: usize,
) ![]const u8 {
    const thread = &state.loaded_threads.items[thread_index];
    var cfg = loadConfigForLoadedThread(allocator, state, thread) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/compact/start failed to load config", err);
    };
    defer cfg.deinit(allocator);

    const project_cwd = try allocator.dupe(u8, thread.cwd);
    defer allocator.free(project_cwd);

    applyProjectLayersToConfigForCwd(allocator, &cfg, project_cwd) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/compact/start failed to load project config", err);
    };

    var empty_params = try std.json.parseFromSlice(std.json.Value, allocator, "{}", .{});
    defer empty_params.deinit();
    applyTurnStartRuntimeOverrides(allocator, &cfg, thread, empty_params.value.object, false) catch |err| switch (err) {
        error.InvalidTurnContextOverride => return renderJsonRpcError(allocator, id_value, -32602, "invalid compact thread runtime config"),
        else => return err,
    };

    var credentials = loadCredentialsForLoadedThread(allocator, &cfg, thread) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/compact/start failed to load auth", err);
    };
    defer credentials.deinit(allocator);

    const turn_id = try allocateNextTurnIdForThread(allocator, thread);
    defer allocator.free(turn_id);
    const item_id = try std.fmt.allocPrint(allocator, "item-{d}", .{thread.transcript.history.items.len});
    defer allocator.free(item_id);

    var effective_writable_roots = try loadedThreadEffectiveWritableRoots(allocator, thread);
    defer effective_writable_roots.deinit(allocator);

    const started_at_ms = currentUnixMilliseconds();
    const started_at = @divTrunc(started_at_ms, std.time.ms_per_s);
    const started_notification = try renderTurnNotification(allocator, "turn/started", thread.id, turn_id, "inProgress", started_at, null);
    var started_notification_moved = false;
    errdefer if (!started_notification_moved) allocator.free(started_notification);

    const compact_prompt = appServerCompactPromptForConfig(cfg);
    const answer = session_mod.runTurnWithOptions(allocator, cfg, &credentials, &thread.transcript, compact_prompt, .{
        .prompt_for_approval = false,
        .additional_writable_roots = effective_writable_roots.items,
        .read_denied_roots = thread.sandbox_read_denied_roots.items,
        .read_denied_globs = thread.sandbox_read_denied_globs.items,
        .include_cwd_write_root = thread.sandbox_include_cwd_write_root,
        .network_enabled = thread.sandbox_network_enabled,
        .include_tools = false,
        .workdir = thread.cwd,
    }) catch |err| {
        const error_message = try std.fmt.allocPrint(allocator, "thread/compact/start failed to run compaction: {s}", .{@errorName(err)});
        defer allocator.free(error_message);
        thread.status = .system_error;
        try refreshLoadedThreadAfterTurn(allocator, thread, compact_prompt);
        if (thread.path) |path| {
            try session_store.saveTranscript(allocator, path, &thread.transcript);
        }
        try queueErrorNotification(allocator, state, thread.id, turn_id, error_message, false);
        try queueThreadStatusChangedNotification(allocator, state, thread.id, .system_error);
        return renderJsonRpcError(allocator, id_value, -32603, error_message);
    };
    defer allocator.free(answer);

    const trimmed = std.mem.trim(u8, answer, " \t\r\n");
    if (trimmed.len == 0) {
        const error_message = "thread/compact/start failed to produce a compaction summary";
        thread.status = .system_error;
        try refreshLoadedThreadAfterTurn(allocator, thread, compact_prompt);
        if (thread.path) |path| {
            try session_store.saveTranscript(allocator, path, &thread.transcript);
        }
        try queueErrorNotification(allocator, state, thread.id, turn_id, error_message, false);
        try queueThreadStatusChangedNotification(allocator, state, thread.id, .system_error);
        return renderJsonRpcError(allocator, id_value, -32603, error_message);
    }
    const compacted = try std.fmt.allocPrint(
        allocator,
        "Compacted conversation summary:\n\n{s}",
        .{trimmed},
    );
    defer allocator.free(compacted);

    try thread.transcript.replaceWithCompactedSummary(allocator, compacted);
    try refreshLoadedThreadAfterRollback(allocator, thread);
    const completed_at_ms = currentUnixMilliseconds();
    const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
    const goal_accounting_changed = refreshLoadedThreadGoalAccountingAt(thread, completed_at);
    if (goal_accounting_changed) {
        try syncLoadedThreadGoalToTranscript(allocator, thread);
        _ = try saveLoadedThreadGoalToStateDb(allocator, configSqliteHome(cfg), thread, false);
    }
    if (thread.path) |path| {
        try session_store.saveTranscript(allocator, path, &thread.transcript);
    }

    const completed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "completed", started_at, completed_at);
    var completed_notification_moved = false;
    errdefer if (!completed_notification_moved) allocator.free(completed_notification);

    thread.status = .active;
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .active);
    try queueTurnNotification(allocator, state, "turn/started", started_notification);
    started_notification_moved = true;
    try queueContextCompactionItemNotification(allocator, state, "item/started", thread.id, turn_id, item_id, "startedAtMs", started_at_ms);
    try queueContextCompactionItemNotification(allocator, state, "item/completed", thread.id, turn_id, item_id, "completedAtMs", completed_at_ms);
    if (goal_accounting_changed) try queueThreadGoalUpdatedNotificationForTurn(allocator, state, thread, turn_id);
    try queueContextCompactedNotification(allocator, state, thread.id, turn_id);
    try queueTurnNotification(allocator, state, "turn/completed", completed_notification);
    completed_notification_moved = true;
    thread.status = .idle;
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .idle);

    return renderJsonRpcResult(allocator, id_value, "{}");
}

fn appServerCompactPromptForConfig(cfg: config.Config) []const u8 {
    if (cfg.compact_prompt) |prompt| {
        if (std.mem.trim(u8, prompt, " \t\r\n").len > 0) return prompt;
    }
    return APP_SERVER_COMPACT_PROMPT;
}

fn handleLoadedThreadShellCommand(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    thread_index: usize,
    command_raw: []const u8,
) ![]const u8 {
    const command = std.mem.trim(u8, command_raw, " \t\r\n");
    const thread = &state.loaded_threads.items[thread_index];
    const turn_id = try allocateNextTurnIdForThread(allocator, thread);
    defer allocator.free(turn_id);

    const started_at_ms = currentUnixMilliseconds();
    const started_at = @divTrunc(started_at_ms, std.time.ms_per_s);
    const started_notification = try renderTurnNotification(allocator, "turn/started", thread.id, turn_id, "inProgress", started_at, null);
    var started_notification_moved = false;
    errdefer if (!started_notification_moved) allocator.free(started_notification);

    thread.status = .active;
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .active);
    try queueTurnNotification(allocator, state, "turn/started", started_notification);
    started_notification_moved = true;

    var io_instance: std.Io.Threaded = .init(allocator, .{});
    defer io_instance.deinit();
    const shell = currentUserShell();
    const argv = [_][]const u8{ shell, "-lc", command };
    const command_started_at_ms = currentUnixMilliseconds();
    var result = runCommandExecProcess(
        allocator,
        &io_instance,
        &argv,
        .{ .path = thread.cwd },
        null,
        null,
        60 * 60 * 1000,
        COMMAND_EXEC_DEFAULT_OUTPUT_BYTES_CAP,
    ) catch |err| {
        thread.status = .system_error;
        try queueThreadStatusChangedNotification(allocator, state, thread.id, .system_error);
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/shellCommand failed", err);
    };
    defer result.deinit(allocator);
    const command_completed_at_ms = currentUnixMilliseconds();
    const duration_ms = @max(command_completed_at_ms - command_started_at_ms, 0);

    const aggregated_output = try commandExecAggregatedOutput(allocator, result.stdout, result.stderr);
    defer allocator.free(aggregated_output);
    const record = try renderUserShellCommandRecord(
        allocator,
        command,
        result.exit_code,
        duration_ms,
        aggregated_output,
    );
    defer allocator.free(record);

    const item_index = thread.transcript.history.items.len;
    try thread.transcript.appendUserMessage(allocator, record);
    try refreshLoadedThreadAfterTurn(allocator, thread, record);
    if (thread.path) |path| {
        try session_store.saveTranscript(allocator, path, &thread.transcript);
    }

    const completed_at_ms = currentUnixMilliseconds();
    const completed_at = @divTrunc(completed_at_ms, std.time.ms_per_s);
    const completed_notification = try renderTurnNotification(allocator, "turn/completed", thread.id, turn_id, "completed", started_at, completed_at);
    var completed_notification_moved = false;
    errdefer if (!completed_notification_moved) allocator.free(completed_notification);

    const user_content_json = try renderSingleTextUserContentJson(allocator, record);
    defer allocator.free(user_content_json);
    try queueUserMessageItemNotification(allocator, state, "item/started", thread.id, turn_id, item_index, user_content_json, "startedAtMs", started_at_ms);
    try queueUserMessageItemNotification(allocator, state, "item/completed", thread.id, turn_id, item_index, user_content_json, "completedAtMs", completed_at_ms);
    try queueTurnNotification(allocator, state, "turn/completed", completed_notification);
    completed_notification_moved = true;
    thread.status = .idle;
    try queueThreadStatusChangedNotification(allocator, state, thread.id, .idle);

    return renderJsonRpcResult(allocator, id_value, "{}");
}

fn commandExecAggregatedOutput(allocator: std.mem.Allocator, stdout: []const u8, stderr: []const u8) ![]const u8 {
    if (stdout.len == 0) return allocator.dupe(u8, stderr);
    if (stderr.len == 0) return allocator.dupe(u8, stdout);
    const separator = if (stdout[stdout.len - 1] == '\n') "" else "\n";
    return std.fmt.allocPrint(allocator, "{s}{s}{s}", .{ stdout, separator, stderr });
}

fn renderUserShellCommandRecord(
    allocator: std.mem.Allocator,
    command: []const u8,
    exit_code: i32,
    duration_ms: i64,
    output: []const u8,
) ![]const u8 {
    const seconds = @divTrunc(duration_ms, std.time.ms_per_s);
    const fractional = @mod(duration_ms, std.time.ms_per_s) * 10;
    return std.fmt.allocPrint(
        allocator,
        "<user_shell_command>\n<command>\n{s}\n</command>\n<result>\nExit code: {d}\nDuration: {d}.{d:0>4} seconds\nOutput:\n{s}\n</result>\n</user_shell_command>",
        .{ command, exit_code, seconds, fractional, output },
    );
}

fn renderSingleTextUserContentJson(allocator: std.mem.Allocator, text: []const u8) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "[{\"type\":\"text\",\"text\":");
    try appendJsonString(allocator, &out, text);
    try out.appendSlice(allocator, ",\"text_elements\":[]}]");
    return out.toOwnedSlice(allocator);
}

fn currentUserShell() []const u8 {
    const raw = std.c.getenv("SHELL") orelse return "/bin/zsh";
    const shell = std.mem.span(raw);
    if (shell.len == 0 or !std.fs.path.isAbsolute(shell)) return "/bin/zsh";
    return shell;
}

fn currentHookShell() []const u8 {
    const raw = std.c.getenv("SHELL") orelse return "/bin/sh";
    const shell = std.mem.span(raw);
    if (shell.len == 0 or !std.fs.path.isAbsolute(shell)) return "/bin/sh";
    return shell;
}

