const PatchNotificationKind = enum {
    add,
    delete,
    update,
};

const PatchNotificationChange = struct {
    path: []const u8,
    kind: PatchNotificationKind,
    diff: []const u8,
    move_path: ?[]const u8 = null,

    fn deinit(self: PatchNotificationChange, allocator: std.mem.Allocator) void {
        allocator.free(self.diff);
    }
};

fn renderFileChangePatchUpdatedNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    turn_id: []const u8,
    item_id: []const u8,
    patch_text: []const u8,
) ![]const u8 {
    var changes = try parsePatchNotificationChanges(allocator, patch_text);
    defer {
        for (changes.items) |change| change.deinit(allocator);
        changes.deinit(allocator);
    }
    if (changes.items.len == 0) return error.InvalidPatch;
    std.mem.sort(PatchNotificationChange, changes.items, {}, patchNotificationChangeLessThan);

    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"item/fileChange/patchUpdated\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &notification, turn_id);
    try notification.appendSlice(allocator, ",\"itemId\":");
    try appendJsonString(allocator, &notification, item_id);
    try notification.appendSlice(allocator, ",\"changes\":[");
    for (changes.items, 0..) |change, index| {
        if (index > 0) try notification.append(allocator, ',');
        try appendPatchNotificationChangeJson(allocator, &notification, change);
    }
    try notification.appendSlice(allocator, "]}}");
    return notification.toOwnedSlice(allocator);
}

fn parsePatchNotificationChanges(allocator: std.mem.Allocator, patch_text: []const u8) !std.ArrayList(PatchNotificationChange) {
    var changes = std.ArrayList(PatchNotificationChange).empty;
    errdefer {
        for (changes.items) |change| change.deinit(allocator);
        changes.deinit(allocator);
    }

    var lines = std.ArrayList([]const u8).empty;
    defer lines.deinit(allocator);
    var raw_lines = std.mem.splitScalar(u8, normalizeNotificationPatchText(patch_text), '\n');
    while (raw_lines.next()) |raw_line| {
        try lines.append(allocator, std.mem.trimEnd(u8, raw_line, "\r"));
    }

    var index: usize = 0;
    while (index < lines.items.len) {
        const line = notificationPatchDirective(lines.items[index]);
        if (std.mem.startsWith(u8, line, "*** Add File: ")) {
            const path = line["*** Add File: ".len..];
            index += 1;
            const diff = try collectAddPatchNotificationDiff(allocator, lines.items, &index);
            errdefer allocator.free(diff);
            try changes.append(allocator, .{ .path = path, .kind = .add, .diff = diff });
            continue;
        }
        if (std.mem.startsWith(u8, line, "*** Update File: ")) {
            const path = line["*** Update File: ".len..];
            index += 1;
            var move_path: ?[]const u8 = null;
            if (index < lines.items.len) {
                const maybe_move = notificationPatchDirective(lines.items[index]);
                if (std.mem.startsWith(u8, maybe_move, "*** Move to: ")) {
                    move_path = maybe_move["*** Move to: ".len..];
                    index += 1;
                }
            }
            const diff = try collectRawPatchNotificationDiff(allocator, lines.items, &index);
            errdefer allocator.free(diff);
            try changes.append(allocator, .{ .path = path, .kind = .update, .diff = diff, .move_path = move_path });
            continue;
        }
        if (std.mem.startsWith(u8, line, "*** Delete File: ")) {
            const path = line["*** Delete File: ".len..];
            index += 1;
            const diff = try allocator.dupe(u8, "");
            errdefer allocator.free(diff);
            try changes.append(allocator, .{ .path = path, .kind = .delete, .diff = diff });
            continue;
        }
        index += 1;
    }

    return changes;
}

fn collectAddPatchNotificationDiff(allocator: std.mem.Allocator, lines: []const []const u8, index: *usize) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    while (index.* < lines.len and !isNotificationPatchSection(lines[index.*])) : (index.* += 1) {
        const line = lines[index.*];
        if (line.len > 0 and line[0] == '+') {
            try out.appendSlice(allocator, line[1..]);
        } else {
            try out.appendSlice(allocator, line);
        }
        try out.append(allocator, '\n');
    }
    return out.toOwnedSlice(allocator);
}

fn collectRawPatchNotificationDiff(allocator: std.mem.Allocator, lines: []const []const u8, index: *usize) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    while (index.* < lines.len and !isNotificationPatchSection(lines[index.*])) : (index.* += 1) {
        try out.appendSlice(allocator, lines[index.*]);
        try out.append(allocator, '\n');
    }
    return out.toOwnedSlice(allocator);
}

fn appendPatchNotificationChangeJson(allocator: std.mem.Allocator, out: *std.ArrayList(u8), change: PatchNotificationChange) !void {
    try out.appendSlice(allocator, "{\"path\":");
    try appendJsonString(allocator, out, change.path);
    try out.appendSlice(allocator, ",\"kind\":");
    try appendPatchNotificationKindJson(allocator, out, change);
    try out.appendSlice(allocator, ",\"diff\":");
    try appendJsonString(allocator, out, change.diff);
    try out.append(allocator, '}');
}

fn appendPatchNotificationKindJson(allocator: std.mem.Allocator, out: *std.ArrayList(u8), change: PatchNotificationChange) !void {
    switch (change.kind) {
        .add => try out.appendSlice(allocator, "{\"type\":\"add\"}"),
        .delete => try out.appendSlice(allocator, "{\"type\":\"delete\"}"),
        .update => {
            try out.appendSlice(allocator, "{\"type\":\"update\",\"move_path\":");
            try appendOptionalJsonString(allocator, out, change.move_path);
            try out.append(allocator, '}');
        },
    }
}

fn normalizeNotificationPatchText(patch_text: []const u8) []const u8 {
    const trimmed = std.mem.trim(u8, patch_text, " \t\r\n");
    const first_newline = std.mem.indexOfScalar(u8, trimmed, '\n') orelse return trimmed;
    const last_newline = std.mem.lastIndexOfScalar(u8, trimmed, '\n') orelse return trimmed;
    if (first_newline >= last_newline) return trimmed;

    const first_line = std.mem.trimEnd(u8, trimmed[0..first_newline], "\r");
    if (!std.mem.eql(u8, first_line, "<<EOF") and
        !std.mem.eql(u8, first_line, "<<'EOF'") and
        !std.mem.eql(u8, first_line, "<<\"EOF\""))
        return trimmed;

    const last_line = std.mem.trimEnd(u8, trimmed[last_newline + 1 ..], "\r");
    if (!std.mem.endsWith(u8, last_line, "EOF")) return trimmed;
    return std.mem.trim(u8, trimmed[first_newline + 1 .. last_newline], " \t\r\n");
}

fn notificationPatchDirective(line: []const u8) []const u8 {
    return std.mem.trim(u8, line, " \t");
}

fn isNotificationPatchSection(line: []const u8) bool {
    const directive = notificationPatchDirective(line);
    return std.mem.eql(u8, directive, "*** End Patch") or
        std.mem.startsWith(u8, directive, "*** Add File: ") or
        std.mem.startsWith(u8, directive, "*** Update File: ") or
        std.mem.startsWith(u8, directive, "*** Delete File: ");
}

fn patchNotificationChangeLessThan(_: void, lhs: PatchNotificationChange, rhs: PatchNotificationChange) bool {
    return std.mem.lessThan(u8, lhs.path, rhs.path);
}

fn renderRawResponseItemCompletedNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    turn_id: []const u8,
    item_json: []const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"rawResponseItem/completed\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &notification, turn_id);
    try notification.appendSlice(allocator, ",\"item\":");
    try notification.appendSlice(allocator, item_json);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

fn appendWebSearchItemNotifications(context: *RawResponseItemNotificationContext, item_json: []const u8) !void {
    if (!context.item_started_enabled and !context.item_completed_enabled) return;

    var parsed = std.json.parseFromSlice(std.json.Value, context.allocator, item_json, .{}) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return,
    };
    defer parsed.deinit();
    if (parsed.value != .object) return;
    const item = parsed.value.object;
    const type_value = item.get("type") orelse return;
    if (type_value != .string or !std.mem.eql(u8, type_value.string, "web_search_call")) return;

    const action_value = webSearchActionValue(item);
    const query = try webSearchActionDetail(context.allocator, action_value);
    defer context.allocator.free(query);
    const item_id = webSearchItemId(item);

    if (context.item_started_enabled) {
        const started = try renderWebSearchItemNotification(context.allocator, "item/started", context.thread_id, context.turn_id, item_id, query, action_value, "startedAtMs", currentUnixMilliseconds());
        var started_moved = false;
        errdefer if (!started_moved) context.allocator.free(started);
        try context.notifications.append(context.allocator, started);
        started_moved = true;
    }
    if (context.item_completed_enabled) {
        const completed = try renderWebSearchItemNotification(context.allocator, "item/completed", context.thread_id, context.turn_id, item_id, query, action_value, "completedAtMs", currentUnixMilliseconds());
        var completed_moved = false;
        errdefer if (!completed_moved) context.allocator.free(completed);
        try context.notifications.append(context.allocator, completed);
        completed_moved = true;
    }
}

fn webSearchItemId(item: std.json.ObjectMap) []const u8 {
    const id_value = item.get("id") orelse return "";
    if (id_value != .string) return "";
    return id_value.string;
}

fn webSearchActionValue(item: std.json.ObjectMap) ?std.json.Value {
    const action_value = item.get("action") orelse return null;
    if (action_value != .object) return null;
    return action_value;
}

fn webSearchActionDetail(allocator: std.mem.Allocator, action_value: ?std.json.Value) ![]const u8 {
    const action = action_value orelse return allocator.dupe(u8, "");
    if (action != .object) return allocator.dupe(u8, "");
    const type_value = action.object.get("type") orelse return allocator.dupe(u8, "");
    if (type_value != .string) return allocator.dupe(u8, "");

    if (std.mem.eql(u8, type_value.string, "search")) {
        if (webSearchStringField(action.object, "query")) |query| {
            if (query.len > 0) return allocator.dupe(u8, query);
        }
        return webSearchQueriesDetail(allocator, action.object.get("queries"));
    }
    if (std.mem.eql(u8, type_value.string, "open_page")) {
        return allocator.dupe(u8, webSearchStringField(action.object, "url") orelse "");
    }
    if (std.mem.eql(u8, type_value.string, "find_in_page")) {
        const pattern = webSearchStringField(action.object, "pattern");
        const url = webSearchStringField(action.object, "url");
        if (pattern) |pattern_value| {
            if (url) |url_value| return std.fmt.allocPrint(allocator, "'{s}' in {s}", .{ pattern_value, url_value });
            return std.fmt.allocPrint(allocator, "'{s}'", .{pattern_value});
        }
        return allocator.dupe(u8, url orelse "");
    }
    return allocator.dupe(u8, "");
}

fn webSearchQueriesDetail(allocator: std.mem.Allocator, queries_value: ?std.json.Value) ![]const u8 {
    const queries = queries_value orelse return allocator.dupe(u8, "");
    if (queries != .array or queries.array.items.len == 0) return allocator.dupe(u8, "");
    const first = queries.array.items[0];
    if (first != .string) return allocator.dupe(u8, "");
    if (queries.array.items.len > 1 and first.string.len > 0) {
        return std.fmt.allocPrint(allocator, "{s} ...", .{first.string});
    }
    return allocator.dupe(u8, first.string);
}

fn webSearchStringField(object: std.json.ObjectMap, name: []const u8) ?[]const u8 {
    const value = object.get(name) orelse return null;
    if (value != .string) return null;
    return value.string;
}

fn renderWebSearchItemNotification(
    allocator: std.mem.Allocator,
    method: []const u8,
    thread_id: []const u8,
    turn_id: []const u8,
    item_id: []const u8,
    query: []const u8,
    action_value: ?std.json.Value,
    timestamp_field: []const u8,
    timestamp_ms: i64,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":");
    try appendJsonString(allocator, &notification, method);
    try notification.appendSlice(allocator, ",\"params\":{\"item\":{\"type\":\"webSearch\",\"id\":");
    try appendJsonString(allocator, &notification, item_id);
    try notification.appendSlice(allocator, ",\"query\":");
    try appendJsonString(allocator, &notification, query);
    try notification.appendSlice(allocator, ",\"action\":");
    try appendWebSearchActionJson(allocator, &notification, action_value);
    try notification.appendSlice(allocator, "},\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &notification, turn_id);
    try notification.append(allocator, ',');
    try appendJsonString(allocator, &notification, timestamp_field);
    try notification.append(allocator, ':');
    try appendInt(allocator, &notification, timestamp_ms);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

fn appendWebSearchActionJson(allocator: std.mem.Allocator, result: *std.ArrayList(u8), action_value: ?std.json.Value) !void {
    const action = action_value orelse {
        try result.appendSlice(allocator, "{\"type\":\"other\"}");
        return;
    };
    if (action != .object) {
        try result.appendSlice(allocator, "{\"type\":\"other\"}");
        return;
    }
    const type_value = webSearchStringField(action.object, "type") orelse {
        try result.appendSlice(allocator, "{\"type\":\"other\"}");
        return;
    };

    if (std.mem.eql(u8, type_value, "search")) {
        try result.appendSlice(allocator, "{\"type\":\"search\",\"query\":");
        try appendJsonMaybeString(allocator, result, webSearchStringField(action.object, "query"));
        try result.appendSlice(allocator, ",\"queries\":");
        try appendWebSearchQueriesJson(allocator, result, action.object.get("queries"));
        try result.append(allocator, '}');
        return;
    }
    if (std.mem.eql(u8, type_value, "open_page")) {
        try result.appendSlice(allocator, "{\"type\":\"openPage\",\"url\":");
        try appendJsonMaybeString(allocator, result, webSearchStringField(action.object, "url"));
        try result.append(allocator, '}');
        return;
    }
    if (std.mem.eql(u8, type_value, "find_in_page")) {
        try result.appendSlice(allocator, "{\"type\":\"findInPage\",\"url\":");
        try appendJsonMaybeString(allocator, result, webSearchStringField(action.object, "url"));
        try result.appendSlice(allocator, ",\"pattern\":");
        try appendJsonMaybeString(allocator, result, webSearchStringField(action.object, "pattern"));
        try result.append(allocator, '}');
        return;
    }
    try result.appendSlice(allocator, "{\"type\":\"other\"}");
}

fn appendJsonMaybeString(allocator: std.mem.Allocator, result: *std.ArrayList(u8), value: ?[]const u8) !void {
    if (value) |string| {
        try appendJsonString(allocator, result, string);
    } else {
        try result.appendSlice(allocator, "null");
    }
}

fn appendWebSearchQueriesJson(allocator: std.mem.Allocator, result: *std.ArrayList(u8), queries_value: ?std.json.Value) !void {
    const queries = queries_value orelse {
        try result.appendSlice(allocator, "null");
        return;
    };
    if (queries != .array) {
        try result.appendSlice(allocator, "null");
        return;
    }
    const start_len = result.items.len;
    try result.append(allocator, '[');
    for (queries.array.items, 0..) |query, index| {
        if (query != .string) {
            result.items.len = start_len;
            try result.appendSlice(allocator, "null");
            return;
        }
        if (index > 0) try result.append(allocator, ',');
        try appendJsonString(allocator, result, query.string);
    }
    try result.append(allocator, ']');
}

fn renderReasoningEventNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    turn_id: []const u8,
    event: api.ReasoningEvent,
) ![]const u8 {
    return switch (event.kind) {
        .summary_text_delta => renderReasoningSummaryTextDeltaNotification(allocator, thread_id, turn_id, event.item_id, event.delta, event.index),
        .summary_part_added => renderReasoningSummaryPartAddedNotification(allocator, thread_id, turn_id, event.item_id, event.index),
        .text_delta => renderReasoningTextDeltaNotification(allocator, thread_id, turn_id, event.item_id, event.delta, event.index),
    };
}

fn renderMcpServerStatusUpdatedNotification(
    allocator: std.mem.Allocator,
    server_name: []const u8,
    status: mcp_runtime.StartupStatus,
    error_message: ?[]const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"mcpServer/startupStatus/updated\",\"params\":{\"name\":");
    try appendJsonString(allocator, &notification, server_name);
    try notification.appendSlice(allocator, ",\"status\":");
    try appendJsonString(allocator, &notification, status.label());
    try notification.appendSlice(allocator, ",\"error\":");
    try appendOptionalJsonString(allocator, &notification, error_message);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

fn queueInitialRemoteControlStatusNotification(allocator: std.mem.Allocator, state: *AppServerState) !void {
    const method = "remoteControl/status/changed";
    if (serverNotificationShouldBeDropped(state, method)) return;

    const status = if (state.remote_control_enabled) "connecting" else "disabled";
    var identity = try resolveRemoteControlIdentity(allocator);
    defer identity.deinit(allocator);
    const notification = try renderRemoteControlStatusChangedNotification(allocator, status, identity, null);
    var notification_moved = false;
    errdefer if (!notification_moved) allocator.free(notification);
    try queuePendingServerNotification(allocator, state, method, notification);
    notification_moved = true;
}

fn renderRemoteControlStatusChangedNotification(
    allocator: std.mem.Allocator,
    status: []const u8,
    identity: RemoteControlIdentity,
    environment_id: ?[]const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"remoteControl/status/changed\",\"params\":{\"status\":");
    try appendJsonString(allocator, &notification, status);
    try notification.appendSlice(allocator, ",\"serverName\":");
    try appendJsonString(allocator, &notification, identity.server_name);
    try notification.appendSlice(allocator, ",\"installationId\":");
    try appendJsonString(allocator, &notification, identity.installation_id);
    try notification.appendSlice(allocator, ",\"environmentId\":");
    try appendOptionalJsonString(allocator, &notification, environment_id);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

fn isRemoteControlMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "remoteControl/enable") or
        std.mem.eql(u8, method, "remoteControl/disable") or
        std.mem.eql(u8, method, "remoteControl/status/read") or
        std.mem.eql(u8, method, "remoteControl/pairing/start") or
        std.mem.eql(u8, method, "remoteControl/pairing/status") or
        std.mem.eql(u8, method, "remoteControl/client/list") or
        std.mem.eql(u8, method, "remoteControl/client/revoke");
}

fn handleRemoteControlMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "remoteControl/enable") or
        std.mem.eql(u8, method, "remoteControl/disable") or
        std.mem.eql(u8, method, "remoteControl/status/read"))
    {
        if (params_value) |params| {
            if (params != .null) {
                const message = try std.fmt.allocPrint(allocator, "{s} params must be null or omitted", .{method});
                defer allocator.free(message);
                return renderJsonRpcError(allocator, id_value, -32602, message);
            }
        }

        if (std.mem.eql(u8, method, "remoteControl/enable")) {
            const changed = !state.remote_control_enabled;
            state.remote_control_enabled = true;
            return handleRemoteControlStatusMutation(allocator, state, id_value, "connecting", changed);
        }
        if (std.mem.eql(u8, method, "remoteControl/disable")) {
            const changed = state.remote_control_enabled;
            state.remote_control_enabled = false;
            return handleRemoteControlStatusMutation(allocator, state, id_value, "disabled", changed);
        }
        const status = if (state.remote_control_enabled) "connecting" else "disabled";
        const result = try renderRemoteControlStatusObject(allocator, status, null);
        defer allocator.free(result);
        return try renderJsonRpcResult(allocator, id_value, result);
    }

    if (std.mem.eql(u8, method, "remoteControl/pairing/start")) {
        if (try validateRemoteControlPairingStartParams(allocator, params_value)) |message| {
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
        return renderJsonRpcError(allocator, id_value, -32600, remoteControlPairingUnavailableMessage(state));
    }
    if (std.mem.eql(u8, method, "remoteControl/pairing/status")) {
        if (try validateRemoteControlPairingStatusParams(allocator, params_value)) |message| {
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
        return renderJsonRpcError(allocator, id_value, -32600, remoteControlPairingUnavailableMessage(state));
    }
    if (std.mem.eql(u8, method, "remoteControl/client/list")) {
        if (try validateRemoteControlClientsListParams(allocator, params_value)) |message| {
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
        return renderJsonRpcError(allocator, id_value, -32600, "remote control requires ChatGPT authentication");
    }
    if (std.mem.eql(u8, method, "remoteControl/client/revoke")) {
        if (try validateRemoteControlClientsRevokeParams(allocator, params_value)) |message| {
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
        return renderJsonRpcError(allocator, id_value, -32600, "remote control requires ChatGPT authentication");
    }

    return renderJsonRpcError(allocator, id_value, -32601, "method not found");
}

fn remoteControlPairingUnavailableMessage(state: *const AppServerState) []const u8 {
    if (!state.remote_control_enabled) return "remote control pairing requires remote control to be enabled";
    return "remote control pairing is unavailable until enrollment completes";
}

fn validateRemoteControlPairingStartParams(allocator: std.mem.Allocator, params_value: ?std.json.Value) !?[]const u8 {
    const params = params_value orelse return try remoteControlMissingParamsMessage(allocator);
    if (params == .null) return try remoteControlMissingParamsMessage(allocator);
    if (params != .object) return try allocator.dupe(u8, "Invalid request: expected struct RemoteControlPairingStartParams");
    const object = params.object;
    if (object.get("manualCode")) |value| {
        if (value != .bool) return try remoteControlInvalidTypeMessage(allocator, value, "a boolean");
    }
    return null;
}

fn validateRemoteControlPairingStatusParams(allocator: std.mem.Allocator, params_value: ?std.json.Value) !?[]const u8 {
    const params = params_value orelse return try remoteControlMissingParamsMessage(allocator);
    if (params == .null) return try remoteControlMissingParamsMessage(allocator);
    if (params != .object) return try allocator.dupe(u8, "Invalid request: expected struct RemoteControlPairingStatusParams");
    const object = params.object;
    var has_code = false;
    if (object.get("pairingCode")) |value| {
        if (value != .null) {
            if (value != .string) return try remoteControlInvalidTypeMessage(allocator, value, "a string");
            has_code = true;
        }
    }
    if (object.get("manualPairingCode")) |value| {
        if (value != .null) {
            if (value != .string) return try remoteControlInvalidTypeMessage(allocator, value, "a string");
            has_code = true;
        }
    }
    if (!has_code) return try allocator.dupe(u8, "remoteControl/pairing/status requires pairingCode or manualPairingCode");
    return null;
}

fn validateRemoteControlClientsListParams(allocator: std.mem.Allocator, params_value: ?std.json.Value) !?[]const u8 {
    const params = params_value orelse return try remoteControlMissingParamsMessage(allocator);
    if (params == .null) return try remoteControlMissingParamsMessage(allocator);
    if (params != .object) return try allocator.dupe(u8, "Invalid request: expected struct RemoteControlClientsListParams");
    const object = params.object;
    if (try validateRemoteControlRequiredStringField(allocator, object, "environmentId")) |message| return message;
    if (try validateRemoteControlOptionalStringField(allocator, object, "cursor")) |message| return message;
    if (object.get("limit")) |value| {
        if (value != .null) {
            if (value != .integer) return try remoteControlInvalidTypeMessage(allocator, value, "u32");
            if (value.integer < 0 or value.integer > std.math.maxInt(u32)) return try remoteControlInvalidValueMessage(allocator, value, "u32");
        }
    }
    if (object.get("order")) |value| {
        if (value != .null) {
            if (value != .string) return try remoteControlInvalidTypeMessage(allocator, value, "`asc` or `desc`");
            if (!std.mem.eql(u8, value.string, "asc") and !std.mem.eql(u8, value.string, "desc")) {
                return try std.fmt.allocPrint(allocator, "Invalid request: unknown variant `{s}`, expected `asc` or `desc`", .{value.string});
            }
        }
    }
    return null;
}

fn validateRemoteControlClientsRevokeParams(allocator: std.mem.Allocator, params_value: ?std.json.Value) !?[]const u8 {
    const params = params_value orelse return try remoteControlMissingParamsMessage(allocator);
    if (params == .null) return try remoteControlMissingParamsMessage(allocator);
    if (params != .object) return try allocator.dupe(u8, "Invalid request: expected struct RemoteControlClientsRevokeParams");
    const object = params.object;
    if (try validateRemoteControlRequiredStringField(allocator, object, "environmentId")) |message| return message;
    if (try validateRemoteControlRequiredStringField(allocator, object, "clientId")) |message| return message;
    return null;
}

fn remoteControlMissingParamsMessage(allocator: std.mem.Allocator) ![]const u8 {
    return allocator.dupe(u8, "Invalid request: missing field `params`");
}

fn validateRemoteControlRequiredStringField(allocator: std.mem.Allocator, object: std.json.ObjectMap, field: []const u8) !?[]const u8 {
    const value = object.get(field) orelse return try std.fmt.allocPrint(allocator, "Invalid request: missing field `{s}`", .{field});
    if (value != .string) return try remoteControlInvalidTypeMessage(allocator, value, "a string");
    return null;
}

fn validateRemoteControlOptionalStringField(allocator: std.mem.Allocator, object: std.json.ObjectMap, field: []const u8) !?[]const u8 {
    const value = object.get(field) orelse return null;
    if (value == .null) return null;
    if (value != .string) return try remoteControlInvalidTypeMessage(allocator, value, "a string");
    return null;
}

fn remoteControlInvalidTypeMessage(allocator: std.mem.Allocator, value: std.json.Value, expected: []const u8) ![]const u8 {
    return switch (value) {
        .string => |text| std.fmt.allocPrint(allocator, "Invalid request: invalid type: string \"{s}\", expected {s}", .{ text, expected }),
        .integer => |integer| std.fmt.allocPrint(allocator, "Invalid request: invalid type: integer `{d}`, expected {s}", .{ integer, expected }),
        .bool => |boolean| std.fmt.allocPrint(allocator, "Invalid request: invalid type: boolean `{}`, expected {s}", .{ boolean, expected }),
        .null => std.fmt.allocPrint(allocator, "Invalid request: invalid type: null, expected {s}", .{expected}),
        else => std.fmt.allocPrint(allocator, "Invalid request: expected {s}", .{expected}),
    };
}

fn remoteControlInvalidValueMessage(allocator: std.mem.Allocator, value: std.json.Value, expected: []const u8) ![]const u8 {
    return switch (value) {
        .integer => |integer| std.fmt.allocPrint(allocator, "Invalid request: invalid value: integer `{d}`, expected {s}", .{ integer, expected }),
        else => remoteControlInvalidTypeMessage(allocator, value, expected),
    };
}

fn isEnvironmentMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "environment/add") or
        std.mem.eql(u8, method, "environment/info") or
        std.mem.eql(u8, method, "environment/status");
}

fn validateEnvironmentRequestParams(allocator: std.mem.Allocator, method: []const u8, params_value: ?std.json.Value) !?[]const u8 {
    const params = params_value orelse return try remoteControlMissingParamsMessage(allocator);
    if (params == .null) return try remoteControlMissingParamsMessage(allocator);
    if (params == .array) {
        const struct_name, const expected_len = environmentParamsStructShape(method);
        return try std.fmt.allocPrint(
            allocator,
            "Invalid request: invalid length {d}, expected struct {s} with {d} elements",
            .{ params.array.items.len, struct_name, expected_len },
        );
    }
    if (params != .object) {
        const struct_name, _ = environmentParamsStructShape(method);
        return try std.fmt.allocPrint(allocator, "Invalid request: expected struct {s}", .{struct_name});
    }

    const object = params.object;
    if (try validateRemoteControlRequiredStringField(allocator, object, "environmentId")) |message| return message;
    if (std.mem.eql(u8, method, "environment/add")) {
        if (try validateRemoteControlRequiredStringField(allocator, object, "execServerUrl")) |message| return message;
        if (object.get("connectTimeoutMs")) |value| {
            if (try validateEnvironmentOptionalU64Field(allocator, value)) |message| return message;
        }
    }
    return null;
}

fn environmentParamsStructShape(method: []const u8) struct { []const u8, usize } {
    if (std.mem.eql(u8, method, "environment/add")) return .{ "EnvironmentAddParams", 3 };
    if (std.mem.eql(u8, method, "environment/info")) return .{ "EnvironmentInfoParams", 1 };
    return .{ "EnvironmentStatusParams", 1 };
}

fn validateEnvironmentOptionalU64Field(allocator: std.mem.Allocator, value: std.json.Value) !?[]const u8 {
    if (value == .null) return null;
    switch (value) {
        .integer => |integer| {
            if (integer < 0) return try remoteControlInvalidValueMessage(allocator, value, "u64");
            return null;
        },
        .number_string => |number| {
            _ = std.fmt.parseUnsigned(u64, number, 10) catch return try remoteControlInvalidValueMessage(allocator, value, "u64");
            return null;
        },
        else => return try remoteControlInvalidTypeMessage(allocator, value, "u64"),
    }
}

fn handleEnvironmentMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value.?.object;
    const environment_id = params.get("environmentId").?.string;

    if (std.mem.eql(u8, method, "environment/add")) {
        const exec_server_url = params.get("execServerUrl").?.string;
        try upsertEnvironmentEntry(allocator, state, environment_id, exec_server_url);
        return renderJsonRpcResult(allocator, id_value, "{}");
    }

    const index = findEnvironmentEntryIndex(state, environment_id) orelse {
        const message = try std.fmt.allocPrint(allocator, "unknown environment id `{s}`", .{environment_id});
        defer allocator.free(message);
        if (std.mem.eql(u8, method, "environment/status")) {
            const result = try renderEnvironmentStatusResult(allocator, "unknown", message);
            defer allocator.free(result);
            return renderJsonRpcResult(allocator, id_value, result);
        }
        return renderJsonRpcError(allocator, id_value, -32600, message);
    };

    const entry = &state.environments.items[index];
    if (std.mem.eql(u8, method, "environment/status")) {
        const status: []const u8 = if (entry.disconnected_error != null) "disconnected" else "pending";
        const result = try renderEnvironmentStatusResult(allocator, status, entry.disconnected_error);
        defer allocator.free(result);
        return renderJsonRpcResult(allocator, id_value, result);
    }

    const connection_error = if (entry.disconnected_error) |message|
        try allocator.dupe(u8, message)
    else
        try std.fmt.allocPrint(
            allocator,
            "exec-server connection attempt failed: failed to connect to exec-server websocket `{s}`: live exec-server connections are not supported yet",
            .{entry.exec_server_url},
        );
    defer allocator.free(connection_error);

    const message = try std.fmt.allocPrint(
        allocator,
        "failed to get info for environment `{s}`: {s}",
        .{ environment_id, connection_error },
    );
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32603, message);
}

fn findEnvironmentEntryIndex(state: *const AppServerState, environment_id: []const u8) ?usize {
    for (state.environments.items, 0..) |entry, index| {
        if (std.mem.eql(u8, entry.environment_id, environment_id)) return index;
    }
    return null;
}

fn upsertEnvironmentEntry(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    environment_id: []const u8,
    exec_server_url: []const u8,
) !void {
    var entry = EnvironmentEntry{
        .environment_id = try allocator.dupe(u8, environment_id),
        .exec_server_url = try allocator.dupe(u8, exec_server_url),
        .disconnected_error = try environmentInitialDisconnectedError(allocator, exec_server_url),
    };
    errdefer entry.deinit(allocator);

    if (findEnvironmentEntryIndex(state, environment_id)) |index| {
        state.environments.items[index].deinit(allocator);
        state.environments.items[index] = entry;
        return;
    }

    try state.environments.append(allocator, entry);
}

fn environmentInitialDisconnectedError(allocator: std.mem.Allocator, exec_server_url: []const u8) !?[]const u8 {
    if (std.mem.startsWith(u8, exec_server_url, "ws://") or std.mem.startsWith(u8, exec_server_url, "wss://")) {
        return null;
    }
    return try std.fmt.allocPrint(
        allocator,
        "exec-server connection attempt failed: failed to connect to exec-server websocket `{s}`: URL error: URL scheme not supported",
        .{exec_server_url},
    );
}

fn renderEnvironmentStatusResult(
    allocator: std.mem.Allocator,
    status: []const u8,
    error_message: ?[]const u8,
) ![]const u8 {
    var result: std.ArrayList(u8) = .empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"status\":");
    try appendJsonString(allocator, &result, status);
    if (error_message) |message| {
        try result.appendSlice(allocator, ",\"error\":");
        try appendJsonString(allocator, &result, message);
    }
    try result.append(allocator, '}');
    return try result.toOwnedSlice(allocator);
}

fn handleRemoteControlStatusMutation(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    status: []const u8,
    changed: bool,
) ![]const u8 {
    var identity = try resolveRemoteControlIdentity(allocator);
    defer identity.deinit(allocator);
    if (changed) {
        const notification = try renderRemoteControlStatusChangedNotification(allocator, status, identity, null);
        var notification_moved = false;
        errdefer if (!notification_moved) allocator.free(notification);
        try queuePendingServerNotification(allocator, state, "remoteControl/status/changed", notification);
        notification_moved = true;
    }

    const result = try renderRemoteControlStatusObjectWithIdentity(allocator, status, identity, null);
    defer allocator.free(result);
    return try renderJsonRpcResult(allocator, id_value, result);
}

fn renderRemoteControlStatusObject(
    allocator: std.mem.Allocator,
    status: []const u8,
    environment_id: ?[]const u8,
) ![]const u8 {
    var identity = try resolveRemoteControlIdentity(allocator);
    defer identity.deinit(allocator);
    return renderRemoteControlStatusObjectWithIdentity(allocator, status, identity, environment_id);
}

fn renderRemoteControlStatusObjectWithIdentity(
    allocator: std.mem.Allocator,
    status: []const u8,
    identity: RemoteControlIdentity,
    environment_id: ?[]const u8,
) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"status\":");
    try appendJsonString(allocator, &out, status);
    try out.appendSlice(allocator, ",\"serverName\":");
    try appendJsonString(allocator, &out, identity.server_name);
    try out.appendSlice(allocator, ",\"installationId\":");
    try appendJsonString(allocator, &out, identity.installation_id);
    try out.appendSlice(allocator, ",\"environmentId\":");
    try appendOptionalJsonString(allocator, &out, environment_id);
    try out.appendSlice(allocator, "}");
    return try out.toOwnedSlice(allocator);
}

fn resolveRemoteControlIdentity(allocator: std.mem.Allocator) !RemoteControlIdentity {
    const server_name = try remoteControlServerName(allocator);
    errdefer allocator.free(server_name);
    const installation_id = try remoteControlInstallationId(allocator);
    return .{
        .server_name = server_name,
        .installation_id = installation_id,
    };
}

fn remoteControlServerName(allocator: std.mem.Allocator) ![]const u8 {
    var hostname_buffer: [std.posix.HOST_NAME_MAX]u8 = undefined;
    const hostname = std.posix.gethostname(&hostname_buffer) catch return allocator.dupe(u8, "unknown");
    const trimmed = std.mem.trim(u8, hostname, " \t\r\n");
    if (trimmed.len == 0) return allocator.dupe(u8, "unknown");
    return allocator.dupe(u8, trimmed);
}

fn remoteControlInstallationId(allocator: std.mem.Allocator) ![]const u8 {
    const codex_home = try resolveCodexHome(allocator);
    defer allocator.free(codex_home);
    return config.resolveInstallationId(allocator, codex_home);
}

fn renderMcpToolCallProgressNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    turn_id: []const u8,
    item_id: []const u8,
    message: []const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"item/mcpToolCall/progress\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &notification, turn_id);
    try notification.appendSlice(allocator, ",\"itemId\":");
    try appendJsonString(allocator, &notification, item_id);
    try notification.appendSlice(allocator, ",\"message\":");
    try appendJsonString(allocator, &notification, message);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

fn renderModelReroutedNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    turn_id: []const u8,
    from_model: []const u8,
    to_model: []const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"model/rerouted\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &notification, turn_id);
    try notification.appendSlice(allocator, ",\"fromModel\":");
    try appendJsonString(allocator, &notification, from_model);
    try notification.appendSlice(allocator, ",\"toModel\":");
    try appendJsonString(allocator, &notification, to_model);
    try notification.appendSlice(allocator, ",\"reason\":\"highRiskCyberActivity\"}}");
    return notification.toOwnedSlice(allocator);
}

fn renderModelVerificationNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    turn_id: []const u8,
    verifications: []const api.ModelVerification,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"model/verification\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &notification, turn_id);
    try notification.appendSlice(allocator, ",\"verifications\":[");
    for (verifications, 0..) |verification, index| {
        if (index > 0) try notification.appendSlice(allocator, ",");
        try appendJsonString(allocator, &notification, verification.label());
    }
    try notification.appendSlice(allocator, "]}}");
    return notification.toOwnedSlice(allocator);
}

fn renderReasoningSummaryTextDeltaNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    turn_id: []const u8,
    item_id: []const u8,
    delta: []const u8,
    summary_index: i64,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"item/reasoning/summaryTextDelta\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"turnId\":");
    try appendJsonString(allocator, &notification, turn_id);
    try notification.appendSlice(allocator, ",\"itemId\":");
    try appendJsonString(allocator, &notification, item_id);
    try notification.appendSlice(allocator, ",\"delta\":");
    try appendJsonString(allocator, &notification, delta);
    try notification.appendSlice(allocator, ",\"summaryIndex\":");
    try appendInt(allocator, &notification, summary_index);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

