        const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
            error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        };
        if (!threadMemoryModeParamIsValid(object)) {
            return renderJsonRpcError(allocator, id_value, -32602, "mode must be enabled or disabled");
        }
        if (!isUuidString(thread_id)) {
            return renderInvalidThreadId(allocator, id_value, thread_id);
        }
        const mode = object.get("mode").?.string;
        if (findLoadedThreadIndex(state, thread_id)) |thread_index| {
            const thread = &state.loaded_threads.items[thread_index];
            if (thread.ephemeral) {
                const message = try std.fmt.allocPrint(allocator, "ephemeral thread does not support memory mode updates: {s}", .{thread_id});
                defer allocator.free(message);
                return renderJsonRpcError(allocator, id_value, -32600, message);
            }
            setLoadedThreadMemoryMode(allocator, thread, mode) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "thread/memoryMode/set failed", err);
            };
            return renderJsonRpcResult(allocator, id_value, "{}");
        }
        var cfg = loadAppServerConfig(allocator, state) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/memoryMode/set failed to load config", err);
        };
        defer cfg.deinit(allocator);
        var stored_thread = createStoredThreadFromParamsIncludingStateDb(allocator, cfg, object) catch |err| switch (err) {
            error.FileNotFound => return renderThreadNotFound(allocator, id_value, thread_id),
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/memoryMode/set failed", err),
        };
        defer stored_thread.deinit(allocator);
        const stored_path = stored_thread.path orelse return renderThreadNotFound(allocator, id_value, thread_id);
        session_store.appendThreadMemoryModeFromTranscript(allocator, stored_path, thread_id, &stored_thread.transcript, mode) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/memoryMode/set failed", err);
        };
        _ = thread_state.updateThreadMemoryMode(allocator, configSqliteHome(cfg), thread_id, mode) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/memoryMode/set failed", err);
        };
        return renderJsonRpcResult(allocator, id_value, "{}");
    }
    if (std.mem.eql(u8, method, "thread/metadata/update")) {
        const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
            error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        };
        if (!isUuidString(thread_id)) {
            return renderInvalidThreadId(allocator, id_value, thread_id);
        }
        if (validateThreadMetadataGitInfoParams(object)) |validation_error| {
            return renderJsonRpcError(allocator, id_value, validation_error.code, validation_error.message);
        }
        const git_info = object.get("gitInfo").?.object;
        if (findLoadedThreadIndex(state, thread_id)) |thread_index| {
            const thread = &state.loaded_threads.items[thread_index];
            if (thread.ephemeral) {
                const message = try std.fmt.allocPrint(allocator, "ephemeral thread does not support metadata updates: {s}", .{thread_id});
                defer allocator.free(message);
                return renderJsonRpcError(allocator, id_value, -32600, message);
            }
            updateLoadedThreadGitInfo(allocator, thread, git_info) catch |err| switch (err) {
                error.InvalidThreadMetadataGitInfo => return renderJsonRpcError(allocator, id_value, -32600, "invalid gitInfo patch"),
                else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/metadata/update failed", err),
            };
            const result = try renderThreadReadResponse(allocator, thread, false);
            defer allocator.free(result);
            return renderJsonRpcResult(allocator, id_value, result);
        }
        var cfg = loadAppServerConfig(allocator, state) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/metadata/update failed to load config", err);
        };
        defer cfg.deinit(allocator);
        var stored_thread = createStoredThreadFromParamsIncludingStateDb(allocator, cfg, object) catch |err| switch (err) {
            error.FileNotFound => return renderThreadNotFound(allocator, id_value, thread_id),
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/metadata/update failed", err),
        };
        defer stored_thread.deinit(allocator);
        patchLoadedThreadGitInfoField(allocator, git_info, "sha", &stored_thread.git_sha) catch |err| switch (err) {
            error.InvalidThreadMetadataGitInfo => return renderJsonRpcError(allocator, id_value, -32600, "invalid gitInfo patch"),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/metadata/update failed", err),
        };
        patchLoadedThreadGitInfoField(allocator, git_info, "branch", &stored_thread.git_branch) catch |err| switch (err) {
            error.InvalidThreadMetadataGitInfo => return renderJsonRpcError(allocator, id_value, -32600, "invalid gitInfo patch"),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/metadata/update failed", err),
        };
        patchLoadedThreadGitInfoField(allocator, git_info, "originUrl", &stored_thread.git_origin_url) catch |err| switch (err) {
            error.InvalidThreadMetadataGitInfo => return renderJsonRpcError(allocator, id_value, -32600, "invalid gitInfo patch"),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/metadata/update failed", err),
        };
        const stored_path = stored_thread.path orelse return renderThreadNotFound(allocator, id_value, thread_id);
        session_store.appendThreadGitInfoFromTranscript(allocator, stored_path, thread_id, &stored_thread.transcript, stored_thread.git_sha, stored_thread.git_branch, stored_thread.git_origin_url, stored_thread.transcript.memory_mode) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/metadata/update failed", err);
        };
        _ = thread_state.updateThreadGitInfo(allocator, configSqliteHome(cfg), thread_id, stored_thread.git_sha, stored_thread.git_branch, stored_thread.git_origin_url) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/metadata/update failed", err);
        };
        const result = try renderStoredThreadReadResponse(allocator, &stored_thread, false);
        defer allocator.free(result);
        return renderJsonRpcResult(allocator, id_value, result);
    }
    if (std.mem.eql(u8, method, "thread/settings/update")) {
        return handleThreadSettingsUpdate(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "thread/read")) {
        const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
            error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        };
        if (!threadReadIncludeTurnsParamIsValid(object)) {
            return renderJsonRpcError(allocator, id_value, -32602, "includeTurns must be a boolean");
        }
        if (!isUuidString(thread_id)) {
            return renderInvalidThreadId(allocator, id_value, thread_id);
        }
        if (findLoadedThread(state, thread_id)) |thread| {
            const include_turns = threadReadIncludeTurnsParam(object);
            if (include_turns) {
                if (thread.ephemeral) return renderThreadReadIncludeTurnsEphemeral(allocator, id_value);
                if (!(try loadedThreadHasMaterializedTurns(allocator, thread))) return renderThreadReadIncludeTurnsUnavailable(allocator, id_value, thread_id);
            }
            const result = try renderThreadReadResponse(allocator, thread, include_turns);
            defer allocator.free(result);
            return renderJsonRpcResult(allocator, id_value, result);
        }
        var cfg = loadAppServerConfig(allocator, state) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/read failed to load config", err);
        };
        defer cfg.deinit(allocator);
        var stored_thread = createStoredThreadFromParamsIncludingArchived(allocator, cfg, object) catch |err| switch (err) {
            error.FileNotFound => return renderThreadNotLoaded(allocator, id_value, thread_id),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/read failed to load stored thread", err),
        };
        defer stored_thread.deinit(allocator);
        const include_turns = threadReadIncludeTurnsParam(object);
        const result = try renderStoredThreadReadResponse(allocator, &stored_thread, include_turns);
        defer allocator.free(result);
        return renderJsonRpcResult(allocator, id_value, result);
    }
    if (std.mem.eql(u8, method, "thread/turns/list")) {
        const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
            error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        };
        if (validateThreadTurnsListParams(object)) |message| {
            return renderJsonRpcError(allocator, id_value, -32602, message);
        }
        if (!isUuidString(thread_id)) {
            return renderInvalidThreadId(allocator, id_value, thread_id);
        }
        if (findLoadedThread(state, thread_id)) |thread| {
            if (thread.ephemeral) return renderThreadTurnsListEphemeral(allocator, id_value);
            if (!(try loadedThreadHasMaterializedTurns(allocator, thread))) return renderThreadTurnsListUnavailable(allocator, id_value, thread_id);
            const result = renderThreadTurnsListResponse(allocator, thread, object) catch |err| switch (err) {
                error.InvalidThreadTurnsCursor => {
                    const cursor = optionalStringParam(object, "cursor") orelse "";
                    const message = try std.fmt.allocPrint(allocator, "invalid cursor: {s}", .{cursor});
                    defer allocator.free(message);
                    return renderJsonRpcError(allocator, id_value, -32600, message);
                },
                error.InvalidThreadTurnsCursorAnchor => return renderJsonRpcError(allocator, id_value, -32600, "invalid cursor: anchor turn is no longer present"),
                else => |other| return other,
            };
            defer allocator.free(result);
            return renderJsonRpcResult(allocator, id_value, result);
        }
        var cfg = loadAppServerConfig(allocator, state) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/turns/list failed to load config", err);
        };
        defer cfg.deinit(allocator);
        var stored_thread = createStoredThreadFromParamsIncludingArchived(allocator, cfg, object) catch |err| switch (err) {
            error.FileNotFound => return renderThreadNotLoaded(allocator, id_value, thread_id),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/turns/list failed to load stored thread", err),
        };
        defer stored_thread.deinit(allocator);
        const result = renderThreadTurnsListResponse(allocator, &stored_thread, object) catch |err| switch (err) {
            error.InvalidThreadTurnsCursor => {
                const cursor = optionalStringParam(object, "cursor") orelse "";
                const message = try std.fmt.allocPrint(allocator, "invalid cursor: {s}", .{cursor});
                defer allocator.free(message);
                return renderJsonRpcError(allocator, id_value, -32600, message);
            },
            error.InvalidThreadTurnsCursorAnchor => return renderJsonRpcError(allocator, id_value, -32600, "invalid cursor: anchor turn is no longer present"),
            else => |other| return other,
        };
        defer allocator.free(result);
        return renderJsonRpcResult(allocator, id_value, result);
    }
    if (std.mem.eql(u8, method, "thread/items/list")) {
        const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
            error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        };
        if (validateThreadItemsListParams(object)) |message| {
            return renderJsonRpcError(allocator, id_value, -32602, message);
        }
        if (!isUuidString(thread_id)) {
            return renderInvalidThreadId(allocator, id_value, thread_id);
        }
        return renderJsonRpcError(allocator, id_value, -32601, "thread/items/list is not supported yet");
    }
    if (std.mem.eql(u8, method, "thread/realtime/listVoices")) {
        _ = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        return renderJsonRpcResult(allocator, id_value, THREAD_REALTIME_LIST_VOICES_RESPONSE_JSON);
    }
    if (std.mem.eql(u8, method, "thread/realtime/stop")) {
        const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
            error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        };
        if (!isUuidString(thread_id)) {
            return renderInvalidThreadId(allocator, id_value, thread_id);
        }
        const thread_index = findLoadedThreadIndex(state, thread_id) orelse {
            return renderThreadNotFound(allocator, id_value, thread_id);
        };
        if (!(try appServerFeatureEnabled(allocator, state, "realtime_conversation"))) {
            return renderThreadRealtimeFeatureDisabled(allocator, id_value, thread_id);
        }
        try stopLoadedThreadRealtime(allocator, state, thread_index);
        return renderJsonRpcResult(allocator, id_value, "{}");
    }
    if (std.mem.eql(u8, method, "thread/realtime/appendText") or
        std.mem.eql(u8, method, "thread/realtime/appendSpeech"))
    {
        return handleThreadRealtimeAppendTextLike(allocator, state, id_value, method, params_value);
    }
    if (std.mem.eql(u8, method, "thread/realtime/appendAudio")) {
        const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
            error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        };
        if (validateThreadRealtimeAudioParam(object)) |message| {
            return renderJsonRpcError(allocator, id_value, -32602, message);
        }
        if (!isUuidString(thread_id)) {
            return renderInvalidThreadId(allocator, id_value, thread_id);
        }
        const thread_index = findLoadedThreadIndex(state, thread_id) orelse {
            return renderThreadNotFound(allocator, id_value, thread_id);
        };
        if (!(try appServerFeatureEnabled(allocator, state, "realtime_conversation"))) {
            return renderThreadRealtimeFeatureDisabled(allocator, id_value, thread_id);
        }
        try requireLoadedThreadRealtimeRunning(allocator, state, thread_index);
        return renderJsonRpcResult(allocator, id_value, "{}");
    }
    if (std.mem.eql(u8, method, "thread/realtime/start")) {
        const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
        };
        const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
            error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        };
        if (validateThreadRealtimeStartParams(object)) |message| {
            return renderJsonRpcError(allocator, id_value, -32602, message);
        }
        if (!isUuidString(thread_id)) {
            return renderInvalidThreadId(allocator, id_value, thread_id);
        }
        const thread_index = findLoadedThreadIndex(state, thread_id) orelse {
            return renderThreadNotFound(allocator, id_value, thread_id);
        };
        if (!(try appServerFeatureEnabled(allocator, state, "realtime_conversation"))) {
            return renderThreadRealtimeFeatureDisabled(allocator, id_value, thread_id);
        }
        try startLoadedThreadRealtime(allocator, state, thread_index, object);
        return renderJsonRpcResult(allocator, id_value, "{}");
    }
    return renderParsedButNotImplemented(allocator, id_value, method);
}

const ThreadRequestConfigOverrides = struct {
    profile_present: bool = false,
    profile: ?[]const u8 = null,
    model_provider_present: bool = false,
    model_provider: ?[]const u8 = null,
    openai_base_url_present: bool = false,
    openai_base_url: ?[]const u8 = null,
    chatgpt_base_url_present: bool = false,
    chatgpt_base_url: ?[]const u8 = null,
    web_search_mode_present: bool = false,
    web_search_mode: ?config.WebSearchMode = null,
    oss_mode_present: bool = false,
    oss_mode: bool = false,
    oss_provider_present: bool = false,
    oss_provider: ?[]const u8 = null,
};

fn validateThreadRequestConfigParam(object: std.json.ObjectMap) ?[]const u8 {
    const value = object.get("config") orelse return null;
    if (value == .null) return null;
    if (value != .object) return "config must be an object or null";
    if (value.object.get("profile")) |profile| {
        if (profile != .null and profile != .string) return "config.profile must be a string or null";
    }
    if (value.object.get("model_provider")) |model_provider| {
        if (model_provider != .null and model_provider != .string) return "config.model_provider must be a string or null";
    }
    if (value.object.get("openai_base_url")) |openai_base_url| {
        if (openai_base_url != .null and openai_base_url != .string) return "config.openai_base_url must be a string or null";
    }
    if (value.object.get("chatgpt_base_url")) |chatgpt_base_url| {
        if (chatgpt_base_url != .null and chatgpt_base_url != .string) return "config.chatgpt_base_url must be a string or null";
    }
    if (value.object.get("web_search")) |web_search| {
        if (!optionalEnumStringIsValid(web_search, &.{ "disabled", "cached", "live" })) {
            return "config.web_search must be disabled, cached, live, or null";
        }
    }
    if (value.object.get("oss")) |oss_mode| {
        if (oss_mode != .null and oss_mode != .bool) return "config.oss must be a boolean or null";
    }
    if (value.object.get("oss_provider")) |oss_provider| {
        if (!optionalEnumStringIsValid(oss_provider, &.{ "lmstudio", "ollama" })) {
            return "config.oss_provider must be lmstudio, ollama, or null";
        }
    }
    return null;
}

fn threadRequestConfigFromParams(params: ?std.json.ObjectMap) !ThreadRequestConfigOverrides {
    const object = params orelse return .{};
    const value = object.get("config") orelse return .{};
    if (value == .null) return .{};
    if (value != .object) return error.InvalidThreadRequestConfig;

    var result = ThreadRequestConfigOverrides{};
    if (value.object.get("profile")) |profile| {
        result.profile_present = true;
        result.profile = switch (profile) {
            .null => null,
            .string => |profile_value| profile_value,
            else => return error.InvalidThreadRequestConfig,
        };
    }
    if (value.object.get("model_provider")) |model_provider| {
        result.model_provider_present = true;
        result.model_provider = switch (model_provider) {
            .null => null,
            .string => |provider| provider,
            else => return error.InvalidThreadRequestConfig,
        };
    }
    if (value.object.get("openai_base_url")) |openai_base_url| {
        result.openai_base_url_present = true;
        result.openai_base_url = switch (openai_base_url) {
            .null => null,
            .string => |base_url| base_url,
            else => return error.InvalidThreadRequestConfig,
        };
    }
    if (value.object.get("chatgpt_base_url")) |chatgpt_base_url| {
        result.chatgpt_base_url_present = true;
        result.chatgpt_base_url = switch (chatgpt_base_url) {
            .null => null,
            .string => |base_url| base_url,
            else => return error.InvalidThreadRequestConfig,
        };
    }
    if (value.object.get("web_search")) |web_search| {
        result.web_search_mode_present = true;
        result.web_search_mode = switch (web_search) {
            .null => null,
            .string => |mode| config.WebSearchMode.parse(mode) catch return error.InvalidThreadRequestConfig,
            else => return error.InvalidThreadRequestConfig,
        };
    }
    if (value.object.get("oss")) |oss_mode| {
        result.oss_mode_present = true;
        result.oss_mode = switch (oss_mode) {
            .null => false,
            .bool => |mode| mode,
            else => return error.InvalidThreadRequestConfig,
        };
    }
    if (value.object.get("oss_provider")) |oss_provider| {
        result.oss_provider_present = true;
        result.oss_provider = switch (oss_provider) {
            .null => null,
            .string => |provider| blk: {
                const parsed = config.OssProvider.parse(provider) catch return error.InvalidThreadRequestConfig;
                break :blk parsed.label();
            },
            else => return error.InvalidThreadRequestConfig,
        };
    }
    return result;
}

fn threadRequestConfigParamPresent(params: ?std.json.ObjectMap, name: []const u8) bool {
    const object = params orelse return false;
    const value = object.get("config") orelse return false;
    if (value != .object) return false;
    return value.object.get(name) != null;
}

fn loadConfigForThreadRequest(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    request_config: ThreadRequestConfigOverrides,
) !config.Config {
    return loadAppServerConfigWithOptions(allocator, state, .{ .profile = request_config.profile });
}

fn loadConfigForLoadedThread(allocator: std.mem.Allocator, state: *const AppServerState, thread: *const LoadedThread) !config.Config {
    return loadAppServerConfigWithOptions(allocator, state, .{ .profile = thread.active_profile });
}

fn applyRuntimeScalarRequirementsToConfigWithRequirements(
    cfg: *config.Config,
    requirements: ConfigRequirementsReadRequirements,
) !void {
    cfg.approval_policy = try configReadRequirementApprovalPolicy(cfg.approval_policy, requirements);
    cfg.approvals_reviewer = try configReadRequirementApprovalsReviewer(cfg.approvals_reviewer, requirements);
    cfg.sandbox_mode = try configReadRequirementSandboxMode(cfg.sandbox_mode, requirements);
    cfg.web_search_mode = try configReadRequirementWebSearchMode(cfg.web_search_mode, requirements);
}

fn runtimeRequirementListAllows(allowed: ?config.StringList, label: []const u8) bool {
    const list = allowed orelse return true;
    if (list.items.len == 0) return false;
    return configReadRequirementListContains(list, label);
}

fn runtimeRequirementAllowsWebSearchMode(value: ?config.WebSearchMode, requirements: ConfigRequirementsReadRequirements) bool {
    const mode = value orelse return true;
    const allowed = requirements.allowed_web_search_modes orelse return true;
    if (allowed.items.len == 0) return mode == .disabled;
    return configReadRequirementListContains(allowed, mode.label());
}

fn validateRuntimeApprovalPolicyAllowed(value: config.ApprovalPolicy, requirements: ConfigRequirementsReadRequirements) !void {
    if (!runtimeRequirementListAllows(requirements.allowed_approval_policies, value.label())) {
        return error.RuntimeApprovalPolicyDisallowed;
    }
}

fn validateRuntimeApprovalsReviewerAllowed(value: config.ApprovalsReviewer, requirements: ConfigRequirementsReadRequirements) !void {
    if (!runtimeRequirementListAllows(requirements.allowed_approvals_reviewers, value.label())) {
        return error.RuntimeApprovalsReviewerDisallowed;
    }
}

fn validateRuntimeSandboxModeAllowed(value: config.SandboxMode, requirements: ConfigRequirementsReadRequirements) !void {
    if (!runtimeRequirementListAllows(requirements.allowed_sandbox_modes, value.label())) {
        return error.RuntimeSandboxModeDisallowed;
    }
}

fn validateRuntimeWebSearchModeAllowed(value: ?config.WebSearchMode, requirements: ConfigRequirementsReadRequirements) !void {
    if (!runtimeRequirementAllowsWebSearchMode(value, requirements)) {
        return error.RuntimeWebSearchModeDisallowed;
    }
}

fn applyThreadRequestConfigOverrides(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    request_config: ThreadRequestConfigOverrides,
    explicit_model: bool,
) !void {
    if (request_config.model_provider_present) {
        try config.applyRuntimeOverrides(cfg, allocator, .{
            .model_provider_id = request_config.model_provider orelse "openai",
        });
    }
    if (request_config.openai_base_url_present) {
        if (request_config.openai_base_url) |base_url| {
            try replaceConfigOwnedString(allocator, &cfg.openai_base_url, base_url);
        }
    }
    if (request_config.chatgpt_base_url_present) {
        if (request_config.chatgpt_base_url) |base_url| {
            try replaceConfigOwnedString(allocator, &cfg.chatgpt_base_url, base_url);
        }
    }
    if (request_config.web_search_mode_present) cfg.web_search_mode = request_config.web_search_mode;
    if (request_config.oss_provider_present) {
        if (request_config.oss_provider) |provider| {
            try replaceConfigOptionalString(allocator, &cfg.oss_provider, provider);
        } else {
            clearOptionalOwnedString(allocator, &cfg.oss_provider);
        }
    }
    if (request_config.oss_mode_present and request_config.oss_mode) {
        try config.applyOssMode(cfg, allocator, null, explicit_model);
    }
}

fn validateLifecycleScalarRequirementOverrides(
    params: ?std.json.ObjectMap,
    request_config: ThreadRequestConfigOverrides,
    requirements: ConfigRequirementsReadRequirements,
) !void {
    if (optionalStringParam(params, "approvalPolicy")) |approval_policy| {
        try validateRuntimeApprovalPolicyAllowed(try config.ApprovalPolicy.parse(approval_policy), requirements);
    }
    if (try optionalApprovalsReviewerLifecycleParam(params, "approvalsReviewer")) |approvals_reviewer| {
        try validateRuntimeApprovalsReviewerAllowed(try config.ApprovalsReviewer.parse(approvals_reviewer), requirements);
    }
    if (optionalStringParam(params, "sandbox")) |sandbox| {
        try validateRuntimeSandboxModeAllowed(try config.SandboxMode.parse(sandbox), requirements);
    }
    if (request_config.web_search_mode_present) {
        try validateRuntimeWebSearchModeAllowed(request_config.web_search_mode, requirements);
    }
}

fn renderRuntimeRequirementOverrideError(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    err: anyerror,
) ![]const u8 {
    const message = switch (err) {
        error.RuntimeApprovalPolicyDisallowed => "approvalPolicy is disallowed by requirements",
        error.RuntimeApprovalsReviewerDisallowed => "approvalsReviewer is disallowed by requirements",
        error.RuntimeSandboxModeDisallowed => "sandbox is disallowed by requirements",
        error.RuntimeWebSearchModeDisallowed => "config.web_search is disallowed by requirements",
        else => return err,
    };
    return renderJsonRpcError(allocator, id_value, -32602, message);
}

fn threadOssProviderForRequest(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    request_config: ThreadRequestConfigOverrides,
) !?[]const u8 {
    if (!request_config.oss_mode) return null;
    const provider = cfg.oss_provider orelse return error.NoDefaultOssProviderConfigured;
    const owned = try allocator.dupe(u8, provider);
    return owned;
}

