fn handleThreadStart(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (validateThreadStartParams(params_value)) |message| {
        return renderJsonRpcError(allocator, id_value, -32602, message);
    }
    const params = threadStartObjectParams(params_value);
    const request_config = threadRequestConfigFromParams(params) catch |err| switch (err) {
        error.InvalidThreadRequestConfig => return renderJsonRpcError(allocator, id_value, -32602, "invalid thread config override"),
    };

    var cfg = loadConfigForThreadRequest(allocator, state, request_config) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to load config", err);
    };
    defer cfg.deinit(allocator);

    var runtime_requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to load config requirements", err);
    };
    defer runtime_requirements.deinit(allocator);
    validateLifecycleScalarRequirementOverrides(params, request_config, runtime_requirements) catch |err| {
        return renderRuntimeRequirementOverrideError(allocator, id_value, err);
    };
    applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to apply config requirements", err);
    };

    var start_permission_profile: ?config.SandboxPermissionProfile = null;
    defer if (start_permission_profile) |*profile| profile.deinit(allocator);
    if (params) |object| {
        const permissions_value = object.get("permissions");
        const has_permissions = permissions_value != null and permissions_value.? != .null;
        if (has_permissions) {
            if (object.get("sandbox")) |sandbox| {
                if (sandbox != .null) return renderJsonRpcError(allocator, id_value, -32602, "invalid thread context override");
            }
            const permission_profile_cwd = threadStartCwd(allocator, params) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to resolve cwd", err);
            };
            defer allocator.free(permission_profile_cwd);
            start_permission_profile = parseTurnStartPermissionSelection(allocator, cfg.codex_home, permission_profile_cwd, permissions_value.?) catch {
                return renderJsonRpcError(allocator, id_value, -32602, "invalid thread context override");
            };
            validateRuntimeSandboxModeAllowed(start_permission_profile.?.mode, runtime_requirements) catch |err| {
                return renderRuntimeRequirementOverrideError(allocator, id_value, err);
            };
            cfg.sandbox_mode = start_permission_profile.?.mode;
        }
    }

    applyThreadStartProjectTrustAndConfig(allocator, &cfg, params, if (start_permission_profile) |*profile| profile else null) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to load project config", err);
    };
    applyThreadRequestConfigOverrides(allocator, &cfg, request_config, paramPresent(params, "model")) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to apply config override", err);
    };
    if (start_permission_profile) |profile| cfg.sandbox_mode = profile.mode;
    applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to apply config requirements", err);
    };

    var mcp_startup_check = runThreadStartMcpStartupCheck(allocator, state, &cfg) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to initialize MCP servers", err);
    };
    defer mcp_startup_check.deinit(allocator);
    if (mcp_startup_check.required_failure_message) |message| {
        try queueThreadStartMcpStartupNotifications(allocator, state, &mcp_startup_check);
        return renderJsonRpcError(allocator, id_value, -32603, message);
    }

    var thread = createLoadedThreadFromStartParamsWithSource(allocator, cfg, params, state.session_source) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to create thread", err);
    };
    var thread_moved = false;
    errdefer if (!thread_moved) thread.deinit(allocator);
    if (start_permission_profile) |*profile| {
        applySandboxPermissionProfileToLoadedThread(allocator, &cfg, &thread, profile) catch |err| {
            return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to apply permission profile", err);
        };
    }
    applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(allocator, &thread, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/start failed to apply runtime requirements", err);
    };

    const result = try renderThreadLifecycleResponse(allocator, &thread, true, state.experimental_api_enabled);
    defer allocator.free(result);
    const started_notification = try renderThreadStartedNotification(allocator, &thread);
    var notification_moved = false;
    errdefer if (!notification_moved) allocator.free(started_notification);

    const subscription_added = try ensureThreadSubscribed(allocator, state, thread.id);
    var subscription_committed = false;
    errdefer {
        if (subscription_added and !subscription_committed) _ = removeThreadSubscription(allocator, state, thread.id);
    }
    try state.loaded_threads.append(allocator, thread);
    thread_moved = true;
    subscription_committed = true;
    try queueThreadStartedNotification(allocator, state, started_notification);
    notification_moved = true;
    try queueThreadLifecycleMcpStartupSuccess(allocator, state, cfg.codex_home, &mcp_startup_check);
    try queueConfigStartupNotifications(allocator, state, cfg, thread.id);
    try queueDeprecatedApprovalPolicyWarningNotification(allocator, state, &thread);
    try queueHookStartupWarningNotifications(allocator, state, cfg.codex_home, thread.id);

    return renderJsonRpcResult(allocator, id_value, result);
}

const ThreadStartMcpStartupCheck = struct {
    notifications: std.ArrayList([]const u8) = .empty,
    required_failure_message: ?[]const u8 = null,

    fn deinit(self: *ThreadStartMcpStartupCheck, allocator: std.mem.Allocator) void {
        for (self.notifications.items) |notification| allocator.free(notification);
        self.notifications.deinit(allocator);
        if (self.required_failure_message) |message| allocator.free(message);
    }
};

const ThreadStartMcpStartupContext = struct {
    allocator: std.mem.Allocator,
    notification_enabled: bool,
    servers: *const mcp_cmd.McpServers,
    notifications: *std.ArrayList([]const u8),
    required_failures: *std.ArrayList([]const u8),
};

fn runThreadStartMcpStartupCheck(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    cfg: *const config.Config,
) !ThreadStartMcpStartupCheck {
    var check = ThreadStartMcpStartupCheck{};
    errdefer check.deinit(allocator);

    var servers = try mcp_cmd.loadServers(allocator, cfg.codex_home);
    defer servers.deinit(allocator);
    if (!mcpServersIncludeEnabledRequired(servers)) return check;

    var required_failures = std.ArrayList([]const u8).empty;
    defer {
        for (required_failures.items) |failure| allocator.free(failure);
        required_failures.deinit(allocator);
    }

    var context = ThreadStartMcpStartupContext{
        .allocator = allocator,
        .notification_enabled = !notificationMethodOptedOut(state, "mcpServer/startupStatus/updated"),
        .servers = &servers,
        .notifications = &check.notifications,
        .required_failures = &required_failures,
    };
    var catalog = try mcp_runtime.loadCatalogWithOptions(allocator, cfg.codex_home, .{
        .server_filter = .required,
        .startup_status_callback = .{
            .ctx = &context,
            .on_startup_status = handleThreadStartMcpStartupStatus,
        },
    });
    catalog.deinit(allocator);

    if (required_failures.items.len > 0) {
        check.required_failure_message = try renderRequiredMcpStartupFailureMessage(allocator, required_failures.items);
    }
    return check;
}

fn mcpServersIncludeEnabledRequired(servers: mcp_cmd.McpServers) bool {
    for (servers.items.items) |server| {
        if (server.enabled and server.required) return true;
    }
    return false;
}

fn handleThreadStartMcpStartupStatus(
    ctx: *anyopaque,
    server_name: []const u8,
    status: mcp_runtime.StartupStatus,
    error_message: ?[]const u8,
) anyerror!void {
    const context: *ThreadStartMcpStartupContext = @ptrCast(@alignCast(ctx));

    if (context.notification_enabled) {
        const notification = try renderMcpServerStatusUpdatedNotification(context.allocator, server_name, status, error_message);
        errdefer context.allocator.free(notification);
        try context.notifications.append(context.allocator, notification);
    }

    if (status == .failed and mcpServerIsRequired(context.servers.*, server_name)) {
        const failure = try std.fmt.allocPrint(
            context.allocator,
            "{s}: {s}",
            .{ server_name, error_message orelse "unknown startup error" },
        );
        errdefer context.allocator.free(failure);
        try context.required_failures.append(context.allocator, failure);
    }
}

fn mcpServerIsRequired(servers: mcp_cmd.McpServers, server_name: []const u8) bool {
    for (servers.items.items) |server| {
        if (std.mem.eql(u8, server.name, server_name)) return server.enabled and server.required;
    }
    return false;
}

fn renderRequiredMcpStartupFailureMessage(allocator: std.mem.Allocator, failures: []const []const u8) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "required MCP servers failed to initialize: ");
    for (failures, 0..) |failure, index| {
        if (index > 0) try result.appendSlice(allocator, "; ");
        try result.appendSlice(allocator, failure);
    }
    return result.toOwnedSlice(allocator);
}

fn queueThreadLifecycleMcpStartupSuccess(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    codex_home: []const u8,
    check: *const ThreadStartMcpStartupCheck,
) !void {
    try queueThreadStartMcpStartupNotifications(allocator, state, check);
    if (try queueThreadStartOptionalMcpStartingNotifications(allocator, state, codex_home)) {
        spawnThreadStartOptionalMcpStartupWorkerForConnection(allocator, state, codex_home) catch {};
    }
}

fn queueThreadStartMcpStartupNotifications(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    check: *const ThreadStartMcpStartupCheck,
) !void {
    for (check.notifications.items) |notification| {
        const owned = try allocator.dupe(u8, notification);
        errdefer allocator.free(owned);
        try state.pending_notifications.append(allocator, owned);
    }
}

fn queueThreadStartOptionalMcpStartingNotifications(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    codex_home: []const u8,
) !bool {
    if (notificationMethodOptedOut(state, "mcpServer/startupStatus/updated")) return false;

    var servers = try mcp_cmd.loadServers(allocator, codex_home);
    defer servers.deinit(allocator);

    var queued_any = false;
    for (servers.items.items) |server| {
        if (!server.enabled or server.required) continue;
        const notification = try renderMcpServerStatusUpdatedNotification(allocator, server.name, .starting, null);
        try queuePendingServerNotification(allocator, state, "mcpServer/startupStatus/updated", notification);
        queued_any = true;
    }
    return queued_any;
}

const ThreadStartOptionalMcpStartupWorker = struct {
    codex_home: []const u8,
    completion_target: AppServerBackgroundNotificationTarget,

    fn deinit(self: *ThreadStartOptionalMcpStartupWorker, allocator: std.mem.Allocator) void {
        allocator.free(self.codex_home);
        self.completion_target.deinit(allocator);
    }
};

const ThreadStartOptionalMcpStartupContext = struct {
    allocator: std.mem.Allocator,
    completion_target: *AppServerBackgroundNotificationTarget,
};

fn spawnThreadStartOptionalMcpStartupWorkerForConnection(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    codex_home: []const u8,
) !void {
    var completion_target = try makeAppServerBackgroundNotificationTarget(allocator, state.connection_output);
    var completion_target_moved = false;
    errdefer if (!completion_target_moved) completion_target.deinit(allocator);
    try spawnThreadStartOptionalMcpStartupWorker(allocator, codex_home, completion_target);
    completion_target_moved = true;
}

fn spawnThreadStartOptionalMcpStartupWorker(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    completion_target: AppServerBackgroundNotificationTarget,
) !void {
    var target = completion_target;
    var target_moved = false;
    errdefer if (!target_moved) target.deinit(allocator);

    const worker = try allocator.create(ThreadStartOptionalMcpStartupWorker);
    var worker_initialized = false;
    errdefer {
        if (worker_initialized) worker.deinit(allocator);
        allocator.destroy(worker);
    }

    const codex_home_owned = try allocator.dupe(u8, codex_home);
    errdefer if (!worker_initialized) allocator.free(codex_home_owned);

    worker.* = .{
        .codex_home = codex_home_owned,
        .completion_target = target,
    };
    worker_initialized = true;
    target_moved = true;

    const thread = try std.Thread.spawn(.{ .allocator = allocator }, threadStartOptionalMcpStartupWorker, .{ allocator, worker });
    thread.detach();
}

fn threadStartOptionalMcpStartupWorker(allocator: std.mem.Allocator, worker: *ThreadStartOptionalMcpStartupWorker) void {
    defer {
        worker.deinit(allocator);
        allocator.destroy(worker);
    }

    std.Io.sleep(
        std.Io.Threaded.global_single_threaded.io(),
        .{ .nanoseconds = 10 * std.time.ns_per_ms },
        .awake,
    ) catch {};

    var context = ThreadStartOptionalMcpStartupContext{
        .allocator = allocator,
        .completion_target = &worker.completion_target,
    };
    var catalog = mcp_runtime.loadCatalogWithOptions(allocator, worker.codex_home, .{
        .server_filter = .optional,
        .startup_status_callback = .{
            .ctx = &context,
            .on_startup_status = handleThreadStartOptionalMcpStartupStatus,
        },
    }) catch return;
    catalog.deinit(allocator);
}

fn handleThreadStartOptionalMcpStartupStatus(
    ctx: *anyopaque,
    server_name: []const u8,
    status: mcp_runtime.StartupStatus,
    error_message: ?[]const u8,
) anyerror!void {
    if (status == .starting) return;

    const context: *ThreadStartOptionalMcpStartupContext = @ptrCast(@alignCast(ctx));
    const notification = try renderMcpServerStatusUpdatedNotification(context.allocator, server_name, status, error_message);
    defer context.allocator.free(notification);
    context.completion_target.send(notification) catch {};
}

fn handleThreadResume(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (validateThreadResumeParams(params_value)) |message| {
        return renderJsonRpcError(allocator, id_value, -32602, message);
    }
    const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
        error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, "thread/resume"),
    };
    const request_config = threadRequestConfigFromParams(object) catch |err| switch (err) {
        error.InvalidThreadRequestConfig => return renderJsonRpcError(allocator, id_value, -32602, "invalid thread config override"),
    };
    var cfg = loadConfigForThreadRequest(allocator, state, request_config) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to load config", err);
    };
    defer cfg.deinit(allocator);
    var runtime_requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to load config requirements", err);
    };
    defer runtime_requirements.deinit(allocator);
    validateLifecycleScalarRequirementOverrides(object, request_config, runtime_requirements) catch |err| {
        return renderRuntimeRequirementOverrideError(allocator, id_value, err);
    };
    applyThreadRequestConfigOverrides(allocator, &cfg, request_config, paramPresent(object, "model")) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to apply config override", err);
    };
    applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to apply config requirements", err);
    };

    if (object.get("history")) |history| {
        if (history != .null) {
            var thread = createLoadedThreadFromHistoryParamsWithSource(allocator, cfg, object, history.array.items, state.session_source) catch |err| switch (err) {
                error.EmptyHistory => return renderJsonRpcError(allocator, id_value, -32600, "history must not be empty"),
                error.InvalidHistory => return renderJsonRpcError(allocator, id_value, -32602, "history entries must be response items"),
                else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to create thread from history", err),
            };
            var thread_moved = false;
            errdefer if (!thread_moved) thread.deinit(allocator);
            applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(allocator, &thread, runtime_requirements) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to apply runtime requirements", err);
            };

            var mcp_startup_check = runThreadStartMcpStartupCheck(allocator, state, &cfg) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to initialize MCP servers", err);
            };
            defer mcp_startup_check.deinit(allocator);
            if (mcp_startup_check.required_failure_message) |message| {
                try queueThreadStartMcpStartupNotifications(allocator, state, &mcp_startup_check);
                const response = try renderJsonRpcError(allocator, id_value, -32603, message);
                thread.deinit(allocator);
                thread_moved = true;
                return response;
            }

            const include_turns = !(optionalBoolParam(object, "excludeTurns") orelse false);
            const result = try renderThreadResumeResponse(allocator, &thread, include_turns, state.experimental_api_enabled, object);
            defer allocator.free(result);

            const subscription_added = try ensureThreadSubscribed(allocator, state, thread.id);
            var subscription_committed = false;
            errdefer {
                if (subscription_added and !subscription_committed) _ = removeThreadSubscription(allocator, state, thread.id);
            }
            try upsertLoadedThread(allocator, state, thread);
            thread_moved = true;
            subscription_committed = true;
            if (include_turns) try queueThreadTokenUsageNotification(allocator, state, &thread);
            try queueThreadLifecycleMcpStartupSuccess(allocator, state, cfg.codex_home, &mcp_startup_check);
            try queueConfigStartupNotifications(allocator, state, cfg, thread.id);
            try queueDeprecatedApprovalPolicyWarningNotification(allocator, state, &thread);
            try queueHookStartupWarningNotifications(allocator, state, cfg.codex_home, thread.id);

            return renderJsonRpcResult(allocator, id_value, result);
        }
    }

    const resume_path_raw = try threadResumePathIncludingStateDb(allocator, cfg.codex_home, configSqliteHome(cfg), object);
    defer allocator.free(resume_path_raw);

    var transcript = session_store.loadTranscript(allocator, resume_path_raw) catch |err| switch (err) {
        error.FileNotFound => return renderNoRolloutFoundForThreadResume(allocator, id_value, object),
        else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to load transcript", err),
    };
    defer transcript.deinit(allocator);

    const resume_path = std.Io.Dir.cwd().realPathFileAlloc(std.Io.Threaded.global_single_threaded.io(), resume_path_raw, allocator) catch |err| switch (err) {
        error.FileNotFound => return renderNoRolloutFoundForThreadResume(allocator, id_value, object),
        else => return err,
    };
    defer allocator.free(resume_path);

    var thread = createLoadedThreadFromResumeParams(allocator, cfg, object, resume_path, &transcript) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to create thread", err);
    };
    var thread_moved = false;
    errdefer if (!thread_moved) thread.deinit(allocator);
    applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(allocator, &thread, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to apply runtime requirements", err);
    };
    applyStateResumeMetadata(allocator, configSqliteHome(cfg), object, &thread) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to apply state metadata", err);
    };

    var mcp_startup_check = runThreadStartMcpStartupCheck(allocator, state, &cfg) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/resume failed to initialize MCP servers", err);
    };
    defer mcp_startup_check.deinit(allocator);
    if (mcp_startup_check.required_failure_message) |message| {
        try queueThreadStartMcpStartupNotifications(allocator, state, &mcp_startup_check);
        const response = try renderJsonRpcError(allocator, id_value, -32603, message);
        thread.deinit(allocator);
        thread_moved = true;
        return response;
    }

    const include_turns = !(optionalBoolParam(object, "excludeTurns") orelse false);
    const result = try renderThreadResumeResponse(allocator, &thread, include_turns, state.experimental_api_enabled, object);
    defer allocator.free(result);

    const subscription_added = try ensureThreadSubscribed(allocator, state, thread.id);
    var subscription_committed = false;
    errdefer {
        if (subscription_added and !subscription_committed) _ = removeThreadSubscription(allocator, state, thread.id);
    }
    try upsertLoadedThread(allocator, state, thread);
    thread_moved = true;
    subscription_committed = true;
    if (include_turns) try queueThreadTokenUsageNotification(allocator, state, &thread);
    try queueThreadLifecycleMcpStartupSuccess(allocator, state, cfg.codex_home, &mcp_startup_check);
    try queueConfigStartupNotifications(allocator, state, cfg, thread.id);
    try queueDeprecatedApprovalPolicyWarningNotification(allocator, state, &thread);
    try queueHookStartupWarningNotifications(allocator, state, cfg.codex_home, thread.id);

    return renderJsonRpcResult(allocator, id_value, result);
}

fn handleThreadFork(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (validateThreadForkParams(params_value)) |message| {
        return renderJsonRpcError(allocator, id_value, -32602, message);
    }
    const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
        error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, "thread/fork"),
    };
    const request_config = threadRequestConfigFromParams(object) catch |err| switch (err) {
        error.InvalidThreadRequestConfig => return renderJsonRpcError(allocator, id_value, -32602, "invalid thread config override"),
    };

    var cfg = loadConfigForThreadRequest(allocator, state, request_config) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to load config", err);
    };
    defer cfg.deinit(allocator);
    var runtime_requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to load config requirements", err);
    };
    defer runtime_requirements.deinit(allocator);
    validateLifecycleScalarRequirementOverrides(object, request_config, runtime_requirements) catch |err| {
        return renderRuntimeRequirementOverrideError(allocator, id_value, err);
    };
    applyThreadRequestConfigOverrides(allocator, &cfg, request_config, paramPresent(object, "model")) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to apply config override", err);
    };
    applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to apply config requirements", err);
    };

    if (optionalStringParam(object, "path")) |path| {
        var source = createLoadedThreadFromForkPath(allocator, cfg, object, path) catch |err| switch (err) {
            error.FileNotFound => return renderNoRolloutFoundForThreadResume(allocator, id_value, object),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to load source transcript", err),
        };
        defer source.deinit(allocator);
        return handleThreadForkWithSource(allocator, state, id_value, object, cfg, &source, runtime_requirements);
    }

    const source_thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
        error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
    };
    if (threadTargetIsLast(source_thread_id)) {
        var stored_source = createStoredThreadFromParams(allocator, cfg, object) catch |err| switch (err) {
            error.FileNotFound, error.NoSavedSessions => return renderNoRolloutFoundForThreadResume(allocator, id_value, object),
            error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, "thread/fork"),
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to load source transcript", err),
        };
        defer stored_source.deinit(allocator);
        return handleThreadForkWithSource(allocator, state, id_value, object, cfg, &stored_source, runtime_requirements);
    }
    if (!isUuidString(source_thread_id)) {
        return renderInvalidThreadId(allocator, id_value, source_thread_id);
    }
    if (findLoadedThread(state, source_thread_id)) |source| {
        return handleThreadForkWithSource(allocator, state, id_value, object, cfg, source, runtime_requirements);
    }

    var stored_source = createStoredThreadFromParamsIncludingArchived(allocator, cfg, object) catch |err| switch (err) {
        error.FileNotFound => return renderThreadNotFound(allocator, id_value, source_thread_id),
        error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, "thread/fork"),
        else => return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to load source transcript", err),
    };
    defer stored_source.deinit(allocator);
    return handleThreadForkWithSource(allocator, state, id_value, object, cfg, &stored_source, runtime_requirements);
}

fn handleThreadForkWithSource(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params: std.json.ObjectMap,
    cfg: config.Config,
    source: *const LoadedThread,
    runtime_requirements: ConfigRequirementsReadRequirements,
) ![]const u8 {
    var thread = createLoadedThreadFromForkParamsWithSource(allocator, cfg, params, source, state.session_source) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to create thread", err);
    };
    var thread_moved = false;
    errdefer if (!thread_moved) thread.deinit(allocator);
    applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(allocator, &thread, runtime_requirements) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "thread/fork failed to apply runtime requirements", err);
    };

    const include_turns = !(optionalBoolParam(params, "excludeTurns") orelse false);
    const result = try renderThreadLifecycleResponse(allocator, &thread, include_turns, state.experimental_api_enabled);
    defer allocator.free(result);
    const started_notification = try renderThreadStartedNotification(allocator, &thread);
    var notification_moved = false;
    errdefer if (!notification_moved) allocator.free(started_notification);

    const subscription_added = try ensureThreadSubscribed(allocator, state, thread.id);
    var subscription_committed = false;
    errdefer {
        if (subscription_added and !subscription_committed) _ = removeThreadSubscription(allocator, state, thread.id);
    }
    try state.loaded_threads.append(allocator, thread);
    thread_moved = true;
    subscription_committed = true;
    if (include_turns) try queueThreadTokenUsageNotification(allocator, state, &thread);
    try queueThreadStartedNotification(allocator, state, started_notification);
    notification_moved = true;
    try queueConfigStartupNotifications(allocator, state, cfg, thread.id);
    try queueDeprecatedApprovalPolicyWarningNotification(allocator, state, &thread);
    try queueHookStartupWarningNotifications(allocator, state, cfg.codex_home, thread.id);

    return renderJsonRpcResult(allocator, id_value, result);
}

fn threadStartObjectParams(params_value: ?std.json.Value) ?std.json.ObjectMap {
    const params = params_value orelse return null;
    if (params != .object) return null;
    return params.object;
}

fn applyThreadStartProjectTrustAndConfig(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    params: ?std.json.ObjectMap,
    start_permission_profile: ?*const config.SandboxPermissionProfile,
) !void {
    const requested_cwd = optionalStringParam(params, "cwd") orelse return;
    const cwd = try realPathFileAllocPlain(allocator, requested_cwd);
    defer allocator.free(cwd);

    const config_path = try config.configTomlPath(allocator, cfg.codex_home);
    defer allocator.free(config_path);

    var user_config_bytes = try config.readConfigTomlFile(allocator, config_path);
    defer if (user_config_bytes) |bytes| allocator.free(bytes);

    const should_trust_project = try threadStartShouldTrustProject(allocator, cwd, params, cfg.*, start_permission_profile);
    if (!(try threadStartProjectTrustedByConfig(allocator, user_config_bytes orelse "", cwd)) and should_trust_project) {
        try persistThreadStartProjectTrust(allocator, config_path, user_config_bytes orelse "", cwd);
        if (user_config_bytes) |bytes| allocator.free(bytes);
        user_config_bytes = null;
        user_config_bytes = try config.readConfigTomlFile(allocator, config_path);
    }

    try applyProjectLayersToConfigFromUserBytes(allocator, cfg, cwd, user_config_bytes orelse "");
}

fn applyProjectLayersToConfigForCwd(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    cwd: []const u8,
) !void {
    const config_path = try config.configTomlPath(allocator, cfg.codex_home);
    defer allocator.free(config_path);

    const user_config_bytes = try config.readConfigTomlFile(allocator, config_path);
    defer if (user_config_bytes) |bytes| allocator.free(bytes);

    try applyProjectLayersToConfigFromUserBytes(allocator, cfg, cwd, user_config_bytes orelse "");
}

fn applyProjectLayersToConfigFromUserBytes(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    cwd: []const u8,
    user_config_bytes: []const u8,
) !void {
    var project_layers = try loadConfigReadProjectLayers(allocator, cwd, cfg.codex_home, user_config_bytes);
    defer project_layers.deinit(allocator);
    try applyThreadStartProjectLayersToConfig(allocator, cfg, project_layers);
}

fn threadStartProjectTrustedByConfig(
    allocator: std.mem.Allocator,
    user_config_bytes: []const u8,
    cwd: []const u8,
) !bool {
    var trusted_ancestors = try configReadTrustedProjectAncestors(allocator, cwd, user_config_bytes);
    defer trusted_ancestors.deinit(allocator);
    return trusted_ancestors.items.len > 0;
}

fn threadStartShouldTrustProject(
    allocator: std.mem.Allocator,
    cwd: []const u8,
    params: ?std.json.ObjectMap,
    cfg: config.Config,
    start_permission_profile: ?*const config.SandboxPermissionProfile,
) !bool {
    if (optionalStringParam(params, "sandbox")) |sandbox| {
        return std.mem.eql(u8, sandbox, "workspace-write") or
            std.mem.eql(u8, sandbox, "danger-full-access");
    }
    if (start_permission_profile) |profile| {
        return sandboxPermissionProfileTrustsProject(allocator, cwd, profile);
    }
    return cfg.sandbox_mode == .workspace_write or cfg.sandbox_mode == .danger_full_access;
}

fn sandboxPermissionProfileTrustsProject(
    allocator: std.mem.Allocator,
    cwd: []const u8,
    profile: *const config.SandboxPermissionProfile,
) !bool {
    if (profile.mode == .danger_full_access) return true;
    if (profile.mode != .workspace_write) return false;
    if (profile.include_cwd_write_root) return true;

    for (profile.additional_writable_roots.items) |root| {
        const resolved = if (std.fs.path.isAbsolute(root))
            try std.fs.path.resolve(allocator, &.{root})
        else
            try std.fs.path.resolve(allocator, &.{ cwd, root });
        defer allocator.free(resolved);
        if (pathWithinOrEqual(resolved, cwd)) return true;
    }
    return false;
}

fn pathWithinOrEqual(parent: []const u8, child: []const u8) bool {
    if (!std.mem.startsWith(u8, child, parent)) return false;
    if (child.len == parent.len) return true;
    if (parent.len == 0) return false;
    return parent[parent.len - 1] == std.fs.path.sep or child[parent.len] == std.fs.path.sep;
}

fn persistThreadStartProjectTrust(
    allocator: std.mem.Allocator,
    config_path: []const u8,
    user_config_bytes: []const u8,
    cwd: []const u8,
) !void {
    const trust_target = try resolveThreadStartProjectTrustTarget(allocator, cwd);
    defer allocator.free(trust_target);

    const key_path = try projectTrustKeyPath(allocator, trust_target);
    defer allocator.free(key_path);

    const updated = try config.updateTomlRawValueForKeyPath(allocator, user_config_bytes, key_path, "\"trusted\"");
    defer allocator.free(updated);
    try config.writeConfigTomlFile(config_path, updated);
}

fn resolveThreadStartProjectTrustTarget(allocator: std.mem.Allocator, cwd: []const u8) ![]const u8 {
    if (try resolveProjectTrustRepoRoot(allocator, cwd)) |repo_root| return repo_root;
    return threadStartProjectTrustSearchBase(allocator, cwd);
}

fn resolveProjectTrustRepoRoot(allocator: std.mem.Allocator, cwd: []const u8) !?[]const u8 {
    var current = try threadStartProjectTrustSearchBase(allocator, cwd);
    errdefer allocator.free(current);

    while (true) {
        const dot_git_path = try std.fs.path.join(allocator, &.{ current, ".git" });
        defer allocator.free(dot_git_path);

        const dot_git_stat = statPathNoFollow(allocator, dot_git_path) catch |err| switch (err) {
            error.NotDir => null,
            else => return err,
        };
        if (dot_git_stat) |metadata| {
            if (std.c.S.ISDIR(@intCast(metadata.mode))) return current;
            if (try resolveThreadStartWorktreeTrustTarget(allocator, current, dot_git_path)) |main_root| {
                allocator.free(current);
                return main_root;
            }
            return current;
        }

        const parent = std.fs.path.dirname(current) orelse break;
        const next = try allocator.dupe(u8, parent);
        allocator.free(current);
        current = next;
    }

    allocator.free(current);
    return null;
}

fn threadStartProjectTrustSearchBase(allocator: std.mem.Allocator, cwd: []const u8) ![]const u8 {
    const stat = (try statPathFollow(allocator, cwd)) orelse return allocator.dupe(u8, cwd);
    if (std.c.S.ISDIR(@intCast(stat.mode))) return allocator.dupe(u8, cwd);
    const parent = std.fs.path.dirname(cwd) orelse return allocator.dupe(u8, cwd);
    return allocator.dupe(u8, parent);
}

fn resolveThreadStartWorktreeTrustTarget(
    allocator: std.mem.Allocator,
    worktree_root: []const u8,
    dot_git_path: []const u8,
) !?[]const u8 {
    const bytes = std.Io.Dir.cwd().readFileAlloc(std.Io.Threaded.global_single_threaded.io(), dot_git_path, allocator, .limited(4096)) catch |err| switch (err) {
        error.FileNotFound, error.NotDir, error.AccessDenied, error.PermissionDenied => return null,
        else => return err,
    };
    defer allocator.free(bytes);

    const trimmed = std.mem.trim(u8, bytes, " \t\r\n");
    const prefix = "gitdir:";
    if (!std.mem.startsWith(u8, trimmed, prefix)) return null;
    const raw_gitdir = std.mem.trim(u8, trimmed[prefix.len..], " \t\r\n");
    if (raw_gitdir.len == 0) return null;

    const gitdir = if (std.fs.path.isAbsolute(raw_gitdir))
        try allocator.dupe(u8, raw_gitdir)
    else
        try std.fs.path.join(allocator, &.{ worktree_root, raw_gitdir });
    defer allocator.free(gitdir);

    const worktrees_dir = std.fs.path.dirname(gitdir) orelse return null;
    const worktrees_name = std.fs.path.basename(worktrees_dir);
    if (!std.mem.eql(u8, worktrees_name, "worktrees")) return null;

    const common_git_dir = std.fs.path.dirname(worktrees_dir) orelse return null;
    const main_root = std.fs.path.dirname(common_git_dir) orelse return null;
    return realPathFileAllocPlain(allocator, main_root) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => try allocator.dupe(u8, main_root),
        else => return err,
    };
}

fn projectTrustKeyPath(allocator: std.mem.Allocator, trust_target: []const u8) ![]const u8 {
    var key_path = std.ArrayList(u8).empty;
    errdefer key_path.deinit(allocator);
    try key_path.appendSlice(allocator, "projects.");
    try appendTomlBasicStringLiteral(allocator, &key_path, trust_target);
    try key_path.appendSlice(allocator, ".trust_level");
    return key_path.toOwnedSlice(allocator);
}

fn appendTomlBasicStringLiteral(
    allocator: std.mem.Allocator,
    output: *std.ArrayList(u8),
    value: []const u8,
) !void {
    try output.append(allocator, '"');
    for (value) |byte| {
        switch (byte) {
            '"' => try output.appendSlice(allocator, "\\\""),
            '\\' => try output.appendSlice(allocator, "\\\\"),
            '\n' => try output.appendSlice(allocator, "\\n"),
            '\r' => try output.appendSlice(allocator, "\\r"),
            '\t' => try output.appendSlice(allocator, "\\t"),
            else => try output.append(allocator, byte),
        }
    }
    try output.append(allocator, '"');
}

fn applyThreadStartProjectLayersToConfig(
    allocator: std.mem.Allocator,
    cfg: *config.Config,
    project_layers: ConfigReadProjectLayers,
) !void {
    if (project_layers.model()) |value| try replaceConfigOwnedString(allocator, &cfg.model, value);
    if (project_layers.modelContextWindow()) |value| cfg.model_context_window = value;
    if (project_layers.modelAutoCompactTokenLimit()) |value| cfg.model_auto_compact_token_limit = value;
    if (project_layers.instructions()) |value| try replaceConfigOptionalString(allocator, &cfg.base_instructions, value);
    if (project_layers.developerInstructions()) |value| try replaceConfigOptionalString(allocator, &cfg.developer_instructions, value);
    if (project_layers.compactPrompt()) |value| try replaceConfigOptionalString(allocator, &cfg.compact_prompt, value);
    if (project_layers.approvalPolicy()) |value| cfg.approval_policy = value;
    if (project_layers.approvalsReviewer()) |value| cfg.approvals_reviewer = value;
    if (project_layers.sandboxMode()) |value| cfg.sandbox_mode = value;
    if (project_layers.webSearchMode()) |value| cfg.web_search_mode = value;
    if (project_layers.modelReasoningEffort()) |value| cfg.model_reasoning_effort = value;
    if (project_layers.modelVerbosity()) |value| cfg.model_verbosity = value;
    if (project_layers.serviceTier()) |value| try replaceConfigOptionalString(allocator, &cfg.service_tier, value);
    if (project_layers.forcedLoginMethod()) |value| cfg.forced_login_method = value;
    if (project_layers.forcedChatGptWorkspaceId()) |value| {
        try replaceConfigOptionalString(allocator, &cfg.forced_chatgpt_workspace_id, value);
    }
}

fn replaceConfigOwnedString(allocator: std.mem.Allocator, slot: *[]const u8, value: []const u8) !void {
    const copy = try allocator.dupe(u8, value);
    allocator.free(slot.*);
    slot.* = copy;
}

fn replaceConfigOptionalString(allocator: std.mem.Allocator, slot: *?[]const u8, value: []const u8) !void {
    const copy = try allocator.dupe(u8, value);
    if (slot.*) |existing| allocator.free(existing);
    slot.* = copy;
}

fn threadResumePath(allocator: std.mem.Allocator, codex_home: []const u8, params: std.json.ObjectMap) ![]const u8 {
    if (optionalStringParam(params, "path")) |path| {
        return allocator.dupe(u8, path);
    }
    const thread_id = requiredThreadIdParam(params) catch return error.InvalidThreadParams;
    return session_store.resolveResumePath(allocator, codex_home, thread_id);
}

fn threadTargetIsLast(target: []const u8) bool {
    const trimmed = std.mem.trim(u8, target, " \t\r\n");
    return std.ascii.eqlIgnoreCase(trimmed, "last");
}

fn threadResumePathIncludingStateDb(allocator: std.mem.Allocator, codex_home: []const u8, sqlite_home: []const u8, params: std.json.ObjectMap) ![]const u8 {
    const path = try threadResumePath(allocator, codex_home, params);
    errdefer allocator.free(path);
    if (optionalStringParam(params, "path") != null) return path;

    const io = std.Io.Threaded.global_single_threaded.io();
    _ = std.Io.Dir.cwd().statFile(io, path, .{ .follow_symlinks = true }) catch |err| switch (err) {
        error.FileNotFound => {
            const thread_id = requiredThreadIdParam(params) catch return error.InvalidThreadParams;
            const state_path = (try thread_state.findRolloutPathByThreadId(allocator, codex_home, sqlite_home, thread_id)) orelse return path;
            allocator.free(path);
            return state_path;
        },
        else => return path,
    };
    return path;
}

fn createStoredThreadFromParams(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
) !LoadedThread {
    const resume_path_raw = try threadResumePath(allocator, cfg.codex_home, params);
    defer allocator.free(resume_path_raw);

    return createStoredThreadFromPath(allocator, cfg, params, resume_path_raw);
}

fn createStoredThreadFromParamsIncludingStateDb(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
) !LoadedThread {
    return createStoredThreadFromParams(allocator, cfg, params) catch |err| switch (err) {
        error.FileNotFound => createStateDbStoredThreadFromParams(allocator, cfg, params),
        else => err,
    };
}

fn createStoredThreadFromParamsIncludingArchived(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
) !LoadedThread {
    return createStoredThreadFromParams(allocator, cfg, params) catch |err| switch (err) {
        error.FileNotFound => createArchivedOrStateDbStoredThreadFromParams(allocator, cfg, params),
        else => err,
    };
}

fn createArchivedOrStateDbStoredThreadFromParams(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
) !LoadedThread {
    return createArchivedStoredThreadFromParams(allocator, cfg, params) catch |err| switch (err) {
        error.FileNotFound => createStateDbStoredThreadFromParams(allocator, cfg, params),
        else => err,
    };
}

fn createArchivedStoredThreadFromParams(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
) !LoadedThread {
    const thread_id = requiredThreadIdParam(params) catch return error.InvalidThreadParams;
    const archived_path = try session_store.resolveArchivedRolloutPath(allocator, cfg.codex_home, thread_id);
    defer allocator.free(archived_path);
    return createStoredThreadFromPath(allocator, cfg, params, archived_path);
}

fn createStateDbStoredThreadFromParams(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
) !LoadedThread {
    const thread_id = requiredThreadIdParam(params) catch return error.InvalidThreadParams;
    const state_path = (try thread_state.findRolloutPathByThreadId(allocator, cfg.codex_home, configSqliteHome(cfg), thread_id)) orelse return error.FileNotFound;
    defer allocator.free(state_path);
    var thread = try createStoredThreadFromPath(allocator, cfg, params, state_path);
    errdefer thread.deinit(allocator);
    const metadata = try thread_state.findThreadMetadataByThreadId(allocator, configSqliteHome(cfg), thread_id);
    defer if (metadata) |value| value.deinit(allocator);
    if (metadata) |value| try applyStateThreadMetadata(allocator, &thread, value);
    try applyStateThreadGoal(allocator, configSqliteHome(cfg), &thread);
    return thread;
}

fn createStoredThreadFromPath(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
    path_raw: []const u8,
) !LoadedThread {
    var transcript = try session_store.loadTranscript(allocator, path_raw);
    defer transcript.deinit(allocator);

    const resume_path = try std.Io.Dir.cwd().realPathFileAlloc(std.Io.Threaded.global_single_threaded.io(), path_raw, allocator);
    defer allocator.free(resume_path);

    var thread = try createLoadedThreadFromResumeParams(allocator, cfg, params, resume_path, &transcript);
    errdefer thread.deinit(allocator);
    try applyIndexedThreadName(allocator, cfg.codex_home, &thread);
    return thread;
}

fn applyIndexedThreadName(allocator: std.mem.Allocator, codex_home: []const u8, thread: *LoadedThread) !void {
    const indexed_name = try session_store.findThreadName(allocator, codex_home, thread.id);
    defer if (indexed_name) |value| allocator.free(value);
    const name = indexed_name orelse return;
    const name_copy = try allocator.dupe(u8, name);
    if (thread.name) |value| allocator.free(value);
    thread.name = name_copy;
}

const StateThreadMetadataApplyOptions = struct {
    apply_model_runtime: bool = true,
    apply_cwd: bool = true,
};

fn applyStateThreadMetadata(allocator: std.mem.Allocator, thread: *LoadedThread, metadata: thread_state.ThreadMetadata) !void {
    try applyStateThreadMetadataWithOptions(allocator, thread, metadata, .{});
}

fn applyStateResumeMetadata(
    allocator: std.mem.Allocator,
    sqlite_home: []const u8,
    params: std.json.ObjectMap,
    thread: *LoadedThread,
) !void {
    const metadata = try thread_state.findThreadMetadataByThreadId(allocator, sqlite_home, thread.id);
    defer if (metadata) |value| value.deinit(allocator);
    if (metadata) |value| {
        try applyStateThreadMetadataWithOptions(allocator, thread, value, .{
            .apply_model_runtime = !threadResumeHasModelRuntimeOverride(params),
            .apply_cwd = optionalStringParam(params, "cwd") == null,
        });
    }
    try applyStateThreadGoal(allocator, sqlite_home, thread);
}

fn applyStateThreadMetadataWithOptions(
    allocator: std.mem.Allocator,
    thread: *LoadedThread,
    metadata: thread_state.ThreadMetadata,
    options: StateThreadMetadataApplyOptions,
) !void {
    thread.summary_created_at_ms = metadata.created_at_ms;
    thread.summary_updated_at_ms = metadata.updated_at_ms;
    if (stateThreadString(metadata.first_user_message)) |preview| {
        try replaceOwnedString(allocator, &thread.preview, preview);
    }
    if (stateThreadTitle(metadata.title, thread.preview)) |title| {
        try replaceOptionalOwnedString(allocator, &thread.name, title);
    }
    if (metadata.memory_mode) |memory_mode| {
        try thread.transcript.setMemoryMode(allocator, memory_mode);
    }
    if (options.apply_model_runtime) {
        if (stateThreadString(metadata.model)) |model| {
            try replaceOwnedString(allocator, &thread.model, model);
            thread.runtime_overrides.model = true;
        }
        if (stateThreadString(metadata.model_provider)) |model_provider| {
            try replaceOwnedString(allocator, &thread.model_provider, model_provider);
            try thread.transcript.setModelProvider(allocator, model_provider);
            thread.runtime_overrides.model_provider = true;
        }
        if (stateThreadReasoningEffort(metadata.reasoning_effort)) |reasoning_effort| {
            try replaceOptionalOwnedString(allocator, &thread.reasoning_effort, reasoning_effort);
            thread.runtime_overrides.reasoning_effort = true;
        }
    }
    if (options.apply_cwd) {
        if (stateThreadString(metadata.cwd)) |cwd| {
            try replaceOwnedString(allocator, &thread.cwd, cwd);
            try thread.transcript.setCwd(allocator, cwd);
        }
    }
    if (stateThreadString(metadata.cli_version)) |cli_version| {
        try replaceOwnedString(allocator, &thread.cli_version, cli_version);
        try thread.transcript.setCliVersion(allocator, cli_version);
    }
    if (metadata.lifecycle_loaded) {
        if (metadata.created_at_ms) |value| thread.created_at = @divFloor(value, 1000);
        if (metadata.updated_at_ms) |value| thread.updated_at = @divFloor(value, 1000);
        if (metadata.source) |source| {
            const normalized_source = try session_store.normalizeSessionSourceText(allocator, source);
            defer allocator.free(normalized_source);
            try replaceOwnedString(allocator, &thread.source, normalized_source);
            try thread.transcript.setSource(allocator, normalized_source);
        }
        if (metadata.thread_source) |thread_source| {
            try replaceOptionalOwnedString(allocator, &thread.thread_source, thread_source);
            try thread.transcript.setThreadSource(allocator, thread_source);
        } else {
            clearOptionalOwnedString(allocator, &thread.thread_source);
        }
        if (metadata.agent_nickname) |agent_nickname| {
            try replaceOptionalOwnedString(allocator, &thread.agent_nickname, agent_nickname);
        } else {
            clearOptionalOwnedString(allocator, &thread.agent_nickname);
        }
        if (metadata.agent_role) |agent_role| {
            try replaceOptionalOwnedString(allocator, &thread.agent_role, agent_role);
        } else {
            clearOptionalOwnedString(allocator, &thread.agent_role);
        }
    }
    try replaceStateMetadataGitInfo(allocator, &thread.git_sha, metadata.git_sha);
    try replaceStateMetadataGitInfo(allocator, &thread.git_branch, metadata.git_branch);
    try replaceStateMetadataGitInfo(allocator, &thread.git_origin_url, metadata.git_origin_url);
    try syncLoadedThreadGitInfoToTranscript(allocator, thread);
}

fn threadResumeHasModelRuntimeOverride(params: std.json.ObjectMap) bool {
    if (optionalStringParam(params, "model") != null) return true;
    if (optionalStringParam(params, "modelProvider") != null) return true;
    const config_value = params.get("config") orelse return false;
    if (config_value != .object) return false;
    if (config_value.object.get("oss") != null) return true;
    return config_value.object.get("profile") != null or
        config_value.object.get("model") != null or
        config_value.object.get("model_provider") != null or
        config_value.object.get("model_reasoning_effort") != null;
}

test "thread resume treats request profile as model runtime override" {
    const allocator = std.testing.allocator;
    var with_profile = try std.json.parseFromSlice(std.json.Value, allocator, "{\"config\":{\"profile\":\"work\"}}", .{});
    defer with_profile.deinit();
    try std.testing.expect(threadResumeHasModelRuntimeOverride(with_profile.value.object));

    var with_web_search = try std.json.parseFromSlice(std.json.Value, allocator, "{\"config\":{\"web_search\":\"live\"}}", .{});
    defer with_web_search.deinit();
    try std.testing.expect(!threadResumeHasModelRuntimeOverride(with_web_search.value.object));

    var with_oss = try std.json.parseFromSlice(std.json.Value, allocator, "{\"config\":{\"oss\":true,\"oss_provider\":\"ollama\"}}", .{});
    defer with_oss.deinit();
    try std.testing.expect(threadResumeHasModelRuntimeOverride(with_oss.value.object));

    var with_oss_clear = try std.json.parseFromSlice(std.json.Value, allocator, "{\"config\":{\"oss\":false}}", .{});
    defer with_oss_clear.deinit();
    try std.testing.expect(threadResumeHasModelRuntimeOverride(with_oss_clear.value.object));

    var with_oss_null = try std.json.parseFromSlice(std.json.Value, allocator, "{\"config\":{\"oss\":null}}", .{});
    defer with_oss_null.deinit();
    try std.testing.expect(threadResumeHasModelRuntimeOverride(with_oss_null.value.object));
}

fn replaceStateMetadataGitInfo(allocator: std.mem.Allocator, slot: *?[]const u8, value: ?[]const u8) !void {
    if (value) |text| {
        try replaceOptionalOwnedString(allocator, slot, text);
    } else {
        clearOptionalOwnedString(allocator, slot);
    }
}

fn createLoadedThreadFromStartParams(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: ?std.json.ObjectMap,
) !LoadedThread {
    return createLoadedThreadFromStartParamsWithSource(allocator, cfg, params, "appServer");
}

fn createLoadedThreadFromStartParamsWithSource(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: ?std.json.ObjectMap,
    session_source: []const u8,
) !LoadedThread {
    const thread_id = try generateUuidString(allocator);
    errdefer allocator.free(thread_id);
    const session_id = try allocator.dupe(u8, thread_id);
    errdefer allocator.free(session_id);
    const preview = try allocator.dupe(u8, "");
    errdefer allocator.free(preview);
    const source = try allocator.dupe(u8, session_source);
    errdefer allocator.free(source);
    const cli_version = try allocator.dupe(u8, "0.0.1");
    errdefer allocator.free(cli_version);
    const turns_json = try allocator.dupe(u8, "[]");
    errdefer allocator.free(turns_json);
    const request_config = try threadRequestConfigFromParams(params);

    const model = try allocator.dupe(u8, optionalStringParam(params, "model") orelse cfg.model);
    errdefer allocator.free(model);

    const model_verbosity = try threadModelVerbosity(allocator, cfg);
    errdefer if (model_verbosity) |value| allocator.free(value);

    const configured_model_provider = cfg.model_provider_id;
    const model_provider = try allocator.dupe(u8, optionalStringParam(params, "modelProvider") orelse configured_model_provider orelse "openai");
    errdefer allocator.free(model_provider);
    const openai_base_url = try threadOpenaiBaseUrlForRequest(allocator, request_config);
    errdefer if (openai_base_url) |value| allocator.free(value);
    const chatgpt_base_url = try threadChatgptBaseUrlForRequest(allocator, request_config);
    errdefer if (chatgpt_base_url) |value| allocator.free(value);
    const oss_provider = try threadOssProviderForRequest(allocator, cfg, request_config);
    errdefer if (oss_provider) |value| allocator.free(value);

    const service_tier = try threadStartServiceTier(allocator, cfg, params);
    errdefer if (service_tier) |value| allocator.free(value);

    const active_profile = try threadActiveProfile(allocator, cfg);
    errdefer if (active_profile) |value| allocator.free(value);

    const cwd = try threadStartCwd(allocator, params);
    errdefer allocator.free(cwd);

    const approval_policy = try allocator.dupe(u8, optionalStringParam(params, "approvalPolicy") orelse cfg.approval_policy.label());
    errdefer allocator.free(approval_policy);

    const requested_approvals_reviewer = try optionalApprovalsReviewerLifecycleParam(params, "approvalsReviewer");
    const approvals_reviewer = try allocator.dupe(u8, requested_approvals_reviewer orelse cfg.approvals_reviewer.label());
    errdefer allocator.free(approvals_reviewer);

    const sandbox_mode = try allocator.dupe(u8, optionalStringParam(params, "sandbox") orelse cfg.sandbox_mode.label());
    errdefer allocator.free(sandbox_mode);
    var sandbox_writable_roots = try emptyStringList(allocator);
    errdefer sandbox_writable_roots.deinit(allocator);
    var sandbox_read_denied_roots = try emptyStringList(allocator);
    errdefer sandbox_read_denied_roots.deinit(allocator);
    var sandbox_read_denied_globs = try emptyStringList(allocator);
    errdefer sandbox_read_denied_globs.deinit(allocator);

    const reasoning_effort = if (cfg.model_reasoning_effort) |effort|
        try allocator.dupe(u8, effort.label())
    else
        null;
    errdefer if (reasoning_effort) |value| allocator.free(value);

    const reasoning_summary = try threadReasoningSummary(allocator, cfg);
    errdefer if (reasoning_summary) |value| allocator.free(value);

    const personality = try threadPersonality(allocator, cfg, params);
    errdefer if (personality) |value| allocator.free(value);

    const collaboration_mode = try allocator.dupe(u8, "default");
    errdefer allocator.free(collaboration_mode);
    const collaboration_developer_instructions: ?[]const u8 = null;

    const ephemeral = optionalBoolParam(params, "ephemeral") orelse false;
    const path = if (ephemeral)
        null
    else
        try session_store.createSessionPathForId(allocator, cfg.codex_home, thread_id);
    errdefer if (path) |value| allocator.free(value);

    const thread_source = if (optionalStringParam(params, "threadSource")) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (thread_source) |value| allocator.free(value);
    const pending_session_start_source = try allocator.dupe(u8, optionalStringParam(params, "sessionStartSource") orelse "startup");
    errdefer allocator.free(pending_session_start_source);

    var transcript = session_mod.Transcript{};
    errdefer transcript.deinit(allocator);
    try transcript.setId(allocator, thread_id);
    try transcript.setSource(allocator, source);
    try transcript.setModelProvider(allocator, model_provider);
    try syncTranscriptBaseUrls(allocator, &transcript, openai_base_url, chatgpt_base_url);
    try transcript.setCwd(allocator, cwd);
    try transcript.setCliVersion(allocator, cli_version);
    if (thread_source) |value| try transcript.setThreadSource(allocator, value);

    const now = currentUnixSeconds();
    return .{
        .id = thread_id,
        .session_id = session_id,
        .forked_from_id = null,
        .preview = preview,
        .model = model,
        .model_context_window = cfg.model_context_window,
        .model_auto_compact_token_limit = cfg.model_auto_compact_token_limit,
        .model_verbosity = model_verbosity,
        .model_provider = model_provider,
        .openai_base_url = openai_base_url,
        .chatgpt_base_url = chatgpt_base_url,
        .oss_provider = oss_provider,
        .service_tier = service_tier,
        .active_profile = active_profile,
        .cwd = cwd,
        .approval_policy = approval_policy,
        .approvals_reviewer = approvals_reviewer,
        .sandbox_mode = sandbox_mode,
        .sandbox_writable_roots = sandbox_writable_roots,
        .sandbox_read_denied_roots = sandbox_read_denied_roots,
        .sandbox_read_denied_globs = sandbox_read_denied_globs,
        .sandbox_include_cwd_write_root = true,
        .sandbox_network_enabled = defaultNetworkEnabledForSandboxModeLabel(sandbox_mode),
        .sandbox_exclude_tmpdir_env_var = false,
        .sandbox_exclude_slash_tmp = false,
        .sandbox_external = false,
        .web_search_mode = cfg.web_search_mode,
        .reasoning_effort = reasoning_effort,
        .reasoning_summary = reasoning_summary,
        .personality = personality,
        .collaboration_mode = collaboration_mode,
        .collaboration_developer_instructions = collaboration_developer_instructions,
        .runtime_overrides = .{
            .model = paramPresent(params, "model"),
            .model_context_window = false,
            .model_auto_compact_token_limit = false,
            .model_verbosity = false,
            .model_provider = paramPresent(params, "modelProvider") or request_config.model_provider_present,
            .service_tier = paramPresent(params, "serviceTier"),
            .approval_policy = paramPresent(params, "approvalPolicy"),
            .approvals_reviewer = paramPresent(params, "approvalsReviewer"),
            .sandbox_mode = paramPresent(params, "sandbox"),
            .web_search_mode = threadRequestConfigParamPresent(params, "web_search"),
            .reasoning_summary = false,
            .personality = optionalStringParam(params, "personality") != null,
        },
        .ephemeral = ephemeral,
        .path = path,
        .source = source,
        .thread_source = thread_source,
        .agent_nickname = null,
        .agent_role = null,
        .cli_version = cli_version,
        .token_usage = null,
        .token_usage_turn_id = null,
        .name = null,
        .elicitation_count = 0,
        .git_sha = null,
        .git_branch = null,
        .git_origin_url = null,
        .goal = null,
        .transcript = transcript,
        .turns_json = turns_json,
        .next_turn_index = turnCountForTranscript(&transcript),
        .pending_session_start_source = pending_session_start_source,
        .created_at = now,
        .updated_at = now,
    };
}

fn createLoadedThreadFromHistoryParams(
