        .service_tier = service_tier,
        .active_profile = active_profile,
        .cwd = cwd,
        .approval_policy = approval_policy,
        .approvals_reviewer = approvals_reviewer,
        .sandbox_mode = sandbox_mode,
        .sandbox_writable_roots = sandbox_writable_roots,
        .sandbox_read_denied_roots = sandbox_read_denied_roots,
        .sandbox_read_denied_globs = sandbox_read_denied_globs,
        .sandbox_include_cwd_write_root = true,
        .sandbox_network_enabled = defaultNetworkEnabledForSandboxModeLabel(sandbox_mode),
        .sandbox_exclude_tmpdir_env_var = false,
        .sandbox_exclude_slash_tmp = false,
        .sandbox_external = false,
        .web_search_mode = cfg.web_search_mode,
        .reasoning_effort = reasoning_effort,
        .reasoning_summary = reasoning_summary,
        .personality = personality,
        .collaboration_mode = collaboration_mode,
        .collaboration_developer_instructions = collaboration_developer_instructions,
        .runtime_overrides = .{
            .model = paramPresent(params, "model"),
            .model_context_window = false,
            .model_auto_compact_token_limit = false,
            .model_verbosity = false,
            .model_provider = paramPresent(params, "modelProvider") or request_config.model_provider_present,
            .service_tier = paramPresent(params, "serviceTier"),
            .approval_policy = paramPresent(params, "approvalPolicy"),
            .approvals_reviewer = paramPresent(params, "approvalsReviewer"),
            .sandbox_mode = paramPresent(params, "sandbox"),
            .web_search_mode = threadRequestConfigParamPresent(params, "web_search"),
            .reasoning_summary = false,
            .personality = optionalStringParam(params, "personality") != null,
        },
        .ephemeral = false,
        .path = path,
        .source = source,
        .thread_source = null,
        .agent_nickname = null,
        .agent_role = null,
        .cli_version = cli_version,
        .token_usage = null,
        .token_usage_turn_id = null,
        .name = null,
        .elicitation_count = 0,
        .git_sha = null,
        .git_branch = null,
        .git_origin_url = null,
        .goal = null,
        .transcript = transcript,
        .turns_json = turns_json,
        .next_turn_index = turnCountForTranscript(&transcript),
        .pending_session_start_source = pending_session_start_source,
        .created_at = now,
        .updated_at = now,
    };
}

fn createLoadedThreadFromResumeParams(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
    path: []const u8,
    transcript: *const session_mod.Transcript,
) !LoadedThread {
    const thread_id = if (transcript.id) |value|
        try allocator.dupe(u8, value)
    else
        try session_store.sessionIdFromPath(allocator, path);
    errdefer allocator.free(thread_id);
    const session_id = try allocator.dupe(u8, thread_id);
    errdefer allocator.free(session_id);
    const forked_from_id = if (transcript.forked_from_id) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (forked_from_id) |value| allocator.free(value);
    const preview = try resumePreview(allocator, transcript);
    errdefer allocator.free(preview);
    const path_copy = try allocator.dupe(u8, path);
    errdefer allocator.free(path_copy);
    const source = try allocator.dupe(u8, transcript.source orelse "cli");
    errdefer allocator.free(source);
    const thread_source = if (transcript.thread_source) |value| try allocator.dupe(u8, value) else null;
    errdefer if (thread_source) |value| allocator.free(value);
    const cli_version = try allocator.dupe(u8, transcript.cli_version orelse "0.0.1");
    errdefer allocator.free(cli_version);
    const token_usage_turn_id = try transcriptTokenUsageTurnId(allocator, transcript);
    errdefer if (token_usage_turn_id) |value| allocator.free(value);
    const name = if (transcript.title) |title| try allocator.dupe(u8, title) else null;
    errdefer if (name) |value| allocator.free(value);
    const git_sha = if (transcript.git_sha) |value| try allocator.dupe(u8, value) else null;
    errdefer if (git_sha) |value| allocator.free(value);
    const git_branch = if (transcript.git_branch) |value| try allocator.dupe(u8, value) else null;
    errdefer if (git_branch) |value| allocator.free(value);
    const git_origin_url = if (transcript.git_origin_url) |value| try allocator.dupe(u8, value) else null;
    errdefer if (git_origin_url) |value| allocator.free(value);
    const turns_json = try renderTranscriptTurnsJson(allocator, transcript, true);
    errdefer allocator.free(turns_json);
    var transcript_copy = try transcript.clone(allocator);
    errdefer transcript_copy.deinit(allocator);
    var goal = try loadedThreadGoalFromSessionGoal(allocator, transcript.goal);
    errdefer if (goal) |*value| value.deinit(allocator);
    if (goal) |*value| {
        const goal_usage_tokens = if (transcript.token_usage) |usage_info| goalUsageTokensFromUsage(usage_info.total) else 0;
        value.token_usage_start_total = loadedThreadGoalStartTotalForSavedUsage(goal_usage_tokens, value.tokens_used);
    }

    const request_config = try threadRequestConfigFromParams(params);
    const use_request_profile = request_config.profile_present;

    const model = try allocator.dupe(u8, optionalStringParam(params, "model") orelse cfg.model);
    errdefer allocator.free(model);

    const model_verbosity = try threadModelVerbosity(allocator, cfg);
    errdefer if (model_verbosity) |value| allocator.free(value);

    const configured_model_provider = cfg.model_provider_id;
    const requested_model_provider = optionalStringParam(params, "modelProvider");
    const use_request_model_provider = use_request_profile or request_config.model_provider_present;
    const reset_provider_state = use_request_model_provider or requested_model_provider != null;
    const default_model_provider = if (use_request_model_provider)
        configured_model_provider orelse "openai"
    else
        transcript.model_provider orelse configured_model_provider orelse "openai";
    const model_provider = try allocator.dupe(u8, requested_model_provider orelse default_model_provider);
    errdefer allocator.free(model_provider);
    const openai_base_url = try resumeThreadOpenaiBaseUrlForRequest(allocator, request_config, reset_provider_state, transcript);
    errdefer if (openai_base_url) |value| allocator.free(value);
    const chatgpt_base_url = try resumeThreadChatgptBaseUrlForRequest(allocator, request_config, reset_provider_state, transcript);
    errdefer if (chatgpt_base_url) |value| allocator.free(value);
    const oss_provider = try threadOssProviderForRequest(allocator, cfg, request_config);
    errdefer if (oss_provider) |value| allocator.free(value);

    const service_tier = try threadStartServiceTier(allocator, cfg, params);
    errdefer if (service_tier) |value| allocator.free(value);

    const active_profile = try threadActiveProfile(allocator, cfg);
    errdefer if (active_profile) |value| allocator.free(value);

    const cwd = try threadResumeCwd(allocator, transcript, params);
    errdefer allocator.free(cwd);
    try transcript_copy.setCwd(allocator, cwd);
    try transcript_copy.setModelProvider(allocator, model_provider);
    try syncTranscriptBaseUrls(allocator, &transcript_copy, openai_base_url, chatgpt_base_url);

    const approval_policy = try allocator.dupe(u8, optionalStringParam(params, "approvalPolicy") orelse cfg.approval_policy.label());
    errdefer allocator.free(approval_policy);

    const requested_approvals_reviewer = try optionalApprovalsReviewerParam(params, "approvalsReviewer");
    const approvals_reviewer = try allocator.dupe(u8, requested_approvals_reviewer orelse cfg.approvals_reviewer.label());
    errdefer allocator.free(approvals_reviewer);

    const sandbox_mode = try allocator.dupe(u8, optionalStringParam(params, "sandbox") orelse cfg.sandbox_mode.label());
    errdefer allocator.free(sandbox_mode);
    var sandbox_writable_roots = try emptyStringList(allocator);
    errdefer sandbox_writable_roots.deinit(allocator);
    var sandbox_read_denied_roots = try emptyStringList(allocator);
    errdefer sandbox_read_denied_roots.deinit(allocator);
    var sandbox_read_denied_globs = try emptyStringList(allocator);
    errdefer sandbox_read_denied_globs.deinit(allocator);

    const reasoning_effort = if (cfg.model_reasoning_effort) |effort|
        try allocator.dupe(u8, effort.label())
    else
        null;
    errdefer if (reasoning_effort) |value| allocator.free(value);

    const reasoning_summary = try threadReasoningSummary(allocator, cfg);
    errdefer if (reasoning_summary) |value| allocator.free(value);

    const personality = try threadPersonality(allocator, cfg, params);
    errdefer if (personality) |value| allocator.free(value);

    const collaboration_mode = try allocator.dupe(u8, "default");
    errdefer allocator.free(collaboration_mode);
    const collaboration_developer_instructions: ?[]const u8 = null;
    const pending_session_start_source = try allocator.dupe(u8, "resume");
    errdefer allocator.free(pending_session_start_source);

    const now = currentUnixSeconds();
    return .{
        .id = thread_id,
        .session_id = session_id,
        .forked_from_id = forked_from_id,
        .preview = preview,
        .model = model,
        .model_context_window = cfg.model_context_window,
        .model_auto_compact_token_limit = cfg.model_auto_compact_token_limit,
        .model_verbosity = model_verbosity,
        .model_provider = model_provider,
        .openai_base_url = openai_base_url,
        .chatgpt_base_url = chatgpt_base_url,
        .oss_provider = oss_provider,
        .service_tier = service_tier,
        .active_profile = active_profile,
        .cwd = cwd,
        .approval_policy = approval_policy,
        .approvals_reviewer = approvals_reviewer,
        .sandbox_mode = sandbox_mode,
        .sandbox_writable_roots = sandbox_writable_roots,
        .sandbox_read_denied_roots = sandbox_read_denied_roots,
        .sandbox_read_denied_globs = sandbox_read_denied_globs,
        .sandbox_include_cwd_write_root = true,
        .sandbox_network_enabled = defaultNetworkEnabledForSandboxModeLabel(sandbox_mode),
        .sandbox_exclude_tmpdir_env_var = false,
        .sandbox_exclude_slash_tmp = false,
        .sandbox_external = false,
        .web_search_mode = cfg.web_search_mode,
        .reasoning_effort = reasoning_effort,
        .reasoning_summary = reasoning_summary,
        .personality = personality,
        .collaboration_mode = collaboration_mode,
        .collaboration_developer_instructions = collaboration_developer_instructions,
        .runtime_overrides = .{
            .model = paramPresent(params, "model"),
            .model_context_window = false,
            .model_auto_compact_token_limit = false,
            .model_verbosity = false,
            .model_provider = paramPresent(params, "modelProvider") or request_config.model_provider_present or (!use_request_profile and transcript.model_provider != null),
            .service_tier = paramPresent(params, "serviceTier"),
            .approval_policy = paramPresent(params, "approvalPolicy"),
            .approvals_reviewer = paramPresent(params, "approvalsReviewer"),
            .sandbox_mode = paramPresent(params, "sandbox"),
            .web_search_mode = threadRequestConfigParamPresent(params, "web_search"),
            .reasoning_summary = false,
            .personality = optionalStringParam(params, "personality") != null,
        },
        .ephemeral = false,
        .path = path_copy,
        .source = source,
        .thread_source = thread_source,
        .agent_nickname = null,
        .agent_role = null,
        .cli_version = cli_version,
        .token_usage = transcript.token_usage,
        .token_usage_turn_id = token_usage_turn_id,
        .name = name,
        .elicitation_count = 0,
        .git_sha = git_sha,
        .git_branch = git_branch,
        .git_origin_url = git_origin_url,
        .goal = goal,
        .transcript = transcript_copy,
        .turns_json = turns_json,
        .next_turn_index = turnCountForTranscript(&transcript_copy),
        .pending_session_start_source = pending_session_start_source,
        .created_at = now,
        .updated_at = now,
    };
}

fn createLoadedThreadFromForkPath(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
    path_raw: []const u8,
) !LoadedThread {
    var transcript = try session_store.loadTranscript(allocator, path_raw);
    defer transcript.deinit(allocator);

    const path = try std.Io.Dir.cwd().realPathFileAlloc(std.Io.Threaded.global_single_threaded.io(), path_raw, allocator);
    defer allocator.free(path);

    return createLoadedThreadFromResumeParams(allocator, cfg, params, path, &transcript);
}

fn createLoadedThreadFromForkParams(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
    source: *const LoadedThread,
) !LoadedThread {
    return createLoadedThreadFromForkParamsWithSource(allocator, cfg, params, source, "appServer");
}

fn createLoadedThreadFromForkParamsWithSource(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: std.json.ObjectMap,
    source: *const LoadedThread,
    session_source: []const u8,
) !LoadedThread {
    const thread_id = try generateUuidString(allocator);
    errdefer allocator.free(thread_id);
    const session_id = try allocator.dupe(u8, thread_id);
    errdefer allocator.free(session_id);
    const forked_from_id = try allocator.dupe(u8, source.id);
    errdefer allocator.free(forked_from_id);
    const preview = try allocator.dupe(u8, source.preview);
    errdefer allocator.free(preview);
    const source_label = try allocator.dupe(u8, session_source);
    errdefer allocator.free(source_label);
    const cli_version = try allocator.dupe(u8, "0.0.1");
    errdefer allocator.free(cli_version);
    const token_usage_turn_id = if (source.token_usage_turn_id) |value| try allocator.dupe(u8, value) else null;
    errdefer if (token_usage_turn_id) |value| allocator.free(value);
    const git_sha = if (source.git_sha) |value| try allocator.dupe(u8, value) else null;
    errdefer if (git_sha) |value| allocator.free(value);
    const git_branch = if (source.git_branch) |value| try allocator.dupe(u8, value) else null;
    errdefer if (git_branch) |value| allocator.free(value);
    const git_origin_url = if (source.git_origin_url) |value| try allocator.dupe(u8, value) else null;
    errdefer if (git_origin_url) |value| allocator.free(value);
    const turns_json = try allocator.dupe(u8, source.turns_json);
    errdefer allocator.free(turns_json);
    var transcript = try source.transcript.clone(allocator);
    errdefer transcript.deinit(allocator);

    const request_config = try threadRequestConfigFromParams(params);
    const use_request_profile = request_config.profile_present;
    const requested_model_provider = optionalStringParam(params, "modelProvider");
    const use_request_model_runtime = use_request_profile or request_config.oss_mode_present or request_config.model_provider_present;
    const reset_provider_state = use_request_model_runtime or requested_model_provider != null;
    const use_request_config_for_web_search = request_config.profile_present or request_config.web_search_mode_present;

    const default_model = if (use_request_model_runtime) cfg.model else source.model;
    const model = try allocator.dupe(u8, optionalStringParam(params, "model") orelse default_model);
    errdefer allocator.free(model);

    const model_context_window = if (use_request_profile) cfg.model_context_window else source.model_context_window;
    const model_auto_compact_token_limit = if (use_request_profile) cfg.model_auto_compact_token_limit else source.model_auto_compact_token_limit;

    const model_verbosity = if (use_request_profile)
        try threadModelVerbosity(allocator, cfg)
    else if (source.model_verbosity) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (model_verbosity) |value| allocator.free(value);

    const configured_model_provider = if (use_request_model_runtime) cfg.model_provider_id else null;
    const default_model_provider = if (use_request_model_runtime) configured_model_provider orelse "openai" else source.model_provider;
    const model_provider = try allocator.dupe(u8, requested_model_provider orelse default_model_provider);
    errdefer allocator.free(model_provider);
    const openai_base_url = try forkThreadOpenaiBaseUrl(allocator, request_config, reset_provider_state, source);
    errdefer if (openai_base_url) |value| allocator.free(value);
    const chatgpt_base_url = try forkThreadChatgptBaseUrl(allocator, request_config, reset_provider_state, source);
    errdefer if (chatgpt_base_url) |value| allocator.free(value);
    const oss_provider = try forkThreadOssProvider(allocator, cfg, request_config, reset_provider_state, source);
    errdefer if (oss_provider) |value| allocator.free(value);

    const service_tier = try lifecycleServiceTier(allocator, if (use_request_profile) cfg.service_tier else source.service_tier, params);
    errdefer if (service_tier) |value| allocator.free(value);

    const active_profile = if (use_request_profile)
        try threadActiveProfile(allocator, cfg)
    else if (source.active_profile) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (active_profile) |value| allocator.free(value);

    const cwd = if (optionalStringParam(params, "cwd")) |value|
        try realPathFileAllocPlain(allocator, value)
    else
        try allocator.dupe(u8, source.cwd);
    errdefer allocator.free(cwd);

    const default_approval_policy = if (use_request_profile) cfg.approval_policy.label() else source.approval_policy;
    const approval_policy = try allocator.dupe(u8, optionalStringParam(params, "approvalPolicy") orelse default_approval_policy);
    errdefer allocator.free(approval_policy);

    const default_approvals_reviewer = if (use_request_profile) cfg.approvals_reviewer.label() else source.approvals_reviewer;
    const requested_approvals_reviewer = try optionalApprovalsReviewerParam(params, "approvalsReviewer");
    const approvals_reviewer = try allocator.dupe(u8, requested_approvals_reviewer orelse default_approvals_reviewer);
    errdefer allocator.free(approvals_reviewer);

    const default_sandbox_mode = if (use_request_profile) cfg.sandbox_mode.label() else source.sandbox_mode;
    const sandbox_mode = try allocator.dupe(u8, optionalStringParam(params, "sandbox") orelse default_sandbox_mode);
    errdefer allocator.free(sandbox_mode);
    const sandbox_override = optionalStringParam(params, "sandbox") != null;
    const reset_sandbox_profile = sandbox_override or use_request_profile;
    var sandbox_writable_roots = if (reset_sandbox_profile)
        try emptyStringList(allocator)
    else
        try source.sandbox_writable_roots.clone(allocator);
    errdefer sandbox_writable_roots.deinit(allocator);
    var sandbox_read_denied_roots = if (reset_sandbox_profile)
        try emptyStringList(allocator)
    else
        try source.sandbox_read_denied_roots.clone(allocator);
    errdefer sandbox_read_denied_roots.deinit(allocator);
    var sandbox_read_denied_globs = if (reset_sandbox_profile)
        try emptyStringList(allocator)
    else
        try source.sandbox_read_denied_globs.clone(allocator);
    errdefer sandbox_read_denied_globs.deinit(allocator);
    const sandbox_include_cwd_write_root = if (reset_sandbox_profile) true else source.sandbox_include_cwd_write_root;
    const sandbox_network_enabled = if (reset_sandbox_profile) defaultNetworkEnabledForSandboxModeLabel(sandbox_mode) else source.sandbox_network_enabled;
    const sandbox_exclude_tmpdir_env_var = if (reset_sandbox_profile) false else source.sandbox_exclude_tmpdir_env_var;
    const sandbox_exclude_slash_tmp = if (reset_sandbox_profile) false else source.sandbox_exclude_slash_tmp;
    const sandbox_external = if (reset_sandbox_profile) false else source.sandbox_external;

    const web_search_mode = if (use_request_config_for_web_search) cfg.web_search_mode else source.web_search_mode;

    const reasoning_effort = if (use_request_profile and cfg.model_reasoning_effort != null)
        try allocator.dupe(u8, cfg.model_reasoning_effort.?.label())
    else if (use_request_profile)
        null
    else if (source.reasoning_effort) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (reasoning_effort) |value| allocator.free(value);

    const reasoning_summary = if (use_request_profile)
        try threadReasoningSummary(allocator, cfg)
    else if (source.reasoning_summary) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (reasoning_summary) |value| allocator.free(value);

    const personality = if (paramPresent(params, "personality")) blk: {
        const requested = try optionalPersonalityParam(params, "personality");
        break :blk if (requested) |value| try allocator.dupe(u8, value.label()) else null;
    } else if (use_request_profile) blk: {
        break :blk if (cfg.personality) |value| try allocator.dupe(u8, value.label()) else null;
    } else if (source.personality) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (personality) |value| allocator.free(value);

    const collaboration_mode = try allocator.dupe(u8, source.collaboration_mode);
    errdefer allocator.free(collaboration_mode);
    const collaboration_developer_instructions = if (source.collaboration_developer_instructions) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (collaboration_developer_instructions) |value| allocator.free(value);

    const ephemeral = optionalBoolParam(params, "ephemeral") orelse false;
    const path = if (ephemeral)
        null
    else
        try session_store.createSessionPathForId(allocator, cfg.codex_home, thread_id);
    errdefer if (path) |value| allocator.free(value);

    const thread_source = if (optionalStringParam(params, "threadSource")) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (thread_source) |value| allocator.free(value);
    const pending_session_start_source = try allocator.dupe(u8, "startup");
    errdefer allocator.free(pending_session_start_source);

    const now = currentUnixSeconds();
    try transcript.setId(allocator, thread_id);
    try transcript.setForkedFromId(allocator, source.id);
    try transcript.setSource(allocator, source_label);
    try transcript.setModelProvider(allocator, model_provider);
    try syncTranscriptBaseUrls(allocator, &transcript, openai_base_url, chatgpt_base_url);
    try transcript.setCwd(allocator, cwd);
    try transcript.setCliVersion(allocator, cli_version);
    if (thread_source) |value| try transcript.setThreadSource(allocator, value);
    transcript.clearGoal(allocator);

    return .{
        .id = thread_id,
        .session_id = session_id,
        .forked_from_id = forked_from_id,
        .preview = preview,
        .model = model,
        .model_context_window = model_context_window,
        .model_auto_compact_token_limit = model_auto_compact_token_limit,
        .model_verbosity = model_verbosity,
        .model_provider = model_provider,
        .openai_base_url = openai_base_url,
        .chatgpt_base_url = chatgpt_base_url,
        .oss_provider = oss_provider,
        .service_tier = service_tier,
        .active_profile = active_profile,
        .cwd = cwd,
        .approval_policy = approval_policy,
        .approvals_reviewer = approvals_reviewer,
        .sandbox_mode = sandbox_mode,
        .sandbox_writable_roots = sandbox_writable_roots,
        .sandbox_read_denied_roots = sandbox_read_denied_roots,
        .sandbox_read_denied_globs = sandbox_read_denied_globs,
        .sandbox_include_cwd_write_root = sandbox_include_cwd_write_root,
        .sandbox_network_enabled = sandbox_network_enabled,
        .sandbox_exclude_tmpdir_env_var = sandbox_exclude_tmpdir_env_var,
        .sandbox_exclude_slash_tmp = sandbox_exclude_slash_tmp,
        .sandbox_external = sandbox_external,
        .web_search_mode = web_search_mode,
        .reasoning_effort = reasoning_effort,
        .reasoning_summary = reasoning_summary,
        .personality = personality,
        .collaboration_mode = collaboration_mode,
        .collaboration_developer_instructions = collaboration_developer_instructions,
        .runtime_overrides = .{
            .model = paramPresent(params, "model") or (!use_request_profile and source.runtime_overrides.model),
            .model_context_window = !use_request_profile and source.runtime_overrides.model_context_window,
            .model_auto_compact_token_limit = !use_request_profile and source.runtime_overrides.model_auto_compact_token_limit,
            .model_verbosity = !use_request_profile and source.runtime_overrides.model_verbosity,
            .model_provider = paramPresent(params, "modelProvider") or request_config.model_provider_present or (!use_request_profile and source.runtime_overrides.model_provider),
            .service_tier = paramPresent(params, "serviceTier") or (!use_request_profile and source.runtime_overrides.service_tier),
            .approval_policy = paramPresent(params, "approvalPolicy") or (!use_request_profile and source.runtime_overrides.approval_policy),
            .approvals_reviewer = paramPresent(params, "approvalsReviewer") or (!use_request_profile and source.runtime_overrides.approvals_reviewer),
            .sandbox_mode = sandbox_override or (!use_request_profile and source.runtime_overrides.sandbox_mode),
            .web_search_mode = request_config.web_search_mode_present or (!use_request_profile and source.runtime_overrides.web_search_mode),
            .reasoning_effort = !use_request_profile and source.runtime_overrides.reasoning_effort,
            .reasoning_summary = !use_request_profile and source.runtime_overrides.reasoning_summary,
            .personality = paramPresent(params, "personality") or (!use_request_profile and source.runtime_overrides.personality),
            .collaboration_mode = source.runtime_overrides.collaboration_mode,
        },
        .ephemeral = ephemeral,
        .path = path,
        .source = source_label,
        .thread_source = thread_source,
        .agent_nickname = null,
        .agent_role = null,
        .cli_version = cli_version,
        .token_usage = source.token_usage,
        .token_usage_turn_id = token_usage_turn_id,
        .name = null,
        .elicitation_count = 0,
        .git_sha = git_sha,
        .git_branch = git_branch,
        .git_origin_url = git_origin_url,
        .goal = null,
        .transcript = transcript,
        .turns_json = turns_json,
        .next_turn_index = turnCountForTranscript(&transcript),
        .pending_session_start_source = pending_session_start_source,
        .created_at = now,
        .updated_at = now,
    };
}

fn threadStartServiceTier(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    params: ?std.json.ObjectMap,
) !?[]const u8 {
    if (params) |object| {
        if (object.get("serviceTier")) |value| {
            if (value == .null) return null;
            return try allocator.dupe(u8, value.string);
        }
    }
    if (cfg.service_tier) |value| return try allocator.dupe(u8, value);
    return null;
}

fn lifecycleServiceTier(
    allocator: std.mem.Allocator,
    default_value: ?[]const u8,
    params: std.json.ObjectMap,
) !?[]const u8 {
    if (params.get("serviceTier")) |value| {
        if (value == .null) return null;
        return try allocator.dupe(u8, value.string);
    }
    if (default_value) |value| return try allocator.dupe(u8, value);
    return null;
}

fn threadModelVerbosity(
    allocator: std.mem.Allocator,
