fn resumePreview(allocator: std.mem.Allocator, transcript: *const session_mod.Transcript) ![]const u8 {
    for (transcript.history.items) |item| {
        if (item.kind == .message and item.text != null) {
            if (item.role) |role| {
                if (std.mem.eql(u8, role, "user")) return allocator.dupe(u8, item.text.?);
            }
        }
    }
    for (transcript.history.items) |item| {
        if (historyItemVisibleInTurns(item) and item.text != null) return allocator.dupe(u8, item.text.?);
    }
    return allocator.dupe(u8, "");
}

fn transcriptTokenUsageTurnId(allocator: std.mem.Allocator, transcript: *const session_mod.Transcript) !?[]const u8 {
    if (transcript.token_usage == null) return null;
    const turn_index = transcript.token_usage_turn_index orelse return null;
    const rendered_turn_index = if (transcriptHasExternalAgentImportedMarker(transcript))
        groupedTurnIndexForMessageTurnIndex(transcript, turn_index) orelse return null
    else
        visibleTurnIndexForMessageTurnIndex(transcript, turn_index) orelse return null;
    const turn_id = try std.fmt.allocPrint(allocator, "turn-{d}", .{rendered_turn_index});
    return turn_id;
}

fn transcriptFromResponseHistory(allocator: std.mem.Allocator, history: []const std.json.Value) !session_mod.Transcript {
    return session_mod.transcriptFromResponseHistory(allocator, history);
}

fn renderTranscriptTurnsJson(allocator: std.mem.Allocator, transcript: *const session_mod.Transcript, include_turns: bool) ![]const u8 {
    if (!include_turns) return allocator.dupe(u8, "[]");
    if (transcriptHasExternalAgentImportedMarker(transcript)) return renderGroupedTranscriptTurnsJson(allocator, transcript);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.append(allocator, '[');
    var turn_index: usize = 0;
    for (transcript.history.items, 0..) |item, item_index| {
        if (!historyItemVisibleInTurns(item)) continue;
        if (turn_index > 0) try out.append(allocator, ',');
        try out.appendSlice(allocator, "{\"id\":\"turn-");
        try appendUsize(allocator, &out, turn_index);
        try out.appendSlice(allocator, "\",\"items\":[");
        try appendHistoryMessageThreadItemJson(allocator, &out, item, item_index);
        try out.appendSlice(allocator, "],\"itemsView\":\"full\",\"status\":\"completed\",\"error\":null,\"startedAt\":null,\"completedAt\":null,\"durationMs\":null}");
        turn_index += 1;
    }
    try out.append(allocator, ']');
    return out.toOwnedSlice(allocator);
}

fn renderGroupedTranscriptTurnsJson(allocator: std.mem.Allocator, transcript: *const session_mod.Transcript) ![]const u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.append(allocator, '[');

    var turn_index: usize = 0;
    var turn_open = false;
    var turn_item_count: usize = 0;
    for (transcript.history.items, 0..) |item, item_index| {
        if (!historyItemVisibleInTurns(item)) continue;
        if (turn_open and turn_item_count > 0 and historyItemIsUserMessage(item)) {
            try out.appendSlice(allocator, "],\"itemsView\":\"full\",\"status\":\"completed\",\"error\":null,\"startedAt\":null,\"completedAt\":null,\"durationMs\":null}");
            turn_open = false;
            turn_item_count = 0;
            turn_index += 1;
        }

        if (!turn_open) {
            if (turn_index > 0) try out.append(allocator, ',');
            try out.appendSlice(allocator, "{\"id\":\"turn-");
            try appendUsize(allocator, &out, turn_index);
            try out.appendSlice(allocator, "\",\"items\":[");
            turn_open = true;
        } else if (turn_item_count > 0) {
            try out.append(allocator, ',');
        }

        try appendHistoryMessageThreadItemJson(allocator, &out, item, item_index);
        turn_item_count += 1;
    }

    if (turn_open) {
        try out.appendSlice(allocator, "],\"itemsView\":\"full\",\"status\":\"completed\",\"error\":null,\"startedAt\":null,\"completedAt\":null,\"durationMs\":null}");
    }
    try out.append(allocator, ']');
    return out.toOwnedSlice(allocator);
}

fn transcriptHasExternalAgentImportedMarker(transcript: *const session_mod.Transcript) bool {
    for (transcript.history.items) |item| {
        if (item.kind != .message) continue;
        if (item.text) |text| {
            if (std.mem.eql(u8, text, session_store.external_agent_session_imported_marker)) return true;
        }
    }
    return false;
}

fn historyItemIsUserMessage(item: api.HistoryItem) bool {
    if (item.role) |role| return std.mem.eql(u8, role, "user");
    return false;
}

fn historyItemIsDeveloperMessage(item: api.HistoryItem) bool {
    if (item.role) |role| return std.mem.eql(u8, role, "developer");
    return false;
}

fn historyItemVisibleInTurns(item: api.HistoryItem) bool {
    return item.kind == .message and !historyItemIsDeveloperMessage(item);
}

fn visibleTurnIndexForMessageTurnIndex(transcript: *const session_mod.Transcript, target_message_turn_index: usize) ?usize {
    var message_turn_index: usize = 0;
    var visible_turn_index: usize = 0;
    for (transcript.history.items) |item| {
        if (item.kind != .message) continue;
        const visible = historyItemVisibleInTurns(item);
        if (message_turn_index == target_message_turn_index) {
            if (!visible) return null;
            return visible_turn_index;
        }
        if (visible) visible_turn_index += 1;
        message_turn_index += 1;
    }
    return null;
}

fn groupedTurnIndexForMessageTurnIndex(transcript: *const session_mod.Transcript, target_message_turn_index: usize) ?usize {
    var message_turn_index: usize = 0;
    var grouped_turn_index: usize = 0;
    var turn_has_items = false;
    for (transcript.history.items) |item| {
        if (item.kind != .message) continue;
        const visible = historyItemVisibleInTurns(item);
        if (visible and turn_has_items and historyItemIsUserMessage(item)) {
            grouped_turn_index += 1;
        }
        if (message_turn_index == target_message_turn_index) {
            if (!visible) return null;
            return grouped_turn_index;
        }
        if (visible) turn_has_items = true;
        message_turn_index += 1;
    }
    return null;
}

fn appendHistoryMessageThreadItemJson(allocator: std.mem.Allocator, out: *std.ArrayList(u8), item: api.HistoryItem, index: usize) !void {
    const text = item.text orelse "";
    const role = item.role orelse "";
    try out.appendSlice(allocator, "{\"type\":");
    if (std.mem.eql(u8, role, "assistant")) {
        try appendJsonString(allocator, out, "agentMessage");
        try out.appendSlice(allocator, ",\"id\":\"item-");
        try appendUsize(allocator, out, index);
        try out.appendSlice(allocator, "\",\"text\":");
        try appendJsonString(allocator, out, text);
        try out.appendSlice(allocator, ",\"phase\":null,\"memoryCitation\":null}");
    } else {
        try appendJsonString(allocator, out, "userMessage");
        try out.appendSlice(allocator, ",\"id\":\"item-");
        try appendUsize(allocator, out, index);
        try out.appendSlice(allocator, "\",\"content\":[{\"type\":\"text\",\"text\":");
        try appendJsonString(allocator, out, text);
        try out.appendSlice(allocator, ",\"text_elements\":[]}]}");
    }
}

fn appendUsize(allocator: std.mem.Allocator, out: *std.ArrayList(u8), value: usize) !void {
    const text = try std.fmt.allocPrint(allocator, "{d}", .{value});
    defer allocator.free(text);
    try out.appendSlice(allocator, text);
}

fn threadStartCwd(allocator: std.mem.Allocator, params: ?std.json.ObjectMap) ![]const u8 {
    const cwd = optionalStringParam(params, "cwd") orelse ".";
    return realPathFileAllocPlain(allocator, cwd);
}

fn threadResumeCwd(
    allocator: std.mem.Allocator,
    transcript: *const session_mod.Transcript,
    params: std.json.ObjectMap,
) ![]const u8 {
    if (optionalStringParam(params, "cwd")) |cwd| {
        return realPathFileAllocPlain(allocator, cwd);
    }
    if (transcript.cwd) |cwd| return allocator.dupe(u8, cwd);
    return threadStartCwd(allocator, params);
}

fn realPathFileAllocPlain(allocator: std.mem.Allocator, path: []const u8) ![]const u8 {
    const real_path = try std.Io.Dir.cwd().realPathFileAlloc(std.Io.Threaded.global_single_threaded.io(), path, allocator);
    defer allocator.free(real_path);
    return allocator.dupe(u8, real_path);
}

fn optionalStringParam(params: ?std.json.ObjectMap, name: []const u8) ?[]const u8 {
    const object = params orelse return null;
    const value = object.get(name) orelse return null;
    if (value == .null) return null;
    return value.string;
}

fn optionalBoolParam(params: ?std.json.ObjectMap, name: []const u8) ?bool {
    const object = params orelse return null;
    const value = object.get(name) orelse return null;
    if (value == .null) return null;
    return value.bool;
}

fn optionalNullableStringParam(params: std.json.ObjectMap, name: []const u8) !?[]const u8 {
    const value = params.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .string) return error.InvalidNullableStringParam;
    return value.string;
}

fn optionalNullableU32Param(params: std.json.ObjectMap, name: []const u8) !?u32 {
    const value = params.get(name) orelse return null;
    return switch (value) {
        .null => null,
        .integer => |integer| blk: {
            if (integer < 0 or integer > std.math.maxInt(u32)) return error.InvalidNullableU32Param;
            break :blk @intCast(integer);
        },
        .number_string => |number| std.fmt.parseUnsigned(u32, number, 10) catch return error.InvalidNullableU32Param,
        else => error.InvalidNullableU32Param,
    };
}

fn parseIntErrorMessage(err: anyerror) []const u8 {
    return switch (err) {
        error.InvalidCharacter => "invalid digit found in string",
        error.Overflow => "number too large to fit in target type",
        else => @errorName(err),
    };
}

fn optionalReasoningEffortParam(params: std.json.ObjectMap, name: []const u8) !?config.ReasoningEffort {
    const value = params.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .string) return error.InvalidTurnContextOverride;
    return config.ReasoningEffort.parse(value.string) catch error.InvalidTurnContextOverride;
}

fn optionalReasoningSummaryParam(params: std.json.ObjectMap, name: []const u8) !?config.ReasoningSummary {
    const value = params.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .string) return error.InvalidTurnContextOverride;
    return config.ReasoningSummary.parse(value.string) catch error.InvalidTurnContextOverride;
}

fn optionalPersonalityParam(params: std.json.ObjectMap, name: []const u8) !?config.Personality {
    const value = params.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .string) return error.InvalidTurnContextOverride;
    return config.Personality.parse(value.string) catch error.InvalidTurnContextOverride;
}

fn optionalApprovalsReviewerParam(params: std.json.ObjectMap, name: []const u8) !?[]const u8 {
    const value = params.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .string) return error.InvalidTurnContextOverride;
    const reviewer = config.ApprovalsReviewer.parse(value.string) catch return error.InvalidTurnContextOverride;
    return reviewer.label();
}

fn optionalApprovalsReviewerLifecycleParam(params: ?std.json.ObjectMap, name: []const u8) !?[]const u8 {
    const object = params orelse return null;
    return optionalApprovalsReviewerParam(object, name);
}

fn paramPresent(params: ?std.json.ObjectMap, name: []const u8) bool {
    const object = params orelse return false;
    return object.get(name) != null;
}

fn optionalJsonParam(params: std.json.ObjectMap, name: []const u8) ?std.json.Value {
    const value = params.get(name) orelse return null;
    if (value == .null) return null;
    return value;
}

fn threadResumeInitialTurnsPageParams(params: std.json.ObjectMap) ?std.json.ObjectMap {
    const value = params.get("initialTurnsPage") orelse return null;
    if (value == .null) return null;
    if (value != .object) return null;
    return value.object;
}

fn replaceOwnedString(allocator: std.mem.Allocator, slot: *[]const u8, value: []const u8) !void {
    const copy = try allocator.dupe(u8, value);
    allocator.free(slot.*);
    slot.* = copy;
}

fn generateUuidString(allocator: std.mem.Allocator) ![]const u8 {
    return uuid_mod.generateV4String(allocator);
}

fn currentUnixSeconds() i64 {
    const now_ns = std.Io.Timestamp.now(std.Io.Threaded.global_single_threaded.io(), .real).nanoseconds;
    return @intCast(@divTrunc(now_ns, 1_000_000_000));
}

fn currentUnixMilliseconds() i64 {
    const now_ns = std.Io.Timestamp.now(std.Io.Threaded.global_single_threaded.io(), .real).nanoseconds;
    return @intCast(@divTrunc(now_ns, std.time.ns_per_ms));
}

fn findLoadedThread(state: *const AppServerState, thread_id: []const u8) ?*const LoadedThread {
    const index = findLoadedThreadIndex(state, thread_id) orelse return null;
    return &state.loaded_threads.items[index];
}

fn findLoadedThreadForRolloutFile(state: *const AppServerState, file: session_store.RolloutFile) ?*const LoadedThread {
    for (state.loaded_threads.items) |*thread| {
        if (std.mem.eql(u8, thread.id, file.id)) return thread;
        if (thread.path) |path| {
            if (std.mem.eql(u8, path, file.path)) return thread;
        }
    }
    return null;
}

fn findLoadedThreadIndex(state: *const AppServerState, thread_id: []const u8) ?usize {
    for (state.loaded_threads.items, 0..) |thread, index| {
        if (std.mem.eql(u8, thread.id, thread_id)) return index;
    }
    return null;
}

fn removeLoadedThread(allocator: std.mem.Allocator, state: *AppServerState, thread_id: []const u8) bool {
    _ = removePendingThreadUnload(allocator, state, thread_id);
    _ = removeThreadSubscription(allocator, state, thread_id);
    const index = findLoadedThreadIndex(state, thread_id) orelse return false;
    var removed = state.loaded_threads.orderedRemove(index);
    removed.deinit(allocator);
    return true;
}

fn deleteThreadRolloutFiles(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    cfg: config.Config,
    thread_id: []const u8,
) !bool {
    var known = false;
    if (findLoadedThread(state, thread_id)) |thread| {
        known = !thread.ephemeral;
        if (thread.path) |path| {
            try deleteRolloutPathIfPresent(path, thread_id);
        }
    }

    const deleted_path = session_store.deleteRollout(allocator, cfg.codex_home, thread_id) catch |err| switch (err) {
        error.FileNotFound => null,
        else => return err,
    };
    if (deleted_path) |path| {
        allocator.free(path);
        return true;
    }

    const state_path = try thread_state.findRolloutPathByThreadId(allocator, cfg.codex_home, configSqliteHome(cfg), thread_id);
    if (state_path) |path| {
        defer allocator.free(path);
        try deleteRolloutPathIfPresent(path, thread_id);
        return true;
    }

    return known;
}

fn deleteRolloutPathIfPresent(path: []const u8, thread_id: []const u8) !void {
    const basename = std.fs.path.basename(path);
    if (std.mem.indexOf(u8, basename, thread_id) == null) return error.InvalidSessionPath;
    std.Io.Dir.cwd().deleteFile(std.Io.Threaded.global_single_threaded.io(), path) catch |err| switch (err) {
        error.FileNotFound => {},
        else => return err,
    };
}

fn upsertLoadedThread(allocator: std.mem.Allocator, state: *AppServerState, thread: LoadedThread) !void {
    if (findLoadedThreadIndex(state, thread.id)) |index| {
        var existing = state.loaded_threads.items[index];
        state.loaded_threads.items[index] = thread;
        existing.deinit(allocator);
        return;
    }
    try state.loaded_threads.append(allocator, thread);
}

fn ensureThreadSubscribed(allocator: std.mem.Allocator, state: *AppServerState, thread_id: []const u8) !bool {
    _ = removePendingThreadUnload(allocator, state, thread_id);
    for (state.subscribed_thread_ids.items) |subscribed_id| {
        if (std.mem.eql(u8, subscribed_id, thread_id)) return false;
    }
    const owned_id = try allocator.dupe(u8, thread_id);
    errdefer allocator.free(owned_id);
    try state.subscribed_thread_ids.append(allocator, owned_id);
    return true;
}

fn removeThreadSubscription(allocator: std.mem.Allocator, state: *AppServerState, thread_id: []const u8) bool {
    for (state.subscribed_thread_ids.items, 0..) |subscribed_id, index| {
        if (std.mem.eql(u8, subscribed_id, thread_id)) {
            const removed = state.subscribed_thread_ids.orderedRemove(index);
            allocator.free(removed);
            return true;
        }
    }
    return false;
}

fn threadHasSubscription(state: *const AppServerState, thread_id: []const u8) bool {
    for (state.subscribed_thread_ids.items) |subscribed_id| {
        if (std.mem.eql(u8, subscribed_id, thread_id)) return true;
    }
    return false;
}

fn findPendingThreadUnloadIndex(state: *const AppServerState, thread_id: []const u8) ?usize {
    for (state.pending_thread_unloads.items, 0..) |pending, index| {
        if (std.mem.eql(u8, pending.thread_id, thread_id)) return index;
    }
    return null;
}

fn removePendingThreadUnload(allocator: std.mem.Allocator, state: *AppServerState, thread_id: []const u8) bool {
    const index = findPendingThreadUnloadIndex(state, thread_id) orelse return false;
    var removed = state.pending_thread_unloads.orderedRemove(index);
    removed.deinit(allocator);
    return true;
}

fn scheduleThreadUnloadIfUnsubscribed(allocator: std.mem.Allocator, state: *AppServerState, thread_id: []const u8) !void {
    if (threadHasSubscription(state, thread_id)) return;
    try scheduleThreadUnload(allocator, state, thread_id);
}

fn scheduleThreadUnload(allocator: std.mem.Allocator, state: *AppServerState, thread_id: []const u8) !void {
    const thread_index = findLoadedThreadIndex(state, thread_id) orelse {
        _ = removePendingThreadUnload(allocator, state, thread_id);
        return;
    };
    const now_ms = currentAppServerAwakeMillis();
    const inactive_since_ms: ?i64 = if (state.loaded_threads.items[thread_index].status == .active) null else now_ms;
    if (findPendingThreadUnloadIndex(state, thread_id)) |pending_index| {
        state.pending_thread_unloads.items[pending_index].no_subscribers_since_ms = now_ms;
        state.pending_thread_unloads.items[pending_index].inactive_since_ms = inactive_since_ms;
        return;
    }
    const owned_id = try allocator.dupe(u8, thread_id);
    errdefer allocator.free(owned_id);
    try state.pending_thread_unloads.append(allocator, .{
        .thread_id = owned_id,
        .no_subscribers_since_ms = now_ms,
        .inactive_since_ms = inactive_since_ms,
    });
}

fn scheduleThreadUnloadsForConnectionClose(allocator: std.mem.Allocator, state: *AppServerState) !void {
    for (state.subscribed_thread_ids.items) |thread_id| {
        try scheduleThreadUnload(allocator, state, thread_id);
    }
}

fn notePendingThreadUnloadStatus(state: *AppServerState, thread_id: []const u8, status: ThreadRuntimeStatus) void {
    const pending_index = findPendingThreadUnloadIndex(state, thread_id) orelse return;
    const now_ms = currentAppServerAwakeMillis();
    switch (status) {
        .active => state.pending_thread_unloads.items[pending_index].inactive_since_ms = null,
        .idle, .system_error, .not_loaded => state.pending_thread_unloads.items[pending_index].inactive_since_ms = now_ms,
    }
}

fn pendingThreadUnloadTargetMs(state: *const AppServerState, pending: PendingThreadUnload) ?i64 {
    const inactive_since_ms = pending.inactive_since_ms orelse return null;
    const base_ms = @max(pending.no_subscribers_since_ms, inactive_since_ms);
    if (state.thread_unloading_delay_ms > std.math.maxInt(i64) - base_ms) return std.math.maxInt(i64);
    return base_ms + state.thread_unloading_delay_ms;
}

fn appServerConnectionPollTimeoutMs(state: *const AppServerState) i32 {
    var timeout_ms: i64 = APP_SERVER_CONNECTION_POLL_MS;
    const now_ms = currentAppServerAwakeMillis();
    for (state.pending_thread_unloads.items) |pending| {
        const target_ms = pendingThreadUnloadTargetMs(state, pending) orelse continue;
        const remaining_ms: i64 = if (target_ms <= now_ms) 0 else target_ms - now_ms;
        timeout_ms = @min(timeout_ms, remaining_ms);
    }
    return @intCast(@min(timeout_ms, @as(i64, std.math.maxInt(i32))));
}

fn appServerDaemonAcceptPollTimeoutMs(state: *const AppServerState) i32 {
    var timeout_ms: ?i64 = null;
    const now_ms = currentAppServerAwakeMillis();
    for (state.pending_thread_unloads.items) |pending| {
        const target_ms = pendingThreadUnloadTargetMs(state, pending) orelse continue;
        const remaining_ms: i64 = if (target_ms <= now_ms) 0 else target_ms - now_ms;
        timeout_ms = if (timeout_ms) |current| @min(current, remaining_ms) else remaining_ms;
    }
    const pending_timeout_ms = timeout_ms orelse return -1;
    return @intCast(@min(pending_timeout_ms, @as(i64, std.math.maxInt(i32))));
}

fn reapExpiredThreadUnloads(allocator: std.mem.Allocator, state: *AppServerState, emit_notifications: bool) !void {
    var index: usize = 0;
    while (index < state.pending_thread_unloads.items.len) {
        const pending = state.pending_thread_unloads.items[index];
        const target_ms = pendingThreadUnloadTargetMs(state, pending) orelse {
            index += 1;
            continue;
        };
        if (target_ms > currentAppServerAwakeMillis()) {
            index += 1;
            continue;
        }
        const thread_index = findLoadedThreadIndex(state, pending.thread_id) orelse {
            var removed = state.pending_thread_unloads.orderedRemove(index);
            removed.deinit(allocator);
            continue;
        };
        if (state.loaded_threads.items[thread_index].status == .active) {
            state.pending_thread_unloads.items[index].inactive_since_ms = null;
            index += 1;
            continue;
        }

        const thread_id = try allocator.dupe(u8, pending.thread_id);
        defer allocator.free(thread_id);
        var removed_pending = state.pending_thread_unloads.orderedRemove(index);
        removed_pending.deinit(allocator);
        if (removeLoadedThread(allocator, state, thread_id) and emit_notifications) {
            try queueThreadStatusChangedNotification(allocator, state, thread_id, .not_loaded);
            try queueThreadIdNotification(allocator, state, "thread/closed", thread_id);
        }
    }
}

fn renderThreadLoadedListResult(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    params_value: ?std.json.Value,
) ![]const u8 {
    var ids = std.ArrayList([]const u8).empty;
    defer ids.deinit(allocator);
    for (state.loaded_threads.items) |thread| try ids.append(allocator, thread.id);
    if (ids.items.len == 0) {
        return allocator.dupe(u8, "{\"data\":[],\"nextCursor\":null}");
    }
    std.mem.sort([]const u8, ids.items, {}, stringLessThan);

    const cursor = threadLoadedListCursor(params_value);
    const limit = threadLoadedListLimit(params_value);
    var start: usize = 0;
    if (cursor) |cursor_value| {
        const normalized_cursor = canonicalUuidString(allocator, cursor_value) catch |err| switch (err) {
            error.InvalidUuidString => return error.InvalidThreadLoadedListCursor,
            else => return err,
        };
        defer allocator.free(normalized_cursor);
        for (ids.items, 0..) |id, index| {
            if (std.mem.eql(u8, id, normalized_cursor)) {
                start = index + 1;
                break;
            }
            if (std.mem.order(u8, id, normalized_cursor) == .gt) {
                start = index;
                break;
            }
        } else {
            start = ids.items.len;
        }
    }
    const effective_limit = if (limit) |value| @max(value, 1) else ids.items.len;
    const capped_end = @min(ids.items.len, start +| effective_limit);

    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"data\":[");
    for (ids.items[start..capped_end], 0..) |thread_id, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try appendJsonString(allocator, &result, thread_id);
    }
    try result.appendSlice(allocator, "],\"nextCursor\":");
    if (capped_end < ids.items.len and capped_end > 0) {
        try appendJsonString(allocator, &result, ids.items[capped_end - 1]);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, "}");
    return result.toOwnedSlice(allocator);
}

const ThreadListSortKey = enum {
    created_at,
    updated_at,
    recency_at,
};

const ThreadListSortDirection = enum {
    asc,
    desc,
};

const ThreadListSortContext = struct {
    key: ThreadListSortKey,
    direction: ThreadListSortDirection,
};

const ThreadListSourceKind = enum {
    cli,
    vscode,
    exec,
    app_server,
    sub_agent,
    sub_agent_review,
    sub_agent_compact,
    sub_agent_thread_spawn,
    sub_agent_other,
    unknown,
    other,
};

const ThreadListMatchContext = struct {
    params: std.json.ObjectMap,
    cwd_filters: ?[][]const u8 = null,
    source_kinds: ?[]ThreadListSourceKind = null,
    apply_search_term_filter: bool = true,
    apply_model_provider_filter: bool = true,
    apply_cwd_filter: bool = true,

    fn init(allocator: std.mem.Allocator, params: std.json.ObjectMap) !ThreadListMatchContext {
        return initWithOptions(allocator, params, .{});
    }

    fn initWithOptions(
        allocator: std.mem.Allocator,
        params: std.json.ObjectMap,
        options: ThreadListCollectionOptions,
    ) !ThreadListMatchContext {
        const cwd_filters = if (options.apply_cwd_filter)
            try parseThreadListCwdFilters(allocator, params.get("cwd"))
        else
            null;
        errdefer freeThreadListCwdFilters(allocator, cwd_filters);

        const source_kinds = try parseThreadListSourceKinds(allocator, params.get("sourceKinds"));
        errdefer if (source_kinds) |values| allocator.free(values);

        return .{
            .params = params,
            .cwd_filters = cwd_filters,
            .source_kinds = source_kinds,
            .apply_search_term_filter = options.apply_search_term_filter,
            .apply_model_provider_filter = options.apply_model_provider_filter,
            .apply_cwd_filter = options.apply_cwd_filter,
        };
    }

    fn deinit(self: *ThreadListMatchContext, allocator: std.mem.Allocator) void {
        freeThreadListCwdFilters(allocator, self.cwd_filters);
        if (self.source_kinds) |values| allocator.free(values);
    }
};

const ThreadListCollectionOptions = struct {
    apply_search_term_filter: bool = true,
    apply_model_provider_filter: bool = true,
    apply_cwd_filter: bool = true,
    allow_state_db_only: bool = true,
};

const SavedThreadListItem = struct {
    id: []const u8,
    session_id: []const u8,
    forked_from_id: ?[]const u8,
    preview: []const u8,
    model_provider: []const u8,
    created_at: i64,
    updated_at: i64,
    created_at_ms: i64,
    updated_at_ms: i64,
    archived: bool,
    path: []const u8,
    cwd: []const u8,
    cli_version: []const u8,
    source: []const u8,
    thread_source: ?[]const u8,
    agent_nickname: ?[]const u8,
    agent_role: ?[]const u8,
    git_sha: ?[]const u8,
    git_branch: ?[]const u8,
    git_origin_url: ?[]const u8,
    name: ?[]const u8,
    status: ThreadRuntimeStatus,

    fn fromRolloutFile(
        allocator: std.mem.Allocator,
        file: session_store.RolloutFile,
        fallback_model_provider: []const u8,
        thread_names: []const session_store.ThreadNameEntry,
        status: ThreadRuntimeStatus,
    ) !SavedThreadListItem {
        var summary = try session_store.loadThreadListSummary(allocator, file.path, file.id);
        defer summary.deinit(allocator);

        const id = try allocator.dupe(u8, summary.id);
        errdefer allocator.free(id);
        const session_id = try allocator.dupe(u8, id);
        errdefer allocator.free(session_id);
        const forked_from_id = if (summary.forked_from_id) |value| try allocator.dupe(u8, value) else null;
        errdefer if (forked_from_id) |value| allocator.free(value);
        const preview_value = stateThreadStringOrFallback(file.first_user_message, summary.preview);
        const preview = try allocator.dupe(u8, preview_value);
        errdefer allocator.free(preview);
        const model_provider_value = stateThreadStringOrFallback(file.model_provider, summary.model_provider orelse fallback_model_provider);
        const model_provider = try allocator.dupe(u8, model_provider_value);
        errdefer allocator.free(model_provider);
        const path = try allocator.dupe(u8, file.path);
        errdefer allocator.free(path);
        const cwd = try allocator.dupe(u8, stateThreadStringOrFallback(file.cwd, summary.cwd orelse ""));
        errdefer allocator.free(cwd);
        const cli_version = try allocator.dupe(u8, stateThreadStringOrFallback(file.cli_version, summary.cli_version orelse "0.0.1"));
        errdefer allocator.free(cli_version);
        const source_value = if (file.state_lifecycle_loaded) file.source orelse summary.source orelse "cli" else summary.source orelse "cli";
        const source = try session_store.normalizeSessionSourceText(allocator, source_value);
        errdefer allocator.free(source);
        const thread_source_value = if (file.state_lifecycle_loaded) file.thread_source else summary.thread_source;
        const thread_source = if (thread_source_value) |value| try allocator.dupe(u8, value) else null;
        errdefer if (thread_source) |value| allocator.free(value);
        const agent_nickname_value = if (file.state_lifecycle_loaded) file.agent_nickname else null;
        const agent_nickname = if (agent_nickname_value) |value| try allocator.dupe(u8, value) else null;
        errdefer if (agent_nickname) |value| allocator.free(value);
        const agent_role_value = if (file.state_lifecycle_loaded) file.agent_role else null;
        const agent_role = if (agent_role_value) |value| try allocator.dupe(u8, value) else null;
        errdefer if (agent_role) |value| allocator.free(value);
        const git_sha_value = if (file.state_metadata_loaded) file.git_sha else summary.git_sha;
        const git_sha = if (git_sha_value) |value| try allocator.dupe(u8, value) else null;
        errdefer if (git_sha) |value| allocator.free(value);
        const git_branch_value = if (file.state_metadata_loaded) file.git_branch else summary.git_branch;
        const git_branch = if (git_branch_value) |value| try allocator.dupe(u8, value) else null;
        errdefer if (git_branch) |value| allocator.free(value);
        const git_origin_url_value = if (file.state_metadata_loaded) file.git_origin_url else summary.git_origin_url;
        const git_origin_url = if (git_origin_url_value) |value| try allocator.dupe(u8, value) else null;
        errdefer if (git_origin_url) |value| allocator.free(value);
        const indexed_name = session_store.threadNameFromIndex(thread_names, summary.id);
        const state_name = if (file.state_metadata_loaded) stateThreadTitle(file.title, preview_value) else null;
        const name_value: ?[]const u8 = if (state_name) |value|
            value
        else if (indexed_name) |value|
            value
        else
            summary.title;
        const name = if (name_value) |value| try allocator.dupe(u8, value) else null;
        errdefer if (name) |value| allocator.free(value);

        return .{
            .id = id,
            .session_id = session_id,
            .forked_from_id = forked_from_id,
            .preview = preview,
            .model_provider = model_provider,
            .created_at = rolloutFileTimestampSeconds(file.state_lifecycle_loaded, file.created_at_ms, file.modified_at_seconds),
            .updated_at = rolloutFileTimestampSeconds(file.state_lifecycle_loaded, file.updated_at_ms, file.modified_at_seconds),
            .created_at_ms = rolloutFileTimestampMilliseconds(file.state_lifecycle_loaded, file.created_at_ms, file.modified_at_seconds),
            .updated_at_ms = rolloutFileTimestampMilliseconds(file.state_lifecycle_loaded, file.updated_at_ms, file.modified_at_seconds),
            .archived = file.archived,
            .path = path,
            .cwd = cwd,
            .cli_version = cli_version,
            .source = source,
            .thread_source = thread_source,
            .agent_nickname = agent_nickname,
            .agent_role = agent_role,
            .git_sha = git_sha,
            .git_branch = git_branch,
            .git_origin_url = git_origin_url,
            .name = name,
            .status = status,
        };
    }

    fn deinit(self: *SavedThreadListItem, allocator: std.mem.Allocator) void {
        allocator.free(self.id);
        allocator.free(self.session_id);
        if (self.forked_from_id) |value| allocator.free(value);
        allocator.free(self.preview);
        allocator.free(self.model_provider);
        allocator.free(self.path);
        allocator.free(self.cwd);
        allocator.free(self.cli_version);
        allocator.free(self.source);
        if (self.thread_source) |value| allocator.free(value);
        if (self.agent_nickname) |value| allocator.free(value);
        if (self.agent_role) |value| allocator.free(value);
        if (self.git_sha) |value| allocator.free(value);
        if (self.git_branch) |value| allocator.free(value);
        if (self.git_origin_url) |value| allocator.free(value);
        if (self.name) |value| allocator.free(value);
    }
};

fn rolloutFileTimestampSeconds(lifecycle_loaded: bool, value_ms: ?i64, fallback_seconds: i64) i64 {
    if (!lifecycle_loaded) return fallback_seconds;
    const value = value_ms orelse return fallback_seconds;
    return @divFloor(value, 1000);
}

fn rolloutFileTimestampMilliseconds(lifecycle_loaded: bool, value_ms: ?i64, fallback_seconds: i64) i64 {
    if (!lifecycle_loaded) return fallback_seconds * 1000;
    return value_ms orelse fallback_seconds * 1000;
}

fn stateThreadTitle(title: ?[]const u8, preview: []const u8) ?[]const u8 {
    const raw = title orelse return null;
    const trimmed = std.mem.trim(u8, raw, " \t\r\n");
    if (trimmed.len == 0) return null;
    if (std.mem.eql(u8, trimmed, std.mem.trim(u8, preview, " \t\r\n"))) return null;
    return trimmed;
}

fn stateThreadString(value: ?[]const u8) ?[]const u8 {
    const text = value orelse return null;
    if (text.len == 0) return null;
    return text;
}

fn stateThreadReasoningEffort(value: ?[]const u8) ?[]const u8 {
    const text = stateThreadString(value) orelse return null;
    _ = config.ReasoningEffort.parse(text) catch return null;
    return text;
}

fn stateThreadStringOrFallback(value: ?[]const u8, fallback: []const u8) []const u8 {
    return stateThreadString(value) orelse fallback;
}

const ThreadListItem = union(enum) {
    loaded: *const LoadedThread,
    saved: SavedThreadListItem,

    fn deinit(self: *ThreadListItem, allocator: std.mem.Allocator) void {
        switch (self.*) {
            .loaded => {},
            .saved => |*saved| saved.deinit(allocator),
        }
    }
};

fn renderThreadListResult(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    cfg: config.Config,
    params_value: std.json.Value,
) ![]const u8 {
    const params = params_value.object;
    var threads = try collectThreadListItems(allocator, state, cfg, params, .{});
    defer deinitThreadListItems(allocator, &threads);

    const sort_context = threadListSortContext(params);
    std.mem.sort(ThreadListItem, threads.items, sort_context, threadListLessThan);

    const cursor_ms = if (optionalStringParam(params, "cursor")) |cursor_value|
        parseThreadListCursorMilliseconds(cursor_value) orelse return error.InvalidThreadListCursor
    else
        null;
    var start: usize = 0;
    if (cursor_ms) |anchor_ms| {
        for (threads.items, 0..) |thread, index| {
            if (threadListItemIsPastCursor(thread, sort_context, anchor_ms)) {
                start = index;
                break;
            }
        } else {
            start = threads.items.len;
        }
    }

    const limit = threadListLimit(params);
    const capped_end = @min(threads.items.len, start + limit);
    const page = threads.items[start..capped_end];

    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"data\":[");
    for (page, 0..) |thread, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try appendThreadListItemJson(allocator, &result, thread);
    }
    try result.appendSlice(allocator, "],\"nextCursor\":");
    if (capped_end < threads.items.len and page.len > 0) {
        const next_cursor = try formatThreadListCursorMilliseconds(allocator, threadListItemSortTimestampMs(page[page.len - 1], sort_context.key), false);
        defer allocator.free(next_cursor);
        try appendJsonString(allocator, &result, next_cursor);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, ",\"backwardsCursor\":");
    if (page.len > 0) {
        if (threadListBackwardsCursorTimestampMs(page[0], sort_context)) |cursor_timestamp| {
            const backwards_cursor = try formatThreadListCursorMilliseconds(allocator, cursor_timestamp, true);
            defer allocator.free(backwards_cursor);
            try appendJsonString(allocator, &result, backwards_cursor);
        } else {
            try result.appendSlice(allocator, "null");
        }
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, "}");
    return result.toOwnedSlice(allocator);
}

const ThreadSearchMatch = struct {
    thread_index: usize,
    snippet: []const u8,

    fn deinit(self: *ThreadSearchMatch, allocator: std.mem.Allocator) void {
        allocator.free(self.snippet);
    }
};

fn renderThreadSearchResult(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    cfg: config.Config,
    params_value: std.json.Value,
) ![]const u8 {
    const params = params_value.object;
    const search_term = std.mem.trim(u8, params.get("searchTerm").?.string, " \t\r\n");

    var threads = try collectThreadListItems(allocator, state, cfg, params, .{
        .apply_search_term_filter = false,
        .apply_model_provider_filter = false,
        .apply_cwd_filter = false,
        .allow_state_db_only = false,
    });
    defer deinitThreadListItems(allocator, &threads);

    const sort_context = threadListSortContext(params);
    std.mem.sort(ThreadListItem, threads.items, sort_context, threadListLessThan);

    const cursor_ms = if (optionalStringParam(params, "cursor")) |cursor_value|
        parseThreadListCursorMilliseconds(cursor_value) orelse return error.InvalidThreadListCursor
    else
        null;
    var start: usize = 0;
    if (cursor_ms) |anchor_ms| {
        for (threads.items, 0..) |thread, index| {
            if (threadListItemIsPastCursor(thread, sort_context, anchor_ms)) {
                start = index;
                break;
            }
        } else {
            start = threads.items.len;
        }
    }

    const limit = threadListLimit(params);
    const match_cap = limit + 1;
    var matches = std.ArrayList(ThreadSearchMatch).empty;
    defer {
        for (matches.items) |*match| match.deinit(allocator);
        matches.deinit(allocator);
    }
    for (threads.items[start..], start..) |thread, index| {
        if (try threadSearchSnippetForItem(allocator, thread, search_term)) |snippet| {
            try matches.append(allocator, .{ .thread_index = index, .snippet = snippet });
            if (matches.items.len >= match_cap) break;
        }
    }

    const capped_end = @min(matches.items.len, limit);
    const page = matches.items[0..capped_end];

    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"data\":[");
    for (page, 0..) |match, out_index| {
        if (out_index > 0) try result.appendSlice(allocator, ",");
        try result.appendSlice(allocator, "{\"thread\":");
        try appendThreadListItemJson(allocator, &result, threads.items[match.thread_index]);
        try result.appendSlice(allocator, ",\"snippet\":");
        try appendJsonString(allocator, &result, match.snippet);
        try result.appendSlice(allocator, "}");
    }
    try result.appendSlice(allocator, "],\"nextCursor\":");
    if (capped_end < matches.items.len and page.len > 0) {
        const last_thread = threads.items[page[page.len - 1].thread_index];
        const next_cursor = try formatThreadListCursorMilliseconds(allocator, threadListItemSortTimestampMs(last_thread, sort_context.key), false);
        defer allocator.free(next_cursor);
        try appendJsonString(allocator, &result, next_cursor);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, ",\"backwardsCursor\":");
    if (page.len > 0) {
        const first_thread = threads.items[page[0].thread_index];
        if (threadListBackwardsCursorTimestampMs(first_thread, sort_context)) |cursor_timestamp| {
            const backwards_cursor = try formatThreadListCursorMilliseconds(allocator, cursor_timestamp, true);
            defer allocator.free(backwards_cursor);
            try appendJsonString(allocator, &result, backwards_cursor);
        } else {
            try result.appendSlice(allocator, "null");
        }
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, "}");
    return result.toOwnedSlice(allocator);
}

fn threadSearchSnippetForItem(
    allocator: std.mem.Allocator,
    thread: ThreadListItem,
    search_term: []const u8,
) !?[]const u8 {
    switch (thread) {
        .loaded => |loaded| {
            if (try threadSearchSnippetForTranscript(allocator, &loaded.transcript, search_term)) |snippet| return snippet;
        },
        .saved => |saved| {
            var transcript: ?session_mod.Transcript = session_store.loadTranscript(allocator, saved.path) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => null,
            };
            if (transcript) |*loaded_transcript| {
                defer loaded_transcript.deinit(allocator);
                if (try threadSearchSnippetForTranscript(allocator, loaded_transcript, search_term)) |snippet| return snippet;
            }
        },
    }

    if (threadListItemName(thread)) |name| {
        if (threadSearchTextContains(name, search_term)) return try allocator.dupe(u8, name);
    }
    const preview = threadListItemPreview(thread);
    if (threadSearchTextContains(preview, search_term)) return try allocator.dupe(u8, preview);
    return null;
}

fn threadSearchSnippetForTranscript(
    allocator: std.mem.Allocator,
    transcript: *const session_mod.Transcript,
    search_term: []const u8,
) !?[]const u8 {
    for (transcript.history.items) |item| {
        if (item.kind != .message) continue;
        const role = item.role orelse continue;
        if (!threadSearchVisibleRole(role)) continue;
        const text = item.text orelse continue;
        if (threadSearchTextContains(text, search_term)) return try allocator.dupe(u8, text);
    }
    return null;
}

fn threadSearchVisibleRole(role: []const u8) bool {
    return std.mem.eql(u8, role, "user") or std.mem.eql(u8, role, "assistant");
}

fn threadSearchTextContains(haystack: []const u8, needle: []const u8) bool {
    return std.ascii.findIgnoreCase(haystack, needle) != null;
}

fn collectThreadListItems(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    cfg: config.Config,
    params: std.json.ObjectMap,
    options: ThreadListCollectionOptions,
) !std.ArrayList(ThreadListItem) {
    var match_context = try ThreadListMatchContext.initWithOptions(allocator, params, options);
    defer match_context.deinit(allocator);

    var threads = std.ArrayList(ThreadListItem).empty;
    errdefer deinitThreadListItems(allocator, &threads);

    const state_db_only = if (options.allow_state_db_only)
        optionalBoolParam(params, "useStateDbOnly") orelse false
    else
        false;
    const archived = optionalBoolParam(params, "archived") orelse false;
    const thread_names = try session_store.loadThreadNameIndex(allocator, cfg.codex_home);
    defer session_store.freeThreadNameIndex(allocator, thread_names);
    const fallback_model_provider = try config.loadModelProviderId(allocator, cfg.active_profile);
    defer if (fallback_model_provider) |value| allocator.free(value);
    const default_model_provider = fallback_model_provider orelse "openai";
    if (state_db_only) {
        const rollout_files = try thread_state.listRolloutFiles(allocator, cfg.codex_home, configSqliteHome(cfg));
        defer session_store.freeRolloutFiles(allocator, rollout_files);
        try appendSavedThreadListItems(allocator, &threads, &match_context, rollout_files, default_model_provider, false, state, thread_names);
    } else {
        if (!archived) {
            for (state.loaded_threads.items) |*thread| {
                const item = ThreadListItem{ .loaded = thread };
                if (try threadListItemMatchesParams(allocator, item, &match_context, default_model_provider)) {
                    try threads.append(allocator, item);
                }
            }
        }

        const rollout_files = try session_store.listRolloutFiles(allocator, cfg.codex_home, archived);
        defer session_store.freeRolloutFiles(allocator, rollout_files);
        try appendSavedThreadListItems(allocator, &threads, &match_context, rollout_files, default_model_provider, !archived, state, thread_names);
    }

    return threads;
}

fn deinitThreadListItems(allocator: std.mem.Allocator, threads: *std.ArrayList(ThreadListItem)) void {
    for (threads.items) |*thread| thread.deinit(allocator);
    threads.deinit(allocator);
}

fn threadListItemMatchesParams(
    allocator: std.mem.Allocator,
    thread: ThreadListItem,
    context: *const ThreadListMatchContext,
    default_model_provider: []const u8,
) !bool {
    const archived = optionalBoolParam(context.params, "archived") orelse false;
    if (threadListItemArchived(thread) != archived) return false;
    if (context.apply_model_provider_filter) {
        if (!threadListModelProviderMatches(context.params.get("modelProviders"), threadListItemModelProvider(thread), default_model_provider)) return false;
    }
    if (!threadListSourceKindMatches(context, thread)) return false;
    if (context.apply_cwd_filter) {
        if (!try threadListCwdMatches(allocator, context, threadListItemCwd(thread))) return false;
    }
    if (context.apply_search_term_filter) {
        if (optionalStringParam(context.params, "searchTerm")) |search| {
            if (search.len > 0 and !threadListItemMatchesSearchTerm(thread, search)) return false;
        }
    }
    return true;
}

fn appendSavedThreadListItems(
    allocator: std.mem.Allocator,
    threads: *std.ArrayList(ThreadListItem),
    context: *const ThreadListMatchContext,
    rollout_files: []session_store.RolloutFile,
    fallback_model_provider: []const u8,
    dedupe_loaded: bool,
    state: *const AppServerState,
    thread_names: []const session_store.ThreadNameEntry,
) !void {
    for (rollout_files) |file| {
        const loaded_duplicate = findLoadedThreadForRolloutFile(state, file) != null;
        if (dedupe_loaded and loaded_duplicate) continue;
        const status: ThreadRuntimeStatus = if (loaded_duplicate) .idle else .not_loaded;
        var saved = SavedThreadListItem.fromRolloutFile(allocator, file, fallback_model_provider, thread_names, status) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => continue,
        };
        var saved_moved = false;
        errdefer if (!saved_moved) saved.deinit(allocator);
        const item = ThreadListItem{ .saved = saved };
        if (try threadListItemMatchesParams(allocator, item, context, fallback_model_provider)) {
            try threads.append(allocator, item);
            saved_moved = true;
        } else {
            saved.deinit(allocator);
        }
    }
}

fn threadListModelProviderMatches(value: ?std.json.Value, candidate: []const u8, default_model_provider: []const u8) bool {
    const actual = value orelse return std.mem.eql(u8, candidate, default_model_provider);
    if (actual == .null) return std.mem.eql(u8, candidate, default_model_provider);
    if (actual.array.items.len == 0) return true;
    for (actual.array.items) |item| {
        if (std.mem.eql(u8, item.string, candidate)) return true;
    }
    return false;
}

fn parseThreadListSourceKinds(allocator: std.mem.Allocator, value: ?std.json.Value) !?[]ThreadListSourceKind {
    const actual = value orelse return null;
    if (actual == .null) return null;
    if (actual.array.items.len == 0) return null;

    const kinds = try allocator.alloc(ThreadListSourceKind, actual.array.items.len);
    errdefer allocator.free(kinds);
    for (actual.array.items, 0..) |item, index| {
        kinds[index] = threadListSourceKindFromParam(item.string);
    }
    return kinds;
}

fn threadListSourceKindFromParam(value: []const u8) ThreadListSourceKind {
    if (std.mem.eql(u8, value, "cli")) return .cli;
    if (std.mem.eql(u8, value, "vscode")) return .vscode;
    if (std.mem.eql(u8, value, "exec")) return .exec;
    if (std.mem.eql(u8, value, "appServer")) return .app_server;
    if (std.mem.eql(u8, value, "subAgent")) return .sub_agent;
    if (std.mem.eql(u8, value, "subAgentReview")) return .sub_agent_review;
    if (std.mem.eql(u8, value, "subAgentCompact")) return .sub_agent_compact;
    if (std.mem.eql(u8, value, "subAgentThreadSpawn")) return .sub_agent_thread_spawn;
    if (std.mem.eql(u8, value, "subAgentOther")) return .sub_agent_other;
    return .unknown;
}

fn threadListSourceKindMatches(context: *const ThreadListMatchContext, thread: ThreadListItem) bool {
    if (context.source_kinds) |kinds| {
        for (kinds) |kind| {
            if (threadListItemMatchesSourceKind(thread, kind)) return true;
        }
        return false;
    }
    return threadListItemMatchesDefaultInteractiveSource(thread);
}

fn threadListItemMatchesDefaultInteractiveSource(thread: ThreadListItem) bool {
    const source = threadListItemSource(thread);
    const kind = threadListItemSourceKind(thread);
    return kind == .cli or kind == .vscode or threadListSourceIsDefaultInteractiveCustom(source);
}

fn threadListItemMatchesSourceKind(thread: ThreadListItem, expected: ThreadListSourceKind) bool {
    const actual = threadListItemSourceKind(thread);
    if (expected == .sub_agent) return threadListSourceKindIsSubAgent(actual);
    return actual == expected;
}

fn threadListItemSourceKind(thread: ThreadListItem) ThreadListSourceKind {
    const source = threadListItemSource(thread);

    if (threadListTextEqualsAny(source, &.{ "subagent_review", "subAgentReview", "sub_agent_review" })) return .sub_agent_review;
    if (threadListTextEqualsAny(source, &.{ "subagent_compact", "subAgentCompact", "sub_agent_compact" })) return .sub_agent_compact;
    if (threadListTextEqualsAny(source, &.{ "threadSpawn", "thread_spawn" }) or threadListTextStartsWithAny(source, &.{ "subagent_thread_spawn", "subAgentThreadSpawn", "sub_agent_thread_spawn" })) return .sub_agent_thread_spawn;
    if (threadListTextEqualsAny(source, &.{ "subAgentOther", "sub_agent_other", "subagent_other" }) or std.mem.startsWith(u8, source, "subagent_other:")) return .sub_agent_other;
    if (threadListTextLooksSubAgent(source)) {
        if (std.mem.eql(u8, source, "subagent_memory_consolidation")) return .sub_agent;
        return .sub_agent_other;
    }
    if (std.mem.eql(u8, source, "cli")) return .cli;
    if (std.mem.eql(u8, source, "vscode")) return .vscode;
    if (std.mem.eql(u8, source, "exec")) return .exec;
    if (threadListTextEqualsAny(source, &.{ "appServer", "mcp", "appserver", "app-server", "app_server" })) return .app_server;
    if (std.mem.eql(u8, source, "unknown")) return .unknown;
    return .other;
}

fn threadListSourceKindIsSubAgent(kind: ThreadListSourceKind) bool {
    return switch (kind) {
        .sub_agent, .sub_agent_review, .sub_agent_compact, .sub_agent_thread_spawn, .sub_agent_other => true,
        else => false,
    };
}

fn threadListTextLooksSubAgent(value: []const u8) bool {
    return threadListTextEqualsAny(value, &.{ "subAgent", "sub_agent" }) or threadListTextStartsWithAny(value, &.{ "subagent_", "subAgent", "sub_agent_" });
}

fn threadListSourceIsDefaultInteractiveCustom(value: []const u8) bool {
    return threadListTextEqualsAny(value, &.{
        "atlas",
        "chatgpt",
        "custom:atlas",
        "custom:chatgpt",
        "{\"custom\":\"atlas\"}",
        "{\"custom\":\"chatgpt\"}",
    });
}

fn threadListTextEqualsAny(value: []const u8, needles: []const []const u8) bool {
    for (needles) |needle| {
        if (std.mem.eql(u8, value, needle)) return true;
    }
    return false;
}

fn threadListTextStartsWithAny(value: []const u8, prefixes: []const []const u8) bool {
    for (prefixes) |prefix| {
        if (std.mem.startsWith(u8, value, prefix)) return true;
    }
    return false;
}

fn parseThreadListCwdFilters(allocator: std.mem.Allocator, value: ?std.json.Value) !?[][]const u8 {
    const actual = value orelse return null;
    if (actual == .null) return null;
    if (actual == .string) {
        const filters = try allocator.alloc([]const u8, 1);
        errdefer allocator.free(filters);
        filters[0] = try normalizeThreadListCwdFilter(allocator, actual.string);
        return filters;
    }

    const filters = try allocator.alloc([]const u8, actual.array.items.len);
    errdefer allocator.free(filters);
    var normalized_count: usize = 0;
    errdefer {
        for (filters[0..normalized_count]) |filter| allocator.free(filter);
    }
    for (actual.array.items, 0..) |item, index| {
        filters[index] = try normalizeThreadListCwdFilter(allocator, item.string);
        normalized_count += 1;
    }
    return filters;
}

fn normalizeThreadListCwdFilter(allocator: std.mem.Allocator, raw: []const u8) ![]const u8 {
    if (std.fs.path.isAbsolute(raw)) return std.fs.path.resolve(allocator, &.{raw});
    const io = std.Io.Threaded.global_single_threaded.io();
    const process_cwd = try std.Io.Dir.cwd().realPathFileAlloc(io, ".", allocator);
    defer allocator.free(process_cwd);
    return std.fs.path.resolve(allocator, &.{ process_cwd, raw });
}

fn freeThreadListCwdFilters(allocator: std.mem.Allocator, filters: ?[][]const u8) void {
    const values = filters orelse return;
    for (values) |filter| allocator.free(filter);
    allocator.free(values);
}

fn threadListCwdMatches(allocator: std.mem.Allocator, context: *const ThreadListMatchContext, cwd: []const u8) !bool {
    const filters = context.cwd_filters orelse return true;
    if (filters.len == 0 or cwd.len == 0) return false;
    const normalized_cwd = try std.fs.path.resolve(allocator, &.{cwd});
    defer allocator.free(normalized_cwd);
    for (filters) |filter| {
        if (std.mem.eql(u8, filter, normalized_cwd)) return true;
    }
    return false;
}

fn saveThreadListTestTranscript(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    id: []const u8,
    source: []const u8,
    thread_source: ?[]const u8,
    model_provider: []const u8,
    cwd: []const u8,
    title: []const u8,
    prompt: []const u8,
) !void {
    const path = try session_store.createSessionPathForId(allocator, codex_home, id);
    defer allocator.free(path);

    var transcript = session_mod.Transcript{};
    defer transcript.deinit(allocator);
    try transcript.setId(allocator, id);
    try transcript.setSource(allocator, source);
    if (thread_source) |value| try transcript.setThreadSource(allocator, value);
    try transcript.setModelProvider(allocator, model_provider);
    try transcript.setCwd(allocator, cwd);
    try transcript.setCliVersion(allocator, "0.0.1");
    try transcript.setTitle(allocator, title);
    try transcript.appendUserMessage(allocator, prompt);

    try session_store.saveTranscript(allocator, path, &transcript);
    try session_store.appendThreadMemoryModeFromTranscript(allocator, path, id, &transcript, "enabled");
}

fn saveThreadListTestTranscriptWithSourceJson(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    id: []const u8,
    source_json: []const u8,
    thread_source: ?[]const u8,
    model_provider: []const u8,
    cwd: []const u8,
    prompt: []const u8,
) !void {
    const path = try session_store.createSessionPathForId(allocator, codex_home, id);
    defer allocator.free(path);

    var out = std.ArrayList(u8).empty;
    defer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"type\":\"session_meta\",\"payload\":{\"id\":");
    try appendJsonString(allocator, &out, id);
    try out.appendSlice(allocator, ",\"timestamp\":\"2025-02-02T09:00:00Z\",\"cwd\":");
    try appendJsonString(allocator, &out, cwd);
    try out.appendSlice(allocator, ",\"originator\":\"codex\",\"cli_version\":\"0.0.0\",\"source\":");
    try out.appendSlice(allocator, source_json);
    if (thread_source) |value| {
        try out.appendSlice(allocator, ",\"thread_source\":");
        try appendJsonString(allocator, &out, value);
    }
    try out.appendSlice(allocator, ",\"model_provider\":");
    try appendJsonString(allocator, &out, model_provider);
    try out.appendSlice(allocator, "}}\n{\"type\":\"response_item\",\"payload\":{\"type\":\"message\",\"role\":\"user\",\"content\":[{\"type\":\"input_text\",\"text\":");
    try appendJsonString(allocator, &out, prompt);
    try out.appendSlice(allocator, "}]}}\n");

    try std.Io.Dir.cwd().writeFile(std.Io.Threaded.global_single_threaded.io(), .{
        .sub_path = path,
        .data = out.items,
    });
}

test "thread/list sourceKinds default to interactive sessions" {
    const allocator = std.testing.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    const codex_home = try dir.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(codex_home);

    var cfg = try testAppServerConfig(allocator, "gpt-5.5");
    defer cfg.deinit(allocator);
    try replaceConfigOwnedString(allocator, &cfg.codex_home, codex_home);

    const cli_id = "11111111-1111-4111-8111-111111111111";
    const cli_thread_source_subagent_id = "22222222-2222-4222-8222-222222222222";
    const subagent_source_id = "33333333-3333-4333-8333-333333333333";
    const subagent_spawn_source_id = "34343434-3434-4434-8434-343434343434";
    const subagent_other_source_id = "36363636-3636-4636-8636-363636363636";
    const custom_atlas_source_id = "55555555-5555-4555-8555-555555555555";
    try saveThreadListTestTranscript(allocator, codex_home, cli_id, "cli", "user", "openai", codex_home, "CLI thread", "interactive prompt");
    try saveThreadListTestTranscript(allocator, codex_home, cli_thread_source_subagent_id, "cli", "subagent", "openai", codex_home, "CLI thread source subagent", "cli subagent prompt");
    try saveThreadListTestTranscriptWithSourceJson(allocator, codex_home, subagent_source_id, "{\"subagent\":\"review\"}", "user", "openai", codex_home, "subagent source prompt");
    try saveThreadListTestTranscriptWithSourceJson(allocator, codex_home, subagent_spawn_source_id, "{\"subagent\":{\"thread_spawn\":{\"parent_thread_id\":\"77777777-7777-4777-8777-777777777777\",\"depth\":2,\"agent_path\":null,\"agent_nickname\":\"Scout\",\"agent_role\":\"reviewer\"}}}", "user", "openai", codex_home, "subagent spawn prompt");
    try saveThreadListTestTranscriptWithSourceJson(allocator, codex_home, subagent_other_source_id, "{\"subagent\":{\"other\":\"debug\"}}", "user", "openai", codex_home, "subagent other prompt");
    try saveThreadListTestTranscriptWithSourceJson(allocator, codex_home, custom_atlas_source_id, "{\"custom\":\"atlas\"}", "user", "openai", codex_home, "atlas source prompt");

    var state = AppServerState{};
    defer state.deinit(allocator);
    var start_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"ephemeral\":true}", .{});
    defer start_params.deinit();
    var loaded_thread = try createLoadedThreadFromStartParams(allocator, cfg, start_params.value.object);
    var loaded_thread_moved = false;
    errdefer if (!loaded_thread_moved) loaded_thread.deinit(allocator);
    const app_server_id = loaded_thread.id;
    try state.loaded_threads.append(allocator, loaded_thread);
    loaded_thread_moved = true;

    var default_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10}", .{});
    defer default_params.deinit();
    const default_result = try renderThreadListResult(allocator, &state, cfg, default_params.value);
    defer allocator.free(default_result);
    try std.testing.expect(std.mem.indexOf(u8, default_result, cli_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, default_result, cli_thread_source_subagent_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, default_result, custom_atlas_source_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, default_result, "\"source\":{\"custom\":\"atlas\"}") != null);
    try std.testing.expect(std.mem.indexOf(u8, default_result, subagent_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, default_result, subagent_spawn_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, default_result, subagent_other_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, default_result, app_server_id) == null);

    var empty_source_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10,\"sourceKinds\":[]}", .{});
    defer empty_source_params.deinit();
    const empty_source_result = try renderThreadListResult(allocator, &state, cfg, empty_source_params.value);
    defer allocator.free(empty_source_result);
    try std.testing.expect(std.mem.indexOf(u8, empty_source_result, cli_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, empty_source_result, cli_thread_source_subagent_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, empty_source_result, custom_atlas_source_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, empty_source_result, subagent_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, empty_source_result, subagent_spawn_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, empty_source_result, subagent_other_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, empty_source_result, app_server_id) == null);

    var app_server_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10,\"sourceKinds\":[\"appServer\"]}", .{});
    defer app_server_params.deinit();
    const app_server_result = try renderThreadListResult(allocator, &state, cfg, app_server_params.value);
    defer allocator.free(app_server_result);
    try std.testing.expect(std.mem.indexOf(u8, app_server_result, app_server_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, app_server_result, cli_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, app_server_result, cli_thread_source_subagent_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, app_server_result, custom_atlas_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, app_server_result, subagent_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, app_server_result, subagent_spawn_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, app_server_result, subagent_other_source_id) == null);

    var cli_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10,\"sourceKinds\":[\"cli\"]}", .{});
    defer cli_params.deinit();
    const cli_result = try renderThreadListResult(allocator, &state, cfg, cli_params.value);
    defer allocator.free(cli_result);
    try std.testing.expect(std.mem.indexOf(u8, cli_result, cli_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, cli_result, cli_thread_source_subagent_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, cli_result, custom_atlas_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, cli_result, subagent_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, cli_result, subagent_spawn_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, cli_result, subagent_other_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, cli_result, app_server_id) == null);

    var subagent_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10,\"sourceKinds\":[\"subAgent\"]}", .{});
    defer subagent_params.deinit();
    const subagent_result = try renderThreadListResult(allocator, &state, cfg, subagent_params.value);
    defer allocator.free(subagent_result);
    try std.testing.expect(std.mem.indexOf(u8, subagent_result, subagent_source_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, subagent_result, subagent_spawn_source_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, subagent_result, subagent_other_source_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, subagent_result, "\"source\":{\"subAgent\":\"review\"}") != null);
    try std.testing.expect(std.mem.indexOf(u8, subagent_result, cli_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, subagent_result, cli_thread_source_subagent_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, subagent_result, custom_atlas_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, subagent_result, app_server_id) == null);

    var spawn_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10,\"sourceKinds\":[\"subAgentThreadSpawn\"]}", .{});
    defer spawn_params.deinit();
    const spawn_result = try renderThreadListResult(allocator, &state, cfg, spawn_params.value);
    defer allocator.free(spawn_result);
    try std.testing.expect(std.mem.indexOf(u8, spawn_result, subagent_spawn_source_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, spawn_result, "\"source\":{\"subAgent\":{\"thread_spawn\":{\"parent_thread_id\":\"77777777-7777-4777-8777-777777777777\",\"depth\":2,\"agent_path\":null,\"agent_nickname\":\"Scout\",\"agent_role\":\"reviewer\"}}}") != null);
    try std.testing.expect(std.mem.indexOf(u8, spawn_result, subagent_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, spawn_result, subagent_other_source_id) == null);

    var other_subagent_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10,\"sourceKinds\":[\"subAgentOther\"]}", .{});
    defer other_subagent_params.deinit();
    const other_subagent_result = try renderThreadListResult(allocator, &state, cfg, other_subagent_params.value);
    defer allocator.free(other_subagent_result);
    try std.testing.expect(std.mem.indexOf(u8, other_subagent_result, subagent_other_source_id) != null);
    try std.testing.expect(std.mem.indexOf(u8, other_subagent_result, "\"source\":{\"subAgent\":{\"other\":\"debug\"}}") != null);
    try std.testing.expect(std.mem.indexOf(u8, other_subagent_result, subagent_source_id) == null);
    try std.testing.expect(std.mem.indexOf(u8, other_subagent_result, subagent_spawn_source_id) == null);
}

test "thread source renderers normalize Rust state DB JSON source strings" {
    const allocator = std.testing.allocator;

    var thread_source = std.ArrayList(u8).empty;
    defer thread_source.deinit(allocator);
    try appendThreadSourceJson(allocator, &thread_source, "{\"subagent\":\"review\"}");
    try std.testing.expectEqualStrings("{\"subAgent\":\"review\"}", thread_source.items);

    var summary_source = std.ArrayList(u8).empty;
    defer summary_source.deinit(allocator);
    try appendConversationSummarySourceJson(allocator, &summary_source, "{\"custom\":\"atlas\"}");
    try std.testing.expectEqualStrings("{\"custom\":\"atlas\"}", summary_source.items);
}

test "thread/list cwd filter resolves relative paths" {
    const allocator = std.testing.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    const codex_home = try dir.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(codex_home);

    var cfg = try testAppServerConfig(allocator, "gpt-5.5");
    defer cfg.deinit(allocator);
    try replaceConfigOwnedString(allocator, &cfg.codex_home, codex_home);

    const process_cwd = try std.Io.Dir.cwd().realPathFileAlloc(io, ".", allocator);
    defer allocator.free(process_cwd);
    const relative_cwd = "thread-list-relative-cwd";
    const absolute_cwd = try std.fs.path.resolve(allocator, &.{ process_cwd, relative_cwd });
    defer allocator.free(absolute_cwd);

    const cli_id = "44444444-4444-4444-8444-444444444444";
    try saveThreadListTestTranscript(allocator, codex_home, cli_id, "cli", "user", "openai", absolute_cwd, "Relative cwd thread", "cwd prompt");

    var state = AppServerState{};
    defer state.deinit(allocator);

    var relative_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10,\"sourceKinds\":[\"cli\"],\"cwd\":\"thread-list-relative-cwd\"}", .{});
    defer relative_params.deinit();
    const relative_result = try renderThreadListResult(allocator, &state, cfg, relative_params.value);
    defer allocator.free(relative_result);
    try std.testing.expect(std.mem.indexOf(u8, relative_result, cli_id) != null);

    var other_params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"limit\":10,\"sourceKinds\":[\"cli\"],\"cwd\":\"other-thread-list-relative-cwd\"}", .{});
    defer other_params.deinit();
    const other_result = try renderThreadListResult(allocator, &state, cfg, other_params.value);
    defer allocator.free(other_result);
    try std.testing.expect(std.mem.indexOf(u8, other_result, cli_id) == null);
}

fn threadListItemMatchesSearchTerm(thread: ThreadListItem, search: []const u8) bool {
    if (threadListItemName(thread)) |name| {
        if (std.mem.indexOf(u8, name, search) != null) return true;
    }
    return std.mem.indexOf(u8, threadListItemPreview(thread), search) != null;
}

fn threadListSortContext(params: std.json.ObjectMap) ThreadListSortContext {
    const key_text = optionalStringParam(params, "sortKey") orelse "created_at";
    const direction_text = optionalStringParam(params, "sortDirection") orelse "desc";
    return .{
        .key = if (std.mem.eql(u8, key_text, "updated_at"))
            .updated_at
        else if (std.mem.eql(u8, key_text, "recency_at"))
            .recency_at
        else
            .created_at,
        .direction = if (std.mem.eql(u8, direction_text, "asc")) .asc else .desc,
    };
}

fn threadListLessThan(context: ThreadListSortContext, lhs: ThreadListItem, rhs: ThreadListItem) bool {
    const lhs_timestamp = threadListItemSortTimestampMs(lhs, context.key);
    const rhs_timestamp = threadListItemSortTimestampMs(rhs, context.key);
    if (lhs_timestamp != rhs_timestamp) {
        return if (context.direction == .asc) lhs_timestamp < rhs_timestamp else lhs_timestamp > rhs_timestamp;
    }
    return stringLessThan({}, threadListItemId(lhs), threadListItemId(rhs));
}

fn threadListItemIsPastCursor(thread: ThreadListItem, context: ThreadListSortContext, cursor_ms: i64) bool {
    const timestamp_ms = threadListItemSortTimestampMs(thread, context.key);
    return switch (context.direction) {
        .asc => timestamp_ms > cursor_ms,
        .desc => timestamp_ms < cursor_ms,
    };
}

fn threadListBackwardsCursorTimestampMs(thread: ThreadListItem, context: ThreadListSortContext) ?i64 {
    const timestamp_ms = threadListItemSortTimestampMs(thread, context.key);
    return switch (context.direction) {
        .asc => timestamp_ms + 1,
        .desc => if (timestamp_ms > 0) timestamp_ms - 1 else null,
    };
}

fn threadListItemId(thread: ThreadListItem) []const u8 {
    return switch (thread) {
        .loaded => |loaded| loaded.id,
        .saved => |saved| saved.id,
    };
}

fn threadListItemPreview(thread: ThreadListItem) []const u8 {
    return switch (thread) {
        .loaded => |loaded| loaded.preview,
        .saved => |saved| saved.preview,
