    allocator: std.mem.Allocator,
    state: *AppServerState,
    cfg: config.Config,
    config_bytes: []const u8,
) !void {
    if (notificationMethodOptedOut(state, "deprecationNotice")) return;

    const value = try config.scopedStringValue(allocator, config_bytes, cfg.active_profile, "experimental_instructions_file");
    defer if (value) |deprecated_file| allocator.free(deprecated_file);
    if (value == null) return;

    try queueDeprecationNoticeNotification(allocator, state, deprecated_instructions_file_summary, deprecated_instructions_file_details);
}

fn queueDeprecationNoticeNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    summary: []const u8,
    details: ?[]const u8,
) !void {
    if (notificationMethodOptedOut(state, "deprecationNotice")) return;

    const notification = try renderDeprecationNoticeNotification(allocator, summary, details);
    errdefer allocator.free(notification);
    try state.pending_notifications.append(allocator, notification);
}

fn renderDeprecationNoticeNotification(allocator: std.mem.Allocator, summary: []const u8, details: ?[]const u8) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"deprecationNotice\",\"params\":{\"summary\":");
    try appendJsonString(allocator, &result, summary);
    try result.appendSlice(allocator, ",\"details\":");
    try appendOptionalJsonString(allocator, &result, details);
    try result.appendSlice(allocator, "}}");
    return result.toOwnedSlice(allocator);
}

fn queueInitializeConfigWarningNotifications(
    allocator: std.mem.Allocator,
    state: *AppServerState,
) !void {
    if (notificationMethodOptedOut(state, "configWarning")) return;

    var context = try loadProjectConfigWarningContext(allocator) orelse return;
    defer context.deinit(allocator);

    try queueExecPolicyConfigWarningNotification(allocator, state, &context);
    if (try projectConfigDisabledWarningSummary(allocator, &context)) |summary| {
        defer allocator.free(summary);
        try queueConfigWarningNotification(allocator, state, summary, null);
    }
    try queueProjectIgnoredConfigKeyWarningNotifications(allocator, state, &context);
}

fn queueConfigWarningNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    summary: []const u8,
    details: ?[]const u8,
) !void {
    try queueConfigWarningNotificationWithPath(allocator, state, summary, details, null);
}

fn queueConfigWarningNotificationWithPath(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    summary: []const u8,
    details: ?[]const u8,
    path: ?[]const u8,
) !void {
    if (notificationMethodOptedOut(state, "configWarning")) return;

    const notification = try renderConfigWarningNotification(allocator, summary, details, path);
    errdefer allocator.free(notification);
    try state.pending_notifications.append(allocator, notification);
}

fn renderConfigWarningNotification(allocator: std.mem.Allocator, summary: []const u8, details: ?[]const u8, path: ?[]const u8) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"configWarning\",\"params\":{\"summary\":");
    try appendJsonString(allocator, &result, summary);
    try result.appendSlice(allocator, ",\"details\":");
    try appendOptionalJsonString(allocator, &result, details);
    if (path) |value| {
        try result.appendSlice(allocator, ",\"path\":");
        try appendJsonString(allocator, &result, value);
    }
    try result.appendSlice(allocator, "}}");
    return result.toOwnedSlice(allocator);
}

const project_config_disabled_summary_prefix = "Project-local config, hooks, and exec policies are disabled in the following folders until the project is trusted, but skills still load.\n";
const project_config_gated_features = "project-local config, hooks, and exec policies";

const ProjectConfigWarningContext = struct {
    cwd: [:0]u8,
    codex_home: []const u8,
    user_config_path: []const u8,
    user_config_bytes: ?[]const u8,
    default_codex_home: ?[]const u8,

    fn deinit(self: *ProjectConfigWarningContext, allocator: std.mem.Allocator) void {
        allocator.free(self.cwd);
        allocator.free(self.codex_home);
        allocator.free(self.user_config_path);
        if (self.user_config_bytes) |bytes| allocator.free(bytes);
        if (self.default_codex_home) |path| allocator.free(path);
    }

    fn userBytes(self: *const ProjectConfigWarningContext) []const u8 {
        return self.user_config_bytes orelse "";
    }

    fn isUserCodexFolder(self: *const ProjectConfigWarningContext, path: []const u8) bool {
        return std.mem.eql(u8, path, self.codex_home) or
            (self.default_codex_home != null and std.mem.eql(u8, path, self.default_codex_home.?));
    }
};

fn loadProjectConfigWarningContext(allocator: std.mem.Allocator) !?ProjectConfigWarningContext {
    const io = std.Io.Threaded.global_single_threaded.io();
    const cwd_z = std.Io.Dir.cwd().realPathFileAlloc(io, ".", allocator) catch return null;
    errdefer allocator.free(cwd_z);

    const codex_home = config.resolveCodexHome(allocator) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return null,
    };
    errdefer allocator.free(codex_home);
    const user_config_path = try config.configTomlPath(allocator, codex_home);
    errdefer allocator.free(user_config_path);
    const user_config_bytes = config.readConfigTomlFile(allocator, user_config_path) catch null;
    errdefer if (user_config_bytes) |bytes| allocator.free(bytes);
    const default_codex_home = try defaultUserCodexHome(allocator);
    errdefer if (default_codex_home) |path| allocator.free(path);

    const context = ProjectConfigWarningContext{
        .cwd = cwd_z,
        .codex_home = codex_home,
        .user_config_path = user_config_path,
        .user_config_bytes = user_config_bytes,
        .default_codex_home = default_codex_home,
    };
    return context;
}

const exec_policy_config_warning_summary = "Error parsing rules; custom rules not applied.";
const exec_policy_rules_dir_name = "rules";
const exec_policy_rules_extension = ".rules";

fn queueExecPolicyConfigWarningNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    context: *const ProjectConfigWarningContext,
) !void {
    if (notificationMethodOptedOut(state, "configWarning")) return;

    var rule_paths = std.ArrayList([]const u8).empty;
    defer {
        for (rule_paths.items) |path| allocator.free(path);
        rule_paths.deinit(allocator);
    }

    const user_rules_dir = try std.fs.path.join(allocator, &.{ context.codex_home, exec_policy_rules_dir_name });
    defer allocator.free(user_rules_dir);
    try collectExecPolicyRuleFiles(allocator, user_rules_dir, &rule_paths);
    try collectProjectExecPolicyRuleFiles(allocator, context, &rule_paths);

    for (rule_paths.items) |path| {
        execpolicy_cmd.validateRulesFile(allocator, path) catch |err| {
            const details = try std.fmt.allocPrint(allocator, "failed to parse rules file {s}: {s}", .{ path, @errorName(err) });
            defer allocator.free(details);
            try queueConfigWarningNotificationWithPath(allocator, state, exec_policy_config_warning_summary, details, path);
            return;
        };
    }
}

fn collectProjectExecPolicyRuleFiles(
    allocator: std.mem.Allocator,
    context: *const ProjectConfigWarningContext,
    rule_paths: *std.ArrayList([]const u8),
) !void {
    var projects = std.ArrayList([]const u8).empty;
    defer projects.deinit(allocator);

    var current: []const u8 = context.cwd;
    while (true) {
        try projects.append(allocator, current);
        const parent = std.fs.path.dirname(current) orelse break;
        if (parent.len == current.len) break;
        current = parent;
    }

    var index = projects.items.len;
    while (index > 0) {
        index -= 1;
        const project_path = projects.items[index];
        const dot_codex_folder = try std.fs.path.join(allocator, &.{ project_path, ".codex" });
        defer allocator.free(dot_codex_folder);

        if (context.isUserCodexFolder(dot_codex_folder) or
            !try projectTrustedBySelfOrAncestor(allocator, context.userBytes(), project_path))
        {
            continue;
        }

        const rules_dir = try std.fs.path.join(allocator, &.{ dot_codex_folder, exec_policy_rules_dir_name });
        defer allocator.free(rules_dir);
        try collectExecPolicyRuleFiles(allocator, rules_dir, rule_paths);
    }
}

fn collectExecPolicyRuleFiles(
    allocator: std.mem.Allocator,
    rules_dir: []const u8,
    rule_paths: *std.ArrayList([]const u8),
) !void {
    const io = std.Io.Threaded.global_single_threaded.io();
    var dir = openExecPolicyRulesDir(io, rules_dir) catch return;
    defer dir.close(io);

    const start_index = rule_paths.items.len;
    var iter = dir.iterate();
    while (true) {
        const entry = (iter.next(io) catch return) orelse break;
        if (!std.mem.endsWith(u8, entry.name, exec_policy_rules_extension)) continue;

        const child_path = try std.fs.path.join(allocator, &.{ rules_dir, entry.name });
        errdefer allocator.free(child_path);
        const metadata = (statPathFollow(allocator, child_path) catch {
            allocator.free(child_path);
            continue;
        }) orelse {
            allocator.free(child_path);
            continue;
        };
        const mode: u32 = @intCast(metadata.mode);
        if (!std.c.S.ISREG(mode)) {
            allocator.free(child_path);
            continue;
        }
        try rule_paths.append(allocator, child_path);
    }
    std.mem.sort([]const u8, rule_paths.items[start_index..], {}, stringLessThan);
}

fn openExecPolicyRulesDir(io: std.Io, path: []const u8) !std.Io.Dir {
    return if (std.fs.path.isAbsolute(path))
        std.Io.Dir.openDirAbsolute(io, path, .{ .iterate = true })
    else
        std.Io.Dir.cwd().openDir(io, path, .{ .iterate = true });
}

fn projectConfigDisabledWarningSummary(allocator: std.mem.Allocator, context: *const ProjectConfigWarningContext) !?[]u8 {
    const io = std.Io.Threaded.global_single_threaded.io();
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);

    var current: []const u8 = context.cwd;
    var disabled_count: usize = 0;
    while (true) {
        const dot_codex_folder = try std.fs.path.join(allocator, &.{ current, ".codex" });
        defer allocator.free(dot_codex_folder);

        const has_project_codex = if (context.isUserCodexFolder(dot_codex_folder))
            false
        else
            dirExists(io, dot_codex_folder) catch false;
        if (has_project_codex and !try projectTrustedBySelfOrAncestor(allocator, context.userBytes(), current)) {
            if (disabled_count == 0) {
                try result.appendSlice(allocator, project_config_disabled_summary_prefix);
            }
            disabled_count += 1;
            try appendProjectConfigDisabledEntry(
                allocator,
                &result,
                disabled_count,
                dot_codex_folder,
                current,
                context.user_config_path,
                context.userBytes(),
            );
        }

        const parent = std.fs.path.dirname(current) orelse break;
        if (parent.len == current.len) break;
        current = parent;
    }

    if (disabled_count == 0) {
        result.deinit(allocator);
        return null;
    }
    const owned = try result.toOwnedSlice(allocator);
    return owned;
}

fn defaultUserCodexHome(allocator: std.mem.Allocator) !?[]u8 {
    const home = try env.getOwned(allocator, "HOME") orelse return null;
    defer allocator.free(home);
    const path = try std.fs.path.join(allocator, &.{ home, ".codex" });
    return path;
}

const project_local_config_denylist = [_][]const u8{
    "openai_base_url",
    "chatgpt_base_url",
    "model_provider",
    "model_providers",
    "notify",
    "profile",
    "profiles",
    "experimental_realtime_ws_base_url",
};

fn queueProjectIgnoredConfigKeyWarningNotifications(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    context: *const ProjectConfigWarningContext,
) !void {
    const io = std.Io.Threaded.global_single_threaded.io();
    var current: []const u8 = context.cwd;
    while (true) {
        const dot_codex_folder = try std.fs.path.join(allocator, &.{ current, ".codex" });
        defer allocator.free(dot_codex_folder);

        if (!context.isUserCodexFolder(dot_codex_folder) and
            (dirExists(io, dot_codex_folder) catch false) and
            try projectTrustedBySelfOrAncestor(allocator, context.userBytes(), current))
        {
            const config_path = try std.fs.path.join(allocator, &.{ dot_codex_folder, "config.toml" });
            defer allocator.free(config_path);
            const project_config_bytes = config.readConfigTomlFile(allocator, config_path) catch null;
            defer if (project_config_bytes) |bytes| allocator.free(bytes);
            if (project_config_bytes) |bytes| {
                if (try projectIgnoredConfigKeysWarningSummary(allocator, config_path, bytes)) |message| {
                    defer allocator.free(message);
                    try queueConfigWarningNotification(allocator, state, message, null);
                }
            }
        }

        const parent = std.fs.path.dirname(current) orelse break;
        if (parent.len == current.len) break;
        current = parent;
    }
}

fn projectIgnoredConfigKeysWarningSummary(allocator: std.mem.Allocator, config_path: []const u8, config_bytes: []const u8) !?[]u8 {
    var ignored = std.ArrayList([]const u8).empty;
    defer ignored.deinit(allocator);
    for (&project_local_config_denylist) |key| {
        if (projectConfigHasRootKey(config_bytes, key)) {
            try ignored.append(allocator, key);
        }
    }
    if (ignored.items.len == 0) return null;

    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "Ignored unsupported project-local config keys in ");
    try result.appendSlice(allocator, config_path);
    try result.appendSlice(allocator, ": ");
    for (ignored.items, 0..) |key, index| {
        if (index > 0) try result.appendSlice(allocator, ", ");
        try result.appendSlice(allocator, key);
    }
    try result.appendSlice(allocator, ". If you want these settings to apply, manually set them in your user-level config.toml.");
    const owned = try result.toOwnedSlice(allocator);
    return owned;
}

fn projectConfigHasRootKey(config_bytes: []const u8, key: []const u8) bool {
    var in_top_level = true;
    var iter = std.mem.splitScalar(u8, config_bytes, '\n');
    while (iter.next()) |line_raw| {
        const line_without_comment = if (std.mem.indexOfScalar(u8, line_raw, '#')) |index| line_raw[0..index] else line_raw;
        const line = std.mem.trim(u8, line_without_comment, " \t\r");
        if (line.len == 0) continue;

        if (line[0] == '[') {
            in_top_level = false;
            if (projectConfigSectionRootMatches(line, key)) return true;
            continue;
        }

        if (!in_top_level) continue;
        const eq = tomlAssignmentEqualsIndex(line) orelse continue;
        const raw_key = std.mem.trim(u8, line[0..eq], " \t");
        if (tomlKeyRootMatches(raw_key, key)) return true;
    }
    return false;
}

fn projectConfigSectionRootMatches(line: []const u8, key: []const u8) bool {
    if (line.len < "[]".len or line[0] != '[' or line[line.len - 1] != ']') return false;
    const section = std.mem.trim(u8, line[1 .. line.len - 1], " \t");
    return tomlKeyRootMatches(section, key);
}

fn tomlKeyRootMatches(raw_key: []const u8, key: []const u8) bool {
    const root_end = std.mem.indexOfScalar(u8, raw_key, '.') orelse raw_key.len;
    const root = raw_key[0..root_end];
    if (std.mem.eql(u8, root, key)) return true;

    if (root.len == key.len + 2 and root[0] == '"' and root[root.len - 1] == '"') {
        return std.mem.eql(u8, root[1 .. root.len - 1], key);
    }
    return false;
}

fn appendProjectConfigDisabledEntry(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    index: usize,
    dot_codex_folder: []const u8,
    project_path: []const u8,
    user_config_path: []const u8,
    user_config_bytes: []const u8,
) !void {
    try result.appendSlice(allocator, "    ");
    try appendInt(allocator, result, index);
    try result.appendSlice(allocator, ". ");
    try result.appendSlice(allocator, dot_codex_folder);
    try result.appendSlice(allocator, "\n       ");

    const trust_level = try config.namedSectionStringValue(allocator, user_config_bytes, "projects.", project_path, "trust_level");
    defer if (trust_level) |value| allocator.free(value);
    if (trust_level) |value| {
        if (std.mem.eql(u8, value, "untrusted")) {
            try result.appendSlice(allocator, project_path);
            try result.appendSlice(allocator, " is marked as untrusted in ");
            try result.appendSlice(allocator, user_config_path);
            try result.appendSlice(allocator, ". To load ");
            try result.appendSlice(allocator, project_config_gated_features);
            try result.appendSlice(allocator, ", mark it trusted.\n");
            return;
        }
    }

    try result.appendSlice(allocator, "To load ");
    try result.appendSlice(allocator, project_config_gated_features);
    try result.appendSlice(allocator, ", add ");
    try result.appendSlice(allocator, project_path);
    try result.appendSlice(allocator, " as a trusted project in ");
    try result.appendSlice(allocator, user_config_path);
    try result.appendSlice(allocator, ".\n");
}

fn projectTrustedBySelfOrAncestor(allocator: std.mem.Allocator, user_config_bytes: []const u8, project_path: []const u8) !bool {
    var current: []const u8 = project_path;
    while (true) {
        if (try configReadProjectTrusted(allocator, user_config_bytes, current)) return true;
        const parent = std.fs.path.dirname(current) orelse break;
        if (parent.len == current.len) break;
        current = parent;
    }
    return false;
}

const deprecated_on_failure_approval_policy_warning = "`on-failure` approval policy is deprecated and will be removed in a future release. Use `on-request` for interactive approvals or `never` for non-interactive runs.";

fn queueDeprecatedApprovalPolicyWarningNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread: *const LoadedThread,
) !void {
    if (notificationMethodOptedOut(state, "warning")) return;
    if (!std.mem.eql(u8, thread.approval_policy, "on-failure")) return;

    try queueWarningNotification(allocator, state, thread.id, deprecated_on_failure_approval_policy_warning);
}

fn queueHookStartupWarningNotifications(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    codex_home: []const u8,
    thread_id: []const u8,
) !void {
    if (notificationMethodOptedOut(state, "warning")) return;

    if (state.bypass_hook_trust) {
        try queueWarningNotification(allocator, state, thread_id, "`--dangerously-bypass-hook-trust` is enabled. Enabled hooks may run without review for this invocation.");
    }

    var warnings = try hooks_list.startupWarnings(allocator, codex_home);
    defer warnings.deinit(allocator);
    for (warnings.items) |message| {
        try queueWarningNotification(allocator, state, thread_id, message);
    }
}

fn queueWarningNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread_id: ?[]const u8,
    message: []const u8,
) !void {
    if (notificationMethodOptedOut(state, "warning")) return;

    const notification = try renderWarningNotification(allocator, thread_id, message);
    errdefer allocator.free(notification);
    try state.pending_notifications.append(allocator, notification);
}

fn renderWarningNotification(allocator: std.mem.Allocator, thread_id: ?[]const u8, message: []const u8) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"warning\",\"params\":{\"threadId\":");
    try appendOptionalJsonString(allocator, &result, thread_id);
    try result.appendSlice(allocator, ",\"message\":");
    try appendJsonString(allocator, &result, message);
    try result.appendSlice(allocator, "}}");
    return result.toOwnedSlice(allocator);
}

