const ThreadTurnsCursor = struct {
    turn_id: []const u8,
    include_anchor: bool,
};

const ThreadTurnItemsView = enum {
    not_loaded,
    summary,
    full,
};

fn renderThreadTurnsListResponse(allocator: std.mem.Allocator, thread: *const LoadedThread, params: std.json.ObjectMap) ![]const u8 {
    return renderThreadTurnsListResponseWithDefaultItemsView(allocator, thread, params, .summary);
}

fn renderThreadTurnsListResponseWithDefaultItemsView(
    allocator: std.mem.Allocator,
    thread: *const LoadedThread,
    params: std.json.ObjectMap,
    default_items_view: ThreadTurnItemsView,
) ![]const u8 {
    var parsed_turns = try std.json.parseFromSlice(std.json.Value, allocator, thread.turns_json, .{});
    defer parsed_turns.deinit();
    if (parsed_turns.value != .array) return error.InvalidThreadTurnsData;

    const turns = parsed_turns.value.array.items;
    var cursor_parse: ?std.json.Parsed(std.json.Value) = null;
    defer if (cursor_parse) |*parsed| parsed.deinit();
    const anchor: ?ThreadTurnsCursor = if (optionalStringParam(params, "cursor")) |cursor| blk: {
        cursor_parse = std.json.parseFromSlice(std.json.Value, allocator, cursor, .{}) catch return error.InvalidThreadTurnsCursor;
        break :blk threadTurnsCursorFromValue(cursor_parse.?.value) orelse return error.InvalidThreadTurnsCursor;
    } else null;

    const anchor_index = if (anchor) |value| findTurnIndexById(turns, value.turn_id) else null;
    if (anchor != null and anchor_index == null) return error.InvalidThreadTurnsCursorAnchor;

    var indices = std.ArrayList(usize).empty;
    defer indices.deinit(allocator);
    const sort_direction = optionalStringParam(params, "sortDirection") orelse "desc";
    if (std.mem.eql(u8, sort_direction, "asc")) {
        for (turns, 0..) |_, index| {
            if (anchor) |value| {
                const anchor_pos = anchor_index.?;
                if (value.include_anchor) {
                    if (index < anchor_pos) continue;
                } else if (index <= anchor_pos) continue;
            }
            try indices.append(allocator, index);
        }
    } else {
        var index = turns.len;
        while (index > 0) {
            index -= 1;
            if (anchor) |value| {
                const anchor_pos = anchor_index.?;
                if (value.include_anchor) {
                    if (index > anchor_pos) continue;
                } else if (index >= anchor_pos) continue;
            }
            try indices.append(allocator, index);
        }
    }

    const requested_limit = threadTurnsListLimit(params) orelse THREAD_TURNS_DEFAULT_LIMIT;
    const page_size = @min(@max(requested_limit, 1), THREAD_TURNS_MAX_LIMIT);
    const page_len = @min(indices.items.len, page_size);
    const more_turns_available = indices.items.len > page_size;
    const items_view = threadTurnsItemsView(params) orelse default_items_view;
    const json_arena_allocator = parsed_turns.arena.allocator();

    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"data\":[");
    for (indices.items[0..page_len], 0..) |turn_index, out_index| {
        if (out_index > 0) try result.append(allocator, ',');
        try applyThreadTurnItemsView(json_arena_allocator, &turns[turn_index], items_view);
        const turn_json = try std.json.Stringify.valueAlloc(allocator, turns[turn_index], .{});
        defer allocator.free(turn_json);
        try result.appendSlice(allocator, turn_json);
    }
    try result.appendSlice(allocator, "],\"nextCursor\":");
    if (more_turns_available) {
        const last_turn_id = turnIdFromValue(turns[indices.items[page_len - 1]]) orelse return error.InvalidThreadTurnsData;
        const next_cursor = try serializeThreadTurnsCursor(allocator, last_turn_id, false);
        defer allocator.free(next_cursor);
        try appendJsonString(allocator, &result, next_cursor);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, ",\"backwardsCursor\":");
    if (page_len > 0) {
        const first_turn_id = turnIdFromValue(turns[indices.items[0]]) orelse return error.InvalidThreadTurnsData;
        const backwards_cursor = try serializeThreadTurnsCursor(allocator, first_turn_id, true);
        defer allocator.free(backwards_cursor);
        try appendJsonString(allocator, &result, backwards_cursor);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.append(allocator, '}');
    return result.toOwnedSlice(allocator);
}

fn threadTurnsItemsView(params: std.json.ObjectMap) ?ThreadTurnItemsView {
    const value = optionalStringParam(params, "itemsView") orelse return null;
    if (std.mem.eql(u8, value, "notLoaded")) return .not_loaded;
    if (std.mem.eql(u8, value, "summary")) return .summary;
    if (std.mem.eql(u8, value, "full")) return .full;
    return null;
}

fn applyThreadTurnItemsView(allocator: std.mem.Allocator, turn: *std.json.Value, items_view: ThreadTurnItemsView) !void {
    if (turn.* != .object) return error.InvalidThreadTurnsData;
    const items_value = turn.object.getPtr("items") orelse return error.InvalidThreadTurnsData;
    if (items_value.* != .array) return error.InvalidThreadTurnsData;

    switch (items_view) {
        .not_loaded => {
            items_value.* = .{ .array = std.json.Array.init(allocator) };
            try turn.object.put(allocator, "itemsView", .{ .string = "notLoaded" });
        },
        .summary => {
            var summary_items = std.json.Array.init(allocator);
            if (firstThreadItemWithType(items_value.array.items, "userMessage")) |user_message| {
                try summary_items.append(user_message);
            }
            if (lastThreadItemWithType(items_value.array.items, "agentMessage")) |agent_message| {
                try summary_items.append(agent_message);
            }
            items_value.* = .{ .array = summary_items };
            try turn.object.put(allocator, "itemsView", .{ .string = "summary" });
        },
        .full => {
            try turn.object.put(allocator, "itemsView", .{ .string = "full" });
        },
    }
}

fn firstThreadItemWithType(items: []const std.json.Value, item_type: []const u8) ?std.json.Value {
    for (items) |item| {
        if (threadItemTypeEquals(item, item_type)) return item;
    }
    return null;
}

fn lastThreadItemWithType(items: []const std.json.Value, item_type: []const u8) ?std.json.Value {
    var index = items.len;
    while (index > 0) {
        index -= 1;
        if (threadItemTypeEquals(items[index], item_type)) return items[index];
    }
    return null;
}

fn threadItemTypeEquals(item: std.json.Value, item_type: []const u8) bool {
    if (item != .object) return false;
    const value = item.object.get("type") orelse return false;
    return value == .string and std.mem.eql(u8, value.string, item_type);
}

fn threadTurnsCursorFromValue(value: std.json.Value) ?ThreadTurnsCursor {
    if (value != .object) return null;
    const turn_id = value.object.get("turnId") orelse return null;
    if (turn_id != .string) return null;
    const include_anchor = value.object.get("includeAnchor") orelse return null;
    if (include_anchor != .bool) return null;
    return .{ .turn_id = turn_id.string, .include_anchor = include_anchor.bool };
}

fn findTurnIndexById(turns: []const std.json.Value, turn_id: []const u8) ?usize {
    for (turns, 0..) |turn, index| {
        const id = turnIdFromValue(turn) orelse continue;
        if (std.mem.eql(u8, id, turn_id)) return index;
    }
    return null;
}

fn turnIdFromValue(turn: std.json.Value) ?[]const u8 {
    if (turn != .object) return null;
    const id = turn.object.get("id") orelse return null;
    if (id != .string) return null;
    return id.string;
}

fn serializeThreadTurnsCursor(allocator: std.mem.Allocator, turn_id: []const u8, include_anchor: bool) ![]const u8 {
    return std.json.Stringify.valueAlloc(allocator, .{ .turnId = turn_id, .includeAnchor = include_anchor }, .{});
}

fn appendLoadedThreadJson(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    thread: *const LoadedThread,
    include_turns: bool,
    status: ThreadRuntimeStatus,
) !void {
    try result.appendSlice(allocator, "{\"id\":");
    try appendJsonString(allocator, result, thread.id);
    try result.appendSlice(allocator, ",\"sessionId\":");
    try appendJsonString(allocator, result, thread.session_id);
    try result.appendSlice(allocator, ",\"forkedFromId\":");
    try appendOptionalJsonString(allocator, result, thread.forked_from_id);
    try result.appendSlice(allocator, ",\"preview\":");
    try appendJsonString(allocator, result, thread.preview);
    try result.appendSlice(allocator, ",\"ephemeral\":");
    try result.appendSlice(allocator, if (thread.ephemeral) "true" else "false");
    try result.appendSlice(allocator, ",\"modelProvider\":");
    try appendJsonString(allocator, result, thread.model_provider);
    try result.appendSlice(allocator, ",\"createdAt\":");
    const created_at = try std.fmt.allocPrint(allocator, "{d}", .{thread.created_at});
    defer allocator.free(created_at);
    try result.appendSlice(allocator, created_at);
    try result.appendSlice(allocator, ",\"updatedAt\":");
    const updated_at = try std.fmt.allocPrint(allocator, "{d}", .{thread.updated_at});
    defer allocator.free(updated_at);
    try result.appendSlice(allocator, updated_at);
    try result.appendSlice(allocator, ",\"status\":");
    try appendLoadedThreadRuntimeStatusJson(allocator, result, thread, status);
    try result.appendSlice(allocator, ",\"path\":");
    try appendOptionalJsonString(allocator, result, thread.path);
    try result.appendSlice(allocator, ",\"cwd\":");
    try appendJsonString(allocator, result, thread.cwd);
    try result.appendSlice(allocator, ",\"cliVersion\":");
    try appendJsonString(allocator, result, thread.cli_version);
    try result.appendSlice(allocator, ",\"source\":");
    try appendThreadSourceJson(allocator, result, thread.source);
    try result.appendSlice(allocator, ",\"threadSource\":");
    try appendOptionalJsonString(allocator, result, thread.thread_source);
    try result.appendSlice(allocator, ",\"agentNickname\":");
    try appendOptionalJsonString(allocator, result, thread.agent_nickname);
    try result.appendSlice(allocator, ",\"agentRole\":");
    try appendOptionalJsonString(allocator, result, thread.agent_role);
    try result.appendSlice(allocator, ",\"gitInfo\":");
    try appendLoadedThreadGitInfoJson(allocator, result, thread);
    try result.appendSlice(allocator, ",\"name\":");
    try appendOptionalJsonString(allocator, result, thread.name);
    try result.appendSlice(allocator, ",\"turns\":");
    try result.appendSlice(allocator, if (include_turns) thread.turns_json else "[]");
    try result.append(allocator, '}');
}

fn appendLoadedThreadRuntimeStatusJson(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    thread: *const LoadedThread,
    status: ThreadRuntimeStatus,
) !void {
    try appendThreadRuntimeStatusJsonWithFlags(
        allocator,
        result,
        status,
        thread.pending_permission_requests > 0,
        thread.pending_user_input_requests > 0,
    );
}

fn appendThreadRuntimeStatusJson(allocator: std.mem.Allocator, result: *std.ArrayList(u8), status: ThreadRuntimeStatus) !void {
    try appendThreadRuntimeStatusJsonWithFlags(allocator, result, status, false, false);
}

fn appendThreadRuntimeStatusJsonWithFlags(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    status: ThreadRuntimeStatus,
    waiting_on_approval: bool,
    waiting_on_user_input: bool,
) !void {
    try result.appendSlice(allocator, switch (status) {
        .active => "{\"type\":\"active\",\"activeFlags\":[",
        .idle => "{\"type\":\"idle\"}",
        .not_loaded => "{\"type\":\"notLoaded\"}",
        .system_error => "{\"type\":\"systemError\"}",
    });
    if (status == .active) {
        var first = true;
        if (waiting_on_approval) {
            try appendJsonString(allocator, result, "waitingOnApproval");
            first = false;
        }
        if (waiting_on_user_input) {
            if (!first) try result.append(allocator, ',');
            try appendJsonString(allocator, result, "waitingOnUserInput");
        }
        try result.appendSlice(allocator, "]}");
    }
}

fn appendThreadListItemJson(allocator: std.mem.Allocator, result: *std.ArrayList(u8), thread: ThreadListItem) !void {
    switch (thread) {
        .loaded => |loaded| try appendLoadedThreadJson(allocator, result, loaded, false, loaded.status),
        .saved => |saved| try appendSavedThreadListItemJson(allocator, result, saved),
    }
}

