fn appendThreadPermissionProfileJson(allocator: std.mem.Allocator, result: *std.ArrayList(u8), thread: *const LoadedThread) !void {
    if (thread.sandbox_external) {
        try result.appendSlice(allocator, "{\"type\":\"external\",\"network\":{\"enabled\":");
        try appendJsonBool(allocator, result, thread.sandbox_network_enabled);
        try result.appendSlice(allocator, "}}");
    } else if (std.mem.eql(u8, thread.sandbox_mode, "danger-full-access")) {
        try result.appendSlice(allocator, "{\"type\":\"disabled\"}");
    } else {
        try result.appendSlice(allocator, "{\"type\":\"managed\",\"fileSystem\":");
        try appendThreadPermissionProfileFileSystemJson(allocator, result, thread);
        try result.appendSlice(allocator, ",\"network\":{\"enabled\":");
        try appendJsonBool(allocator, result, thread.sandbox_network_enabled);
        try result.appendSlice(allocator, "}}");
    }
}

fn appendThreadPermissionProfileFileSystemJson(allocator: std.mem.Allocator, result: *std.ArrayList(u8), thread: *const LoadedThread) !void {
    try result.appendSlice(allocator, "{\"type\":\"restricted\",\"entries\":[");
    try result.appendSlice(allocator, "{\"path\":{\"type\":\"special\",\"value\":{\"kind\":\"root\"}},\"access\":\"read\"}");
    for (thread.sandbox_read_denied_roots.items) |root| {
        try result.appendSlice(allocator, ",{\"path\":{\"type\":\"path\",\"path\":");
        try appendJsonString(allocator, result, root);
        try result.appendSlice(allocator, "},\"access\":\"none\"}");
    }
    for (thread.sandbox_read_denied_globs.items) |pattern| {
        try result.appendSlice(allocator, ",{\"path\":{\"type\":\"glob_pattern\",\"pattern\":");
        try appendJsonString(allocator, result, pattern);
        try result.appendSlice(allocator, "},\"access\":\"none\"}");
    }
    if (std.mem.eql(u8, thread.sandbox_mode, "workspace-write")) {
        if (thread.sandbox_include_cwd_write_root) {
            try result.appendSlice(allocator, ",{\"path\":{\"type\":\"special\",\"value\":{\"kind\":\"project_roots\"}},\"access\":\"write\"}");
        }
        for (thread.sandbox_writable_roots.items) |root| {
            try result.appendSlice(allocator, ",{\"path\":{\"type\":\"path\",\"path\":");
            try appendJsonString(allocator, result, root);
            try result.appendSlice(allocator, "},\"access\":\"write\"}");
        }
        if (!thread.sandbox_exclude_tmpdir_env_var) {
            try result.appendSlice(allocator, ",{\"path\":{\"type\":\"special\",\"value\":{\"kind\":\"tmpdir\"}},\"access\":\"write\"}");
        }
        if (!thread.sandbox_exclude_slash_tmp) {
            try result.appendSlice(allocator, ",{\"path\":{\"type\":\"special\",\"value\":{\"kind\":\"slash_tmp\"}},\"access\":\"write\"}");
        }
    }
    try result.appendSlice(allocator, "]}");
}

fn updateInitializeCapabilities(allocator: std.mem.Allocator, state: *AppServerState, params_value: ?std.json.Value) !void {
    clearOptOutNotificationMethods(allocator, state);
    state.experimental_api_enabled = false;
    const params = params_value orelse return;
    if (params != .object) return;
    const capabilities = params.object.get("capabilities") orelse return;
    if (capabilities == .null) return;
    if (capabilities != .object) return;
    if (capabilities.object.get("experimentalApi")) |experimental_api| {
        if (experimental_api == .bool) state.experimental_api_enabled = experimental_api.bool;
    }
    const opt_out = capabilities.object.get("optOutNotificationMethods") orelse return;
    if (opt_out == .null) return;
    if (opt_out != .array) return;
    for (opt_out.array.items) |method| {
        if (method != .string) continue;
        const owned = try allocator.dupe(u8, method.string);
        errdefer allocator.free(owned);
        try state.opt_out_notification_methods.append(allocator, owned);
    }
}

fn experimentalReasonForRequestMethod(method: []const u8) ?[]const u8 {
    inline for (&.{
        "memory/reset",
        "fuzzyFileSearch/sessionStart",
        "fuzzyFileSearch/sessionUpdate",
        "fuzzyFileSearch/sessionStop",
        "collaborationMode/list",
        "process/spawn",
        "process/writeStdin",
        "process/kill",
        "process/resizePty",
        "thread/backgroundTerminals/clean",
        "thread/backgroundTerminals/list",
        "thread/backgroundTerminals/terminate",
        "thread/increment_elicitation",
        "thread/decrement_elicitation",
        "thread/goal/set",
        "thread/goal/get",
        "thread/goal/clear",
        "thread/memoryMode/set",
        "thread/settings/update",
        "thread/turns/list",
        "thread/items/list",
        "thread/realtime/start",
        "thread/realtime/appendAudio",
        "thread/realtime/appendSpeech",
        "thread/realtime/appendText",
        "thread/realtime/stop",
        "thread/realtime/listVoices",
        "remoteControl/enable",
        "remoteControl/disable",
        "remoteControl/status/read",
        "remoteControl/pairing/start",
        "remoteControl/pairing/status",
        "remoteControl/client/list",
        "remoteControl/client/revoke",
        "environment/add",
        "environment/info",
        "environment/status",
    }) |experimental_method| {
        if (std.mem.eql(u8, method, experimental_method)) return experimental_method;
    }
    return null;
}

fn experimentalReasonForServerNotificationMethod(method: []const u8) ?[]const u8 {
    inline for (&.{
        .{ .method = "thread/goal/updated", .reason = "thread/goal/updated" },
        .{ .method = "thread/goal/cleared", .reason = "thread/goal/cleared" },
        .{ .method = "thread/settings/updated", .reason = "thread/settings/updated" },
        .{ .method = "process/outputDelta", .reason = "process/outputDelta" },
        .{ .method = "process/exited", .reason = "process/exited" },
        .{ .method = "thread/realtime/started", .reason = "thread/realtime/started" },
        .{ .method = "thread/realtime/itemAdded", .reason = "thread/realtime/itemAdded" },
        .{ .method = "thread/realtime/transcript/delta", .reason = "thread/realtime/transcript/delta" },
        .{ .method = "thread/realtime/transcript/done", .reason = "thread/realtime/transcript/done" },
        .{ .method = "thread/realtime/outputAudio/delta", .reason = "thread/realtime/outputAudio/delta" },
        .{ .method = "thread/realtime/sdp", .reason = "thread/realtime/sdp" },
        .{ .method = "thread/realtime/error", .reason = "thread/realtime/error" },
        .{ .method = "thread/realtime/closed", .reason = "thread/realtime/closed" },
    }) |experimental_notification| {
        if (std.mem.eql(u8, method, experimental_notification.method)) return experimental_notification.reason;
    }
    return null;
}

fn renderExperimentalApiRequiredError(
    allocator: std.mem.Allocator,
    id_value: ?std.json.Value,
    reason: []const u8,
) ![]const u8 {
    const message = try std.fmt.allocPrint(allocator, "{s} requires experimentalApi capability", .{reason});
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32600, message);
}

fn experimentalReasonForRequestFields(method: []const u8, params_value: ?std.json.Value) ?[]const u8 {
    const params = params_value orelse return null;
    if (params == .null) return null;
    if (params != .object) return null;
    const object = params.object;

    if (std.mem.eql(u8, method, "thread/start")) return experimentalReasonForThreadStartFields(object);
    if (std.mem.eql(u8, method, "thread/resume")) return experimentalReasonForThreadResumeFields(object);
    if (std.mem.eql(u8, method, "thread/fork")) return experimentalReasonForThreadForkFields(object);
    if (std.mem.eql(u8, method, "turn/start")) return experimentalReasonForTurnStartFields(object);
    if (std.mem.eql(u8, method, "turn/steer")) return experimentalReasonForTurnSteerFields(object);
    if (std.mem.eql(u8, method, "command/exec")) return experimentalReasonForCommandExecFields(object);
    if (std.mem.eql(u8, method, "account/login/start")) return experimentalReasonForAccountLoginStartFields(object);
    return null;
}

fn experimentalReasonForThreadStartFields(object: std.json.ObjectMap) ?[]const u8 {
    if (experimentalReasonForApprovalPolicy(object)) |reason| return reason;
    inline for (&.{
        .{ .field = "permissions", .reason = "thread/start.permissions" },
        .{ .field = "environments", .reason = "thread/start.environments" },
        .{ .field = "dynamicTools", .reason = "thread/start.dynamicTools" },
        .{ .field = "mockExperimentalField", .reason = "thread/start.mockExperimentalField" },
    }) |gate| {
        if (optionalExperimentalFieldIsSet(object, gate.field)) return gate.reason;
    }
    if (boolExperimentalFieldIsEnabled(object, "experimentalRawEvents")) return "thread/start.experimentalRawEvents";
    if (boolExperimentalFieldIsEnabled(object, "persistExtendedHistory")) return "thread/start.persistFullHistory";
    return null;
}

fn experimentalReasonForThreadResumeFields(object: std.json.ObjectMap) ?[]const u8 {
    inline for (&.{
        .{ .field = "history", .reason = "thread/resume.history" },
        .{ .field = "path", .reason = "thread/resume.path" },
        .{ .field = "initialTurnsPage", .reason = "thread/resume.initialTurnsPage" },
    }) |gate| {
        if (optionalExperimentalFieldIsSet(object, gate.field)) return gate.reason;
    }
    if (experimentalReasonForApprovalPolicy(object)) |reason| return reason;
    if (optionalExperimentalFieldIsSet(object, "permissions")) return "thread/resume.permissions";
    if (boolExperimentalFieldIsEnabled(object, "excludeTurns")) return "thread/resume.excludeTurns";
    if (boolExperimentalFieldIsEnabled(object, "persistExtendedHistory")) return "thread/resume.persistFullHistory";
    return null;
}

fn experimentalReasonForThreadForkFields(object: std.json.ObjectMap) ?[]const u8 {
    if (optionalExperimentalFieldIsSet(object, "path")) return "thread/fork.path";
    if (experimentalReasonForApprovalPolicy(object)) |reason| return reason;
    if (optionalExperimentalFieldIsSet(object, "permissions")) return "thread/fork.permissions";
    if (boolExperimentalFieldIsEnabled(object, "excludeTurns")) return "thread/fork.excludeTurns";
    if (boolExperimentalFieldIsEnabled(object, "persistExtendedHistory")) return "thread/fork.persistFullHistory";
    return null;
}

fn experimentalReasonForTurnStartFields(object: std.json.ObjectMap) ?[]const u8 {
    inline for (&.{
        .{ .field = "responsesapiClientMetadata", .reason = "turn/start.responsesapiClientMetadata" },
        .{ .field = "environments", .reason = "turn/start.environments" },
    }) |gate| {
        if (optionalExperimentalFieldIsSet(object, gate.field)) return gate.reason;
    }
    if (experimentalReasonForApprovalPolicy(object)) |reason| return reason;
    if (optionalExperimentalFieldIsSet(object, "permissions")) return "turn/start.permissions";
    if (optionalExperimentalFieldIsSet(object, "collaborationMode")) return "turn/start.collaborationMode";
    return null;
}

fn experimentalReasonForTurnSteerFields(object: std.json.ObjectMap) ?[]const u8 {
    if (optionalExperimentalFieldIsSet(object, "responsesapiClientMetadata")) return "turn/steer.responsesapiClientMetadata";
    return null;
}

fn experimentalReasonForCommandExecFields(object: std.json.ObjectMap) ?[]const u8 {
    if (optionalExperimentalFieldIsSet(object, "permissionProfile")) return "command/exec.permissionProfile";
    return null;
}

fn experimentalReasonForAccountLoginStartFields(object: std.json.ObjectMap) ?[]const u8 {
    const login_type = object.get("type") orelse return null;
    if (login_type != .string) return null;
    if (std.mem.eql(u8, login_type.string, "chatgptAuthTokens")) return "account/login/start.chatgptAuthTokens";
    return null;
}

fn experimentalReasonForApprovalPolicy(object: std.json.ObjectMap) ?[]const u8 {
    const value = object.get("approvalPolicy") orelse return null;
    if (value != .object) return null;
    if (value.object.get("granular")) |granular| {
        if (granular != .null) return "askForApproval.granular";
    }
    return null;
}

fn optionalExperimentalFieldIsSet(object: std.json.ObjectMap, field: []const u8) bool {
    const value = object.get(field) orelse return false;
    return value != .null;
}

fn boolExperimentalFieldIsEnabled(object: std.json.ObjectMap, field: []const u8) bool {
    const value = object.get(field) orelse return false;
    return value == .bool and value.bool;
}

fn clearOptOutNotificationMethods(allocator: std.mem.Allocator, state: *AppServerState) void {
    for (state.opt_out_notification_methods.items) |method| allocator.free(method);
    state.opt_out_notification_methods.clearRetainingCapacity();
}

fn notificationMethodOptedOut(state: *const AppServerState, method: []const u8) bool {
    for (state.opt_out_notification_methods.items) |opt_out_method| {
        if (std.mem.eql(u8, opt_out_method, method)) return true;
    }
    return false;
}

fn renderThreadNotFoundForThreadIdParam(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
        error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
    };
    const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
        error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
    };
    if (!isUuidString(thread_id)) {
        return renderInvalidThreadId(allocator, id_value, thread_id);
    }
    return renderThreadNotFound(allocator, id_value, thread_id);
}

fn renderThreadRealtimeFeatureDisabled(allocator: std.mem.Allocator, id_value: std.json.Value, thread_id: []const u8) ![]const u8 {
    const message = try std.fmt.allocPrint(
        allocator,
        "thread {s} does not support realtime conversation",
        .{thread_id},
    );
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32600, message);
}

fn handleThreadRealtimeAppendTextLike(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    const object = parseThreadObjectParams(params_value) catch |err| switch (err) {
        error.InvalidThreadParams => return renderThreadObjectParamsError(allocator, id_value, method),
    };
    const thread_id = requiredThreadIdParam(object) catch |err| switch (err) {
        error.MissingThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
    };
    const text = object.get("text") orelse return renderJsonRpcError(allocator, id_value, -32602, "text must be a string");
    if (text != .string) return renderJsonRpcError(allocator, id_value, -32602, "text must be a string");
    if (!isUuidString(thread_id)) {
        return renderInvalidThreadId(allocator, id_value, thread_id);
    }
    const thread_index = findLoadedThreadIndex(state, thread_id) orelse {
        return renderThreadNotFound(allocator, id_value, thread_id);
    };
    if (!(try appServerFeatureEnabled(allocator, state, "realtime_conversation"))) {
        return renderThreadRealtimeFeatureDisabled(allocator, id_value, thread_id);
    }
    try requireLoadedThreadRealtimeRunning(allocator, state, thread_index);
    return renderJsonRpcResult(allocator, id_value, "{}");
}

fn startLoadedThreadRealtime(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread_index: usize,
    object: std.json.ObjectMap,
) !void {
    var thread = &state.loaded_threads.items[thread_index];
    if (thread.realtime_session) |*session| {
        session.deinit(allocator);
        thread.realtime_session = null;
    }

    const transport = threadRealtimeStartTransport(object);
    if (std.mem.eql(u8, transport, "webrtc")) {
        try queueThreadRealtimeErrorNotification(
            allocator,
            state,
            thread.id,
            "realtime WebRTC transport requires upstream realtime backend support",
        );
        return;
    }

    var session_id: ?[]const u8 = null;
    errdefer if (session_id) |value| allocator.free(value);
    const requested_session_id = optionalStringParam(object, "realtimeSessionId") orelse thread.session_id;
    session_id = try allocator.dupe(u8, requested_session_id);

    thread.realtime_session = .{
        .session_id = session_id,
        .version = "v2",
    };
    session_id = null;

    try queueThreadRealtimeStartedNotification(
        allocator,
        state,
        thread.id,
        thread.realtime_session.?.session_id,
        thread.realtime_session.?.version,
    );
}

fn stopLoadedThreadRealtime(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread_index: usize,
) !void {
    var thread = &state.loaded_threads.items[thread_index];
    if (thread.realtime_session) |*session| {
        session.deinit(allocator);
        thread.realtime_session = null;
    }
    try queueThreadRealtimeClosedNotification(allocator, state, thread.id, "requested");
}

fn requireLoadedThreadRealtimeRunning(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread_index: usize,
) !void {
    const thread = &state.loaded_threads.items[thread_index];
    if (thread.realtime_session != null) return;
    try queueThreadRealtimeErrorNotification(allocator, state, thread.id, "conversation is not running");
}

fn threadRealtimeStartTransport(object: std.json.ObjectMap) []const u8 {
    const value = object.get("transport") orelse return "websocket";
    if (value == .null) return "websocket";
    return value.object.get("type").?.string;
}

fn queueThreadRealtimeStartedNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread_id: []const u8,
    realtime_session_id: ?[]const u8,
    version: []const u8,
) !void {
    const notification = try renderThreadRealtimeStartedNotification(allocator, thread_id, realtime_session_id, version);
    var notification_moved = false;
    errdefer if (!notification_moved) allocator.free(notification);
    try queuePendingServerNotification(allocator, state, "thread/realtime/started", notification);
    notification_moved = true;
}

fn queueThreadRealtimeClosedNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread_id: []const u8,
    reason: ?[]const u8,
) !void {
    const notification = try renderThreadRealtimeClosedNotification(allocator, thread_id, reason);
    var notification_moved = false;
    errdefer if (!notification_moved) allocator.free(notification);
    try queuePendingServerNotification(allocator, state, "thread/realtime/closed", notification);
    notification_moved = true;
}

fn queueThreadRealtimeErrorNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    thread_id: []const u8,
    message: []const u8,
) !void {
    const notification = try renderThreadRealtimeErrorNotification(allocator, thread_id, message);
    var notification_moved = false;
    errdefer if (!notification_moved) allocator.free(notification);
    try queuePendingServerNotification(allocator, state, "thread/realtime/error", notification);
    notification_moved = true;
}

fn renderThreadRealtimeStartedNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    realtime_session_id: ?[]const u8,
    version: []const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"thread/realtime/started\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"realtimeSessionId\":");
    try appendOptionalJsonString(allocator, &notification, realtime_session_id);
    try notification.appendSlice(allocator, ",\"version\":");
    try appendJsonString(allocator, &notification, version);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

fn renderThreadRealtimeClosedNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    reason: ?[]const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"thread/realtime/closed\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"reason\":");
    try appendOptionalJsonString(allocator, &notification, reason);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

fn renderThreadRealtimeErrorNotification(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    message: []const u8,
) ![]const u8 {
    var notification = std.ArrayList(u8).empty;
    errdefer notification.deinit(allocator);
    try notification.appendSlice(allocator, "{\"jsonrpc\":\"2.0\",\"method\":\"thread/realtime/error\",\"params\":{\"threadId\":");
    try appendJsonString(allocator, &notification, thread_id);
    try notification.appendSlice(allocator, ",\"message\":");
    try appendJsonString(allocator, &notification, message);
    try notification.appendSlice(allocator, "}}");
    return notification.toOwnedSlice(allocator);
}

fn parseThreadObjectParams(params_value: ?std.json.Value) !std.json.ObjectMap {
    const params = params_value orelse return error.InvalidThreadParams;
    if (params != .object) return error.InvalidThreadParams;
    return params.object;
}

fn requiredThreadIdParam(object: std.json.ObjectMap) ![]const u8 {
    const thread_id = object.get("threadId") orelse return error.MissingThreadId;
    if (thread_id != .string) return error.MissingThreadId;
    return thread_id.string;
}

fn requiredThreadNumTurnsParam(object: std.json.ObjectMap) !u32 {
    const num_turns = object.get("numTurns") orelse return error.InvalidNumTurns;
    if (num_turns != .integer) return error.InvalidNumTurns;
    if (num_turns.integer < 0 or num_turns.integer > std.math.maxInt(u32)) return error.InvalidNumTurns;
    return @intCast(num_turns.integer);
}

fn appServerFeatureEnabled(allocator: std.mem.Allocator, state: *const AppServerState, key: []const u8) !bool {
    return appServerFeatureEnabledForProfile(allocator, state, null, key);
}

fn appServerFeatureEnabledForProfile(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    profile: ?[]const u8,
    key: []const u8,
) !bool {
    var cfg = try loadAppServerConfig(allocator, state);
    defer cfg.deinit(allocator);
    const feature_profile: ?[]const u8 = if (profile) |value| value else cfg.active_profile;
    var config_overrides = try features_cmd.loadFeatureOverridesForProfile(allocator, cfg.codex_home, feature_profile);
    defer config_overrides.deinit(allocator);

    if (state.cli_feature_overrides.get(key)) |enabled| return enabled;
    if (config_overrides.get(key)) |enabled| return enabled;
    if (state.runtime_feature_enablement.get(key)) |enabled| return enabled;
    for (features_cmd.FeatureSpec.all) |feature| {
        if (std.mem.eql(u8, feature.key, key)) return feature.default_enabled;
    }
    return false;
}

fn appServerGoalsFeatureEnabledForRequest(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    params_value: ?std.json.Value,
) !bool {
    if (try appServerFeatureEnabled(allocator, state, "goals")) return true;
    const params = params_value orelse return false;
    if (params != .object) return false;
    const thread_id = params.object.get("threadId") orelse return false;
    if (thread_id != .string) return false;
    if (!isUuidString(thread_id.string)) return false;
    const thread_index = findLoadedThreadIndex(state, thread_id.string) orelse return false;
    const thread = &state.loaded_threads.items[thread_index];
    return appServerFeatureEnabledForProfile(allocator, state, thread.active_profile, "goals");
}

fn effectiveAppServerTurnFeatureOverrides(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    thread: *const LoadedThread,
) !features_cmd.FeatureOverrides {
    var overrides = features_cmd.FeatureOverrides{};
    errdefer overrides.deinit(allocator);
    try overrides.put(allocator, "apps", try appServerFeatureEnabledForProfile(allocator, state, thread.active_profile, "apps"));
    if (!thread.ephemeral and try appServerFeatureEnabledForProfile(allocator, state, thread.active_profile, "goals")) {
        try overrides.put(allocator, "goal_tools", true);
    }
    if (try appServerFeatureEnabledForProfile(allocator, state, thread.active_profile, "request_permissions_tool")) {
        try overrides.put(allocator, "request_permissions_tool", true);
    }
    const default_mode_request_user_input_enabled = try appServerFeatureEnabledForProfile(allocator, state, thread.active_profile, "default_mode_request_user_input");
    if (default_mode_request_user_input_enabled) {
        try overrides.put(allocator, "default_mode_request_user_input", true);
    }
    if (std.mem.eql(u8, thread.collaboration_mode, "plan") or default_mode_request_user_input_enabled) {
        try overrides.put(allocator, "request_user_input_tool", true);
    }
    return overrides;
}

fn guardianAssessmentEventIsValid(value: std.json.Value) bool {
    if (value != .object) return false;
    const object = value.object;
    if (!jsonRequiredStringFieldIsValid(object, "id")) return false;
    if (object.get("target_item_id")) |field| {
        if (!jsonOptionalStringValueIsValid(field)) return false;
    }
    if (object.get("turn_id")) |field| {
        if (field != .string) return false;
    }
    const status = object.get("status") orelse return false;
    if (!enumStringIsValid(status, &.{ "in_progress", "approved", "denied", "timed_out", "aborted" })) return false;
    if (object.get("risk_level")) |field| {
        if (!optionalEnumStringIsValid(field, &.{ "low", "medium", "high", "critical" })) return false;
    }
    if (object.get("user_authorization")) |field| {
        if (!optionalEnumStringIsValid(field, &.{ "unknown", "low", "medium", "high" })) return false;
    }
    if (object.get("rationale")) |field| {
        if (!jsonOptionalStringValueIsValid(field)) return false;
    }
    if (object.get("decision_source")) |field| {
        if (!optionalEnumStringIsValid(field, &.{"agent"})) return false;
    }
    const action = object.get("action") orelse return false;
    return guardianAssessmentActionIsValid(action);
}

fn guardianAssessmentActionIsValid(value: std.json.Value) bool {
    if (value != .object) return false;
    const object = value.object;
    const action_type = object.get("type") orelse return false;
    if (action_type != .string) return false;
    if (std.mem.eql(u8, action_type.string, "command")) {
        return guardianCommandSourceFieldIsValid(object) and
            jsonRequiredStringFieldIsValid(object, "command") and
            jsonRequiredStringFieldIsValid(object, "cwd");
    }
    if (std.mem.eql(u8, action_type.string, "execve")) {
        return guardianCommandSourceFieldIsValid(object) and
            jsonRequiredStringFieldIsValid(object, "program") and
            jsonRequiredStringArrayFieldIsValid(object, "argv") and
            jsonRequiredStringFieldIsValid(object, "cwd");
    }
    if (std.mem.eql(u8, action_type.string, "apply_patch")) {
        return jsonRequiredStringFieldIsValid(object, "cwd") and
            jsonRequiredStringArrayFieldIsValid(object, "files");
    }
    if (std.mem.eql(u8, action_type.string, "network_access")) {
        return jsonRequiredStringFieldIsValid(object, "target") and
            jsonRequiredStringFieldIsValid(object, "host") and
            guardianNetworkProtocolFieldIsValid(object) and
            jsonRequiredU16FieldIsValid(object, "port");
    }
    if (std.mem.eql(u8, action_type.string, "mcp_tool_call")) {
        return jsonRequiredStringFieldIsValid(object, "server") and
            jsonRequiredStringFieldIsValid(object, "tool_name") and
            jsonOptionalStringFieldIsValid(object, "connector_id") and
            jsonOptionalStringFieldIsValid(object, "connector_name") and
            jsonOptionalStringFieldIsValid(object, "tool_title");
    }
    if (std.mem.eql(u8, action_type.string, "request_permissions")) {
        return jsonOptionalStringFieldIsValid(object, "reason") and
            jsonRequiredObjectFieldIsValid(object, "permissions");
    }
    return false;
}

fn guardianCommandSourceFieldIsValid(object: std.json.ObjectMap) bool {
    const source = object.get("source") orelse return false;
    return enumStringIsValid(source, &.{ "shell", "unified_exec" });
}

fn guardianNetworkProtocolFieldIsValid(object: std.json.ObjectMap) bool {
    const protocol = object.get("protocol") orelse return false;
    return enumStringIsValid(protocol, &.{ "http", "https", "https_connect", "http-connect", "socks5_tcp", "socks5_udp" });
}

fn jsonRequiredStringFieldIsValid(object: std.json.ObjectMap, field: []const u8) bool {
    const value = object.get(field) orelse return false;
    return value == .string;
}

fn jsonOptionalStringFieldIsValid(object: std.json.ObjectMap, field: []const u8) bool {
    const value = object.get(field) orelse return true;
    return jsonOptionalStringValueIsValid(value);
}

fn jsonOptionalStringValueIsValid(value: std.json.Value) bool {
    return value == .null or value == .string;
}

fn jsonRequiredStringArrayFieldIsValid(object: std.json.ObjectMap, field: []const u8) bool {
    const value = object.get(field) orelse return false;
    if (value != .array) return false;
    for (value.array.items) |item| {
        if (item != .string) return false;
    }
    return true;
}

fn jsonRequiredObjectFieldIsValid(object: std.json.ObjectMap, field: []const u8) bool {
    const value = object.get(field) orelse return false;
    return value == .object;
}

fn jsonRequiredU16FieldIsValid(object: std.json.ObjectMap, field: []const u8) bool {
    const value = object.get(field) orelse return false;
    return value == .integer and value.integer >= 0 and value.integer <= std.math.maxInt(u16);
}

fn jsonRequiredU32FieldIsValid(object: std.json.ObjectMap, field: []const u8) bool {
    const value = object.get(field) orelse return false;
    return value == .integer and value.integer >= 0 and value.integer <= std.math.maxInt(u32);
}

fn threadMemoryModeParamIsValid(object: std.json.ObjectMap) bool {
    const mode = object.get("mode") orelse return false;
    if (mode != .string) return false;
    return std.mem.eql(u8, mode.string, "enabled") or std.mem.eql(u8, mode.string, "disabled");
}

fn threadReadIncludeTurnsParamIsValid(object: std.json.ObjectMap) bool {
    const include_turns = object.get("includeTurns") orelse return true;
    return include_turns == .bool;
}

fn threadReadIncludeTurnsParam(object: std.json.ObjectMap) bool {
    const include_turns = object.get("includeTurns") orelse return false;
    return include_turns.bool;
}

fn threadTurnsListLimit(object: std.json.ObjectMap) ?usize {
    const limit = object.get("limit") orelse return null;
    if (limit == .null) return null;
    return @intCast(limit.integer);
}

fn validateThreadTurnsListParams(object: std.json.ObjectMap) ?[]const u8 {
    return validateThreadTurnsPageParams(object, true);
}

fn validateThreadItemsListParams(object: std.json.ObjectMap) ?[]const u8 {
    if (object.get("turnId")) |value| {
        if (value != .null and value != .string) return "turnId must be a string or null";
    }
    if (object.get("cursor")) |value| {
        if (value != .null and value != .string) return "cursor must be a string or null";
    }
    if (object.get("limit")) |value| {
        switch (value) {
            .null => {},
            .integer => |integer| if (integer < 0 or integer > std.math.maxInt(u32)) return "limit must be a non-negative integer or null",
            else => return "limit must be a non-negative integer or null",
        }
    }
    if (object.get("sortDirection")) |value| {
        if (!optionalEnumStringIsValid(value, &.{ "asc", "desc" })) return "sortDirection must be asc or desc";
    }
    return null;
}

fn validateThreadTurnsPageParams(object: std.json.ObjectMap, allow_cursor: bool) ?[]const u8 {
    if (allow_cursor) {
        if (object.get("cursor")) |value| {
            if (value != .null and value != .string) return "cursor must be a string or null";
        }
    }
    if (object.get("limit")) |value| {
        switch (value) {
            .null => {},
            .integer => |integer| if (integer < 0 or integer > std.math.maxInt(u32)) return "limit must be a non-negative integer or null",
            else => return "limit must be a non-negative integer or null",
        }
    }
    if (object.get("sortDirection")) |value| {
        if (!optionalEnumStringIsValid(value, &.{ "asc", "desc" })) return "sortDirection must be asc or desc";
    }
    if (object.get("itemsView")) |value| {
        if (!optionalEnumStringIsValid(value, &.{ "notLoaded", "summary", "full" })) return "itemsView must be notLoaded, summary, full, or null";
    }
    return null;
}

fn validateThreadRealtimeAudioParam(object: std.json.ObjectMap) ?[]const u8 {
    const audio = object.get("audio") orelse return "audio must be an object";
    if (audio != .object) return "audio must be an object";
    return validateThreadRealtimeAudioChunk(audio.object);
}

fn validateThreadRealtimeAudioChunk(object: std.json.ObjectMap) ?[]const u8 {
    if (!jsonRequiredStringFieldIsValid(object, "data")) return "audio.data must be a string";
    if (!jsonRequiredU32FieldIsValid(object, "sampleRate")) return "audio.sampleRate must be a non-negative integer";
    if (!jsonRequiredU16FieldIsValid(object, "numChannels")) return "audio.numChannels must be a non-negative integer";
    if (object.get("samplesPerChannel")) |value| {
        switch (value) {
            .null => {},
            .integer => |integer| if (integer < 0 or integer > std.math.maxInt(u32)) return "audio.samplesPerChannel must be a non-negative integer or null",
            else => return "audio.samplesPerChannel must be a non-negative integer or null",
        }
    }
    if (object.get("itemId")) |value| {
        if (!jsonOptionalStringValueIsValid(value)) return "audio.itemId must be a string or null";
    }
    return null;
}

fn validateThreadGoalSetParams(object: std.json.ObjectMap) ?[]const u8 {
    const has_objective = object.get("objective") != null;
    const has_token_budget = object.get("tokenBudget") != null or object.get("token_budget") != null;
    if (object.get("objective")) |value| {
        if (!jsonOptionalStringValueIsValid(value)) return "goal objective must be a string or null";
        if (value == .string) {
            const objective = std.mem.trim(u8, value.string, " \t\r\n");
            if (objective.len == 0) return "goal objective must not be empty";
            const count = std.unicode.utf8CountCodepoints(objective) catch objective.len;
            if (count > 4000) return "goal objective must be at most 4000 characters";
        }
    }
    if (object.get("status")) |value| {
        if (!optionalEnumStringIsValid(value, &.{ "active", "paused", "blocked", "usageLimited", "budgetLimited", "complete" })) return "goal status must be active, paused, blocked, usageLimited, budgetLimited, complete, or null";
    }
    if (object.get("tokenBudget")) |value| {
        if (validateThreadGoalBudgetValue(value, "tokenBudget", has_objective, has_token_budget)) |message| return message;
    }
    if (object.get("token_budget")) |value| {
        if (validateThreadGoalBudgetValue(value, "token_budget", has_objective, has_token_budget)) |message| return message;
    }
    return null;
}

fn validateThreadGoalBudgetValue(
    value: std.json.Value,
    comptime field: []const u8,
    has_objective: bool,
    has_token_budget: bool,
) ?[]const u8 {
    if (value != .null and value != .integer) return "goal " ++ field ++ " must be a positive integer or null";
    if ((has_objective or has_token_budget) and value == .integer and value.integer <= 0) {
        return "goal budgets must be positive when provided";
    }
    return null;
}

fn validateThreadRealtimeStartParams(object: std.json.ObjectMap) ?[]const u8 {
    const output_modality = object.get("outputModality") orelse return "outputModality must be text or audio";
    if (!enumStringIsValid(output_modality, &.{ "text", "audio" })) return "outputModality must be text or audio";
    if (object.get("prompt")) |value| {
        if (!jsonOptionalStringValueIsValid(value)) return "prompt must be a string or null";
    }
    if (object.get("realtimeSessionId")) |value| {
        if (!jsonOptionalStringValueIsValid(value)) return "realtimeSessionId must be a string or null";
    }
    if (object.get("voice")) |value| {
        if (!optionalEnumStringIsValid(value, &.{ "alloy", "arbor", "ash", "ballad", "breeze", "cedar", "coral", "cove", "echo", "ember", "juniper", "maple", "marin", "sage", "shimmer", "sol", "spruce", "vale", "verse" })) return "voice must be a supported realtime voice or null";
    }
    if (object.get("transport")) |value| {
        if (value == .null) return null;
        if (value != .object) return "transport must be an object or null";
        return validateThreadRealtimeStartTransport(value.object);
    }
    return null;
}

fn validateThreadRealtimeStartTransport(object: std.json.ObjectMap) ?[]const u8 {
    const transport_type = object.get("type") orelse return "transport.type must be websocket or webrtc";
    if (transport_type != .string) return "transport.type must be websocket or webrtc";
    if (std.mem.eql(u8, transport_type.string, "websocket")) return null;
    if (std.mem.eql(u8, transport_type.string, "webrtc")) {
        if (!jsonRequiredStringFieldIsValid(object, "sdp")) return "transport.sdp must be a string";
        return null;
    }
    return "transport.type must be websocket or webrtc";
}

const ThreadMetadataGitInfoValidationError = struct {
    code: i64,
    message: []const u8,
};

fn validateThreadMetadataGitInfoParams(object: std.json.ObjectMap) ?ThreadMetadataGitInfoValidationError {
    const git_info = object.get("gitInfo") orelse return .{ .code = -32600, .message = "gitInfo must include at least one field" };
    if (git_info == .null) return .{ .code = -32600, .message = "gitInfo must include at least one field" };
    if (git_info != .object) return .{ .code = -32602, .message = "gitInfo must be an object or null" };

    var saw_field = false;
    if (validateThreadMetadataGitInfoField(git_info.object, "sha", &saw_field)) |err| return err;
    if (validateThreadMetadataGitInfoField(git_info.object, "branch", &saw_field)) |err| return err;
    if (validateThreadMetadataGitInfoField(git_info.object, "originUrl", &saw_field)) |err| return err;
    if (!saw_field) return .{ .code = -32600, .message = "gitInfo must include at least one field" };
    return null;
}

fn validateThreadMetadataGitInfoField(
    object: std.json.ObjectMap,
    field_name: []const u8,
    saw_field: *bool,
) ?ThreadMetadataGitInfoValidationError {
    const value = object.get(field_name) orelse return null;
    saw_field.* = true;
    if (value == .null) return null;
    if (value != .string) {
        return .{ .code = -32602, .message = "gitInfo fields must be strings or null" };
    }
    if (std.mem.trim(u8, value.string, " \t\r\n").len == 0) {
        if (std.mem.eql(u8, field_name, "sha")) return .{ .code = -32600, .message = "gitInfo.sha must not be empty" };
        if (std.mem.eql(u8, field_name, "branch")) return .{ .code = -32600, .message = "gitInfo.branch must not be empty" };
        return .{ .code = -32600, .message = "gitInfo.originUrl must not be empty" };
    }
    return null;
}

fn renderThreadObjectParamsError(allocator: std.mem.Allocator, id_value: std.json.Value, method: []const u8) ![]const u8 {
    const message = try std.fmt.allocPrint(allocator, "{s} params must be an object", .{method});
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32602, message);
}

