}

fn handleProcessResizePty(allocator: std.mem.Allocator, state: *AppServerState, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    const object = switch (commandExecObjectParams(params_value, "process/resizePty")) {
        .object => |value| value,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };
    const process_handle = switch (commandExecRequiredStringField(object, "processHandle", "processHandle must be a string")) {
        .value => |value| value,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };

    const size = commandExecRequiredTerminalSize(object, "size") catch |err| switch (err) {
        error.InvalidCommandExecTerminalSizeObject => return renderJsonRpcError(allocator, id_value, -32602, "size must be an object"),
        error.InvalidCommandExecTerminalSize => return renderJsonRpcError(allocator, id_value, -32602, "process size rows and cols must be greater than 0"),
    };
    if (findActiveCommandExecSession(state, .process, process_handle)) |session| {
        return resizeActiveCommandExecPty(allocator, id_value, session, size);
    }
    return renderNoActiveProcess(allocator, id_value, process_handle);
}

const CommandExecObjectParams = union(enum) {
    object: std.json.ObjectMap,
    message: []const u8,
};

const CommandExecStringField = union(enum) {
    value: []const u8,
    message: []const u8,
};

fn commandExecObjectParams(params_value: ?std.json.Value, method: []const u8) CommandExecObjectParams {
    const params = params_value orelse return .{ .message = commandExecParamsMessage(method) };
    if (params != .object) return .{ .message = commandExecParamsMessage(method) };
    return .{ .object = params.object };
}

fn commandExecParamsMessage(method: []const u8) []const u8 {
    if (std.mem.eql(u8, method, "command/exec/write")) return "command/exec/write params must be an object";
    if (std.mem.eql(u8, method, "command/exec/terminate")) return "command/exec/terminate params must be an object";
    if (std.mem.eql(u8, method, "command/exec/resize")) return "command/exec/resize params must be an object";
    if (std.mem.eql(u8, method, "process/spawn")) return "process/spawn params must be an object";
    if (std.mem.eql(u8, method, "process/writeStdin")) return "process/writeStdin params must be an object";
    if (std.mem.eql(u8, method, "process/kill")) return "process/kill params must be an object";
    if (std.mem.eql(u8, method, "process/resizePty")) return "process/resizePty params must be an object";
    return "command/exec params must be an object";
}

fn commandExecRequiredStringField(object: std.json.ObjectMap, field: []const u8, message: []const u8) CommandExecStringField {
    const value = object.get(field) orelse return .{ .message = message };
    if (value != .string) return .{ .message = message };
    return .{ .value = value.string };
}

fn commandExecRequiredPositiveU16(object: std.json.ObjectMap, field: []const u8) !u16 {
    const value = object.get(field) orelse return error.InvalidCommandExecTerminalSize;
    const integer = switch (value) {
        .integer => |raw| raw,
        .number_string => |raw| std.fmt.parseInt(i64, raw, 10) catch return error.InvalidCommandExecTerminalSize,
        else => return error.InvalidCommandExecTerminalSize,
    };
    if (integer <= 0) return error.InvalidCommandExecTerminalSize;
    return std.math.cast(u16, integer) orelse error.InvalidCommandExecTerminalSize;
}

fn commandExecOptionalTerminalSize(object: std.json.ObjectMap, field: []const u8, tty: bool) !?CommandExecTerminalSize {
    const value = object.get(field) orelse return null;
    if (value == .null) return null;
    if (!tty) return error.CommandExecSizeRequiresTty;
    return try commandExecTerminalSizeFromValue(value);
}

fn commandExecRequiredTerminalSize(object: std.json.ObjectMap, field: []const u8) !CommandExecTerminalSize {
    const value = object.get(field) orelse return error.InvalidCommandExecTerminalSizeObject;
    return commandExecTerminalSizeFromValue(value);
}

fn commandExecTerminalSizeFromValue(value: std.json.Value) !CommandExecTerminalSize {
    if (value != .object) return error.InvalidCommandExecTerminalSizeObject;
    return .{
        .rows = try commandExecRequiredPositiveU16(value.object, "rows"),
        .cols = try commandExecRequiredPositiveU16(value.object, "cols"),
    };
}

fn renderNoActiveCommandExec(allocator: std.mem.Allocator, id_value: std.json.Value, process_id: []const u8) ![]const u8 {
    const process_id_json = try std.json.Stringify.valueAlloc(allocator, process_id, .{});
    defer allocator.free(process_id_json);
    const message = try std.fmt.allocPrint(allocator, "no active command/exec for process id {s}", .{process_id_json});
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32600, message);
}

fn renderNoActiveProcess(allocator: std.mem.Allocator, id_value: std.json.Value, process_handle: []const u8) ![]const u8 {
    const process_handle_json = try std.json.Stringify.valueAlloc(allocator, process_handle, .{});
    defer allocator.free(process_handle_json);
    const message = try std.fmt.allocPrint(allocator, "no active process for process handle {s}", .{process_handle_json});
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32600, message);
}

fn renderNoActiveSession(allocator: std.mem.Allocator, id_value: std.json.Value, kind: ActiveCommandExecKind, process_id: []const u8) ![]const u8 {
    return switch (kind) {
        .command_exec => renderNoActiveCommandExec(allocator, id_value, process_id),
        .process => renderNoActiveProcess(allocator, id_value, process_id),
    };
}

fn queueCommandExecOutputDeltas(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    process_id: []const u8,
    stdout: []const u8,
    stderr: []const u8,
    stdout_observed_len: usize,
    stderr_observed_len: usize,
    output_bytes_cap: ?usize,
) !void {
    if (stdout_observed_len > 0) {
        try queueCommandExecOutputDelta(allocator, state, process_id, "stdout", stdout, stdout_observed_len, output_bytes_cap);
    }
    if (stderr_observed_len > 0) {
        try queueCommandExecOutputDelta(allocator, state, process_id, "stderr", stderr, stderr_observed_len, output_bytes_cap);
    }
}

fn queueCommandExecOutputDelta(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    process_id: []const u8,
    stream: []const u8,
    bytes: []const u8,
    observed_len: usize,
    output_bytes_cap: ?usize,
) !void {
    const capped = commandExecCappedOutput(bytes, output_bytes_cap);
    const cap_reached = commandExecOutputCapReached(observed_len, output_bytes_cap);

    const encoded_len = std.base64.standard.Encoder.calcSize(capped.len);
    const encoded = try allocator.alloc(u8, encoded_len);
    defer allocator.free(encoded);
    _ = std.base64.standard.Encoder.encode(encoded, capped);

    const process_id_json = try std.json.Stringify.valueAlloc(allocator, process_id, .{});
    defer allocator.free(process_id_json);
    const stream_json = try std.json.Stringify.valueAlloc(allocator, stream, .{});
    defer allocator.free(stream_json);
    const delta_json = try std.json.Stringify.valueAlloc(allocator, encoded, .{});
    defer allocator.free(delta_json);

    const notification = try std.fmt.allocPrint(
        allocator,
        "{{\"jsonrpc\":\"2.0\",\"method\":\"command/exec/outputDelta\",\"params\":{{\"processId\":{s},\"stream\":{s},\"deltaBase64\":{s},\"capReached\":{s}}}}}",
        .{ process_id_json, stream_json, delta_json, if (cap_reached) "true" else "false" },
    );
    errdefer allocator.free(notification);
    try state.pre_response_notifications.append(allocator, notification);
}

fn queueProcessOutputDeltas(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    process_handle: []const u8,
    stdout: []const u8,
    stderr: []const u8,
    stdout_observed_len: usize,
    stderr_observed_len: usize,
    output_bytes_cap: ?usize,
) !void {
    if (stdout_observed_len > 0) {
        try queueProcessOutputDelta(allocator, state, process_handle, "stdout", stdout, stdout_observed_len, output_bytes_cap);
    }
    if (stderr_observed_len > 0) {
        try queueProcessOutputDelta(allocator, state, process_handle, "stderr", stderr, stderr_observed_len, output_bytes_cap);
    }
}

fn queueProcessOutputDelta(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    process_handle: []const u8,
    stream: []const u8,
    bytes: []const u8,
    observed_len: usize,
    output_bytes_cap: ?usize,
) !void {
    const capped = commandExecCappedOutput(bytes, output_bytes_cap);
    const cap_reached = commandExecOutputCapReached(observed_len, output_bytes_cap);

    const notification = try renderProcessOutputDeltaNotification(allocator, process_handle, stream, capped, cap_reached);
    try queuePendingServerNotification(allocator, state, "process/outputDelta", notification);
}

fn renderProcessOutputDeltaNotification(
    allocator: std.mem.Allocator,
    process_handle: []const u8,
    stream: []const u8,
    bytes: []const u8,
    cap_reached: bool,
) ![]const u8 {
    const encoded_len = std.base64.standard.Encoder.calcSize(bytes.len);
    const encoded = try allocator.alloc(u8, encoded_len);
    defer allocator.free(encoded);
    _ = std.base64.standard.Encoder.encode(encoded, bytes);

    const process_handle_json = try std.json.Stringify.valueAlloc(allocator, process_handle, .{});
    defer allocator.free(process_handle_json);
    const stream_json = try std.json.Stringify.valueAlloc(allocator, stream, .{});
    defer allocator.free(stream_json);
    const delta_json = try std.json.Stringify.valueAlloc(allocator, encoded, .{});
    defer allocator.free(delta_json);

    return std.fmt.allocPrint(
        allocator,
        "{{\"jsonrpc\":\"2.0\",\"method\":\"process/outputDelta\",\"params\":{{\"processHandle\":{s},\"stream\":{s},\"deltaBase64\":{s},\"capReached\":{s}}}}}",
        .{ process_handle_json, stream_json, delta_json, if (cap_reached) "true" else "false" },
    );
}

fn queueProcessExitedNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    process_handle: []const u8,
    exit_code: i32,
    stdout: []const u8,
    stderr: []const u8,
    stdout_cap_reached: bool,
    stderr_cap_reached: bool,
) !void {
    const notification = try renderProcessExitedNotification(allocator, process_handle, exit_code, stdout, stderr, stdout_cap_reached, stderr_cap_reached);
    try queuePendingServerNotification(allocator, state, "process/exited", notification);
}

fn renderProcessExitedNotification(
    allocator: std.mem.Allocator,
    process_handle: []const u8,
    exit_code: i32,
    stdout: []const u8,
    stderr: []const u8,
    stdout_cap_reached: bool,
    stderr_cap_reached: bool,
) ![]const u8 {
    const process_handle_json = try std.json.Stringify.valueAlloc(allocator, process_handle, .{});
    defer allocator.free(process_handle_json);
    const stdout_json = try std.json.Stringify.valueAlloc(allocator, stdout, .{});
    defer allocator.free(stdout_json);
    const stderr_json = try std.json.Stringify.valueAlloc(allocator, stderr, .{});
    defer allocator.free(stderr_json);

    return std.fmt.allocPrint(
        allocator,
        "{{\"jsonrpc\":\"2.0\",\"method\":\"process/exited\",\"params\":{{\"processHandle\":{s},\"exitCode\":{d},\"stdout\":{s},\"stdoutCapReached\":{s},\"stderr\":{s},\"stderrCapReached\":{s}}}}}",
        .{
            process_handle_json,
            exit_code,
            stdout_json,
            if (stdout_cap_reached) "true" else "false",
            stderr_json,
            if (stderr_cap_reached) "true" else "false",
        },
    );
}

fn commandExecCappedOutput(bytes: []const u8, output_bytes_cap: ?usize) []const u8 {
    const cap = output_bytes_cap orelse return bytes;
    return bytes[0..@min(bytes.len, cap)];
}

fn commandExecOutputCapReached(observed_len: usize, output_bytes_cap: ?usize) bool {
    const cap = output_bytes_cap orelse return false;
    return observed_len >= cap;
}

fn commandExecExitCode(term: std.process.Child.Term) i32 {
    return switch (term) {
        .exited => |code| @intCast(code),
        .signal => |sig| 128 + @as(i32, @intCast(@intFromEnum(sig))),
        .stopped => |sig| 128 + @as(i32, @intCast(@intFromEnum(sig))),
        .unknown => |code| @intCast(code),
    };
}

fn isFeedbackMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "feedback/upload");
}

fn handleFeedbackMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "feedback/upload")) {
        return handleFeedbackUpload(allocator, state, id_value, params_value);
    }
    return renderJsonRpcError(allocator, id_value, -32601, "unknown feedback method");
}

fn handleFeedbackUpload(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "feedback/upload params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "feedback/upload params must be an object");
    const object = params.object;

    const classification = object.get("classification") orelse return renderJsonRpcError(allocator, id_value, -32602, "classification must be a string");
    if (classification != .string) return renderJsonRpcError(allocator, id_value, -32602, "classification must be a string");

    const include_logs = object.get("includeLogs") orelse return renderJsonRpcError(allocator, id_value, -32602, "includeLogs must be a boolean");
    if (include_logs != .bool) return renderJsonRpcError(allocator, id_value, -32602, "includeLogs must be a boolean");

    var reason: ?[]const u8 = null;
    if (object.get("reason")) |reason_value| {
        if (reason_value != .null and reason_value != .string) {
            return renderJsonRpcError(allocator, id_value, -32602, "reason must be a string or null");
        }
        if (reason_value == .string) reason = reason_value.string;
    }

    var owned_thread_id: ?[]const u8 = null;
    defer if (owned_thread_id) |owned| allocator.free(owned);
    var thread_id: ?[]const u8 = null;
    if (object.get("threadId")) |thread_id_value| {
        if (thread_id_value != .null) {
            if (thread_id_value != .string) return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string or null");
            if (!isUuidString(thread_id_value.string)) return renderInvalidThreadId(allocator, id_value, thread_id_value.string);
            thread_id = thread_id_value.string;
        }
    }

    var extra_log_files = std.ArrayList([]const u8).empty;
    defer extra_log_files.deinit(allocator);
    if (object.get("extraLogFiles")) |extra_log_files_value| {
        if (extra_log_files_value != .null) {
            if (extra_log_files_value != .array) {
                return renderJsonRpcError(allocator, id_value, -32602, "extraLogFiles must be an array of strings or null");
            }
            for (extra_log_files_value.array.items) |file| {
                if (file != .string) {
                    return renderJsonRpcError(allocator, id_value, -32602, "extraLogFiles must be an array of strings or null");
                }
                try extra_log_files.append(allocator, file.string);
            }
        }
    }
    var tags_object: ?std.json.ObjectMap = null;
    if (object.get("tags")) |tags_value| {
        if (tags_value != .null) {
            if (tags_value != .object) {
                return renderJsonRpcError(allocator, id_value, -32602, "tags must be an object with string values or null");
            }
            var iter = tags_value.object.iterator();
            while (iter.next()) |entry| {
                if (entry.value_ptr.* != .string) {
                    return renderJsonRpcError(allocator, id_value, -32602, "tags must be an object with string values or null");
                }
            }
            tags_object = tags_value.object;
        }
    }

    const feedback_enabled = config.loadFeedbackEnabled(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "feedback/upload failed to load config", err);
    };
    if (!feedback_enabled) {
        return renderJsonRpcError(allocator, id_value, -32600, "sending feedback is disabled by configuration");
    }

    var metadata_tags = std.ArrayList(feedback_upload.Tag).empty;
    defer metadata_tags.deinit(allocator);
    var feedback_credentials: ?auth_mod.Credentials = null;
    defer if (feedback_credentials) |*credentials| credentials.deinit(allocator);
    if (loadAppServerConfigWithOptions(allocator, state, .{})) |cfg| {
        var loaded_cfg = cfg;
        defer loaded_cfg.deinit(allocator);
        feedback_credentials = auth_mod.loadCliAuthNoRefreshForConfig(allocator, &loaded_cfg) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => null,
        };
        if (feedback_credentials) |credentials| {
            if (credentials.account_id) |account_id| {
                try metadata_tags.append(allocator, .{ .key = "account_id", .value = account_id });
            }
            if (credentials.chatgpt_user_id) |chatgpt_user_id| {
                try metadata_tags.append(allocator, .{ .key = "chatgpt_user_id", .value = chatgpt_user_id });
            }
        }
    } else |err| switch (err) {
        error.OutOfMemory => return err,
        else => {},
    }

    if (thread_id == null) {
        const uuid = try generateUuidString(allocator);
        defer allocator.free(uuid);
        owned_thread_id = try std.fmt.allocPrint(allocator, "no-active-thread-{s}", .{uuid});
        thread_id = owned_thread_id.?;
    }

    var feedback_thread_ids = std.ArrayList([]const u8).empty;
    defer feedback_thread_ids.deinit(allocator);
    var owned_feedback_thread_ids = std.ArrayList([]const u8).empty;
    defer {
        for (owned_feedback_thread_ids.items) |owned| allocator.free(owned);
        owned_feedback_thread_ids.deinit(allocator);
    }
    var feedback_cfg: ?config.Config = null;
    defer if (feedback_cfg) |*cfg| cfg.deinit(allocator);
    if (include_logs.bool) {
        try appendFeedbackThreadIds(allocator, state, thread_id.?, &feedback_thread_ids);

        feedback_cfg = loadAppServerConfig(allocator, state) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => null,
        };
        if (feedback_cfg) |cfg| {
            if (!std.mem.startsWith(u8, thread_id.?, "no-active-thread-")) {
                feedback_state.appendSpawnDescendantThreadIds(
                    allocator,
                    configSqliteHome(cfg),
                    thread_id.?,
                    &feedback_thread_ids,
                    &owned_feedback_thread_ids,
                ) catch |err| switch (err) {
                    error.OutOfMemory => return err,
                    else => {},
                };
            }
        }
    }

    var sqlite_log_bytes: ?[]const u8 = null;
    defer if (sqlite_log_bytes) |bytes| allocator.free(bytes);
    if (include_logs.bool and feedback_thread_ids.items.len > 0) {
        if (feedback_cfg) |cfg| {
            sqlite_log_bytes = feedback_logs.queryFeedbackLogsForThreads(allocator, configSqliteHome(cfg), feedback_thread_ids.items) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => null,
            };
            if (sqlite_log_bytes) |bytes| {
                if (bytes.len == 0) {
                    allocator.free(bytes);
                    sqlite_log_bytes = null;
                }
            }
        }
    }

    var upload_log_files = std.ArrayList([]const u8).empty;
    defer upload_log_files.deinit(allocator);
    var owned_upload_log_files = std.ArrayList([]const u8).empty;
    defer {
        for (owned_upload_log_files.items) |path| allocator.free(path);
        owned_upload_log_files.deinit(allocator);
    }
    if (include_logs.bool) {
        try appendFeedbackThreadRolloutPaths(
            allocator,
            state,
            thread_id.?,
            feedback_thread_ids.items,
            if (feedback_cfg) |cfg| cfg.codex_home else null,
            if (feedback_cfg) |cfg| configSqliteHome(cfg) else null,
            &upload_log_files,
            &owned_upload_log_files,
        );
    }
    for (extra_log_files.items) |path| try upload_log_files.append(allocator, path);

    feedback_upload.upload(allocator, .{
        .classification = classification.string,
        .reason = reason,
        .thread_id = thread_id.?,
        .include_logs = include_logs.bool,
        .log_bytes = sqlite_log_bytes orelse "",
        .extra_log_files = upload_log_files.items,
        .tags = if (tags_object) |*tags| tags else null,
        .metadata_tags = metadata_tags.items,
        .session_source = appServerSessionSourceFeedbackTag(state.session_source),
    }) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "failed to upload feedback", err);
    };

    return renderFeedbackUploadResponse(allocator, id_value, thread_id.?);
}

fn appendFeedbackThreadIds(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    thread_id: []const u8,
    thread_ids: *std.ArrayList([]const u8),
) !void {
    if (std.mem.startsWith(u8, thread_id, "no-active-thread-")) return;

    try thread_ids.append(allocator, thread_id);
    for (state.loaded_threads.items) |*thread| {
        if (std.mem.eql(u8, thread.id, thread_id)) continue;
        if (!loadedThreadInFeedbackSubtree(state, thread, thread_id)) continue;
        if (containsString(thread_ids.items, thread.id)) continue;
        try thread_ids.append(allocator, thread.id);
    }
}

fn containsString(values: []const []const u8, needle: []const u8) bool {
    for (values) |value| {
        if (std.mem.eql(u8, value, needle)) return true;
    }
    return false;
}

fn appendFeedbackThreadRolloutPaths(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    root_thread_id: []const u8,
    thread_ids: []const []const u8,
    codex_home: ?[]const u8,
    sqlite_home: ?[]const u8,
    upload_log_files: *std.ArrayList([]const u8),
    owned_upload_log_files: *std.ArrayList([]const u8),
) !void {
    if (std.mem.startsWith(u8, root_thread_id, "no-active-thread-")) return;

    for (thread_ids) |thread_id| {
        if (findLoadedThread(state, thread_id)) |thread| {
            if (thread.path) |path| {
                try upload_log_files.append(allocator, path);
                continue;
            }
        }

        if (codex_home) |home| {
            const path = feedback_state.findRolloutPathByThreadId(allocator, sqlite_home orelse home, thread_id) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => null,
            };
            if (path) |owned_path| {
                owned_upload_log_files.append(allocator, owned_path) catch |err| {
                    allocator.free(owned_path);
                    return err;
                };
                try upload_log_files.append(allocator, owned_path);
                continue;
            }
        }

        if (std.mem.eql(u8, thread_id, root_thread_id)) {
            _ = try appendSavedRootRolloutPath(allocator, root_thread_id, codex_home, upload_log_files, owned_upload_log_files);
        }
    }
}

fn appendSavedRootRolloutPath(
    allocator: std.mem.Allocator,
    thread_id: []const u8,
    codex_home: ?[]const u8,
    upload_log_files: *std.ArrayList([]const u8),
    owned_upload_log_files: *std.ArrayList([]const u8),
) !bool {
    if (codex_home) |home| {
        const path = session_store.resolveResumePath(allocator, home, thread_id) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return false,
        };
        owned_upload_log_files.append(allocator, path) catch |err| {
            allocator.free(path);
            return err;
        };
        try upload_log_files.append(allocator, path);
        return true;
    }

    const home = resolveCodexHome(allocator) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return false,
    };
    defer allocator.free(home);

    const path = session_store.resolveResumePath(allocator, home, thread_id) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return false,
    };
    owned_upload_log_files.append(allocator, path) catch |err| {
        allocator.free(path);
        return err;
    };
    try upload_log_files.append(allocator, path);
    return true;
}

fn loadedThreadInFeedbackSubtree(state: *const AppServerState, thread: *const LoadedThread, root_thread_id: []const u8) bool {
    if (std.mem.eql(u8, thread.id, root_thread_id)) return true;

    var current_parent = thread.forked_from_id orelse return false;
    var depth: usize = 0;
    while (depth < state.loaded_threads.items.len) : (depth += 1) {
        if (std.mem.eql(u8, current_parent, root_thread_id)) return true;
        const parent = findLoadedThread(state, current_parent) orelse return false;
        current_parent = parent.forked_from_id orelse return false;
    }
    return false;
}

fn renderFeedbackUploadResponse(allocator: std.mem.Allocator, id_value: std.json.Value, thread_id: []const u8) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"threadId\":");
    try appendJsonString(allocator, &result, thread_id);
    try result.appendSlice(allocator, "}");
    const result_json = try result.toOwnedSlice(allocator);
    defer allocator.free(result_json);
    return renderJsonRpcResult(allocator, id_value, result_json);
}

fn isWindowsSandboxMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "windowsSandbox/readiness") or
        std.mem.eql(u8, method, "windowsSandbox/setupStart");
}

fn handleWindowsSandboxMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "windowsSandbox/readiness")) {
        return handleWindowsSandboxReadiness(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "windowsSandbox/setupStart")) {
        return handleWindowsSandboxSetupStart(allocator, state, id_value, params_value);
    }
    return renderJsonRpcError(allocator, id_value, -32601, "unknown windows sandbox method");
}

fn handleWindowsSandboxReadiness(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (params_value) |params| {
        if (params != .null) {
            return renderJsonRpcError(allocator, id_value, -32602, "windowsSandbox/readiness params must be null or omitted");
        }
    }
    return renderJsonRpcResult(allocator, id_value, "{\"status\":\"notConfigured\"}");
}

fn handleWindowsSandboxSetupStart(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "windowsSandbox/setupStart params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "windowsSandbox/setupStart params must be an object");

    const mode_value = params.object.get("mode") orelse return renderJsonRpcError(allocator, id_value, -32600, "Invalid Request");
    if (mode_value != .string) return renderJsonRpcError(allocator, id_value, -32600, "Invalid Request");
    const mode = mode_value.string;
    if (!std.mem.eql(u8, mode, "elevated") and !std.mem.eql(u8, mode, "unelevated")) {
        return renderJsonRpcError(allocator, id_value, -32600, "Invalid Request");
    }

    if (params.object.get("cwd")) |cwd_value| {
        if (cwd_value != .null) {
            if (cwd_value != .string) return renderJsonRpcError(allocator, id_value, -32600, FS_ABSOLUTE_PATH_MESSAGE);
            if (!std.fs.path.isAbsolute(cwd_value.string)) return renderJsonRpcError(allocator, id_value, -32600, FS_ABSOLUTE_PATH_MESSAGE);
        }
    }

    const error_message = windowsSandboxSetupError(mode);
    try queueWindowsSandboxSetupCompletedNotification(allocator, state, mode, error_message == null, error_message);
    return renderJsonRpcResult(allocator, id_value, "{\"started\":true}");
}

fn windowsSandboxSetupError(mode: []const u8) ?[]const u8 {
    if (builtin.os.tag == .windows) return "Windows sandbox setup is parsed but not implemented yet";
    if (std.mem.eql(u8, mode, "elevated")) return "elevated Windows sandbox setup is only supported on Windows";
    return "legacy Windows sandbox setup is only supported on Windows";
}

fn queueWindowsSandboxSetupCompletedNotification(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    mode: []const u8,
    success: bool,
    error_message: ?[]const u8,
) !void {
    const mode_json = try std.json.Stringify.valueAlloc(allocator, mode, .{});
    defer allocator.free(mode_json);

    const error_json = if (error_message) |message|
        try std.json.Stringify.valueAlloc(allocator, message, .{})
    else
        try allocator.dupe(u8, "null");
    defer allocator.free(error_json);

    const notification = try std.fmt.allocPrint(
        allocator,
        "{{\"jsonrpc\":\"2.0\",\"method\":\"windowsSandbox/setupCompleted\",\"params\":{{\"mode\":{s},\"success\":{s},\"error\":{s}}}}}",
        .{ mode_json, if (success) "true" else "false", error_json },
    );
    errdefer allocator.free(notification);
    try state.pending_notifications.append(allocator, notification);
}

fn processOptionalOutputBytesCap(object: std.json.ObjectMap, field: []const u8, default: usize) !?usize {
    const value = object.get(field) orelse return default;
    if (value == .null) return null;
    const parsed = try commandExecNonNegativeUsize(value);
    return parsed;
}

fn processOptionalTimeoutMs(object: std.json.ObjectMap, field: []const u8, default: i64) CommandExecTimeoutMsParse {
    const value = object.get(field) orelse return .{ .value = default };
    if (value == .null) return .{ .value = null };
    return parseCommandExecTimeoutMsValue(value);
}

fn commandExecOptionalBool(object: std.json.ObjectMap, field: []const u8, default: bool) !bool {
    const value = object.get(field) orelse return default;
    if (value == .null) return default;
    if (value != .bool) return error.InvalidCommandExecBool;
    return value.bool;
}

fn commandExecOptionalString(object: std.json.ObjectMap, field: []const u8) !?[]const u8 {
    const value = object.get(field) orelse return null;
    if (value == .null) return null;
    if (value != .string) return error.InvalidCommandExecString;
    return value.string;
}

fn commandExecOptionalUsize(object: std.json.ObjectMap, field: []const u8, message: []const u8) !?usize {
    if (try commandExecOptionalU64(object, field, message)) |value| {
        return std.math.cast(usize, value) orelse error.InvalidCommandExecNumber;
    }
    return null;
}

fn commandExecOptionalU64(object: std.json.ObjectMap, field: []const u8, message: []const u8) !?u64 {
    _ = message;
    const value = object.get(field) orelse return null;
    if (value == .null) return null;
    const parsed = try commandExecNonNegativeU64(value);
    return parsed;
}

const CommandExecTimeoutMsParse = union(enum) {
    value: ?i64,
    negative: i64,
    invalid,
};

fn commandExecOptionalTimeoutMs(object: std.json.ObjectMap, field: []const u8) CommandExecTimeoutMsParse {
    const value = object.get(field) orelse return .{ .value = null };
    if (value == .null) return .{ .value = null };
    return parseCommandExecTimeoutMsValue(value);
}

fn parseCommandExecTimeoutMsValue(value: std.json.Value) CommandExecTimeoutMsParse {
    const integer = switch (value) {
        .integer => |raw| raw,
        .number_string => |raw| std.fmt.parseInt(i64, raw, 10) catch return .invalid,
        else => return .invalid,
    };
    if (integer < 0) return .{ .negative = integer };
    return .{ .value = integer };
}

fn commandExecNonNegativeUsize(value: std.json.Value) !usize {
    const integer = try commandExecNonNegativeU64(value);
    return std.math.cast(usize, integer) orelse error.InvalidCommandExecNumber;
}

fn commandExecNonNegativeU64(value: std.json.Value) !u64 {
    return switch (value) {
        .integer => |integer| blk: {
            if (integer < 0) return error.InvalidCommandExecNumber;
            break :blk @intCast(integer);
        },
        .number_string => |number| std.fmt.parseUnsigned(u64, number, 10) catch return error.InvalidCommandExecNumber,
        else => error.InvalidCommandExecNumber,
    };
}

fn commandExecBoolError(allocator: std.mem.Allocator, id_value: std.json.Value, err: anyerror, message: []const u8) ![]const u8 {
    return switch (err) {
        error.InvalidCommandExecBool => renderJsonRpcError(allocator, id_value, -32602, message),
        else => err,
    };
}

fn commandExecNumberError(allocator: std.mem.Allocator, id_value: std.json.Value, err: anyerror, message: []const u8) ![]const u8 {
    return switch (err) {
        error.InvalidCommandExecNumber => renderJsonRpcError(allocator, id_value, -32602, message),
        else => err,
    };
}

const CommandExecProjectRootsPath = union(enum) {
    not_project_roots,
    root,
    subpath: []const u8,
};

fn parseCommandExecPermissionProfile(
    allocator: std.mem.Allocator,
    value: std.json.Value,
    default_mode: config.SandboxMode,
    cwd: ?[]const u8,
) !CommandExecSandbox {
    if (value == .null) return .{ .mode = default_mode, .writable_roots = try allocator.alloc([]const u8, 0) };
    if (value != .object) return error.InvalidCommandExecPermissionProfile;

    const type_value = value.object.get("type") orelse return error.InvalidCommandExecPermissionProfileType;
    if (type_value != .string) return error.InvalidCommandExecPermissionProfileType;

    if (std.mem.eql(u8, type_value.string, "disabled")) {
        return .{ .mode = .danger_full_access, .writable_roots = try allocator.alloc([]const u8, 0) };
    }
    if (std.mem.eql(u8, type_value.string, "external")) {
        const network_enabled = try parseCommandExecPermissionNetwork(value.object.get("network"));
        return .{ .mode = .danger_full_access, .writable_roots = try allocator.alloc([]const u8, 0), .network_enabled = network_enabled };
    }
    if (!std.mem.eql(u8, type_value.string, "managed")) {
        return error.InvalidCommandExecPermissionProfileType;
    }

    const network_enabled = try parseCommandExecPermissionNetwork(value.object.get("network"));
    const file_system_value = value.object.get("fileSystem") orelse return error.InvalidCommandExecPermissionProfileFileSystem;
    if (file_system_value != .object) return error.InvalidCommandExecPermissionProfileFileSystem;
    const file_system_type = file_system_value.object.get("type") orelse return error.InvalidCommandExecPermissionProfileFileSystemType;
    if (file_system_type != .string) return error.InvalidCommandExecPermissionProfileFileSystemType;

    if (std.mem.eql(u8, file_system_type.string, "unrestricted")) {
        _ = try parseCommandExecPermissionProfileGlobScanMaxDepth(file_system_value.object);
        return try commandExecFullFilesystemSandbox(allocator, network_enabled);
    }
    if (!std.mem.eql(u8, file_system_type.string, "restricted")) {
        return error.InvalidCommandExecPermissionProfileFileSystemType;
    }
    const glob_scan_max_depth = try parseCommandExecPermissionProfileGlobScanMaxDepth(file_system_value.object);

    const entries_value = file_system_value.object.get("entries") orelse return error.InvalidCommandExecPermissionProfileEntries;
    if (entries_value != .array) return error.InvalidCommandExecPermissionProfileEntries;

    var summary = CommandExecPermissionProfileSummary{};
    defer summary.deinit(allocator);
    for (entries_value.array.items) |entry| {
        try addCommandExecPermissionProfileEntry(allocator, &summary, entry, cwd);
    }

    if (summary.unsupported) return error.UnsupportedCommandExecPermissionProfile;
    if (summary.root_write) {
        if (!summary.root_read) return error.UnsupportedCommandExecPermissionProfile;
        if (summary.read_denied_roots.items.len > 0 or summary.read_denied_globs.items.len > 0) {
            const roots = try allocator.alloc([]const u8, 1);
            roots[0] = "/";
            return try commandExecSandboxFromPermissionSummary(allocator, &summary, .workspace_write, roots, false, network_enabled, glob_scan_max_depth);
        }
        return try commandExecFullFilesystemSandbox(allocator, network_enabled);
    }
    if (summary.project_roots_write or summary.tmpdir_write or summary.slash_tmp_write or summary.path_writable_roots.items.len > 0 or summary.writable_globs.items.len > 0) {
        if (!summary.root_read) return error.UnsupportedCommandExecPermissionProfile;
        const explicit_roots = try summary.path_writable_roots.toOwnedSlice(allocator);
        summary.path_writable_roots = .empty;
        defer allocator.free(explicit_roots);
        const roots = try buildCommandExecWorkspaceWriteRoots(
            allocator,
            explicit_roots,
            if (summary.tmpdir_write) commandExecCurrentAbsoluteEnv("TMPDIR") else null,
            if (summary.slash_tmp_write) "/tmp" else null,
        );
        return try commandExecSandboxFromPermissionSummary(allocator, &summary, .workspace_write, roots, summary.project_roots_write, network_enabled, glob_scan_max_depth);
    }
    if (summary.root_read) {
        return try commandExecSandboxFromPermissionSummary(allocator, &summary, .read_only, try allocator.alloc([]const u8, 0), true, network_enabled, glob_scan_max_depth);
    }
    if (summary.non_root_read and (summary.readable_roots.items.len > 0 or summary.readable_globs.items.len > 0 or summary.include_platform_defaults)) {
        return try commandExecSandboxFromPermissionSummary(allocator, &summary, .read_only, try allocator.alloc([]const u8, 0), true, network_enabled, glob_scan_max_depth);
    }
    return error.UnsupportedCommandExecPermissionProfile;
}

fn commandExecSandboxFromPermissionSummary(
    allocator: std.mem.Allocator,
    summary: *CommandExecPermissionProfileSummary,
    mode: config.SandboxMode,
    writable_roots: []const []const u8,
    include_cwd_write_root: bool,
    network_enabled: bool,
    glob_scan_max_depth: ?usize,
) !CommandExecSandbox {
    errdefer allocator.free(writable_roots);

    const read_denied_roots = try summary.read_denied_roots.toOwnedSlice(allocator);
    summary.read_denied_roots = .empty;
    errdefer allocator.free(read_denied_roots);
    const read_denied_globs = try summary.read_denied_globs.toOwnedSlice(allocator);
    summary.read_denied_globs = .empty;
    errdefer allocator.free(read_denied_globs);
    const readable_root_carveouts = if (summary.root_read) blk: {
        const roots = try summary.readable_roots.toOwnedSlice(allocator);
        summary.readable_roots = .empty;
        break :blk roots;
    } else try allocator.alloc([]const u8, 0);
    errdefer allocator.free(readable_root_carveouts);
    const readable_glob_carveouts = if (summary.root_read) blk: {
        const globs = try summary.readable_globs.toOwnedSlice(allocator);
        summary.readable_globs = .empty;
        break :blk globs;
    } else try allocator.alloc([]const u8, 0);
    errdefer allocator.free(readable_glob_carveouts);
    const readable_globs = if (summary.root_read)
        try allocator.alloc([]const u8, 0)
    else blk: {
        const globs = try summary.readable_globs.toOwnedSlice(allocator);
        summary.readable_globs = .empty;
        break :blk globs;
    };
    errdefer allocator.free(readable_globs);
    const writable_globs = try summary.writable_globs.toOwnedSlice(allocator);
    summary.writable_globs = .empty;
    errdefer allocator.free(writable_globs);
    const readable_roots = if (summary.root_read)
        try allocator.alloc([]const u8, 0)
    else blk: {
        const roots = try summary.readable_roots.toOwnedSlice(allocator);
        summary.readable_roots = .empty;
        break :blk roots;
    };
    errdefer allocator.free(readable_roots);

    const owned_paths = try summary.owned_paths.toOwnedSlice(allocator);
    summary.owned_paths = .empty;
    errdefer freeCommandExecOwnedPaths(allocator, owned_paths);

    return .{
        .mode = mode,
        .writable_roots = writable_roots,
        .readable_roots = readable_roots,
        .readable_globs = readable_globs,
        .readable_root_carveouts = readable_root_carveouts,
        .readable_glob_carveouts = readable_glob_carveouts,
        .writable_globs = writable_globs,
        .allow_glob_max_depth = glob_scan_max_depth,
        .read_denied_roots = read_denied_roots,
        .read_denied_globs = read_denied_globs,
        .owned_paths = owned_paths,
        .include_cwd_write_root = include_cwd_write_root,
        .include_platform_defaults = mode == .read_only and !summary.root_read and summary.include_platform_defaults,
        .network_enabled = network_enabled,
    };
}

fn freeCommandExecOwnedPaths(allocator: std.mem.Allocator, paths: []const []const u8) void {
    for (paths) |path| allocator.free(path);
    allocator.free(paths);
}

fn commandExecFullFilesystemSandbox(allocator: std.mem.Allocator, network_enabled: bool) !CommandExecSandbox {
    if (network_enabled) {
        return .{ .mode = .danger_full_access, .writable_roots = try allocator.alloc([]const u8, 0) };
    }

    const roots = try allocator.alloc([]const u8, 1);
    roots[0] = "/";
    return .{
        .mode = .workspace_write,
        .writable_roots = roots,
        .include_cwd_write_root = false,
        .network_enabled = false,
    };
}

fn parseCommandExecPermissionNetwork(value: ?std.json.Value) !bool {
    const network = value orelse return error.InvalidCommandExecPermissionProfileNetwork;
    if (network != .object) return error.InvalidCommandExecPermissionProfileNetwork;
    const enabled = network.object.get("enabled") orelse return error.InvalidCommandExecPermissionProfileNetwork;
    if (enabled != .bool) return error.InvalidCommandExecPermissionProfileNetwork;
    return enabled.bool;
}

fn parseCommandExecPermissionProfileGlobScanMaxDepth(object: std.json.ObjectMap) !?usize {
    const value = object.get("globScanMaxDepth") orelse return null;
    if (value == .null) return null;
    const depth = switch (value) {
        .integer => |integer| blk: {
            if (integer <= 0) return error.InvalidCommandExecPermissionProfileGlobScanMaxDepth;
            break :blk @as(u64, @intCast(integer));
        },
        .number_string => |raw| std.fmt.parseUnsigned(u64, raw, 10) catch return error.InvalidCommandExecPermissionProfileGlobScanMaxDepth,
        else => return error.InvalidCommandExecPermissionProfileGlobScanMaxDepth,
    };
    if (depth == 0) return error.InvalidCommandExecPermissionProfileGlobScanMaxDepth;
    if (depth > @as(u64, @intCast(sandbox_mod.max_allow_glob_scan_depth))) return error.InvalidCommandExecPermissionProfileGlobScanMaxDepth;
    if (depth > std.math.maxInt(usize)) return error.InvalidCommandExecPermissionProfileGlobScanMaxDepth;
    return @intCast(depth);
}

fn addCommandExecPermissionProfileEntry(
    allocator: std.mem.Allocator,
    summary: *CommandExecPermissionProfileSummary,
    value: std.json.Value,
    cwd: ?[]const u8,
) !void {
    if (value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const path = value.object.get("path") orelse return error.InvalidCommandExecPermissionProfileEntry;
    const access_value = value.object.get("access") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (access_value != .string) return error.InvalidCommandExecPermissionProfileEntry;

    if (std.mem.eql(u8, access_value.string, "none")) {
        try addCommandExecPermissionReadDenyRoot(allocator, summary, path, cwd);
        return;
    }
    if (std.mem.eql(u8, access_value.string, "read")) {
        if (try commandExecPermissionPathGlobPattern(allocator, path)) |pattern| {
            errdefer allocator.free(pattern);
            summary.non_root_read = true;
            try summary.owned_paths.append(allocator, pattern);
            errdefer _ = summary.owned_paths.pop();
            try summary.readable_globs.append(allocator, pattern);
            return;
        }
        if (commandExecPermissionPathIsRoot(path) catch |err| switch (err) {
            error.InvalidCommandExecPermissionProfileEntry => return err,
        }) {
            summary.root_read = true;
        } else {
            try addCommandExecPermissionReadRoot(allocator, summary, path, cwd);
        }
        return;
    }
    if (!std.mem.eql(u8, access_value.string, "write")) {
        return error.InvalidCommandExecPermissionProfileEntry;
    }

    if (try commandExecPermissionPathGlobPattern(allocator, path)) |pattern| {
        errdefer allocator.free(pattern);
        try summary.owned_paths.append(allocator, pattern);
        errdefer _ = summary.owned_paths.pop();
        try summary.writable_globs.append(allocator, pattern);
        return;
    }
    if (try commandExecPermissionPathIsRoot(path)) {
        summary.root_write = true;
        return;
    }
    switch (try commandExecPermissionProjectRootsPath(path)) {
        .not_project_roots => {},
        .root => {
            summary.project_roots_write = true;
            return;
        },
        .subpath => |subpath| {
            const owned = try commandExecResolveCwdSubpath(allocator, cwd, subpath, .{});
            errdefer allocator.free(owned);
            try summary.owned_paths.append(allocator, owned);
            errdefer _ = summary.owned_paths.pop();
            try summary.path_writable_roots.append(allocator, owned);
            return;
        },
    }
    if (try commandExecPermissionPathIsTmpdir(path)) {
        summary.tmpdir_write = true;
        return;
    }
    if (try commandExecPermissionPathIsSlashTmp(path)) {
        summary.slash_tmp_write = true;
        return;
    }
    if (try commandExecPermissionUnknownSpecialAbsolutePath(allocator, summary, path)) |absolute_path| {
        try summary.path_writable_roots.append(allocator, absolute_path);
        return;
    }
    if (try commandExecPermissionPathAbsolute(path)) |absolute_path| {
        try summary.path_writable_roots.append(allocator, absolute_path);
        return;
    }
    summary.unsupported = true;
}

fn addCommandExecPermissionReadDenyRoot(
    allocator: std.mem.Allocator,
    summary: *CommandExecPermissionProfileSummary,
    path: std.json.Value,
    cwd: ?[]const u8,
) !void {
    if (try commandExecPermissionPathGlobPattern(allocator, path)) |pattern| {
        errdefer allocator.free(pattern);
        try summary.owned_paths.append(allocator, pattern);
        errdefer _ = summary.owned_paths.pop();
        try summary.read_denied_globs.append(allocator, pattern);
        return;
    }
    if (try commandExecPermissionPathIsRoot(path)) {
        try summary.read_denied_roots.append(allocator, "/");
        return;
    }
    if (try commandExecPermissionPathIsMinimal(path)) return;
    switch (try commandExecPermissionProjectRootsPath(path)) {
        .not_project_roots => {},
        .root => {
            const owned = try commandExecResolveCwdSubpath(allocator, cwd, null, .{});
            errdefer allocator.free(owned);
            try summary.owned_paths.append(allocator, owned);
            errdefer _ = summary.owned_paths.pop();
            try summary.read_denied_roots.append(allocator, owned);
            return;
        },
        .subpath => |subpath| {
            const owned = try commandExecResolveCwdSubpath(allocator, cwd, subpath, .{ .allow_missing_leaf = true });
            errdefer allocator.free(owned);
            try summary.owned_paths.append(allocator, owned);
            errdefer _ = summary.owned_paths.pop();
            try summary.read_denied_roots.append(allocator, owned);
            return;
        },
    }
    if (try commandExecPermissionPathIsTmpdir(path)) {
        if (commandExecCurrentAbsoluteEnv("TMPDIR")) |tmpdir| {
            try summary.read_denied_roots.append(allocator, tmpdir);
            return;
        }
        summary.unsupported = true;
        return;
    }
    if (try commandExecPermissionPathIsSlashTmp(path)) {
        try summary.read_denied_roots.append(allocator, "/tmp");
        return;
    }
    if (try commandExecPermissionUnknownSpecialAbsolutePath(allocator, summary, path)) |absolute_path| {
        try summary.read_denied_roots.append(allocator, absolute_path);
        return;
    }
    if (try commandExecPermissionPathAbsolute(path)) |absolute_path| {
        try summary.read_denied_roots.append(allocator, absolute_path);
        return;
    }
    summary.unsupported = true;
}

fn addCommandExecPermissionReadRoot(
    allocator: std.mem.Allocator,
    summary: *CommandExecPermissionProfileSummary,
    path: std.json.Value,
    cwd: ?[]const u8,
) !void {
    summary.non_root_read = true;
    if (try commandExecPermissionPathIsMinimal(path)) {
        summary.include_platform_defaults = true;
        return;
    }
    switch (try commandExecPermissionProjectRootsPath(path)) {
        .not_project_roots => {},
        .root => {
            const owned = try commandExecResolveCwdSubpath(allocator, cwd, null, .{});
            errdefer allocator.free(owned);
            try summary.owned_paths.append(allocator, owned);
            errdefer _ = summary.owned_paths.pop();
            try summary.readable_roots.append(allocator, owned);
            return;
        },
        .subpath => |subpath| {
            const owned = try commandExecResolveCwdSubpath(allocator, cwd, subpath, .{ .allow_missing_leaf = true });
            errdefer allocator.free(owned);
            try summary.owned_paths.append(allocator, owned);
            errdefer _ = summary.owned_paths.pop();
            try summary.readable_roots.append(allocator, owned);
            return;
        },
    }
    if (try commandExecPermissionPathIsTmpdir(path)) {
        if (commandExecCurrentAbsoluteEnv("TMPDIR")) |tmpdir| {
            try summary.readable_roots.append(allocator, tmpdir);
            return;
        }
        summary.unsupported = true;
        return;
    }
    if (try commandExecPermissionPathIsSlashTmp(path)) {
        try summary.readable_roots.append(allocator, "/tmp");
        return;
    }
    if (try commandExecPermissionUnknownSpecialAbsolutePath(allocator, summary, path)) |absolute_path| {
        try summary.readable_roots.append(allocator, absolute_path);
        return;
    }
    if (try commandExecPermissionPathAbsolute(path)) |absolute_path| {
        try summary.readable_roots.append(allocator, absolute_path);
        return;
    }
    summary.unsupported = true;
}

fn commandExecPermissionUnknownSpecialAbsolutePath(
    allocator: std.mem.Allocator,
    summary: *CommandExecPermissionProfileSummary,
    value: std.json.Value,
) !?[]const u8 {
    if (value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const type_value = value.object.get("type") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (type_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    if (!std.mem.eql(u8, type_value.string, "special")) return null;
    const special_value = value.object.get("value") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (special_value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const kind_value = special_value.object.get("kind") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (kind_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    if (!std.mem.eql(u8, kind_value.string, "unknown")) return null;

    const path_value = special_value.object.get("path") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (path_value != .string or !std.fs.path.isAbsolute(path_value.string)) return error.InvalidCommandExecPermissionProfileEntry;

    const subpath_value = special_value.object.get("subpath") orelse return path_value.string;
    if (subpath_value == .null) return path_value.string;
    if (subpath_value != .string or std.fs.path.isAbsolute(subpath_value.string)) return error.InvalidCommandExecPermissionProfileEntry;

    const base = try commandExecCanonicalMissingPath(allocator, path_value.string);
    defer allocator.free(base);
    const resolved = try std.fs.path.resolve(allocator, &.{ base, subpath_value.string });
    defer allocator.free(resolved);
    if (!commandExecPathIsWithinBase(base, resolved)) return error.InvalidCommandExecPermissionProfileEntry;

    const canonical = try commandExecCanonicalMissingPath(allocator, resolved);
    errdefer allocator.free(canonical);
    if (!commandExecPathIsWithinBase(base, canonical)) return error.InvalidCommandExecPermissionProfileEntry;
    try summary.owned_paths.append(allocator, canonical);
    return canonical;
}

fn commandExecPermissionPathGlobPattern(
    allocator: std.mem.Allocator,
    value: std.json.Value,
) !?[]const u8 {
    if (value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const type_value = value.object.get("type") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (type_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    if (!std.mem.eql(u8, type_value.string, "glob_pattern")) return null;

    const pattern_value = value.object.get("pattern") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (pattern_value != .string or pattern_value.string.len == 0) return error.InvalidCommandExecPermissionProfileEntry;
    if (std.fs.path.isAbsolute(pattern_value.string)) return try allocator.dupe(u8, pattern_value.string);
    if (!commandExecSafeRelativeGlobPattern(pattern_value.string)) return error.InvalidCommandExecPermissionProfileEntry;

    return try allocator.dupe(u8, pattern_value.string);
}

fn commandExecSafeRelativeGlobPattern(pattern: []const u8) bool {
    if (pattern.len == 0 or std.fs.path.isAbsolute(pattern)) return false;
    var iter = std.mem.splitScalar(u8, pattern, '/');
    while (iter.next()) |part| {
        if (part.len == 0 or std.mem.eql(u8, part, ".") or std.mem.eql(u8, part, "..")) return false;
    }
    return true;
}

fn commandExecPermissionPathIsRoot(value: std.json.Value) !bool {
    const special = try commandExecPermissionSpecialPathKind(value);
    return if (special) |kind| std.mem.eql(u8, kind, "root") else false;
}

fn commandExecPermissionPathIsMinimal(value: std.json.Value) !bool {
    const special = try commandExecPermissionSpecialPathKind(value);
    return if (special) |kind| std.mem.eql(u8, kind, "minimal") else false;
}

fn commandExecPermissionProjectRootsPath(value: std.json.Value) !CommandExecProjectRootsPath {
    if (value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const type_value = value.object.get("type") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (type_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    if (!std.mem.eql(u8, type_value.string, "special")) return .not_project_roots;
    const special_value = value.object.get("value") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (special_value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const kind_value = special_value.object.get("kind") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (kind_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    if (!std.mem.eql(u8, kind_value.string, "project_roots") and !std.mem.eql(u8, kind_value.string, "current_working_directory")) return .not_project_roots;
    if (special_value.object.get("subpath")) |subpath| {
        if (subpath == .null) return .root;
        if (subpath != .string) return error.InvalidCommandExecPermissionProfileEntry;
        return .{ .subpath = subpath.string };
    }
    return .root;
}

const CommandExecResolveCwdSubpathOptions = struct {
    allow_missing_leaf: bool = false,
};

fn commandExecResolveCwdSubpath(
    allocator: std.mem.Allocator,
    cwd: ?[]const u8,
    subpath: ?[]const u8,
    options: CommandExecResolveCwdSubpathOptions,
) ![]const u8 {
    const base = try realPathFileAllocPlain(allocator, cwd orelse ".");
    defer allocator.free(base);
    const child = subpath orelse return allocator.dupe(u8, base);
    if (std.fs.path.isAbsolute(child)) return error.InvalidCommandExecPermissionProfileEntry;
    const resolved = try std.fs.path.resolve(allocator, &.{ base, child });
    defer allocator.free(resolved);
    if (!commandExecPathIsWithinBase(base, resolved)) return error.InvalidCommandExecPermissionProfileEntry;
    const canonical = realPathFileAllocPlain(allocator, resolved) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => if (options.allow_missing_leaf)
            try commandExecCanonicalMissingPath(allocator, resolved)
        else
            return error.InvalidCommandExecPermissionProfileEntry,
        else => return err,
    };
    errdefer allocator.free(canonical);
    if (!commandExecPathIsWithinBase(base, canonical)) return error.InvalidCommandExecPermissionProfileEntry;
    return canonical;
}

fn commandExecCanonicalMissingPath(allocator: std.mem.Allocator, absolute_path: []const u8) ![]const u8 {
    var probe_end = absolute_path.len;
    while (probe_end > 0) {
        const probe = absolute_path[0..probe_end];
        const real_parent = realPathFileAllocPlain(allocator, probe) catch |err| switch (err) {
            error.FileNotFound, error.NotDir => {
                const parent = std.fs.path.dirname(probe) orelse return allocator.dupe(u8, absolute_path);
                if (parent.len >= probe.len) return allocator.dupe(u8, absolute_path);
                probe_end = parent.len;
                continue;
            },
            else => return err,
        };
        errdefer allocator.free(real_parent);

        const suffix = if (probe_end < absolute_path.len and absolute_path[probe_end] == std.fs.path.sep)
            absolute_path[probe_end + 1 ..]
        else
            absolute_path[probe_end..];
        if (suffix.len == 0) return real_parent;

        const joined = try std.fs.path.join(allocator, &.{ real_parent, suffix });
        allocator.free(real_parent);
        return joined;
    }
    return allocator.dupe(u8, absolute_path);
}

fn commandExecPathIsWithinBase(base: []const u8, path: []const u8) bool {
    if (std.mem.eql(u8, base, path)) return true;
    if (std.mem.eql(u8, base, std.fs.path.sep_str)) return std.fs.path.isAbsolute(path);
    if (!std.mem.startsWith(u8, path, base)) return false;
    return path.len > base.len and path[base.len] == std.fs.path.sep;
}

fn commandExecPermissionPathIsTmpdir(value: std.json.Value) !bool {
    const kind = try commandExecPermissionSpecialPathKind(value);
    return if (kind) |special| std.mem.eql(u8, special, "tmpdir") else false;
}

fn commandExecPermissionPathIsSlashTmp(value: std.json.Value) !bool {
    const kind = try commandExecPermissionSpecialPathKind(value);
    return if (kind) |special| std.mem.eql(u8, special, "slash_tmp") else false;
}

fn commandExecPermissionSpecialPathKind(value: std.json.Value) !?[]const u8 {
    if (value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const type_value = value.object.get("type") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (type_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    if (!std.mem.eql(u8, type_value.string, "special")) return null;
    const special_value = value.object.get("value") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (special_value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const kind_value = special_value.object.get("kind") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (kind_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    return kind_value.string;
}

fn commandExecPermissionPathAbsolute(value: std.json.Value) !?[]const u8 {
    if (value != .object) return error.InvalidCommandExecPermissionProfileEntry;
    const type_value = value.object.get("type") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (type_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    if (!std.mem.eql(u8, type_value.string, "path")) return null;
    const path_value = value.object.get("path") orelse return error.InvalidCommandExecPermissionProfileEntry;
    if (path_value != .string) return error.InvalidCommandExecPermissionProfileEntry;
    if (!std.fs.path.isAbsolute(path_value.string)) return error.InvalidCommandExecPermissionProfileEntry;
    return path_value.string;
}

fn parseCommandExecSandboxPolicy(
    allocator: std.mem.Allocator,
    value: ?std.json.Value,
    default_mode: config.SandboxMode,
) !CommandExecSandbox {
    const policy = value orelse return defaultCommandExecSandbox(allocator, default_mode);
    if (policy == .null) return defaultCommandExecSandbox(allocator, default_mode);
    if (policy != .object) return error.InvalidCommandExecSandboxPolicy;

    const type_value = policy.object.get("type") orelse return error.InvalidCommandExecSandboxPolicyType;
    if (type_value != .string) return error.InvalidCommandExecSandboxPolicyType;
    if (std.mem.eql(u8, type_value.string, "dangerFullAccess")) {
        return .{ .mode = .danger_full_access, .writable_roots = try allocator.alloc([]const u8, 0) };
    }
    if (std.mem.eql(u8, type_value.string, "readOnly")) {
        const network_enabled = try parseCommandExecSandboxPolicyNetworkAccess(policy.object);
        return .{ .mode = .read_only, .writable_roots = try allocator.alloc([]const u8, 0), .network_enabled = network_enabled };
    }
    if (std.mem.eql(u8, type_value.string, "externalSandbox")) {
        const network_enabled = try parseCommandExecExternalSandboxPolicyNetworkAccess(policy.object);
        return .{ .mode = .danger_full_access, .writable_roots = try allocator.alloc([]const u8, 0), .network_enabled = network_enabled };
    }
    if (!std.mem.eql(u8, type_value.string, "workspaceWrite")) return error.InvalidCommandExecSandboxPolicyType;

    const writable_roots = try parseCommandExecWorkspaceWriteRoots(allocator, policy.object);
    const network_enabled = try parseCommandExecSandboxPolicyNetworkAccess(policy.object);
    return .{ .mode = .workspace_write, .writable_roots = writable_roots, .network_enabled = network_enabled };
}

fn defaultCommandExecSandbox(allocator: std.mem.Allocator, mode: config.SandboxMode) !CommandExecSandbox {
    const writable_roots = if (mode == .workspace_write)
        try buildCommandExecWorkspaceWriteRoots(allocator, &.{}, commandExecCurrentAbsoluteEnv("TMPDIR"), "/tmp")
    else
        try allocator.alloc([]const u8, 0);
    return .{ .mode = mode, .writable_roots = writable_roots };
}

fn parseCommandExecSandboxPolicyNetworkAccess(object: std.json.ObjectMap) !bool {
    const value = object.get("networkAccess") orelse return false;
    if (value == .null) return false;
    if (value != .bool) return error.InvalidCommandExecSandboxPolicyNetworkAccess;
    return value.bool;
}

fn parseCommandExecExternalSandboxPolicyNetworkAccess(object: std.json.ObjectMap) !bool {
    const value = object.get("networkAccess") orelse return false;
    if (value == .null) return false;
    if (value != .string) return error.InvalidCommandExecSandboxPolicyExternalNetworkAccess;
    if (std.mem.eql(u8, value.string, "restricted")) return false;
    if (std.mem.eql(u8, value.string, "enabled")) return true;
    return error.InvalidCommandExecSandboxPolicyExternalNetworkAccess;
}

fn parseCommandExecWorkspaceWriteRoots(allocator: std.mem.Allocator, object: std.json.ObjectMap) ![]const []const u8 {
    const explicit_roots = try parseCommandExecWritableRoots(allocator, object);
    defer allocator.free(explicit_roots);

    const exclude_tmpdir = try parseCommandExecSandboxPolicyBool(
        object,
        "excludeTmpdirEnvVar",
        error.InvalidCommandExecSandboxPolicyExcludeTmpdirEnvVar,
    );
    const exclude_slash_tmp = try parseCommandExecSandboxPolicyBool(
        object,
        "excludeSlashTmp",
        error.InvalidCommandExecSandboxPolicyExcludeSlashTmp,
    );
    const tmpdir_root = if (!exclude_tmpdir) commandExecCurrentAbsoluteEnv("TMPDIR") else null;
    const slash_tmp_root: ?[]const u8 = if (!exclude_slash_tmp) "/tmp" else null;

    return buildCommandExecWorkspaceWriteRoots(allocator, explicit_roots, tmpdir_root, slash_tmp_root);
}

fn buildCommandExecWorkspaceWriteRoots(
    allocator: std.mem.Allocator,
    explicit_roots: []const []const u8,
    tmpdir_root: ?[]const u8,
    slash_tmp_root: ?[]const u8,
) ![]const []const u8 {
    var root_count = explicit_roots.len;
    if (tmpdir_root != null) root_count += 1;
    if (slash_tmp_root != null) root_count += 1;

    const roots = try allocator.alloc([]const u8, root_count);
    @memcpy(roots[0..explicit_roots.len], explicit_roots);
    var index = explicit_roots.len;
    if (tmpdir_root) |root| {
        roots[index] = root;
        index += 1;
    }
    if (slash_tmp_root) |root| {
        roots[index] = root;
    }
    return roots;
}

fn parseCommandExecSandboxPolicyBool(
    object: std.json.ObjectMap,
    field: []const u8,
    comptime invalid_error: anyerror,
) !bool {
    const value = object.get(field) orelse return false;
    if (value == .null) return false;
    if (value != .bool) return invalid_error;
    return value.bool;
}

fn commandExecCurrentAbsoluteEnv(comptime name: []const u8) ?[]const u8 {
    const c_name: [*:0]const u8 = name ++ "\x00";
    const raw = std.c.getenv(c_name) orelse return null;
    const value = std.mem.span(raw);
    if (value.len == 0 or !std.fs.path.isAbsolute(value)) return null;
    return value;
}

fn parseCommandExecWritableRoots(allocator: std.mem.Allocator, object: std.json.ObjectMap) ![]const []const u8 {
    const value = object.get("writableRoots") orelse return allocator.alloc([]const u8, 0);
    if (value == .null) return allocator.alloc([]const u8, 0);
    if (value != .array) return error.InvalidCommandExecWritableRoots;
    const roots = try allocator.alloc([]const u8, value.array.items.len);
    errdefer allocator.free(roots);
    for (value.array.items, 0..) |item, index| {
        if (item != .string or !std.fs.path.isAbsolute(item.string)) return error.InvalidCommandExecWritableRoots;
        roots[index] = item.string;
    }
    return roots;
}

fn commandExecEnvironment(allocator: std.mem.Allocator, value: std.json.Value) !std.process.Environ.Map {
    if (value == .null) return error.InvalidCommandExecEnv;
    if (value != .object) return error.InvalidCommandExecEnv;

    var child_env = try commandExecCurrentEnvironment(allocator);
    errdefer child_env.deinit();

    var iterator = value.object.iterator();
    while (iterator.next()) |entry| {
        const key = entry.key_ptr.*;
        if (!std.process.Environ.Map.validateKeyForPut(key)) return error.InvalidCommandExecEnvKey;
        switch (entry.value_ptr.*) {
            .null => _ = child_env.swapRemove(key),
            .string => |string| try child_env.put(key, string),
            else => return error.InvalidCommandExecEnvValue,
        }
    }

    return child_env;
}

fn commandExecCurrentEnvironment(allocator: std.mem.Allocator) !std.process.Environ.Map {
    var result = std.process.Environ.Map.init(allocator);
    errdefer result.deinit();

    var index: usize = 0;
    while (std.c.environ[index]) |entry_ptr| : (index += 1) {
        const entry = std.mem.span(entry_ptr);
        const eq = std.mem.indexOfScalar(u8, entry, '=') orelse continue;
        const key = entry[0..eq];
        if (!std.process.Environ.Map.validateKeyForPut(key)) continue;
        try result.put(key, entry[eq + 1 ..]);
    }
    return result;
}

fn copyPath(allocator: std.mem.Allocator, io: std.Io, source_path: []const u8, destination_path: []const u8, recursive: bool) !void {
    const metadata = (try statPathNoFollow(allocator, source_path)) orelse return error.FileNotFound;
    const mode: u32 = @intCast(metadata.mode);
    if (std.c.S.ISDIR(mode)) {
        if (!recursive) return error.FsCopyDirectoryRequiresRecursive;
        if (pathIsSameOrDescendant(source_path, destination_path)) return error.FsCopyDestinationInsideSource;
        try std.Io.Dir.cwd().createDirPath(io, destination_path);
        var source_dir = try std.Io.Dir.openDirAbsolute(io, source_path, .{ .iterate = true });
        defer source_dir.close(io);
        var iter = source_dir.iterate();
        while (try iter.next(io)) |entry| {
            const child_source = try std.fs.path.join(allocator, &.{ source_path, entry.name });
            defer allocator.free(child_source);
            const child_destination = try std.fs.path.join(allocator, &.{ destination_path, entry.name });
            defer allocator.free(child_destination);
            try copyPath(allocator, io, child_source, child_destination, recursive);
        }
        return;
    }
    if (std.c.S.ISLNK(mode)) {
        var target_buffer: [std.fs.max_path_bytes]u8 = undefined;
        const target_len = try std.Io.Dir.readLinkAbsolute(io, source_path, &target_buffer);
        try std.Io.Dir.cwd().symLink(io, target_buffer[0..target_len], destination_path, .{});
        return;
    }
    if (std.c.S.ISREG(mode)) {
        try std.Io.Dir.copyFileAbsolute(source_path, destination_path, io, .{});
        return;
    }
    return error.FsCopyUnsupportedFileType;
}

fn pathIsSameOrDescendant(source_path: []const u8, destination_path: []const u8) bool {
    const source = std.mem.trimEnd(u8, source_path, std.fs.path.sep_str);
    const destination = std.mem.trimEnd(u8, destination_path, std.fs.path.sep_str);
    if (std.mem.eql(u8, source, destination)) return true;
    if (!std.mem.startsWith(u8, destination, source)) return false;
    if (destination.len <= source.len) return false;
    return destination[source.len] == std.fs.path.sep;
}

fn statCreatedAtMs(stat: std.c.Stat) i64 {
    if (@hasDecl(std.c.Stat, "birthtime")) return timespecToUnixMs(stat.birthtime());
    return 0;
}

fn timespecToUnixMs(value: std.c.timespec) i64 {
    return @as(i64, @intCast(value.sec)) * 1000 + @divTrunc(@as(i64, @intCast(value.nsec)), 1_000_000);
}

fn timespecToUnixNs(value: std.c.timespec) i64 {
    return @as(i64, @intCast(value.sec)) * std.time.ns_per_s + @as(i64, @intCast(value.nsec));
}

fn isConfigMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "config/read") or
        std.mem.eql(u8, method, "config/value/write") or
        std.mem.eql(u8, method, "config/batchWrite") or
        std.mem.eql(u8, method, "configRequirements/read") or
        std.mem.eql(u8, method, "externalAgentConfig/detect") or
        std.mem.eql(u8, method, "externalAgentConfig/import");
}

fn handleConfigMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "config/read")) {
        return handleConfigRead(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "config/value/write")) {
        const response = try handleConfigValueWrite(allocator, id_value, params_value);
        clearSkillsListCache(allocator, state);
        return response;
    }
    if (std.mem.eql(u8, method, "config/batchWrite")) {
        const response = try handleConfigBatchWrite(allocator, state, id_value, params_value);
        clearSkillsListCache(allocator, state);
        return response;
    }
    if (std.mem.eql(u8, method, "configRequirements/read")) {
        return handleConfigRequirementsRead(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "externalAgentConfig/detect")) {
        return handleExternalAgentConfigDetect(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "externalAgentConfig/import")) {
        return handleExternalAgentConfigImport(allocator, state, id_value, params_value);
    }
    return try renderJsonRpcError(allocator, id_value, -32601, "unknown config method");
}

fn handleExternalAgentConfigDetect(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    var include_home = false;
    var cwds: []const std.json.Value = &.{};
    if (params_value) |params| {
        if (params != .null and params != .object) {
            return renderJsonRpcError(allocator, id_value, -32602, "externalAgentConfig/detect params must be an object, null, or omitted");
        }
        if (params == .object) {
            if (params.object.get("includeHome")) |value| {
                if (value != .bool) return renderJsonRpcError(allocator, id_value, -32602, "includeHome must be a boolean");
                include_home = value.bool;
            }
            if (params.object.get("cwds")) |value| {
                if (value != .null and value != .array) return renderJsonRpcError(allocator, id_value, -32602, "cwds must be an array of strings or null");
                if (value == .array) {
                    for (value.array.items) |cwd| {
                        if (cwd != .string) return renderJsonRpcError(allocator, id_value, -32602, "cwds must be an array of strings or null");
                    }
                    cwds = value.array.items;
                }
            }
        }
    }

    const codex_home = resolveCodexHome(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/detect failed to resolve CODEX_HOME", err);
    };
    defer allocator.free(codex_home);

    const result = try renderExternalAgentConfigDetectResponse(allocator, codex_home, include_home, cwds);
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

const ExternalAgentConfigImportItem = struct {
    item_type: []const u8,
    cwd: ?[]const u8,
    details: ?std.json.Value = null,
};

fn handleExternalAgentConfigImport(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "externalAgentConfig/import params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "externalAgentConfig/import params must be an object");

    const migration_items = params.object.get("migrationItems") orelse return renderJsonRpcError(allocator, id_value, -32602, "migrationItems must be an array");
    if (migration_items != .array) return renderJsonRpcError(allocator, id_value, -32602, "migrationItems must be an array");
    var all_items_supported = true;
    var import_items = std.ArrayList(ExternalAgentConfigImportItem).empty;
    defer import_items.deinit(allocator);
    for (migration_items.array.items) |item| {
        if (item != .object) return renderJsonRpcError(allocator, id_value, -32602, "migrationItems entries must be objects");
        const item_type = item.object.get("itemType") orelse return renderJsonRpcError(allocator, id_value, -32602, "migrationItems entries must include itemType");
        if (item_type != .string or !isExternalAgentConfigMigrationItemType(item_type.string)) {
            return renderJsonRpcError(allocator, id_value, -32602, "migrationItems entries must use a supported itemType");
        }
        const description = item.object.get("description") orelse return renderJsonRpcError(allocator, id_value, -32602, "migrationItems entries must include description");
        if (description != .string) return renderJsonRpcError(allocator, id_value, -32602, "migrationItems entries must include description");
        if (item.object.get("cwd")) |cwd| {
            if (cwd != .null and cwd != .string) return renderJsonRpcError(allocator, id_value, -32602, "migrationItems cwd must be a string or null");
        }
        if (item.object.get("details")) |details| {
            if (details != .null and details != .object) return renderJsonRpcError(allocator, id_value, -32602, "migrationItems details must be an object or null");
        }
        if (!isSupportedExternalAgentConfigImportItem(item.object)) {
            all_items_supported = false;
        } else {
            const cwd = if (item.object.get("cwd")) |cwd_value|
                if (cwd_value == .string) cwd_value.string else null
            else
                null;
            const details = if (item.object.get("details")) |details_value|
                if (details_value == .object) details_value else null
            else
                null;
            try import_items.append(allocator, .{ .item_type = item_type.string, .cwd = cwd, .details = details });
        }
    }
    if (migration_items.array.items.len == 0) {
        return renderJsonRpcResult(allocator, id_value, "{}");
    }
    if (!all_items_supported) {
        return renderJsonRpcError(allocator, id_value, -32603, "externalAgentConfig/import migration items are parsed but not implemented yet");
    }
    const needs_runtime_refresh = externalAgentImportNeedsRuntimeRefresh(import_items.items);

    const codex_home = resolveCodexHome(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to resolve CODEX_HOME", err);
    };
    defer allocator.free(codex_home);

    for (import_items.items) |item| {
        if (std.mem.eql(u8, item.item_type, "CONFIG")) {
            importExternalAgentConfig(allocator, codex_home, item.cwd) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import config", err);
            };
        } else if (std.mem.eql(u8, item.item_type, "MCP_SERVER_CONFIG")) {
            importExternalAgentMcpServerConfig(allocator, codex_home, item.cwd) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import MCP server config", err);
            };
        } else if (std.mem.eql(u8, item.item_type, "HOOKS")) {
            importExternalAgentHooks(allocator, codex_home, item.cwd) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import hooks", err);
            };
        } else if (std.mem.eql(u8, item.item_type, "AGENTS_MD")) {
            importExternalAgentAgentsMd(allocator, codex_home, item.cwd) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import AGENTS.md", err);
            };
        } else if (std.mem.eql(u8, item.item_type, "PLUGINS")) {
            importExternalAgentPlugins(allocator, codex_home, item.cwd, item.details) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import plugins", err);
            };
        } else if (std.mem.eql(u8, item.item_type, "SKILLS")) {
            importExternalAgentSkills(allocator, codex_home, item.cwd) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import skills", err);
            };
        } else if (std.mem.eql(u8, item.item_type, "COMMANDS")) {
            importExternalAgentCommands(allocator, codex_home, item.cwd) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import commands", err);
            };
        } else if (std.mem.eql(u8, item.item_type, "SUBAGENTS")) {
            importExternalAgentSubagents(allocator, codex_home, item.cwd) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import subagents", err);
            };
        } else if (std.mem.eql(u8, item.item_type, "SESSIONS")) {
            importExternalAgentSessions(allocator, codex_home, item.details) catch |err| {
                return renderJsonRpcErrorForFailure(allocator, id_value, "externalAgentConfig/import failed to import sessions", err);
            };
        }
    }
    if (needs_runtime_refresh) clearSkillsListCache(allocator, state);

    const response = try renderJsonRpcResult(allocator, id_value, "{}");
    defer allocator.free(response);
    return renderResultWithExternalAgentConfigImportCompletedNotification(allocator, response);
}

fn externalAgentImportNeedsRuntimeRefresh(items: []const ExternalAgentConfigImportItem) bool {
    for (items) |item| {
        if (std.mem.eql(u8, item.item_type, "CONFIG") or
            std.mem.eql(u8, item.item_type, "MCP_SERVER_CONFIG") or
            std.mem.eql(u8, item.item_type, "HOOKS") or
            std.mem.eql(u8, item.item_type, "PLUGINS") or
            std.mem.eql(u8, item.item_type, "SKILLS") or
            std.mem.eql(u8, item.item_type, "COMMANDS")) return true;
    }
    return false;
}

fn importExternalAgentConfig(allocator: std.mem.Allocator, codex_home: []const u8, cwd: ?[]const u8) !void {
    if (cwd) |cwd_value| {
        if (cwd_value.len != 0) {
            const repo_root = (try findExternalAgentRepoRoot(allocator, cwd_value)) orelse return;
            defer allocator.free(repo_root);
            const settings_path = try externalAgentProjectSettingsPath(allocator, repo_root);
            defer allocator.free(settings_path);
            const target_config = try externalAgentProjectConfigPath(allocator, repo_root);
            defer allocator.free(target_config);
            return importExternalAgentConfigAt(allocator, settings_path, target_config);
        }
    }
    return importExternalAgentHomeConfig(allocator, codex_home);
}

fn importExternalAgentMcpServerConfig(allocator: std.mem.Allocator, codex_home: []const u8, cwd: ?[]const u8) !void {
    if (cwd) |cwd_value| {
        if (cwd_value.len != 0) {
            const repo_root = (try findExternalAgentRepoRoot(allocator, cwd_value)) orelse return;
            defer allocator.free(repo_root);
            return importExternalAgentProjectMcpServerConfig(allocator, repo_root);
        }
    }
    return importExternalAgentHomeMcpServerConfig(allocator, codex_home);
}

fn importExternalAgentHooks(allocator: std.mem.Allocator, codex_home: []const u8, cwd: ?[]const u8) !void {
    if (cwd) |cwd_value| {
        if (cwd_value.len != 0) {
            const repo_root = (try findExternalAgentRepoRoot(allocator, cwd_value)) orelse return;
            defer allocator.free(repo_root);
            return importExternalAgentProjectHooks(allocator, repo_root);
        }
    }
    return importExternalAgentHomeHooks(allocator, codex_home);
}

fn importExternalAgentPlugins(allocator: std.mem.Allocator, codex_home: []const u8, cwd: ?[]const u8, details: ?std.json.Value) !void {
    if (cwd) |cwd_value| {
        if (cwd_value.len != 0) {
            const repo_root = (try findExternalAgentRepoRoot(allocator, cwd_value)) orelse return;
            defer allocator.free(repo_root);
            return importExternalAgentProjectPlugins(allocator, codex_home, repo_root, details);
        }
    }
    return importExternalAgentHomePlugins(allocator, codex_home, details);
}

