fn findExternalAgentRepoRoot(allocator: std.mem.Allocator, cwd: []const u8) !?[]const u8 {
    if (cwd.len == 0) return null;
    const io = std.Io.Threaded.global_single_threaded.io();
    var current = if (std.fs.path.isAbsolute(cwd))
        try allocator.dupe(u8, cwd)
    else blk: {
        const process_cwd = try std.Io.Dir.cwd().realPathFileAlloc(io, ".", allocator);
        defer allocator.free(process_cwd);
        break :blk try std.fs.path.join(allocator, &.{ process_cwd, cwd });
    };
    errdefer allocator.free(current);

    const current_stat = statPathFollow(allocator, current) catch |err| switch (err) {
        error.NotDir => return null,
        else => return err,
    } orelse return null;
    if (std.c.S.ISREG(@intCast(current_stat.mode))) {
        const parent = std.fs.path.dirname(current) orelse return null;
        const next = try allocator.dupe(u8, parent);
        allocator.free(current);
        current = next;
    }

    const fallback = try allocator.dupe(u8, current);
    defer allocator.free(fallback);
    while (true) {
        const git_path = try std.fs.path.join(allocator, &.{ current, ".git" });
        defer allocator.free(git_path);
        const git_stat = statPathFollow(allocator, git_path) catch |err| switch (err) {
            error.NotDir => null,
            else => return err,
        };
        if (git_stat != null) return current;

        const parent = std.fs.path.dirname(current) orelse break;
        const next = try allocator.dupe(u8, parent);
        allocator.free(current);
        current = next;
    }

    allocator.free(current);
    const owned_fallback = try allocator.dupe(u8, fallback);
    return owned_fallback;
}

fn isNonEmptyTextFile(allocator: std.mem.Allocator, path: []const u8) !bool {
    const bytes = readTextFile(allocator, path) catch |err| switch (err) {
        error.FileNotFound => return false,
        error.NotDir => return false,
        else => return err,
    };
    defer allocator.free(bytes);
    return std.mem.trim(u8, bytes, " \t\r\n").len > 0;
}

fn isMissingOrEmptyTextFile(allocator: std.mem.Allocator, path: []const u8) !bool {
    const bytes = readTextFile(allocator, path) catch |err| switch (err) {
        error.FileNotFound => return true,
        error.NotDir => return false,
        else => return err,
    };
    defer allocator.free(bytes);
    return std.mem.trim(u8, bytes, " \t\r\n").len == 0;
}

fn externalAgentPathExists(allocator: std.mem.Allocator, path: []const u8) !bool {
    return (statPathFollow(allocator, path) catch |err| switch (err) {
        error.NotDir => return false,
        else => return err,
    }) != null;
}

fn readTextFile(allocator: std.mem.Allocator, path: []const u8) ![]const u8 {
    return std.Io.Dir.cwd().readFileAlloc(std.Io.Threaded.global_single_threaded.io(), path, allocator, .limited(1024 * 1024));
}

fn writeTextFile(path: []const u8, bytes: []const u8) !void {
    const io = std.Io.Threaded.global_single_threaded.io();
    if (std.fs.path.dirname(path)) |parent| {
        try std.Io.Dir.cwd().createDirPath(io, parent);
    }
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = bytes });
}

fn rewriteExternalAgentTerms(allocator: std.mem.Allocator, content: []const u8) ![]const u8 {
    var rewritten = try replaceAsciiCaseInsensitiveWithBoundaries(allocator, content, "claude.md", "AGENTS.md");
    errdefer allocator.free(rewritten);
    const replacements = [_][]const u8{
        "claude code",
        "claude-code",
        "claude_code",
        "claudecode",
        "claude",
    };
    for (replacements) |needle| {
        const next = try replaceAsciiCaseInsensitiveWithBoundaries(allocator, rewritten, needle, "Codex");
        allocator.free(rewritten);
        rewritten = next;
    }
    return rewritten;
}

fn replaceAsciiCaseInsensitiveWithBoundaries(
    allocator: std.mem.Allocator,
    input: []const u8,
    needle: []const u8,
    replacement: []const u8,
) ![]const u8 {
    if (needle.len == 0) return allocator.dupe(u8, input);
    var output = std.ArrayList(u8).empty;
    errdefer output.deinit(allocator);

    var last_emitted: usize = 0;
    var search_start: usize = 0;
    while (search_start + needle.len <= input.len) {
        if (asciiRegionEqlIgnoreCase(input[search_start .. search_start + needle.len], needle) and
            isExternalAgentRewriteBoundary(input, search_start, search_start + needle.len))
        {
            try output.appendSlice(allocator, input[last_emitted..search_start]);
            try output.appendSlice(allocator, replacement);
            search_start += needle.len;
            last_emitted = search_start;
            continue;
        }
        search_start += 1;
    }

    if (last_emitted == 0) return allocator.dupe(u8, input);
    try output.appendSlice(allocator, input[last_emitted..]);
    return output.toOwnedSlice(allocator);
}

fn asciiRegionEqlIgnoreCase(lhs: []const u8, rhs: []const u8) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |left, right| {
        if (std.ascii.toLower(left) != std.ascii.toLower(right)) return false;
    }
    return true;
}

fn isExternalAgentRewriteBoundary(input: []const u8, start: usize, end: usize) bool {
    const boundary_before = start == 0 or !isExternalAgentRewriteWordByte(input[start - 1]);
    const boundary_after = end == input.len or !isExternalAgentRewriteWordByte(input[end]);
    return boundary_before and boundary_after;
}

fn isExternalAgentRewriteWordByte(byte: u8) bool {
    return std.ascii.isAlphanumeric(byte) or byte == '_';
}

fn tomlKeyPathHasAssignment(bytes: []const u8, key_path: []const u8) bool {
    const section, const key = splitTomlKeyPath(key_path);
    var in_target = section == null;
    var start: usize = 0;
    while (start < bytes.len) {
        const end = std.mem.indexOfScalarPos(u8, bytes, start, '\n') orelse bytes.len;
        const line_raw = bytes[start..end];
        start = if (end < bytes.len) end + 1 else bytes.len;

        const line_without_comment = if (std.mem.indexOfScalar(u8, line_raw, '#')) |index| line_raw[0..index] else line_raw;
        const trimmed = std.mem.trim(u8, line_without_comment, " \t\r");
        if (trimmed.len == 0) continue;
        if (trimmed[0] == '[') {
            in_target = if (section) |section_name| isExactTomlSection(trimmed, section_name) else false;
            continue;
        }
        if (in_target and tomlValueForKey(trimmed, key) != null) return true;
    }
    return false;
}

fn splitTomlKeyPath(key_path: []const u8) struct { ?[]const u8, []const u8 } {
    if (std.mem.lastIndexOfScalar(u8, key_path, '.')) |index| {
        return .{ key_path[0..index], key_path[index + 1 ..] };
    }
    return .{ null, key_path };
}

fn renderResultWithExternalAgentConfigImportCompletedNotification(allocator: std.mem.Allocator, response: []const u8) ![]const u8 {
    return std.fmt.allocPrint(
        allocator,
        "{s}\n{{\"method\":\"externalAgentConfig/import/completed\",\"params\":{{}}}}",
        .{response},
    );
}

fn handleConfigRequirementsRead(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    if (params_value) |params| {
        if (params != .null) {
            return renderJsonRpcError(allocator, id_value, -32602, "configRequirements/read params must be null or omitted");
        }
    }
    var requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "configRequirements/read failed to load config requirements", err);
    };
    defer requirements.deinit(allocator);
    const result = try renderConfigRequirementsReadResponse(allocator, requirements);
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

const ConfigRequirementsReadRequirements = struct {
    allowed_approval_policies: ?config.StringList = null,
    allowed_approvals_reviewers: ?config.StringList = null,
    allowed_sandbox_modes: ?config.StringList = null,
    allowed_web_search_modes: ?config.StringList = null,
    feature_requirements: ?FeatureRequirementList = null,
    hooks: ?config_requirements_hooks.ManagedHooksRequirements = null,
    enforce_residency: ?[]const u8 = null,
    network: ?NetworkRequirements = null,
    // Internal app/list enforcement. The current configRequirements/read API does not expose apps.
    app_requirements: ?plugin_list.AppRequirements = null,

    fn deinit(self: *ConfigRequirementsReadRequirements, allocator: std.mem.Allocator) void {
        if (self.allowed_approval_policies) |*value| value.deinit(allocator);
        if (self.allowed_approvals_reviewers) |*value| value.deinit(allocator);
        if (self.allowed_sandbox_modes) |*value| value.deinit(allocator);
        if (self.allowed_web_search_modes) |*value| value.deinit(allocator);
        if (self.feature_requirements) |*value| value.deinit(allocator);
        if (self.hooks) |*value| value.deinit(allocator);
        if (self.enforce_residency) |value| allocator.free(value);
        if (self.network) |*value| value.deinit(allocator);
        if (self.app_requirements) |*value| value.deinit(allocator);
        self.* = .{};
    }

    fn isEmpty(self: ConfigRequirementsReadRequirements) bool {
        return self.allowed_approval_policies == null and
            self.allowed_approvals_reviewers == null and
            self.allowed_sandbox_modes == null and
            self.allowed_web_search_modes == null and
            self.feature_requirements == null and
            self.hooks == null and
            self.enforce_residency == null and
            self.network == null;
    }

    fn mergeUnset(self: *ConfigRequirementsReadRequirements, other: *ConfigRequirementsReadRequirements) void {
        if (self.allowed_approval_policies == null) {
            self.allowed_approval_policies = other.allowed_approval_policies;
            other.allowed_approval_policies = null;
        }
        if (self.allowed_approvals_reviewers == null) {
            self.allowed_approvals_reviewers = other.allowed_approvals_reviewers;
            other.allowed_approvals_reviewers = null;
        }
        if (self.allowed_sandbox_modes == null) {
            self.allowed_sandbox_modes = other.allowed_sandbox_modes;
            other.allowed_sandbox_modes = null;
        }
        if (self.allowed_web_search_modes == null) {
            self.allowed_web_search_modes = other.allowed_web_search_modes;
            other.allowed_web_search_modes = null;
        }
        if (self.feature_requirements == null) {
            self.feature_requirements = other.feature_requirements;
            other.feature_requirements = null;
        }
        if (self.hooks == null) {
            self.hooks = other.hooks;
            other.hooks = null;
        }
        if (self.enforce_residency == null) {
            self.enforce_residency = other.enforce_residency;
            other.enforce_residency = null;
        }
        if (self.network == null) {
            self.network = other.network;
            other.network = null;
        }
        if (self.app_requirements == null) {
            self.app_requirements = other.app_requirements;
            other.app_requirements = null;
        }
    }
};

const FeatureRequirement = struct {
    name: []const u8,
    enabled: bool,
};

const FeatureRequirementList = struct {
    items: []FeatureRequirement,

    fn deinit(self: *FeatureRequirementList, allocator: std.mem.Allocator) void {
        for (self.items) |item| allocator.free(item.name);
        allocator.free(self.items);
        self.items = &.{};
    }
};

const NetworkPermissionEntry = struct {
    key: []const u8,
    value: []const u8,
};

const NetworkPermissionEntryList = struct {
    items: []NetworkPermissionEntry,

    fn deinit(self: *NetworkPermissionEntryList, allocator: std.mem.Allocator) void {
        for (self.items) |item| deinitNetworkPermissionEntry(allocator, item);
        allocator.free(self.items);
        self.items = &.{};
    }
};

const NetworkRequirements = struct {
    enabled: ?bool = null,
    http_port: ?u16 = null,
    socks_port: ?u16 = null,
    allow_upstream_proxy: ?bool = null,
    dangerously_allow_non_loopback_proxy: ?bool = null,
    dangerously_allow_all_unix_sockets: ?bool = null,
    domains: ?NetworkPermissionEntryList = null,
    managed_allowed_domains_only: ?bool = null,
    unix_sockets: ?NetworkPermissionEntryList = null,
    allow_local_binding: ?bool = null,

    fn deinit(self: *NetworkRequirements, allocator: std.mem.Allocator) void {
        if (self.domains) |*value| value.deinit(allocator);
        if (self.unix_sockets) |*value| value.deinit(allocator);
        self.* = .{};
    }

    fn isEmpty(self: NetworkRequirements) bool {
        return self.enabled == null and
            self.http_port == null and
            self.socks_port == null and
            self.allow_upstream_proxy == null and
            self.dangerously_allow_non_loopback_proxy == null and
            self.dangerously_allow_all_unix_sockets == null and
            self.domains == null and
            self.managed_allowed_domains_only == null and
            self.unix_sockets == null and
            self.allow_local_binding == null;
    }
};

fn loadConfigRequirementsReadRequirements(allocator: std.mem.Allocator) !ConfigRequirementsReadRequirements {
    var requirements = try loadSystemConfigRequirements(allocator);
    errdefer requirements.deinit(allocator);

    var legacy_requirements = try loadLegacyManagedConfigRequirements(allocator);
    defer legacy_requirements.deinit(allocator);
    requirements.mergeUnset(&legacy_requirements);

    return requirements;
}

fn loadSystemConfigRequirements(allocator: std.mem.Allocator) !ConfigRequirementsReadRequirements {
    const path = try systemRequirementsPath(allocator);
    defer allocator.free(path);

    const bytes = try config.readConfigTomlFile(allocator, path);
    defer if (bytes) |payload| allocator.free(payload);
    const payload = bytes orelse return .{};

    var requirements = ConfigRequirementsReadRequirements{};
    errdefer requirements.deinit(allocator);

    requirements.allowed_approval_policies = try parseAllowedRequirementList(allocator, payload, "allowed_approval_policies", .approval_policy);
    requirements.allowed_approvals_reviewers = try parseAllowedRequirementList(allocator, payload, "allowed_approvals_reviewers", .approvals_reviewer);
    requirements.allowed_sandbox_modes = try parseAllowedRequirementList(allocator, payload, "allowed_sandbox_modes", .sandbox_mode);
    requirements.allowed_web_search_modes = try parseAllowedRequirementList(allocator, payload, "allowed_web_search_modes", .web_search_mode);
    requirements.feature_requirements = try parseFeatureRequirements(allocator, payload);
    requirements.hooks = try config_requirements_hooks.parse(allocator, payload);
    requirements.enforce_residency = try parseResidencyRequirement(allocator, payload);
    requirements.network = try parseNetworkRequirements(allocator, payload);
    requirements.app_requirements = try plugin_list.parseAppRequirements(allocator, payload);

    return requirements;
}

fn loadLegacyManagedConfigRequirements(allocator: std.mem.Allocator) !ConfigRequirementsReadRequirements {
    const path = try managedConfigPath(allocator);
    defer allocator.free(path);

    const bytes = try config.readConfigTomlFile(allocator, path);
    defer if (bytes) |payload| allocator.free(payload);
    const payload = bytes orelse return .{};

    var requirements = ConfigRequirementsReadRequirements{};
    errdefer requirements.deinit(allocator);

    if (try config.topLevelStringValue(allocator, payload, "approval_policy")) |value| {
        defer allocator.free(value);
        const approval_policy = try config.ApprovalPolicy.parse(value);
        requirements.allowed_approval_policies = try stringListFromLabels(allocator, &.{approval_policy.label()});
    }
    if (try config.topLevelStringValue(allocator, payload, "approvals_reviewer")) |value| {
        defer allocator.free(value);
        const approvals_reviewer = try config.ApprovalsReviewer.parse(value);
        requirements.allowed_approvals_reviewers = switch (approvals_reviewer) {
            .user => try stringListFromLabels(allocator, &.{"user"}),
            .auto_review => try stringListFromLabels(allocator, &.{ "guardian_subagent", "user" }),
        };
    }
    if (try config.topLevelStringValue(allocator, payload, "sandbox_mode")) |value| {
        defer allocator.free(value);
        const sandbox_mode = try config.SandboxMode.parse(value);
        requirements.allowed_sandbox_modes = switch (sandbox_mode) {
            .read_only => try stringListFromLabels(allocator, &.{"read-only"}),
            .workspace_write => try stringListFromLabels(allocator, &.{ "read-only", "workspace-write" }),
            .danger_full_access => try stringListFromLabels(allocator, &.{ "read-only", "danger-full-access" }),
        };
    }
    return requirements;
}

const RequirementListKind = enum {
    approval_policy,
    approvals_reviewer,
    sandbox_mode,
    web_search_mode,
};

fn parseAllowedRequirementList(
    allocator: std.mem.Allocator,
    payload: []const u8,
    key: []const u8,
    kind: RequirementListKind,
) !?config.StringList {
    var raw = try config.topLevelStringArrayValue(allocator, payload, key) orelse return null;
    defer raw.deinit(allocator);

    var labels = std.ArrayList([]const u8).empty;
    errdefer {
        for (labels.items) |label| allocator.free(label);
        labels.deinit(allocator);
    }

    var disabled_present = false;
    for (raw.items) |value| {
        const label = try requirementLabel(kind, value) orelse continue;
        if (std.mem.eql(u8, label, config.WebSearchMode.disabled.label())) {
            disabled_present = true;
        }
        const owned_label = try allocator.dupe(u8, label);
        errdefer allocator.free(owned_label);
        try labels.append(allocator, owned_label);
    }

    const extra_disabled: usize = if (kind == .web_search_mode and !disabled_present) 1 else 0;
    if (extra_disabled == 1) {
        const owned_label = try allocator.dupe(u8, config.WebSearchMode.disabled.label());
        errdefer allocator.free(owned_label);
        try labels.append(allocator, owned_label);
    }

    return .{ .items = try labels.toOwnedSlice(allocator) };
}

fn requirementLabel(kind: RequirementListKind, value: []const u8) !?[]const u8 {
    return switch (kind) {
        .approval_policy => (try config.ApprovalPolicy.parse(value)).label(),
        .approvals_reviewer => (try config.ApprovalsReviewer.parse(value)).label(),
        .sandbox_mode => if (std.mem.eql(u8, value, "external-sandbox")) null else (try config.SandboxMode.parse(value)).label(),
        .web_search_mode => (try config.WebSearchMode.parse(value)).label(),
    };
}

fn parseFeatureRequirements(allocator: std.mem.Allocator, payload: []const u8) !?FeatureRequirementList {
    var entries = std.ArrayList(FeatureRequirement).empty;
    errdefer {
        deinitFeatureRequirementItems(allocator, entries.items);
        entries.deinit(allocator);
    }

    try appendFeatureRequirementsSection(allocator, payload, "features", &entries);
    try appendFeatureRequirementsSection(allocator, payload, "feature_requirements", &entries);

    if (entries.items.len == 0) {
        entries.deinit(allocator);
        return null;
    }

    const items = try entries.toOwnedSlice(allocator);
    std.mem.sort(FeatureRequirement, items, {}, featureRequirementLessThan);
    return .{ .items = items };
}

fn appendFeatureRequirementsSection(
    allocator: std.mem.Allocator,
    payload: []const u8,
    section_name: []const u8,
    entries: *std.ArrayList(FeatureRequirement),
) !void {
    var in_section = false;
    var iter = std.mem.splitScalar(u8, payload, '\n');
    while (iter.next()) |line_raw| {
        const line_without_comment = stripTomlLineComment(line_raw);
        const line = std.mem.trim(u8, line_without_comment, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (line[0] == '[') {
            in_section = isExactTomlSection(line, section_name);
            continue;
        }
        if (!in_section) continue;
        if (try parseFeatureRequirementLine(allocator, line)) |entry| {
            errdefer allocator.free(entry.name);
            try entries.append(allocator, entry);
        }
    }
}

fn stripTomlLineComment(line: []const u8) []const u8 {
    var quote: ?u8 = null;
    var escaped = false;
    for (line, 0..) |byte, index| {
        if (quote == null) {
            if (byte == '#') return line[0..index];
            if (byte == '"' or byte == 39) quote = byte;
            continue;
        }
        if (quote.? == '"' and escaped) {
            escaped = false;
            continue;
        }
        if (quote.? == '"' and byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == quote.?) quote = null;
    }
    return line;
}

fn parseFeatureRequirementLine(allocator: std.mem.Allocator, line: []const u8) !?FeatureRequirement {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return null;
    const raw_key = std.mem.trim(u8, line[0..eq], " \t");
    const raw_value = std.mem.trim(u8, line[eq + 1 ..], " \t");
    if (raw_key.len == 0) return error.InvalidFeatureRequirement;

    const enabled = if (std.mem.eql(u8, raw_value, "true"))
        true
    else if (std.mem.eql(u8, raw_value, "false"))
        false
    else
        return error.InvalidFeatureRequirement;

    const name = try parseTomlKeyName(allocator, raw_key);
    return .{ .name = name, .enabled = enabled };
}

fn parseTomlKeyName(allocator: std.mem.Allocator, raw_key: []const u8) ![]const u8 {
    if (raw_key.len > 0 and raw_key[0] == '"') {
        return try config.parseTomlString(allocator, raw_key) orelse error.InvalidFeatureRequirement;
    }
    return allocator.dupe(u8, raw_key);
}

fn isExactTomlSection(line: []const u8, section_name: []const u8) bool {
    if (line.len < "[]".len or line[0] != '[' or line[line.len - 1] != ']') return false;
    const name = std.mem.trim(u8, line[1 .. line.len - 1], " \t");
    return std.mem.eql(u8, name, section_name);
}

fn featureRequirementLessThan(_: void, lhs: FeatureRequirement, rhs: FeatureRequirement) bool {
    return std.mem.lessThan(u8, lhs.name, rhs.name);
}

fn deinitFeatureRequirementItems(allocator: std.mem.Allocator, items: []FeatureRequirement) void {
    for (items) |item| allocator.free(item.name);
}

fn parseResidencyRequirement(allocator: std.mem.Allocator, payload: []const u8) !?[]const u8 {
    const value = try config.topLevelStringValue(allocator, payload, "enforce_residency") orelse return null;
    errdefer allocator.free(value);
    if (!std.mem.eql(u8, value, "us")) return error.InvalidResidencyRequirement;
    return value;
}

fn parseNetworkRequirements(allocator: std.mem.Allocator, payload: []const u8) !?NetworkRequirements {
    const section = "experimental_network";
    var network = NetworkRequirements{
        .enabled = config.sectionBoolValue(payload, section, "enabled"),
        .http_port = try sectionU16Value(payload, section, "http_port"),
        .socks_port = try sectionU16Value(payload, section, "socks_port"),
        .allow_upstream_proxy = config.sectionBoolValue(payload, section, "allow_upstream_proxy"),
        .dangerously_allow_non_loopback_proxy = config.sectionBoolValue(payload, section, "dangerously_allow_non_loopback_proxy"),
        .dangerously_allow_all_unix_sockets = config.sectionBoolValue(payload, section, "dangerously_allow_all_unix_sockets"),
        .managed_allowed_domains_only = config.sectionBoolValue(payload, section, "managed_allowed_domains_only"),
        .allow_local_binding = config.sectionBoolValue(payload, section, "allow_local_binding"),
    };
    errdefer network.deinit(allocator);

    network.domains = try parseNetworkDomainRequirements(allocator, payload);
    network.unix_sockets = try parseNetworkUnixSocketRequirements(allocator, payload);

    if (network.isEmpty()) return null;
    return network;
}

fn parseNetworkDomainRequirements(allocator: std.mem.Allocator, payload: []const u8) !?NetworkPermissionEntryList {
    var canonical = try parseNetworkPermissionSection(allocator, payload, "experimental_network.domains", .domain);
    errdefer if (canonical) |*value| value.deinit(allocator);

    var allowed_domains = try config.sectionStringArrayValue(allocator, payload, "experimental_network", "allowed_domains");
    defer if (allowed_domains) |*value| value.deinit(allocator);
    var denied_domains = try config.sectionStringArrayValue(allocator, payload, "experimental_network", "denied_domains");
    defer if (denied_domains) |*value| value.deinit(allocator);

    if (canonical != null and (allowed_domains != null or denied_domains != null)) {
        return error.InvalidNetworkRequirement;
    }
    if (canonical) |value| return value;

    var entries = std.ArrayList(NetworkPermissionEntry).empty;
    errdefer {
        deinitNetworkPermissionEntries(allocator, entries.items);
        entries.deinit(allocator);
    }
    if (allowed_domains) |list| {
        for (list.items) |domain| try putNetworkPermissionEntryFromParts(allocator, &entries, domain, "allow");
    }
    if (denied_domains) |list| {
        for (list.items) |domain| try putNetworkPermissionEntryFromParts(allocator, &entries, domain, "deny");
    }
    if (entries.items.len == 0) {
        entries.deinit(allocator);
        return null;
    }
    const items = try entries.toOwnedSlice(allocator);
    std.mem.sort(NetworkPermissionEntry, items, {}, networkPermissionEntryLessThan);
    return .{ .items = items };
}

fn parseNetworkUnixSocketRequirements(allocator: std.mem.Allocator, payload: []const u8) !?NetworkPermissionEntryList {
    var canonical = try parseNetworkPermissionSection(allocator, payload, "experimental_network.unix_sockets", .unix_socket);
    errdefer if (canonical) |*value| value.deinit(allocator);

    var allow_unix_sockets = try config.sectionStringArrayValue(allocator, payload, "experimental_network", "allow_unix_sockets");
    defer if (allow_unix_sockets) |*value| value.deinit(allocator);

    if (canonical != null and allow_unix_sockets != null) {
        return error.InvalidNetworkRequirement;
    }
    if (canonical) |value| return value;

    var entries = std.ArrayList(NetworkPermissionEntry).empty;
    errdefer {
        deinitNetworkPermissionEntries(allocator, entries.items);
        entries.deinit(allocator);
    }
    if (allow_unix_sockets) |list| {
        for (list.items) |path| try putNetworkPermissionEntryFromParts(allocator, &entries, path, "allow");
    }
    if (entries.items.len == 0) {
        entries.deinit(allocator);
        return null;
    }
    const items = try entries.toOwnedSlice(allocator);
    std.mem.sort(NetworkPermissionEntry, items, {}, networkPermissionEntryLessThan);
    return .{ .items = items };
}

const NetworkPermissionKind = enum {
    domain,
    unix_socket,
};

fn parseNetworkPermissionSection(
    allocator: std.mem.Allocator,
    payload: []const u8,
    section_name: []const u8,
    kind: NetworkPermissionKind,
) !?NetworkPermissionEntryList {
    var entries = std.ArrayList(NetworkPermissionEntry).empty;
    errdefer {
        deinitNetworkPermissionEntries(allocator, entries.items);
        entries.deinit(allocator);
    }

    var in_section = false;
    var iter = std.mem.splitScalar(u8, payload, '\n');
    while (iter.next()) |line_raw| {
        const line = std.mem.trim(u8, line_raw, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (line[0] == '[') {
            in_section = isExactTomlSection(line, section_name);
            continue;
        }
        if (!in_section) continue;
        if (try parseNetworkPermissionLine(allocator, line, kind)) |entry| {
            var owned_entry = entry;
            errdefer deinitNetworkPermissionEntry(allocator, owned_entry);
            try putOwnedNetworkPermissionEntry(allocator, &entries, &owned_entry);
        }
    }

    if (entries.items.len == 0) {
        entries.deinit(allocator);
        return null;
    }
    const items = try entries.toOwnedSlice(allocator);
    std.mem.sort(NetworkPermissionEntry, items, {}, networkPermissionEntryLessThan);
    return .{ .items = items };
}

fn parseNetworkPermissionLine(
    allocator: std.mem.Allocator,
    line: []const u8,
    kind: NetworkPermissionKind,
) !?NetworkPermissionEntry {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return null;
    const raw_key = std.mem.trim(u8, line[0..eq], " \t");
    const raw_value = std.mem.trim(u8, line[eq + 1 ..], " \t");
    if (raw_key.len == 0) return error.InvalidNetworkRequirement;

    const value = try config.parseTomlString(allocator, raw_value) orelse return error.InvalidNetworkRequirement;
    errdefer allocator.free(value);
    try validateNetworkPermission(value, kind);

    const key = parseTomlKeyName(allocator, raw_key) catch |err| switch (err) {
        error.InvalidFeatureRequirement, error.InvalidTomlString => return error.InvalidNetworkRequirement,
        else => return err,
    };
    errdefer allocator.free(key);
    return .{ .key = key, .value = value };
}

fn validateNetworkPermission(value: []const u8, kind: NetworkPermissionKind) !void {
    switch (kind) {
        .domain => {
            if (std.mem.eql(u8, value, "allow") or std.mem.eql(u8, value, "deny")) return;
        },
        .unix_socket => {
            if (std.mem.eql(u8, value, "allow") or std.mem.eql(u8, value, "none")) return;
        },
    }
    return error.InvalidNetworkRequirement;
}

fn putNetworkPermissionEntryFromParts(
    allocator: std.mem.Allocator,
    entries: *std.ArrayList(NetworkPermissionEntry),
    key: []const u8,
    value: []const u8,
) !void {
    var entry = NetworkPermissionEntry{
        .key = try allocator.dupe(u8, key),
        .value = try allocator.dupe(u8, value),
    };
    errdefer deinitNetworkPermissionEntry(allocator, entry);
    try putOwnedNetworkPermissionEntry(allocator, entries, &entry);
}

fn putOwnedNetworkPermissionEntry(
    allocator: std.mem.Allocator,
    entries: *std.ArrayList(NetworkPermissionEntry),
    entry: *NetworkPermissionEntry,
) !void {
    for (entries.items) |*existing| {
        if (std.mem.eql(u8, existing.key, entry.key)) {
            deinitNetworkPermissionEntry(allocator, existing.*);
            existing.* = entry.*;
            entry.* = .{ .key = &.{}, .value = &.{} };
            return;
        }
    }
    try entries.append(allocator, entry.*);
    entry.* = .{ .key = &.{}, .value = &.{} };
}

fn deinitNetworkPermissionEntry(allocator: std.mem.Allocator, entry: NetworkPermissionEntry) void {
    if (entry.key.len > 0) allocator.free(entry.key);
    if (entry.value.len > 0) allocator.free(entry.value);
}

fn deinitNetworkPermissionEntries(allocator: std.mem.Allocator, entries: []NetworkPermissionEntry) void {
    for (entries) |entry| deinitNetworkPermissionEntry(allocator, entry);
}

fn networkPermissionEntryLessThan(_: void, lhs: NetworkPermissionEntry, rhs: NetworkPermissionEntry) bool {
    return std.mem.lessThan(u8, lhs.key, rhs.key);
}

fn sectionU16Value(bytes: []const u8, section_name: []const u8, key: []const u8) !?u16 {
    var in_section = false;
    var iter = std.mem.splitScalar(u8, bytes, '\n');
    while (iter.next()) |line_raw| {
        const line = std.mem.trim(u8, line_raw, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (line[0] == '[') {
            in_section = isExactTomlSection(line, section_name);
            continue;
        }
        if (!in_section) continue;
        if (tomlValueForKey(line, key)) |value| {
            return std.fmt.parseUnsigned(u16, value, 10) catch error.InvalidNetworkRequirement;
        }
    }
    return null;
}

fn tomlValueForKey(line: []const u8, key: []const u8) ?[]const u8 {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return null;
    const lhs = std.mem.trim(u8, line[0..eq], " \t");
    if (!std.mem.eql(u8, lhs, key)) return null;
    return std.mem.trim(u8, line[eq + 1 ..], " \t");
}

fn stringListFromLabels(allocator: std.mem.Allocator, labels: []const []const u8) !config.StringList {
    const items = try allocator.alloc([]const u8, labels.len);
    var copied: usize = 0;
    errdefer {
        for (items[0..copied]) |item| allocator.free(item);
        allocator.free(items);
    }
    for (labels, 0..) |label, index| {
        items[index] = try allocator.dupe(u8, label);
        copied += 1;
    }
    return .{ .items = items };
}

fn managedConfigPath(allocator: std.mem.Allocator) ![]const u8 {
    if (try env.getOwned(allocator, MANAGED_CONFIG_PATH_ENV_VAR)) |path| {
        if (path.len > 0) return path;
        allocator.free(path);
    }
    if (builtin.os.tag == .windows) {
        const codex_home = try resolveCodexHome(allocator);
        defer allocator.free(codex_home);
        return std.fs.path.join(allocator, &.{ codex_home, "managed_config.toml" });
    }
    return allocator.dupe(u8, UNIX_MANAGED_CONFIG_SYSTEM_PATH);
}

fn systemRequirementsPath(allocator: std.mem.Allocator) ![]const u8 {
    if (try env.getOwned(allocator, SYSTEM_REQUIREMENTS_PATH_ENV_VAR)) |path| {
        if (path.len > 0) return path;
        allocator.free(path);
    }
    if (builtin.os.tag == .windows) {
        const codex_home = try resolveCodexHome(allocator);
        defer allocator.free(codex_home);
        return std.fs.path.join(allocator, &.{ codex_home, "requirements.toml" });
    }
    return allocator.dupe(u8, UNIX_SYSTEM_REQUIREMENTS_PATH);
}

fn systemConfigPath(allocator: std.mem.Allocator) ![]const u8 {
    if (try env.getOwned(allocator, SYSTEM_CONFIG_PATH_ENV_VAR)) |path| {
        if (path.len > 0) return path;
        allocator.free(path);
    }
    if (builtin.os.tag == .windows) {
        const codex_home = try resolveCodexHome(allocator);
        defer allocator.free(codex_home);
        return std.fs.path.join(allocator, &.{ codex_home, "config.toml" });
    }
    return allocator.dupe(u8, UNIX_SYSTEM_CONFIG_PATH);
}

fn renderConfigRequirementsReadResponse(allocator: std.mem.Allocator, requirements: ConfigRequirementsReadRequirements) ![]const u8 {
    if (requirements.isEmpty()) return allocator.dupe(u8, "{\"requirements\":null}");

    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"requirements\":{");
    var first = true;
    if (requirements.allowed_approval_policies) |approval_policies| {
        try appendJsonFieldName(allocator, &result, &first, "allowedApprovalPolicies");
        try appendJsonStringArray(allocator, &result, approval_policies.items);
    }
    if (requirements.allowed_approvals_reviewers) |approvals_reviewers| {
        try appendJsonFieldName(allocator, &result, &first, "allowedApprovalsReviewers");
        try appendJsonStringArray(allocator, &result, approvals_reviewers.items);
    }
    if (requirements.allowed_sandbox_modes) |sandbox_modes| {
        try appendJsonFieldName(allocator, &result, &first, "allowedSandboxModes");
        try appendJsonStringArray(allocator, &result, sandbox_modes.items);
    }
    if (requirements.allowed_web_search_modes) |web_search_modes| {
        try appendJsonFieldName(allocator, &result, &first, "allowedWebSearchModes");
        try appendJsonStringArray(allocator, &result, web_search_modes.items);
    }
    if (requirements.feature_requirements) |feature_requirements| {
        try appendJsonFieldName(allocator, &result, &first, "featureRequirements");
        try appendFeatureRequirementsObject(allocator, &result, feature_requirements);
    }
    if (requirements.hooks) |hooks| {
        try appendJsonFieldName(allocator, &result, &first, "hooks");
        try appendManagedHooksRequirementsObject(allocator, &result, hooks);
    }
    if (requirements.enforce_residency) |enforce_residency| {
        try appendJsonFieldName(allocator, &result, &first, "enforceResidency");
        try appendJsonString(allocator, &result, enforce_residency);
    }
    if (requirements.network) |network| {
        try appendJsonFieldName(allocator, &result, &first, "network");
        try appendNetworkRequirementsObject(allocator, &result, network);
    }
    try result.appendSlice(allocator, "}}");
    return result.toOwnedSlice(allocator);
}

fn appendFeatureRequirementsObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    feature_requirements: FeatureRequirementList,
) !void {
    try result.appendSlice(allocator, "{");
    for (feature_requirements.items, 0..) |entry, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try appendJsonString(allocator, result, entry.name);
        try result.appendSlice(allocator, ":");
        try result.appendSlice(allocator, if (entry.enabled) "true" else "false");
    }
    try result.appendSlice(allocator, "}");
}

fn appendManagedHooksRequirementsObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    hooks: config_requirements_hooks.ManagedHooksRequirements,
) !void {
    var first = true;
    try result.appendSlice(allocator, "{");
    if (hooks.managed_dir) |value| try appendJsonStringField(allocator, result, &first, "managedDir", value);
    if (hooks.windows_managed_dir) |value| try appendJsonStringField(allocator, result, &first, "windowsManagedDir", value);
    for (config_requirements_hooks.EVENT_ORDER) |event| {
        try appendJsonFieldName(allocator, result, &first, event.configLabel());
        try appendHookMatcherGroupsArray(allocator, result, hooks.events[event.index()]);
    }
    try result.appendSlice(allocator, "}");
}

fn appendHookMatcherGroupsArray(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    groups: config_requirements_hooks.MatcherGroupList,
) !void {
    try result.appendSlice(allocator, "[");
    for (groups.items, 0..) |group, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try appendHookMatcherGroupObject(allocator, result, group);
    }
    try result.appendSlice(allocator, "]");
}

fn appendHookMatcherGroupObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    group: config_requirements_hooks.MatcherGroup,
) !void {
    var first = true;
    try result.appendSlice(allocator, "{");
    if (group.matcher) |matcher| try appendJsonStringField(allocator, result, &first, "matcher", matcher);
    try appendJsonFieldName(allocator, result, &first, "hooks");
    try result.appendSlice(allocator, "[");
    for (group.hooks, 0..) |hook, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try appendHookHandlerObject(allocator, result, hook);
    }
    try result.appendSlice(allocator, "]}");
}

fn appendHookHandlerObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    hook: config_requirements_hooks.HookHandler,
) !void {
    var first = true;
    try result.appendSlice(allocator, "{");
    try appendJsonStringField(allocator, result, &first, "type", hook.kind.label());
    if (hook.kind == .command) {
        if (hook.command) |command| try appendJsonStringField(allocator, result, &first, "command", command);
        if (hook.timeout_sec) |timeout_sec| try appendJsonU64Field(allocator, result, &first, "timeoutSec", timeout_sec);
        try appendJsonBoolField(allocator, result, &first, "async", hook.async_handler);
        if (hook.status_message) |status_message| try appendJsonStringField(allocator, result, &first, "statusMessage", status_message);
    }
    try result.appendSlice(allocator, "}");
}

fn appendNetworkRequirementsObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    network: NetworkRequirements,
) !void {
    var first = true;
    try result.appendSlice(allocator, "{");
    if (network.enabled) |value| try appendJsonBoolField(allocator, result, &first, "enabled", value);
    if (network.http_port) |value| try appendJsonU16Field(allocator, result, &first, "httpPort", value);
    if (network.socks_port) |value| try appendJsonU16Field(allocator, result, &first, "socksPort", value);
    if (network.allow_upstream_proxy) |value| try appendJsonBoolField(allocator, result, &first, "allowUpstreamProxy", value);
    if (network.dangerously_allow_non_loopback_proxy) |value| try appendJsonBoolField(allocator, result, &first, "dangerouslyAllowNonLoopbackProxy", value);
    if (network.dangerously_allow_all_unix_sockets) |value| try appendJsonBoolField(allocator, result, &first, "dangerouslyAllowAllUnixSockets", value);
    if (network.domains) |domains| {
        try appendJsonFieldName(allocator, result, &first, "domains");
        try appendNetworkPermissionMap(allocator, result, domains);
    }
    if (network.managed_allowed_domains_only) |value| try appendJsonBoolField(allocator, result, &first, "managedAllowedDomainsOnly", value);
    if (network.domains) |domains| {
        if (hasNetworkPermissionEntries(domains, "allow")) {
            try appendJsonFieldName(allocator, result, &first, "allowedDomains");
            try appendNetworkPermissionKeysArray(allocator, result, domains, "allow");
        }
        if (hasNetworkPermissionEntries(domains, "deny")) {
            try appendJsonFieldName(allocator, result, &first, "deniedDomains");
            try appendNetworkPermissionKeysArray(allocator, result, domains, "deny");
        }
    }
    if (network.unix_sockets) |unix_sockets| {
        try appendJsonFieldName(allocator, result, &first, "unixSockets");
        try appendNetworkPermissionMap(allocator, result, unix_sockets);
        if (hasNetworkPermissionEntries(unix_sockets, "allow")) {
            try appendJsonFieldName(allocator, result, &first, "allowUnixSockets");
            try appendNetworkPermissionKeysArray(allocator, result, unix_sockets, "allow");
        }
    }
    if (network.allow_local_binding) |value| try appendJsonBoolField(allocator, result, &first, "allowLocalBinding", value);
    try result.appendSlice(allocator, "}");
}

fn appendNetworkPermissionMap(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    entries: NetworkPermissionEntryList,
) !void {
    try result.appendSlice(allocator, "{");
    for (entries.items, 0..) |entry, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try appendJsonString(allocator, result, entry.key);
        try result.appendSlice(allocator, ":");
        try appendJsonString(allocator, result, entry.value);
    }
    try result.appendSlice(allocator, "}");
}

fn hasNetworkPermissionEntries(entries: NetworkPermissionEntryList, permission: []const u8) bool {
    for (entries.items) |entry| {
        if (std.mem.eql(u8, entry.value, permission)) return true;
    }
    return false;
}

fn appendNetworkPermissionKeysArray(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    entries: NetworkPermissionEntryList,
    permission: []const u8,
) !void {
    var first = true;
    try result.appendSlice(allocator, "[");
    for (entries.items) |entry| {
        if (!std.mem.eql(u8, entry.value, permission)) continue;
        if (first) {
            first = false;
        } else {
            try result.appendSlice(allocator, ",");
        }
        try appendJsonString(allocator, result, entry.key);
    }
    try result.appendSlice(allocator, "]");
}

fn appendJsonU16Field(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    first: *bool,
    name: []const u8,
    value: u16,
) !void {
    try appendJsonFieldName(allocator, result, first, name);
    const value_json = try std.fmt.allocPrint(allocator, "{d}", .{value});
    defer allocator.free(value_json);
    try result.appendSlice(allocator, value_json);
}

fn appendJsonU64Field(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    first: *bool,
    name: []const u8,
    value: u64,
) !void {
    try appendJsonFieldName(allocator, result, first, name);
    const value_json = try std.fmt.allocPrint(allocator, "{d}", .{value});
    defer allocator.free(value_json);
    try result.appendSlice(allocator, value_json);
}

fn appendJsonMaybeI64Field(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    first: *bool,
    name: []const u8,
    value: ?i64,
) !void {
    try appendJsonFieldName(allocator, result, first, name);
    if (value) |number| {
        const value_json = try std.fmt.allocPrint(allocator, "{d}", .{number});
        defer allocator.free(value_json);
        try result.appendSlice(allocator, value_json);
    } else {
        try result.appendSlice(allocator, "null");
    }
}

const ConfigRawEdit = struct {
    key_path: []const u8,
    value: std.json.Value,
    merge_strategy: ConfigMergeStrategy,
};

const ConfigWriteEditsResult = struct {
    response: []const u8,
    wrote: bool,
};

const ConfigMergeStrategy = enum {
    replace,
    upsert,
};

fn handleConfigValueWrite(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "config/value/write params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "config/value/write params must be an object");

    const edit = parseConfigWriteEdit(params.object) catch |err| switch (err) {
        error.InvalidConfigKeyPathParam => return renderJsonRpcError(allocator, id_value, -32602, "keyPath must be a non-empty string"),
        error.MissingConfigWriteValue => return renderJsonRpcError(allocator, id_value, -32602, "value is required"),
        error.InvalidConfigMergeStrategy => return renderJsonRpcError(allocator, id_value, -32602, "mergeStrategy must be replace or upsert"),
    };

    const write_result = try handleConfigWriteEdits(allocator, id_value, params.object, &.{edit}, "config/value/write");
    return write_result.response;
}

fn handleConfigBatchWrite(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "config/batchWrite params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "config/batchWrite params must be an object");

    const edits_value = params.object.get("edits") orelse return renderJsonRpcError(allocator, id_value, -32602, "edits must be an array");
    if (edits_value != .array) return renderJsonRpcError(allocator, id_value, -32602, "edits must be an array");

    const reload_user_config = parseConfigReloadUserConfig(params.object) catch |err| switch (err) {
        error.InvalidConfigReloadUserConfig => return renderJsonRpcError(allocator, id_value, -32602, "reloadUserConfig must be a boolean or null"),
    };

    const edits = try allocator.alloc(ConfigRawEdit, edits_value.array.items.len);
    defer allocator.free(edits);

    for (edits_value.array.items, 0..) |edit_value, index| {
        if (edit_value != .object) return renderJsonRpcError(allocator, id_value, -32602, "edits entries must be objects");
        edits[index] = parseConfigWriteEdit(edit_value.object) catch |err| switch (err) {
            error.InvalidConfigKeyPathParam => return renderJsonRpcError(allocator, id_value, -32602, "edits entries must include a non-empty keyPath string"),
            error.MissingConfigWriteValue => return renderJsonRpcError(allocator, id_value, -32602, "edits entries must include value"),
            error.InvalidConfigMergeStrategy => return renderJsonRpcError(allocator, id_value, -32602, "edits entries must use mergeStrategy replace or upsert"),
        };
    }

    const write_result = try handleConfigWriteEdits(allocator, id_value, params.object, edits, "config/batchWrite");
    errdefer allocator.free(write_result.response);
    if (reload_user_config and write_result.wrote) try reloadLoadedThreadRuntimeConfig(allocator, state);
    return write_result.response;
}

fn parseConfigReloadUserConfig(object: std.json.ObjectMap) !bool {
    const value = object.get("reloadUserConfig") orelse return false;
    if (value == .null) return false;
    if (value != .bool) return error.InvalidConfigReloadUserConfig;
    return value.bool;
}

fn reloadLoadedThreadRuntimeConfig(allocator: std.mem.Allocator, state: *AppServerState) !void {
    if (state.loaded_threads.items.len == 0) return;

    var runtime_requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return,
    };
    defer runtime_requirements.deinit(allocator);

    for (state.loaded_threads.items) |*thread| {
        var cfg = loadConfigForLoadedThread(allocator, state, thread) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => continue,
        };
        defer cfg.deinit(allocator);
        applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, runtime_requirements) catch continue;
        if (thread.oss_provider) |provider| {
            replaceConfigOptionalString(allocator, &cfg.oss_provider, provider) catch |err| switch (err) {
                error.OutOfMemory => return err,
            };
            config.applyOssMode(&cfg, allocator, null, thread.runtime_overrides.model) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => continue,
            };
        }

        const model_provider = cfg.model_provider_id orelse "openai";

        if (!thread.runtime_overrides.model) {
            try replaceOwnedString(allocator, &thread.model, cfg.model);
        }
        if (!thread.runtime_overrides.model_context_window) {
            thread.model_context_window = cfg.model_context_window;
        }
        if (!thread.runtime_overrides.model_auto_compact_token_limit) {
            thread.model_auto_compact_token_limit = cfg.model_auto_compact_token_limit;
        }
        if (!thread.runtime_overrides.model_verbosity) {
            if (cfg.model_verbosity) |verbosity| {
                try replaceOptionalOwnedString(allocator, &thread.model_verbosity, verbosity.label());
            } else {
                clearOptionalOwnedString(allocator, &thread.model_verbosity);
            }
        }
        if (!thread.runtime_overrides.model_provider) {
            try replaceOwnedString(allocator, &thread.model_provider, model_provider);
            try thread.transcript.setModelProvider(allocator, model_provider);
        }
        if (!thread.runtime_overrides.service_tier) {
            if (cfg.service_tier) |value| {
                try replaceOptionalOwnedString(allocator, &thread.service_tier, value);
            } else {
                clearOptionalOwnedString(allocator, &thread.service_tier);
            }
        }
        if (!thread.runtime_overrides.approval_policy) {
            try replaceOwnedString(allocator, &thread.approval_policy, cfg.approval_policy.label());
        }
        if (!thread.runtime_overrides.approvals_reviewer) {
            try replaceOwnedString(allocator, &thread.approvals_reviewer, cfg.approvals_reviewer.label());
        }
        if (!thread.runtime_overrides.sandbox_mode) {
            try replaceOwnedString(allocator, &thread.sandbox_mode, cfg.sandbox_mode.label());
            var roots = try emptyStringList(allocator);
            var roots_moved = false;
            errdefer if (!roots_moved) roots.deinit(allocator);
            thread.sandbox_writable_roots.deinit(allocator);
            thread.sandbox_writable_roots = roots;
            roots_moved = true;
            var read_denied_roots = try emptyStringList(allocator);
            var read_denied_roots_moved = false;
            errdefer if (!read_denied_roots_moved) read_denied_roots.deinit(allocator);
            thread.sandbox_read_denied_roots.deinit(allocator);
            thread.sandbox_read_denied_roots = read_denied_roots;
            read_denied_roots_moved = true;
            var read_denied_globs = try emptyStringList(allocator);
            var read_denied_globs_moved = false;
            errdefer if (!read_denied_globs_moved) read_denied_globs.deinit(allocator);
            thread.sandbox_read_denied_globs.deinit(allocator);
            thread.sandbox_read_denied_globs = read_denied_globs;
            read_denied_globs_moved = true;
            thread.sandbox_include_cwd_write_root = true;
            thread.sandbox_network_enabled = defaultNetworkEnabledForSandboxMode(cfg.sandbox_mode);
            thread.sandbox_exclude_tmpdir_env_var = false;
            thread.sandbox_exclude_slash_tmp = false;
            thread.sandbox_external = false;
        }
        if (!thread.runtime_overrides.web_search_mode) {
            thread.web_search_mode = cfg.web_search_mode;
        }
        applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(allocator, thread, runtime_requirements) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => continue,
        };
        if (!thread.runtime_overrides.reasoning_effort) {
            if (cfg.model_reasoning_effort) |effort| {
                try replaceOptionalOwnedString(allocator, &thread.reasoning_effort, effort.label());
            } else {
                clearOptionalOwnedString(allocator, &thread.reasoning_effort);
            }
        }
        if (!thread.runtime_overrides.reasoning_summary) {
            if (cfg.model_reasoning_summary) |summary| {
                try replaceOptionalOwnedString(allocator, &thread.reasoning_summary, summary.label());
            } else {
                clearOptionalOwnedString(allocator, &thread.reasoning_summary);
            }
        }
        if (!thread.runtime_overrides.personality) {
            if (cfg.personality) |personality| {
                try replaceOptionalOwnedString(allocator, &thread.personality, personality.label());
            } else {
                clearOptionalOwnedString(allocator, &thread.personality);
            }
        }
        thread.updated_at = currentUnixSeconds();
    }
}

fn parseConfigWriteEdit(object: std.json.ObjectMap) !ConfigRawEdit {
    const key_path_value = object.get("keyPath") orelse return error.InvalidConfigKeyPathParam;
    if (key_path_value != .string or key_path_value.string.len == 0) return error.InvalidConfigKeyPathParam;

    const value = object.get("value") orelse return error.MissingConfigWriteValue;

    const merge_strategy_value = object.get("mergeStrategy") orelse return error.InvalidConfigMergeStrategy;
    if (merge_strategy_value != .string) return error.InvalidConfigMergeStrategy;
    if (!std.mem.eql(u8, merge_strategy_value.string, "replace") and !std.mem.eql(u8, merge_strategy_value.string, "upsert")) {
        return error.InvalidConfigMergeStrategy;
    }

    return .{
        .key_path = key_path_value.string,
        .value = value,
        .merge_strategy = if (std.mem.eql(u8, merge_strategy_value.string, "replace")) .replace else .upsert,
    };
}

fn handleConfigWriteEdits(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    params: std.json.ObjectMap,
    edits: []const ConfigRawEdit,
    method_name: []const u8,
) !ConfigWriteEditsResult {
    const expected_version = switch (optionalStringOrNull(params, "expectedVersion")) {
        .value => |string| string,
        .missing => null,
        .invalid => return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, "expectedVersion must be a string or null"), .wrote = false },
    };

    const config_path = resolveConfigWritePath(allocator, params.get("filePath")) catch |err| switch (err) {
        error.InvalidConfigWritePath => return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, "filePath must be a non-empty string or null"), .wrote = false },
        error.ConfigWritePathReadonly => return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, "Only writes to the user config are allowed"), .wrote = false },
        else => return err,
    };
    defer allocator.free(config_path);

    const current_bytes = config.readConfigTomlFile(allocator, config_path) catch |err| {
        const message = try std.fmt.allocPrint(allocator, "{s} failed to read config", .{method_name});
        defer allocator.free(message);
        return .{ .response = try renderJsonRpcErrorForFailure(allocator, id_value, message, err), .wrote = false };
    };
    defer if (current_bytes) |bytes| allocator.free(bytes);

    if (expected_version) |expected| {
        const current_version = try configVersionAlloc(allocator, current_bytes orelse "");
        defer allocator.free(current_version);
        if (!std.mem.eql(u8, current_version, expected)) {
            return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, "config version conflict"), .wrote = false };
        }
    }

    var updated: []const u8 = try allocator.dupe(u8, current_bytes orelse "");
    defer allocator.free(updated);

    for (edits) |edit| {
        const next = applyConfigWriteEdit(allocator, updated, edit) catch |err| switch (err) {
            error.UnsupportedConfigWriteValue => return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, "value must be a TOML-compatible value"), .wrote = false },
            error.InvalidConfigKeyPath => return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, "keyPath must be a supported TOML key path"), .wrote = false },
            else => return err,
        };
        allocator.free(updated);
        updated = next;
    }

    var requirements = loadSystemConfigRequirements(allocator) catch |err| {
        const message = try std.fmt.allocPrint(allocator, "{s} failed to load config requirements", .{method_name});
        defer allocator.free(message);
        return .{ .response = try renderJsonRpcErrorForFailure(allocator, id_value, message, err), .wrote = false };
    };
    defer requirements.deinit(allocator);
    if (try configWriteFeatureRequirementConflictMessage(allocator, updated, requirements.feature_requirements)) |message| {
        defer allocator.free(message);
        const full_message = try std.fmt.allocPrint(allocator, "Invalid configuration: {s}", .{message});
        defer allocator.free(full_message);
        return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, full_message), .wrote = false };
    }
    const scalar_conflict = configWriteScalarRequirementConflictMessage(allocator, updated, requirements) catch |err| switch (err) {
        error.InvalidApprovalPolicy,
        error.InvalidApprovalsReviewer,
        error.InvalidSandboxMode,
        error.InvalidWebSearchMode,
        error.InvalidConfigWriteScalarType,
        => {
            const message = try std.fmt.allocPrint(allocator, "Invalid configuration: {s}", .{@errorName(err)});
            defer allocator.free(message);
            return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, message), .wrote = false };
        },
        else => return err,
    };
    if (scalar_conflict) |message| {
        defer allocator.free(message);
        const full_message = try std.fmt.allocPrint(allocator, "Invalid configuration: {s}", .{message});
        defer allocator.free(full_message);
        return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, full_message), .wrote = false };
    }

    var managed_layer = loadConfigReadManagedLayer(allocator) catch |err| {
        const message = try std.fmt.allocPrint(allocator, "{s} failed to read managed config", .{method_name});
        defer allocator.free(message);
        return .{ .response = try renderJsonRpcErrorForFailure(allocator, id_value, message, err), .wrote = false };
    };
    defer if (managed_layer) |*layer| layer.deinit(allocator);

    const overridden_metadata = if (managed_layer) |layer|
        renderFirstManagedConfigWriteOverrideMetadata(allocator, layer, edits, updated) catch |err| switch (err) {
            error.InvalidApprovalPolicy,
            error.InvalidApprovalsReviewer,
            error.InvalidSandboxMode,
            error.InvalidWebSearchMode,
            error.InvalidReasoningEffort,
            error.InvalidVerbosity,
            error.InvalidForcedLoginMethod,
            error.InvalidConfigWriteScalarType,
            error.InvalidTomlInteger,
            => {
                const message = try std.fmt.allocPrint(allocator, "Invalid configuration: {s}", .{@errorName(err)});
                defer allocator.free(message);
                return .{ .response = try renderJsonRpcError(allocator, id_value, -32602, message), .wrote = false };
            },
            else => return err,
        }
    else
        null;
    defer if (overridden_metadata) |metadata| allocator.free(metadata);

    config.writeConfigTomlFile(config_path, updated) catch |err| {
        const message = try std.fmt.allocPrint(allocator, "{s} failed to write config", .{method_name});
        defer allocator.free(message);
        return .{ .response = try renderJsonRpcErrorForFailure(allocator, id_value, message, err), .wrote = false };
    };

    const version = try configVersionAlloc(allocator, updated);
    defer allocator.free(version);
    const result = try renderConfigWriteResponse(allocator, config_path, version, overridden_metadata);
    defer allocator.free(result);
    return .{ .response = try renderJsonRpcResult(allocator, id_value, result), .wrote = true };
}

fn configWriteFeatureRequirementConflictMessage(
    allocator: std.mem.Allocator,
    bytes: []const u8,
    feature_requirements: ?FeatureRequirementList,
) !?[]const u8 {
    const requirements = feature_requirements orelse return null;
    var current_scope: ConfigWriteTomlScope = .top_level;
    var multiline_string: ?TomlMultilineStringKind = null;

    var start: usize = 0;
    while (start < bytes.len) {
        const end = std.mem.indexOfScalarPos(u8, bytes, start, '\n') orelse bytes.len;
        const line_raw = bytes[start..end];
        start = if (end < bytes.len) end + 1 else bytes.len;

        if (tomlLineIsMultilineStringBody(&multiline_string, line_raw)) continue;
        const line_without_comment = stripTomlLineComment(line_raw);
        const line = std.mem.trim(u8, line_without_comment, " \t\r");
        if (line.len == 0) continue;
        if (line[0] == '[') {
            current_scope = if (configWriteTomlSectionPath(line)) |section|
                ConfigWriteTomlScope{ .table = section }
            else
                .ignored;
            continue;
        }
        defer observeTomlMultilineStringOpen(&multiline_string, line_without_comment);

        const eq = tomlAssignmentEqualsIndex(line) orelse continue;
        const lhs = std.mem.trim(u8, line[0..eq], " \t");
        const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
        const current_section: ?[]const u8 = switch (current_scope) {
            .top_level => null,
            .table => current_scope.table,
            .ignored => continue,
        };

        var path = (configWriteAssignmentPath(allocator, current_section, lhs) catch |err| switch (err) {
            error.InvalidConfigReadProfileDottedKey, error.InvalidConfigReadAppSection, error.InvalidTomlString => continue,
            else => return err,
        }) orelse continue;
        defer path.deinit(allocator);
        if (parseTomlBoolLiteral(rhs)) |enabled| {
            if (try configWriteFeatureRequirementConflictForPathItems(allocator, requirements, path.items, enabled)) |message| return message;
        } else if (rhs.len > 0 and rhs[0] == '{' and configWritePathMayContainFeatureRequirement(path.items)) {
            var path_stack = std.ArrayList([]const u8).empty;
            defer path_stack.deinit(allocator);
            try path_stack.appendSlice(allocator, path.items);
            if (try configWriteInlineTableFeatureRequirementConflictMessage(allocator, requirements, &path_stack, rhs)) |message| return message;
        }
    }
    return null;
}

const ConfigWriteTomlScope = union(enum) {
    top_level,
    table: []const u8,
    ignored,
};

fn configWriteTomlSectionPath(line: []const u8) ?[]const u8 {
    if (line.len < "[]".len or line[0] != '[' or line[line.len - 1] != ']') return null;
    if (line.len >= "[[]]".len and line[1] == '[') return null;
    return std.mem.trim(u8, line[1 .. line.len - 1], " \t");
}

fn parseTomlBoolLiteral(raw: []const u8) ?bool {
    if (std.mem.eql(u8, raw, "true")) return true;
    if (std.mem.eql(u8, raw, "false")) return false;
    return null;
}

fn tomlAssignmentEqualsIndex(line: []const u8) ?usize {
    var quote: u8 = 0;
    var escaped = false;
    for (line, 0..) |byte, index| {
        if (quote != 0) {
            if (quote == '"' and escaped) {
                escaped = false;
            } else if (quote == '"' and byte == '\\') {
                escaped = true;
            } else if (byte == quote) {
                quote = 0;
            }
            continue;
        }
        if (byte == '"' or byte == '\'') {
            quote = byte;
            continue;
        }
        if (byte == '=') return index;
    }
    return null;
}

fn configWriteAssignmentPath(
    allocator: std.mem.Allocator,
    current_section: ?[]const u8,
    lhs: []const u8,
) !?ConfigReadTomlPath {
    var lhs_path = (try parseConfigReadTomlDottedPath(allocator, lhs)) orelse return null;
    errdefer lhs_path.deinit(allocator);

    const section = current_section orelse return lhs_path;
    var section_path = (try parseConfigReadTomlDottedPath(allocator, section)) orelse return lhs_path;
    errdefer section_path.deinit(allocator);

    const items = try allocator.alloc([]const u8, section_path.items.len + lhs_path.items.len);
    @memcpy(items[0..section_path.items.len], section_path.items);
    @memcpy(items[section_path.items.len..], lhs_path.items);
    allocator.free(section_path.items);
    allocator.free(lhs_path.items);
    section_path.items = &.{};
    lhs_path.items = &.{};
    return .{ .items = items };
}

fn configWriteInlineTableFeatureRequirementConflictMessage(
    allocator: std.mem.Allocator,
    requirements: FeatureRequirementList,
    path_stack: *std.ArrayList([]const u8),
    raw_table: []const u8,
) !?[]const u8 {
    const body = configReadInlineTableBody(raw_table) catch |err| switch (err) {
        error.InvalidConfigReadInlineTable => return null,
    };
    var field_start: usize = 0;
    while (nextConfigReadInlineTableField(body, &field_start) catch |err| switch (err) {
        error.InvalidConfigReadInlineTable => return null,
    }) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = tomlAssignmentEqualsIndex(field) orelse continue;
        const key = (parseConfigReadInlineFieldKey(allocator, field[0..eq]) catch |err| switch (err) {
            error.InvalidConfigReadAppSection, error.InvalidTomlString => continue,
            else => return err,
        }) orelse continue;
        defer allocator.free(key);
        try path_stack.append(allocator, key);
        defer _ = path_stack.pop();

        const rhs = std.mem.trim(u8, field[eq + 1 ..], " \t\r\n");
        if (parseTomlBoolLiteral(rhs)) |enabled| {
            if (try configWriteFeatureRequirementConflictForPathItems(allocator, requirements, path_stack.items, enabled)) |message| return message;
        } else if (rhs.len > 0 and rhs[0] == '{' and configWritePathMayContainFeatureRequirement(path_stack.items)) {
            if (try configWriteInlineTableFeatureRequirementConflictMessage(allocator, requirements, path_stack, rhs)) |message| return message;
        }
    }
    return null;
}

fn configWritePathMayContainFeatureRequirement(path_items: []const []const u8) bool {
    if (path_items.len == 0) return false;
    if (std.mem.eql(u8, path_items[0], "features")) return path_items.len == 1;
    if (!std.mem.eql(u8, path_items[0], "profiles")) return false;
    if (path_items.len <= 2) return true;
    return path_items.len == 3 and std.mem.eql(u8, path_items[2], "features");
}

fn configWriteFeatureRequirementConflictForPathItems(
    allocator: std.mem.Allocator,
    requirements: FeatureRequirementList,
    path_items: []const []const u8,
    enabled: bool,
) !?[]const u8 {
    const feature_key = if (path_items.len == 2 and std.mem.eql(u8, path_items[0], "features"))
        path_items[1]
    else if (path_items.len == 4 and std.mem.eql(u8, path_items[0], "profiles") and std.mem.eql(u8, path_items[2], "features"))
        path_items[3]
    else
        return null;

    const canonical_key = canonicalFeatureRequirementKey(feature_key) orelse return null;
    const required = featureRequirementValue(requirements, canonical_key) orelse return null;
    if (required == enabled) return null;

    const key_path = try configWriteJoinPath(allocator, path_items);
    defer allocator.free(key_path);
    const message = try std.fmt.allocPrint(
        allocator,
        "invalid value for `features`: `{s}={s}` is disallowed by requirements",
        .{ key_path, if (enabled) "true" else "false" },
    );
    return @as(?[]const u8, message);
}

const ConfigWriteScalarRequirementKind = enum {
    approval_policy,
    approvals_reviewer,
    sandbox_mode,
    web_search,

    fn key(self: ConfigWriteScalarRequirementKind) []const u8 {
        return switch (self) {
            .approval_policy => "approval_policy",
            .approvals_reviewer => "approvals_reviewer",
            .sandbox_mode => "sandbox_mode",
            .web_search => "web_search",
        };
    }
};

fn configWriteScalarRequirementConflictMessage(
    allocator: std.mem.Allocator,
    bytes: []const u8,
    requirements: ConfigRequirementsReadRequirements,
) !?[]const u8 {
    if (requirements.allowed_approval_policies == null and
        requirements.allowed_approvals_reviewers == null and
        requirements.allowed_sandbox_modes == null and
        requirements.allowed_web_search_modes == null)
    {
        return null;
    }

    var current_scope: ConfigWriteTomlScope = .top_level;
    var multiline_string: ?TomlMultilineStringKind = null;

    var start: usize = 0;
    while (start < bytes.len) {
        const end = std.mem.indexOfScalarPos(u8, bytes, start, '\n') orelse bytes.len;
        const line_raw = bytes[start..end];
        start = if (end < bytes.len) end + 1 else bytes.len;

        if (tomlLineIsMultilineStringBody(&multiline_string, line_raw)) continue;
        const line_without_comment = stripTomlLineComment(line_raw);
        const line = std.mem.trim(u8, line_without_comment, " \t\r");
        if (line.len == 0) continue;
        if (line[0] == '[') {
            current_scope = if (configWriteTomlSectionPath(line)) |section|
                ConfigWriteTomlScope{ .table = section }
            else
                .ignored;
            continue;
        }
        defer observeTomlMultilineStringOpen(&multiline_string, line_without_comment);

        const eq = tomlAssignmentEqualsIndex(line) orelse continue;
        const lhs = std.mem.trim(u8, line[0..eq], " \t");
        const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
        const current_section: ?[]const u8 = switch (current_scope) {
            .top_level => null,
            .table => current_scope.table,
            .ignored => continue,
        };

        var path = (configWriteAssignmentPath(allocator, current_section, lhs) catch |err| switch (err) {
            error.InvalidConfigReadProfileDottedKey, error.InvalidConfigReadAppSection, error.InvalidTomlString => continue,
            else => return err,
        }) orelse continue;
        defer path.deinit(allocator);

        if (try configWriteScalarRequirementConflictForPathItems(allocator, requirements, path.items, rhs)) |message| return message;
        if (rhs.len > 0 and rhs[0] == '{' and configWritePathMayContainScalarRequirement(path.items)) {
            var path_stack = std.ArrayList([]const u8).empty;
            defer path_stack.deinit(allocator);
            try path_stack.appendSlice(allocator, path.items);
            if (try configWriteInlineTableScalarRequirementConflictMessage(allocator, requirements, &path_stack, rhs)) |message| return message;
        }
    }
    return null;
}

fn configWriteInlineTableScalarRequirementConflictMessage(
    allocator: std.mem.Allocator,
    requirements: ConfigRequirementsReadRequirements,
    path_stack: *std.ArrayList([]const u8),
    raw_table: []const u8,
) !?[]const u8 {
    const body = configReadInlineTableBody(raw_table) catch |err| switch (err) {
        error.InvalidConfigReadInlineTable => return null,
    };
    var field_start: usize = 0;
    while (nextConfigReadInlineTableField(body, &field_start) catch |err| switch (err) {
        error.InvalidConfigReadInlineTable => return null,
    }) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = tomlAssignmentEqualsIndex(field) orelse continue;
        const key = (parseConfigReadInlineFieldKey(allocator, field[0..eq]) catch |err| switch (err) {
            error.InvalidConfigReadAppSection, error.InvalidTomlString => continue,
            else => return err,
        }) orelse continue;
        defer allocator.free(key);
        try path_stack.append(allocator, key);
        defer _ = path_stack.pop();

        const rhs = std.mem.trim(u8, field[eq + 1 ..], " \t\r\n");
        if (try configWriteScalarRequirementConflictForPathItems(allocator, requirements, path_stack.items, rhs)) |message| return message;
        if (rhs.len > 0 and rhs[0] == '{' and configWritePathMayContainScalarRequirement(path_stack.items)) {
            if (try configWriteInlineTableScalarRequirementConflictMessage(allocator, requirements, path_stack, rhs)) |message| return message;
        }
    }
    return null;
}

fn configWritePathMayContainScalarRequirement(path_items: []const []const u8) bool {
    if (path_items.len == 0) return false;
    return std.mem.eql(u8, path_items[0], "profiles") and path_items.len <= 2;
}

fn configWriteScalarRequirementConflictForPathItems(
    allocator: std.mem.Allocator,
    requirements: ConfigRequirementsReadRequirements,
    path_items: []const []const u8,
    raw_value: []const u8,
) !?[]const u8 {
    const kind = configWriteScalarRequirementKindForPathItems(path_items) orelse return null;
    const allowed = configWriteAllowedScalarRequirementList(requirements, kind) orelse return null;

    const label = try configWriteScalarRequirementValueLabel(allocator, kind, raw_value);
    defer allocator.free(label);
    if (configReadRequirementListContains(allowed, label)) return null;

    const key_path = try configWriteJoinPath(allocator, path_items);
    defer allocator.free(key_path);
    return @as(?[]const u8, try std.fmt.allocPrint(
        allocator,
        "invalid value for `{s}`: `{s}=\"{s}\"` is disallowed by requirements",
        .{ kind.key(), key_path, label },
    ));
}

fn configWriteScalarRequirementKindForPathItems(path_items: []const []const u8) ?ConfigWriteScalarRequirementKind {
    const key = if (path_items.len == 1)
        path_items[0]
    else if (path_items.len == 3 and std.mem.eql(u8, path_items[0], "profiles"))
        path_items[2]
    else
        return null;
    if (std.mem.eql(u8, key, "approval_policy")) return .approval_policy;
    if (std.mem.eql(u8, key, "approvals_reviewer")) return .approvals_reviewer;
    if (std.mem.eql(u8, key, "sandbox_mode")) return .sandbox_mode;
    if (std.mem.eql(u8, key, "web_search")) return .web_search;
    return null;
}

fn configWriteAllowedScalarRequirementList(
    requirements: ConfigRequirementsReadRequirements,
    kind: ConfigWriteScalarRequirementKind,
) ?config.StringList {
    return switch (kind) {
        .approval_policy => requirements.allowed_approval_policies,
        .approvals_reviewer => requirements.allowed_approvals_reviewers,
        .sandbox_mode => requirements.allowed_sandbox_modes,
        .web_search => requirements.allowed_web_search_modes,
    };
}

fn configWriteScalarRequirementValueLabel(
    allocator: std.mem.Allocator,
    kind: ConfigWriteScalarRequirementKind,
    raw_value: []const u8,
) ![]const u8 {
    const value = configReadStringValue(allocator, raw_value) catch |err| switch (err) {
        error.InvalidConfigReadString, error.InvalidTomlString => return error.InvalidConfigWriteScalarType,
        else => return err,
    };
    defer allocator.free(value);
    const label = switch (kind) {
        .approval_policy => (try config.ApprovalPolicy.parse(value)).label(),
        .approvals_reviewer => (try config.ApprovalsReviewer.parse(value)).label(),
        .sandbox_mode => (try config.SandboxMode.parse(value)).label(),
        .web_search => (try config.WebSearchMode.parse(value)).label(),
    };
    return allocator.dupe(u8, label);
}

fn configWriteJoinPath(allocator: std.mem.Allocator, path_items: []const []const u8) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);
    for (path_items, 0..) |item, index| {
        if (index > 0) try result.append(allocator, '.');
        try result.appendSlice(allocator, item);
    }
    return result.toOwnedSlice(allocator);
}

fn applyConfigWriteEdit(allocator: std.mem.Allocator, bytes: []const u8, edit: ConfigRawEdit) ![]const u8 {
    if (edit.value == .null) {
        return config.removeTomlValueForKeyPath(allocator, bytes, edit.key_path);
    }

    if (edit.value == .object and try shouldApplyConfigTableObjectWrite(bytes, edit.key_path, edit.value.object)) {
        return applyConfigTableObjectWrite(allocator, bytes, edit);
    }

    const raw_value = renderTomlValue(allocator, edit.value) catch |err| switch (err) {
        error.UnsupportedConfigWriteValue => return error.UnsupportedConfigWriteValue,
        else => return err,
    };
    defer allocator.free(raw_value);

    return config.updateTomlRawValueForKeyPath(allocator, bytes, edit.key_path, raw_value);
}

const ConfigObjectLeafWrite = struct {
    key_path: []const u8,
    raw_value: []const u8,

    fn deinit(self: ConfigObjectLeafWrite, allocator: std.mem.Allocator) void {
        allocator.free(self.key_path);
        allocator.free(self.raw_value);
    }
};

fn applyConfigTableObjectWrite(
    allocator: std.mem.Allocator,
    bytes: []const u8,
    edit: ConfigRawEdit,
) ![]const u8 {
    var writes = std.ArrayList(ConfigObjectLeafWrite).empty;
    defer {
        for (writes.items) |item| item.deinit(allocator);
        writes.deinit(allocator);
    }
    try collectConfigObjectLeafWrites(allocator, &writes, edit.key_path, edit.value.object);

    var updated = if (edit.merge_strategy == .replace)
        try config.removeTomlTableForKeyPath(allocator, bytes, edit.key_path)
    else
        try allocator.dupe(u8, bytes);
    errdefer allocator.free(updated);

    for (writes.items) |write| {
        const next = try config.updateTomlRawValueForKeyPath(allocator, updated, write.key_path, write.raw_value);
        allocator.free(updated);
        updated = next;
    }
    return updated;
}

fn shouldApplyConfigTableObjectWrite(
    bytes: []const u8,
    key_path: []const u8,
    object: std.json.ObjectMap,
) !bool {
    if (std.mem.eql(u8, key_path, "hooks.state")) return false;
    if (!configObjectKeysAreBare(object)) return false;
    return std.mem.startsWith(u8, key_path, "mcp_servers.") or
        std.mem.startsWith(u8, key_path, "model_providers.") or
        try config.tomlHasSectionForKeyPath(bytes, key_path);
}

fn configObjectKeysAreBare(object: std.json.ObjectMap) bool {
    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        if (!isBareTomlKeySegment(entry.key_ptr.*)) return false;
        if (entry.value_ptr.* == .object and !configObjectKeysAreBare(entry.value_ptr.*.object)) return false;
    }
    return true;
}

fn isBareTomlKeySegment(value: []const u8) bool {
    if (value.len == 0) return false;
    for (value) |byte| {
        if (std.ascii.isAlphanumeric(byte) or byte == '_' or byte == '-') continue;
        return false;
    }
    return true;
}

fn collectConfigObjectLeafWrites(
    allocator: std.mem.Allocator,
    writes: *std.ArrayList(ConfigObjectLeafWrite),
    prefix: []const u8,
    object: std.json.ObjectMap,
) !void {
    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        const child_key_path = try std.fmt.allocPrint(allocator, "{s}.{s}", .{ prefix, entry.key_ptr.* });
        errdefer allocator.free(child_key_path);

        if (entry.value_ptr.* == .object and configObjectHasEntries(entry.value_ptr.*.object)) {
            try collectConfigObjectLeafWrites(allocator, writes, child_key_path, entry.value_ptr.*.object);
            allocator.free(child_key_path);
            continue;
        }

        const raw_value = renderTomlValue(allocator, entry.value_ptr.*) catch |err| switch (err) {
            error.UnsupportedConfigWriteValue => return error.UnsupportedConfigWriteValue,
            else => return err,
        };
        errdefer allocator.free(raw_value);
        try writes.append(allocator, .{ .key_path = child_key_path, .raw_value = raw_value });
    }
}

fn configObjectHasEntries(object: std.json.ObjectMap) bool {
    var iterator = object.iterator();
    return iterator.next() != null;
}

fn handleConfigRead(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = switch (optionalConfigReadParams(params_value)) {
        .object => |object| object,
        .empty => null,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };

    var include_layers = false;
    var cwd: ?[]const u8 = null;
    if (params) |object| {
        if (object.get("includeLayers")) |value| {
            if (value != .bool) return renderJsonRpcError(allocator, id_value, -32602, "includeLayers must be a boolean");
            include_layers = value.bool;
        }
        if (object.get("cwd")) |value| {
            if (value != .null and value != .string) return renderJsonRpcError(allocator, id_value, -32602, "cwd must be a string or null");
            if (value == .string) {
                if (!std.fs.path.isAbsolute(value.string)) {
                    return renderJsonRpcError(allocator, id_value, -32602, "cwd must be an absolute path or null");
                }
                cwd = value.string;
            }
        }
    }

    var cfg = loadAppServerConfigWithOptions(allocator, state, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/read failed to load config", err);
    };
    defer cfg.deinit(allocator);
    var feature_overrides = features_cmd.loadFeatureOverridesForProfile(allocator, cfg.codex_home, cfg.active_profile) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/read failed to load feature config", err);
    };
    defer feature_overrides.deinit(allocator);

    const config_path = try config.configTomlPath(allocator, cfg.codex_home);
    defer allocator.free(config_path);
    const config_bytes = config.readConfigTomlFile(allocator, config_path) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/read failed to read user config", err);
    };
    defer if (config_bytes) |bytes| allocator.free(bytes);

    var user_layer = try loadConfigReadUserLayer(allocator, config_path, config_bytes orelse "", cfg.active_profile);
    defer user_layer.deinit(allocator);

    var managed_layer = loadConfigReadManagedLayer(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/read failed to read managed config", err);
    };
    defer if (managed_layer) |*layer| layer.deinit(allocator);

    var system_layer = loadConfigReadSystemLayer(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/read failed to read system config", err);
    };
    defer system_layer.deinit(allocator);

    var project_layers = loadConfigReadProjectLayers(allocator, cwd, cfg.codex_home, config_bytes) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/read failed to read project config", err);
    };
    defer project_layers.deinit(allocator);

    var requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/read failed to load config requirements", err);
    };
    defer requirements.deinit(allocator);

    const result = renderConfigReadResponse(allocator, cfg, state.cli_feature_overrides, feature_overrides, state.runtime_feature_enablement, requirements, include_layers, managed_layer, project_layers, user_layer, system_layer) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/read failed to render config", err);
    };
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn optionalConfigReadParams(params_value: ?std.json.Value) OptionalObjectParams {
    const params = params_value orelse return .empty;
    if (params == .null) return .empty;
    if (params != .object) return .{ .message = "config/read params must be an object" };
    return .{ .object = params.object };
}

const OptionalStringField = union(enum) {
    value: ?[]const u8,
    missing,
    invalid,
};

fn optionalStringOrNull(object: std.json.ObjectMap, field: []const u8) OptionalStringField {
    const value = object.get(field) orelse return .missing;
    if (value == .null) return .{ .value = null };
    if (value != .string) return .invalid;
    return .{ .value = value.string };
}

fn resolveConfigWritePath(allocator: std.mem.Allocator, file_path_value: ?std.json.Value) ![]const u8 {
    const default_path = try resolveDefaultConfigWritePath(allocator);
    errdefer allocator.free(default_path);

    const value = file_path_value orelse return default_path;
    if (value == .null) return default_path;
    if (value != .string or value.string.len == 0) return error.InvalidConfigWritePath;
    if (!std.fs.path.isAbsolute(value.string)) return error.InvalidConfigWritePath;

    const config_path = try std.fs.path.resolve(allocator, &.{value.string});
    errdefer allocator.free(config_path);
    if (!try configWritePathMatches(allocator, default_path, config_path)) {
        return error.ConfigWritePathReadonly;
    }
    allocator.free(default_path);
    return config_path;
}

fn resolveDefaultConfigWritePath(allocator: std.mem.Allocator) ![]const u8 {
    const codex_home = try resolveCodexHome(allocator);
    defer allocator.free(codex_home);
    return config.configTomlPath(allocator, codex_home);
}

fn configWritePathMatches(allocator: std.mem.Allocator, expected: []const u8, provided: []const u8) !bool {
    if (std.mem.eql(u8, expected, provided)) return true;

    const normalized_expected = try std.fs.path.resolve(allocator, &.{expected});
    defer allocator.free(normalized_expected);
    const normalized_provided = try std.fs.path.resolve(allocator, &.{provided});
    defer allocator.free(normalized_provided);
    if (std.mem.eql(u8, normalized_expected, normalized_provided)) return true;

    if (try configWriteParentPathMatches(allocator, normalized_expected, normalized_provided)) return true;

    const real_expected = realPathFileAllocPlain(allocator, normalized_expected) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return false,
    };
    defer allocator.free(real_expected);
    const real_provided = realPathFileAllocPlain(allocator, normalized_provided) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return false,
    };
    defer allocator.free(real_provided);
    return std.mem.eql(u8, real_expected, real_provided);
}

fn configWriteParentPathMatches(allocator: std.mem.Allocator, expected: []const u8, provided: []const u8) !bool {
    if (!std.mem.eql(u8, std.fs.path.basename(expected), std.fs.path.basename(provided))) return false;
    const expected_parent = std.fs.path.dirname(expected) orelse return false;
    const provided_parent = std.fs.path.dirname(provided) orelse return false;

    const real_expected_parent = realPathFileAllocPlain(allocator, expected_parent) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return false,
    };
    defer allocator.free(real_expected_parent);
    const real_provided_parent = realPathFileAllocPlain(allocator, provided_parent) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return false,
    };
    defer allocator.free(real_provided_parent);
    return std.mem.eql(u8, real_expected_parent, real_provided_parent);
}

fn renderTomlValue(allocator: std.mem.Allocator, value: std.json.Value) anyerror![]const u8 {
    return switch (value) {
        .string => |string| renderTomlString(allocator, string),
        .bool => |boolean| allocator.dupe(u8, if (boolean) "true" else "false"),
        .integer => |integer| std.fmt.allocPrint(allocator, "{}", .{integer}),
        .float => |float| std.fmt.allocPrint(allocator, "{d}", .{float}),
        .number_string => |number| allocator.dupe(u8, number),
        .array => |array| renderTomlArray(allocator, array.items),
        .object => |object| renderTomlInlineTable(allocator, object),
        else => error.UnsupportedConfigWriteValue,
    };
}

fn renderTomlArray(allocator: std.mem.Allocator, values: []std.json.Value) anyerror![]const u8 {
    var rendered = std.ArrayList(u8).empty;
    errdefer rendered.deinit(allocator);
    try rendered.append(allocator, '[');
    for (values, 0..) |value, index| {
        if (index > 0) try rendered.appendSlice(allocator, ", ");
        const item = try renderTomlValue(allocator, value);
        defer allocator.free(item);
        try rendered.appendSlice(allocator, item);
    }
    try rendered.append(allocator, ']');
    return rendered.toOwnedSlice(allocator);
}

fn renderTomlInlineTable(allocator: std.mem.Allocator, object: std.json.ObjectMap) anyerror![]const u8 {
    var rendered = std.ArrayList(u8).empty;
    errdefer rendered.deinit(allocator);
    try rendered.append(allocator, '{');

    var iterator = object.iterator();
    var index: usize = 0;
    while (iterator.next()) |entry| {
        if (index > 0) try rendered.appendSlice(allocator, ", ");
        const key = try renderTomlString(allocator, entry.key_ptr.*);
        defer allocator.free(key);
        try rendered.appendSlice(allocator, key);
        try rendered.appendSlice(allocator, " = ");
        const value = try renderTomlValue(allocator, entry.value_ptr.*);
        defer allocator.free(value);
        try rendered.appendSlice(allocator, value);
        index += 1;
    }

    try rendered.append(allocator, '}');
    return rendered.toOwnedSlice(allocator);
}

fn renderTomlString(allocator: std.mem.Allocator, value: []const u8) ![]const u8 {
    var rendered = std.ArrayList(u8).empty;
    errdefer rendered.deinit(allocator);
    try rendered.append(allocator, '"');
    for (value) |byte| {
        switch (byte) {
            '"' => try rendered.appendSlice(allocator, "\\\""),
            '\\' => try rendered.appendSlice(allocator, "\\\\"),
            '\n' => try rendered.appendSlice(allocator, "\\n"),
            '\r' => try rendered.appendSlice(allocator, "\\r"),
            '\t' => try rendered.appendSlice(allocator, "\\t"),
            else => try rendered.append(allocator, byte),
        }
    }
    try rendered.append(allocator, '"');
    return rendered.toOwnedSlice(allocator);
}

fn configVersionAlloc(allocator: std.mem.Allocator, bytes: []const u8) ![]const u8 {
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(bytes, &digest, .{});
    const prefix = "sha256:";
    var out = try allocator.alloc(u8, prefix.len + digest.len * 2);
    @memcpy(out[0..prefix.len], prefix);
    const hex = "0123456789abcdef";
    for (digest, 0..) |byte, index| {
        out[prefix.len + index * 2] = hex[byte >> 4];
        out[prefix.len + index * 2 + 1] = hex[byte & 0x0f];
    }
    return out;
}

fn renderFirstManagedConfigWriteOverrideMetadata(
    allocator: std.mem.Allocator,
    layer: ConfigReadManagedLayer,
    edits: []const ConfigRawEdit,
    user_config_bytes: []const u8,
) !?[]const u8 {
    for (edits) |edit| {
        const effective_value_json = try renderManagedConfigWriteOverrideValueJson(allocator, layer, edit.key_path, user_config_bytes);
        if (effective_value_json) |value_json| {
            defer allocator.free(value_json);
            const metadata = try renderManagedConfigWriteOverrideMetadata(allocator, layer, value_json);
            return metadata;
        }
    }
    return null;
}

fn renderManagedConfigWriteOverrideValueJson(
    allocator: std.mem.Allocator,
    layer: ConfigReadManagedLayer,
    key_path: []const u8,
    user_config_bytes: []const u8,
) !?[]const u8 {
    if (std.mem.eql(u8, key_path, "model")) {
        if (layer.model) |value| return renderStringOverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "review_model")) {
        if (layer.review_model) |value| return renderStringOverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "model_context_window")) {
        if (layer.model_context_window) |value| return renderI64OverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "model_auto_compact_token_limit")) {
        if (layer.model_auto_compact_token_limit) |value| return renderI64OverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "model_provider")) {
        if (layer.model_provider) |value| return renderStringOverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "instructions") or std.mem.eql(u8, key_path, "base_instructions")) {
        if (layer.instructions) |value| return renderStringOverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "developer_instructions")) {
        if (layer.developer_instructions) |value| return renderStringOverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "compact_prompt")) {
        if (layer.compact_prompt) |value| return renderStringOverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "approval_policy")) {
        if (layer.approval_policy) |value| return renderStringOverrideValue(allocator, value.label(), key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "approvals_reviewer")) {
        if (layer.approvals_reviewer) |value| return renderStringOverrideValue(allocator, value.label(), key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "sandbox_mode")) {
        if (layer.sandbox_mode) |value| return renderStringOverrideValue(allocator, value.label(), key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "web_search")) {
        if (layer.web_search_mode) |value| return renderStringOverrideValue(allocator, value.label(), key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "model_reasoning_effort")) {
        if (layer.model_reasoning_effort) |value| return renderStringOverrideValue(allocator, value.label(), key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "model_verbosity")) {
        if (layer.model_verbosity) |value| return renderStringOverrideValue(allocator, value.label(), key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "service_tier")) {
        if (layer.service_tier) |value| return renderStringOverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "forced_chatgpt_workspace_id")) {
        if (layer.forced_chatgpt_workspace_id) |value| return renderStringOverrideValue(allocator, value, key_path, user_config_bytes);
    } else if (std.mem.eql(u8, key_path, "forced_login_method")) {
        if (layer.forced_login_method) |value| return renderStringOverrideValue(allocator, value.label(), key_path, user_config_bytes);
    }
    return null;
}

fn renderStringOverrideValue(
    allocator: std.mem.Allocator,
    effective_value: []const u8,
    key_path: []const u8,
    user_config_bytes: []const u8,
) !?[]const u8 {
    if (try configWriteUserScalarEquals(allocator, user_config_bytes, key_path, effective_value)) return null;
    const value_json = try std.json.Stringify.valueAlloc(allocator, effective_value, .{});
    return value_json;
}

fn renderI64OverrideValue(
    allocator: std.mem.Allocator,
    effective_value: i64,
    key_path: []const u8,
    user_config_bytes: []const u8,
) !?[]const u8 {
    if (try configWriteUserI64Equals(user_config_bytes, key_path, effective_value)) return null;
    return @as(?[]const u8, try std.fmt.allocPrint(allocator, "{d}", .{effective_value}));
}

fn configWriteUserScalarEquals(
    allocator: std.mem.Allocator,
    user_config_bytes: []const u8,
    key_path: []const u8,
    expected: []const u8,
) !bool {
    const user_value = try configWriteUserScalarValue(allocator, user_config_bytes, key_path) orelse return false;
    defer allocator.free(user_value);
    return std.mem.eql(u8, user_value, expected);
}

fn configWriteUserI64Equals(
    user_config_bytes: []const u8,
    key_path: []const u8,
    expected: i64,
) !bool {
    const user_value = try configWriteUserI64Value(user_config_bytes, key_path) orelse return false;
    return user_value == expected;
}

fn configWriteUserScalarValue(
    allocator: std.mem.Allocator,
    user_config_bytes: []const u8,
    key_path: []const u8,
) !?[]const u8 {
    if (std.mem.eql(u8, key_path, "model")) {
        return configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "model");
    }
    if (std.mem.eql(u8, key_path, "review_model")) {
        return configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "review_model");
    }
    if (std.mem.eql(u8, key_path, "model_provider")) {
        return configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "model_provider");
    }
    if (std.mem.eql(u8, key_path, "instructions")) {
        return configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "instructions");
    }
    if (std.mem.eql(u8, key_path, "base_instructions")) {
        return configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "base_instructions");
    }
    if (std.mem.eql(u8, key_path, "developer_instructions")) {
        return configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "developer_instructions");
    }
    if (std.mem.eql(u8, key_path, "compact_prompt")) {
        return configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "compact_prompt");
    }
    if (std.mem.eql(u8, key_path, "model_verbosity")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "model_verbosity")) |value| {
            defer allocator.free(value);
            const normalized = try allocator.dupe(u8, (try config.Verbosity.parse(value)).label());
            return normalized;
        }
        return null;
    }
    if (std.mem.eql(u8, key_path, "approval_policy")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "approval_policy")) |value| {
            defer allocator.free(value);
            const normalized = try allocator.dupe(u8, (try config.ApprovalPolicy.parse(value)).label());
            return normalized;
        }
        return null;
    }
    if (std.mem.eql(u8, key_path, "approvals_reviewer")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "approvals_reviewer")) |value| {
            defer allocator.free(value);
            const normalized = try allocator.dupe(u8, (try config.ApprovalsReviewer.parse(value)).label());
            return normalized;
        }
        return null;
    }
    if (std.mem.eql(u8, key_path, "sandbox_mode")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "sandbox_mode")) |value| {
            defer allocator.free(value);
            const normalized = try allocator.dupe(u8, (try config.SandboxMode.parse(value)).label());
            return normalized;
        }
        return null;
    }
    if (std.mem.eql(u8, key_path, "web_search")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "web_search")) |value| {
            defer allocator.free(value);
            const normalized = try allocator.dupe(u8, (try config.WebSearchMode.parse(value)).label());
            return normalized;
        }
        return null;
    }
    if (std.mem.eql(u8, key_path, "model_reasoning_effort")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "model_reasoning_effort")) |value| {
            defer allocator.free(value);
            const normalized = try allocator.dupe(u8, (try config.ReasoningEffort.parse(value)).label());
            return normalized;
        }
        return null;
    }
    if (std.mem.eql(u8, key_path, "service_tier")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "service_tier")) |value| {
            defer allocator.free(value);
            const normalized = try config.normalizeServiceTier(allocator, value);
            return normalized;
        }
        return null;
    }
    if (std.mem.eql(u8, key_path, "forced_chatgpt_workspace_id")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "forced_chatgpt_workspace_id")) |value| {
            defer allocator.free(value);
            const trimmed = std.mem.trim(u8, value, " \t\r\n");
            if (trimmed.len == 0) return null;
            return @as(?[]const u8, try allocator.dupe(u8, trimmed));
        }
        return null;
    }
    if (std.mem.eql(u8, key_path, "forced_login_method")) {
        if (try configWriteRequiredTopLevelStringValue(allocator, user_config_bytes, "forced_login_method")) |value| {
            defer allocator.free(value);
            const normalized = try allocator.dupe(u8, (try config.ForcedLoginMethod.parse(value)).label());
            return normalized;
        }
        return null;
    }
    return null;
}

fn configWriteUserI64Value(user_config_bytes: []const u8, key_path: []const u8) !?i64 {
    if (std.mem.eql(u8, key_path, "model_context_window")) {
        return configWriteRequiredTopLevelI64Value(user_config_bytes, "model_context_window");
    }
    if (std.mem.eql(u8, key_path, "model_auto_compact_token_limit")) {
        return configWriteRequiredTopLevelI64Value(user_config_bytes, "model_auto_compact_token_limit");
    }
    return null;
}

fn configWriteRequiredTopLevelStringValue(
    allocator: std.mem.Allocator,
    user_config_bytes: []const u8,
    key: []const u8,
) !?[]const u8 {
    _ = configReadTopLevelRawValue(user_config_bytes, key) orelse return null;
    return (try config.topLevelStringValue(allocator, user_config_bytes, key)) orelse error.InvalidConfigWriteScalarType;
}

fn configWriteRequiredTopLevelI64Value(user_config_bytes: []const u8, key: []const u8) !?i64 {
    _ = configReadTopLevelRawValue(user_config_bytes, key) orelse return null;
    return (try config.topLevelI64Value(user_config_bytes, key)) orelse error.InvalidConfigWriteScalarType;
}

fn renderManagedConfigWriteOverrideMetadata(
    allocator: std.mem.Allocator,
    layer: ConfigReadManagedLayer,
    effective_value_json: []const u8,
) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);

    const message = try std.fmt.allocPrint(allocator, "Overridden by legacy managed_config.toml: {s}", .{layer.file_path});
    defer allocator.free(message);
    const message_json = try std.json.Stringify.valueAlloc(allocator, message, .{});
    defer allocator.free(message_json);
    const version_json = try std.json.Stringify.valueAlloc(allocator, layer.version, .{});
    defer allocator.free(version_json);

    try result.appendSlice(allocator, "{\"message\":");
    try result.appendSlice(allocator, message_json);
    try result.appendSlice(allocator, ",\"overridingLayer\":{\"name\":");
    try appendConfigReadManagedSource(allocator, &result, layer.file_path);
    try result.appendSlice(allocator, ",\"version\":");
    try result.appendSlice(allocator, version_json);
    try result.appendSlice(allocator, "},\"effectiveValue\":");
    try result.appendSlice(allocator, effective_value_json);
    try result.append(allocator, '}');

    return result.toOwnedSlice(allocator);
}

fn renderConfigWriteResponse(
    allocator: std.mem.Allocator,
    file_path: []const u8,
    version: []const u8,
    overridden_metadata: ?[]const u8,
) ![]const u8 {
    const path_json = try std.json.Stringify.valueAlloc(allocator, file_path, .{});
    defer allocator.free(path_json);
    const version_json = try std.json.Stringify.valueAlloc(allocator, version, .{});
    defer allocator.free(version_json);
    return std.fmt.allocPrint(
        allocator,
        "{{\"status\":\"{s}\",\"version\":{s},\"filePath\":{s},\"overriddenMetadata\":{s}}}",
        .{
            if (overridden_metadata != null) "okOverridden" else "ok",
            version_json,
            path_json,
            overridden_metadata orelse "null",
        },
    );
}

fn renderConfigReadResponse(
    allocator: std.mem.Allocator,
    cfg: config.Config,
    cli_feature_overrides: features_cmd.FeatureOverrides,
    config_feature_overrides: features_cmd.FeatureOverrides,
    runtime_feature_enablement: features_cmd.FeatureOverrides,
    requirements: ConfigRequirementsReadRequirements,
    include_layers: bool,
    managed_layer: ?ConfigReadManagedLayer,
    project_layers: ConfigReadProjectLayers,
    user_layer: ?ConfigReadUserLayer,
    system_layer: ?ConfigReadSystemLayer,
) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);

    try result.appendSlice(allocator, "{\"config\":{");
    var first = true;
    const system_model = if (system_layer) |layer| layer.model else null;
    const model = if (managed_layer) |layer| layer.model orelse project_layers.model() orelse configReadUserOrSystemString(cfg.model, user_layer, "model", system_model) else project_layers.model() orelse configReadUserOrSystemString(cfg.model, user_layer, "model", system_model);
    try appendJsonStringField(allocator, &result, &first, "model", model);
    const system_review_model = if (system_layer) |layer| layer.review_model else null;
    const managed_review_model = if (managed_layer) |layer| layer.review_model else null;
    const review_model = managed_review_model orelse project_layers.reviewModel() orelse configReadUserOrSystemMaybeString(cfg.review_model, user_layer, "review_model", system_review_model);
    try appendJsonMaybeStringField(allocator, &result, &first, "review_model", review_model);
    const system_model_context_window = if (system_layer) |layer| layer.model_context_window else null;
    const managed_model_context_window = if (managed_layer) |layer| layer.model_context_window else null;
    const model_context_window = managed_model_context_window orelse project_layers.modelContextWindow() orelse configReadUserOrSystemMaybeI64(cfg.model_context_window, user_layer, "model_context_window", system_model_context_window);
    try appendJsonMaybeI64Field(allocator, &result, &first, "model_context_window", model_context_window);
    const system_model_auto_compact_token_limit = if (system_layer) |layer| layer.model_auto_compact_token_limit else null;
    const managed_model_auto_compact_token_limit = if (managed_layer) |layer| layer.model_auto_compact_token_limit else null;
    const model_auto_compact_token_limit = managed_model_auto_compact_token_limit orelse project_layers.modelAutoCompactTokenLimit() orelse configReadUserOrSystemMaybeI64(cfg.model_auto_compact_token_limit, user_layer, "model_auto_compact_token_limit", system_model_auto_compact_token_limit);
    try appendJsonMaybeI64Field(allocator, &result, &first, "model_auto_compact_token_limit", model_auto_compact_token_limit);
    const system_model_provider = if (system_layer) |layer| layer.model_provider else null;
    const managed_model_provider = if (managed_layer) |layer| layer.model_provider else null;
    const model_provider = managed_model_provider orelse configReadUserOrSystemMaybeString(cfg.model_provider_id, user_layer, "model_provider", system_model_provider);
    try appendJsonMaybeStringField(allocator, &result, &first, "model_provider", model_provider);
    try appendJsonMaybeStringField(allocator, &result, &first, "profile", cfg.active_profile);
    try appendJsonFieldName(allocator, &result, &first, "profiles");
    try appendEffectiveConfigReadProfilesObject(allocator, &result, managed_layer, project_layers, user_layer, system_layer);
    const system_instructions = if (system_layer) |layer| layer.instructions else null;
    const managed_instructions = if (managed_layer) |layer| layer.instructions else null;
    const instructions = managed_instructions orelse project_layers.instructions() orelse configReadUserOrSystemMaybeString(cfg.base_instructions, user_layer, "instructions", system_instructions);
    try appendJsonMaybeStringField(allocator, &result, &first, "instructions", instructions);
    const system_developer_instructions = if (system_layer) |layer| layer.developer_instructions else null;
    const managed_developer_instructions = if (managed_layer) |layer| layer.developer_instructions else null;
    const developer_instructions = managed_developer_instructions orelse project_layers.developerInstructions() orelse configReadUserOrSystemMaybeString(cfg.developer_instructions, user_layer, "developer_instructions", system_developer_instructions);
    try appendJsonMaybeStringField(allocator, &result, &first, "developer_instructions", developer_instructions);
    const system_compact_prompt = if (system_layer) |layer| layer.compact_prompt else null;
    const managed_compact_prompt = if (managed_layer) |layer| layer.compact_prompt else null;
    const compact_prompt = managed_compact_prompt orelse project_layers.compactPrompt() orelse configReadUserOrSystemMaybeString(cfg.compact_prompt, user_layer, "compact_prompt", system_compact_prompt);
    try appendJsonMaybeStringField(allocator, &result, &first, "compact_prompt", compact_prompt);
    const system_approval_policy = if (system_layer) |layer| layer.approval_policy else null;
    const configured_approval_policy = if (managed_layer) |layer| layer.approval_policy orelse project_layers.approvalPolicy() orelse configReadUserOrSystemApprovalPolicy(cfg.approval_policy, user_layer, system_approval_policy) else project_layers.approvalPolicy() orelse configReadUserOrSystemApprovalPolicy(cfg.approval_policy, user_layer, system_approval_policy);
    const approval_policy = try configReadRequirementApprovalPolicy(configured_approval_policy, requirements);
    try appendJsonStringField(allocator, &result, &first, "approval_policy", approval_policy.label());
    const system_approvals_reviewer = if (system_layer) |layer| layer.approvals_reviewer else null;
    const configured_approvals_reviewer = if (managed_layer) |layer| layer.approvals_reviewer orelse project_layers.approvalsReviewer() orelse configReadUserOrSystemApprovalsReviewer(cfg.approvals_reviewer, user_layer, system_approvals_reviewer) else project_layers.approvalsReviewer() orelse configReadUserOrSystemApprovalsReviewer(cfg.approvals_reviewer, user_layer, system_approvals_reviewer);
    const approvals_reviewer = try configReadRequirementApprovalsReviewer(configured_approvals_reviewer, requirements);
    try appendJsonStringField(allocator, &result, &first, "approvals_reviewer", approvals_reviewer.label());
    const system_sandbox_mode = if (system_layer) |layer| layer.sandbox_mode else null;
    const configured_sandbox_mode = if (managed_layer) |layer| layer.sandbox_mode orelse project_layers.sandboxMode() orelse configReadUserOrSystemSandboxMode(cfg.sandbox_mode, user_layer, system_sandbox_mode) else project_layers.sandboxMode() orelse configReadUserOrSystemSandboxMode(cfg.sandbox_mode, user_layer, system_sandbox_mode);
    const sandbox_mode = try configReadRequirementSandboxMode(configured_sandbox_mode, requirements);
    try appendJsonStringField(allocator, &result, &first, "sandbox_mode", sandbox_mode.label());
    try appendConfigReadSandboxWorkspaceWriteField(allocator, &result, &first, effectiveConfigReadSandboxWorkspaceWrite(managed_layer, project_layers, user_layer, system_layer));
    const system_forced_chatgpt_workspace_id = if (system_layer) |layer| layer.forced_chatgpt_workspace_id else null;
    const managed_forced_chatgpt_workspace_id = if (managed_layer) |layer| layer.forced_chatgpt_workspace_id else null;
    const forced_chatgpt_workspace_id = managed_forced_chatgpt_workspace_id orelse project_layers.forcedChatGptWorkspaceId() orelse configReadUserOrSystemMaybeString(cfg.forced_chatgpt_workspace_id, user_layer, "forced_chatgpt_workspace_id", system_forced_chatgpt_workspace_id);
    try appendJsonMaybeStringField(allocator, &result, &first, "forced_chatgpt_workspace_id", forced_chatgpt_workspace_id);
    const system_forced_login_method = if (system_layer) |layer| layer.forced_login_method else null;
    const managed_forced_login_method = if (managed_layer) |layer| layer.forced_login_method else null;
    const forced_login_method = managed_forced_login_method orelse project_layers.forcedLoginMethod() orelse configReadUserOrSystemForcedLoginMethod(cfg.forced_login_method, user_layer, system_forced_login_method);
    try appendJsonMaybeStringField(allocator, &result, &first, "forced_login_method", if (forced_login_method) |method| method.label() else null);
    const system_web_search_mode = if (system_layer) |layer| layer.web_search_mode else null;
    const managed_web_search_mode = if (managed_layer) |layer| layer.web_search_mode else null;
    const configured_web_search_mode = managed_web_search_mode orelse project_layers.webSearchMode() orelse configReadUserOrSystemWebSearchMode(cfg.web_search_mode, user_layer, system_web_search_mode);
    const web_search_mode = try configReadRequirementWebSearchMode(configured_web_search_mode, requirements);
    try appendJsonMaybeStringField(allocator, &result, &first, "web_search", if (web_search_mode) |mode| mode.label() else null);
    try appendConfigReadToolsField(allocator, &result, &first, effectiveConfigReadTools(managed_layer, project_layers, user_layer, system_layer));
    var apps = try effectiveConfigReadApps(allocator, managed_layer, project_layers, user_layer, system_layer, requirements.app_requirements);
    defer if (apps) |*value| value.deinit(allocator);
    try appendConfigReadAppsField(allocator, &result, &first, apps);
    const system_model_reasoning_effort = if (system_layer) |layer| layer.model_reasoning_effort else null;
    const managed_model_reasoning_effort = if (managed_layer) |layer| layer.model_reasoning_effort else null;
    const model_reasoning_effort = managed_model_reasoning_effort orelse project_layers.modelReasoningEffort() orelse configReadUserOrSystemReasoningEffort(cfg.model_reasoning_effort, user_layer, system_model_reasoning_effort);
    try appendJsonMaybeStringField(allocator, &result, &first, "model_reasoning_effort", if (model_reasoning_effort) |effort| effort.label() else null);
    const system_model_verbosity = if (system_layer) |layer| layer.model_verbosity else null;
    const managed_model_verbosity = if (managed_layer) |layer| layer.model_verbosity else null;
    const model_verbosity = managed_model_verbosity orelse project_layers.modelVerbosity() orelse configReadUserOrSystemVerbosity(cfg.model_verbosity, user_layer, system_model_verbosity);
    try appendJsonMaybeStringField(allocator, &result, &first, "model_verbosity", if (model_verbosity) |verbosity| verbosity.label() else null);
    const system_service_tier = if (system_layer) |layer| layer.service_tier else null;
    const managed_service_tier = if (managed_layer) |layer| layer.service_tier else null;
    const service_tier = managed_service_tier orelse project_layers.serviceTier() orelse configReadUserOrSystemMaybeString(cfg.service_tier, user_layer, "service_tier", system_service_tier);
    try appendJsonMaybeStringField(allocator, &result, &first, "service_tier", service_tier);
    try appendConfigReadAnalyticsField(allocator, &result, &first, effectiveConfigReadAnalytics(managed_layer, project_layers, user_layer, system_layer, cfg.active_profile));
    try appendJsonMaybeStringField(allocator, &result, &first, "oss_provider", cfg.oss_provider);
    try appendJsonStringField(allocator, &result, &first, "openai_base_url", cfg.openai_base_url);
    try appendJsonStringField(allocator, &result, &first, "chatgpt_base_url", cfg.chatgpt_base_url);
    try appendConfigReadFeaturesField(allocator, &result, &first, cli_feature_overrides, config_feature_overrides, runtime_feature_enablement, requirements.feature_requirements);
    try result.appendSlice(allocator, "},\"origins\":");
    try appendConfigReadOrigins(allocator, &result, managed_layer, project_layers, user_layer, system_layer);
    try result.appendSlice(allocator, ",\"layers\":");
    try appendConfigReadLayers(allocator, &result, cfg, include_layers, managed_layer, project_layers, user_layer, system_layer);
    try result.appendSlice(allocator, "}");

    return result.toOwnedSlice(allocator);
}

const ConfigReadManagedLayer = struct {
    file_path: []const u8,
    version: []const u8,
    origin_keys: []const []const u8,
    model: ?[]const u8 = null,
    review_model: ?[]const u8 = null,
    model_context_window: ?i64 = null,
    model_auto_compact_token_limit: ?i64 = null,
    model_provider: ?[]const u8 = null,
    instructions: ?[]const u8 = null,
    developer_instructions: ?[]const u8 = null,
    compact_prompt: ?[]const u8 = null,
    approval_policy: ?config.ApprovalPolicy = null,
    approvals_reviewer: ?config.ApprovalsReviewer = null,
    sandbox_mode: ?config.SandboxMode = null,
    web_search_mode: ?config.WebSearchMode = null,
    model_reasoning_effort: ?config.ReasoningEffort = null,
    model_verbosity: ?config.Verbosity = null,
    service_tier: ?[]const u8 = null,
    analytics: ConfigReadAnalytics = .{},
    forced_chatgpt_workspace_id: ?[]const u8 = null,
    forced_login_method: ?config.ForcedLoginMethod = null,
    profiles: ConfigReadProfiles = ConfigReadProfiles.empty(),
    tools: ConfigReadTools = .{},
    apps: ConfigReadApps = ConfigReadApps.empty(),
    sandbox_workspace_write: ConfigReadSandboxWorkspaceWrite = .{},

    fn deinit(self: *ConfigReadManagedLayer, allocator: std.mem.Allocator) void {
        allocator.free(self.file_path);
        allocator.free(self.version);
        if (self.model) |value| allocator.free(value);
        if (self.review_model) |value| allocator.free(value);
        if (self.model_provider) |value| allocator.free(value);
        if (self.instructions) |value| allocator.free(value);
        if (self.developer_instructions) |value| allocator.free(value);
        if (self.compact_prompt) |value| allocator.free(value);
        if (self.service_tier) |value| allocator.free(value);
        if (self.forced_chatgpt_workspace_id) |value| allocator.free(value);
        for (self.origin_keys) |key| allocator.free(key);
        if (self.origin_keys.len > 0) allocator.free(self.origin_keys);
        self.profiles.deinit(allocator);
        self.tools.deinit(allocator);
        self.apps.deinit(allocator);
        self.sandbox_workspace_write.deinit(allocator);
    }

    fn hasOriginKey(self: ConfigReadManagedLayer, key: []const u8) bool {
        for (self.origin_keys) |origin_key| {
            if (std.mem.eql(u8, origin_key, key)) return true;
        }
        return false;
    }

    fn hasSandboxWorkspaceWriteRoot(self: ConfigReadManagedLayer) bool {
        return self.sandbox_workspace_write.writable_roots != null;
    }

    fn hasToolsAllowedDomains(self: ConfigReadManagedLayer) bool {
        return configReadToolsHasAllowedDomains(self.tools);
    }
};

