    }

    fn modelAutoCompactTokenLimit(self: ConfigReadProjectLayers) ?i64 {
        for (self.items) |layer| {
            if (layer.model_auto_compact_token_limit) |value| return value;
        }
        return null;
    }

    fn instructions(self: ConfigReadProjectLayers) ?[]const u8 {
        for (self.items) |layer| {
            if (layer.instructions) |value| return value;
        }
        return null;
    }

    fn developerInstructions(self: ConfigReadProjectLayers) ?[]const u8 {
        for (self.items) |layer| {
            if (layer.developer_instructions) |value| return value;
        }
        return null;
    }

    fn compactPrompt(self: ConfigReadProjectLayers) ?[]const u8 {
        for (self.items) |layer| {
            if (layer.compact_prompt) |value| return value;
        }
        return null;
    }

    fn approvalPolicy(self: ConfigReadProjectLayers) ?config.ApprovalPolicy {
        for (self.items) |layer| {
            if (layer.approval_policy) |policy| return policy;
        }
        return null;
    }

    fn approvalsReviewer(self: ConfigReadProjectLayers) ?config.ApprovalsReviewer {
        for (self.items) |layer| {
            if (layer.approvals_reviewer) |reviewer| return reviewer;
        }
        return null;
    }

    fn sandboxMode(self: ConfigReadProjectLayers) ?config.SandboxMode {
        for (self.items) |layer| {
            if (layer.sandbox_mode) |mode| return mode;
        }
        return null;
    }

    fn webSearchMode(self: ConfigReadProjectLayers) ?config.WebSearchMode {
        for (self.items) |layer| {
            if (layer.web_search_mode) |mode| return mode;
        }
        return null;
    }

    fn modelReasoningEffort(self: ConfigReadProjectLayers) ?config.ReasoningEffort {
        for (self.items) |layer| {
            if (layer.model_reasoning_effort) |effort| return effort;
        }
        return null;
    }

    fn modelVerbosity(self: ConfigReadProjectLayers) ?config.Verbosity {
        for (self.items) |layer| {
            if (layer.model_verbosity) |verbosity| return verbosity;
        }
        return null;
    }

    fn serviceTier(self: ConfigReadProjectLayers) ?[]const u8 {
        for (self.items) |layer| {
            if (layer.service_tier) |value| return value;
        }
        return null;
    }

    fn analytics(self: ConfigReadProjectLayers) ConfigReadAnalytics {
        var merged = ConfigReadAnalytics{};
        for (self.items) |layer| {
            mergeConfigReadAnalytics(&merged, layer.analytics);
        }
        return merged;
    }

    fn forcedChatGptWorkspaceId(self: ConfigReadProjectLayers) ?[]const u8 {
        for (self.items) |layer| {
            if (layer.forced_chatgpt_workspace_id) |value| return value;
        }
        return null;
    }

    fn forcedLoginMethod(self: ConfigReadProjectLayers) ?config.ForcedLoginMethod {
        for (self.items) |layer| {
            if (layer.forced_login_method) |value| return value;
        }
        return null;
    }

    fn tools(self: ConfigReadProjectLayers) ConfigReadTools {
        var merged = ConfigReadTools{};
        for (self.items) |layer| {
            mergeConfigReadTools(&merged, layer.tools);
        }
        return merged;
    }

    fn sandboxWorkspaceWrite(self: ConfigReadProjectLayers) ConfigReadSandboxWorkspaceWrite {
        var sandbox = ConfigReadSandboxWorkspaceWrite{};
        for (self.items) |layer| {
            const layer_sandbox = layer.sandbox_workspace_write;
            if (layer_sandbox.present) sandbox.present = true;
            if (sandbox.writable_roots == null) {
                if (layer_sandbox.writable_roots) |roots| sandbox.writable_roots = roots;
            }
            if (!sandbox.network_access_present and layer_sandbox.network_access_present) {
                sandbox.network_access = layer_sandbox.network_access;
                sandbox.network_access_present = true;
            }
            if (!sandbox.exclude_tmpdir_env_var_present and layer_sandbox.exclude_tmpdir_env_var_present) {
                sandbox.exclude_tmpdir_env_var = layer_sandbox.exclude_tmpdir_env_var;
                sandbox.exclude_tmpdir_env_var_present = true;
            }
            if (!sandbox.exclude_slash_tmp_present and layer_sandbox.exclude_slash_tmp_present) {
                sandbox.exclude_slash_tmp = layer_sandbox.exclude_slash_tmp;
                sandbox.exclude_slash_tmp_present = true;
            }
        }
        return sandbox;
    }

    fn hasOriginKey(self: ConfigReadProjectLayers, key: []const u8) bool {
        return configReadProjectSliceHasOriginKey(self.items, key);
    }

    fn hasSandboxWorkspaceWriteRoot(self: ConfigReadProjectLayers) bool {
        for (self.items) |layer| {
            if (layer.sandbox_workspace_write.writable_roots != null) return true;
        }
        return false;
    }

    fn hasToolsAllowedDomains(self: ConfigReadProjectLayers) bool {
        return configReadProjectSliceHasToolsAllowedDomains(self.items);
    }

    fn hasProfileAllowedDomains(self: ConfigReadProjectLayers, profile_name: []const u8) bool {
        return configReadProjectSliceHasProfileAllowedDomains(self.items, profile_name);
    }
};

const ConfigReadUserLayer = struct {
    file_path: []const u8,
    version: []const u8,
    origin_keys: []const []const u8,
    model_provider: ?[]const u8,
    profiles: ConfigReadProfiles,
    analytics: ConfigReadAnalytics,
    tools: ConfigReadTools,
    apps: ConfigReadApps,
    sandbox_workspace_write: ConfigReadSandboxWorkspaceWrite,

    fn deinit(self: *ConfigReadUserLayer, allocator: std.mem.Allocator) void {
        allocator.free(self.version);
        if (self.model_provider) |value| allocator.free(value);
        for (self.origin_keys) |key| allocator.free(key);
        allocator.free(self.origin_keys);
        self.profiles.deinit(allocator);
        self.tools.deinit(allocator);
        self.apps.deinit(allocator);
        self.sandbox_workspace_write.deinit(allocator);
    }
};

fn loadConfigReadUserLayer(
    allocator: std.mem.Allocator,
    config_path: []const u8,
    bytes: []const u8,
    active_profile: ?[]const u8,
) !ConfigReadUserLayer {
    var origin_keys = std.ArrayList([]const u8).fromOwnedSlice(try collectConfigReadUserOriginKeys(allocator, bytes, active_profile));
    errdefer {
        for (origin_keys.items) |key| allocator.free(key);
        origin_keys.deinit(allocator);
    }
    var tools = try loadConfigReadTools(allocator, bytes);
    errdefer tools.deinit(allocator);
    var apps = try loadConfigReadApps(allocator, bytes);
    errdefer apps.deinit(allocator);
    const model_provider = try config.scopedStringValue(allocator, bytes, active_profile, "model_provider");
    errdefer if (model_provider) |value| allocator.free(value);
    var profiles = try loadConfigReadProfiles(allocator, bytes);
    errdefer profiles.deinit(allocator);
    try appendConfigReadProfilesOriginKeys(allocator, &origin_keys, profiles);
    const analytics = try loadConfigReadAnalytics(allocator, bytes);
    var sandbox_workspace_write = try loadConfigReadSandboxWorkspaceWrite(allocator, bytes);
    errdefer sandbox_workspace_write.deinit(allocator);
    const version = try configVersionAlloc(allocator, bytes);
    errdefer allocator.free(version);
    const owned_origin_keys = try origin_keys.toOwnedSlice(allocator);
    return .{
        .file_path = config_path,
        .version = version,
        .origin_keys = owned_origin_keys,
        .model_provider = model_provider,
        .profiles = profiles,
        .analytics = analytics,
        .tools = tools,
        .apps = apps,
        .sandbox_workspace_write = sandbox_workspace_write,
    };
}

const ConfigReadProfiles = struct {
    items: []ConfigReadProfile,

    fn empty() ConfigReadProfiles {
        return .{ .items = &.{} };
    }

    fn deinit(self: *ConfigReadProfiles, allocator: std.mem.Allocator) void {
        for (self.items) |*profile| profile.deinit(allocator);
        if (self.items.len > 0) allocator.free(self.items);
        self.items = &.{};
    }
};

const ConfigReadProfile = struct {
    name: []const u8,
    model: ?[]const u8 = null,
    model_provider: ?[]const u8 = null,
    approval_policy: ?config.ApprovalPolicy = null,
    approvals_reviewer: ?config.ApprovalsReviewer = null,
    sandbox_mode: ?config.SandboxMode = null,
    service_tier: ?[]const u8 = null,
    model_reasoning_effort: ?config.ReasoningEffort = null,
    model_reasoning_summary: ?config.ReasoningSummary = null,
    model_verbosity: ?config.Verbosity = null,
    web_search_mode: ?config.WebSearchMode = null,
    tools: ConfigReadTools = .{},
    analytics: ConfigReadAnalytics = .{},
    chatgpt_base_url: ?[]const u8 = null,

    fn deinit(self: *ConfigReadProfile, allocator: std.mem.Allocator) void {
        allocator.free(self.name);
        if (self.model) |value| allocator.free(value);
        if (self.model_provider) |value| allocator.free(value);
        if (self.service_tier) |value| allocator.free(value);
        if (self.chatgpt_base_url) |value| allocator.free(value);
        self.tools.deinit(allocator);
    }
};

fn mergeConfigReadProfile(target: *ConfigReadProfile, source: ConfigReadProfile) void {
    if (target.model == null) target.model = source.model;
    if (target.model_provider == null) target.model_provider = source.model_provider;
    if (target.approval_policy == null) target.approval_policy = source.approval_policy;
    if (target.approvals_reviewer == null) target.approvals_reviewer = source.approvals_reviewer;
    if (target.sandbox_mode == null) target.sandbox_mode = source.sandbox_mode;
    if (target.service_tier == null) target.service_tier = source.service_tier;
    if (target.model_reasoning_effort == null) target.model_reasoning_effort = source.model_reasoning_effort;
    if (target.model_reasoning_summary == null) target.model_reasoning_summary = source.model_reasoning_summary;
    if (target.model_verbosity == null) target.model_verbosity = source.model_verbosity;
    if (target.web_search_mode == null) target.web_search_mode = source.web_search_mode;
    mergeConfigReadTools(&target.tools, source.tools);
    mergeConfigReadAnalytics(&target.analytics, source.analytics);
    if (target.chatgpt_base_url == null) target.chatgpt_base_url = source.chatgpt_base_url;
}

fn configReadProfilesFind(profiles: ConfigReadProfiles, name: []const u8) ?ConfigReadProfile {
    if (findConfigReadProfileIndex(profiles.items, name)) |index| return profiles.items[index];
    return null;
}

fn effectiveConfigReadProfile(
    name: []const u8,
    managed_layer: ?ConfigReadManagedLayer,
    project_layers: ConfigReadProjectLayers,
    user_layer: ?ConfigReadUserLayer,
    system_layer: ?ConfigReadSystemLayer,
) ConfigReadProfile {
    var profile = ConfigReadProfile{ .name = name };
    if (managed_layer) |layer| {
        if (configReadProfilesFind(layer.profiles, name)) |source| mergeConfigReadProfile(&profile, source);
    }
    for (project_layers.items) |layer| {
        if (configReadProfilesFind(layer.profiles, name)) |source| mergeConfigReadProfile(&profile, source);
    }
    if (user_layer) |layer| {
        if (configReadProfilesFind(layer.profiles, name)) |source| mergeConfigReadProfile(&profile, source);
    }
    if (system_layer) |layer| {
        if (configReadProfilesFind(layer.profiles, name)) |source| mergeConfigReadProfile(&profile, source);
    }
    return profile;
}

fn appendEffectiveConfigReadProfilesObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    managed_layer: ?ConfigReadManagedLayer,
    project_layers: ConfigReadProjectLayers,
    user_layer: ?ConfigReadUserLayer,
    system_layer: ?ConfigReadSystemLayer,
) !void {
    var seen = std.ArrayList([]const u8).empty;
    defer seen.deinit(allocator);

    try result.append(allocator, '{');
    var first = true;
    if (managed_layer) |layer| {
        try appendEffectiveConfigReadProfilesFromLayer(allocator, result, &first, &seen, layer.profiles, managed_layer, project_layers, user_layer, system_layer);
    }
    for (project_layers.items) |layer| {
        try appendEffectiveConfigReadProfilesFromLayer(allocator, result, &first, &seen, layer.profiles, managed_layer, project_layers, user_layer, system_layer);
    }
    if (user_layer) |layer| {
        try appendEffectiveConfigReadProfilesFromLayer(allocator, result, &first, &seen, layer.profiles, managed_layer, project_layers, user_layer, system_layer);
    }
    if (system_layer) |layer| {
        try appendEffectiveConfigReadProfilesFromLayer(allocator, result, &first, &seen, layer.profiles, managed_layer, project_layers, user_layer, system_layer);
    }
    try result.append(allocator, '}');
}

fn appendEffectiveConfigReadProfilesFromLayer(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    first: *bool,
    seen: *std.ArrayList([]const u8),
    profiles: ConfigReadProfiles,
    managed_layer: ?ConfigReadManagedLayer,
    project_layers: ConfigReadProjectLayers,
    user_layer: ?ConfigReadUserLayer,
    system_layer: ?ConfigReadSystemLayer,
) !void {
    for (profiles.items) |profile| {
        if (configReadProfileNameSeen(seen.items, profile.name)) continue;
        try seen.append(allocator, profile.name);
        try appendJsonFieldName(allocator, result, first, profile.name);
        try appendConfigReadProfileObject(allocator, result, effectiveConfigReadProfile(profile.name, managed_layer, project_layers, user_layer, system_layer));
    }
}

fn configReadProfileNameSeen(names: []const []const u8, name: []const u8) bool {
    for (names) |existing| {
        if (std.mem.eql(u8, existing, name)) return true;
    }
    return false;
}

const ConfigReadAnalytics = struct {
    present: bool = false,
    enabled: ?bool = null,
};

const TomlMultilineStringKind = enum {
    basic,
    literal,

    fn delimiter(self: TomlMultilineStringKind) []const u8 {
        return switch (self) {
            .basic => "\"\"\"",
            .literal => "'''",
        };
    }
};

const TomlMultilineStringOpen = struct {
    kind: TomlMultilineStringKind,
    index: usize,
};

fn tomlMultilineStringOpen(line: []const u8) ?TomlMultilineStringOpen {
    const basic_index = std.mem.indexOf(u8, line, "\"\"\"");
    const literal_index = std.mem.indexOf(u8, line, "'''");
    if (basic_index) |basic| {
        if (literal_index) |literal| {
            return if (basic < literal)
                .{ .kind = .basic, .index = basic }
            else
                .{ .kind = .literal, .index = literal };
        }
        return .{ .kind = .basic, .index = basic };
    }
    if (literal_index) |literal| return .{ .kind = .literal, .index = literal };
    return null;
}

fn tomlLineIsMultilineStringBody(active: *?TomlMultilineStringKind, line: []const u8) bool {
    if (active.*) |kind| {
        if (std.mem.indexOf(u8, line, kind.delimiter()) != null) active.* = null;
        return true;
    }

    return false;
}

fn observeTomlMultilineStringOpen(active: *?TomlMultilineStringKind, line: []const u8) void {
    if (active.* != null) return;
    const open = tomlMultilineStringOpen(line) orelse return;
    const delimiter = open.kind.delimiter();
    if (std.mem.indexOfPos(u8, line, open.index + delimiter.len, delimiter) == null) {
        active.* = open.kind;
    }
}

const ConfigReadProfileSectionKind = enum {
    profile,
    tools,
    web_search_tool,
    web_search_location,
    analytics,
};

const ConfigReadProfileSection = struct {
    name: []const u8,
    kind: ConfigReadProfileSectionKind,

    fn deinit(self: *ConfigReadProfileSection, allocator: std.mem.Allocator) void {
        allocator.free(self.name);
    }
};

fn loadConfigReadProfiles(allocator: std.mem.Allocator, bytes: []const u8) !ConfigReadProfiles {
    var profiles = std.ArrayList(ConfigReadProfile).empty;
    errdefer {
        for (profiles.items) |*profile| profile.deinit(allocator);
        profiles.deinit(allocator);
    }

    var current_profile_index: ?usize = null;
    var in_profiles_table = false;
    var current_kind: ConfigReadProfileSectionKind = .profile;
    var multiline_string: ?TomlMultilineStringKind = null;
    var iter = std.mem.splitScalar(u8, bytes, '\n');
    while (iter.next()) |line_raw| {
        if (tomlLineIsMultilineStringBody(&multiline_string, line_raw)) continue;
        const line_without_comment = stripTomlLineComment(line_raw);
        const line = std.mem.trim(u8, line_without_comment, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (line[0] == '[') {
            current_profile_index = null;
            in_profiles_table = false;
            if (isExactTomlSection(line, "profiles")) {
                in_profiles_table = true;
                continue;
            }
            if (try parseConfigReadProfileSection(allocator, line)) |section_value| {
                var section = section_value;
                defer section.deinit(allocator);
                current_profile_index = try ensureConfigReadProfileIndex(allocator, &profiles, section.name);
                current_kind = section.kind;
            }
            continue;
        }
        defer observeTomlMultilineStringOpen(&multiline_string, line_without_comment);

        if (try applyConfigReadProfileDottedAssignment(allocator, &profiles, line)) continue;
        if (in_profiles_table) {
            try applyConfigReadProfilesTableLine(allocator, &profiles, line);
            continue;
        }

        const profile_index = current_profile_index orelse continue;
        if (try applyConfigReadProfileRelativeDottedAssignment(allocator, &profiles.items[profile_index], current_kind, line)) continue;
        switch (current_kind) {
            .profile => try applyConfigReadProfileLine(allocator, &profiles.items[profile_index], line),
            .tools => try applyConfigReadProfileToolsLine(allocator, &profiles.items[profile_index], line),
            .web_search_tool => try applyConfigReadProfileWebSearchToolLine(allocator, &profiles.items[profile_index], line),
            .web_search_location => try applyConfigReadProfileWebSearchLocationLine(allocator, &profiles.items[profile_index], line),
            .analytics => try applyConfigReadProfileAnalyticsLine(&profiles.items[profile_index], line),
        }
    }

    if (profiles.items.len == 0) return ConfigReadProfiles.empty();
    return .{ .items = try profiles.toOwnedSlice(allocator) };
}

fn applyConfigReadProfilesTableLine(
    allocator: std.mem.Allocator,
    profiles: *std.ArrayList(ConfigReadProfile),
    line: []const u8,
) !void {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const lhs = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    var path = (try parseConfigReadTomlDottedPath(allocator, lhs)) orelse return;
    defer path.deinit(allocator);
    try applyConfigReadProfilePathAssignment(allocator, profiles, path.items, rhs);
}

fn ensureConfigReadProfileIndex(
    allocator: std.mem.Allocator,
    profiles: *std.ArrayList(ConfigReadProfile),
    name: []const u8,
) !usize {
    if (findConfigReadProfileIndex(profiles.items, name)) |index| return index;
    const owned_name = try allocator.dupe(u8, name);
    errdefer allocator.free(owned_name);
    try profiles.append(allocator, .{ .name = owned_name });
    return profiles.items.len - 1;
}

fn findConfigReadProfileIndex(profiles: []const ConfigReadProfile, name: []const u8) ?usize {
    for (profiles, 0..) |profile, index| {
        if (std.mem.eql(u8, profile.name, name)) return index;
    }
    return null;
}

fn parseConfigReadProfileSection(allocator: std.mem.Allocator, line: []const u8) !?ConfigReadProfileSection {
    if (line.len < "[]".len or line[0] != '[' or line[line.len - 1] != ']') return null;
    const section = std.mem.trim(u8, line[1 .. line.len - 1], " \t");
    const prefix = "profiles.";
    if (!std.mem.startsWith(u8, section, prefix)) return null;
    const remainder = section[prefix.len..];
    if (remainder.len == 0) return null;

    const name_end = profileSectionNameEnd(remainder) orelse return null;
    const name = (try parseConfigReadAppPathComponent(allocator, remainder[0..name_end])) orelse return null;
    errdefer allocator.free(name);

    const suffix = remainder[name_end..];
    const kind: ConfigReadProfileSectionKind = if (suffix.len == 0)
        .profile
    else if (std.mem.eql(u8, suffix, ".tools"))
        .tools
    else if (std.mem.eql(u8, suffix, ".tools.web_search"))
        .web_search_tool
    else if (std.mem.eql(u8, suffix, ".tools.web_search.location"))
        .web_search_location
    else if (std.mem.eql(u8, suffix, ".analytics"))
        .analytics
    else {
        allocator.free(name);
        return null;
    };

    return .{ .name = name, .kind = kind };
}

fn profileSectionNameEnd(remainder: []const u8) ?usize {
    if (remainder.len == 0) return null;
    if (remainder[0] != '"' and remainder[0] != '\'') {
        return std.mem.indexOfScalar(u8, remainder, '.') orelse remainder.len;
    }

    if (remainder[0] == '\'') {
        var index: usize = 1;
        while (index < remainder.len) : (index += 1) {
            if (remainder[index] == '\'') return index + 1;
        }
        return null;
    }

    var index: usize = 1;
    var escaped = false;
    while (index < remainder.len) : (index += 1) {
        const byte = remainder[index];
        if (escaped) {
            escaped = false;
            continue;
        }
        if (byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == '"') return index + 1;
    }
    return null;
}

const ConfigReadTomlPath = struct {
    items: []const []const u8,

    fn deinit(self: *ConfigReadTomlPath, allocator: std.mem.Allocator) void {
        for (self.items) |item| allocator.free(item);
        allocator.free(self.items);
    }
};

fn applyConfigReadProfileDottedAssignment(
    allocator: std.mem.Allocator,
    profiles: *std.ArrayList(ConfigReadProfile),
    line: []const u8,
) !bool {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return false;
    const lhs = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    if (!std.mem.startsWith(u8, lhs, "profiles") and !std.mem.startsWith(u8, lhs, "\"profiles\"")) return false;
    var path = (try parseConfigReadTomlDottedPath(allocator, lhs)) orelse return false;
    defer path.deinit(allocator);

    if (path.items.len == 0 or !std.mem.eql(u8, path.items[0], "profiles")) return false;
    if (path.items.len == 1) {
        try applyConfigReadProfilesInlineTable(allocator, profiles, rhs);
        return true;
    }

    try applyConfigReadProfilePathAssignment(allocator, profiles, path.items[1..], rhs);
    return true;
}

fn applyConfigReadProfilePathAssignment(
    allocator: std.mem.Allocator,
    profiles: *std.ArrayList(ConfigReadProfile),
    path_items: []const []const u8,
    rhs: []const u8,
) !void {
    if (path_items.len == 0) return;
    const profile_index = try ensureConfigReadProfileIndex(allocator, profiles, path_items[0]);
    try applyConfigReadProfileFieldPath(allocator, &profiles.items[profile_index], path_items[1..], rhs);
}

fn applyConfigReadProfileFieldPath(
    allocator: std.mem.Allocator,
    profile: *ConfigReadProfile,
    path_items: []const []const u8,
    rhs: []const u8,
) !void {
    if (path_items.len == 0) {
        try applyConfigReadProfileInlineTable(allocator, profile, rhs);
    } else if (path_items.len == 1) {
        try applyConfigReadProfileFieldValue(allocator, profile, path_items[0], rhs);
    } else if (std.mem.eql(u8, path_items[0], "tools")) {
        try applyConfigReadProfileToolsPath(allocator, profile, path_items[1..], rhs);
    } else if (std.mem.eql(u8, path_items[0], "analytics")) {
        try applyConfigReadProfileAnalyticsPath(&profile.analytics, path_items[1..], rhs);
    }
}

fn applyConfigReadProfileRelativeDottedAssignment(
    allocator: std.mem.Allocator,
    profile: *ConfigReadProfile,
    section_kind: ConfigReadProfileSectionKind,
    line: []const u8,
) !bool {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return false;
    const lhs = std.mem.trim(u8, line[0..eq], " \t");
    if (std.mem.indexOfScalar(u8, lhs, '.') == null) return false;
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    var path = (try parseConfigReadTomlDottedPath(allocator, lhs)) orelse return false;
    defer path.deinit(allocator);

    switch (section_kind) {
        .profile => try applyConfigReadProfileFieldPath(allocator, profile, path.items, rhs),
        .tools => try applyConfigReadProfileToolsPath(allocator, profile, path.items, rhs),
        .web_search_tool => try applyConfigReadProfileWebSearchPath(allocator, profile, path.items, rhs),
        .web_search_location => try applyConfigReadProfileWebSearchLocationPath(allocator, profile, path.items, rhs),
        .analytics => try applyConfigReadProfileAnalyticsPath(&profile.analytics, path.items, rhs),
    }
    return true;
}

fn parseConfigReadTomlDottedPath(allocator: std.mem.Allocator, raw: []const u8) !?ConfigReadTomlPath {
    var items = std.ArrayList([]const u8).empty;
    errdefer {
        for (items.items) |item| allocator.free(item);
        items.deinit(allocator);
    }

    var index: usize = 0;
    while (index < raw.len) {
        while (index < raw.len and (raw[index] == ' ' or raw[index] == '\t')) index += 1;
        if (index >= raw.len) break;

        const component_start = index;
        if (raw[index] == '"' or raw[index] == '\'') {
            const component_end = profileSectionNameEnd(raw[index..]) orelse return error.InvalidConfigReadProfileDottedKey;
            index += component_end;
        } else {
            while (index < raw.len and raw[index] != '.') index += 1;
        }

        const component_raw = std.mem.trim(u8, raw[component_start..index], " \t");
        const component = (try parseConfigReadAppPathComponent(allocator, component_raw)) orelse return error.InvalidConfigReadProfileDottedKey;
        try items.append(allocator, component);

        while (index < raw.len and (raw[index] == ' ' or raw[index] == '\t')) index += 1;
        if (index >= raw.len) break;
        if (raw[index] != '.') return error.InvalidConfigReadProfileDottedKey;
        index += 1;
    }

    if (items.items.len == 0) return null;
    return .{ .items = try items.toOwnedSlice(allocator) };
}

fn applyConfigReadProfilesInlineTable(
    allocator: std.mem.Allocator,
    profiles: *std.ArrayList(ConfigReadProfile),
    raw: []const u8,
) !void {
    const body = try configReadInlineTableBody(raw);
    var field_start: usize = 0;
    while (try nextConfigReadInlineTableField(body, &field_start)) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, field, '=') orelse return error.InvalidConfigReadInlineTable;
        const key = (try parseConfigReadInlineFieldKey(allocator, field[0..eq])) orelse return error.InvalidConfigReadInlineTable;
        defer allocator.free(key);
        const profile_index = try ensureConfigReadProfileIndex(allocator, profiles, key);
        try applyConfigReadProfileInlineTable(allocator, &profiles.items[profile_index], field[eq + 1 ..]);
    }
}

fn applyConfigReadProfileInlineTable(allocator: std.mem.Allocator, profile: *ConfigReadProfile, raw: []const u8) !void {
    const body = try configReadInlineTableBody(raw);
    var field_start: usize = 0;
    while (try nextConfigReadInlineTableField(body, &field_start)) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, field, '=') orelse return error.InvalidConfigReadInlineTable;
        const key = (try parseConfigReadInlineFieldKey(allocator, field[0..eq])) orelse return error.InvalidConfigReadInlineTable;
        defer allocator.free(key);
        const rhs = std.mem.trim(u8, field[eq + 1 ..], " \t\r\n");
        if (std.mem.eql(u8, key, "tools")) {
            try applyConfigReadProfileToolsInlineTable(allocator, profile, rhs);
        } else if (std.mem.eql(u8, key, "analytics")) {
            try applyConfigReadProfileAnalyticsInlineTable(profile, rhs);
        } else {
            try applyConfigReadProfileFieldValue(allocator, profile, key, rhs);
        }
    }
}

fn applyConfigReadProfileToolsInlineTable(allocator: std.mem.Allocator, profile: *ConfigReadProfile, raw: []const u8) !void {
    const body = try configReadInlineTableBody(raw);
    var field_start: usize = 0;
    while (try nextConfigReadInlineTableField(body, &field_start)) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, field, '=') orelse return error.InvalidConfigReadInlineTable;
        const key = (try parseConfigReadInlineFieldKey(allocator, field[0..eq])) orelse return error.InvalidConfigReadInlineTable;
        defer allocator.free(key);
        const rhs = std.mem.trim(u8, field[eq + 1 ..], " \t\r\n");
        try applyConfigReadProfileToolsField(allocator, profile, key, rhs);
    }
}

fn applyConfigReadProfileWebSearchInlineTable(allocator: std.mem.Allocator, profile: *ConfigReadProfile, raw: []const u8) !void {
    const body = try configReadInlineTableBody(raw);
    var field_start: usize = 0;
    while (try nextConfigReadInlineTableField(body, &field_start)) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, field, '=') orelse return error.InvalidConfigReadInlineTable;
        const key = (try parseConfigReadInlineFieldKey(allocator, field[0..eq])) orelse return error.InvalidConfigReadInlineTable;
        defer allocator.free(key);
        try applyConfigReadProfileWebSearchToolField(allocator, profile, key, field[eq + 1 ..]);
    }
}

fn applyConfigReadProfileAnalyticsInlineTable(profile: *ConfigReadProfile, raw: []const u8) !void {
    try applyConfigReadAnalyticsInlineTable(&profile.analytics, raw);
}

fn applyConfigReadAnalyticsInlineTable(analytics: *ConfigReadAnalytics, raw: []const u8) !void {
    const body = try configReadInlineTableBody(raw);
    analytics.present = true;
    var field_start: usize = 0;
    while (try nextConfigReadInlineTableField(body, &field_start)) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, field, '=') orelse return error.InvalidConfigReadInlineTable;
        const key = std.mem.trim(u8, field[0..eq], " \t\r\n");
        try applyConfigReadProfileAnalyticsField(analytics, key, field[eq + 1 ..]);
    }
}

fn configReadInlineTableBody(raw: []const u8) ![]const u8 {
    const trimmed = std.mem.trim(u8, raw, " \t\r\n");
    if (trimmed.len < 2 or trimmed[0] != '{') return error.InvalidConfigReadInlineTable;
    const close_index = std.mem.lastIndexOfScalar(u8, trimmed, '}') orelse return error.InvalidConfigReadInlineTable;
    return trimmed[1..close_index];
}

fn parseConfigReadInlineFieldKey(allocator: std.mem.Allocator, raw_key: []const u8) !?[]const u8 {
    return parseConfigReadAppPathComponent(allocator, std.mem.trim(u8, raw_key, " \t\r\n"));
}

fn applyConfigReadProfileLine(allocator: std.mem.Allocator, profile: *ConfigReadProfile, line: []const u8) !void {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const key = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    try applyConfigReadProfileFieldValue(allocator, profile, key, rhs);
}

fn applyConfigReadProfileFieldValue(
    allocator: std.mem.Allocator,
    profile: *ConfigReadProfile,
    key: []const u8,
    rhs: []const u8,
) !void {
    if (std.mem.eql(u8, key, "tools")) {
        try applyConfigReadProfileToolsInlineTable(allocator, profile, rhs);
    } else if (std.mem.eql(u8, key, "analytics")) {
        try applyConfigReadProfileAnalyticsInlineTable(profile, rhs);
    } else if (std.mem.eql(u8, key, "model")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        try replaceConfigOptionalString(allocator, &profile.model, value);
    } else if (std.mem.eql(u8, key, "model_provider")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        try replaceConfigOptionalString(allocator, &profile.model_provider, value);
    } else if (std.mem.eql(u8, key, "approval_policy")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        profile.approval_policy = try config.ApprovalPolicy.parse(value);
    } else if (std.mem.eql(u8, key, "approvals_reviewer")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        profile.approvals_reviewer = try config.ApprovalsReviewer.parse(value);
    } else if (std.mem.eql(u8, key, "sandbox_mode")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        profile.sandbox_mode = try config.SandboxMode.parse(value);
    } else if (std.mem.eql(u8, key, "service_tier")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        const normalized = try config.normalizeServiceTier(allocator, value);
        if (profile.service_tier) |existing| allocator.free(existing);
        profile.service_tier = normalized;
    } else if (std.mem.eql(u8, key, "model_reasoning_effort")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        profile.model_reasoning_effort = try config.ReasoningEffort.parse(value);
    } else if (std.mem.eql(u8, key, "model_reasoning_summary")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        profile.model_reasoning_summary = try config.ReasoningSummary.parse(value);
    } else if (std.mem.eql(u8, key, "model_verbosity")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        profile.model_verbosity = try config.Verbosity.parse(value);
    } else if (std.mem.eql(u8, key, "web_search")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        profile.web_search_mode = try config.WebSearchMode.parse(value);
    } else if (std.mem.eql(u8, key, "chatgpt_base_url")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        try replaceConfigOptionalString(allocator, &profile.chatgpt_base_url, value);
    }
}

fn applyConfigReadProfileToolsLine(allocator: std.mem.Allocator, profile: *ConfigReadProfile, line: []const u8) !void {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const key = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    try applyConfigReadProfileToolsField(allocator, profile, key, rhs);
}

fn applyConfigReadProfileToolsField(allocator: std.mem.Allocator, profile: *ConfigReadProfile, key: []const u8, rhs: []const u8) !void {
    if (std.mem.eql(u8, key, "view_image")) {
        profile.tools.present = true;
        profile.tools.view_image = try parseConfigReadBool(rhs);
    } else if (std.mem.eql(u8, key, "web_search")) {
        if (std.mem.eql(u8, rhs, "true") or std.mem.eql(u8, rhs, "false")) {
            profile.tools.present = true;
            return;
        }
        try applyConfigReadProfileWebSearchInlineTable(allocator, profile, rhs);
    }
}

fn applyConfigReadProfileToolsPath(
    allocator: std.mem.Allocator,
    profile: *ConfigReadProfile,
    path_items: []const []const u8,
    rhs: []const u8,
) !void {
    if (path_items.len == 1) {
        try applyConfigReadProfileToolsField(allocator, profile, path_items[0], rhs);
    } else if (path_items.len > 1 and std.mem.eql(u8, path_items[0], "web_search")) {
        try applyConfigReadProfileWebSearchPath(allocator, profile, path_items[1..], rhs);
    }
}

fn applyConfigReadProfileWebSearchToolLine(allocator: std.mem.Allocator, profile: *ConfigReadProfile, line: []const u8) !void {
    profile.tools.present = true;
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const key = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    try applyConfigReadProfileWebSearchToolField(allocator, profile, key, rhs);
}

fn applyConfigReadProfileWebSearchToolField(
    allocator: std.mem.Allocator,
    profile: *ConfigReadProfile,
    key: []const u8,
    rhs_raw: []const u8,
) !void {
    profile.tools.present = true;
    if (profile.tools.web_search == null) profile.tools.web_search = ConfigReadWebSearchTool{};
    const rhs = std.mem.trim(u8, rhs_raw, " \t\r\n");
    if (std.mem.eql(u8, key, "context_size")) {
        const value = try configReadStringValue(allocator, rhs);
        defer allocator.free(value);
        if (!isConfigReadWebSearchContextSize(value)) return error.InvalidConfigReadWebSearchContextSize;
        try replaceConfigOptionalString(allocator, &profile.tools.web_search.?.context_size, value);
    } else if (std.mem.eql(u8, key, "allowed_domains")) {
        const domains = try config.parseTomlStringArray(allocator, rhs) orelse return error.InvalidConfigReadStringArray;
        if (profile.tools.web_search.?.allowed_domains) |*existing| existing.deinit(allocator);
        profile.tools.web_search.?.allowed_domains = domains;
    } else if (std.mem.eql(u8, key, "location")) {
        const location = try parseConfigReadWebSearchLocation(allocator, rhs);
        if (profile.tools.web_search.?.location) |*existing| existing.deinit(allocator);
        profile.tools.web_search.?.location = location;
    }
}

fn applyConfigReadProfileWebSearchPath(
    allocator: std.mem.Allocator,
    profile: *ConfigReadProfile,
    path_items: []const []const u8,
    rhs: []const u8,
) !void {
    if (path_items.len == 1) {
        try applyConfigReadProfileWebSearchToolField(allocator, profile, path_items[0], rhs);
    } else if (path_items.len > 1 and std.mem.eql(u8, path_items[0], "location")) {
        try applyConfigReadProfileWebSearchLocationPath(allocator, profile, path_items[1..], rhs);
    }
}

fn applyConfigReadProfileWebSearchLocationField(
    allocator: std.mem.Allocator,
    profile: *ConfigReadProfile,
    key: []const u8,
    rhs: []const u8,
) !void {
    if (!configReadWebSearchLocationKeySupported(key)) return;
    profile.tools.present = true;
    if (profile.tools.web_search == null) profile.tools.web_search = ConfigReadWebSearchTool{};
    if (profile.tools.web_search.?.location == null) profile.tools.web_search.?.location = ConfigReadWebSearchLocation{};
    const value = try configReadStringValue(allocator, rhs);
    defer allocator.free(value);
    if (profile.tools.web_search.?.location) |*location| {
        if (std.mem.eql(u8, key, "country")) {
            try replaceConfigOptionalString(allocator, &location.country, value);
        } else if (std.mem.eql(u8, key, "region")) {
            try replaceConfigOptionalString(allocator, &location.region, value);
        } else if (std.mem.eql(u8, key, "city")) {
            try replaceConfigOptionalString(allocator, &location.city, value);
        } else if (std.mem.eql(u8, key, "timezone")) {
            try replaceConfigOptionalString(allocator, &location.timezone, value);
        }
    }
}

fn applyConfigReadProfileWebSearchLocationPath(
    allocator: std.mem.Allocator,
    profile: *ConfigReadProfile,
    path_items: []const []const u8,
    rhs: []const u8,
) !void {
    if (path_items.len == 1) {
        try applyConfigReadProfileWebSearchLocationField(allocator, profile, path_items[0], rhs);
    }
}

fn applyConfigReadProfileWebSearchLocationLine(allocator: std.mem.Allocator, profile: *ConfigReadProfile, line: []const u8) !void {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const key = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    try applyConfigReadProfileWebSearchLocationField(allocator, profile, key, rhs);
}

fn applyConfigReadProfileAnalyticsLine(profile: *ConfigReadProfile, line: []const u8) !void {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const key = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    try applyConfigReadProfileAnalyticsField(&profile.analytics, key, rhs);
}

fn applyConfigReadProfileAnalyticsField(analytics: *ConfigReadAnalytics, key: []const u8, rhs_raw: []const u8) !void {
    if (std.mem.eql(u8, key, "enabled")) {
        const rhs = std.mem.trim(u8, rhs_raw, " \t\r\n");
        analytics.enabled = try parseConfigReadBool(rhs);
        analytics.present = true;
    }
}

fn applyConfigReadProfileAnalyticsPath(analytics: *ConfigReadAnalytics, path_items: []const []const u8, rhs: []const u8) !void {
    if (path_items.len == 1) {
        try applyConfigReadProfileAnalyticsField(analytics, path_items[0], rhs);
    }
}

fn configReadStringValue(allocator: std.mem.Allocator, rhs: []const u8) ![]const u8 {
    return try config.parseTomlStringValue(allocator, rhs) orelse error.InvalidConfigReadString;
}

fn configReadStringLineValue(allocator: std.mem.Allocator, line: []const u8, key: []const u8) !?[]const u8 {
    const rhs = tomlValueForKey(line, key) orelse return null;
    return try config.parseTomlStringValue(allocator, rhs) orelse error.InvalidConfigReadString;
}

fn configReadStringArrayLineValue(allocator: std.mem.Allocator, line: []const u8, key: []const u8) !?config.StringList {
    const rhs = tomlValueForKey(line, key) orelse return null;
    return try config.parseTomlStringArray(allocator, rhs) orelse error.InvalidConfigReadStringArray;
}

fn loadConfigReadAnalytics(allocator: std.mem.Allocator, bytes: []const u8) !ConfigReadAnalytics {
    var analytics = ConfigReadAnalytics{};
    var in_section = false;
    var top_level = true;
    var multiline_string: ?TomlMultilineStringKind = null;
    var iter = std.mem.splitScalar(u8, bytes, '\n');
    while (iter.next()) |line_raw| {
        if (tomlLineIsMultilineStringBody(&multiline_string, line_raw)) continue;
        const line_without_comment = stripTomlLineComment(line_raw);
        const line = std.mem.trim(u8, line_without_comment, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (line[0] == '[') {
            top_level = false;
            in_section = isExactTomlSection(line, "analytics");
            if (in_section) analytics.present = true;
            continue;
        }
        defer observeTomlMultilineStringOpen(&multiline_string, line_without_comment);
        if (top_level and try applyConfigReadAnalyticsTopLevelAssignment(allocator, &analytics, line)) continue;
        if (!in_section) continue;
        if (tomlValueForKey(line, "enabled")) |rhs| {
            analytics.enabled = try parseConfigReadBool(rhs);
            analytics.present = true;
        }
    }
    return analytics;
}

fn applyConfigReadAnalyticsTopLevelAssignment(
    allocator: std.mem.Allocator,
    analytics: *ConfigReadAnalytics,
    line: []const u8,
) !bool {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return false;
    const lhs = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    var path = (try parseConfigReadTomlDottedPath(allocator, lhs)) orelse return false;
    defer path.deinit(allocator);

    if (path.items.len == 2 and
        std.mem.eql(u8, path.items[0], "analytics") and
        std.mem.eql(u8, path.items[1], "enabled"))
    {
        try applyConfigReadProfileAnalyticsField(analytics, "enabled", rhs);
        return true;
    }
    if (path.items.len == 1 and std.mem.eql(u8, path.items[0], "analytics")) {
        try applyConfigReadAnalyticsInlineTable(analytics, rhs);
        return true;
    }
    return false;
}

fn mergeConfigReadAnalytics(target: *ConfigReadAnalytics, source: ConfigReadAnalytics) void {
    if (source.present) target.present = true;
    if (target.enabled == null and source.enabled != null) target.enabled = source.enabled;
}

fn effectiveConfigReadAnalytics(
    managed_layer: ?ConfigReadManagedLayer,
    project_layers: ConfigReadProjectLayers,
    user_layer: ?ConfigReadUserLayer,
    system_layer: ?ConfigReadSystemLayer,
    active_profile: ?[]const u8,
) ?ConfigReadAnalytics {
    var analytics = ConfigReadAnalytics{};
    if (managed_layer) |layer| {
        mergeConfigReadLayerAnalytics(&analytics, layer.profiles, layer.analytics, active_profile);
    }
    for (project_layers.items) |layer| {
        mergeConfigReadLayerAnalytics(&analytics, layer.profiles, layer.analytics, active_profile);
    }
    if (user_layer) |layer| {
        mergeConfigReadLayerAnalytics(&analytics, layer.profiles, layer.analytics, active_profile);
    }
    if (system_layer) |layer| {
        mergeConfigReadLayerAnalytics(&analytics, layer.profiles, layer.analytics, active_profile);
    }
    return if (analytics.present) analytics else null;
}

fn mergeConfigReadLayerAnalytics(
    target: *ConfigReadAnalytics,
    profiles: ConfigReadProfiles,
    analytics: ConfigReadAnalytics,
    active_profile: ?[]const u8,
) void {
    if (active_profile) |profile_name| {
        if (configReadProfileAnalytics(profiles, profile_name)) |profile_analytics| {
            mergeConfigReadAnalytics(target, profile_analytics);
        }
    }
    mergeConfigReadAnalytics(target, analytics);
}

fn configReadProfileAnalytics(profiles: ConfigReadProfiles, profile_name: []const u8) ?ConfigReadAnalytics {
    if (findConfigReadProfileIndex(profiles.items, profile_name)) |index| {
        const analytics = profiles.items[index].analytics;
        return if (analytics.present) analytics else null;
    }
    return null;
}

const ConfigReadTools = struct {
    present: bool = false,
    web_search: ?ConfigReadWebSearchTool = null,
    view_image: ?bool = null,

    fn deinit(self: *ConfigReadTools, allocator: std.mem.Allocator) void {
        if (self.web_search) |*tool| tool.deinit(allocator);
    }
};

const ConfigReadWebSearchTool = struct {
    context_size: ?[]const u8 = null,
    allowed_domains: ?config.StringList = null,
    location: ?ConfigReadWebSearchLocation = null,

    fn deinit(self: *ConfigReadWebSearchTool, allocator: std.mem.Allocator) void {
        if (self.context_size) |value| allocator.free(value);
        if (self.allowed_domains) |*domains| domains.deinit(allocator);
        if (self.location) |*location| location.deinit(allocator);
    }
};

const ConfigReadWebSearchLocation = struct {
    country: ?[]const u8 = null,
    region: ?[]const u8 = null,
    city: ?[]const u8 = null,
    timezone: ?[]const u8 = null,

    fn deinit(self: *ConfigReadWebSearchLocation, allocator: std.mem.Allocator) void {
        if (self.country) |value| allocator.free(value);
        if (self.region) |value| allocator.free(value);
        if (self.city) |value| allocator.free(value);
        if (self.timezone) |value| allocator.free(value);
    }
};

const ConfigReadApps = struct {
    default_config: ?ConfigReadAppsDefault = null,
    items: []ConfigReadApp,

    fn empty() ConfigReadApps {
        return .{ .items = &.{} };
    }

    fn isEmpty(self: ConfigReadApps) bool {
        return self.default_config == null and self.items.len == 0;
    }

    fn deinit(self: *ConfigReadApps, allocator: std.mem.Allocator) void {
        for (self.items) |*app| app.deinit(allocator);
        if (self.items.len > 0) allocator.free(self.items);
    }
};

const ConfigReadAppsDefault = struct {
    enabled: bool = true,
    enabled_present: bool = false,
    destructive_enabled: bool = true,
    destructive_enabled_present: bool = false,
    open_world_enabled: bool = true,
    open_world_enabled_present: bool = false,
};

const ConfigReadApp = struct {
    name: []const u8,
    enabled: bool = true,
    has_enabled: bool = false,
    destructive_enabled: ?bool = null,
    open_world_enabled: ?bool = null,
    default_tools_approval_mode: ?[]const u8 = null,
    default_tools_enabled: ?bool = null,
    tools: std.ArrayList(ConfigReadAppTool) = .empty,

    fn deinit(self: *ConfigReadApp, allocator: std.mem.Allocator) void {
        allocator.free(self.name);
        if (self.default_tools_approval_mode) |value| allocator.free(value);
        for (self.tools.items) |*tool| tool.deinit(allocator);
        self.tools.deinit(allocator);
    }
};

const ConfigReadAppTool = struct {
    name: []const u8,
    enabled: ?bool = null,
    approval_mode: ?[]const u8 = null,

    fn deinit(self: *ConfigReadAppTool, allocator: std.mem.Allocator) void {
        allocator.free(self.name);
        if (self.approval_mode) |value| allocator.free(value);
    }
};

const ConfigReadSandboxWorkspaceWrite = struct {
    present: bool = false,
    writable_roots: ?config.StringList = null,
    network_access: bool = false,
    network_access_present: bool = false,
    exclude_tmpdir_env_var: bool = false,
    exclude_tmpdir_env_var_present: bool = false,
    exclude_slash_tmp: bool = false,
    exclude_slash_tmp_present: bool = false,

    fn deinit(self: *ConfigReadSandboxWorkspaceWrite, allocator: std.mem.Allocator) void {
        if (self.writable_roots) |*roots| roots.deinit(allocator);
    }
};

fn effectiveConfigReadSandboxWorkspaceWrite(
    managed_layer: ?ConfigReadManagedLayer,
    project_layers: ConfigReadProjectLayers,
    user_layer: ?ConfigReadUserLayer,
    system_layer: ?ConfigReadSystemLayer,
) ?ConfigReadSandboxWorkspaceWrite {
    const managed = if (managed_layer) |layer| layer.sandbox_workspace_write else ConfigReadSandboxWorkspaceWrite{};
    const project = project_layers.sandboxWorkspaceWrite();
    const user = if (user_layer) |layer| layer.sandbox_workspace_write else ConfigReadSandboxWorkspaceWrite{};
    const system = if (system_layer) |layer| layer.sandbox_workspace_write else ConfigReadSandboxWorkspaceWrite{};
    if (!managed.present and !project.present and !user.present and !system.present) return null;

    return .{
        .present = true,
        .writable_roots = managed.writable_roots orelse project.writable_roots orelse user.writable_roots orelse system.writable_roots,
        .network_access = if (managed.network_access_present) managed.network_access else if (project.network_access_present) project.network_access else if (user.network_access_present) user.network_access else system.network_access,
        .network_access_present = managed.network_access_present or project.network_access_present or user.network_access_present or system.network_access_present,
        .exclude_tmpdir_env_var = if (managed.exclude_tmpdir_env_var_present) managed.exclude_tmpdir_env_var else if (project.exclude_tmpdir_env_var_present) project.exclude_tmpdir_env_var else if (user.exclude_tmpdir_env_var_present) user.exclude_tmpdir_env_var else system.exclude_tmpdir_env_var,
        .exclude_tmpdir_env_var_present = managed.exclude_tmpdir_env_var_present or project.exclude_tmpdir_env_var_present or user.exclude_tmpdir_env_var_present or system.exclude_tmpdir_env_var_present,
        .exclude_slash_tmp = if (managed.exclude_slash_tmp_present) managed.exclude_slash_tmp else if (project.exclude_slash_tmp_present) project.exclude_slash_tmp else if (user.exclude_slash_tmp_present) user.exclude_slash_tmp else system.exclude_slash_tmp,
        .exclude_slash_tmp_present = managed.exclude_slash_tmp_present or project.exclude_slash_tmp_present or user.exclude_slash_tmp_present or system.exclude_slash_tmp_present,
    };
}

fn effectiveConfigReadTools(
    managed_layer: ?ConfigReadManagedLayer,
    project_layers: ConfigReadProjectLayers,
    user_layer: ?ConfigReadUserLayer,
    system_layer: ?ConfigReadSystemLayer,
) ?ConfigReadTools {
    var tools = ConfigReadTools{};
    if (managed_layer) |layer| mergeConfigReadTools(&tools, layer.tools);
    mergeConfigReadTools(&tools, project_layers.tools());
    if (user_layer) |layer| mergeConfigReadTools(&tools, layer.tools);
    if (system_layer) |layer| mergeConfigReadTools(&tools, layer.tools);
    if (!tools.present) return null;
    return tools;
}

fn effectiveConfigReadApps(
    allocator: std.mem.Allocator,
    managed_layer: ?ConfigReadManagedLayer,
    project_layers: ConfigReadProjectLayers,
    user_layer: ?ConfigReadUserLayer,
    system_layer: ?ConfigReadSystemLayer,
    app_requirements: ?plugin_list.AppRequirements,
) !?ConfigReadApps {
    var default_config: ?ConfigReadAppsDefault = null;
    var items = std.ArrayList(ConfigReadApp).empty;
    errdefer {
        for (items.items) |*app| app.deinit(allocator);
        items.deinit(allocator);
    }

    if (managed_layer) |layer| try mergeConfigReadApps(allocator, &default_config, &items, layer.apps);
    for (project_layers.items) |layer| try mergeConfigReadApps(allocator, &default_config, &items, layer.apps);
    if (user_layer) |layer| try mergeConfigReadApps(allocator, &default_config, &items, layer.apps);
    if (system_layer) |layer| try mergeConfigReadApps(allocator, &default_config, &items, layer.apps);
    try applyConfigReadAppRequirements(allocator, &items, app_requirements);
    if (default_config == null and items.items.len == 0) return null;

    return .{
        .default_config = default_config,
        .items = if (items.items.len == 0) &.{} else try items.toOwnedSlice(allocator),
    };
}

fn applyConfigReadAppRequirements(
    allocator: std.mem.Allocator,
    items: *std.ArrayList(ConfigReadApp),
    app_requirements: ?plugin_list.AppRequirements,
) !void {
    const requirements = app_requirements orelse return;
    for (requirements.disabled_ids) |app_id| {
        const app = try ensureConfigReadApp(allocator, items, app_id);
        app.enabled = false;
        app.has_enabled = true;
    }
}

fn mergeConfigReadApps(
    allocator: std.mem.Allocator,
    default_config: *?ConfigReadAppsDefault,
    items: *std.ArrayList(ConfigReadApp),
    source: ConfigReadApps,
) !void {
    if (source.default_config) |source_default| {
        if (default_config.* == null) default_config.* = ConfigReadAppsDefault{};
        mergeConfigReadAppsDefault(&default_config.*.?, source_default);
    }
    for (source.items) |source_app| {
        const target_app = try ensureConfigReadApp(allocator, items, source_app.name);
        try mergeConfigReadApp(allocator, target_app, source_app);
    }
}

fn mergeConfigReadAppsDefault(target: *ConfigReadAppsDefault, source: ConfigReadAppsDefault) void {
    if (!target.enabled_present and source.enabled_present) {
        target.enabled = source.enabled;
        target.enabled_present = true;
    }
    if (!target.destructive_enabled_present and source.destructive_enabled_present) {
        target.destructive_enabled = source.destructive_enabled;
        target.destructive_enabled_present = true;
    }
    if (!target.open_world_enabled_present and source.open_world_enabled_present) {
        target.open_world_enabled = source.open_world_enabled;
        target.open_world_enabled_present = true;
    }
}

fn ensureConfigReadApp(
    allocator: std.mem.Allocator,
    items: *std.ArrayList(ConfigReadApp),
    name: []const u8,
) !*ConfigReadApp {
    if (findConfigReadAppIndex(items.items, name)) |index| return &items.items[index];
    const owned_name = try allocator.dupe(u8, name);
    errdefer allocator.free(owned_name);
    try items.append(allocator, .{ .name = owned_name });
    return &items.items[items.items.len - 1];
}

fn mergeConfigReadApp(
    allocator: std.mem.Allocator,
    target: *ConfigReadApp,
    source: ConfigReadApp,
) !void {
    if (!target.has_enabled and source.has_enabled) {
        target.enabled = source.enabled;
        target.has_enabled = true;
    }
    if (target.destructive_enabled == null) target.destructive_enabled = source.destructive_enabled;
    if (target.open_world_enabled == null) target.open_world_enabled = source.open_world_enabled;
    if (target.default_tools_enabled == null) target.default_tools_enabled = source.default_tools_enabled;
    if (target.default_tools_approval_mode == null) {
        if (source.default_tools_approval_mode) |value| {
            target.default_tools_approval_mode = try allocator.dupe(u8, value);
        }
    }
    for (source.tools.items) |source_tool| {
        const target_tool = try ensureConfigReadAppTool(allocator, &target.tools, source_tool.name);
        try mergeConfigReadAppTool(allocator, target_tool, source_tool);
    }
}

fn ensureConfigReadAppTool(
    allocator: std.mem.Allocator,
    tools: *std.ArrayList(ConfigReadAppTool),
    name: []const u8,
) !*ConfigReadAppTool {
    if (findConfigReadAppToolIndex(tools.items, name)) |index| return &tools.items[index];
    const owned_name = try allocator.dupe(u8, name);
    errdefer allocator.free(owned_name);
    try tools.append(allocator, .{ .name = owned_name });
    return &tools.items[tools.items.len - 1];
}

fn mergeConfigReadAppTool(
    allocator: std.mem.Allocator,
    target: *ConfigReadAppTool,
    source: ConfigReadAppTool,
) !void {
    if (target.enabled == null) target.enabled = source.enabled;
    if (target.approval_mode == null) {
        if (source.approval_mode) |value| {
            target.approval_mode = try allocator.dupe(u8, value);
        }
    }
}

fn mergeConfigReadTools(target: *ConfigReadTools, source: ConfigReadTools) void {
    if (source.present) target.present = true;
    if (target.view_image == null) target.view_image = source.view_image;
    if (source.web_search) |source_web_search| {
        if (target.web_search == null) target.web_search = ConfigReadWebSearchTool{};
        mergeConfigReadWebSearchTool(&target.web_search.?, source_web_search);
    }
}

fn mergeConfigReadWebSearchTool(target: *ConfigReadWebSearchTool, source: ConfigReadWebSearchTool) void {
    if (target.context_size == null) target.context_size = source.context_size;
    if (target.allowed_domains == null) target.allowed_domains = source.allowed_domains;
    if (source.location) |source_location| {
        if (target.location == null) target.location = ConfigReadWebSearchLocation{};
        mergeConfigReadWebSearchLocation(&target.location.?, source_location);
    }
}

fn mergeConfigReadWebSearchLocation(target: *ConfigReadWebSearchLocation, source: ConfigReadWebSearchLocation) void {
    if (target.country == null) target.country = source.country;
    if (target.region == null) target.region = source.region;
    if (target.city == null) target.city = source.city;
    if (target.timezone == null) target.timezone = source.timezone;
}

fn loadConfigReadTools(allocator: std.mem.Allocator, bytes: []const u8) !ConfigReadTools {
    var tools = ConfigReadTools{};
    errdefer tools.deinit(allocator);

    if (configReadSectionHasKey(bytes, "tools", "web_search")) {
        tools.present = true;
    }
    if (config.sectionBoolValue(bytes, "tools", "view_image")) |value| {
        tools.view_image = value;
        tools.present = true;
    }
    if (try loadConfigReadWebSearchTool(allocator, bytes)) |web_search| {
        tools.web_search = web_search;
        tools.present = true;
    }

    return tools;
}

fn appendConfigReadToolsOriginKeys(
    allocator: std.mem.Allocator,
    origin_keys: *std.ArrayList([]const u8),
    tools: ConfigReadTools,
) !void {
    if (tools.web_search) |web_search| {
        if (web_search.context_size != null) {
            try appendUniqueOriginKey(allocator, origin_keys, "tools.web_search.context_size");
        }
        if (web_search.allowed_domains) |domains| {
            for (domains.items, 0..) |_, index| {
                const key = try std.fmt.allocPrint(allocator, "tools.web_search.allowed_domains.{d}", .{index});
                defer allocator.free(key);
                try appendUniqueOriginKey(allocator, origin_keys, key);
            }
        }
        if (web_search.location) |location| {
            if (location.country != null) {
                try appendUniqueOriginKey(allocator, origin_keys, "tools.web_search.location.country");
            }
            if (location.region != null) {
                try appendUniqueOriginKey(allocator, origin_keys, "tools.web_search.location.region");
            }
            if (location.city != null) {
                try appendUniqueOriginKey(allocator, origin_keys, "tools.web_search.location.city");
            }
            if (location.timezone != null) {
                try appendUniqueOriginKey(allocator, origin_keys, "tools.web_search.location.timezone");
            }
        }
    }
    if (tools.view_image != null) {
        try appendUniqueOriginKey(allocator, origin_keys, "tools.view_image");
    }
}

fn loadConfigReadWebSearchTool(allocator: std.mem.Allocator, bytes: []const u8) !?ConfigReadWebSearchTool {
    if (!configReadSectionExists(bytes, "tools.web_search")) return null;

    var tool = ConfigReadWebSearchTool{};
    errdefer tool.deinit(allocator);

    if (try config.sectionStringValue(allocator, bytes, "tools.web_search", "context_size")) |value| {
        errdefer allocator.free(value);
        if (!isConfigReadWebSearchContextSize(value)) return error.InvalidConfigReadWebSearchContextSize;
        tool.context_size = value;
    }
    if (try config.sectionStringArrayValue(allocator, bytes, "tools.web_search", "allowed_domains")) |domains| {
        tool.allowed_domains = domains;
    }
    if (configReadSectionRawValue(bytes, "tools.web_search", "location")) |raw_location| {
        tool.location = try parseConfigReadWebSearchLocation(allocator, raw_location);
    }

    return tool;
}

fn isConfigReadWebSearchContextSize(value: []const u8) bool {
    return std.mem.eql(u8, value, "low") or
        std.mem.eql(u8, value, "medium") or
        std.mem.eql(u8, value, "high");
}

fn parseConfigReadWebSearchLocation(allocator: std.mem.Allocator, raw: []const u8) !ConfigReadWebSearchLocation {
    const trimmed = std.mem.trim(u8, raw, " \t\r");
    if (trimmed.len < 2 or trimmed[0] != '{') return error.InvalidConfigReadWebSearchLocation;
    const close_index = std.mem.lastIndexOfScalar(u8, trimmed, '}') orelse return error.InvalidConfigReadWebSearchLocation;
    const body = trimmed[1..close_index];

    var location = ConfigReadWebSearchLocation{};
    errdefer location.deinit(allocator);

    var field_start: usize = 0;
    while (try nextConfigReadInlineTableField(body, &field_start)) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, field, '=') orelse return error.InvalidConfigReadWebSearchLocation;
        const key = std.mem.trim(u8, field[0..eq], " \t\r\n");
        if (!configReadWebSearchLocationKeySupported(key)) continue;

        const value_rhs = std.mem.trim(u8, field[eq + 1 ..], " \t\r\n");
        const value = try config.parseTomlString(allocator, value_rhs) orelse return error.InvalidConfigReadWebSearchLocation;
        errdefer allocator.free(value);
        if (std.mem.eql(u8, key, "country")) {
            if (location.country) |existing| allocator.free(existing);
            location.country = value;
        } else if (std.mem.eql(u8, key, "region")) {
            if (location.region) |existing| allocator.free(existing);
            location.region = value;
        } else if (std.mem.eql(u8, key, "city")) {
            if (location.city) |existing| allocator.free(existing);
            location.city = value;
        } else if (std.mem.eql(u8, key, "timezone")) {
            if (location.timezone) |existing| allocator.free(existing);
            location.timezone = value;
        }
    }

    return location;
}

fn nextConfigReadInlineTableField(body: []const u8, start: *usize) !?[]const u8 {
    while (start.* < body.len and (body[start.*] == ',' or body[start.*] == ' ' or body[start.*] == '\t' or body[start.*] == '\r' or body[start.*] == '\n')) {
        start.* += 1;
    }
    if (start.* >= body.len) return null;

    const field_start = start.*;
    var index = start.*;
    var string_quote: u8 = 0;
    var escaped = false;
    var bracket_depth: usize = 0;
    var brace_depth: usize = 0;
    while (index < body.len) : (index += 1) {
        const byte = body[index];
        if (string_quote != 0) {
            if (string_quote == '"' and escaped) {
                escaped = false;
            } else if (string_quote == '"' and byte == '\\') {
                escaped = true;
            } else if (byte == string_quote) {
                string_quote = 0;
            }
            continue;
        }
        if (byte == '"' or byte == '\'') {
            string_quote = byte;
        } else if (byte == '[') {
            bracket_depth += 1;
        } else if (byte == ']') {
            if (bracket_depth == 0) return error.InvalidConfigReadInlineTable;
            bracket_depth -= 1;
        } else if (byte == '{') {
            brace_depth += 1;
        } else if (byte == '}') {
            if (brace_depth == 0) return error.InvalidConfigReadInlineTable;
            brace_depth -= 1;
        } else if (byte == ',' and bracket_depth == 0 and brace_depth == 0) {
            start.* = index + 1;
            return body[field_start..index];
        }
    }
    if (string_quote != 0 or escaped or bracket_depth != 0 or brace_depth != 0) return error.InvalidConfigReadInlineTable;

    start.* = index;
    return body[field_start..index];
}

fn configReadWebSearchLocationKeySupported(key: []const u8) bool {
    return std.mem.eql(u8, key, "country") or
        std.mem.eql(u8, key, "region") or
        std.mem.eql(u8, key, "city") or
        std.mem.eql(u8, key, "timezone");
}

fn configReadSectionExists(bytes: []const u8, section_name: []const u8) bool {
    var iter = std.mem.splitScalar(u8, bytes, '\n');
    while (iter.next()) |line_raw| {
        const line = std.mem.trim(u8, line_raw, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (configReadLineIsExactSection(line, section_name)) return true;
    }
    return false;
}

fn configReadSectionHasKey(bytes: []const u8, section_name: []const u8, key: []const u8) bool {
    return configReadSectionRawValue(bytes, section_name, key) != null;
}

fn configReadSectionRawValue(bytes: []const u8, section_name: []const u8, key: []const u8) ?[]const u8 {
    var in_section = false;
    var iter = std.mem.splitScalar(u8, bytes, '\n');
    while (iter.next()) |line_raw| {
        const line = std.mem.trim(u8, line_raw, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (line[0] == '[') {
            in_section = configReadLineIsExactSection(line, section_name);
            continue;
        }
        if (!in_section) continue;
        const eq = std.mem.indexOfScalar(u8, line, '=') orelse continue;
        const lhs = std.mem.trim(u8, line[0..eq], " \t");
        if (!std.mem.eql(u8, lhs, key)) continue;
        return std.mem.trim(u8, line[eq + 1 ..], " \t");
    }
    return null;
}

fn configReadLineIsExactSection(line: []const u8, section_name: []const u8) bool {
    if (line.len < 2 or line[0] != '[' or line[line.len - 1] != ']') return false;
    const section = std.mem.trim(u8, line[1 .. line.len - 1], " \t");
    return std.mem.eql(u8, section, section_name);
}

fn loadConfigReadApps(allocator: std.mem.Allocator, bytes: []const u8) !ConfigReadApps {
    var apps = std.ArrayList(ConfigReadApp).empty;
    errdefer {
        for (apps.items) |*app| app.deinit(allocator);
        apps.deinit(allocator);
    }

    var default_config: ?ConfigReadAppsDefault = null;
    var in_default_section = false;
    var current_app_index: ?usize = null;
    var current_tool_app_index: ?usize = null;
    var current_tool_index: ?usize = null;
    var iter = std.mem.splitScalar(u8, bytes, '\n');
    while (iter.next()) |line_raw| {
        const line = std.mem.trim(u8, line_raw, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (line[0] == '[') {
            in_default_section = false;
            current_app_index = null;
            current_tool_app_index = null;
            current_tool_index = null;
            if (try parseConfigReadAppToolSection(allocator, line)) |section| {
                var owned_app_name: ?[]const u8 = section.app_name;
                var owned_tool_name: ?[]const u8 = section.tool_name;
                errdefer if (owned_app_name) |value| allocator.free(value);
                errdefer if (owned_tool_name) |value| allocator.free(value);

                if (std.mem.eql(u8, section.app_name, "_default")) {
                    allocator.free(section.app_name);
                    allocator.free(section.tool_name);
                    continue;
                }

                current_tool_app_index = findConfigReadAppIndex(apps.items, section.app_name);
                if (current_tool_app_index == null) {
                    try apps.append(allocator, .{ .name = section.app_name });
                    current_tool_app_index = apps.items.len - 1;
                    owned_app_name = null;
                }
                if (owned_app_name) |value| {
                    allocator.free(value);
                    owned_app_name = null;
                }

                const app_index = current_tool_app_index.?;
                current_tool_index = findConfigReadAppToolIndex(apps.items[app_index].tools.items, section.tool_name);
                if (current_tool_index == null) {
                    try apps.items[app_index].tools.append(allocator, .{ .name = section.tool_name });
                    current_tool_index = apps.items[app_index].tools.items.len - 1;
                    owned_tool_name = null;
                }
                if (owned_tool_name) |value| {
                    allocator.free(value);
                    owned_tool_name = null;
                }
                continue;
            }
            if (try parseConfigReadAppSectionName(allocator, line)) |name| {
                var owned_name: ?[]const u8 = name;
                errdefer if (owned_name) |value| allocator.free(value);
                if (std.mem.eql(u8, name, "_default")) {
                    default_config = default_config orelse ConfigReadAppsDefault{};
                    in_default_section = true;
                    allocator.free(name);
                    continue;
                }
                current_app_index = findConfigReadAppIndex(apps.items, name);
                if (current_app_index == null) {
                    try apps.append(allocator, .{ .name = name });
                    current_app_index = apps.items.len - 1;
                    owned_name = null;
                }
                if (owned_name) |value| allocator.free(value);
            }
            continue;
        }

        if (in_default_section) {
            try applyConfigReadAppsDefaultLine(&default_config.?, line);
            continue;
        }
        if (current_tool_app_index) |app_index| {
            if (current_tool_index) |tool_index| {
                try applyConfigReadAppToolLine(allocator, &apps.items[app_index].tools.items[tool_index], line);
                continue;
            }
        }
        const app_index = current_app_index orelse continue;
        try applyConfigReadAppLine(allocator, &apps.items[app_index], line);
    }

    if (apps.items.len == 0 and default_config == null) return ConfigReadApps.empty();
    return .{
        .default_config = default_config,
        .items = if (apps.items.len == 0) &.{} else try apps.toOwnedSlice(allocator),
    };
}

fn parseConfigReadAppSectionName(allocator: std.mem.Allocator, line: []const u8) !?[]const u8 {
    if (line.len < 2 or line[0] != '[' or line[line.len - 1] != ']') return null;
    const section = std.mem.trim(u8, line[1 .. line.len - 1], " \t");
    const prefix = "apps.";
    if (!std.mem.startsWith(u8, section, prefix)) return null;
    const raw_name = section[prefix.len..];
    return parseConfigReadAppPathComponent(allocator, raw_name);
}

const ConfigReadAppToolSection = struct {
    app_name: []const u8,
    tool_name: []const u8,
};

fn parseConfigReadAppToolSection(allocator: std.mem.Allocator, line: []const u8) !?ConfigReadAppToolSection {
    if (line.len < 2 or line[0] != '[' or line[line.len - 1] != ']') return null;
    const section = std.mem.trim(u8, line[1 .. line.len - 1], " \t");
    const prefix = "apps.";
    if (!std.mem.startsWith(u8, section, prefix)) return null;
    const marker = ".tools.";
    const marker_index = std.mem.indexOf(u8, section, marker) orelse return null;
    const raw_app_name = section[prefix.len..marker_index];
    const raw_tool_name = section[marker_index + marker.len ..];
    const app_name = (try parseConfigReadAppPathComponent(allocator, raw_app_name)) orelse return null;
    errdefer allocator.free(app_name);
    const tool_name = (try parseConfigReadAppPathComponent(allocator, raw_tool_name)) orelse {
        allocator.free(app_name);
        return null;
    };
    return .{ .app_name = app_name, .tool_name = tool_name };
}

fn parseConfigReadAppPathComponent(allocator: std.mem.Allocator, raw_name: []const u8) !?[]const u8 {
    if (raw_name.len == 0) return null;
    if (raw_name[0] == '"') {
        const name_end = profileSectionNameEnd(raw_name) orelse return error.InvalidConfigReadAppSection;
        if (name_end != raw_name.len) return null;
        return try config.parseTomlString(allocator, raw_name) orelse error.InvalidConfigReadAppSection;
    }
    if (raw_name[0] == '\'') {
        const name_end = profileSectionNameEnd(raw_name) orelse return error.InvalidConfigReadAppSection;
        if (name_end != raw_name.len) return null;
        return try parseConfigReadTomlLiteralString(allocator, raw_name);
    }
    if (std.mem.indexOfScalar(u8, raw_name, '.') != null) return null;
    return @as(?[]const u8, try allocator.dupe(u8, raw_name));
}

fn parseConfigReadTomlLiteralString(allocator: std.mem.Allocator, rhs: []const u8) ![]const u8 {
    if (rhs.len < 2 or rhs[0] != '\'') return error.InvalidTomlString;
    var index: usize = 1;
    while (index < rhs.len) : (index += 1) {
        if (rhs[index] == '\'') {
            if (index + 1 != rhs.len) return error.InvalidTomlString;
            return allocator.dupe(u8, rhs[1..index]);
        }
    }
    return error.InvalidTomlString;
}

fn findConfigReadAppIndex(apps: []const ConfigReadApp, name: []const u8) ?usize {
    for (apps, 0..) |app, index| {
        if (std.mem.eql(u8, app.name, name)) return index;
    }
    return null;
}

fn findConfigReadAppToolIndex(tools: []const ConfigReadAppTool, name: []const u8) ?usize {
    for (tools, 0..) |tool, index| {
        if (std.mem.eql(u8, tool.name, name)) return index;
    }
    return null;
}

fn applyConfigReadAppsDefaultLine(default_config: *ConfigReadAppsDefault, line: []const u8) !void {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const key = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    if (std.mem.eql(u8, key, "enabled")) {
        default_config.enabled = try parseConfigReadBool(rhs);
        default_config.enabled_present = true;
    } else if (std.mem.eql(u8, key, "destructive_enabled")) {
        default_config.destructive_enabled = try parseConfigReadBool(rhs);
        default_config.destructive_enabled_present = true;
    } else if (std.mem.eql(u8, key, "open_world_enabled")) {
        default_config.open_world_enabled = try parseConfigReadBool(rhs);
        default_config.open_world_enabled_present = true;
    }
}

fn applyConfigReadAppToolLine(allocator: std.mem.Allocator, tool: *ConfigReadAppTool, line: []const u8) !void {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const key = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    if (std.mem.eql(u8, key, "enabled")) {
        tool.enabled = try parseConfigReadBool(rhs);
    } else if (std.mem.eql(u8, key, "approval_mode")) {
        const value = try config.parseTomlString(allocator, rhs) orelse return error.InvalidConfigReadAppToolApproval;
        errdefer allocator.free(value);
        if (!isConfigReadAppToolApproval(value)) return error.InvalidConfigReadAppToolApproval;
        if (tool.approval_mode) |existing| allocator.free(existing);
        tool.approval_mode = value;
    }
}

fn applyConfigReadAppLine(allocator: std.mem.Allocator, app: *ConfigReadApp, line: []const u8) !void {
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse return;
    const key = std.mem.trim(u8, line[0..eq], " \t");
    const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
    if (std.mem.eql(u8, key, "enabled")) {
        app.enabled = try parseConfigReadBool(rhs);
        app.has_enabled = true;
    } else if (std.mem.eql(u8, key, "destructive_enabled")) {
        app.destructive_enabled = try parseConfigReadBool(rhs);
    } else if (std.mem.eql(u8, key, "open_world_enabled")) {
        app.open_world_enabled = try parseConfigReadBool(rhs);
    } else if (std.mem.eql(u8, key, "default_tools_enabled")) {
        app.default_tools_enabled = try parseConfigReadBool(rhs);
    } else if (std.mem.eql(u8, key, "default_tools_approval_mode")) {
        const value = try config.parseTomlString(allocator, rhs) orelse return error.InvalidConfigReadAppToolApproval;
        errdefer allocator.free(value);
        if (!isConfigReadAppToolApproval(value)) return error.InvalidConfigReadAppToolApproval;
        if (app.default_tools_approval_mode) |existing| allocator.free(existing);
        app.default_tools_approval_mode = value;
    }
}

fn parseConfigReadBool(rhs: []const u8) !bool {
    if (std.mem.eql(u8, rhs, "true")) return true;
    if (std.mem.eql(u8, rhs, "false")) return false;
    return error.InvalidConfigReadBool;
}

fn isConfigReadAppToolApproval(value: []const u8) bool {
    return std.mem.eql(u8, value, "auto") or
        std.mem.eql(u8, value, "prompt") or
        std.mem.eql(u8, value, "approve");
}

fn loadConfigReadForcedChatGptWorkspaceId(allocator: std.mem.Allocator, bytes: []const u8) !?[]const u8 {
    if (try config.topLevelStringValue(allocator, bytes, "forced_chatgpt_workspace_id")) |value| {
        defer allocator.free(value);
        const trimmed = std.mem.trim(u8, value, " \t\r\n");
        if (trimmed.len == 0) return null;
        return @as(?[]const u8, try allocator.dupe(u8, trimmed));
    }

    return null;
}

fn loadConfigReadForcedLoginMethod(allocator: std.mem.Allocator, bytes: []const u8) !?config.ForcedLoginMethod {
    if (try config.topLevelStringValue(allocator, bytes, "forced_login_method")) |value| {
        defer allocator.free(value);
        return try config.ForcedLoginMethod.parse(value);
    }

    return null;
}

fn loadConfigReadManagedLayer(allocator: std.mem.Allocator) !?ConfigReadManagedLayer {
    const file_path = try managedConfigPath(allocator);
    errdefer allocator.free(file_path);
    const bytes = try config.readConfigTomlFile(allocator, file_path);
    const payload = bytes orelse {
        allocator.free(file_path);
        return null;
    };
    defer allocator.free(payload);

    var origin_keys = std.ArrayList([]const u8).empty;
    errdefer {
        for (origin_keys.items) |key| allocator.free(key);
        origin_keys.deinit(allocator);
    }

    var model: ?[]const u8 = null;
    errdefer if (model) |value| allocator.free(value);
    var review_model: ?[]const u8 = null;
    errdefer if (review_model) |value| allocator.free(value);
    var model_context_window: ?i64 = null;
    var model_auto_compact_token_limit: ?i64 = null;
    var model_provider: ?[]const u8 = null;
    errdefer if (model_provider) |value| allocator.free(value);
    var instructions: ?[]const u8 = null;
    errdefer if (instructions) |value| allocator.free(value);
    var developer_instructions: ?[]const u8 = null;
    errdefer if (developer_instructions) |value| allocator.free(value);
    var compact_prompt: ?[]const u8 = null;
    errdefer if (compact_prompt) |value| allocator.free(value);
    var approval_policy: ?config.ApprovalPolicy = null;
    var approvals_reviewer: ?config.ApprovalsReviewer = null;
    var sandbox_mode: ?config.SandboxMode = null;
    var web_search_mode: ?config.WebSearchMode = null;
    var model_reasoning_effort: ?config.ReasoningEffort = null;
    var model_verbosity: ?config.Verbosity = null;
    var service_tier: ?[]const u8 = null;
    errdefer if (service_tier) |value| allocator.free(value);
    var forced_chatgpt_workspace_id: ?[]const u8 = null;
    errdefer if (forced_chatgpt_workspace_id) |value| allocator.free(value);
    var forced_login_method: ?config.ForcedLoginMethod = null;
    var tools = ConfigReadTools{};
    errdefer tools.deinit(allocator);
    var apps = ConfigReadApps.empty();
    errdefer apps.deinit(allocator);

    if (try config.topLevelStringValue(allocator, payload, "model")) |value| {
        model = value;
        try appendUniqueOriginKey(allocator, &origin_keys, "model");
    }
    if (try config.topLevelStringValue(allocator, payload, "review_model")) |value| {
        review_model = value;
        try appendUniqueOriginKey(allocator, &origin_keys, "review_model");
    }
    if (try config.topLevelI64Value(payload, "model_context_window")) |value| {
        model_context_window = value;
        try appendUniqueOriginKey(allocator, &origin_keys, "model_context_window");
    }
    if (try config.topLevelI64Value(payload, "model_auto_compact_token_limit")) |value| {
        model_auto_compact_token_limit = value;
        try appendUniqueOriginKey(allocator, &origin_keys, "model_auto_compact_token_limit");
    }
    if (try config.topLevelStringValue(allocator, payload, "model_provider")) |value| {
        model_provider = value;
        try appendUniqueOriginKey(allocator, &origin_keys, "model_provider");
    }
    if (try configReadTopLevelInstructionsValue(allocator, payload)) |value| {
        instructions = value;
        try appendUniqueOriginKey(allocator, &origin_keys, "instructions");
    }
    if (try config.topLevelStringValue(allocator, payload, "developer_instructions")) |value| {
        developer_instructions = value;
        try appendUniqueOriginKey(allocator, &origin_keys, "developer_instructions");
    }
    if (try config.topLevelStringValue(allocator, payload, "compact_prompt")) |value| {
        compact_prompt = value;
        try appendUniqueOriginKey(allocator, &origin_keys, "compact_prompt");
    }
    if (try config.topLevelStringValue(allocator, payload, "approval_policy")) |value| {
        defer allocator.free(value);
        approval_policy = try config.ApprovalPolicy.parse(value);
        try appendUniqueOriginKey(allocator, &origin_keys, "approval_policy");
    }
    if (try config.topLevelStringValue(allocator, payload, "approvals_reviewer")) |value| {
        defer allocator.free(value);
        approvals_reviewer = try config.ApprovalsReviewer.parse(value);
        try appendUniqueOriginKey(allocator, &origin_keys, "approvals_reviewer");
    }
    if (try config.topLevelStringValue(allocator, payload, "sandbox_mode")) |value| {
        defer allocator.free(value);
        sandbox_mode = try config.SandboxMode.parse(value);
        try appendUniqueOriginKey(allocator, &origin_keys, "sandbox_mode");
    }
    if (try config.topLevelStringValue(allocator, payload, "web_search")) |value| {
        defer allocator.free(value);
        web_search_mode = try config.WebSearchMode.parse(value);
        try appendUniqueOriginKey(allocator, &origin_keys, "web_search");
    }
    if (try config.topLevelStringValue(allocator, payload, "model_reasoning_effort")) |value| {
        defer allocator.free(value);
        model_reasoning_effort = try config.ReasoningEffort.parse(value);
        try appendUniqueOriginKey(allocator, &origin_keys, "model_reasoning_effort");
    }
    if (try config.topLevelStringValue(allocator, payload, "model_verbosity")) |value| {
        defer allocator.free(value);
        model_verbosity = try config.Verbosity.parse(value);
        try appendUniqueOriginKey(allocator, &origin_keys, "model_verbosity");
    }
    if (try config.topLevelStringValue(allocator, payload, "service_tier")) |value| {
        defer allocator.free(value);
        service_tier = try config.normalizeServiceTier(allocator, value);
        try appendUniqueOriginKey(allocator, &origin_keys, "service_tier");
    }
    const analytics = try loadConfigReadAnalytics(allocator, payload);
    if (analytics.enabled != null) {
        try appendUniqueOriginKey(allocator, &origin_keys, "analytics.enabled");
    }
    forced_chatgpt_workspace_id = try loadConfigReadForcedChatGptWorkspaceId(allocator, payload);
    if (forced_chatgpt_workspace_id != null) {
        try appendUniqueOriginKey(allocator, &origin_keys, "forced_chatgpt_workspace_id");
    }
    forced_login_method = try loadConfigReadForcedLoginMethod(allocator, payload);
    if (forced_login_method != null) {
        try appendUniqueOriginKey(allocator, &origin_keys, "forced_login_method");
    }
    var profiles = try loadConfigReadProfiles(allocator, payload);
    errdefer profiles.deinit(allocator);
    try appendConfigReadProfilesOriginKeys(allocator, &origin_keys, profiles);
    tools = try loadConfigReadTools(allocator, payload);
    try appendConfigReadToolsOriginKeys(allocator, &origin_keys, tools);
    apps = try loadConfigReadApps(allocator, payload);

    var sandbox_workspace_write = try loadConfigReadSandboxWorkspaceWrite(allocator, payload);
    errdefer sandbox_workspace_write.deinit(allocator);
    try appendConfigReadSandboxWorkspaceOriginKeys(allocator, &origin_keys, sandbox_workspace_write);

    const owned_origin_keys = if (origin_keys.items.len > 0)
        try origin_keys.toOwnedSlice(allocator)
    else
        &.{};

    return .{
        .file_path = file_path,
        .version = try configVersionAlloc(allocator, payload),
        .origin_keys = owned_origin_keys,
        .model = model,
        .review_model = review_model,
        .model_context_window = model_context_window,
        .model_auto_compact_token_limit = model_auto_compact_token_limit,
        .model_provider = model_provider,
        .instructions = instructions,
        .developer_instructions = developer_instructions,
        .compact_prompt = compact_prompt,
        .approval_policy = approval_policy,
        .approvals_reviewer = approvals_reviewer,
        .sandbox_mode = sandbox_mode,
        .web_search_mode = web_search_mode,
        .model_reasoning_effort = model_reasoning_effort,
        .model_verbosity = model_verbosity,
        .service_tier = service_tier,
        .analytics = analytics,
        .forced_chatgpt_workspace_id = forced_chatgpt_workspace_id,
        .forced_login_method = forced_login_method,
        .profiles = profiles,
        .tools = tools,
        .apps = apps,
        .sandbox_workspace_write = sandbox_workspace_write,
    };
}

