fn appendConfigReadProjectLayerConfig(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    layer: ConfigReadProjectLayer,
) !void {
    try result.append(allocator, '{');
    var first = true;
    for (layer.origin_keys) |key| {
        if (std.mem.eql(u8, key, "model")) {
            if (layer.model) |value| try appendJsonStringField(allocator, result, &first, key, value);
        } else if (std.mem.eql(u8, key, "review_model")) {
            try appendJsonMaybeStringField(allocator, result, &first, key, layer.review_model);
        } else if (std.mem.eql(u8, key, "model_context_window")) {
            try appendJsonMaybeI64Field(allocator, result, &first, key, layer.model_context_window);
        } else if (std.mem.eql(u8, key, "model_auto_compact_token_limit")) {
            try appendJsonMaybeI64Field(allocator, result, &first, key, layer.model_auto_compact_token_limit);
        } else if (std.mem.eql(u8, key, "model_provider")) {
            try appendJsonMaybeStringField(allocator, result, &first, key, layer.model_provider);
        } else if (std.mem.eql(u8, key, "instructions")) {
            try appendJsonMaybeStringField(allocator, result, &first, key, layer.instructions);
        } else if (std.mem.eql(u8, key, "developer_instructions")) {
            try appendJsonMaybeStringField(allocator, result, &first, key, layer.developer_instructions);
        } else if (std.mem.eql(u8, key, "compact_prompt")) {
            try appendJsonMaybeStringField(allocator, result, &first, key, layer.compact_prompt);
        } else if (std.mem.eql(u8, key, "approval_policy")) {
            if (layer.approval_policy) |policy| try appendJsonStringField(allocator, result, &first, key, policy.label());
        } else if (std.mem.eql(u8, key, "approvals_reviewer")) {
            if (layer.approvals_reviewer) |reviewer| try appendJsonStringField(allocator, result, &first, key, reviewer.label());
        } else if (std.mem.eql(u8, key, "sandbox_mode")) {
            if (layer.sandbox_mode) |mode| try appendJsonStringField(allocator, result, &first, key, mode.label());
        } else if (std.mem.eql(u8, key, "forced_chatgpt_workspace_id")) {
            try appendJsonMaybeStringField(allocator, result, &first, key, layer.forced_chatgpt_workspace_id);
        } else if (std.mem.eql(u8, key, "forced_login_method")) {
            try appendJsonMaybeStringField(allocator, result, &first, key, if (layer.forced_login_method) |method| method.label() else null);
