    }
    try appendJsonBoolField(allocator, result, &first, "network_access", sandbox.network_access);
    try appendJsonBoolField(allocator, result, &first, "exclude_tmpdir_env_var", sandbox.exclude_tmpdir_env_var);
    try appendJsonBoolField(allocator, result, &first, "exclude_slash_tmp", sandbox.exclude_slash_tmp);
    try result.append(allocator, '}');
}

fn appendConfigReadAppObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    app: ConfigReadApp,
) !void {
    try result.append(allocator, '{');
    var first = true;
    try appendJsonBoolField(allocator, result, &first, "enabled", app.enabled);
    try appendJsonMaybeBoolField(allocator, result, &first, "destructive_enabled", app.destructive_enabled);
    try appendJsonMaybeBoolField(allocator, result, &first, "open_world_enabled", app.open_world_enabled);
    try appendJsonMaybeStringField(allocator, result, &first, "default_tools_approval_mode", app.default_tools_approval_mode);
    try appendJsonMaybeBoolField(allocator, result, &first, "default_tools_enabled", app.default_tools_enabled);
    try appendJsonFieldName(allocator, result, &first, "tools");
    if (app.tools.items.len > 0) {
        try appendConfigReadAppToolsObject(allocator, result, app.tools.items);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.append(allocator, '}');
}

fn appendConfigReadAppToolsObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    tools: []const ConfigReadAppTool,
) !void {
    try result.append(allocator, '{');
    var first = true;
    for (tools) |tool| {
        try appendJsonFieldName(allocator, result, &first, tool.name);
        try appendConfigReadAppToolObject(allocator, result, tool);
    }
    try result.append(allocator, '}');
}

fn appendConfigReadAppToolObject(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    tool: ConfigReadAppTool,
) !void {
    try result.append(allocator, '{');
    var first = true;
    try appendJsonMaybeBoolField(allocator, result, &first, "enabled", tool.enabled);
    try appendJsonMaybeStringField(allocator, result, &first, "approval_mode", tool.approval_mode);
    try result.append(allocator, '}');
}

fn appendConfigReadFeaturesField(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    first: *bool,
    cli_feature_overrides: features_cmd.FeatureOverrides,
    config_feature_overrides: features_cmd.FeatureOverrides,
    runtime_feature_enablement: features_cmd.FeatureOverrides,
    feature_requirements: ?FeatureRequirementList,
) !void {
    try appendJsonFieldName(allocator, result, first, "features");
    try result.appendSlice(allocator, "{");
    for (features_cmd.FeatureSpec.all, 0..) |feature, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        const key_json = try std.json.Stringify.valueAlloc(allocator, feature.key, .{});
        defer allocator.free(key_json);
        const enabled = featureRequirementValue(feature_requirements, feature.key) orelse
            cli_feature_overrides.get(feature.key) orelse
            config_feature_overrides.get(feature.key) orelse
            runtime_feature_enablement.get(feature.key) orelse
            feature.default_enabled;
        try result.appendSlice(allocator, key_json);
        try result.appendSlice(allocator, if (enabled) ":true" else ":false");
    }
    try result.appendSlice(allocator, "}");
}

fn featureRequirementValue(feature_requirements: ?FeatureRequirementList, key: []const u8) ?bool {
    const requirements = feature_requirements orelse return null;
    var value: ?bool = null;
    for (requirements.items) |entry| {
        const canonical_key = canonicalFeatureRequirementKey(entry.name) orelse continue;
        if (std.mem.eql(u8, canonical_key, key)) value = entry.enabled;
    }
    return value;
}

fn canonicalFeatureRequirementKey(name: []const u8) ?[]const u8 {
    if (std.mem.eql(u8, name, "auto_review")) return "guardian_approval";
    return features_cmd.canonicalFeatureKey(name);
}

fn appendJsonFieldName(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    first: *bool,
    name: []const u8,
) !void {
    if (first.*) {
        first.* = false;
    } else {
        try result.appendSlice(allocator, ",");
    }
    const name_json = try std.json.Stringify.valueAlloc(allocator, name, .{});
    defer allocator.free(name_json);
    try result.appendSlice(allocator, name_json);
    try result.appendSlice(allocator, ":");
}

fn isAccountMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "account/read") or
        std.mem.eql(u8, method, "getAuthStatus") or
        std.mem.eql(u8, method, "account/login/cancel") or
        std.mem.eql(u8, method, "account/login/start") or
        std.mem.eql(u8, method, "account/rateLimits/read") or
        std.mem.eql(u8, method, "account/sendAddCreditsNudgeEmail") or
        std.mem.eql(u8, method, "account/logout");
}

fn handleAccountMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "account/read")) {
        return handleAccountRead(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "getAuthStatus")) {
        return handleGetAuthStatus(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "account/login/cancel")) {
        return handleAccountLoginCancel(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "account/login/start")) {
        return handleAccountLoginStart(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "account/rateLimits/read")) {
        return handleAccountRateLimitsRead(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "account/sendAddCreditsNudgeEmail")) {
        return handleSendAddCreditsNudgeEmail(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "account/logout")) {
        return handleAccountLogout(allocator, state, id_value, params_value);
    }
    return try renderJsonRpcError(allocator, id_value, -32601, "unknown account method");
}

fn handleAccountLoginStart(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "account/login/start params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "account/login/start params must be an object");
    const object = params.object;

    const type_value = object.get("type") orelse return renderJsonRpcError(allocator, id_value, -32602, "type must be a string");
    if (type_value != .string) return renderJsonRpcError(allocator, id_value, -32602, "type must be a string");

    const login_type = type_value.string;
    if (std.mem.eql(u8, login_type, "apiKey")) {
        return handleAccountLoginStartApiKey(allocator, state, id_value, object);
    }
    if (std.mem.eql(u8, login_type, "chatgptAuthTokens")) {
        return handleAccountLoginStartChatGptAuthTokens(allocator, state, id_value, object);
    }
    if (std.mem.eql(u8, login_type, "chatgpt")) {
        return handleAccountLoginStartChatGpt(allocator, state, id_value, object);
    }
    if (std.mem.eql(u8, login_type, "chatgptDeviceCode")) {
        return handleAccountLoginStartChatGptDeviceCode(allocator, state, id_value);
    }

    const message = try std.fmt.allocPrint(
        allocator,
        "account/login/start type {s} is parsed but not implemented yet",
        .{login_type},
    );
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32603, message);
}

fn handleAccountLoginStartApiKey(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    object: std.json.ObjectMap,
) ![]const u8 {
    const api_key_value = object.get("apiKey") orelse return renderJsonRpcError(allocator, id_value, -32602, "apiKey must be a non-empty string");
    if (api_key_value != .string or api_key_value.string.len == 0) {
        return renderJsonRpcError(allocator, id_value, -32602, "apiKey must be a non-empty string");
    }

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/login/start failed to load config", err);
    };
    defer cfg.deinit(allocator);
    if (try externalChatGptAuthActive(allocator, &cfg)) {
        return renderJsonRpcError(allocator, id_value, -32600, EXTERNAL_AUTH_ACTIVE_LOGIN_MESSAGE);
    }
    if (cfg.forced_login_method == .chatgpt) {
        return renderJsonRpcError(allocator, id_value, -32600, "API key login is disabled. Use ChatGPT login instead.");
    }
    clearActiveAccountLogin(allocator, state, true);

    auth_mod.saveApiKeyAuth(allocator, cfg.codex_home, cfg.cli_auth_credentials_store_mode, api_key_value.string) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/login/start failed to save API key", err);
    };

    const response = try renderJsonRpcResult(allocator, id_value, "{\"type\":\"apiKey\"}");
    defer allocator.free(response);
    return renderResultWithLoginNotifications(allocator, response, "apikey", null);
}

fn handleAccountLoginStartChatGpt(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    object: std.json.ObjectMap,
) ![]const u8 {
    const codex_streamlined_login = accountLoginOptionalBool(object, "codexStreamlinedLogin") catch |err| switch (err) {
        error.InvalidAccountLoginBool => return renderJsonRpcError(allocator, id_value, -32602, "codexStreamlinedLogin must be a boolean or null"),
    };

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/login/start failed to load config", err);
    };
    defer cfg.deinit(allocator);
    if (try externalChatGptAuthActive(allocator, &cfg)) {
        return renderJsonRpcError(allocator, id_value, -32600, EXTERNAL_AUTH_ACTIVE_LOGIN_MESSAGE);
    }
    if (cfg.forced_login_method == .api) {
        return renderJsonRpcError(allocator, id_value, -32600, "ChatGPT login is disabled. Use API key login instead.");
    }

    const issuer_override = try accountLoginIssuerOverride(allocator);
    defer if (issuer_override) |value| allocator.free(value);
    const issuer = issuer_override orelse login_mod.default_issuer;
    var login_handle = login_mod.startBrowserAuthReturnUrl(allocator, .{
        .codex_home = cfg.codex_home,
        .auth_store_mode = cfg.cli_auth_credentials_store_mode,
        .issuer = issuer,
        .forced_chatgpt_workspace_id = cfg.forced_chatgpt_workspace_id,
        .codex_streamlined_login = codex_streamlined_login,
    }) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/login/start failed to start ChatGPT login", err);
    };
    errdefer login_handle.deinit(allocator);

    const login_id = try generateUuidString(allocator);
    errdefer allocator.free(login_id);
    const login_registry = try ensureActiveAccountLoginRegistry(allocator, state);
    replaceActiveAccountLogin(allocator, login_registry, .{
        .login_id = try allocator.dupe(u8, login_id),
        .kind = .{ .browser = login_handle.actual_port },
    }, true);
    errdefer clearMatchingActiveAccountLogin(allocator, login_registry, login_id, true);

    const response = try renderAccountLoginChatGptResponse(allocator, id_value, login_id, login_handle.auth_url);
    errdefer allocator.free(response);
    var completion_target = try makeAppServerBackgroundNotificationTarget(allocator, state.connection_output);
    errdefer completion_target.deinit(allocator);
    try spawnAccountLoginWorker(allocator, login_id, login_handle, login_registry, completion_target);
    return response;
}

fn handleAccountLoginStartChatGptDeviceCode(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
) ![]const u8 {
    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/login/start failed to load config", err);
    };
    defer cfg.deinit(allocator);
    if (try externalChatGptAuthActive(allocator, &cfg)) {
        return renderJsonRpcError(allocator, id_value, -32600, EXTERNAL_AUTH_ACTIVE_LOGIN_MESSAGE);
    }
    if (cfg.forced_login_method == .api) {
        return renderJsonRpcError(allocator, id_value, -32600, "ChatGPT login is disabled. Use API key login instead.");
    }

    const issuer_override = try accountLoginIssuerOverride(allocator);
    defer if (issuer_override) |value| allocator.free(value);
    const issuer = issuer_override orelse login_mod.default_issuer;
    var device_handle = login_mod.startDeviceAuth(allocator, .{
        .codex_home = cfg.codex_home,
        .auth_store_mode = cfg.cli_auth_credentials_store_mode,
        .issuer = issuer,
        .forced_chatgpt_workspace_id = cfg.forced_chatgpt_workspace_id,
    }) catch |err| switch (err) {
        error.DeviceAuthUnsupported => return renderJsonRpcError(allocator, id_value, -32600, "device auth is not supported by this issuer"),
        else => return renderJsonRpcErrorForFailure(allocator, id_value, "account/login/start failed to start ChatGPT device-code login", err),
    };
    errdefer device_handle.deinit(allocator);

    const login_id = try generateUuidString(allocator);
    errdefer allocator.free(login_id);
    const cancel_token = try allocator.create(AccountLoginCancelToken);
    cancel_token.* = .{};
    var cancel_token_owned = true;
    errdefer if (cancel_token_owned) cancel_token.release(allocator);

    const login_registry = try ensureActiveAccountLoginRegistry(allocator, state);
    replaceActiveAccountLogin(allocator, login_registry, .{
        .login_id = try allocator.dupe(u8, login_id),
        .kind = .{ .device_code = cancel_token },
    }, true);
    cancel_token_owned = false;
    errdefer clearMatchingActiveAccountLogin(allocator, login_registry, login_id, true);

    const response = try renderAccountLoginDeviceCodeResponse(allocator, id_value, login_id, device_handle.device_code.verification_url, device_handle.device_code.user_code);
    errdefer allocator.free(response);
    var completion_target = try makeAppServerBackgroundNotificationTarget(allocator, state.connection_output);
    errdefer completion_target.deinit(allocator);
    try spawnAccountDeviceCodeWorker(allocator, login_id, device_handle, cancel_token, login_registry, completion_target);
    return response;
}

fn handleAccountLoginStartChatGptAuthTokens(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    object: std.json.ObjectMap,
) ![]const u8 {
    const access_token_value = object.get("accessToken") orelse return renderJsonRpcError(allocator, id_value, -32602, "accessToken must be a non-empty string");
    if (access_token_value != .string or access_token_value.string.len == 0) {
        return renderJsonRpcError(allocator, id_value, -32602, "accessToken must be a non-empty string");
    }

    const account_id_value = object.get("chatgptAccountId") orelse return renderJsonRpcError(allocator, id_value, -32602, "chatgptAccountId must be a non-empty string");
    if (account_id_value != .string or account_id_value.string.len == 0) {
        return renderJsonRpcError(allocator, id_value, -32602, "chatgptAccountId must be a non-empty string");
    }

    const plan_type = blk: {
        const value = object.get("chatgptPlanType") orelse break :blk null;
        if (value == .null) break :blk null;
        if (value != .string) return renderJsonRpcError(allocator, id_value, -32602, "chatgptPlanType must be a string or null");
        break :blk value.string;
    };

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/login/start failed to load config", err);
    };
    defer cfg.deinit(allocator);
    if (cfg.forced_login_method == .api) {
        return renderJsonRpcError(allocator, id_value, -32600, "External ChatGPT auth is disabled. Use API key login instead.");
    }
    if (cfg.forced_chatgpt_workspace_id) |expected_workspace| {
        if (!std.mem.eql(u8, account_id_value.string, expected_workspace)) {
            const message = try std.fmt.allocPrint(
                allocator,
                "External auth must use workspace {s}, but received \"{s}\".",
                .{ expected_workspace, account_id_value.string },
            );
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
    }
    clearActiveAccountLogin(allocator, state, true);

    auth_mod.saveChatGptAuthTokensJsonWithMode(allocator, cfg.codex_home, .ephemeral, access_token_value.string, account_id_value.string, plan_type) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/login/start failed to save ChatGPT auth tokens", err);
    };

    const response = try renderJsonRpcResult(allocator, id_value, "{\"type\":\"chatgptAuthTokens\"}");
    defer allocator.free(response);
    return renderResultWithLoginNotifications(allocator, response, "chatgptAuthTokens", plan_type);
}

fn handleAccountLoginCancel(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "account/login/cancel params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "account/login/cancel params must be an object");

    const login_id_value = params.object.get("loginId") orelse return renderJsonRpcError(allocator, id_value, -32602, "loginId must be a string");
    if (login_id_value != .string) return renderJsonRpcError(allocator, id_value, -32602, "loginId must be a string");
    if (!isUuidString(login_id_value.string)) {
        const message = try std.fmt.allocPrint(allocator, "invalid login id: {s}", .{login_id_value.string});
        defer allocator.free(message);
        return renderJsonRpcError(allocator, id_value, -32602, message);
    }

    const canonical = try canonicalUuidString(allocator, login_id_value.string);
    defer allocator.free(canonical);
    if (state.active_account_login) |registry| {
        const canceled = cancelMatchingActiveAccountLogin(allocator, registry, canonical);
        if (canceled) {
            return renderJsonRpcResult(allocator, id_value, "{\"status\":\"canceled\"}");
        }
    }
    return renderJsonRpcResult(allocator, id_value, "{\"status\":\"notFound\"}");
}

fn accountLoginOptionalBool(object: std.json.ObjectMap, name: []const u8) !bool {
    const value = object.get(name) orelse return false;
    if (value == .null) return false;
    if (value != .bool) return error.InvalidAccountLoginBool;
    return value.bool;
}

fn clearActiveAccountLogin(allocator: std.mem.Allocator, state: *AppServerState, cancel: bool) void {
    const registry = state.active_account_login orelse return;
    clearActiveAccountLoginRegistry(allocator, registry, cancel);
}

fn ensureActiveAccountLoginRegistry(allocator: std.mem.Allocator, state: *AppServerState) !*ActiveAccountLoginRegistry {
    if (state.active_account_login) |registry| return registry;
    const registry = try ActiveAccountLoginRegistry.create(allocator);
    state.active_account_login = registry;
    return registry;
}

fn releaseActiveAccountLoginRegistry(allocator: std.mem.Allocator, state: *AppServerState, cancel: bool) void {
    const registry = state.active_account_login orelse return;
    state.active_account_login = null;
    clearActiveAccountLoginRegistry(allocator, registry, cancel);
    registry.release(allocator, false);
}

fn replaceActiveAccountLogin(
    allocator: std.mem.Allocator,
    registry: *ActiveAccountLoginRegistry,
    active: ActiveAccountLogin,
    cancel_existing: bool,
) void {
    var active_owned = active;
    var moved = false;
    defer if (!moved) active_owned.deinit(allocator);

    var replaced = takeActiveAccountLogin(registry, null);
    defer if (replaced) |*existing| {
        if (cancel_existing) cancelAccountLogin(existing);
        existing.deinit(allocator);
    };

    lockActiveAccountLoginRegistry(registry);
    defer unlockActiveAccountLoginRegistry(registry);
    registry.active = active_owned;
    moved = true;
}

fn clearActiveAccountLoginRegistry(
    allocator: std.mem.Allocator,
    registry: *ActiveAccountLoginRegistry,
    cancel: bool,
) void {
    var active = takeActiveAccountLogin(registry, null) orelse return;
    defer active.deinit(allocator);
    if (cancel) cancelAccountLogin(&active);
}

fn clearMatchingActiveAccountLogin(
    allocator: std.mem.Allocator,
    registry: *ActiveAccountLoginRegistry,
    login_id: []const u8,
    cancel: bool,
) void {
    var active = takeActiveAccountLogin(registry, login_id) orelse return;
    defer active.deinit(allocator);
    if (cancel) cancelAccountLogin(&active);
}

fn cancelMatchingActiveAccountLogin(
    allocator: std.mem.Allocator,
    registry: *ActiveAccountLoginRegistry,
    login_id: []const u8,
) bool {
    var active = takeActiveAccountLogin(registry, login_id) orelse return false;
    defer active.deinit(allocator);
    cancelAccountLogin(&active);
    return true;
}

fn takeActiveAccountLogin(registry: *ActiveAccountLoginRegistry, login_id: ?[]const u8) ?ActiveAccountLogin {
    lockActiveAccountLoginRegistry(registry);
    defer unlockActiveAccountLoginRegistry(registry);

    const active = registry.active orelse return null;
    if (login_id) |expected| {
        if (!std.mem.eql(u8, active.login_id, expected)) return null;
    }
    registry.active = null;
    return active;
}

fn cancelAccountLogin(active: *ActiveAccountLogin) void {
    switch (active.kind) {
        .browser => |port| login_mod.cancelBrowserAuth(port) catch {},
        .device_code => |token| token.canceled.store(true, .release),
    }
}

fn lockActiveAccountLoginRegistry(registry: *ActiveAccountLoginRegistry) void {
    const io = std.Io.Threaded.global_single_threaded.io();
    registry.mutex.lockUncancelable(io);
}

fn unlockActiveAccountLoginRegistry(registry: *ActiveAccountLoginRegistry) void {
    const io = std.Io.Threaded.global_single_threaded.io();
    registry.mutex.unlock(io);
}

fn renderAccountLoginChatGptResponse(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    login_id: []const u8,
    auth_url: []const u8,
) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"type\":\"chatgpt\",\"loginId\":");
    try appendJsonString(allocator, &result, login_id);
    try result.appendSlice(allocator, ",\"authUrl\":");
    try appendJsonString(allocator, &result, auth_url);
    try result.append(allocator, '}');
    return renderJsonRpcResult(allocator, id_value, result.items);
}

fn renderAccountLoginDeviceCodeResponse(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    login_id: []const u8,
    verification_url: []const u8,
    user_code: []const u8,
) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"type\":\"chatgptDeviceCode\",\"loginId\":");
    try appendJsonString(allocator, &result, login_id);
    try result.appendSlice(allocator, ",\"verificationUrl\":");
    try appendJsonString(allocator, &result, verification_url);
    try result.appendSlice(allocator, ",\"userCode\":");
    try appendJsonString(allocator, &result, user_code);
    try result.append(allocator, '}');
    return renderJsonRpcResult(allocator, id_value, result.items);
}

const AccountLoginWorker = struct {
    login_id: []const u8,
    handle: login_mod.BrowserAuthHandle,
    login_registry: *ActiveAccountLoginRegistry,
    completion_target: AppServerBackgroundNotificationTarget,

    fn deinit(self: *AccountLoginWorker, allocator: std.mem.Allocator) void {
        allocator.free(self.login_id);
        self.handle.deinit(allocator);
        self.login_registry.release(allocator, false);
        self.completion_target.deinit(allocator);
    }
};

fn spawnAccountLoginWorker(
    allocator: std.mem.Allocator,
    login_id: []const u8,
    handle: login_mod.BrowserAuthHandle,
    login_registry: *ActiveAccountLoginRegistry,
    completion_target: AppServerBackgroundNotificationTarget,
) !void {
    const worker = try allocator.create(AccountLoginWorker);
    errdefer allocator.destroy(worker);
    const login_id_owned = try allocator.dupe(u8, login_id);
    errdefer allocator.free(login_id_owned);
    login_registry.retain();
    errdefer login_registry.release(allocator, false);
    worker.* = .{
        .login_id = login_id_owned,
        .handle = handle,
        .login_registry = login_registry,
        .completion_target = completion_target,
    };
    const thread = try std.Thread.spawn(.{ .allocator = allocator }, accountLoginWorker, .{ allocator, worker });
    thread.detach();
}

const AccountDeviceCodeWorker = struct {
    login_id: []const u8,
    handle: login_mod.DeviceAuthHandle,
    cancel_token: *AccountLoginCancelToken,
    login_registry: *ActiveAccountLoginRegistry,
    completion_target: AppServerBackgroundNotificationTarget,

    fn deinit(self: *AccountDeviceCodeWorker, allocator: std.mem.Allocator) void {
        allocator.free(self.login_id);
        self.handle.deinit(allocator);
        self.cancel_token.release(allocator);
        self.login_registry.release(allocator, false);
        self.completion_target.deinit(allocator);
    }
};

fn spawnAccountDeviceCodeWorker(
    allocator: std.mem.Allocator,
    login_id: []const u8,
    handle: login_mod.DeviceAuthHandle,
    cancel_token: *AccountLoginCancelToken,
    login_registry: *ActiveAccountLoginRegistry,
    completion_target: AppServerBackgroundNotificationTarget,
) !void {
