    errdefer allocator.free(login_id_owned);
    cancel_token.retain();
    errdefer cancel_token.release(allocator);
    login_registry.retain();
    errdefer login_registry.release(allocator, false);
    worker.* = .{
        .login_id = login_id_owned,
        .handle = handle,
        .cancel_token = cancel_token,
        .login_registry = login_registry,
        .completion_target = completion_target,
    };
    const thread = try std.Thread.spawn(.{ .allocator = allocator }, accountDeviceCodeWorker, .{ allocator, worker });
    thread.detach();
}

fn accountLoginWorker(allocator: std.mem.Allocator, worker: *AccountLoginWorker) void {
    var maybe_error = if (worker.handle.waitAndSave(allocator)) |_| null else |err| accountLoginErrorText(allocator, err, worker.handle.forced_chatgpt_workspace_id);
    defer if (maybe_error) |*message| message.deinit(allocator);
    clearMatchingActiveAccountLogin(allocator, worker.login_registry, worker.login_id, false);

    var notification_storage: [4096]u8 = undefined;
    var notification_writer = std.Io.Writer.fixed(&notification_storage);
    if (maybe_error) |message| {
        writeAccountLoginCompletedNotification(&notification_writer, worker.login_id, false, message.text) catch {
            worker.deinit(allocator);
            allocator.destroy(worker);
            return;
        };
    } else {
        writeAccountLoginCompletedNotification(&notification_writer, worker.login_id, true, null) catch {
            worker.deinit(allocator);
            allocator.destroy(worker);
            return;
        };
        const plan_type = accountLoginCompletedPlanType(allocator, worker.handle.codex_home, worker.handle.auth_store_mode) catch null;
        defer if (plan_type) |value| allocator.free(value);
        notification_writer.writeAll("\n") catch {
            worker.deinit(allocator);
            allocator.destroy(worker);
            return;
        };
        writeAccountUpdatedNotification(&notification_writer, "chatgpt", plan_type) catch {
            worker.deinit(allocator);
            allocator.destroy(worker);
            return;
        };
    }

    var completion_target = worker.completion_target;
    worker.completion_target = .stdout;
    allocator.free(worker.login_id);
    worker.handle.deinit(allocator);
    worker.login_registry.release(allocator, false);
    allocator.destroy(worker);

    completion_target.send(notification_writer.buffer[0..notification_writer.end]) catch {};
    completion_target.deinit(allocator);
}

fn accountDeviceCodeWorker(allocator: std.mem.Allocator, worker: *AccountDeviceCodeWorker) void {
    var maybe_error = if (worker.handle.completeAndSave(allocator, &worker.cancel_token.canceled)) |_| null else |err| accountLoginErrorText(allocator, err, worker.handle.forced_chatgpt_workspace_id);
