fn accountLoginErrorMessage(err: anyerror) []const u8 {
    return switch (err) {
        error.LoginCancelled => "Login cancelled",
        error.DeviceAuthCancelled => "Login was not completed",
        error.MissingAuthorizationCode => login_mod.missing_authorization_code_message,
        error.MissingCodexEntitlement => login_mod.missing_codex_entitlement_message,
        error.WorkspaceRestrictionMissingAccount => login_mod.missing_workspace_account_message,
        else => @errorName(err),
    };
}

const AccountLoginErrorText = struct {
    text: []const u8,
    owned: bool = false,

    fn deinit(self: *AccountLoginErrorText, allocator: std.mem.Allocator) void {
        if (self.owned) allocator.free(self.text);
    }
};

fn accountLoginErrorText(
    allocator: std.mem.Allocator,
    err: anyerror,
    forced_chatgpt_workspace_id: ?[]const u8,
) AccountLoginErrorText {
    if (err == error.WorkspaceRestriction) {
        if (forced_chatgpt_workspace_id) |workspace_id| {
            if (login_mod.workspaceRestrictionMessage(allocator, workspace_id)) |message| {
                return .{ .text = message, .owned = true };
            } else |_| {}
        }
    }
    return .{ .text = accountLoginErrorMessage(err) };
}

fn accountLoginIssuerOverride(allocator: std.mem.Allocator) !?[]const u8 {
    const value = try env.getOwned(allocator, "CODEX_APP_SERVER_LOGIN_ISSUER") orelse return null;
    errdefer allocator.free(value);
    const trimmed = std.mem.trim(u8, value, " \t\r\n");
    if (trimmed.len == 0) {
        allocator.free(value);
        return null;
    }
    if (trimmed.ptr == value.ptr and trimmed.len == value.len) return value;
    const owned = try allocator.dupe(u8, trimmed);
    allocator.free(value);
    return owned;
}

fn accountLoginCompletedPlanType(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    store_mode: config.AuthCredentialsStoreMode,
) !?[]const u8 {
    var info = (try auth_mod.loadStoredChatGptAccountInfoWithMode(allocator, codex_home, store_mode)) orelse return null;
    defer info.deinit(allocator);
    const plan_type = try allocator.dupe(u8, info.plan_type);
    return plan_type;
}

fn writeAccountLoginCompletedNotification(
    writer: *std.Io.Writer,
    login_id: []const u8,
    success: bool,
    error_message: ?[]const u8,
) !void {
    try writer.writeAll("{\"jsonrpc\":\"2.0\",\"method\":\"account/login/completed\",\"params\":{\"loginId\":");
    try writeJsonStringLiteral(writer, login_id);
    try writer.writeAll(",\"success\":");
    try writer.writeAll(if (success) "true" else "false");
    try writer.writeAll(",\"error\":");
    if (error_message) |message| {
        try writeJsonStringLiteral(writer, message);
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll("}}");
}

fn writeAccountUpdatedNotification(
    writer: *std.Io.Writer,
    auth_mode: ?[]const u8,
    plan_type: ?[]const u8,
) !void {
    try writer.writeAll("{\"jsonrpc\":\"2.0\",\"method\":\"account/updated\",\"params\":{\"authMode\":");
    if (auth_mode) |value| {
        try writeJsonStringLiteral(writer, value);
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll(",\"planType\":");
    if (plan_type) |value| {
        try writeJsonStringLiteral(writer, value);
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll("}}");
}

fn externalChatGptAuthActive(allocator: std.mem.Allocator, cfg: *const config.Config) !bool {
    var credentials = (try auth_mod.loadActiveStoredWithMode(allocator, cfg.codex_home, cfg.cli_auth_credentials_store_mode)) orelse return false;
    defer credentials.deinit(allocator);
    return credentials.mode == .chatgpt_auth_tokens;
}

fn isUuidString(value: []const u8) bool {
    return switch (value.len) {
        32 => isSimpleUuidString(value),
        36 => isHyphenatedUuidString(value),
        38 => value[0] == '{' and value[37] == '}' and isHyphenatedUuidString(value[1..37]),
        45 => std.mem.startsWith(u8, value, "urn:uuid:") and isHyphenatedUuidString(value[9..]),
        else => false,
    };
}

fn canonicalUuidString(allocator: std.mem.Allocator, value: []const u8) ![]const u8 {
    if (!isUuidString(value)) return error.InvalidUuidString;

    const raw = switch (value.len) {
        38 => value[1..37],
        45 => value[9..],
        else => value,
    };

    var hex: [32]u8 = undefined;
    var hex_index: usize = 0;
    for (raw) |byte| {
        if (byte == '-') continue;
        if (hex_index >= hex.len) return error.InvalidUuidString;
        hex[hex_index] = std.ascii.toLower(byte);
        hex_index += 1;
    }
    if (hex_index != hex.len) return error.InvalidUuidString;

    var canonical: [36]u8 = undefined;
    var input_index: usize = 0;
    for (&canonical, 0..) |*byte, index| {
        switch (index) {
            8, 13, 18, 23 => byte.* = '-',
            else => {
                byte.* = hex[input_index];
                input_index += 1;
            },
        }
    }
    return allocator.dupe(u8, canonical[0..]);
}

fn isSimpleUuidString(value: []const u8) bool {
    if (value.len != 32) return false;
    for (value) |byte| {
        if (!std.ascii.isHex(byte)) return false;
    }
    return true;
}

fn isHyphenatedUuidString(value: []const u8) bool {
    if (value.len != 36) return false;
    for (value, 0..) |byte, index| {
        switch (index) {
            8, 13, 18, 23 => if (byte != '-') return false,
            else => if (!std.ascii.isHex(byte)) return false,
        }
    }
    return true;
}

fn handleAccountRateLimitsRead(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    if (params_value) |params| {
        if (params != .null) return renderJsonRpcError(allocator, id_value, -32602, "account/rateLimits/read params must be null or omitted");
    }

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/rateLimits/read failed to load config", err);
    };
    defer cfg.deinit(allocator);

    var credentials = auth_mod.loadCliAuthForConfig(allocator, &cfg) catch |err| switch (err) {
        error.NoUsableAuth => return renderJsonRpcError(allocator, id_value, -32602, "codex account authentication required to read rate limits"),
        else => return renderJsonRpcErrorForFailure(allocator, id_value, "account/rateLimits/read failed to load auth", err),
    };
    defer credentials.deinit(allocator);

    switch (credentials.mode) {
        .chatgpt, .chatgpt_auth_tokens, .agent_identity => {},
        .api_key, .local_oss, .provider_no_auth => return renderJsonRpcError(allocator, id_value, -32602, "chatgpt authentication required to read rate limits"),
    }

    const result = account_rate_limits.fetchJson(allocator, cfg.chatgpt_base_url, credentials) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/rateLimits/read failed to fetch codex rate limits", err);
    };
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn handleSendAddCreditsNudgeEmail(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "account/sendAddCreditsNudgeEmail params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "account/sendAddCreditsNudgeEmail params must be an object");

    const credit_type_value = params.object.get("creditType") orelse return renderJsonRpcError(allocator, id_value, -32602, "creditType must be credits or usage_limit");
    if (credit_type_value != .string) return renderJsonRpcError(allocator, id_value, -32602, "creditType must be credits or usage_limit");
    const credit_type = credit_type_value.string;
    if (!std.mem.eql(u8, credit_type, "credits") and !std.mem.eql(u8, credit_type, "usage_limit")) {
        return renderJsonRpcError(allocator, id_value, -32602, "creditType must be credits or usage_limit");
    }

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/sendAddCreditsNudgeEmail failed to load config", err);
    };
    defer cfg.deinit(allocator);

    var credentials = auth_mod.loadCliAuthForConfig(allocator, &cfg) catch |err| switch (err) {
        error.NoUsableAuth => return renderJsonRpcError(allocator, id_value, -32602, "codex account authentication required to notify workspace owner"),
        else => return renderJsonRpcErrorForFailure(allocator, id_value, "account/sendAddCreditsNudgeEmail failed to load auth", err),
    };
    defer credentials.deinit(allocator);

    switch (credentials.mode) {
        .chatgpt, .chatgpt_auth_tokens, .agent_identity => {},
        .api_key, .local_oss, .provider_no_auth => return renderJsonRpcError(allocator, id_value, -32602, "chatgpt authentication required to notify workspace owner"),
    }

    const status = account_nudge.sendAddCreditsNudgeEmail(allocator, cfg.chatgpt_base_url, credentials, credit_type) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/sendAddCreditsNudgeEmail failed to notify workspace owner", err);
    };
    const result = try std.fmt.allocPrint(allocator, "{{\"status\":\"{s}\"}}", .{status.jsonLabel()});
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn handleGetAuthStatus(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    const params = switch (optionalGetAuthStatusParams(params_value)) {
        .object => |object| object,
        .empty => null,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };

    var include_token = false;
    var refresh_token = false;
    if (params) |object| {
        include_token = switch (optionalNullableBoolField(object, "includeToken", false)) {
            .value => |value| value,
            .message => return renderJsonRpcError(allocator, id_value, -32602, "includeToken must be a boolean"),
        };
        refresh_token = switch (optionalNullableBoolField(object, "refreshToken", false)) {
            .value => |value| value,
            .message => return renderJsonRpcError(allocator, id_value, -32602, "refreshToken must be a boolean"),
        };
    }

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "getAuthStatus failed to load config", err);
    };
    defer cfg.deinit(allocator);

    const provider_requires_openai_auth = config.loadModelProviderRequiresOpenAiAuth(allocator, null) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "getAuthStatus failed to load model provider auth requirements", err);
    };
    const requires_openai_auth = cfg.oss_provider == null and provider_requires_openai_auth;
    if (!requires_openai_auth) {
        const result = try renderAuthStatusJson(allocator, null, null, false);
        defer allocator.free(result);
        return renderJsonRpcResult(allocator, id_value, result);
    }

    var credentials = blk: {
        const loaded = if (refresh_token)
            auth_mod.loadCliAuthForConfig(allocator, &cfg)
        else
            auth_mod.loadCliAuthNoRefreshForConfig(allocator, &cfg);
        break :blk loaded catch |err| switch (err) {
            error.NoUsableAuth => null,
            else => return renderJsonRpcErrorForFailure(allocator, id_value, "getAuthStatus failed to load auth", err),
        };
    };
    defer if (credentials) |*value| value.deinit(allocator);

    const fields = if (credentials) |value|
        authStatusFields(value, include_token)
    else
        AuthStatusFields{};
    const result = try renderAuthStatusJson(allocator, fields.auth_method, fields.auth_token, true);
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn optionalGetAuthStatusParams(params_value: ?std.json.Value) OptionalObjectParams {
    const params = params_value orelse return .empty;
    if (params == .null) return .empty;
    if (params != .object) return .{ .message = "getAuthStatus params must be an object" };
    return .{ .object = params.object };
}

const AuthStatusFields = struct {
    auth_method: ?[]const u8 = null,
    auth_token: ?[]const u8 = null,
};

fn authStatusFields(credentials: auth_mod.Credentials, include_token: bool) AuthStatusFields {
    return switch (credentials.mode) {
        .api_key, .chatgpt, .chatgpt_auth_tokens => if (credentials.token.len == 0)
            .{}
        else
            .{
                .auth_method = authMethodLabel(credentials.mode),
                .auth_token = if (include_token) credentials.token else null,
            },
        .agent_identity => .{ .auth_method = authMethodLabel(credentials.mode) },
        .local_oss, .provider_no_auth => .{},
    };
}

fn authMethodLabel(mode: auth_mod.Credentials.Mode) ?[]const u8 {
    return switch (mode) {
        .api_key => "apikey",
        .chatgpt => "chatgpt",
        .chatgpt_auth_tokens => "chatgptAuthTokens",
        .agent_identity => "agentIdentity",
        .local_oss, .provider_no_auth => null,
    };
}

fn authCacheModeLabel(mode: auth_mod.Credentials.Mode) []const u8 {
    return authMethodLabel(mode) orelse switch (mode) {
        .local_oss => "local_oss",
        .provider_no_auth => "provider_no_auth",
        else => unreachable,
    };
}

fn renderAuthStatusJson(
    allocator: std.mem.Allocator,
    auth_method: ?[]const u8,
    auth_token: ?[]const u8,
    requires_openai_auth: bool,
) ![]const u8 {
    const auth_method_json = if (auth_method) |value|
        try std.json.Stringify.valueAlloc(allocator, value, .{})
    else
        try allocator.dupe(u8, "null");
    defer allocator.free(auth_method_json);

    const auth_token_json = if (auth_token) |value|
        try std.json.Stringify.valueAlloc(allocator, value, .{})
    else
        try allocator.dupe(u8, "null");
    defer allocator.free(auth_token_json);

    return std.fmt.allocPrint(
        allocator,
        "{{\"authMethod\":{s},\"authToken\":{s},\"requiresOpenaiAuth\":{}}}",
        .{ auth_method_json, auth_token_json, requires_openai_auth },
    );
}

fn handleAccountLogout(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (params_value) |params| {
        if (params != .null) return renderJsonRpcError(allocator, id_value, -32602, "account/logout params must be null or omitted");
    }

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/logout failed to load config", err);
    };
    defer cfg.deinit(allocator);

    clearActiveAccountLogin(allocator, state, true);
    _ = auth_mod.logoutWithRevokeWithMode(allocator, cfg.codex_home, cfg.cli_auth_credentials_store_mode) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/logout failed to delete auth", err);
    };

    const response = try renderJsonRpcResult(allocator, id_value, "{}");
    defer allocator.free(response);
    return renderResultWithAccountUpdatedNotification(allocator, response);
}

fn handleAccountRead(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    const params = switch (optionalAccountReadParams(params_value)) {
        .object => |object| object,
        .empty => null,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };

    var refresh_token = false;
    if (params) |object| {
        if (object.get("refreshToken")) |value| {
            if (value != .bool) return renderJsonRpcError(allocator, id_value, -32602, "refreshToken must be a boolean");
            refresh_token = value.bool;
        }
    }

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/read failed to load config", err);
    };
    defer cfg.deinit(allocator);

    const model_provider = config.loadModelProviderId(allocator, null) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/read failed to load model provider", err);
    };
    defer if (model_provider) |value| allocator.free(value);

    const is_bedrock = if (model_provider) |provider| std.mem.eql(u8, provider, "amazon-bedrock") else false;
    const provider_requires_openai_auth = config.loadModelProviderRequiresOpenAiAuth(allocator, null) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "account/read failed to load model provider auth requirements", err);
    };
    const requires_openai_auth = cfg.oss_provider == null and provider_requires_openai_auth;
    const account_json = if (requires_openai_auth)
        try renderOpenAiAccountJson(allocator, &cfg, refresh_token)
    else if (is_bedrock)
        try allocator.dupe(u8, "{\"type\":\"amazonBedrock\"}")
    else
        try allocator.dupe(u8, "null");
    defer allocator.free(account_json);

    const result = try std.fmt.allocPrint(
        allocator,
        "{{\"account\":{s},\"requiresOpenaiAuth\":{}}}",
        .{ account_json, requires_openai_auth },
    );
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn optionalAccountReadParams(params_value: ?std.json.Value) OptionalObjectParams {
    const params = params_value orelse return .empty;
    if (params == .null) return .empty;
    if (params != .object) return .{ .message = "account/read params must be an object" };
    return .{ .object = params.object };
}

fn renderOpenAiAccountJson(allocator: std.mem.Allocator, cfg: *const config.Config, refresh_token: bool) ![]const u8 {
    var credentials = blk: {
        const loaded = if (refresh_token)
            auth_mod.loadCliAuthForConfig(allocator, cfg)
        else
            auth_mod.loadCliAuthNoRefreshForConfig(allocator, cfg);
        break :blk loaded catch |err| switch (err) {
            error.NoUsableAuth => return allocator.dupe(u8, "null"),
            else => return err,
        };
    };
    defer credentials.deinit(allocator);

    switch (credentials.mode) {
        .api_key => return allocator.dupe(u8, "{\"type\":\"apiKey\"}"),
        .chatgpt, .chatgpt_auth_tokens, .agent_identity => {
            if (try auth_mod.loadActiveStoredChatGptAccountInfoWithMode(allocator, cfg.codex_home, cfg.cli_auth_credentials_store_mode)) |info| {
                defer info.deinit(allocator);
                return renderChatGptAccountJson(allocator, info);
            }
            return allocator.dupe(u8, "null");
        },
        .local_oss, .provider_no_auth => return allocator.dupe(u8, "null"),
    }
}

fn renderChatGptAccountJson(allocator: std.mem.Allocator, info: auth_mod.ChatGptAccountInfo) ![]const u8 {
    const email_json = try std.json.Stringify.valueAlloc(allocator, info.email, .{});
    defer allocator.free(email_json);
    const plan_type_json = try std.json.Stringify.valueAlloc(allocator, info.plan_type, .{});
    defer allocator.free(plan_type_json);
    return std.fmt.allocPrint(
        allocator,
        "{{\"type\":\"chatgpt\",\"email\":{s},\"planType\":{s}}}",
        .{ email_json, plan_type_json },
    );
}

fn renderResultWithAccountUpdatedNotification(allocator: std.mem.Allocator, response: []const u8) ![]const u8 {
    return std.fmt.allocPrint(
        allocator,
        "{s}\n{{\"method\":\"account/updated\",\"params\":{{\"authMode\":null,\"planType\":null}}}}",
        .{response},
    );
}

fn renderResultWithLoginNotifications(
    allocator: std.mem.Allocator,
    response: []const u8,
    auth_mode: []const u8,
    plan_type: ?[]const u8,
) ![]const u8 {
    const auth_mode_json = try std.json.Stringify.valueAlloc(allocator, auth_mode, .{});
    defer allocator.free(auth_mode_json);
    const plan_type_json = if (plan_type) |value|
        try std.json.Stringify.valueAlloc(allocator, value, .{})
    else
        try allocator.dupe(u8, "null");
    defer allocator.free(plan_type_json);

    return std.fmt.allocPrint(
        allocator,
        "{s}\n{{\"method\":\"account/login/completed\",\"params\":{{\"loginId\":null,\"success\":true,\"error\":null}}}}\n{{\"method\":\"account/updated\",\"params\":{{\"authMode\":{s},\"planType\":{s}}}}}",
        .{ response, auth_mode_json, plan_type_json },
    );
}

fn isModelMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "model/list") or
        std.mem.eql(u8, method, "modelProvider/capabilities/read");
}

fn handleModelMethod(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "model/list")) return handleModelList(allocator, id_value, params_value);
    if (std.mem.eql(u8, method, "modelProvider/capabilities/read")) {
        return handleModelProviderCapabilitiesRead(allocator, id_value, params_value);
    }
    return try renderJsonRpcError(allocator, id_value, -32601, "unknown model method");
}

fn handleModelList(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    const params = switch (optionalModelListParams(params_value)) {
        .object => |object| object,
        .empty => null,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };

    var cursor: ?[]const u8 = null;
    var limit: ?usize = null;
    var include_hidden = false;
    if (params) |object| {
        if (object.get("cursor")) |value| {
            if (value != .null) {
                if (value != .string) return renderJsonRpcError(allocator, id_value, -32602, "cursor must be a string or null");
                cursor = value.string;
            }
        }
        if (object.get("limit")) |value| {
            limit = switch (value) {
                .null => null,
                .integer => |integer| blk: {
                    if (integer < 0) return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null");
                    break :blk @intCast(integer);
                },
                .number_string => |number| std.fmt.parseUnsigned(usize, number, 10) catch {
                    return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null");
                },
                else => return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null"),
            };
        }
        include_hidden = switch (optionalBoolFieldValue(object, "includeHidden", false, true)) {
            .value => |value| value,
            .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
        };
    }

    const start = if (cursor) |value|
        std.fmt.parseUnsigned(usize, value, 10) catch {
            const message = try std.fmt.allocPrint(allocator, "invalid cursor: {s}", .{value});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
    else
        0;

    var cfg = config.loadWithOptions(allocator, .{}) catch null;
    if (cfg) |*loaded_cfg| {
        defer loaded_cfg.deinit(allocator);

        var maybe_scope_credentials = loadModelCatalogScopeCredentials(allocator, loaded_cfg) catch null;
        defer if (maybe_scope_credentials) |*credentials| credentials.deinit(allocator);

        var cached_models = try loadFreshModelCatalogCacheForConfig(allocator, loaded_cfg, maybe_scope_credentials);
        defer if (cached_models) |*cache| cache.deinit(allocator);
        if (cached_models) |*cache| {
            return handleCachedModelList(allocator, id_value, start, limit, include_hidden, cache, modelListUsesCodexBackend(allocator));
        }

        var maybe_refresh_credentials = maybe_scope_credentials;
        var refresh_credentials_owned = false;
        if (maybe_refresh_credentials == null) {
            maybe_refresh_credentials = auth_mod.loadForConfig(allocator, loaded_cfg) catch null;
            refresh_credentials_owned = maybe_refresh_credentials != null;
        }
        defer if (refresh_credentials_owned) {
            if (maybe_refresh_credentials) |*credentials| credentials.deinit(allocator);
        };

        if (maybe_refresh_credentials) |credentials| {
            var refreshed_models = refreshModelCatalogCacheIfAllowedForConfig(allocator, loaded_cfg, credentials) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => null,
            };
            defer if (refreshed_models) |*refresh| refresh.deinit(allocator);
            if (refreshed_models) |*refresh| {
                return handleCachedModelList(allocator, id_value, start, limit, include_hidden, &refresh.catalog, refresh.uses_codex_backend);
            }
        }
    }

    const total = bundledModelListTotal(include_hidden);
    if (start > total) {
        const message = try std.fmt.allocPrint(allocator, "cursor {d} exceeds total models {d}", .{ start, total });
        defer allocator.free(message);
        return renderJsonRpcError(allocator, id_value, -32600, message);
    }

    const effective_limit = @min(@max(limit orelse total, 1), total);
    const end = @min(start + effective_limit, total);

    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"data\":[");
    var visible_index: usize = 0;
    var emitted = false;
    const default_slug = model_catalog.defaultModel().slug;
    for (model_catalog.bundled_models) |model| {
        if (!include_hidden and model.hidden()) continue;
        if (visible_index >= start and visible_index < end) {
            if (emitted) try result.appendSlice(allocator, ",");
            try appendAppServerModelJson(allocator, &result, model, std.mem.eql(u8, model.slug, default_slug));
            emitted = true;
        }
        visible_index += 1;
    }
    try result.appendSlice(allocator, "],\"nextCursor\":");
    if (end < total) {
        const next_cursor = try std.fmt.allocPrint(allocator, "{d}", .{end});
        defer allocator.free(next_cursor);
        const next_cursor_json = try std.json.Stringify.valueAlloc(allocator, next_cursor, .{});
        defer allocator.free(next_cursor_json);
        try result.appendSlice(allocator, next_cursor_json);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, "}");

    return renderJsonRpcResult(allocator, id_value, result.items);
}

const OptionalObjectParams = union(enum) {
    object: std.json.ObjectMap,
    empty,
    message: []const u8,
};

fn optionalAppsListParams(params_value: ?std.json.Value) OptionalObjectParams {
    const params = params_value orelse return .empty;
    if (params == .null) return .empty;
    if (params != .object) return .{ .message = "app/list params must be an object" };
    const object = params.object;
    if (object.get("cursor")) |value| {
        if (value != .null and value != .string) return .{ .message = "cursor must be a string or null" };
    }
    if (object.get("limit")) |value| {
        switch (value) {
            .null => {},
            .integer => |integer| if (integer < 0 or integer > std.math.maxInt(u32)) return .{ .message = "limit must be a non-negative integer or null" },
            .number_string => |number| {
                _ = std.fmt.parseUnsigned(u32, number, 10) catch return .{ .message = "limit must be a non-negative integer or null" };
            },
            else => return .{ .message = "limit must be a non-negative integer or null" },
        }
    }
    if (object.get("threadId")) |value| {
        if (value != .null and value != .string) return .{ .message = "threadId must be a string or null" };
    }
    if (object.get("forceRefetch")) |value| {
        if (value != .bool) return .{ .message = "forceRefetch must be a boolean" };
    }
    return .{ .object = object };
}

fn optionalModelListParams(params_value: ?std.json.Value) OptionalObjectParams {
    const params = params_value orelse return .empty;
    if (params == .null) return .empty;
    if (params != .object) return .{ .message = "model/list params must be an object" };
    return .{ .object = params.object };
}

const MODEL_CACHE_FILE_NAME = "models_cache.json";
const MODEL_CACHE_CLIENT_VERSION = "0.0.1";
// The /models backend filters entries by minimal_client_version. Keep this
// aligned with the newest upstream client generation represented in the bundled
// catalog, not with the Zig port's local cache schema/version marker.
const MODEL_CATALOG_REFRESH_CLIENT_VERSION = "0.124.0";
const MODEL_CACHE_RUST_SOURCE_CLIENT_VERSION = "0.0.0";
const MODEL_CACHE_MIN_RUST_RELEASE_CLIENT_VERSION = Semver{ .major = 0, .minor = 98, .patch = 0 };
const MODEL_CACHE_TTL_MS: i64 = 300_000;
const MODEL_CACHE_MAX_BYTES: usize = 4 * 1024 * 1024;
const MODEL_CATALOG_REFRESH_TIMEOUT_MS: u64 = 5_000;
const MODEL_PERSONALITY_PLACEHOLDER = "{{ personality }}";
const DEFAULT_MODEL_INPUT_MODALITIES = [_][]const u8{ "text", "image" };

const Semver = struct {
    major: u32,
    minor: u32,
    patch: u32,
};

const CachedModelCatalog = struct {
    bytes: []u8,
    parsed: std.json.Parsed(std.json.Value),
    models: []const std.json.Value,
    etag: ?[]const u8 = null,
    cache_key: ?[]const u8 = null,

    fn deinit(self: *CachedModelCatalog, allocator: std.mem.Allocator) void {
        self.parsed.deinit();
        allocator.free(self.bytes);
        if (self.etag) |etag| allocator.free(etag);
        if (self.cache_key) |cache_key| allocator.free(cache_key);
    }
};

const RefreshedModelCatalog = struct {
    catalog: CachedModelCatalog,
    uses_codex_backend: bool,

    fn deinit(self: *RefreshedModelCatalog, allocator: std.mem.Allocator) void {
        self.catalog.deinit(allocator);
    }
};

const ModelCatalogFetchContext = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    cfg: *const config.Config,
    credentials: auth_mod.Credentials,
    done: std.Io.Event = .unset,
    result: ?CachedModelCatalog = null,
    err: ?anyerror = null,
};

const ModelCatalogCacheScope = struct {
    key: []const u8,
    allow_unscoped: bool,

    fn deinit(self: *ModelCatalogCacheScope, allocator: std.mem.Allocator) void {
        allocator.free(self.key);
    }
};

fn loadModelCatalogScopeCredentials(allocator: std.mem.Allocator, cfg: *const config.Config) !?auth_mod.Credentials {
    var credentials = if (cfg.model_provider_auth_command != null)
        try auth_mod.loadForConfig(allocator, cfg)
    else
        try auth_mod.loadCliAuthNoRefreshForConfig(allocator, cfg);
    errdefer credentials.deinit(allocator);
    if (!modelCatalogShouldScopeCredentials(cfg, credentials)) {
        credentials.deinit(allocator);
        return null;
    }
    return credentials;
}

fn loadFreshModelCatalogCacheForConfig(
    allocator: std.mem.Allocator,
    cfg: *const config.Config,
    credentials: ?auth_mod.Credentials,
) !?CachedModelCatalog {
    var scope = try modelCatalogCacheScope(allocator, cfg, credentials);
    defer scope.deinit(allocator);
    return loadModelCatalogCache(allocator, true, &scope);
}

fn loadModelCatalogCache(allocator: std.mem.Allocator, require_fresh: bool, scope: ?*const ModelCatalogCacheScope) !?CachedModelCatalog {
    const path = modelCatalogCachePath(allocator) catch return null;
    defer allocator.free(path);

    const bytes = std.Io.Dir.cwd().readFileAlloc(
        std.Io.Threaded.global_single_threaded.io(),
        path,
        allocator,
        .limited(MODEL_CACHE_MAX_BYTES),
    ) catch return null;

    return parseModelCatalogCacheBytes(allocator, bytes, .{
        .require_fresh = require_fresh,
        .cache_key = if (scope) |value| value.key else null,
        .allow_unscoped_cache = if (scope) |value| value.allow_unscoped else true,
    }) catch {
        allocator.free(bytes);
        return null;
    };
}

fn modelCatalogCachePath(allocator: std.mem.Allocator) ![]const u8 {
    const codex_home = try resolveCodexHome(allocator);
    defer allocator.free(codex_home);
    return std.fs.path.join(allocator, &.{ codex_home, MODEL_CACHE_FILE_NAME });
}

const ModelCatalogCacheParseOptions = struct {
    require_fresh: bool = true,
    cache_key: ?[]const u8 = null,
    allow_unscoped_cache: bool = false,
};

fn parseModelCatalogCacheBytes(allocator: std.mem.Allocator, bytes: []u8, options: ModelCatalogCacheParseOptions) !CachedModelCatalog {
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, bytes, .{});
    var keep = false;
    defer if (!keep) {
        parsed.deinit();
    };

    if (parsed.value != .object) return error.InvalidModelCatalogCache;
    const object = parsed.value.object;
    const client_version = cachedStringField(object, "client_version") orelse return error.InvalidModelCatalogCache;
    if (!modelCacheClientVersionIsCompatible(client_version)) return error.InvalidModelCatalogCache;
    const fetched_at = cachedStringField(object, "fetched_at") orelse return error.InvalidModelCatalogCache;
    const fetched_at_ms = parseThreadListRfc3339Milliseconds(fetched_at) orelse return error.InvalidModelCatalogCache;
    if (options.require_fresh and !modelCacheTimestampIsFresh(fetched_at_ms)) return error.InvalidModelCatalogCache;
    const models_value = object.get("models") orelse return error.InvalidModelCatalogCache;
    if (models_value != .array) return error.InvalidModelCatalogCache;
    for (models_value.array.items) |model| {
        if (!cachedModelIsUsable(model)) return error.InvalidModelCatalogCache;
    }
    const etag = if (cachedStringField(object, "etag")) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (etag) |value| allocator.free(value);
    const cache_key = if (cachedStringField(object, "cache_key")) |value|
        try allocator.dupe(u8, value)
    else
        null;
    errdefer if (cache_key) |value| allocator.free(value);
    if (options.cache_key) |expected| {
        if (cache_key) |actual| {
            if (!std.mem.eql(u8, actual, expected)) return error.InvalidModelCatalogCache;
        } else if (!options.allow_unscoped_cache) {
            return error.InvalidModelCatalogCache;
        }
    }

    keep = true;
    return .{
        .bytes = bytes,
        .parsed = parsed,
        .models = models_value.array.items,
        .etag = etag,
        .cache_key = cache_key,
    };
}

fn renewModelCatalogCacheForModelsEtag(
    allocator: std.mem.Allocator,
    cfg: *const config.Config,
    credentials: auth_mod.Credentials,
    etag: []const u8,
) !void {
    if (etag.len == 0) return;

    var scope = try modelCatalogCacheScope(allocator, cfg, modelCatalogScopeCredentials(cfg, credentials));
    defer scope.deinit(allocator);

    var cache = try loadModelCatalogCache(allocator, false, &scope) orelse {
        var refreshed = try refreshModelCatalogCacheIfAllowedForConfig(allocator, cfg, credentials);
        defer if (refreshed) |*value| value.deinit(allocator);
        return;
    };
    defer cache.deinit(allocator);

    if (cache.etag) |cached_etag| {
        if (std.mem.eql(u8, cached_etag, etag)) {
            if (cache.cache_key == null) {
                cache.cache_key = try allocator.dupe(u8, scope.key);
            }
            try persistModelCatalogCache(allocator, &cache);
            return;
        }
    }

    var refreshed = try refreshModelCatalogCacheIfAllowedForConfig(allocator, cfg, credentials);
    defer if (refreshed) |*value| value.deinit(allocator);
}

fn refreshModelCatalogCacheIfAllowedForConfig(
    allocator: std.mem.Allocator,
    cfg: *const config.Config,
    credentials: auth_mod.Credentials,
) !?RefreshedModelCatalog {
    if (!modelCatalogOnlineRefreshAllowed(cfg, credentials)) return null;

    var scope = try modelCatalogCacheScope(allocator, cfg, modelCatalogScopeCredentials(cfg, credentials));
    defer scope.deinit(allocator);
    var catalog = try fetchRemoteModelCatalog(allocator, cfg, credentials);
    errdefer catalog.deinit(allocator);
    catalog.cache_key = try allocator.dupe(u8, scope.key);
    persistModelCatalogCache(allocator, &catalog) catch {};
    return .{
        .catalog = catalog,
        .uses_codex_backend = modelCatalogCredentialsUseCodexBackend(credentials),
    };
}

fn modelCatalogOnlineRefreshAllowed(cfg: *const config.Config, credentials: auth_mod.Credentials) bool {
    return switch (credentials.mode) {
        .chatgpt, .chatgpt_auth_tokens, .agent_identity => cfg.oss_provider == null and cfg.model_provider_requires_openai_auth,
        .api_key => cfg.model_provider_auth_command != null,
        .local_oss, .provider_no_auth => false,
    };
}

fn modelCatalogScopeCredentials(cfg: *const config.Config, credentials: auth_mod.Credentials) ?auth_mod.Credentials {
    if (modelCatalogShouldScopeCredentials(cfg, credentials)) return credentials;
    return null;
}

fn modelCatalogShouldScopeCredentials(cfg: *const config.Config, credentials: auth_mod.Credentials) bool {
    if (cfg.model_provider_auth_command != null) return true;
    if (cfg.model_provider_env_key != null or cfg.model_provider_bearer_token != null) return false;
    if (cfg.oss_provider != null or !cfg.model_provider_requires_openai_auth) return false;
    return switch (credentials.mode) {
        .chatgpt, .chatgpt_auth_tokens, .agent_identity => true,
        .api_key, .local_oss, .provider_no_auth => false,
    };
}

fn modelCatalogCacheScope(
    allocator: std.mem.Allocator,
    cfg: *const config.Config,
    credentials: ?auth_mod.Credentials,
) !ModelCatalogCacheScope {
    var key = std.ArrayList(u8).empty;
    errdefer key.deinit(allocator);

    try appendModelCatalogCacheKeyPart(allocator, &key, "provider", cfg.model_provider_id orelse "openai");
    try appendModelCatalogCacheKeyPart(allocator, &key, "openai_base_url", cfg.openai_base_url);
    try appendModelCatalogCacheKeyPart(allocator, &key, "chatgpt_base_url", cfg.chatgpt_base_url);
    try appendModelCatalogCacheKeyPart(allocator, &key, "wire_api", cfg.model_provider_wire_api.label());
    try appendModelCatalogCacheKeyPart(allocator, &key, "auth_source", modelCatalogAuthSource(cfg));
    try appendModelCatalogCacheAuthKeyParts(allocator, &key, cfg);
    if (credentials) |creds| {
        try appendModelCatalogCacheCredentialKeyParts(allocator, &key, creds);
    }
    if (cfg.model_provider_query_params) |params| {
        for (params.entries) |entry| {
            try appendModelCatalogCacheKeyPart(allocator, &key, "query_key", entry.key);
            try appendModelCatalogCacheHashedKeyPart(allocator, &key, "query_value", entry.value);
        }
    }
    try appendModelCatalogCacheHeaderKeyParts(allocator, &key, cfg);

    return .{
        .key = try key.toOwnedSlice(allocator),
        .allow_unscoped = credentials == null and modelCatalogAllowsUnscopedCache(cfg),
    };
}

fn appendModelCatalogCacheKeyPart(
    allocator: std.mem.Allocator,
    key: *std.ArrayList(u8),
    name: []const u8,
    value: []const u8,
) !void {
    const len_text = try std.fmt.allocPrint(allocator, "{d}", .{value.len});
    defer allocator.free(len_text);
    try key.appendSlice(allocator, name);
    try key.append(allocator, ':');
    try key.appendSlice(allocator, len_text);
    try key.append(allocator, ':');
    try key.appendSlice(allocator, value);
    try key.append(allocator, '\n');
}

fn appendModelCatalogCacheHashedKeyPart(
    allocator: std.mem.Allocator,
    key: *std.ArrayList(u8),
    name: []const u8,
    value: []const u8,
) !void {
    const digest = try configVersionAlloc(allocator, value);
    defer allocator.free(digest);
    try appendModelCatalogCacheKeyPart(allocator, key, name, digest);
}

fn appendModelCatalogCacheOptionalEnvValue(
    allocator: std.mem.Allocator,
    key: *std.ArrayList(u8),
    name: []const u8,
    env_key: []const u8,
) !void {
    const value = try env.getOwnedDynamic(allocator, env_key);
    if (value) |owned| {
        defer allocator.free(owned);
        if (std.mem.trim(u8, owned, " \t\r\n").len == 0) {
            try appendModelCatalogCacheKeyPart(allocator, key, name, "empty");
        } else {
            try appendModelCatalogCacheHashedKeyPart(allocator, key, name, owned);
        }
    } else {
        try appendModelCatalogCacheKeyPart(allocator, key, name, "missing");
    }
}

fn appendModelCatalogCacheAuthKeyParts(
    allocator: std.mem.Allocator,
    key: *std.ArrayList(u8),
    cfg: *const config.Config,
) !void {
    if (cfg.model_provider_auth_command) |command| {
        try appendModelCatalogCacheHashedKeyPart(allocator, key, "auth_command.command", command.command);
        if (command.cwd) |cwd| {
            try appendModelCatalogCacheHashedKeyPart(allocator, key, "auth_command.cwd", cwd);
        } else {
            try appendModelCatalogCacheKeyPart(allocator, key, "auth_command.cwd", "null");
        }
        for (command.args.items) |arg| {
            try appendModelCatalogCacheHashedKeyPart(allocator, key, "auth_command.arg", arg);
        }
        const timeout_ms = try std.fmt.allocPrint(allocator, "{d}", .{command.timeout_ms});
        defer allocator.free(timeout_ms);
        try appendModelCatalogCacheKeyPart(allocator, key, "auth_command.timeout_ms", timeout_ms);
    }
    if (cfg.model_provider_env_key) |env_key| {
        try appendModelCatalogCacheKeyPart(allocator, key, "auth_env_key", env_key);
        try appendModelCatalogCacheOptionalEnvValue(allocator, key, "auth_env_value", env_key);
    }
    if (cfg.model_provider_bearer_token) |token| {
        try appendModelCatalogCacheHashedKeyPart(allocator, key, "auth_bearer_token", token);
    }
}

fn appendModelCatalogCacheCredentialKeyParts(
    allocator: std.mem.Allocator,
    key: *std.ArrayList(u8),
    creds: auth_mod.Credentials,
) !void {
    try appendModelCatalogCacheKeyPart(
        allocator,
        key,
        "credential.mode",
        authCacheModeLabel(creds.mode),
    );
    switch (creds.mode) {
        .local_oss, .provider_no_auth => {},
        else => try appendModelCatalogCacheHashedKeyPart(allocator, key, "credential.token", creds.token),
    }
    if (creds.account_id) |account_id| {
        try appendModelCatalogCacheHashedKeyPart(allocator, key, "credential.account_id", account_id);
    } else {
        try appendModelCatalogCacheKeyPart(allocator, key, "credential.account_id", "null");
    }
    if (creds.chatgpt_user_id) |chatgpt_user_id| {
        try appendModelCatalogCacheHashedKeyPart(allocator, key, "credential.chatgpt_user_id", chatgpt_user_id);
    } else {
        try appendModelCatalogCacheKeyPart(allocator, key, "credential.chatgpt_user_id", "null");
    }
    try appendModelCatalogCacheKeyPart(
        allocator,
        key,
        "credential.fedramp",
        if (creds.fedramp) "true" else "false",
    );
}

fn appendModelCatalogCacheHeaderKeyParts(
    allocator: std.mem.Allocator,
    key: *std.ArrayList(u8),
    cfg: *const config.Config,
) !void {
    if (cfg.model_provider_http_headers) |headers| {
        for (headers.entries) |entry| {
            try appendModelCatalogCacheKeyPart(allocator, key, "http_header.key", entry.key);
            try appendModelCatalogCacheHashedKeyPart(allocator, key, "http_header.value", entry.value);
        }
    }
    if (cfg.model_provider_env_http_headers) |headers| {
        for (headers.entries) |entry| {
            try appendModelCatalogCacheKeyPart(allocator, key, "env_header.key", entry.key);
            try appendModelCatalogCacheKeyPart(allocator, key, "env_header.env_key", entry.value);
            try appendModelCatalogCacheOptionalEnvValue(allocator, key, "env_header.value", entry.value);
        }
    }
}

fn modelCatalogAuthSource(cfg: *const config.Config) []const u8 {
    if (cfg.model_provider_auth_command != null) return "command";
    if (cfg.model_provider_env_key != null) return "env";
    if (cfg.model_provider_bearer_token != null) return "bearer";
    return "default";
}

fn modelCatalogAllowsUnscopedCache(cfg: *const config.Config) bool {
    if (cfg.model_provider_id) |provider| {
        if (!std.mem.eql(u8, provider, "openai")) return false;
    }
    if (cfg.model_provider_auth_command != null or
        cfg.model_provider_env_key != null or
        cfg.model_provider_bearer_token != null)
    {
        return false;
    }
    if (cfg.model_provider_query_params) |params| {
        if (params.entries.len > 0) return false;
    }
    if (cfg.model_provider_http_headers) |headers| {
        if (headers.entries.len > 0) return false;
    }
    if (cfg.model_provider_env_http_headers) |headers| {
        if (headers.entries.len > 0) return false;
    }
    return std.mem.eql(u8, cfg.openai_base_url, "https://api.openai.com/v1") and
        std.mem.eql(u8, cfg.chatgpt_base_url, "https://chatgpt.com/backend-api/codex");
}

test "model catalog unscoped cache rejects provider headers" {
    var cfg = testDefaultModelCatalogCacheConfig();
    try std.testing.expect(modelCatalogAllowsUnscopedCache(&cfg));

    var header_entries = [_]config.StringMapEntry{.{ .key = "X-Tenant", .value = "tenant-a" }};
    cfg.model_provider_http_headers = .{ .entries = header_entries[0..] };
    try std.testing.expect(!modelCatalogAllowsUnscopedCache(&cfg));

    cfg.model_provider_http_headers = null;
    cfg.model_provider_env_http_headers = .{ .entries = header_entries[0..] };
    try std.testing.expect(!modelCatalogAllowsUnscopedCache(&cfg));
}

test "model catalog cache scope includes credentials without leaking token" {
    var cfg = testDefaultModelCatalogCacheConfig();
    const command_args = [_][]const u8{};
    cfg.model_provider_auth_command = .{
        .command = "/bin/cat",
        .args = .{ .items = command_args[0..] },
    };
    const credentials: auth_mod.Credentials = .{
        .mode = .api_key,
        .token = "provider-token",
        .account_id = "acct-provider",
    };

    var scope = try modelCatalogCacheScope(std.testing.allocator, &cfg, credentials);
    defer scope.deinit(std.testing.allocator);

    try std.testing.expect(!scope.allow_unscoped);
    try std.testing.expect(std.mem.indexOf(u8, scope.key, "credential.mode") != null);
    try std.testing.expect(std.mem.indexOf(u8, scope.key, "credential.token") != null);
    try std.testing.expect(std.mem.indexOf(u8, scope.key, "provider-token") == null);
    try std.testing.expect(std.mem.indexOf(u8, scope.key, "acct-provider") == null);
}

test "model catalog cache scope hashes query values" {
    var cfg = testDefaultModelCatalogCacheConfig();
    var query_entries = [_]config.StringMapEntry{.{ .key = "api_key", .value = "secret-query-token" }};
    cfg.model_provider_query_params = .{ .entries = query_entries[0..] };

    var scope = try modelCatalogCacheScope(std.testing.allocator, &cfg, null);
    defer scope.deinit(std.testing.allocator);

    try std.testing.expect(!scope.allow_unscoped);
    try std.testing.expect(std.mem.indexOf(u8, scope.key, "query_key") != null);
    try std.testing.expect(std.mem.indexOf(u8, scope.key, "api_key") != null);
    try std.testing.expect(std.mem.indexOf(u8, scope.key, "query_value") != null);
    try std.testing.expect(std.mem.indexOf(u8, scope.key, "secret-query-token") == null);
}

test "model catalog cache scope includes backend auth but not default api keys" {
    var cfg = testDefaultModelCatalogCacheConfig();
    const backend_credentials: auth_mod.Credentials = .{
        .mode = .agent_identity,
