    try std.testing.expect(std.mem.indexOf(u8, backend_scope.key, "agent-token") == null);
    try std.testing.expect(std.mem.indexOf(u8, backend_scope.key, "acct-one") == null);

    const api_key_credentials: auth_mod.Credentials = .{
