fn fetchRemoteModelCatalog(
    allocator: std.mem.Allocator,
    cfg: *const config.Config,
    credentials: auth_mod.Credentials,
) !CachedModelCatalog {
    var io_instance: std.Io.Threaded = .init(allocator, .{ .async_limit = .limited(1) });
    defer io_instance.deinit();
    const io = io_instance.io();
    var context = ModelCatalogFetchContext{
        .allocator = allocator,
        .io = io,
        .cfg = cfg,
        .credentials = credentials,
    };
    var future = try io.concurrent(fetchRemoteModelCatalogTimeoutWorker, .{&context});
    const deadline = modelCatalogRequestDeadline(io, MODEL_CATALOG_REFRESH_TIMEOUT_MS);
    while (true) {
        context.done.waitTimeout(io, .{ .deadline = deadline }) catch |err| switch (err) {
            error.Timeout => {
                if (context.done.isSet()) break;
                const now = std.Io.Clock.Timestamp.now(io, .awake);
                if (std.Io.Clock.Timestamp.compare(now, .lt, deadline)) continue;
                _ = future.cancel(io);
                if (context.result) |*catalog| catalog.deinit(allocator);
                return error.Timeout;
            },
            else => |e| {
                _ = future.cancel(io);
                if (context.result) |*catalog| catalog.deinit(allocator);
                return e;
            },
        };
        break;
    }
    _ = future.await(io);
    if (context.result) |catalog| return catalog;
    return context.err orelse error.Canceled;
}

fn fetchRemoteModelCatalogTimeoutWorker(context: *ModelCatalogFetchContext) void {
    defer context.done.set(context.io);
    context.result = fetchRemoteModelCatalogWithIo(context.allocator, context.io, context.cfg, context.credentials) catch |err| {
        context.err = err;
        return;
    };
}

fn modelCatalogRequestDeadline(io: std.Io, timeout_ms: u64) std.Io.Clock.Timestamp {
    const timeout_ms_i64 = std.math.cast(i64, timeout_ms) orelse std.math.maxInt(i64);
    return std.Io.Clock.Timestamp.fromNow(io, .{
        .raw = std.Io.Duration.fromMilliseconds(timeout_ms_i64),
        .clock = .awake,
    });
}

fn fetchRemoteModelCatalogWithIo(
    allocator: std.mem.Allocator,
    io: std.Io,
    cfg: *const config.Config,
    credentials: auth_mod.Credentials,
) !CachedModelCatalog {
    const url = try modelCatalogRefreshUrl(allocator, cfg, credentials);
    defer allocator.free(url);

    var headers = std.ArrayList(std.http.Header).empty;
    defer headers.deinit(allocator);
    const auth_header = try auth_mod.authorizationHeader(allocator, credentials);
    defer allocator.free(auth_header);
    try headers.append(allocator, .{ .name = "Authorization", .value = auth_header });
    try headers.append(allocator, .{ .name = "Accept", .value = "application/json" });
    try headers.append(allocator, .{ .name = "User-Agent", .value = "codex-zig-port/0.0.1" });
    var provider_env_header_values = std.ArrayList([]const u8).empty;
    defer {
        for (provider_env_header_values.items) |value| allocator.free(value);
        provider_env_header_values.deinit(allocator);
    }
    try appendModelCatalogProviderHeaders(allocator, &headers, &provider_env_header_values, cfg);
    if (credentials.account_id) |account_id| {
        try headers.append(allocator, .{ .name = "ChatGPT-Account-ID", .value = account_id });
    }
    if (credentials.fedramp) {
        try headers.append(allocator, .{ .name = "X-OpenAI-Fedramp", .value = "true" });
    }

    var client = std.http.Client{ .allocator = allocator, .io = io };
    defer client.deinit();

    const uri = try std.Uri.parse(url);
    var request = try client.request(.GET, uri, .{
        .redirect_behavior = .unhandled,
        .extra_headers = headers.items,
    });
    defer request.deinit();
    try request.sendBodiless();

    var response_head_buffer: [8192]u8 = undefined;
    var response = try request.receiveHead(&response_head_buffer);
    const status: u16 = @intFromEnum(response.head.status);
    if (status < 200 or status >= 300) return error.ModelCatalogHttpStatus;

    const etag = try modelCatalogEtagFromHttpHeaders(allocator, response.head);
    errdefer if (etag) |value| allocator.free(value);

    const decompress_buffer: []u8 = switch (response.head.content_encoding) {
        .identity => &.{},
        .zstd => try allocator.alloc(u8, std.compress.zstd.default_window_len),
        .deflate, .gzip => try allocator.alloc(u8, std.compress.flate.max_window_len),
        .compress => return error.UnsupportedCompressionMethod,
    };
    defer if (response.head.content_encoding != .identity) allocator.free(decompress_buffer);

    const response_storage = try allocator.alloc(u8, MODEL_CACHE_MAX_BYTES);
    defer allocator.free(response_storage);
    var response_body = std.Io.Writer.fixed(response_storage);
    var transfer_buffer: [8192]u8 = undefined;
    var decompress: std.http.Decompress = undefined;
    const reader = response.readerDecompressing(&transfer_buffer, &decompress, decompress_buffer);
    _ = reader.streamRemaining(&response_body) catch |err| switch (err) {
        error.ReadFailed => return response.bodyErr().?,
        error.WriteFailed => return error.ModelCatalogResponseTooLarge,
        else => |e| return e,
    };

    const bytes = try allocator.dupe(u8, response_body.buffered());
    errdefer allocator.free(bytes);
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, bytes, .{});
    var keep = false;
    defer if (!keep) parsed.deinit();

    if (parsed.value != .object) return error.InvalidModelCatalogResponse;
    const models_value = parsed.value.object.get("models") orelse return error.InvalidModelCatalogResponse;
    if (models_value != .array) return error.InvalidModelCatalogResponse;
    for (models_value.array.items) |model| {
        if (!cachedModelIsUsable(model)) return error.InvalidModelCatalogResponse;
    }

    keep = true;
    return .{
        .bytes = bytes,
        .parsed = parsed,
        .models = models_value.array.items,
        .etag = etag,
    };
}

fn modelCatalogRefreshUrl(
    allocator: std.mem.Allocator,
    cfg: *const config.Config,
    credentials: auth_mod.Credentials,
) ![]const u8 {
    const base_url = switch (credentials.mode) {
        .chatgpt, .chatgpt_auth_tokens, .agent_identity => cfg.chatgpt_base_url,
        .api_key => cfg.openai_base_url,
        .local_oss, .provider_no_auth => return error.ModelCatalogRefreshUnavailable,
    };

    var url = std.ArrayList(u8).empty;
    errdefer url.deinit(allocator);
    try url.appendSlice(allocator, std.mem.trimEnd(u8, base_url, "/"));
    try url.appendSlice(allocator, "/models");
    var has_query = false;
    if (cfg.model_provider_query_params) |params| {
        if (params.entries.len > 0) {
            try url.append(allocator, '?');
            for (params.entries, 0..) |entry, index| {
                if (index > 0) try url.append(allocator, '&');
                try url.appendSlice(allocator, entry.key);
                try url.append(allocator, '=');
                try url.appendSlice(allocator, entry.value);
            }
            has_query = true;
        }
    }
    try url.append(allocator, if (has_query) '&' else '?');
    try url.appendSlice(allocator, "client_version=");
    try url.appendSlice(allocator, MODEL_CATALOG_REFRESH_CLIENT_VERSION);
    return url.toOwnedSlice(allocator);
}

fn appendModelCatalogProviderHeaders(
    allocator: std.mem.Allocator,
    headers: *std.ArrayList(std.http.Header),
    owned_env_values: *std.ArrayList([]const u8),
    cfg: *const config.Config,
) !void {
    if (cfg.model_provider_http_headers) |header_map| {
        for (header_map.entries) |entry| {
            try headers.append(allocator, .{ .name = entry.key, .value = entry.value });
        }
    }
    if (cfg.model_provider_env_http_headers) |header_map| {
        for (header_map.entries) |entry| {
            const value = try env.getOwnedDynamic(allocator, entry.value);
            if (value) |owned| {
                if (std.mem.trim(u8, owned, " \t\r\n").len == 0) {
                    allocator.free(owned);
                    continue;
                }
                owned_env_values.append(allocator, owned) catch |err| {
                    allocator.free(owned);
                    return err;
                };
                try headers.append(allocator, .{ .name = entry.key, .value = owned });
            }
        }
    }
}

fn modelCatalogEtagFromHttpHeaders(allocator: std.mem.Allocator, head: std.http.Client.Response.Head) !?[]const u8 {
    var iterator = head.iterateHeaders();
    while (iterator.next()) |header| {
        if (!std.ascii.eqlIgnoreCase(header.name, "etag")) continue;
        if (header.value.len == 0) continue;
        return try allocator.dupe(u8, header.value);
    }
    return null;
}

fn persistModelCatalogCache(allocator: std.mem.Allocator, catalog: *const CachedModelCatalog) !void {
    const path = try modelCatalogCachePath(allocator);
    defer allocator.free(path);

    const fetched_at = try formatThreadListCursorMilliseconds(allocator, currentUnixMilliseconds(), false);
    defer allocator.free(fetched_at);

    var rendered = std.ArrayList(u8).empty;
    defer rendered.deinit(allocator);
    try rendered.appendSlice(allocator, "{\"fetched_at\":");
    try appendJsonString(allocator, &rendered, fetched_at);
    try rendered.appendSlice(allocator, ",\"etag\":");
    try appendOptionalJsonString(allocator, &rendered, catalog.etag);
    try rendered.appendSlice(allocator, ",\"cache_key\":");
    try appendOptionalJsonString(allocator, &rendered, catalog.cache_key);
    try rendered.appendSlice(allocator, ",\"client_version\":");
    try appendJsonString(allocator, &rendered, MODEL_CACHE_CLIENT_VERSION);
    try rendered.appendSlice(allocator, ",\"models\":[");
    for (catalog.models, 0..) |model, index| {
        if (index > 0) try rendered.append(allocator, ',');
        const model_json = try std.json.Stringify.valueAlloc(allocator, model, .{});
        defer allocator.free(model_json);
        try rendered.appendSlice(allocator, model_json);
    }
    try rendered.appendSlice(allocator, "]}");

    const io = std.Io.Threaded.global_single_threaded.io();
    try ensureParentDir(io, path);
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = rendered.items });
}

fn modelCacheClientVersionIsCompatible(client_version: []const u8) bool {
    if (std.mem.eql(u8, client_version, MODEL_CACHE_CLIENT_VERSION)) return true;
    if (std.mem.eql(u8, client_version, MODEL_CACHE_RUST_SOURCE_CLIENT_VERSION)) return true;
    const parsed = parseWholeSemver(client_version) orelse return false;
    return semverAtLeast(parsed, MODEL_CACHE_MIN_RUST_RELEASE_CLIENT_VERSION);
}

fn parseWholeSemver(value: []const u8) ?Semver {
    var parts = std.mem.splitScalar(u8, value, '.');
    const major_text = parts.next() orelse return null;
    const minor_text = parts.next() orelse return null;
    const patch_text = parts.next() orelse return null;
    if (parts.next() != null) return null;
    if (major_text.len == 0 or minor_text.len == 0 or patch_text.len == 0) return null;
    return .{
        .major = std.fmt.parseUnsigned(u32, major_text, 10) catch return null,
        .minor = std.fmt.parseUnsigned(u32, minor_text, 10) catch return null,
        .patch = std.fmt.parseUnsigned(u32, patch_text, 10) catch return null,
    };
}

fn semverAtLeast(version: Semver, minimum: Semver) bool {
    if (version.major != minimum.major) return version.major > minimum.major;
    if (version.minor != minimum.minor) return version.minor > minimum.minor;
    return version.patch >= minimum.patch;
}

fn modelCacheTimestampIsFresh(fetched_at_ms: i64) bool {
    const age_ms = currentUnixMilliseconds() - fetched_at_ms;
    return age_ms <= MODEL_CACHE_TTL_MS;
}

const ModelListEntry = union(enum) {
    bundled: model_catalog.Entry,
    cached: std.json.Value,
};

const IndexedModelListEntry = struct {
    entry: ModelListEntry,
    order: usize,
};

fn handleCachedModelList(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    start: usize,
    limit: ?usize,
    include_hidden: bool,
    cache: *const CachedModelCatalog,
    uses_codex_backend: bool,
) ![]const u8 {
    var entries = std.ArrayList(IndexedModelListEntry).empty;
    defer entries.deinit(allocator);

    var order: usize = 0;
    for (model_catalog.bundled_models) |bundled_model| {
        const entry = if (cachedModelForSlug(cache.models, bundled_model.slug)) |cached_model|
            ModelListEntry{ .cached = cached_model }
        else
            ModelListEntry{ .bundled = bundled_model };
        if (!uses_codex_backend and !modelListEntrySupportedInApi(entry)) {
            order += 1;
            continue;
        }
        try entries.append(allocator, .{ .entry = entry, .order = order });
        order += 1;
    }
    for (cache.models) |cached_model| {
        const slug = cachedModelSlug(cached_model).?;
        if (model_catalog.bundledModel(slug) != null) continue;
        const entry = ModelListEntry{ .cached = cached_model };
        if (!uses_codex_backend and !modelListEntrySupportedInApi(entry)) continue;
        try entries.append(allocator, .{ .entry = entry, .order = order });
        order += 1;
    }
    std.mem.sort(IndexedModelListEntry, entries.items, {}, indexedModelListEntryLessThan);

    const total = modelListEntryTotal(entries.items, include_hidden);
    if (start > total) {
        const message = try std.fmt.allocPrint(allocator, "cursor {d} exceeds total models {d}", .{ start, total });
        defer allocator.free(message);
        return renderJsonRpcError(allocator, id_value, -32600, message);
    }

    const effective_limit = @min(@max(limit orelse total, 1), total);
    const end = @min(start + effective_limit, total);
    const default_slug = modelListDefaultSlug(entries.items);

    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"data\":[");
    var visible_index: usize = 0;
    var emitted = false;
    for (entries.items) |indexed| {
        if (!include_hidden and modelListEntryHidden(indexed.entry)) continue;
        if (visible_index >= start and visible_index < end) {
            if (emitted) try result.appendSlice(allocator, ",");
            const is_default = if (default_slug) |slug| std.mem.eql(u8, modelListEntrySlug(indexed.entry), slug) else false;
            try appendModelListEntryJson(allocator, &result, indexed.entry, is_default);
            emitted = true;
        }
        visible_index += 1;
    }
    try result.appendSlice(allocator, "],\"nextCursor\":");
    if (end < total) {
        const next_cursor = try std.fmt.allocPrint(allocator, "{d}", .{end});
        defer allocator.free(next_cursor);
        const next_cursor_json = try std.json.Stringify.valueAlloc(allocator, next_cursor, .{});
        defer allocator.free(next_cursor_json);
        try result.appendSlice(allocator, next_cursor_json);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, "}");

    return renderJsonRpcResult(allocator, id_value, result.items);
}

fn modelListUsesCodexBackend(allocator: std.mem.Allocator) bool {
    var cfg = config.loadWithOptions(allocator, .{}) catch return false;
    defer cfg.deinit(allocator);
    if (cfg.model_provider_auth_command != null or cfg.model_provider_env_key != null or cfg.model_provider_bearer_token != null) return false;

    var credentials = auth_mod.loadCliAuthNoRefreshForConfig(allocator, &cfg) catch return false;
    defer credentials.deinit(allocator);
    return modelCatalogCredentialsUseCodexBackend(credentials);
}

fn modelCatalogCredentialsUseCodexBackend(credentials: auth_mod.Credentials) bool {
    return switch (credentials.mode) {
        .chatgpt, .chatgpt_auth_tokens, .agent_identity => true,
        .api_key, .local_oss, .provider_no_auth => false,
    };
}

fn cachedModelForSlug(models: []const std.json.Value, slug: []const u8) ?std.json.Value {
    for (models) |model| {
        if (cachedModelSlug(model)) |model_slug| {
            if (std.mem.eql(u8, model_slug, slug)) return model;
        }
    }
    return null;
}

fn modelListEntryTotal(entries: []const IndexedModelListEntry, include_hidden: bool) usize {
    var total: usize = 0;
    for (entries) |entry| {
        if (include_hidden or !modelListEntryHidden(entry.entry)) total += 1;
    }
    return total;
}

fn modelListDefaultSlug(entries: []const IndexedModelListEntry) ?[]const u8 {
    for (entries) |entry| {
        if (!modelListEntryHidden(entry.entry)) return modelListEntrySlug(entry.entry);
    }
    if (entries.len > 0) return modelListEntrySlug(entries[0].entry);
    return null;
}

fn indexedModelListEntryLessThan(_: void, lhs: IndexedModelListEntry, rhs: IndexedModelListEntry) bool {
    const lhs_priority = modelListEntryPriority(lhs.entry);
    const rhs_priority = modelListEntryPriority(rhs.entry);
    if (lhs_priority != rhs_priority) return lhs_priority < rhs_priority;
    return lhs.order < rhs.order;
}

fn modelListEntrySlug(entry: ModelListEntry) []const u8 {
    return switch (entry) {
        .bundled => |model| model.slug,
        .cached => |model| cachedModelSlug(model).?,
    };
}

fn modelListEntryHidden(entry: ModelListEntry) bool {
    return switch (entry) {
        .bundled => |model| model.hidden(),
        .cached => |model| cachedModelHidden(model),
    };
}

fn modelListEntrySupportedInApi(entry: ModelListEntry) bool {
    return switch (entry) {
        .bundled => |model| model.supported_in_api,
        .cached => |model| cachedModelSupportedInApi(model),
    };
}

fn modelListEntryPriority(entry: ModelListEntry) i64 {
    return switch (entry) {
        .bundled => |model| @intCast(model.priority),
        .cached => |model| cachedModelPriority(model),
    };
}

fn appendModelListEntryJson(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    entry: ModelListEntry,
    is_default: bool,
) !void {
    switch (entry) {
        .bundled => |model| try appendAppServerModelJson(allocator, result, model, is_default),
        .cached => |model| try appendAppServerCachedModelJson(allocator, result, model, is_default),
    }
}

fn cachedModelIsUsable(value: std.json.Value) bool {
    if (value != .object) return false;
    const object = value.object;
    return cachedStringField(object, "slug") != null and
        cachedStringField(object, "display_name") != null and
        cachedStringField(object, "visibility") != null and
        cachedBoolFieldValue(object, "supported_in_api") != null and
        cachedIntegerField(object, "priority") != null and
        cachedArrayField(object, "supported_reasoning_levels") != null;
}

fn cachedModelSlug(value: std.json.Value) ?[]const u8 {
    if (value != .object) return null;
    return cachedStringField(value.object, "slug");
}

fn cachedModelHidden(value: std.json.Value) bool {
    if (value != .object) return true;
    const visibility = cachedStringField(value.object, "visibility") orelse return true;
    return !std.mem.eql(u8, visibility, "list");
}

fn cachedModelSupportedInApi(value: std.json.Value) bool {
    if (value != .object) return false;
    return cachedBoolField(value.object, "supported_in_api", false);
}

fn cachedModelPriority(value: std.json.Value) i64 {
    if (value != .object) return std.math.maxInt(i64);
    return cachedIntegerField(value.object, "priority") orelse std.math.maxInt(i64);
}

fn appendAppServerCachedModelJson(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    value: std.json.Value,
    is_default: bool,
) !void {
    const object = value.object;
    const slug = cachedStringField(object, "slug").?;
    const display_name = cachedStringField(object, "display_name").?;
    const description = cachedStringField(object, "description") orelse "";
    const default_reasoning = cachedStringField(object, "default_reasoning_level") orelse "none";

    try result.appendSlice(allocator, "{\"id\":");
    try appendJsonString(allocator, result, slug);
    try result.appendSlice(allocator, ",\"model\":");
    try appendJsonString(allocator, result, slug);
    try appendCachedUpgradeFields(allocator, result, cachedObjectField(object, "upgrade"));
    try result.appendSlice(allocator, ",\"availabilityNux\":");
    if (cachedObjectField(object, "availability_nux")) |nux| {
        if (cachedStringField(nux, "message")) |message| {
            try result.appendSlice(allocator, "{\"message\":");
            try appendJsonString(allocator, result, message);
            try result.appendSlice(allocator, "}");
        } else {
            try result.appendSlice(allocator, "null");
        }
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, ",\"displayName\":");
    try appendJsonString(allocator, result, display_name);
    try result.appendSlice(allocator, ",\"description\":");
    try appendJsonString(allocator, result, description);
    try result.appendSlice(allocator, ",\"hidden\":");
    try result.appendSlice(allocator, if (cachedModelHidden(value)) "true" else "false");
    try result.appendSlice(allocator, ",\"supportedReasoningEfforts\":");
    try appendCachedReasoningEfforts(allocator, result, cachedArrayField(object, "supported_reasoning_levels"));
    try result.appendSlice(allocator, ",\"defaultReasoningEffort\":");
    try appendJsonString(allocator, result, default_reasoning);
    try result.appendSlice(allocator, ",\"inputModalities\":");
    try appendCachedStringArray(allocator, result, cachedArrayField(object, "input_modalities"), DEFAULT_MODEL_INPUT_MODALITIES[0..]);
    try result.appendSlice(allocator, ",\"supportsPersonality\":");
    try result.appendSlice(allocator, if (cachedModelSupportsPersonality(object)) "true" else "false");
    try result.appendSlice(allocator, ",\"additionalSpeedTiers\":");
    try appendCachedStringArray(allocator, result, cachedArrayField(object, "additional_speed_tiers"), &.{});
    try result.appendSlice(allocator, ",\"serviceTiers\":");
    try appendCachedServiceTiers(allocator, result, cachedArrayField(object, "service_tiers"));
    try result.appendSlice(allocator, ",\"isDefault\":");
    try result.appendSlice(allocator, if (is_default) "true" else "false");
    try result.appendSlice(allocator, "}");
}

fn appendCachedUpgradeFields(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    upgrade: ?std.json.ObjectMap,
) !void {
    try result.appendSlice(allocator, ",\"upgrade\":");
    if (upgrade) |object| {
        if (cachedStringField(object, "model")) |model| {
            try appendJsonString(allocator, result, model);
            try result.appendSlice(allocator, ",\"upgradeInfo\":{\"model\":");
            try appendJsonString(allocator, result, model);
            try result.appendSlice(allocator, ",\"upgradeCopy\":null,\"modelLink\":null,\"migrationMarkdown\":");
            try appendOptionalJsonString(allocator, result, cachedStringField(object, "migration_markdown"));
            try result.appendSlice(allocator, "}");
            return;
        }
    }
    try result.appendSlice(allocator, "null,\"upgradeInfo\":null");
}

fn appendCachedReasoningEfforts(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    values: ?[]const std.json.Value,
) !void {
    try result.appendSlice(allocator, "[");
    var emitted = false;
    if (values) |items| {
        for (items) |item| {
            if (item != .object) continue;
            const effort = cachedStringField(item.object, "effort") orelse continue;
            const description = cachedStringField(item.object, "description") orelse "";
            if (emitted) try result.appendSlice(allocator, ",");
            try result.appendSlice(allocator, "{\"reasoningEffort\":");
            try appendJsonString(allocator, result, effort);
            try result.appendSlice(allocator, ",\"description\":");
            try appendJsonString(allocator, result, description);
            try result.appendSlice(allocator, "}");
            emitted = true;
        }
    }
    try result.appendSlice(allocator, "]");
}

fn appendCachedStringArray(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    values: ?[]const std.json.Value,
    default_values: []const []const u8,
) !void {
    if (values) |items| {
        try result.appendSlice(allocator, "[");
        var emitted = false;
        for (items) |item| {
            if (item != .string) continue;
            if (emitted) try result.appendSlice(allocator, ",");
            try appendJsonString(allocator, result, item.string);
            emitted = true;
        }
        try result.appendSlice(allocator, "]");
        return;
    }
    try appendJsonStringArray(allocator, result, default_values);
}

fn appendCachedServiceTiers(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    values: ?[]const std.json.Value,
) !void {
    try result.appendSlice(allocator, "[");
    var emitted = false;
    if (values) |items| {
        for (items) |item| {
            if (item != .object) continue;
            const id = cachedStringField(item.object, "id") orelse continue;
            const name = cachedStringField(item.object, "name") orelse continue;
            const description = cachedStringField(item.object, "description") orelse continue;
            if (emitted) try result.appendSlice(allocator, ",");
            try result.appendSlice(allocator, "{\"id\":");
            try appendJsonString(allocator, result, id);
            try result.appendSlice(allocator, ",\"name\":");
            try appendJsonString(allocator, result, name);
            try result.appendSlice(allocator, ",\"description\":");
            try appendJsonString(allocator, result, description);
            try result.appendSlice(allocator, "}");
            emitted = true;
        }
    }
    try result.appendSlice(allocator, "]");
}

fn cachedModelSupportsPersonality(object: std.json.ObjectMap) bool {
    const messages = cachedObjectField(object, "model_messages") orelse return false;
    const template = cachedStringField(messages, "instructions_template") orelse return false;
    if (std.mem.indexOf(u8, template, MODEL_PERSONALITY_PLACEHOLDER) == null) return false;
    const variables = cachedObjectField(messages, "instructions_variables") orelse return false;
    return cachedStringField(variables, "personality_default") != null and
        cachedStringField(variables, "personality_friendly") != null and
        cachedStringField(variables, "personality_pragmatic") != null;
}

fn cachedStringField(object: std.json.ObjectMap, name: []const u8) ?[]const u8 {
    const value = object.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .string) return null;
    return value.string;
}

fn cachedBoolField(object: std.json.ObjectMap, name: []const u8, default_value: bool) bool {
    return cachedBoolFieldValue(object, name) orelse default_value;
}

fn cachedBoolFieldValue(object: std.json.ObjectMap, name: []const u8) ?bool {
    const value = object.get(name) orelse return null;
    if (value != .bool) return null;
    return value.bool;
}

fn cachedIntegerField(object: std.json.ObjectMap, name: []const u8) ?i64 {
    const value = object.get(name) orelse return null;
    return switch (value) {
        .integer => |integer| integer,
        .number_string => |number| std.fmt.parseInt(i64, number, 10) catch null,
        else => null,
    };
}

fn cachedObjectField(object: std.json.ObjectMap, name: []const u8) ?std.json.ObjectMap {
    const value = object.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .object) return null;
    return value.object;
}

fn cachedArrayField(object: std.json.ObjectMap, name: []const u8) ?[]const std.json.Value {
    const value = object.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .array) return null;
    return value.array.items;
}

fn bundledModelListTotal(include_hidden: bool) usize {
    var total: usize = 0;
    for (model_catalog.bundled_models) |model| {
        if (include_hidden or !model.hidden()) total += 1;
    }
    return total;
}

fn appendAppServerModelJson(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    model: model_catalog.Entry,
    is_default: bool,
) !void {
    try result.appendSlice(allocator, "{\"id\":");
    try appendJsonString(allocator, result, model.slug);
    try result.appendSlice(allocator, ",\"model\":");
    try appendJsonString(allocator, result, model.slug);
    try result.appendSlice(allocator, ",\"upgrade\":");
    if (model.upgrade) |upgrade| try appendJsonString(allocator, result, upgrade.model) else try result.appendSlice(allocator, "null");
    try result.appendSlice(allocator, ",\"upgradeInfo\":");
    if (model.upgrade) |upgrade| {
        try result.appendSlice(allocator, "{\"model\":");
        try appendJsonString(allocator, result, upgrade.model);
        try result.appendSlice(allocator, ",\"upgradeCopy\":");
        try appendOptionalJsonString(allocator, result, upgrade.upgrade_copy);
        try result.appendSlice(allocator, ",\"modelLink\":");
        try appendOptionalJsonString(allocator, result, upgrade.model_link);
        try result.appendSlice(allocator, ",\"migrationMarkdown\":");
        try appendOptionalJsonString(allocator, result, upgrade.migration_markdown);
        try result.appendSlice(allocator, "}");
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, ",\"availabilityNux\":");
    if (model.availability_nux) |nux| {
        try result.appendSlice(allocator, "{\"message\":");
        try appendJsonString(allocator, result, nux.message);
        try result.appendSlice(allocator, "}");
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, ",\"displayName\":");
    try appendJsonString(allocator, result, model.display_name);
    try result.appendSlice(allocator, ",\"description\":");
    try appendJsonString(allocator, result, model.description);
    try result.appendSlice(allocator, ",\"hidden\":");
    try result.appendSlice(allocator, if (model.hidden()) "true" else "false");
    try result.appendSlice(allocator, ",\"supportedReasoningEfforts\":[");
    for (model.supported_reasoning_levels, 0..) |reasoning, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try result.appendSlice(allocator, "{\"reasoningEffort\":");
        try appendJsonString(allocator, result, reasoning.effort);
        try result.appendSlice(allocator, ",\"description\":");
        try appendJsonString(allocator, result, reasoning.description);
        try result.appendSlice(allocator, "}");
    }
    try result.appendSlice(allocator, "],\"defaultReasoningEffort\":");
    try appendJsonString(allocator, result, model.default_reasoning_level);
    try result.appendSlice(allocator, ",\"inputModalities\":");
    try appendJsonStringArray(allocator, result, model.input_modalities);
    try result.appendSlice(allocator, ",\"supportsPersonality\":");
    try result.appendSlice(allocator, if (model.supports_personality) "true" else "false");
    try result.appendSlice(allocator, ",\"additionalSpeedTiers\":");
    try appendJsonStringArray(allocator, result, model.additional_speed_tiers);
    try result.appendSlice(allocator, ",\"serviceTiers\":[");
    for (model.service_tiers, 0..) |tier, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try result.appendSlice(allocator, "{\"id\":");
        try appendJsonString(allocator, result, tier.id);
        try result.appendSlice(allocator, ",\"name\":");
        try appendJsonString(allocator, result, tier.name);
        try result.appendSlice(allocator, ",\"description\":");
        try appendJsonString(allocator, result, tier.description);
        try result.appendSlice(allocator, "}");
    }
    try result.appendSlice(allocator, "],\"isDefault\":");
    try result.appendSlice(allocator, if (is_default) "true" else "false");
    try result.appendSlice(allocator, "}");
}

fn appendJsonString(allocator: std.mem.Allocator, result: *std.ArrayList(u8), value: []const u8) !void {
    const value_json = try std.json.Stringify.valueAlloc(allocator, value, .{});
    defer allocator.free(value_json);
    try result.appendSlice(allocator, value_json);
}

fn appendJsonBool(allocator: std.mem.Allocator, result: *std.ArrayList(u8), value: bool) !void {
    try result.appendSlice(allocator, if (value) "true" else "false");
}

fn appendOptionalJsonString(allocator: std.mem.Allocator, result: *std.ArrayList(u8), value: ?[]const u8) !void {
    if (value) |payload| {
        try appendJsonString(allocator, result, payload);
    } else {
        try result.appendSlice(allocator, "null");
    }
}

fn appendJsonStringArray(allocator: std.mem.Allocator, result: *std.ArrayList(u8), values: []const []const u8) !void {
    try result.appendSlice(allocator, "[");
    for (values, 0..) |value, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        try appendJsonString(allocator, result, value);
    }
    try result.appendSlice(allocator, "]");
}

fn handleModelProviderCapabilitiesRead(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    if (validateOptionalObjectParams(params_value)) |message| {
        return renderJsonRpcError(allocator, id_value, -32602, message);
    }

    const model_provider = config.loadModelProviderId(allocator, null) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "modelProvider/capabilities/read failed to load config", err);
    };
    defer if (model_provider) |value| allocator.free(value);

    const supports_default_tools = if (model_provider) |provider|
        !std.mem.eql(u8, provider, "amazon-bedrock")
    else
        true;
    const result = try std.fmt.allocPrint(
        allocator,
        "{{\"namespaceTools\":{},\"imageGeneration\":{},\"webSearch\":{}}}",
        .{ supports_default_tools, supports_default_tools, supports_default_tools },
    );
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn isCollaborationModeMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "collaborationMode/list");
}

fn handleCollaborationModeMethod(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "collaborationMode/list")) {
        return handleCollaborationModeList(allocator, id_value, params_value);
    }
    return renderJsonRpcError(allocator, id_value, -32601, "unknown collaboration mode method");
}

fn handleCollaborationModeList(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (validateOptionalObjectParams(params_value)) |message| {
        return renderJsonRpcError(allocator, id_value, -32602, message);
    }

    const result =
        \\{"data":[{"name":"Plan","mode":"plan","model":null,"reasoning_effort":"medium"},{"name":"Default","mode":"default","model":null,"reasoning_effort":null}]}
    ;
    return renderJsonRpcResult(allocator, id_value, result);
}

fn isPermissionProfileMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "permissionProfile/list");
}

fn handlePermissionProfileMethod(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "permissionProfile/list")) {
        return handlePermissionProfileList(allocator, state, id_value, params_value);
    }
    return renderJsonRpcError(allocator, id_value, -32601, "unknown permission profile method");
}

const built_in_permission_profile_ids = [_][]const u8{
    ":read-only",
    ":workspace",
    ":danger-full-access",
};

const PermissionProfileSummaryEntry = struct {
    id: []const u8,
    description: ?[]const u8 = null,

    fn deinit(self: *PermissionProfileSummaryEntry, allocator: std.mem.Allocator) void {
        allocator.free(self.id);
        if (self.description) |value| allocator.free(value);
    }
};

const PermissionProfileCatalog = struct {
    items: std.ArrayList(PermissionProfileSummaryEntry) = .empty,

    fn deinit(self: *PermissionProfileCatalog, allocator: std.mem.Allocator) void {
        for (self.items.items) |*item| item.deinit(allocator);
        self.items.deinit(allocator);
    }
};

fn handlePermissionProfileList(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = switch (optionalPermissionProfileListParams(params_value)) {
        .object => |object| object,
        .empty => null,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };

    var cursor: ?[]const u8 = null;
    var limit: ?usize = null;
    var cwd: ?[]const u8 = null;
    if (params) |object| {
        if (object.get("cursor")) |value| {
            if (value != .null) {
                if (value != .string) return renderJsonRpcError(allocator, id_value, -32602, "cursor must be a string or null");
                cursor = value.string;
            }
        }
        if (object.get("limit")) |value| {
            limit = switch (value) {
                .null => null,
                .integer => |integer| blk: {
                    if (integer < 0) return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null");
                    break :blk @intCast(integer);
                },
                .number_string => |number| std.fmt.parseUnsigned(usize, number, 10) catch {
                    return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null");
                },
                else => return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null"),
            };
        }
        if (object.get("cwd")) |value| {
            if (value != .null) {
                if (value != .string) return renderJsonRpcError(allocator, id_value, -32602, "cwd must be a string or null");
                cwd = value.string;
            }
        }
    }

    var cfg = loadAppServerConfigWithOptions(allocator, state, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "permissionProfile/list failed to load config", err);
    };
    defer cfg.deinit(allocator);

    var layers = loadPermissionProfileConfigLayerBytes(allocator, cfg.codex_home, cwd) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "permissionProfile/list failed to load profiles", err);
    };
    defer layers.deinit(allocator);
    var catalog = loadPermissionProfileCatalog(allocator, layers.items.items) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "permissionProfile/list failed to load profiles", err);
    };
    defer catalog.deinit(allocator);
    std.mem.sort(PermissionProfileSummaryEntry, catalog.items.items, {}, permissionProfileSummaryLessThan);

    const total = built_in_permission_profile_ids.len + catalog.items.items.len;
    const start = if (cursor) |value|
        std.fmt.parseUnsigned(usize, value, 10) catch {
            const message = try std.fmt.allocPrint(allocator, "invalid cursor: {s}", .{value});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
    else
        0;

    if (start > total) {
        const message = try std.fmt.allocPrint(allocator, "cursor {d} exceeds total permission profiles {d}", .{ start, total });
        defer allocator.free(message);
        return renderJsonRpcError(allocator, id_value, -32600, message);
    }

    const effective_limit = @min(@max(limit orelse total, 1), total);
    const end = @min(start + effective_limit, total);

    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"data\":[");
    var index = start;
    while (index < end) : (index += 1) {
        if (index > start) try result.appendSlice(allocator, ",");
        try appendPermissionProfileSummaryAt(allocator, &result, catalog.items.items, index);
    }
    try result.appendSlice(allocator, "],\"nextCursor\":");
    if (end < total) {
        const next_cursor = try std.fmt.allocPrint(allocator, "{d}", .{end});
        defer allocator.free(next_cursor);
        try appendJsonString(allocator, &result, next_cursor);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, "}");

    return renderJsonRpcResult(allocator, id_value, result.items);
}

fn optionalPermissionProfileListParams(params_value: ?std.json.Value) OptionalObjectParams {
    const params = params_value orelse return .empty;
    if (params == .null) return .empty;
    if (params != .object) return .{ .message = "permissionProfile/list params must be an object" };
    return .{ .object = params.object };
}

fn loadPermissionProfileCatalog(
    allocator: std.mem.Allocator,
    layer_bytes: []const []const u8,
) !PermissionProfileCatalog {
    var catalog = PermissionProfileCatalog{};
    errdefer catalog.deinit(allocator);

    for (layer_bytes) |bytes| {
        try parsePermissionProfileConfigBytes(allocator, &catalog, bytes);
    }

    return catalog;
}

const PermissionProfileConfigLayerBytes = struct {
    items: std.ArrayList([]const u8) = .empty,

    fn deinit(self: *PermissionProfileConfigLayerBytes, allocator: std.mem.Allocator) void {
        for (self.items.items) |bytes| allocator.free(bytes);
        self.items.deinit(allocator);
    }
};

fn loadSandboxPermissionProfileFromAppServerConfigStack(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    cwd: []const u8,
    profile_id: []const u8,
    options: config.SandboxPermissionProfileOptions,
) !config.SandboxPermissionProfile {
    var layers = try loadPermissionProfileConfigLayerBytes(allocator, codex_home, cwd);
    defer layers.deinit(allocator);
    return config.loadSandboxPermissionProfileFromConfigLayerBytesWithOptions(
        allocator,
        profile_id,
        layers.items.items,
        options,
    );
}

fn loadPermissionProfileConfigLayerBytes(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    cwd: ?[]const u8,
) !PermissionProfileConfigLayerBytes {
    var layers = PermissionProfileConfigLayerBytes{};
    errdefer layers.deinit(allocator);

    const system_config_path = try systemConfigPath(allocator);
    defer allocator.free(system_config_path);
    const system_config_bytes = try appendPermissionProfileLayerBytes(allocator, &layers, try config.readConfigTomlFile(allocator, system_config_path));

    const user_config_path = try config.configTomlPath(allocator, codex_home);
    defer allocator.free(user_config_path);
    const user_config_bytes = try appendPermissionProfileLayerBytes(allocator, &layers, try config.readConfigTomlFile(allocator, user_config_path));

    if (cwd) |project_cwd| {
        const resolved_project_cwd = try resolvePermissionProfileCwd(allocator, project_cwd);
        defer allocator.free(resolved_project_cwd);
        var trusted_ancestors = try configReadTrustedProjectAncestorsFromLayers(allocator, resolved_project_cwd, system_config_bytes, user_config_bytes);
        defer trusted_ancestors.deinit(allocator);
        var ancestor_index = trusted_ancestors.items.len;
        while (ancestor_index > 0) {
            ancestor_index -= 1;
            const ancestor = trusted_ancestors.items[ancestor_index];
            const dot_codex_folder = try std.fs.path.join(allocator, &.{ ancestor, ".codex" });
            defer allocator.free(dot_codex_folder);
            if (std.mem.eql(u8, dot_codex_folder, codex_home)) continue;

            const project_config_path = try std.fs.path.join(allocator, &.{ dot_codex_folder, "config.toml" });
            defer allocator.free(project_config_path);
            _ = try appendPermissionProfileLayerBytes(allocator, &layers, try config.readConfigTomlFile(allocator, project_config_path));
        }
    }

    const managed_config_path = try managedConfigPath(allocator);
    defer allocator.free(managed_config_path);
    _ = try appendPermissionProfileLayerBytes(allocator, &layers, try config.readConfigTomlFile(allocator, managed_config_path));

    return layers;
}

fn appendPermissionProfileLayerBytes(
    allocator: std.mem.Allocator,
    layers: *PermissionProfileConfigLayerBytes,
    bytes_opt: ?[]const u8,
) !?[]const u8 {
    const bytes = bytes_opt orelse return null;
    errdefer allocator.free(bytes);
    try layers.items.append(allocator, bytes);
    return bytes;
}

fn configReadTrustedProjectAncestorsFromLayers(
    allocator: std.mem.Allocator,
    cwd: []const u8,
    system_config_bytes: ?[]const u8,
    user_config_bytes: ?[]const u8,
) !std.ArrayList([]const u8) {
    var ancestors = std.ArrayList([]const u8).empty;
    errdefer ancestors.deinit(allocator);

    const project_root = try configReadProjectRootForCwd(allocator, cwd, system_config_bytes, user_config_bytes);
    defer allocator.free(project_root);

    const project_root_trust = try configReadProjectTrustLevelFromLayers(allocator, system_config_bytes, user_config_bytes, project_root);
    const repo_root = try resolveProjectTrustRepoRoot(allocator, cwd);
    defer if (repo_root) |root| allocator.free(root);
    const repo_root_trust = if (repo_root) |root|
        try configReadProjectTrustLevelFromLayers(allocator, system_config_bytes, user_config_bytes, root)
    else
        .unknown;

    var chain = std.ArrayList([]const u8).empty;
    defer chain.deinit(allocator);
    var current = cwd;
    while (true) {
        try chain.append(allocator, current);
        if (std.mem.eql(u8, current, project_root)) break;
        const parent = std.fs.path.dirname(current) orelse break;
        if (std.mem.eql(u8, parent, current)) break;
        current = parent;
    }

    var trusted_root_to_leaf = std.ArrayList([]const u8).empty;
    defer trusted_root_to_leaf.deinit(allocator);
    var effective_trust = repo_root_trust;
    var index = chain.items.len;
    while (index > 0) {
        index -= 1;
        const path = chain.items[index];
        const direct_trust = try configReadProjectTrustLevelFromLayers(allocator, system_config_bytes, user_config_bytes, path);
        if (direct_trust != .unknown) {
            effective_trust = direct_trust;
        } else if (index == chain.items.len - 1 and project_root_trust != .unknown) {
            effective_trust = project_root_trust;
        }
        if (effective_trust == .trusted) try trusted_root_to_leaf.append(allocator, path);
    }

    index = trusted_root_to_leaf.items.len;
    while (index > 0) {
        index -= 1;
        try ancestors.append(allocator, trusted_root_to_leaf.items[index]);
    }

    return ancestors;
}

fn configReadProjectRootForCwd(
    allocator: std.mem.Allocator,
    cwd: []const u8,
    system_config_bytes: ?[]const u8,
    user_config_bytes: ?[]const u8,
) ![]const u8 {
    var markers = try configReadProjectRootMarkers(allocator, system_config_bytes, user_config_bytes);
    defer markers.deinit(allocator);
    if (markers.items.len == 0) return allocator.dupe(u8, cwd);

    var current = try allocator.dupe(u8, cwd);
    errdefer allocator.free(current);

    while (true) {
        if (try configReadDirHasProjectRootMarker(allocator, current, markers.items)) return current;

        const parent = std.fs.path.dirname(current) orelse break;
        if (std.mem.eql(u8, parent, current)) break;
        const next = try allocator.dupe(u8, parent);
        allocator.free(current);
        current = next;
    }

    allocator.free(current);
    return allocator.dupe(u8, cwd);
}

fn configReadProjectRootMarkers(
    allocator: std.mem.Allocator,
    system_config_bytes: ?[]const u8,
    user_config_bytes: ?[]const u8,
) !config.StringList {
    var markers: ?config.StringList = null;
    errdefer if (markers) |*existing| existing.deinit(allocator);

    if (system_config_bytes) |bytes| {
        markers = try config.topLevelStringArrayValue(allocator, bytes, "project_root_markers");
    }
    if (user_config_bytes) |bytes| {
        if (try config.topLevelStringArrayValue(allocator, bytes, "project_root_markers")) |user_markers| {
            if (markers) |*existing| existing.deinit(allocator);
            markers = user_markers;
        }
    }

    if (markers) |value| return value;
    return stringListFromLabels(allocator, &.{".git"});
}

fn configReadDirHasProjectRootMarker(
    allocator: std.mem.Allocator,
    dir: []const u8,
    markers: []const []const u8,
) !bool {
    for (markers) |marker| {
        if (marker.len == 0) continue;
        const marker_path = try std.fs.path.join(allocator, &.{ dir, marker });
        defer allocator.free(marker_path);
        if (configReadPathExists(marker_path)) return true;
    }
    return false;
}

fn configReadPathExists(path: []const u8) bool {
    _ = std.Io.Dir.cwd().statFile(std.Io.Threaded.global_single_threaded.io(), path, .{
        .follow_symlinks = false,
    }) catch return false;
    return true;
}

const ConfigReadProjectTrustLevel = enum {
    unknown,
    trusted,
    untrusted,
};

fn configReadProjectTrustedFromLayers(
    allocator: std.mem.Allocator,
    system_config_bytes: ?[]const u8,
    user_config_bytes: ?[]const u8,
    cwd: []const u8,
) !bool {
    return (try configReadProjectTrustLevelFromLayers(allocator, system_config_bytes, user_config_bytes, cwd)) == .trusted;
}

fn configReadProjectTrustLevelFromLayers(
    allocator: std.mem.Allocator,
    system_config_bytes: ?[]const u8,
    user_config_bytes: ?[]const u8,
    cwd: []const u8,
) !ConfigReadProjectTrustLevel {
    var trust_level: ?[]const u8 = null;
    defer if (trust_level) |value| allocator.free(value);

    if (system_config_bytes) |bytes| {
        trust_level = try config.namedSectionStringValue(allocator, bytes, "projects.", cwd, "trust_level");
    }
    if (user_config_bytes) |bytes| {
        if (try config.namedSectionStringValue(allocator, bytes, "projects.", cwd, "trust_level")) |value| {
            if (trust_level) |existing| allocator.free(existing);
            trust_level = value;
        }
    }

    return if (trust_level) |value|
        if (std.mem.eql(u8, value, "trusted"))
            .trusted
        else if (std.mem.eql(u8, value, "untrusted"))
            .untrusted
        else
            .unknown
    else
        .unknown;
}

fn resolvePermissionProfileCwd(allocator: std.mem.Allocator, raw: []const u8) ![]const u8 {
    return realPathFileAllocPlain(allocator, raw);
}

fn parsePermissionProfileConfigBytes(
    allocator: std.mem.Allocator,
    catalog: *PermissionProfileCatalog,
    bytes: []const u8,
) !void {
    var current_section: ?[]const u8 = null;
    var multiline_string: ?TomlMultilineStringKind = null;
    var layer_profiles = std.ArrayList([]const u8).empty;
    defer {
        for (layer_profiles.items) |profile_id| allocator.free(profile_id);
        layer_profiles.deinit(allocator);
    }

    var iter = std.mem.splitScalar(u8, bytes, '\n');
    while (iter.next()) |line_raw| {
        if (tomlLineIsMultilineStringBody(&multiline_string, line_raw)) continue;
        const line_without_comment = stripTomlLineComment(line_raw);
        const line = std.mem.trim(u8, line_without_comment, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        if (line[0] == '[') {
            current_section = configWriteTomlSectionPath(line);
            if (current_section) |section| {
                var section_path = (parseConfigReadTomlDottedPath(allocator, section) catch |err| switch (err) {
                    error.InvalidConfigReadProfileDottedKey, error.InvalidTomlString => null,
                    else => return err,
                }) orelse continue;
                defer section_path.deinit(allocator);
                try applyPermissionProfileTomlPath(allocator, catalog, &layer_profiles, section_path.items, null);
            }
            continue;
        }
        const eq = tomlAssignmentEqualsIndex(line) orelse continue;
        const lhs = std.mem.trim(u8, line[0..eq], " \t");
        const rhs = std.mem.trim(u8, line[eq + 1 ..], " \t");
        var path = (configWriteAssignmentPath(allocator, current_section, lhs) catch |err| switch (err) {
            error.InvalidConfigReadProfileDottedKey, error.InvalidConfigReadAppSection, error.InvalidTomlString => null,
            else => return err,
        }) orelse continue;
        defer path.deinit(allocator);

        if (permissionProfileTomlPathIsDescription(path.items)) {
            if (permissionProfileMultilineStringKind(rhs)) |kind| {
                if (!tomlMultilineStringValueClosed(rhs, kind)) {
                    var collected = std.ArrayList(u8).empty;
                    errdefer collected.deinit(allocator);
                    try collected.appendSlice(allocator, rhs);

                    var closed = false;
                    while (iter.next()) |body_line_raw| {
                        try collected.append(allocator, '\n');
                        try collected.appendSlice(allocator, body_line_raw);
                        if (std.mem.indexOf(u8, body_line_raw, kind.delimiter()) != null) {
                            closed = true;
                            break;
                        }
                    }
                    if (!closed) return error.InvalidTomlString;

                    const multiline_rhs = try collected.toOwnedSlice(allocator);
                    defer allocator.free(multiline_rhs);
                    try applyPermissionProfileTomlPath(allocator, catalog, &layer_profiles, path.items, multiline_rhs);
                    continue;
                }
            }
        }

        try applyPermissionProfileTomlPath(allocator, catalog, &layer_profiles, path.items, rhs);
        observeTomlMultilineStringOpen(&multiline_string, line_without_comment);
    }
}

fn permissionProfileTomlPathIsDescription(path_items: []const []const u8) bool {
    return path_items.len == 3 and
        std.mem.eql(u8, path_items[0], "permissions") and
        std.mem.eql(u8, path_items[2], "description");
}

fn permissionProfileMultilineStringKind(rhs_raw: []const u8) ?TomlMultilineStringKind {
    const rhs = std.mem.trim(u8, rhs_raw, " \t");
    if (std.mem.startsWith(u8, rhs, "\"\"\"")) return .basic;
    if (std.mem.startsWith(u8, rhs, "'''")) return .literal;
    return null;
}

fn tomlMultilineStringValueClosed(rhs_raw: []const u8, kind: TomlMultilineStringKind) bool {
    const rhs = std.mem.trim(u8, rhs_raw, " \t");
    const delimiter = kind.delimiter();
    return std.mem.indexOfPos(u8, rhs, delimiter.len, delimiter) != null;
}

fn applyPermissionProfileTomlPath(
    allocator: std.mem.Allocator,
    catalog: *PermissionProfileCatalog,
    layer_profiles: *std.ArrayList([]const u8),
    path_items: []const []const u8,
    rhs: ?[]const u8,
) !void {
    if (path_items.len == 1 and std.mem.eql(u8, path_items[0], "permissions")) {
        const value = rhs orelse return;
        try applyPermissionProfilesInlineTable(allocator, catalog, layer_profiles, value);
        return;
    }

    if (path_items.len < 2 or !std.mem.eql(u8, path_items[0], "permissions")) return;
    const profile_id = path_items[1];
    const value = rhs orelse {
        _ = try touchPermissionProfileEntryForLayer(allocator, catalog, layer_profiles, profile_id);
        return;
    };

    if (path_items.len == 3 and std.mem.eql(u8, path_items[2], "description")) {
        try setPermissionProfileDescriptionFromToml(allocator, catalog, layer_profiles, profile_id, value);
        return;
    }

    if (path_items.len == 2) {
        try applyPermissionProfileInlineTable(allocator, catalog, layer_profiles, profile_id, value);
        return;
    }

    _ = try touchPermissionProfileEntryForLayer(allocator, catalog, layer_profiles, profile_id);
}

fn applyPermissionProfilesInlineTable(
    allocator: std.mem.Allocator,
    catalog: *PermissionProfileCatalog,
    layer_profiles: *std.ArrayList([]const u8),
    raw: []const u8,
) !void {
    const body = try configReadInlineTableBody(raw);
    var field_start: usize = 0;
    while (try nextConfigReadInlineTableField(body, &field_start)) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = tomlAssignmentEqualsIndex(field) orelse continue;
        const profile_id = (try parseConfigReadInlineFieldKey(allocator, field[0..eq])) orelse continue;
        defer allocator.free(profile_id);

        const value = std.mem.trim(u8, field[eq + 1 ..], " \t\r\n");
        try applyPermissionProfileInlineTable(allocator, catalog, layer_profiles, profile_id, value);
    }
}

fn applyPermissionProfileInlineTable(
    allocator: std.mem.Allocator,
    catalog: *PermissionProfileCatalog,
    layer_profiles: *std.ArrayList([]const u8),
    profile_id: []const u8,
    raw: []const u8,
) !void {
    const body = try configReadInlineTableBody(raw);
    _ = try touchPermissionProfileEntryForLayer(allocator, catalog, layer_profiles, profile_id);
    var field_start: usize = 0;
    while (try nextConfigReadInlineTableField(body, &field_start)) |field_raw| {
        const field = std.mem.trim(u8, field_raw, " \t\r\n");
        if (field.len == 0) continue;
        const eq = tomlAssignmentEqualsIndex(field) orelse continue;
        const key = (try parseConfigReadInlineFieldKey(allocator, field[0..eq])) orelse continue;
        defer allocator.free(key);
        if (!std.mem.eql(u8, key, "description")) continue;
        try setPermissionProfileDescriptionFromToml(allocator, catalog, layer_profiles, profile_id, field[eq + 1 ..]);
    }
}

fn ensurePermissionProfileEntry(
    allocator: std.mem.Allocator,
    catalog: *PermissionProfileCatalog,
    profile_id: []const u8,
) !usize {
    for (catalog.items.items, 0..) |entry, index| {
        if (std.mem.eql(u8, entry.id, profile_id)) return index;
    }

    const owned_id = try allocator.dupe(u8, profile_id);
    errdefer allocator.free(owned_id);
    try catalog.items.append(allocator, .{ .id = owned_id });
    return catalog.items.items.len - 1;
}

fn touchPermissionProfileEntryForLayer(
    allocator: std.mem.Allocator,
    catalog: *PermissionProfileCatalog,
    layer_profiles: *std.ArrayList([]const u8),
    profile_id: []const u8,
) !usize {
    const index = try ensurePermissionProfileEntry(allocator, catalog, profile_id);
    for (layer_profiles.items) |seen_id| {
        if (std.mem.eql(u8, seen_id, profile_id)) return index;
    }

    const owned_id = try allocator.dupe(u8, profile_id);
    errdefer allocator.free(owned_id);
    try layer_profiles.append(allocator, owned_id);
    return index;
}

fn setPermissionProfileDescriptionFromToml(
    allocator: std.mem.Allocator,
    catalog: *PermissionProfileCatalog,
    layer_profiles: *std.ArrayList([]const u8),
    profile_id: []const u8,
    rhs_raw: []const u8,
) !void {
    const rhs = std.mem.trim(u8, rhs_raw, " \t\r\n");
    const description = try parsePermissionProfileDescriptionString(allocator, rhs) orelse return error.InvalidTomlString;
    errdefer allocator.free(description);
    const index = try touchPermissionProfileEntryForLayer(allocator, catalog, layer_profiles, profile_id);
    if (catalog.items.items[index].description) |existing| allocator.free(existing);
    catalog.items.items[index].description = description;
}

fn parsePermissionProfileDescriptionString(allocator: std.mem.Allocator, rhs: []const u8) !?[]const u8 {
    if (std.mem.startsWith(u8, rhs, "\"\"\"")) return try config.parseTomlStringValue(allocator, rhs);
    if (std.mem.startsWith(u8, rhs, "'''")) return try parsePermissionProfileMultilineLiteralString(allocator, rhs);
    if (rhs.len > 0 and rhs[0] == '\'') return try parsePermissionProfileLiteralString(allocator, rhs);
    return try config.parseTomlString(allocator, rhs);
}

fn parsePermissionProfileLiteralString(allocator: std.mem.Allocator, rhs: []const u8) ![]const u8 {
    return parseConfigReadTomlLiteralString(allocator, rhs);
}

fn parsePermissionProfileMultilineLiteralString(allocator: std.mem.Allocator, rhs: []const u8) ![]const u8 {
    if (!std.mem.startsWith(u8, rhs, "'''")) return error.InvalidTomlString;

    var start: usize = 3;
    if (start < rhs.len and rhs[start] == '\n') {
        start += 1;
    } else if (start + 1 < rhs.len and rhs[start] == '\r' and rhs[start + 1] == '\n') {
        start += 2;
    }

    const end = std.mem.indexOfPos(u8, rhs, start, "'''") orelse return error.InvalidTomlString;
    return allocator.dupe(u8, rhs[start..end]);
}

fn permissionProfileSummaryLessThan(_: void, lhs: PermissionProfileSummaryEntry, rhs: PermissionProfileSummaryEntry) bool {
    return std.mem.lessThan(u8, lhs.id, rhs.id);
}

fn appendPermissionProfileSummaryAt(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    custom_profiles: []const PermissionProfileSummaryEntry,
    index: usize,
) !void {
    if (index < built_in_permission_profile_ids.len) {
        try appendPermissionProfileSummaryJson(allocator, result, built_in_permission_profile_ids[index], null);
        return;
    }

    const custom = custom_profiles[index - built_in_permission_profile_ids.len];
    try appendPermissionProfileSummaryJson(allocator, result, custom.id, custom.description);
}

fn appendPermissionProfileSummaryJson(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    id: []const u8,
    description: ?[]const u8,
) !void {
    try result.appendSlice(allocator, "{\"id\":");
    try appendJsonString(allocator, result, id);
    try result.appendSlice(allocator, ",\"description\":");
    try appendOptionalJsonString(allocator, result, description);
    try result.appendSlice(allocator, "}");
}

fn isExperimentalFeatureMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "experimentalFeature/list") or
        std.mem.eql(u8, method, "experimentalFeature/enablement/set");
}

fn handleExperimentalFeatureMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "experimentalFeature/list")) {
        return handleExperimentalFeatureList(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "experimentalFeature/enablement/set")) {
        return handleExperimentalFeatureEnablementSet(allocator, state, id_value, params_value);
    }
    return try renderJsonRpcError(allocator, id_value, -32601, "unknown experimental feature method");
}

fn handleExperimentalFeatureList(
    allocator: std.mem.Allocator,
    state: *const AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = switch (optionalExperimentalFeatureListParams(params_value)) {
        .object => |object| object,
        .empty => null,
        .message => |message| return renderJsonRpcError(allocator, id_value, -32602, message),
    };

    var cursor: ?[]const u8 = null;
    var limit: ?usize = null;
    if (params) |object| {
        if (object.get("cursor")) |value| {
            if (value != .null) {
                if (value != .string) return renderJsonRpcError(allocator, id_value, -32602, "cursor must be a string or null");
                cursor = value.string;
            }
        }
        if (object.get("limit")) |value| {
            limit = switch (value) {
                .null => null,
                .integer => |integer| blk: {
                    if (integer < 0) return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null");
                    break :blk @intCast(integer);
                },
                .number_string => |number| std.fmt.parseUnsigned(usize, number, 10) catch {
                    return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null");
                },
                else => return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null"),
            };
        }
    }

    const start = if (cursor) |value|
        std.fmt.parseUnsigned(usize, value, 10) catch {
            const message = try std.fmt.allocPrint(allocator, "invalid cursor: {s}", .{value});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
    else
        0;

    const all_features = features_cmd.FeatureSpec.all;
    const total = all_features.len;
    if (start > total) {
        const message = try std.fmt.allocPrint(allocator, "cursor {d} exceeds total feature flags {d}", .{ start, total });
        defer allocator.free(message);
        return renderJsonRpcError(allocator, id_value, -32600, message);
    }

    var cfg = config.loadWithOptions(allocator, .{}) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "experimentalFeature/list failed to load config", err);
    };
    defer cfg.deinit(allocator);
    var feature_overrides = features_cmd.loadFeatureOverridesForProfile(allocator, cfg.codex_home, cfg.active_profile) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "experimentalFeature/list failed to load feature config", err);
    };
    defer feature_overrides.deinit(allocator);
    var requirements = loadConfigRequirementsReadRequirements(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "experimentalFeature/list failed to load config requirements", err);
    };
    defer requirements.deinit(allocator);

    const effective_limit = if (total == 0) 0 else @min(@max(limit orelse total, 1), total);
    const end = @min(start + effective_limit, total);

    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"data\":[");
    for (all_features[start..end], 0..) |feature, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        const enabled = featureRequirementValue(requirements.feature_requirements, feature.key) orelse
            state.cli_feature_overrides.get(feature.key) orelse
            feature_overrides.get(feature.key) orelse
            state.runtime_feature_enablement.get(feature.key) orelse
            feature.default_enabled;
        try appendExperimentalFeatureJson(allocator, &result, feature, enabled);
    }
    try result.appendSlice(allocator, "],\"nextCursor\":");
    if (end < total) {
        const next_cursor = try std.fmt.allocPrint(allocator, "{d}", .{end});
        defer allocator.free(next_cursor);
        const next_cursor_json = try std.json.Stringify.valueAlloc(allocator, next_cursor, .{});
        defer allocator.free(next_cursor_json);
        try result.appendSlice(allocator, next_cursor_json);
    } else {
        try result.appendSlice(allocator, "null");
    }
    try result.appendSlice(allocator, "}");

    return renderJsonRpcResult(allocator, id_value, result.items);
}

fn optionalExperimentalFeatureListParams(params_value: ?std.json.Value) OptionalObjectParams {
    const params = params_value orelse return .empty;
    if (params == .null) return .empty;
    if (params != .object) return .{ .message = "experimentalFeature/list params must be an object" };
    return .{ .object = params.object };
}

fn appendExperimentalFeatureJson(
    allocator: std.mem.Allocator,
    result: *std.ArrayList(u8),
    feature: features_cmd.FeatureSpec,
    enabled: bool,
) !void {
    const key_json = try std.json.Stringify.valueAlloc(allocator, feature.key, .{});
    defer allocator.free(key_json);
    try result.appendSlice(allocator, "{\"name\":");
    try result.appendSlice(allocator, key_json);
    try result.appendSlice(allocator, ",\"stage\":\"");
    try result.appendSlice(allocator, experimentalFeatureStageLabel(feature.stage));
    try result.appendSlice(allocator, "\",\"displayName\":");
    if (std.mem.eql(u8, feature.stage, "experimental")) {
        try result.appendSlice(allocator, key_json);
        try result.appendSlice(allocator, ",\"description\":\"Experimental Zig feature flag.\",\"announcement\":\"Available for opt-in testing in the Zig port.\"");
    } else {
        try result.appendSlice(allocator, "null,\"description\":null,\"announcement\":null");
    }
    try result.appendSlice(allocator, ",\"enabled\":");
    try result.appendSlice(allocator, if (enabled) "true" else "false");
    try result.appendSlice(allocator, ",\"defaultEnabled\":");
    try result.appendSlice(allocator, if (feature.default_enabled) "true" else "false");
    try result.appendSlice(allocator, "}");
}

fn experimentalFeatureStageLabel(stage: []const u8) []const u8 {
    if (std.mem.eql(u8, stage, "experimental")) return "beta";
    if (std.mem.eql(u8, stage, "under development")) return "underDevelopment";
    if (std.mem.eql(u8, stage, "stable")) return "stable";
    if (std.mem.eql(u8, stage, "deprecated")) return "deprecated";
    if (std.mem.eql(u8, stage, "removed")) return "removed";
    return "underDevelopment";
}

const supported_experimental_feature_enablement = [_][]const u8{
    "apps",
    "memories",
    "plugins",
    "remote_control",
    "tool_search",
    "tool_suggest",
    "tool_call_mcp_elicitation",
};

const supported_experimental_feature_enablement_message = "apps, memories, plugins, remote_control, tool_search, tool_suggest, tool_call_mcp_elicitation";

fn handleExperimentalFeatureEnablementSet(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = params_value orelse return renderJsonRpcError(allocator, id_value, -32602, "experimentalFeature/enablement/set params must be an object");
    if (params != .object) return renderJsonRpcError(allocator, id_value, -32602, "experimentalFeature/enablement/set params must be an object");
    const enablement = params.object.get("enablement") orelse return renderJsonRpcError(allocator, id_value, -32602, "enablement must be an object");
    if (enablement != .object) return renderJsonRpcError(allocator, id_value, -32602, "enablement must be an object");

    for (enablement.object.keys(), enablement.object.values()) |key, value| {
        if (value != .bool) return renderJsonRpcError(allocator, id_value, -32602, "enablement values must be booleans");
        if (!features_cmd.isCanonicalFeatureKey(key)) {
            if (features_cmd.canonicalFeatureKey(key)) |canonical| {
                const message = try std.fmt.allocPrint(
                    allocator,
                    "invalid feature enablement `{s}`: use canonical feature key `{s}`",
                    .{ key, canonical },
                );
                defer allocator.free(message);
                return renderJsonRpcError(allocator, id_value, -32600, message);
            }
            const message = try std.fmt.allocPrint(allocator, "invalid feature enablement `{s}`", .{key});
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
        if (!isSupportedExperimentalFeatureEnablement(key)) {
            const message = try std.fmt.allocPrint(
                allocator,
                "unsupported feature enablement `{s}`: currently supported features are {s}",
                .{ key, supported_experimental_feature_enablement_message },
            );
            defer allocator.free(message);
            return renderJsonRpcError(allocator, id_value, -32600, message);
        }
    }

    for (enablement.object.keys(), enablement.object.values()) |key, value| {
        try state.runtime_feature_enablement.put(allocator, key, value.bool);
    }

    const result = try renderExperimentalFeatureEnablementResponse(allocator, enablement.object);
    defer allocator.free(result);
    if (enablement.object.get("apps")) |apps_value| {
        if (apps_value.bool) queueAppListUpdatedNotificationAfterEnablement(allocator, state) catch {};
    }
    return renderJsonRpcResult(allocator, id_value, result);
}

fn isSupportedExperimentalFeatureEnablement(key: []const u8) bool {
    for (supported_experimental_feature_enablement) |supported| {
        if (std.mem.eql(u8, key, supported)) return true;
    }
    return false;
}

fn renderExperimentalFeatureEnablementResponse(allocator: std.mem.Allocator, enablement: std.json.ObjectMap) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    errdefer result.deinit(allocator);

    try result.appendSlice(allocator, "{\"enablement\":{");
    for (enablement.keys(), enablement.values(), 0..) |key, value, index| {
        if (index > 0) try result.appendSlice(allocator, ",");
        const key_json = try std.json.Stringify.valueAlloc(allocator, key, .{});
        defer allocator.free(key_json);
        try result.appendSlice(allocator, key_json);
        try result.appendSlice(allocator, if (value.bool) ":true" else ":false");
    }
    try result.appendSlice(allocator, "}}");
    return result.toOwnedSlice(allocator);
}

const McpStatusParams = struct {
    cursor: ?usize = null,
    limit: ?usize = null,
    detail: McpStatusDetail = .full,
};

const McpStatusDetail = enum {
    full,
    tools_and_auth_only,
};

const McpServerOauthLoginParams = struct {
    name: []const u8,
    scopes: std.ArrayList([]const u8) = .empty,
    scopes_present: bool = false,
    timeout_secs: ?i64 = null,

    fn deinit(self: *McpServerOauthLoginParams, allocator: std.mem.Allocator) void {
        self.scopes.deinit(allocator);
    }
};

const McpResourceReadParams = struct {
    thread_id: ?[]const u8 = null,
    server: []const u8,
    uri: []const u8,
};

const McpServerToolCallParams = struct {
    thread_id: []const u8,
    server: []const u8,
    tool: []const u8,
    arguments: ?std.json.Value = null,
    meta: ?std.json.Value = null,
};

fn isMcpServerMethod(method: []const u8) bool {
    return std.mem.eql(u8, method, "config/mcpServer/reload") or
        std.mem.eql(u8, method, "mcpServer/oauth/login") or
        std.mem.eql(u8, method, "mcpServerStatus/list") or
        std.mem.eql(u8, method, "mcpServer/resource/read") or
        std.mem.eql(u8, method, "mcpServer/tool/call");
}

fn handleMcpServerMethod(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    method: []const u8,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (std.mem.eql(u8, method, "config/mcpServer/reload")) {
        return handleMcpServerReload(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "mcpServer/oauth/login")) {
        return handleMcpServerOauthLogin(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "mcpServerStatus/list")) {
        return handleMcpServerStatusList(allocator, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "mcpServer/resource/read")) {
        return handleMcpResourceRead(allocator, state, id_value, params_value);
    }
    if (std.mem.eql(u8, method, "mcpServer/tool/call")) {
        return handleMcpServerToolCall(allocator, state, id_value, params_value);
    }
    return renderJsonRpcError(allocator, id_value, -32601, "unknown MCP server method");
}

fn handleMcpServerReload(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    if (params_value) |params| {
        if (params != .null and params != .object) {
            return renderJsonRpcError(allocator, id_value, -32602, "config/mcpServer/reload params must be an object, null, or omitted");
        }
    }

    var cfg = config.load(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/mcpServer/reload failed to load config", err);
    };
    defer cfg.deinit(allocator);

    const config_bytes = mcp_cmd.readConfigToml(allocator, cfg.codex_home) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/mcpServer/reload failed to load MCP config", err);
    };
    defer if (config_bytes) |bytes| allocator.free(bytes);

    var servers = mcp_cmd.loadServersFromConfig(allocator, cfg.codex_home, config_bytes orelse "") catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "config/mcpServer/reload failed to load MCP servers", err);
    };
    defer servers.deinit(allocator);

    return renderJsonRpcResult(allocator, id_value, "{}");
}

fn handleMcpServerOauthLogin(allocator: std.mem.Allocator, state: *AppServerState, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    var params = parseMcpServerOauthLoginParams(allocator, params_value) catch |err| switch (err) {
        error.InvalidMcpOauthLoginParams => return renderJsonRpcError(allocator, id_value, -32602, "mcpServer/oauth/login params must be an object"),
        error.InvalidMcpOauthLoginName => return renderJsonRpcError(allocator, id_value, -32602, "name must be a string"),
        error.InvalidMcpOauthLoginScopes => return renderJsonRpcError(allocator, id_value, -32602, "scopes must be an array of strings or null"),
        error.InvalidMcpOauthLoginTimeout => return renderJsonRpcError(allocator, id_value, -32602, "timeoutSecs must be an integer or null"),
        else => return err,
    };
    defer params.deinit(allocator);

    const codex_home = resolveCodexHome(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServer/oauth/login failed to resolve CODEX_HOME", err);
    };
    defer allocator.free(codex_home);

    const config_bytes = mcp_cmd.readConfigToml(allocator, codex_home) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServer/oauth/login failed to load MCP config", err);
    };
    defer if (config_bytes) |bytes| allocator.free(bytes);
    var servers = mcp_cmd.loadServersFromConfig(allocator, codex_home, config_bytes orelse "") catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServer/oauth/login failed to load MCP servers", err);
    };
    defer servers.deinit(allocator);

    const server = servers.get(params.name) orelse return renderMcpServerNotFound(allocator, id_value, params.name);
    if (server.kind != .streamable_http or server.url == null) {
        return renderJsonRpcError(allocator, id_value, -32600, "OAuth login is only supported for streamable HTTP servers.");
    }

    const requested_scopes = if (params.scopes_present) params.scopes.items else server.scopes.items;
    var login_handle = mcp_cmd.startMcpOAuthLoginReturnUrl(allocator, codex_home, config_bytes orelse "", server.*, requested_scopes, !params.scopes_present) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServer/oauth/login failed to start OAuth login", err);
    };
    errdefer login_handle.deinit(allocator);

    const response = try renderMcpServerOauthLoginResponse(allocator, id_value, login_handle.authorization_url);
    errdefer allocator.free(response);
    var completion_target = try makeAppServerBackgroundNotificationTarget(allocator, state.connection_output);
    errdefer completion_target.deinit(allocator);
    try spawnMcpServerOauthLoginWorker(allocator, params.name, login_handle, params.timeout_secs, completion_target);
    return response;
}

const AppServerBackgroundNotificationTarget = union(enum) {
    stdout,
    socket: struct {
        output: *AppServerConnectionOutputState,
        fd: std.posix.fd_t,
    },

    fn deinit(self: *AppServerBackgroundNotificationTarget, allocator: std.mem.Allocator) void {
        switch (self.*) {
            .stdout => {},
            .socket => |target| {
                closeFd(target.fd);
                releaseAppServerConnectionOutput(allocator, target.output);
            },
        }
        self.* = .stdout;
    }

    fn send(self: *AppServerBackgroundNotificationTarget, payload: []const u8) !void {
        switch (self.*) {
            .stdout => try writeStdoutLine(payload),
            .socket => |target| try writeAppServerBackgroundSocketNotification(target.output, target.fd, payload),
        }
    }
};

fn makeAppServerBackgroundNotificationTarget(
    allocator: std.mem.Allocator,
    output: ?*AppServerConnectionOutputState,
) !AppServerBackgroundNotificationTarget {
    _ = allocator;
    const connection_output = output orelse return .stdout;
    const duplicated_fd = try duplicateFd(connection_output.socket_handle);
    retainAppServerConnectionOutput(connection_output);
    return .{ .socket = .{ .output = connection_output, .fd = duplicated_fd } };
}

const McpServerOauthLoginWorker = struct {
    name: []const u8,
    handle: mcp_cmd.McpOAuthLoginHandle,
    timeout_secs: ?i64 = null,
    completion_target: AppServerBackgroundNotificationTarget,

    fn deinit(self: *McpServerOauthLoginWorker, allocator: std.mem.Allocator) void {
        allocator.free(self.name);
        self.handle.deinit(allocator);
        self.completion_target.deinit(allocator);
    }
};

fn spawnMcpServerOauthLoginWorker(
    allocator: std.mem.Allocator,
    name: []const u8,
    handle: mcp_cmd.McpOAuthLoginHandle,
    timeout_secs: ?i64,
    completion_target: AppServerBackgroundNotificationTarget,
) !void {
    const worker = try allocator.create(McpServerOauthLoginWorker);
    var worker_initialized = false;
    errdefer {
        if (worker_initialized) worker.deinit(allocator);
        allocator.destroy(worker);
    }
    const name_owned = try allocator.dupe(u8, name);
    errdefer if (!worker_initialized) allocator.free(name_owned);
    worker.* = .{
        .name = name_owned,
        .handle = handle,
        .timeout_secs = timeout_secs,
        .completion_target = completion_target,
    };
    worker_initialized = true;
    const thread = try std.Thread.spawn(.{ .allocator = allocator }, mcpServerOauthLoginWorker, .{ allocator, worker });
    thread.detach();
}

fn mcpServerOauthLoginWorker(allocator: std.mem.Allocator, worker: *McpServerOauthLoginWorker) void {
    const maybe_error = if (worker.handle.waitAndSave(allocator, worker.timeout_secs)) |_| null else |err| @errorName(err);
    var notification_storage: [4096]u8 = undefined;
    var notification_writer = std.Io.Writer.fixed(&notification_storage);
    writeMcpServerOauthLoginCompletedNotification(&notification_writer, worker.name, maybe_error == null, maybe_error) catch {
        worker.deinit(allocator);
        allocator.destroy(worker);
        return;
    };

    var completion_target = worker.completion_target;
    worker.completion_target = .stdout;
    allocator.free(worker.name);
    worker.handle.deinit(allocator);
    allocator.destroy(worker);

    completion_target.send(notification_writer.buffer[0..notification_writer.end]) catch {};
    completion_target.deinit(allocator);
}

fn renderMcpServerOauthLoginResponse(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    authorization_url: []const u8,
) ![]const u8 {
    var result = std.ArrayList(u8).empty;
    defer result.deinit(allocator);
    try result.appendSlice(allocator, "{\"authorizationUrl\":");
    try appendJsonString(allocator, &result, authorization_url);
    try result.append(allocator, '}');
    return renderJsonRpcResult(allocator, id_value, result.items);
}

fn writeMcpServerOauthLoginCompletedNotification(
    writer: *std.Io.Writer,
    name: []const u8,
    success: bool,
    error_message: ?[]const u8,
) !void {
    try writer.writeAll("{\"jsonrpc\":\"2.0\",\"method\":\"mcpServer/oauthLogin/completed\",\"params\":{\"name\":");
    try writeJsonStringLiteral(writer, name);
    try writer.writeAll(",\"success\":");
    try writer.writeAll(if (success) "true" else "false");
    try writer.writeAll(",\"error\":");
    if (error_message) |message| {
        try writeJsonStringLiteral(writer, message);
    } else {
        try writer.writeAll("null");
    }
    try writer.writeAll("}}");
}

fn writeJsonStringLiteral(writer: *std.Io.Writer, value: []const u8) !void {
    const hex = "0123456789abcdef";
    try writer.writeByte('"');
    for (value) |byte| {
        switch (byte) {
            '"' => try writer.writeAll("\\\""),
            '\\' => try writer.writeAll("\\\\"),
            '\n' => try writer.writeAll("\\n"),
            '\r' => try writer.writeAll("\\r"),
            '\t' => try writer.writeAll("\\t"),
            else => {
                if (byte < 0x20) {
                    try writer.writeAll("\\u00");
                    try writer.writeByte(hex[byte >> 4]);
                    try writer.writeByte(hex[byte & 0x0f]);
                } else {
                    try writer.writeByte(byte);
                }
            },
        }
    }
    try writer.writeByte('"');
}

fn handleMcpServerStatusList(allocator: std.mem.Allocator, id_value: std.json.Value, params_value: ?std.json.Value) ![]const u8 {
    const params = parseMcpStatusParams(params_value) catch |err| switch (err) {
        error.InvalidMcpStatusParams => return renderJsonRpcError(allocator, id_value, -32602, "mcpServerStatus/list params must be an object"),
        error.InvalidMcpStatusCursor => return renderJsonRpcError(allocator, id_value, -32602, "invalid cursor"),
        error.InvalidMcpStatusLimit => return renderJsonRpcError(allocator, id_value, -32602, "limit must be a non-negative integer or null"),
        error.InvalidMcpStatusDetail => return renderJsonRpcError(allocator, id_value, -32602, "detail must be full, toolsAndAuthOnly, or null"),
    };

    const codex_home = resolveCodexHome(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServerStatus/list failed to resolve CODEX_HOME", err);
    };
    defer allocator.free(codex_home);

    const config_bytes = mcp_cmd.readConfigToml(allocator, codex_home) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServerStatus/list failed to load MCP config", err);
    };
    defer if (config_bytes) |bytes| allocator.free(bytes);
    var servers = mcp_cmd.loadServersFromConfig(allocator, codex_home, config_bytes orelse "") catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServerStatus/list failed to load MCP servers", err);
    };
    defer servers.deinit(allocator);
    std.mem.sort(mcp_cmd.McpServer, servers.items.items, {}, mcpServerNameLessThan);

    const result = renderMcpServerStatusListResponse(allocator, codex_home, config_bytes orelse "", servers, params) catch |err| switch (err) {
        error.McpStatusCursorOutOfRange => return renderJsonRpcError(allocator, id_value, -32602, "cursor exceeds total MCP servers"),
        else => return err,
    };
    defer allocator.free(result);
    return renderJsonRpcResult(allocator, id_value, result);
}

fn handleMcpResourceRead(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = parseMcpResourceReadParams(params_value) catch |err| switch (err) {
        error.InvalidMcpResourceReadParams => return renderJsonRpcError(allocator, id_value, -32602, "mcpServer/resource/read params must be an object"),
        error.InvalidMcpResourceThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string or null"),
        error.InvalidMcpResourceServer => return renderJsonRpcError(allocator, id_value, -32602, "server must be a string"),
        error.InvalidMcpResourceUri => return renderJsonRpcError(allocator, id_value, -32602, "uri must be a string"),
    };

    if (params.thread_id) |thread_id| {
        if (!isUuidString(thread_id)) return renderInvalidThreadId(allocator, id_value, thread_id);
        if (findLoadedThreadIndex(state, thread_id) == null) return renderThreadNotFound(allocator, id_value, thread_id);
    }

    const codex_home = resolveCodexHome(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServer/resource/read failed to resolve CODEX_HOME", err);
    };
    defer allocator.free(codex_home);

    const result = mcp_runtime.readResourceJsonRpc(allocator, codex_home, params.server, params.uri) catch |err| switch (err) {
        error.McpServerNotFound => return renderMcpServerNotFound(allocator, id_value, params.server),
        error.McpServerUnavailable => return renderMcpServerUnavailable(allocator, id_value, params.server),
        else => return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServer/resource/read failed", err),
    };
    defer result.deinit(allocator);
    return renderMcpJsonRpcMethodResult(allocator, id_value, result);
}

fn handleMcpServerToolCall(
    allocator: std.mem.Allocator,
    state: *AppServerState,
    id_value: std.json.Value,
    params_value: ?std.json.Value,
) ![]const u8 {
    const params = parseMcpServerToolCallParams(params_value) catch |err| switch (err) {
        error.InvalidMcpToolCallParams => return renderJsonRpcError(allocator, id_value, -32602, "mcpServer/tool/call params must be an object"),
        error.InvalidMcpToolCallThreadId => return renderJsonRpcError(allocator, id_value, -32602, "threadId must be a string"),
        error.InvalidMcpToolCallServer => return renderJsonRpcError(allocator, id_value, -32602, "server must be a string"),
        error.InvalidMcpToolCallTool => return renderJsonRpcError(allocator, id_value, -32602, "tool must be a string"),
    };

    if (!isUuidString(params.thread_id)) return renderInvalidThreadId(allocator, id_value, params.thread_id);
    const thread_index = findLoadedThreadIndex(state, params.thread_id) orelse return renderThreadNotFound(allocator, id_value, params.thread_id);
    const thread = &state.loaded_threads.items[thread_index];

    const arguments_json = if (params.arguments) |arguments|
        try std.json.Stringify.valueAlloc(allocator, arguments, .{})
    else
        null;
    defer if (arguments_json) |json| allocator.free(json);

    const meta_json = try renderMcpToolCallMeta(allocator, params.thread_id, params.meta);
    defer allocator.free(meta_json);

    const codex_home = resolveCodexHome(allocator) catch |err| {
        return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServer/tool/call failed to resolve CODEX_HOME", err);
    };
    defer allocator.free(codex_home);

    var mcp_elicitation_context: AppServerMcpElicitationContext = undefined;
    const call_options: mcp_runtime.CallToolOptions = if (state.server_request_transport) |transport| blk: {
        mcp_elicitation_context = .{
            .allocator = allocator,
            .state = state,
            .transport = transport,
            .thread_id = params.thread_id,
            .turn_id = null,
            .auto_decline = std.mem.eql(u8, thread.approval_policy, "never"),
        };
        break :blk .{
            .elicitation_callback = .{
                .ctx = &mcp_elicitation_context,
                .on_elicitation_requested = handleAppServerMcpElicitation,
            },
        };
    } else .{};

    const result = mcp_runtime.callToolByNameJsonRpcWithOptions(allocator, codex_home, params.server, params.tool, arguments_json, meta_json, call_options) catch |err| switch (err) {
        error.McpServerNotFound => return renderMcpServerNotFound(allocator, id_value, params.server),
        error.McpServerUnavailable => return renderMcpServerUnavailable(allocator, id_value, params.server),
        else => return renderJsonRpcErrorForFailure(allocator, id_value, "mcpServer/tool/call failed", err),
    };
    defer result.deinit(allocator);
    return renderMcpJsonRpcMethodResult(allocator, id_value, result);
}

fn renderMcpServerNotFound(allocator: std.mem.Allocator, id_value: std.json.Value, server: []const u8) ![]const u8 {
    const message = try std.fmt.allocPrint(allocator, "No MCP server named '{s}' found.", .{server});
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32600, message);
}

fn renderMcpServerUnavailable(allocator: std.mem.Allocator, id_value: std.json.Value, server: []const u8) ![]const u8 {
    const message = try std.fmt.allocPrint(allocator, "MCP server '{s}' is unavailable.", .{server});
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32600, message);
}

fn renderMcpJsonRpcMethodResult(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    result: mcp_runtime.JsonRpcMethodResult,
) ![]const u8 {
    return switch (result) {
        .result_json => |json| renderJsonRpcResult(allocator, id_value, json),
        .rpc_error => |payload| renderJsonRpcErrorWithData(allocator, id_value, payload.code, payload.message, payload.data_json),
    };
}

fn mcpServerNameLessThan(_: void, lhs: mcp_cmd.McpServer, rhs: mcp_cmd.McpServer) bool {
    return std.mem.lessThan(u8, lhs.name, rhs.name);
}

fn parseMcpServerOauthLoginParams(allocator: std.mem.Allocator, params_value: ?std.json.Value) !McpServerOauthLoginParams {
    const params = params_value orelse return error.InvalidMcpOauthLoginParams;
    if (params != .object) return error.InvalidMcpOauthLoginParams;

    const name = params.object.get("name") orelse return error.InvalidMcpOauthLoginName;
    if (name != .string or name.string.len == 0) return error.InvalidMcpOauthLoginName;

    var parsed = McpServerOauthLoginParams{ .name = name.string };
    errdefer parsed.deinit(allocator);
    if (params.object.get("scopes")) |scopes| {
        if (scopes != .null) {
            if (scopes != .array) return error.InvalidMcpOauthLoginScopes;
            parsed.scopes_present = true;
            for (scopes.array.items) |scope| {
                if (scope != .string) return error.InvalidMcpOauthLoginScopes;
                try parsed.scopes.append(allocator, scope.string);
            }
        }
    }
    if (params.object.get("timeoutSecs")) |timeout| {
        if (timeout != .null and timeout != .integer and timeout != .number_string) return error.InvalidMcpOauthLoginTimeout;
        if (timeout == .integer) {
            parsed.timeout_secs = timeout.integer;
        } else if (timeout == .number_string) {
            parsed.timeout_secs = std.fmt.parseInt(i64, timeout.number_string, 10) catch return error.InvalidMcpOauthLoginTimeout;
        }
    }
    return parsed;
}

fn parseMcpStatusParams(params_value: ?std.json.Value) !McpStatusParams {
    const params = params_value orelse return .{};
    if (params == .null) return .{};
    if (params != .object) return error.InvalidMcpStatusParams;

    var parsed = McpStatusParams{};
    if (params.object.get("cursor")) |cursor| {
        if (cursor == .null) {
            parsed.cursor = null;
        } else if (cursor == .string) {
            parsed.cursor = std.fmt.parseUnsigned(usize, cursor.string, 10) catch return error.InvalidMcpStatusCursor;
        } else {
            return error.InvalidMcpStatusCursor;
        }
    }
    if (params.object.get("limit")) |limit| {
        if (limit == .null) {
            parsed.limit = null;
        } else if (limit == .integer and limit.integer >= 0) {
            parsed.limit = @intCast(limit.integer);
        } else {
            return error.InvalidMcpStatusLimit;
        }
    }
    if (params.object.get("detail")) |detail| {
        if (detail == .null) {
            return parsed;
        }
        if (detail != .string) return error.InvalidMcpStatusDetail;
        if (std.mem.eql(u8, detail.string, "full")) {
            parsed.detail = .full;
        } else if (std.mem.eql(u8, detail.string, "toolsAndAuthOnly")) {
            parsed.detail = .tools_and_auth_only;
        } else {
            return error.InvalidMcpStatusDetail;
        }
    }
    return parsed;
}

fn parseMcpResourceReadParams(params_value: ?std.json.Value) !McpResourceReadParams {
    const params = params_value orelse return error.InvalidMcpResourceReadParams;
    if (params != .object) return error.InvalidMcpResourceReadParams;
    const object = params.object;

    const server = object.get("server") orelse return error.InvalidMcpResourceServer;
    if (server != .string) return error.InvalidMcpResourceServer;
    const uri = object.get("uri") orelse return error.InvalidMcpResourceUri;
    if (uri != .string) return error.InvalidMcpResourceUri;

    var parsed = McpResourceReadParams{
        .server = server.string,
        .uri = uri.string,
    };
    if (object.get("threadId")) |thread_id| {
        if (thread_id == .null) {
            parsed.thread_id = null;
        } else if (thread_id == .string) {
            parsed.thread_id = thread_id.string;
        } else {
            return error.InvalidMcpResourceThreadId;
        }
    }
    return parsed;
}

fn parseMcpServerToolCallParams(params_value: ?std.json.Value) !McpServerToolCallParams {
    const params = params_value orelse return error.InvalidMcpToolCallParams;
    if (params != .object) return error.InvalidMcpToolCallParams;
    const object = params.object;

    const thread_id = object.get("threadId") orelse return error.InvalidMcpToolCallThreadId;
    if (thread_id != .string) return error.InvalidMcpToolCallThreadId;
    const server = object.get("server") orelse return error.InvalidMcpToolCallServer;
    if (server != .string) return error.InvalidMcpToolCallServer;
    const tool = object.get("tool") orelse return error.InvalidMcpToolCallTool;
    if (tool != .string) return error.InvalidMcpToolCallTool;

    var parsed = McpServerToolCallParams{
        .thread_id = thread_id.string,
        .server = server.string,
        .tool = tool.string,
    };
    if (object.get("arguments")) |arguments| {
        if (arguments == .null) {
            parsed.arguments = null;
        } else {
            parsed.arguments = arguments;
        }
    }
    if (object.get("_meta")) |meta| {
        parsed.meta = if (meta == .null) null else meta;
    }
    return parsed;
}

fn renderMcpToolCallMeta(allocator: std.mem.Allocator, thread_id: []const u8, meta: ?std.json.Value) ![]const u8 {
    const thread_id_json = try std.json.Stringify.valueAlloc(allocator, thread_id, .{});
    defer allocator.free(thread_id_json);
    const meta_value = meta orelse return std.fmt.allocPrint(allocator, "{{\"threadId\":{s}}}", .{thread_id_json});
    if (meta_value != .object) return std.json.Stringify.valueAlloc(allocator, meta_value, .{});

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.append(allocator, '{');
    var first = true;
    var iter = meta_value.object.iterator();
    while (iter.next()) |entry| {
        if (std.mem.eql(u8, entry.key_ptr.*, "threadId")) continue;
        if (!first) try out.append(allocator, ',');
        first = false;
        const key_json = try std.json.Stringify.valueAlloc(allocator, entry.key_ptr.*, .{});
        defer allocator.free(key_json);
        const value_json = try std.json.Stringify.valueAlloc(allocator, entry.value_ptr.*, .{});
        defer allocator.free(value_json);
        try out.appendSlice(allocator, key_json);
        try out.append(allocator, ':');
        try out.appendSlice(allocator, value_json);
    }
    if (!first) try out.append(allocator, ',');
    try out.appendSlice(allocator, "\"threadId\":");
    try out.appendSlice(allocator, thread_id_json);
    try out.append(allocator, '}');
    return out.toOwnedSlice(allocator);
}

fn renderMcpServerStatusListResponse(
    allocator: std.mem.Allocator,
    codex_home: []const u8,
    config_bytes: []const u8,
    servers: mcp_cmd.McpServers,
    params: McpStatusParams,
) ![]const u8 {
    const total = servers.items.items.len;
    const start = params.cursor orelse 0;
    if (start > total) return error.McpStatusCursorOutOfRange;
    const limit = @max(params.limit orelse total, 1);
    const effective_limit = @min(limit, total);
    const remaining = total - start;
    const end = start + @min(effective_limit, remaining);

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try out.appendSlice(allocator, "{\"data\":[");
    for (servers.items.items[start..end], 0..) |server, index| {
        if (index > 0) try out.appendSlice(allocator, ",");
        try appendMcpServerStatusJson(allocator, &out, codex_home, config_bytes, server, params.detail == .full);
    }
    try out.appendSlice(allocator, "],\"nextCursor\":");
    if (end < total) {
        const next_cursor = try std.fmt.allocPrint(allocator, "{d}", .{end});
        defer allocator.free(next_cursor);
        const next_cursor_json = try std.json.Stringify.valueAlloc(allocator, next_cursor, .{});
        defer allocator.free(next_cursor_json);
        try out.appendSlice(allocator, next_cursor_json);
    } else {
        try out.appendSlice(allocator, "null");
    }
    try out.appendSlice(allocator, "}");
    return out.toOwnedSlice(allocator);
}

fn appendMcpServerStatusJson(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(u8),
    codex_home: []const u8,
    config_bytes: []const u8,
    server: mcp_cmd.McpServer,
    include_resource_inventory: bool,
) !void {
    const name_json = try std.json.Stringify.valueAlloc(allocator, server.name, .{});
    defer allocator.free(name_json);
    const auth_status = try mcpAuthStatus(allocator, codex_home, config_bytes, server);
    defer allocator.free(auth_status);
    const auth_status_json = try std.json.Stringify.valueAlloc(allocator, auth_status, .{});
    defer allocator.free(auth_status_json);
    const inventory = mcp_runtime.serverStatusInventoryJson(allocator, codex_home, server, include_resource_inventory) catch try mcp_runtime.ServerStatusInventoryJson.empty(allocator);
    defer inventory.deinit(allocator);

    try out.appendSlice(allocator, "{\"name\":");
    try out.appendSlice(allocator, name_json);
    try out.appendSlice(allocator, ",\"tools\":");
    try out.appendSlice(allocator, inventory.tools);
    try out.appendSlice(allocator, ",\"resources\":");
    try out.appendSlice(allocator, inventory.resources);
    try out.appendSlice(allocator, ",\"resourceTemplates\":");
    try out.appendSlice(allocator, inventory.resource_templates);
    try out.appendSlice(allocator, ",\"authStatus\":");
    try out.appendSlice(allocator, auth_status_json);
    try out.appendSlice(allocator, "}");
}

fn mcpAuthStatus(allocator: std.mem.Allocator, codex_home: []const u8, config_bytes: []const u8, server: mcp_cmd.McpServer) ![]const u8 {
    if (server.kind == .streamable_http) {
        if (server.bearer_token_env_var) |bearer_token_env_var| {
            if (try envVarIsSet(allocator, bearer_token_env_var)) {
                return allocator.dupe(u8, "bearerToken");
            }
            return allocator.dupe(u8, "notLoggedIn");
        }
        return switch (try mcp_cmd.mcpAuthStatusForServer(allocator, codex_home, config_bytes, server)) {
            .oauth => allocator.dupe(u8, "oAuth"),
            .not_logged_in => allocator.dupe(u8, "notLoggedIn"),
            .bearer_token => allocator.dupe(u8, "bearerToken"),
            .unsupported => allocator.dupe(u8, "unsupported"),
        };
    }
    return allocator.dupe(u8, "unsupported");
}

fn envVarIsSet(allocator: std.mem.Allocator, name: []const u8) !bool {
    const name_z = try allocator.dupeZ(u8, name);
    defer allocator.free(name_z);
    return std.c.getenv(name_z.ptr) != null;
}

fn renderInitializeResult(allocator: std.mem.Allocator) ![]const u8 {
    return allocator.dupe(
        u8,
        "{\"serverInfo\":{\"name\":\"codex-zig-app-server\",\"version\":\"0.0.1\"},\"capabilities\":{}}",
    );
}

fn renderJsonRpcResult(allocator: std.mem.Allocator, id_value: std.json.Value, result_json: []const u8) ![]const u8 {
    const id_json = try std.json.Stringify.valueAlloc(allocator, id_value, .{});
    defer allocator.free(id_json);
    return std.fmt.allocPrint(
        allocator,
        "{{\"jsonrpc\":\"2.0\",\"id\":{s},\"result\":{s}}}",
        .{ id_json, result_json },
    );
}

fn renderJsonRpcError(allocator: std.mem.Allocator, id_value: ?std.json.Value, code: i64, message: []const u8) ![]const u8 {
    return renderJsonRpcErrorWithData(allocator, id_value, code, message, null);
}

fn renderJsonRpcErrorWithData(
    allocator: std.mem.Allocator,
    id_value: ?std.json.Value,
    code: i64,
    message: []const u8,
    data_json: ?[]const u8,
) ![]const u8 {
    const id_json = if (id_value) |value|
        try std.json.Stringify.valueAlloc(allocator, value, .{})
    else
        try allocator.dupe(u8, "null");
    defer allocator.free(id_json);
    const message_json = try std.json.Stringify.valueAlloc(allocator, message, .{});
    defer allocator.free(message_json);
    if (data_json) |data| {
        return std.fmt.allocPrint(
            allocator,
            "{{\"jsonrpc\":\"2.0\",\"id\":{s},\"error\":{{\"code\":{d},\"message\":{s},\"data\":{s}}}}}",
            .{ id_json, code, message_json, data },
        );
    }
    return std.fmt.allocPrint(
        allocator,
        "{{\"jsonrpc\":\"2.0\",\"id\":{s},\"error\":{{\"code\":{d},\"message\":{s}}}}}",
        .{ id_json, code, message_json },
    );
}

fn renderJsonRpcErrorForFailure(
    allocator: std.mem.Allocator,
    id_value: std.json.Value,
    context: []const u8,
    err: anyerror,
) ![]const u8 {
    const message = try std.fmt.allocPrint(allocator, "{s}: {s}", .{ context, @errorName(err) });
    defer allocator.free(message);
    return renderJsonRpcError(allocator, id_value, -32603, message);
}

fn writeStdoutLine(payload: []const u8) !void {
    const io = std.Io.Threaded.global_single_threaded.io();
    app_server_stdout_mutex.lockUncancelable(io);
    defer app_server_stdout_mutex.unlock(io);
    try cli_utils.writeStdout(payload);
    try cli_utils.writeStdout("\n");
}

fn createAppServerConnectionOutput(
    allocator: std.mem.Allocator,
    kind: JsonRpcTransportKind,
    socket_handle: std.posix.fd_t,
) !*AppServerConnectionOutputState {
    const output = try allocator.create(AppServerConnectionOutputState);
    output.* = .{ .kind = kind, .socket_handle = socket_handle };
    return output;
}

fn retainAppServerConnectionOutput(output: *AppServerConnectionOutputState) void {
    _ = output.ref_count.fetchAdd(1, .acq_rel);
}

fn releaseAppServerConnectionOutput(allocator: std.mem.Allocator, output: *AppServerConnectionOutputState) void {
    if (output.ref_count.fetchSub(1, .acq_rel) == 1) allocator.destroy(output);
}

fn closeAppServerConnectionOutput(allocator: std.mem.Allocator, output: *AppServerConnectionOutputState) void {
    const io = std.Io.Threaded.global_single_threaded.io();
    output.mutex.lockUncancelable(io);
    output.closed = true;
    output.mutex.unlock(io);
    releaseAppServerConnectionOutput(allocator, output);
}

fn writeStreamLine(writer: *std.Io.Writer, payload: []const u8) !void {
    try writer.writeAll(payload);
    try writer.writeAll("\n");
    try writer.flush();
}

fn writeStreamLineWithConnection(
    output: ?*AppServerConnectionOutputState,
    writer: *std.Io.Writer,
    payload: []const u8,
) !void {
    if (output) |connection_output| {
        const io = std.Io.Threaded.global_single_threaded.io();
        connection_output.mutex.lockUncancelable(io);
        defer connection_output.mutex.unlock(io);
        if (connection_output.closed) return error.AppServerTransportClosed;
        return writeStreamLine(writer, payload);
    }
    return writeStreamLine(writer, payload);
}

fn writeWebSocketFrameWithConnection(
    output: ?*AppServerConnectionOutputState,
    writer: *std.Io.Writer,
    opcode: u8,
    payload: []const u8,
) !void {
    if (output) |connection_output| {
        const io = std.Io.Threaded.global_single_threaded.io();
        connection_output.mutex.lockUncancelable(io);
        defer connection_output.mutex.unlock(io);
        if (connection_output.closed) return error.AppServerTransportClosed;
        return writeWebSocketFrame(writer, opcode, payload);
    }
    return writeWebSocketFrame(writer, opcode, payload);
}

fn writeWebSocketTextFrameWithConnection(
    output: ?*AppServerConnectionOutputState,
    writer: *std.Io.Writer,
    payload: []const u8,
) !void {
    try writeWebSocketFrameWithConnection(output, writer, 0x1, payload);
}

fn writeAppServerBackgroundSocketNotification(
    output: *AppServerConnectionOutputState,
    fd: std.posix.fd_t,
    payload: []const u8,
) !void {
    const io = std.Io.Threaded.global_single_threaded.io();
    output.mutex.lockUncancelable(io);
    defer output.mutex.unlock(io);
    if (output.closed) return error.AppServerTransportClosed;

    switch (output.kind) {
        .stream_line => {
            try writeFdAll(fd, payload);
            try writeFdAll(fd, "\n");
        },
        .websocket => try writeWebSocketFrameFd(fd, 0x1, payload),
        .stdout_line => return error.AppServerTransportUnsupported,
    }
}

fn writeWebSocketFrameFd(fd: std.posix.fd_t, opcode: u8, payload: []const u8) !void {
    var header: [10]u8 = undefined;
    var header_len: usize = 0;
    header[header_len] = 0x80 | (opcode & 0x0f);
    header_len += 1;
    if (payload.len <= 125) {
        header[header_len] = @intCast(payload.len);
        header_len += 1;
    } else if (payload.len <= std.math.maxInt(u16)) {
        header[header_len] = 126;
        header_len += 1;
        std.mem.writeInt(u16, header[header_len..][0..2], @intCast(payload.len), .big);
        header_len += 2;
    } else {
        header[header_len] = 127;
        header_len += 1;
        std.mem.writeInt(u64, header[header_len..][0..8], @intCast(payload.len), .big);
        header_len += 8;
    }
    try writeFdAll(fd, header[0..header_len]);
    try writeFdAll(fd, payload);
}

fn writeFdAll(fd: std.posix.fd_t, bytes: []const u8) !void {
    var offset: usize = 0;
    while (offset < bytes.len) {
        const rc = std.c.write(fd, bytes[offset..].ptr, bytes.len - offset);
        switch (std.c.errno(rc)) {
            .SUCCESS => {
                if (rc <= 0) return error.AppServerTransportWriteFailed;
                offset += @intCast(rc);
            },
            .INTR => continue,
            else => return error.AppServerTransportWriteFailed,
        }
    }
}

fn duplicateFd(fd: std.posix.fd_t) !std.posix.fd_t {
    while (true) {
        const duplicated = std.c.dup(fd);
        switch (std.c.errno(duplicated)) {
            .SUCCESS => return @intCast(duplicated),
            .INTR => continue,
            .MFILE => return error.ProcessFdQuotaExceeded,
            .NFILE => return error.SystemFdQuotaExceeded,
            else => return error.AppServerTransportDuplicateFailed,
        }
    }
}

fn closeFd(fd: std.posix.fd_t) void {
    _ = std.c.close(fd);
}

fn writePreResponseNotificationsStdout(allocator: std.mem.Allocator, state: *AppServerState) !void {
    var notifications = state.pre_response_notifications;
    state.pre_response_notifications = .empty;
    defer freePendingNotifications(allocator, &notifications);
    for (notifications.items) |payload| {
        try writeStdoutLine(payload);
    }
}

fn writePreResponseNotificationsStream(allocator: std.mem.Allocator, state: *AppServerState, writer: *std.Io.Writer) !void {
    var notifications = state.pre_response_notifications;
    state.pre_response_notifications = .empty;
    defer freePendingNotifications(allocator, &notifications);
    for (notifications.items) |payload| {
        try writeStreamLineWithConnection(state.connection_output, writer, payload);
    }
}

fn writePreResponseNotificationsWebSocket(allocator: std.mem.Allocator, state: *AppServerState, writer: *std.Io.Writer) !void {
    var notifications = state.pre_response_notifications;
    state.pre_response_notifications = .empty;
    defer freePendingNotifications(allocator, &notifications);
    for (notifications.items) |payload| {
        try writeWebSocketTextFrameWithConnection(state.connection_output, writer, payload);
    }
}

fn writePendingNotificationsStdout(allocator: std.mem.Allocator, state: *AppServerState) !void {
    var notifications = state.pending_notifications;
    state.pending_notifications = .empty;
    defer freePendingNotifications(allocator, &notifications);
    for (notifications.items) |payload| {
        try writeStdoutLine(payload);
    }
}

fn writePendingNotificationsStream(allocator: std.mem.Allocator, state: *AppServerState, writer: *std.Io.Writer) !void {
    var notifications = state.pending_notifications;
    state.pending_notifications = .empty;
    defer freePendingNotifications(allocator, &notifications);
    for (notifications.items) |payload| {
        try writeStreamLineWithConnection(state.connection_output, writer, payload);
    }
}

fn writePendingNotificationsWebSocket(allocator: std.mem.Allocator, state: *AppServerState, writer: *std.Io.Writer) !void {
    var notifications = state.pending_notifications;
    state.pending_notifications = .empty;
    defer freePendingNotifications(allocator, &notifications);
    for (notifications.items) |payload| {
        try writeWebSocketTextFrameWithConnection(state.connection_output, writer, payload);
    }
}

fn flushAppServerIdleWorkStdout(allocator: std.mem.Allocator, state: *AppServerState) !void {
    try queueExternalFsWatchNotifications(allocator, state);
    try reapExpiredThreadUnloads(allocator, state, true);
    try writePendingNotificationsStdout(allocator, state);
    cleanupFinishedCommandExecSessions(allocator, state, false);
}

fn flushAppServerIdleWorkStream(allocator: std.mem.Allocator, state: *AppServerState, writer: *std.Io.Writer) !void {
    try queueExternalFsWatchNotifications(allocator, state);
    try reapExpiredThreadUnloads(allocator, state, true);
    try writePendingNotificationsStream(allocator, state, writer);
    cleanupFinishedCommandExecSessions(allocator, state, false);
}

fn flushAppServerIdleWorkWebSocket(allocator: std.mem.Allocator, state: *AppServerState, writer: *std.Io.Writer) !void {
    try queueExternalFsWatchNotifications(allocator, state);
    try reapExpiredThreadUnloads(allocator, state, true);
    try writePendingNotificationsWebSocket(allocator, state, writer);
    cleanupFinishedCommandExecSessions(allocator, state, false);
}

fn freePendingNotifications(allocator: std.mem.Allocator, notifications: *std.ArrayList([]const u8)) void {
    for (notifications.items) |payload| allocator.free(payload);
    notifications.deinit(allocator);
}

fn defaultUnixSocketPath(allocator: std.mem.Allocator) ![]const u8 {
    const codex_home = try resolveCodexHome(allocator);
    defer allocator.free(codex_home);
    return std.fs.path.join(allocator, &.{ codex_home, DEFAULT_SOCKET_DIR_NAME, DEFAULT_SOCKET_FILE_NAME });
}

fn resolveCodexHome(allocator: std.mem.Allocator) ![]const u8 {
    if (try env.getOwned(allocator, "CODEX_HOME")) |value| return value;

    const home = (try env.getOwned(allocator, "HOME")) orelse return error.MissingHome;
    defer allocator.free(home);
    return std.fs.path.join(allocator, &.{ home, ".codex" });
}

fn ensureParentDir(io: std.Io, path: []const u8) !void {
    const parent = std.fs.path.dirname(path) orelse return;
    if (parent.len == 0) return;
    if (try dirExists(io, parent)) return;
    try std.Io.Dir.cwd().createDirPath(io, parent);
}

fn dirExists(io: std.Io, path: []const u8) !bool {
    var dir = if (std.fs.path.isAbsolute(path))
        std.Io.Dir.openDirAbsolute(io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        }
    else
        std.Io.Dir.cwd().openDir(io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
    defer dir.close(io);
    return true;
}

fn deleteSocketFileIfSocket(allocator: std.mem.Allocator, io: std.Io, path: []const u8) !void {
    const stat = statPathNoFollow(allocator, path) catch |err| switch (err) {
        error.NotDir => return error.AppServerUnixSocketPathExists,
        else => return err,
    } orelse return;
    if (!std.c.S.ISSOCK(@intCast(stat.mode))) return error.AppServerUnixSocketPathExists;
    try std.Io.Dir.cwd().deleteFile(io, path);
}

fn statPathFollow(allocator: std.mem.Allocator, path: []const u8) !?std.c.Stat {
    return statPathWithFlags(allocator, path, 0);
}

fn statPathNoFollow(allocator: std.mem.Allocator, path: []const u8) !?std.c.Stat {
    return statPathWithFlags(allocator, path, std.c.AT.SYMLINK_NOFOLLOW);
}

fn statPathWithFlags(allocator: std.mem.Allocator, path: []const u8, flags: u32) !?std.c.Stat {
    const path_z = try allocator.dupeZ(u8, path);
    defer allocator.free(path_z);

    var stat = std.mem.zeroes(std.c.Stat);
    while (true) {
        switch (std.c.errno(std.c.fstatat(std.c.AT.FDCWD, path_z.ptr, &stat, flags))) {
            .SUCCESS => break,
            .INTR => continue,
            .NOENT => return null,
            .NOTDIR => return error.NotDir,
            .ACCES => return error.AccessDenied,
            .PERM => return error.PermissionDenied,
            .LOOP => return error.SymLinkLoop,
            .NAMETOOLONG => return error.NameTooLong,
            else => |err| return std.posix.unexpectedErrno(err),
        }
    }
    return stat;
}

fn isHelpFlag(arg: []const u8) bool {
    return std.mem.eql(u8, arg, "--help") or std.mem.eql(u8, arg, "-h");
}

pub fn remoteRejectionLabel(args: []const []const u8) []const u8 {
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (isHelpFlag(arg)) return "app-server";
        if (optionConsumesValue(arg)) {
            if (index + 1 >= args.len) return "app-server";
            index += 1;
            continue;
        }
        if (optionHasInlineValue(arg) or std.mem.eql(u8, arg, "--analytics-default-enabled")) {
            continue;
        }
        if (std.mem.startsWith(u8, arg, "-")) return "app-server";
        if (std.mem.eql(u8, arg, "daemon")) return daemonSubcommandLabel(args[index + 1 ..]);
        if (subcommandLabel(arg)) |label| return label;
        return "app-server";
    }
    return "app-server";
}

fn optionConsumesValue(arg: []const u8) bool {
    return std.mem.eql(u8, arg, "--listen") or
        std.mem.eql(u8, arg, "--session-source") or
        std.mem.eql(u8, arg, "-c") or
        std.mem.eql(u8, arg, "--config") or
        std.mem.eql(u8, arg, "--enable") or
        std.mem.eql(u8, arg, "--disable") or
        std.mem.eql(u8, arg, "--ws-auth") or
        std.mem.eql(u8, arg, "--ws-token-file") or
        std.mem.eql(u8, arg, "--ws-token-sha256") or
        std.mem.eql(u8, arg, "--ws-shared-secret-file") or
        std.mem.eql(u8, arg, "--ws-issuer") or
        std.mem.eql(u8, arg, "--ws-audience") or
        std.mem.eql(u8, arg, "--ws-max-clock-skew-seconds");
}

fn optionHasInlineValue(arg: []const u8) bool {
    return std.mem.startsWith(u8, arg, "--listen=") or
        std.mem.startsWith(u8, arg, "--session-source=") or
        std.mem.startsWith(u8, arg, "--config=") or
        std.mem.startsWith(u8, arg, "--enable=") or
        std.mem.startsWith(u8, arg, "--disable=") or
        std.mem.startsWith(u8, arg, "--ws-auth=") or
        std.mem.startsWith(u8, arg, "--ws-token-file=") or
        std.mem.startsWith(u8, arg, "--ws-token-sha256=") or
        std.mem.startsWith(u8, arg, "--ws-shared-secret-file=") or
        std.mem.startsWith(u8, arg, "--ws-issuer=") or
        std.mem.startsWith(u8, arg, "--ws-audience=") or
        std.mem.startsWith(u8, arg, "--ws-max-clock-skew-seconds=");
}

fn subcommandLabel(arg: []const u8) ?[]const u8 {
    if (std.mem.eql(u8, arg, "proxy")) return "app-server proxy";
    if (std.mem.eql(u8, arg, "daemon")) return "app-server daemon";
    if (std.mem.eql(u8, arg, "generate-ts")) return "app-server generate-ts";
    if (std.mem.eql(u8, arg, "generate-json-schema")) return "app-server generate-json-schema";
    if (std.mem.eql(u8, arg, "generate-internal-json-schema")) return "app-server generate-internal-json-schema";
    return null;
}

fn daemonSubcommandLabel(args: []const []const u8) []const u8 {
    var index: usize = 0;
    while (index < args.len) : (index += 1) {
        const arg = args[index];
        if (isHelpFlag(arg)) return "app-server daemon";
        if (std.mem.eql(u8, arg, "-c") or
            std.mem.eql(u8, arg, "--config") or
            std.mem.eql(u8, arg, "--enable") or
            std.mem.eql(u8, arg, "--disable"))
        {
            if (index + 1 >= args.len) return "app-server daemon";
            index += 1;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--config=") or
            std.mem.startsWith(u8, arg, "--enable=") or
            std.mem.startsWith(u8, arg, "--disable=") or
            std.mem.eql(u8, arg, "--remote-control"))
        {
            continue;
        }
        if (std.mem.startsWith(u8, arg, "-")) return "app-server daemon";
        if (daemonCommandFromName(arg)) |cmd| return daemonCommandLabel(cmd);
        return "app-server daemon";
    }
    return "app-server daemon";
}

fn daemonCommandLabel(command: DaemonCommand) []const u8 {
    return switch (command) {
        .bootstrap => "app-server daemon bootstrap",
        .start => "app-server daemon start",
        .restart => "app-server daemon restart",
        .enable_remote_control => "app-server daemon enable-remote-control",
        .disable_remote_control => "app-server daemon disable-remote-control",
        .stop => "app-server daemon stop",
        .version => "app-server daemon version",
        .pid_update_loop => "app-server daemon pid-update-loop",
    };
}

pub fn printHelp() void {
    std.debug.print(
        \\Usage:
        \\  codex-zig app-server [--strict-config] [--listen URL] [--session-source SOURCE]
        \\  codex-zig app-server daemon [OPTIONS] <COMMAND>
        \\  codex-zig app-server proxy [--sock SOCKET_PATH]
        \\  codex-zig app-server generate-ts --out DIR [--experimental]
        \\  codex-zig app-server generate-json-schema --out DIR [--experimental]
        \\  codex-zig app-server help [COMMAND]...
        \\
        \\Runs the app-server JSON-RPC transport.
        \\
        \\Subcommands:
        \\  daemon                 Manage the local app-server daemon
        \\  proxy                  Proxy stdio to the app-server Unix socket
        \\  generate-ts            Generate TypeScript bindings for the app-server protocol
        \\  generate-json-schema   Generate JSON Schema for the app-server protocol
        \\  help                   Print this message or the help of the given subcommand(s)
        \\
        \\Options:
        \\  -c, --config <key=value>
        \\                          Override a supported config value
        \\      --enable <FEATURE>  Enable a feature for this invocation
        \\      --disable <FEATURE> Disable a feature for this invocation
        \\  --strict-config        Error on unknown config fields.
        \\  --listen URL           Transport URL. Defaults to stdio://.
        \\  --session-source SOURCE
        \\                          Session source metadata. Defaults to vscode.
        \\  --analytics-default-enabled
        \\                          Accept Rust-compatible app-server analytics default flag.
        \\  --ws-auth MODE         Websocket auth mode: capability-token or signed-bearer-token.
        \\  --ws-token-file PATH   Capability-token file. Requires --ws-auth capability-token.
        \\  --ws-token-sha256 HEX  Capability-token SHA-256. Requires --ws-auth capability-token.
        \\  --ws-shared-secret-file PATH
        \\                          Signed JWT bearer secret file. Requires --ws-auth signed-bearer-token.
        \\  --ws-issuer ISSUER     Expected signed JWT issuer.
        \\  --ws-audience AUDIENCE Expected signed JWT audience.
        \\  --ws-max-clock-skew-seconds SECONDS
        \\                          Signed JWT max clock skew. Defaults to 30.
        \\
        \\Supported URL forms:
        \\  stdio://               Read and write newline-delimited JSON-RPC on stdio
        \\  off                    Disable the app-server transport
        \\  unix://                Listen on CODEX_HOME/app-server-control/app-server-control.sock
        \\  unix://PATH            Listen on a Unix socket transport path
        \\  ws://IP:PORT           Parse a websocket transport address
        \\
        \\The Zig port currently implements stdio://, unix://, unix://PATH, and off.
        \\
    , .{});
}

fn printAppServerHelpForArgs(args: []const []const u8) !void {
    if (args.len == 0) {
        printHelp();
        return;
    }

    const target = args[0];
    if (std.mem.eql(u8, target, "help")) {
        if (args.len > 1) return failAppServerHelpSubcommand(args[1], "Usage: codex-zig app-server help [COMMAND]...", false);
        printAppServerHelpCommandHelp();
        return;
    }
    if (std.mem.eql(u8, target, "proxy")) {
        if (args.len > 1) return failAppServerHelpSubcommand(args[1], "Usage: codex-zig app-server proxy [--sock SOCKET_PATH]", true);
        printProxyHelp();
        return;
    }
    if (std.mem.eql(u8, target, "daemon")) {
        try printDaemonHelpForArgs(args[1..]);
        return;
    }
    if (std.mem.eql(u8, target, "generate-ts")) {
        if (args.len > 1) return failAppServerHelpSubcommand(args[1], "Usage: codex-zig app-server generate-ts [OPTIONS] --out <DIR>", true);
        printGenerateTsHelp();
        return;
    }
    if (std.mem.eql(u8, target, "generate-json-schema")) {
        if (args.len > 1) return failAppServerHelpSubcommand(args[1], "Usage: codex-zig app-server generate-json-schema [OPTIONS] --out <DIR>", true);
        printGenerateJsonSchemaHelp();
        return;
    }
    if (std.mem.eql(u8, target, "generate-internal-json-schema")) {
        if (args.len > 1) return failAppServerHelpSubcommand(args[1], "Usage: codex-zig app-server generate-internal-json-schema --out <DIR>", true);
        printGenerateInternalJsonSchemaHelp();
        return;
    }
    return failAppServerHelpSubcommand(target, "Usage: codex-zig app-server [OPTIONS] [COMMAND]", true);
}

fn printAppServerHelpCommandHelp() void {
    std.debug.print(
        \\Print this message or the help of the given subcommand(s)
        \\
        \\Usage: codex-zig app-server help [COMMAND]...
        \\
        \\Arguments:
        \\  [COMMAND]...  Print help for the subcommand(s)
        \\
    , .{});
}

fn printDaemonHelpForArgs(args: []const []const u8) !void {
    if (args.len == 0) {
        printDaemonHelp();
        return;
    }

    const target = args[0];
    if (std.mem.eql(u8, target, "help")) {
        if (args.len > 1) return failAppServerHelpSubcommand(args[1], "Usage: codex-zig app-server daemon help [COMMAND]...", false);
        printDaemonHelpCommandHelp();
        return;
    }
    if (daemonCommandFromName(target)) |command| {
        if (args.len > 1) return failAppServerDaemonCommandHelpSubcommand(command, args[1]);
        printDaemonCommandHelp(command);
        return;
    }
    return failAppServerHelpSubcommand(target, "Usage: codex-zig app-server daemon [OPTIONS] <COMMAND>", true);
}

fn failAppServerHelpSubcommand(subcommand: []const u8, usage: []const u8, include_for_more: bool) error{HelpSubcommandInvalid} {
    if (!builtin.is_test) cli_utils.printUnrecognizedSubcommand(subcommand, usage, include_for_more);
    return error.HelpSubcommandInvalid;
}

fn failAppServerDaemonCommandHelpSubcommand(command: DaemonCommand, subcommand: []const u8) error{HelpSubcommandInvalid} {
    var usage_buf: [160]u8 = undefined;
    const usage = std.fmt.bufPrint(&usage_buf, "Usage: {s}", .{daemonCommandUsage(command)}) catch unreachable;
    return failAppServerHelpSubcommand(subcommand, usage, true);
}

