test "app-server remote rejection labels known subcommands" {
    try std.testing.expectEqualStrings("app-server", remoteRejectionLabel(&.{}));
    try std.testing.expectEqualStrings("app-server proxy", remoteRejectionLabel(&.{"proxy"}));
    try std.testing.expectEqualStrings("app-server daemon", remoteRejectionLabel(&.{"daemon"}));
    try std.testing.expectEqualStrings("app-server daemon version", remoteRejectionLabel(&.{ "daemon", "version" }));
    try std.testing.expectEqualStrings("app-server daemon bootstrap", remoteRejectionLabel(&.{ "daemon", "bootstrap", "--remote-control" }));
    try std.testing.expectEqualStrings("app-server daemon stop", remoteRejectionLabel(&.{ "daemon", "--config", "model=\"x\"", "stop" }));
    try std.testing.expectEqualStrings(
        "app-server proxy",
        remoteRejectionLabel(&.{ "--listen", "off", "proxy" }),
    );
    try std.testing.expectEqualStrings(
        "app-server generate-internal-json-schema",
        remoteRejectionLabel(&.{ "--listen=off", "generate-internal-json-schema" }),
    );
    try std.testing.expectEqualStrings(
        "app-server generate-ts",
        remoteRejectionLabel(&.{ "--ws-auth", "capability-token", "generate-ts" }),
    );
    try std.testing.expectEqualStrings("app-server", remoteRejectionLabel(&.{"--help"}));
}

test "config/read user origin keys include active profile scalars" {
    const allocator = std.testing.allocator;
    const keys = try collectConfigReadUserOriginKeys(allocator,
        \\model = "base-model"
        \\profile = "work"
        \\approval_policy = "on-request"
        \\approvals_reviewer = "user"
        \\base_instructions = "base instructions"
        \\
        \\[features]
        \\apps = false
        \\
        \\[profiles.work]
        \\model = "profile-model"
        \\sandbox_mode = "danger-full-access"
        \\approvals_reviewer = "auto_review"
        \\profile = "ignored-profile-key"
        \\base_instructions = "profile base instructions"
        \\
        \\[profiles.work.features]
        \\goals = true
        \\
        \\[profiles.other]
        \\service_tier = "flex"
        \\
    , "work");
    defer {
        for (keys) |key| allocator.free(key);
        allocator.free(keys);
    }

    try std.testing.expectEqual(@as(usize, 6), keys.len);
    try std.testing.expectEqualStrings("model", keys[0]);
    try std.testing.expectEqualStrings("profile", keys[1]);
    try std.testing.expectEqualStrings("approval_policy", keys[2]);
    try std.testing.expectEqualStrings("approvals_reviewer", keys[3]);
    try std.testing.expectEqualStrings("instructions", keys[4]);
    try std.testing.expectEqualStrings("sandbox_mode", keys[5]);
}

test "feature requirements normalize aliases for effective feature values" {
    const allocator = std.testing.allocator;
    var requirements = (try parseFeatureRequirements(allocator,
        \\[features] # managed feature pins
        \\connectors = false # legacy apps alias
        \\"auto_review" = false # guardian approval alias
        \\"unknown#feature" = true # preserved raw key, ignored for effective features
        \\
    )).?;
    defer requirements.deinit(allocator);

    try std.testing.expectEqual(false, featureRequirementValue(requirements, "apps").?);
    try std.testing.expectEqual(false, featureRequirementValue(requirements, "guardian_approval").?);
    try std.testing.expect(featureRequirementValue(requirements, "unknown#feature") == null);
}

test "config write feature requirements reject conflicting user and profile values" {
    const allocator = std.testing.allocator;
    var requirements = (try parseFeatureRequirements(allocator,
        \\[features]
        \\personality = true
        \\connectors = false
        \\
    )).?;
    defer requirements.deinit(allocator);

    const user_conflict = try configWriteFeatureRequirementConflictMessage(allocator,
        \\[features]
        \\personality = false
        \\apps = false
        \\
    , requirements);
    try std.testing.expect(user_conflict != null);
    defer allocator.free(user_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, user_conflict.?, "features.personality=false") != null);

    const profile_conflict = try configWriteFeatureRequirementConflictMessage(allocator,
        \\[profiles.enterprise.features]
        \\personality = false
        \\
    , requirements);
    try std.testing.expect(profile_conflict != null);
    defer allocator.free(profile_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, profile_conflict.?, "profiles.enterprise.features.personality=false") != null);

    const dotted_conflict = try configWriteFeatureRequirementConflictMessage(allocator,
        \\profiles.enterprise.features.personality = false
        \\
    , requirements);
    try std.testing.expect(dotted_conflict != null);
    defer allocator.free(dotted_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, dotted_conflict.?, "profiles.enterprise.features.personality=false") != null);

    const quoted_equals_profile_conflict = try configWriteFeatureRequirementConflictMessage(allocator,
        \\profiles."prod=eu".features.personality = false
        \\
    , requirements);
    try std.testing.expect(quoted_equals_profile_conflict != null);
    defer allocator.free(quoted_equals_profile_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, quoted_equals_profile_conflict.?, "profiles.prod=eu.features.personality=false") != null);

    const inline_conflict = try configWriteFeatureRequirementConflictMessage(allocator,
        \\features = { "personality" = false }
        \\
    , requirements);
    try std.testing.expect(inline_conflict != null);
    defer allocator.free(inline_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, inline_conflict.?, "features.personality=false") != null);

    const profile_inline_conflict = try configWriteFeatureRequirementConflictMessage(allocator,
        \\[profiles.enterprise]
        \\features = { "personality" = false }
        \\
    , requirements);
    try std.testing.expect(profile_inline_conflict != null);
    defer allocator.free(profile_inline_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, profile_inline_conflict.?, "profiles.enterprise.features.personality=false") != null);

    const nested_inline_conflict = try configWriteFeatureRequirementConflictMessage(allocator,
        \\profiles = { enterprise = { features = { "personality" = false } } }
        \\
    , requirements);
    try std.testing.expect(nested_inline_conflict != null);
    defer allocator.free(nested_inline_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, nested_inline_conflict.?, "profiles.enterprise.features.personality=false") != null);

    const unrelated_inline = try configWriteFeatureRequirementConflictMessage(allocator,
        \\bar = { baz = ']' }
        \\
    , requirements);
    try std.testing.expect(unrelated_inline == null);

    const unrelated_profile_inline = try configWriteFeatureRequirementConflictMessage(allocator,
        \\[profiles.enterprise]
        \\tools = { default = { note = '}' } }
        \\
    , requirements);
    try std.testing.expect(unrelated_profile_inline == null);

    const unrelated_nested_profile_inline = try configWriteFeatureRequirementConflictMessage(allocator,
        \\profiles = { enterprise = { tools = { default = { note = '}' } } } }
        \\
    , requirements);
    try std.testing.expect(unrelated_nested_profile_inline == null);

    const array_table_local_features = try configWriteFeatureRequirementConflictMessage(allocator,
        \\[[skills.config]]
        \\name = "local"
        \\features = { "personality" = false }
        \\
    , requirements);
    try std.testing.expect(array_table_local_features == null);

    const allowed = try configWriteFeatureRequirementConflictMessage(allocator,
        \\[features]
        \\personality = true
        \\apps = false
        \\
        \\[profiles.enterprise.features]
        \\personality = true
        \\
    , requirements);
    try std.testing.expect(allowed == null);

    const multiline_allowed = try configWriteFeatureRequirementConflictMessage(allocator,
        \\instructions = """
        \\[features]
        \\personality = false
        \\"""
        \\
        \\[features]
        \\personality = true
        \\
    , requirements);
    try std.testing.expect(multiline_allowed == null);
}

test "config requirements filter external sandbox mode from API list" {
    const allocator = std.testing.allocator;
    var mixed = (try parseAllowedRequirementList(allocator,
        \\allowed_sandbox_modes = ["external-sandbox", "workspace-write", "read-only"]
        \\
    , "allowed_sandbox_modes", .sandbox_mode)).?;
    defer mixed.deinit(allocator);

    try std.testing.expectEqual(@as(usize, 2), mixed.items.len);
    try std.testing.expectEqualStrings("workspace-write", mixed.items[0]);
    try std.testing.expectEqualStrings("read-only", mixed.items[1]);

    var external_only = (try parseAllowedRequirementList(allocator,
        \\allowed_sandbox_modes = ["external-sandbox"]
        \\
    , "allowed_sandbox_modes", .sandbox_mode)).?;
    defer external_only.deinit(allocator);

