}

test "config/read scalar requirements fall back to first allowed value" {
    const allocator = std.testing.allocator;
    var requirements = ConfigRequirementsReadRequirements{
        .allowed_approval_policies = try stringListFromLabels(allocator, &.{"on-request"}),
        .allowed_approvals_reviewers = try stringListFromLabels(allocator, &.{"guardian_subagent"}),
        .allowed_sandbox_modes = try stringListFromLabels(allocator, &.{"read-only"}),
        .allowed_web_search_modes = try stringListFromLabels(allocator, &.{ "live", "cached", "disabled" }),
    };
    defer requirements.deinit(allocator);

    try std.testing.expectEqual(config.ApprovalPolicy.on_request, try configReadRequirementApprovalPolicy(.never, requirements));
    try std.testing.expectEqual(config.ApprovalsReviewer.auto_review, try configReadRequirementApprovalsReviewer(.user, requirements));
    try std.testing.expectEqual(config.SandboxMode.read_only, try configReadRequirementSandboxMode(.danger_full_access, requirements));
    try std.testing.expectEqual(config.WebSearchMode.live, (try configReadRequirementWebSearchMode(.live, requirements)).?);
    try std.testing.expectEqual(config.WebSearchMode.cached, (try configReadRequirementWebSearchMode(null, requirements)).?);

    var unsupported_approval = ConfigRequirementsReadRequirements{
        .allowed_approval_policies = try stringListFromLabels(allocator, &.{}),
    };
    defer unsupported_approval.deinit(allocator);

    try std.testing.expectError(
        error.ConfigReadRequirementsNoAllowedApprovalPolicies,
        configReadRequirementApprovalPolicy(.never, unsupported_approval),
    );

    var unsupported_reviewer = ConfigRequirementsReadRequirements{
        .allowed_approvals_reviewers = try stringListFromLabels(allocator, &.{}),
    };
    defer unsupported_reviewer.deinit(allocator);

    try std.testing.expectError(
        error.ConfigReadRequirementsNoAllowedApprovalsReviewers,
        configReadRequirementApprovalsReviewer(.user, unsupported_reviewer),
    );

    var unsupported_sandbox = ConfigRequirementsReadRequirements{
        .allowed_sandbox_modes = try stringListFromLabels(allocator, &.{}),
    };
    defer unsupported_sandbox.deinit(allocator);

    try std.testing.expectError(
        error.ConfigReadRequirementsNoSupportedSandboxModes,
        configReadRequirementSandboxMode(.danger_full_access, unsupported_sandbox),
    );
}

test "config/read app requirements disable and materialize apps" {
    const allocator = std.testing.allocator;
    var requirements = (try plugin_list.parseAppRequirements(allocator,
        \\[apps.connector_drive]
        \\enabled = false
        \\
        \\[apps.connector_calendar]
        \\enabled = false
        \\
        \\[apps.connector_docs]
        \\enabled = true
        \\
    )).?;
    defer requirements.deinit(allocator);

    var items = std.ArrayList(ConfigReadApp).empty;
    defer {
        for (items.items) |*app| app.deinit(allocator);
        items.deinit(allocator);
    }

    const drive = try ensureConfigReadApp(allocator, &items, "connector_drive");
    drive.enabled = true;
    drive.has_enabled = true;

    const slack = try ensureConfigReadApp(allocator, &items, "connector_slack");
    slack.enabled = false;
    slack.has_enabled = true;

    try applyConfigReadAppRequirements(allocator, &items, requirements);

    const drive_index = findConfigReadAppIndex(items.items, "connector_drive").?;
    try std.testing.expectEqual(false, items.items[drive_index].enabled);
    try std.testing.expect(items.items[drive_index].has_enabled);

    const slack_index = findConfigReadAppIndex(items.items, "connector_slack").?;
    try std.testing.expectEqual(false, items.items[slack_index].enabled);
    try std.testing.expect(items.items[slack_index].has_enabled);

    const calendar_index = findConfigReadAppIndex(items.items, "connector_calendar").?;
    try std.testing.expectEqual(false, items.items[calendar_index].enabled);
    try std.testing.expect(items.items[calendar_index].has_enabled);
    try std.testing.expect(findConfigReadAppIndex(items.items, "connector_docs") == null);
}

test "runtime scalar requirements constrain config and loaded thread state" {
    const allocator = std.testing.allocator;
    var requirements = ConfigRequirementsReadRequirements{
        .allowed_approval_policies = try stringListFromLabels(allocator, &.{"on-request"}),
        .allowed_approvals_reviewers = try stringListFromLabels(allocator, &.{"guardian_subagent"}),
        .allowed_sandbox_modes = try stringListFromLabels(allocator, &.{"read-only"}),
        .allowed_web_search_modes = try stringListFromLabels(allocator, &.{ "cached", "disabled" }),
    };
    defer requirements.deinit(allocator);

    var cfg = try testAppServerConfig(allocator, "gpt-5.5");
    defer cfg.deinit(allocator);
    cfg.approval_policy = .never;
    cfg.approvals_reviewer = .user;
    cfg.sandbox_mode = .danger_full_access;
    cfg.web_search_mode = .live;

    try applyRuntimeScalarRequirementsToConfigWithRequirements(&cfg, requirements);
    try std.testing.expectEqual(config.ApprovalPolicy.on_request, cfg.approval_policy);
    try std.testing.expectEqual(config.ApprovalsReviewer.auto_review, cfg.approvals_reviewer);
    try std.testing.expectEqual(config.SandboxMode.read_only, cfg.sandbox_mode);
    try std.testing.expectEqual(config.WebSearchMode.cached, cfg.web_search_mode.?);

    var thread_cfg = try testAppServerConfig(allocator, "gpt-5.5");
    defer thread_cfg.deinit(allocator);
    thread_cfg.approval_policy = .never;
    thread_cfg.approvals_reviewer = .user;
    thread_cfg.sandbox_mode = .danger_full_access;
    thread_cfg.web_search_mode = .live;

    var params = try std.json.parseFromSlice(std.json.Value, allocator, "{\"ephemeral\":true}", .{});
    defer params.deinit();
    var thread = try createLoadedThreadFromStartParams(allocator, thread_cfg, params.value.object);
    defer thread.deinit(allocator);
    thread.runtime_overrides.sandbox_mode = true;

    try applyRuntimeScalarRequirementsToLoadedThreadWithRequirements(allocator, &thread, requirements);
    try std.testing.expectEqualStrings("on-request", thread.approval_policy);
    try std.testing.expectEqualStrings("guardian_subagent", thread.approvals_reviewer);
    try std.testing.expectEqualStrings("read-only", thread.sandbox_mode);
    try std.testing.expect(!thread.sandbox_network_enabled);
    try std.testing.expect(thread.runtime_overrides.sandbox_mode);
    try std.testing.expectEqual(config.WebSearchMode.cached, thread.web_search_mode.?);
}

