test "thread request config supports model provider and base URL overrides" {
    const allocator = std.testing.allocator;
    const io = std.Io.Threaded.global_single_threaded.io();
    var dir = std.testing.tmpDir(.{});
    defer dir.cleanup();
    try dir.dir.writeFile(io, .{
        .sub_path = "config.toml",
        .data =
        \\[model_providers.mock_provider]
        \\base_url = "http://127.0.0.1:7654/v1"
        \\env_key = "MOCK_PROVIDER_KEY"
        \\requires_openai_auth = false
        \\
        ,
    });
    const codex_home_z = try dir.dir.realPathFileAlloc(io, ".", allocator);
    defer allocator.free(codex_home_z);

    var cfg = try testAppServerConfig(allocator, "gpt-5.5");
    defer cfg.deinit(allocator);
    try replaceConfigOwnedString(allocator, &cfg.codex_home, codex_home_z);

    var params = try std.json.parseFromSlice(
        std.json.Value,
        allocator,
        "{\"ephemeral\":true,\"config\":{\"model_provider\":\"mock_provider\",\"openai_base_url\":\"http://127.0.0.1:11434/v1\",\"chatgpt_base_url\":\"http://127.0.0.1:8080/backend-api/codex\"}}",
        .{},
    );
    defer params.deinit();
    const request_config = try threadRequestConfigFromParams(params.value.object);
    try applyThreadRequestConfigOverrides(allocator, &cfg, request_config, false);

    try std.testing.expectEqualStrings("mock_provider", cfg.model_provider_id.?);
    try std.testing.expectEqualStrings("http://127.0.0.1:11434/v1", cfg.openai_base_url);
    try std.testing.expectEqualStrings("http://127.0.0.1:8080/backend-api/codex", cfg.chatgpt_base_url);

    var thread = try createLoadedThreadFromStartParams(allocator, cfg, params.value.object);
    defer thread.deinit(allocator);
    try std.testing.expectEqualStrings("mock_provider", thread.model_provider);
    try std.testing.expect(thread.runtime_overrides.model_provider);
    try std.testing.expectEqualStrings("http://127.0.0.1:11434/v1", thread.openai_base_url.?);
    try std.testing.expectEqualStrings("http://127.0.0.1:8080/backend-api/codex", thread.chatgpt_base_url.?);

    var turn_cfg = try testAppServerConfig(allocator, "gpt-other");
    defer turn_cfg.deinit(allocator);
    var turn_params = try std.json.parseFromSlice(std.json.Value, allocator, "{}", .{});
    defer turn_params.deinit();
    try applyTurnStartRuntimeConfigOverrides(allocator, &turn_cfg, &thread, turn_params.value.object);
    try std.testing.expectEqualStrings("http://127.0.0.1:11434/v1", turn_cfg.openai_base_url);
    try std.testing.expectEqualStrings("http://127.0.0.1:8080/backend-api/codex", turn_cfg.chatgpt_base_url);

    var inherited_fork = try createLoadedThreadFromForkParams(allocator, turn_cfg, turn_params.value.object, &thread);
    defer inherited_fork.deinit(allocator);
    try std.testing.expectEqualStrings("http://127.0.0.1:11434/v1", inherited_fork.openai_base_url.?);
    try std.testing.expectEqualStrings("http://127.0.0.1:8080/backend-api/codex", inherited_fork.chatgpt_base_url.?);

    var persisted_params = try std.json.parseFromSlice(
        std.json.Value,
        allocator,
        "{\"config\":{\"model_provider\":\"mock_provider\",\"openai_base_url\":\"http://127.0.0.1:11434/v1\",\"chatgpt_base_url\":\"http://127.0.0.1:8080/backend-api/codex\"}}",
        .{},
    );
    defer persisted_params.deinit();
    var persisted_thread = try createLoadedThreadFromStartParams(allocator, cfg, persisted_params.value.object);
    defer persisted_thread.deinit(allocator);
    try session_store.saveTranscript(allocator, persisted_thread.path.?, &persisted_thread.transcript);

    var loaded_transcript = try session_store.loadTranscript(allocator, persisted_thread.path.?);
    defer loaded_transcript.deinit(allocator);
    try std.testing.expectEqualStrings("http://127.0.0.1:11434/v1", loaded_transcript.openai_base_url.?);
    try std.testing.expectEqualStrings("http://127.0.0.1:8080/backend-api/codex", loaded_transcript.chatgpt_base_url.?);

    var resumed_cfg = try testAppServerConfig(allocator, "gpt-resumed-custom-url");
    defer resumed_cfg.deinit(allocator);
    var resumed_thread = try createLoadedThreadFromResumeParams(
        allocator,
        resumed_cfg,
        turn_params.value.object,
        persisted_thread.path.?,
        &loaded_transcript,
    );
    defer resumed_thread.deinit(allocator);
    try std.testing.expectEqualStrings("http://127.0.0.1:11434/v1", resumed_thread.openai_base_url.?);
    try std.testing.expectEqualStrings("http://127.0.0.1:8080/backend-api/codex", resumed_thread.chatgpt_base_url.?);

    var resumed_turn_cfg = try testAppServerConfig(allocator, "gpt-resumed-turn");
    defer resumed_turn_cfg.deinit(allocator);
    try applyLoadedThreadRuntimeToConfig(allocator, &resumed_turn_cfg, &resumed_thread);
    try std.testing.expectEqualStrings("http://127.0.0.1:11434/v1", resumed_turn_cfg.openai_base_url);
    try std.testing.expectEqualStrings("http://127.0.0.1:8080/backend-api/codex", resumed_turn_cfg.chatgpt_base_url);

    var clear_params = try std.json.parseFromSlice(
        std.json.Value,
        allocator,
        "{\"ephemeral\":true,\"config\":{\"openai_base_url\":null,\"chatgpt_base_url\":null}}",
        .{},
    );
    defer clear_params.deinit();
    var clear_cfg = try testAppServerConfig(allocator, "gpt-reset");
    defer clear_cfg.deinit(allocator);
    const clear_request_config = try threadRequestConfigFromParams(clear_params.value.object);
    try applyThreadRequestConfigOverrides(allocator, &clear_cfg, clear_request_config, false);
    var cleared_fork = try createLoadedThreadFromForkParams(allocator, clear_cfg, clear_params.value.object, &thread);
    defer cleared_fork.deinit(allocator);
    try std.testing.expect(cleared_fork.openai_base_url == null);
    try std.testing.expect(cleared_fork.chatgpt_base_url == null);

    var source_params = try std.json.parseFromSlice(
        std.json.Value,
        allocator,
        "{\"ephemeral\":true}",
        .{},
    );
    defer source_params.deinit();
    var source_cfg = try testAppServerConfig(allocator, "gpt-source");
    defer source_cfg.deinit(allocator);
    var source_thread = try createLoadedThreadFromStartParams(allocator, source_cfg, source_params.value.object);
    defer source_thread.deinit(allocator);
    try std.testing.expectEqualStrings("openai", source_thread.model_provider);

    var clear_provider_params = try std.json.parseFromSlice(
