test "config write scalar requirements reject disallowed top-level and profile values" {
    const allocator = std.testing.allocator;
    var requirements = ConfigRequirementsReadRequirements{
        .allowed_approval_policies = try stringListFromLabels(allocator, &.{"on-request"}),
        .allowed_approvals_reviewers = try stringListFromLabels(allocator, &.{"guardian_subagent"}),
        .allowed_sandbox_modes = try stringListFromLabels(allocator, &.{"read-only"}),
        .allowed_web_search_modes = try stringListFromLabels(allocator, &.{ "cached", "disabled" }),
    };
    defer requirements.deinit(allocator);

    const approval_conflict = try configWriteScalarRequirementConflictMessage(allocator,
        \\approval_policy = "never"
        \\
    , requirements);
    try std.testing.expect(approval_conflict != null);
    defer allocator.free(approval_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, approval_conflict.?, "approval_policy=\"never\"") != null);

    const profile_conflict = try configWriteScalarRequirementConflictMessage(allocator,
        \\[profiles.enterprise]
        \\sandbox_mode = "danger-full-access"
        \\
    , requirements);
    try std.testing.expect(profile_conflict != null);
    defer allocator.free(profile_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, profile_conflict.?, "profiles.enterprise.sandbox_mode=\"danger-full-access\"") != null);

    const inline_profile_conflict = try configWriteScalarRequirementConflictMessage(allocator,
        \\profiles = { enterprise = { web_search = "live" } }
        \\
    , requirements);
    try std.testing.expect(inline_profile_conflict != null);
    defer allocator.free(inline_profile_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, inline_profile_conflict.?, "profiles.enterprise.web_search=\"live\"") != null);

    const dotted_profile_conflict = try configWriteScalarRequirementConflictMessage(allocator,
        \\profiles.enterprise.approvals_reviewer = "user"
        \\
    , requirements);
    try std.testing.expect(dotted_profile_conflict != null);
    defer allocator.free(dotted_profile_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, dotted_profile_conflict.?, "profiles.enterprise.approvals_reviewer=\"user\"") != null);

    const quoted_equals_profile_conflict = try configWriteScalarRequirementConflictMessage(allocator,
        \\profiles."prod=eu".sandbox_mode = "danger-full-access"
        \\
    , requirements);
    try std.testing.expect(quoted_equals_profile_conflict != null);
    defer allocator.free(quoted_equals_profile_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, quoted_equals_profile_conflict.?, "profiles.prod=eu.sandbox_mode=\"danger-full-access\"") != null);

    const unrelated_nested_profile_inline = try configWriteScalarRequirementConflictMessage(allocator,
        \\profiles = { enterprise = { tools = { default = { note = "}" } } } }
        \\
    , requirements);
    try std.testing.expect(unrelated_nested_profile_inline == null);

    const array_table_local_scalar = try configWriteScalarRequirementConflictMessage(allocator,
        \\[[skills.config]]
        \\name = "local"
        \\approval_policy = "never"
        \\
    , requirements);
    try std.testing.expect(array_table_local_scalar == null);

    try std.testing.expectError(
        error.InvalidConfigWriteScalarType,
        configWriteScalarRequirementConflictMessage(allocator,
            \\approval_policy = true
            \\
        , requirements),
    );

    const allowed = try configWriteScalarRequirementConflictMessage(allocator,
        \\approval_policy = "on-request"
        \\approvals_reviewer = "auto_review"
        \\sandbox_mode = "read-only"
        \\web_search = "cached"
        \\
        \\[profiles.enterprise]
        \\approvals_reviewer = "guardian_subagent"
        \\web_search = "disabled"
        \\
    , requirements);
    try std.testing.expect(allowed == null);

    var empty_sandbox_requirement = ConfigRequirementsReadRequirements{
        .allowed_sandbox_modes = try stringListFromLabels(allocator, &.{}),
    };
    defer empty_sandbox_requirement.deinit(allocator);
    const empty_conflict = try configWriteScalarRequirementConflictMessage(allocator,
        \\sandbox_mode = "read-only"
        \\
    , empty_sandbox_requirement);
    try std.testing.expect(empty_conflict != null);
    defer allocator.free(empty_conflict.?);
    try std.testing.expect(std.mem.indexOf(u8, empty_conflict.?, "sandbox_mode=\"read-only\"") != null);
}

test "config/read profiles parse inline tables and sandbox mode" {
    const allocator = std.testing.allocator;
    var profiles = try loadConfigReadProfiles(allocator,
        \\profiles = { inline = { model = "gpt-inline", sandbox_mode = "read-only", tools = { view_image = true }, analytics = { enabled = false } } }
        \\
        \\[profiles]
        \\section_inline = { model_provider = "provider", sandbox_mode = "workspace-write" }
        \\dotted.model = "gpt-dotted"
        \\dotted.analytics.enabled = true
        \\dotted.tools.view_image = true
        \\dotted.tools.web_search.context_size = "low"
        \\dotted.tools.web_search.location.city = "New York"
        \\
        \\[profiles.table_form]
        \\model = "gpt-table"
        \\tools = { view_image = true, web_search = { context_size = "medium", allowed_domains = ["example.com"] } }
        \\analytics = { enabled = true }
        \\
    );
    defer profiles.deinit(allocator);

    try std.testing.expectEqual(@as(usize, 4), profiles.items.len);
    const inline_index = findConfigReadProfileIndex(profiles.items, "inline").?;
    const inline_profile = profiles.items[inline_index];
    try std.testing.expectEqualStrings("gpt-inline", inline_profile.model.?);
    try std.testing.expectEqual(config.SandboxMode.read_only, inline_profile.sandbox_mode.?);
    try std.testing.expectEqual(true, inline_profile.tools.view_image.?);
    try std.testing.expectEqual(false, inline_profile.analytics.enabled.?);

    const section_index = findConfigReadProfileIndex(profiles.items, "section_inline").?;
    const section_inline = profiles.items[section_index];
    try std.testing.expectEqualStrings("provider", section_inline.model_provider.?);
    try std.testing.expectEqual(config.SandboxMode.workspace_write, section_inline.sandbox_mode.?);

    const dotted_index = findConfigReadProfileIndex(profiles.items, "dotted").?;
    const dotted = profiles.items[dotted_index];
    try std.testing.expectEqualStrings("gpt-dotted", dotted.model.?);
    try std.testing.expectEqual(true, dotted.analytics.enabled.?);
    try std.testing.expectEqual(true, dotted.tools.view_image.?);
    try std.testing.expectEqualStrings("low", dotted.tools.web_search.?.context_size.?);
    try std.testing.expectEqualStrings("New York", dotted.tools.web_search.?.location.?.city.?);

    const table_form_index = findConfigReadProfileIndex(profiles.items, "table_form").?;
    const table_form = profiles.items[table_form_index];
    try std.testing.expectEqualStrings("gpt-table", table_form.model.?);
    try std.testing.expectEqual(true, table_form.tools.view_image.?);
    try std.testing.expectEqualStrings("medium", table_form.tools.web_search.?.context_size.?);
    try std.testing.expectEqualStrings("example.com", table_form.tools.web_search.?.allowed_domains.?.items[0]);
    try std.testing.expectEqual(true, table_form.analytics.enabled.?);
}

