test "app-server collaboration mode list returns built-in presets" {
    const allocator = std.testing.allocator;
    var state = AppServerState{};
    state.experimental_api_enabled = true;
    defer state.deinit(allocator);

    const response = try handleJsonRpcLine(
        allocator,
        &state,
        "{\"jsonrpc\":\"2.0\",\"id\":\"collaboration-modes\",\"method\":\"collaborationMode/list\",\"params\":{}}",
    );
    defer allocator.free(response.?);

    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, response.?, .{});
    defer parsed.deinit();

    const data = parsed.value.object.get("result").?.object.get("data").?.array.items;
    try std.testing.expectEqual(@as(usize, 2), data.len);

    const plan = data[0].object;
    try std.testing.expectEqualStrings("Plan", plan.get("name").?.string);
    try std.testing.expectEqualStrings("plan", plan.get("mode").?.string);
    try std.testing.expect(plan.get("model").? == .null);
    try std.testing.expectEqualStrings("medium", plan.get("reasoning_effort").?.string);

    const default = data[1].object;
    try std.testing.expectEqualStrings("Default", default.get("name").?.string);
    try std.testing.expectEqualStrings("default", default.get("mode").?.string);
    try std.testing.expect(default.get("model").? == .null);
    try std.testing.expect(default.get("reasoning_effort").? == .null);

    const invalid = try handleJsonRpcLine(
        allocator,
        &state,
        "{\"jsonrpc\":\"2.0\",\"id\":\"bad-collaboration-modes\",\"method\":\"collaborationMode/list\",\"params\":[]}",
    );
    defer allocator.free(invalid.?);
    try std.testing.expect(std.mem.indexOf(u8, invalid.?, "\"code\":-32602") != null);
}

test "app-server filters experimental server notifications by capability" {
    const allocator = std.testing.allocator;

    var stable_state = AppServerState{};
    defer stable_state.deinit(allocator);
    try queueThreadGoalClearedNotification(allocator, &stable_state, "thread-1");
    try queueProcessOutputDelta(allocator, &stable_state, "process-1", "stdout", "hello", "hello".len, null);
    try queueProcessExitedNotification(allocator, &stable_state, "process-1", 0, "", "", false, false);
    try std.testing.expectEqual(@as(usize, 0), stable_state.pending_notifications.items.len);

    var experimental_state = AppServerState{ .experimental_api_enabled = true };
    defer experimental_state.deinit(allocator);
    try queueThreadGoalClearedNotification(allocator, &experimental_state, "thread-1");
    try queueProcessOutputDelta(allocator, &experimental_state, "process-1", "stdout", "hello", "hello".len, null);
    try queueProcessExitedNotification(allocator, &experimental_state, "process-1", 0, "", "", false, false);
    try std.testing.expectEqual(@as(usize, 3), experimental_state.pending_notifications.items.len);
    try std.testing.expect(std.mem.indexOf(u8, experimental_state.pending_notifications.items[0], "\"method\":\"thread/goal/cleared\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, experimental_state.pending_notifications.items[1], "\"method\":\"process/outputDelta\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, experimental_state.pending_notifications.items[2], "\"method\":\"process/exited\"") != null);
}

test "app-server filters experimental server request fields by capability" {
    const allocator = std.testing.allocator;
    const request =
        "{\"jsonrpc\":\"2.0\",\"id\":\"approval-1\",\"method\":\"item/commandExecution/requestApproval\",\"params\":{\"threadId\":\"thread-1\",\"turnId\":\"turn-1\",\"itemId\":\"item-1\",\"command\":\"echo hi\",\"cwd\":\"/tmp\",\"additionalPermissions\":{\"network\":{\"enabled\":true}}}}";

    const stable = try renderServerRequestForConnection(allocator, false, request);
    defer allocator.free(stable);
    try std.testing.expect(std.mem.indexOf(u8, stable, "\"method\":\"item/commandExecution/requestApproval\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, stable, "\"command\":\"echo hi\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, stable, "additionalPermissions") == null);

    const experimental = try renderServerRequestForConnection(allocator, true, request);
    defer allocator.free(experimental);
    try std.testing.expect(std.mem.indexOf(u8, experimental, "additionalPermissions") != null);

    const other_request =
        "{\"jsonrpc\":\"2.0\",\"id\":\"tool-1\",\"method\":\"item/tool/requestUserInput\",\"params\":{\"additionalPermissions\":{\"network\":{\"enabled\":true}},\"question\":{\"label\":\"Continue?\"}}}";
    const other_stable = try renderServerRequestForConnection(allocator, false, other_request);
    defer allocator.free(other_stable);
    try std.testing.expect(std.mem.indexOf(u8, other_stable, "additionalPermissions") != null);
}

test "app-server resolves pending server requests from client responses" {
    const allocator = std.testing.allocator;
    var state = AppServerState{};
    defer state.deinit(allocator);

    try trackPendingServerRequest(
        allocator,
        &state,
        "{\"jsonrpc\":\"2.0\",\"id\":\"approval-1\",\"method\":\"item/commandExecution/requestApproval\",\"params\":{\"threadId\":\"thread-1\",\"turnId\":\"turn-1\",\"itemId\":\"item-1\",\"command\":\"echo hi\",\"cwd\":\"/tmp\"}}",
    );
    try std.testing.expectEqual(@as(usize, 1), state.pending_server_requests.items.len);

    const unmatched = try handleJsonRpcLine(
        allocator,
        &state,
        "{\"jsonrpc\":\"2.0\",\"id\":\"approval-2\",\"result\":{\"decision\":\"accept\"}}",
    );
    try std.testing.expect(unmatched == null);
    try std.testing.expectEqual(@as(usize, 1), state.pending_server_requests.items.len);
    try std.testing.expectEqual(@as(usize, 0), state.pending_notifications.items.len);

    const resolved = try handleJsonRpcLine(
        allocator,
        &state,
        "{\"jsonrpc\":\"2.0\",\"id\":\"approval-1\",\"result\":{\"decision\":\"accept\"}}",
    );
    try std.testing.expect(resolved == null);
    try std.testing.expectEqual(@as(usize, 0), state.pending_server_requests.items.len);
    try std.testing.expectEqual(@as(usize, 1), state.pending_notifications.items.len);
    try std.testing.expect(std.mem.indexOf(u8, state.pending_notifications.items[0], "\"method\":\"serverRequest/resolved\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, state.pending_notifications.items[0], "\"threadId\":\"thread-1\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, state.pending_notifications.items[0], "\"requestId\":\"approval-1\"") != null);
}

test "app-server resolves pending server requests from client errors" {
    const allocator = std.testing.allocator;
    var state = AppServerState{};
    defer state.deinit(allocator);

    try trackPendingServerRequest(
        allocator,
        &state,
        "{\"jsonrpc\":\"2.0\",\"id\":42,\"method\":\"item/tool/requestUserInput\",\"params\":{\"threadId\":\"thread-2\",\"turnId\":\"turn-1\",\"itemId\":\"item-1\",\"question\":{\"label\":\"Continue?\"}}}",
    );

    const resolved = try handleJsonRpcLine(
        allocator,
        &state,
        "{\"jsonrpc\":\"2.0\",\"id\":42,\"error\":{\"code\":-32000,\"message\":\"declined\"}}",
    );
    try std.testing.expect(resolved == null);
    try std.testing.expectEqual(@as(usize, 0), state.pending_server_requests.items.len);
    try std.testing.expectEqual(@as(usize, 1), state.pending_notifications.items.len);
    try std.testing.expect(std.mem.indexOf(u8, state.pending_notifications.items[0], "\"threadId\":\"thread-2\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, state.pending_notifications.items[0], "\"requestId\":42") != null);
}

test "app-server transport labels preserve configured listen URL" {
    const allocator = std.testing.allocator;
    const unix_path = try formatTransportLabel(allocator, try parseTransport("unix:///tmp/codex.sock"));
    defer allocator.free(unix_path);
    try std.testing.expectEqualStrings("unix:///tmp/codex.sock", unix_path);

    const websocket = try formatTransportLabel(allocator, try parseTransport("ws://127.0.0.1:3456"));
    defer allocator.free(websocket);
    try std.testing.expectEqualStrings("ws://127.0.0.1:3456", websocket);
}
